    .{ .name = "upper", .type = .u64 },
};

const fs_p3_directory_entry_fields = [_]ctypes.Field{
    .{ .name = "type", .type = .{ .variant = 2 } },
    .{ .name = "name", .type = .string },
};

const fs_p3_local_types = [_]ctypes.TypeDef{
    .{ .option = .{ .inner = .string } }, // 0: option<string>
    .{ .variant = .{ .cases = &fs_p3_error_code_cases } }, // 1: error-code
    .{ .variant = .{ .cases = &fs_p3_descriptor_type_cases } }, // 2: descriptor-type
    .{ .flags = .{ .names = &fs_p3_descriptor_flags_names } }, // 3: descriptor-flags
    .{ .record = .{ .fields = &fs_p3_instant_fields } }, // 4: instant
    .{ .option = .{ .inner = .{ .type_idx = 4 } } }, // 5: option<instant>
    .{ .record = .{ .fields = &fs_p3_descriptor_stat_fields } }, // 6: descriptor-stat
    .{ .record = .{ .fields = &fs_p3_metadata_hash_fields } }, // 7: metadata-hash-value
    .{ .record = .{ .fields = &fs_p3_directory_entry_fields } }, // 8: directory-entry
    .{ .result = .{ .ok = null, .err = .{ .variant = 1 } } }, // 9: result<_, error-code>
    .{ .result = .{ .ok = .{ .own = 0 }, .err = .{ .variant = 1 } } }, // 10: result<descriptor (own), error-code>
    .{ .result = .{ .ok = .{ .variant = 2 }, .err = .{ .variant = 1 } } }, // 11: result<descriptor-type, ...>
    .{ .result = .{ .ok = .{ .flags = 3 }, .err = .{ .variant = 1 } } }, // 12: result<descriptor-flags, ...>
    .{ .result = .{ .ok = .string, .err = .{ .variant = 1 } } }, // 13: result<string, ...>
    .{ .result = .{ .ok = .{ .record = 6 }, .err = .{ .variant = 1 } } }, // 14: result<descriptor-stat, ...>
    .{ .result = .{ .ok = .{ .record = 7 }, .err = .{ .variant = 1 } } }, // 15: result<metadata-hash-value, ...>
};

const FS_P3_ERROR_CODE_IDX: u32 = 1;
const FS_P3_DESCRIPTOR_TYPE_IDX: u32 = 2;
const FS_P3_DESCRIPTOR_FLAGS_IDX: u32 = 3;
const FS_P3_DESCRIPTOR_STAT_IDX: u32 = 6;
const FS_P3_METADATA_HASH_IDX: u32 = 7;
const FS_P3_DIRECTORY_ENTRY_IDX: u32 = 8;
const FS_P3_RESULT_UNIT_ERR_IDX: u32 = 9;
const FS_P3_RESULT_DESC_ERR_IDX: u32 = 10;
const FS_P3_RESULT_DESC_TYPE_ERR_IDX: u32 = 11;
const FS_P3_RESULT_DESC_FLAGS_ERR_IDX: u32 = 12;
const FS_P3_RESULT_STRING_ERR_IDX: u32 = 13;
const FS_P3_RESULT_DESC_STAT_ERR_IDX: u32 = 14;
const FS_P3_RESULT_METADATA_HASH_ERR_IDX: u32 = 15;

fn fsP3TypeRegistry() abi.TypeRegistry {
    return abi.TypeRegistry.fromTypes(&fs_p3_local_types);
}

/// Shape of an `async func` return on the 0.3 `wasi:filesystem/types`
/// surface. Each shape maps to a `ValType` resolvable in
/// `fs_p3_local_types`; `fsP3LowerAsyncPayload` consumes a fully-lifted
/// 0.2-shape `InterfaceValue` and writes its canonical lowering into a
/// heap-owned `[]u8` ready to install on `Future.payload`.
const FsP3AsyncReturn = enum {
    /// `result<_, error-code>`
    unit_err,
    /// `result<descriptor, error-code>` — `descriptor` is a u32 own-handle.
    desc_err,
    /// `result<descriptor-type, error-code>`
    desc_type_err,
    /// `result<descriptor-flags, error-code>`
    desc_flags_err,
    /// `result<string, error-code>`
    string_err,
    /// `result<descriptor-stat, error-code>` — the 0.2 sync body emits
    /// the `option<datetime>` timestamps with `.u64` seconds; this
    /// kind triggers a fixup to `.s64` (matching 0.3's `instant`).
    desc_stat_err,
    /// `result<metadata-hash-value, error-code>`
    metadata_hash_err,
    /// Bare `bool` — used by `is-same-object`.
    just_bool,

    pub fn valType(self: FsP3AsyncReturn) ctypes.ValType {
        return switch (self) {
            .unit_err => .{ .result = FS_P3_RESULT_UNIT_ERR_IDX },
            .desc_err => .{ .result = FS_P3_RESULT_DESC_ERR_IDX },
            .desc_type_err => .{ .result = FS_P3_RESULT_DESC_TYPE_ERR_IDX },
            .desc_flags_err => .{ .result = FS_P3_RESULT_DESC_FLAGS_ERR_IDX },
            .string_err => .{ .result = FS_P3_RESULT_STRING_ERR_IDX },
            .desc_stat_err => .{ .result = FS_P3_RESULT_DESC_STAT_ERR_IDX },
            .metadata_hash_err => .{ .result = FS_P3_RESULT_METADATA_HASH_ERR_IDX },
            .just_bool => .bool,
        };
    }
};

/// Fix-up the `option<datetime { u64 seconds, u32 nanoseconds }>` tag the
/// 0.2 sync body produced into `option<instant { s64 seconds, u32 nanoseconds }>`
/// for 0.3 canonical lowering. Operates in-place on the `result_val.ok`
/// payload of a `descriptor-stat` record. The seconds bits are
/// `@bitCast`-preserved so positive Unix timestamps survive the tag
/// transition unchanged.
fn fsP3FixupStatRecord(val: InterfaceValue) void {
    if (val != .result_val) return;
    if (!val.result_val.is_ok) return;
    const ok_ptr = val.result_val.payload orelse return;
    if (ok_ptr.* != .record_val) return;
    const rec = ok_ptr.record_val;
    if (rec.len < 6) return;
    inline for ([_]usize{ 3, 4, 5 }) |i| {
        fsP3FixupOptionalInstant(@constCast(&rec[i]));
    }
}

fn fsP3FixupOptionalInstant(val_ptr: *InterfaceValue) void {
    if (val_ptr.* != .option_val) return;
    if (!val_ptr.option_val.is_some) return;
    const some_ptr = val_ptr.option_val.payload orelse return;
    if (some_ptr.* != .record_val) return;
    const rec = some_ptr.record_val;
    if (rec.len < 1) return;
    // The 0.2 body writes `.u64` for the seconds field; reinterpret the
    // bit pattern as the signed `.s64` 0.3 spec expects.
    switch (rec[0]) {
        .u64 => |bits| @constCast(&rec[0]).* = .{ .s64 = @bitCast(bits) },
        else => {},
    }
}

/// Map a discriminant produced by the host's 0.2-shape `FsErrorCode`
/// enum into the 0.3 `variant error-code` discriminant position. The
/// 0.3 spec dropped the `would-block` case (which sat at position 1 in
/// 0.2), shifting every subsequent case down by one. Sockets has the
/// same shape via `socketCodeToP3Disc`. (#564.)
///
/// Internal `would_block` (`= 1`) maps to 0.3 `busy` (`= 3`) — the
/// closest semantic equivalent for a "transient retry" error on a
/// filesystem operation.
fn fsCodeToP3Disc(p2_disc: u32) u32 {
    if (p2_disc == 0) return 0; // access stays
    if (p2_disc == 1) return 3; // would_block → busy (closest 0.3 equivalent)
    return p2_disc - 1; // already (2)..cross_device (36) shift down by one
}

/// Walk the `result<_, error-code>` shape and transcode the err-arm
/// discriminant from the host's 0.2 enum to the 0.3 variant via
/// `fsCodeToP3Disc`. The ok arm and non-variant err payloads (none
/// produced by the current host fns) are left untouched. (#564.)
fn fsP3FixupErrCode(val: InterfaceValue) void {
    if (val != .result_val) return;
    if (val.result_val.is_ok) return;
    const err_ptr = val.result_val.payload orelse return;
    if (err_ptr.* != .variant_val) return;
    const p2 = err_ptr.variant_val.discriminant;
    @constCast(err_ptr).variant_val.discriminant = fsCodeToP3Disc(p2);
}

/// Map a discriminant produced by the host's 0.2-shape `DescType`
/// enum into the 0.3 `variant descriptor-type` discriminant. The 0.2
/// enum had `unknown=0` at the head; the 0.3 spec drops it and
/// introduces an `other(option<string>)` case at the tail. Each
/// 0.2 case 1..7 shifts down by one; `unknown` maps to `other` (with
/// no payload — see `fsP3FixupDescType`). (#564.)
fn descTypeToP3Disc(p2_disc: u32) u32 {
    if (p2_disc == 0) return 7; // unknown → other(none)
    return p2_disc - 1; // block_device..socket shift down by one
}

/// Walk a `result<descriptor-type, error-code>` shape and transcode
/// the ok-arm `descriptor-type` variant discriminant from the host's
/// 0.2 enum to the 0.3 variant. Also descends into a
/// `descriptor-stat` record (field 0 is the descriptor-type) for the
/// `.desc_stat_err` shape. (#564.)
fn fsP3FixupDescType(val: InterfaceValue) void {
    if (val != .result_val) return;
    if (!val.result_val.is_ok) return;
    const ok_ptr = val.result_val.payload orelse return;
    if (ok_ptr.* != .variant_val) return;
    const p2 = ok_ptr.variant_val.discriminant;
    @constCast(ok_ptr).variant_val.discriminant = descTypeToP3Disc(p2);
}

fn fsP3FixupDescStatType(val: InterfaceValue) void {
    if (val != .result_val) return;
    if (!val.result_val.is_ok) return;
    const ok_ptr = val.result_val.payload orelse return;
    if (ok_ptr.* != .record_val) return;
    const rec = ok_ptr.record_val;
    if (rec.len < 1) return;
    if (rec[0] != .variant_val) return;
    const p2 = rec[0].variant_val.discriminant;
    @constCast(&rec[0]).variant_val.discriminant = descTypeToP3Disc(p2);
}

/// Lower a fully-lifted `InterfaceValue` into a heap-owned byte buffer
/// using the canonical ABI layout for `kind`'s `ValType`. The returned
/// slice is owned by `allocator` and is suitable for installation on
/// `async_mod.Future.payload`; the executor's `future_read` arm will
/// memcpy it into the guest's destination pointer at rendezvous time.
///
/// For `result<_, error-code>` (`.unit_err`), the 0.2 sync bodies
/// conventionally fabricate an empty-tuple `ok` payload — that payload
/// is irrelevant on the 0.3 wire (the ok arm is unit) and is stripped
/// before lowering so `storeValReg` doesn't try to lower a non-existent
/// ok type.
fn fsP3LowerAsyncPayload(
    allocator: Allocator,
    kind: FsP3AsyncReturn,
    val: InterfaceValue,
) ![]u8 {
    const reg = fsP3TypeRegistry();
    const vt = kind.valType();
    const size = abi.sizeOfType(reg, vt);
    if (size == 0) return error.LowerError;
    const buf = try allocator.alloc(u8, size);
    errdefer allocator.free(buf);
    @memset(buf, 0);

    // Strip a stray ok-payload from `result<_, error-code>` (the 0.2
    // sync body emits `.tuple_val = &.{}` which is non-null but the
    // 0.3 result type's ok arm is null — `storeValReg` would otherwise
    // unwrap `td.result.ok.?`).
    var effective = val;
    if (kind == .unit_err and val == .result_val and val.result_val.is_ok) {
        effective = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    // The 0.2 sync bodies write the err-arm discriminant via
    // `@intFromEnum(FsErrorCode)`, but the 0.3 `variant error-code`
    // dropped `would-block`. Transcode in-place for every
    // `result<_, error-code>`-shaped return so the wire-level disc
    // matches the guest's 0.3 enum positions. The 0.2 `DescType`
    // similarly has a leading `unknown=0` case absent from 0.3's
    // `descriptor-type` variant — transcode the ok-arm disc for
    // `.desc_type_err` and the `descriptor-stat.type` field for
    // `.desc_stat_err`. Tier-D / `.just_bool` doesn't carry an error
    // variant; safe to skip. (#564.)
    switch (kind) {
        .unit_err, .desc_err, .desc_type_err, .desc_flags_err, .string_err, .desc_stat_err, .metadata_hash_err => fsP3FixupErrCode(effective),
        .just_bool => {},
    }
    switch (kind) {
        .desc_type_err => fsP3FixupDescType(effective),
        .desc_stat_err => fsP3FixupDescStatType(effective),
        else => {},
    }

    try abi.storeValReg(buf, 0, vt, effective, reg);
    return buf;
}

/// Lower a host slice-of-byte-slices into a canonical
/// `list<list<u8>>` PtrLen in guest memory. Each inner slice is
/// `hostAllocAndWrite`'d; the outer buffer holds `n × (u32 ptr, u32 len)`
/// pairs. Returns `{ .ptr = 0, .len = 0 }` for empty input without
/// touching guest memory.
fn lowerByteListList(ci: *ComponentInstance, lists: []const []const u8) !InterfaceValue.PtrLen {
    if (lists.len == 0) return .{ .ptr = 0, .len = 0 };
    const total: u32 = @intCast(lists.len * 8);
    const outer = ci.hostAllocGuest(total, 4) orelse return error.OutOfMemory;
    const dst = ci.writableGuestBytes(outer, total) orelse return error.OutOfMemory;
    var off: u32 = 0;
    for (lists) |bytes| {
        // Empty inner lists must still carry a non-zero pointer:
        // wit-bindgen 0.45 lifts each inner via `Vec::from_raw_parts`
        // which asserts the pointer is non-null even when length is
        // zero. Allocate a single byte so the lift survives (#538).
        const inner_ptr: u32 = if (bytes.len == 0)
            (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
        else
            (ci.hostAllocAndWrite(bytes, 1) orelse return error.OutOfMemory);
        std.mem.writeInt(u32, dst[off..][0..4], inner_ptr, .little);
        std.mem.writeInt(u32, dst[off + 4 ..][0..4], @intCast(bytes.len), .little);
        off += 8;
    }
    return .{ .ptr = outer, .len = @intCast(lists.len) };
}

/// Lower a slice of (name, value) byte pairs into canonical
/// `list<tuple<list<u8>, list<u8>>>` PtrLen in guest memory. Each
/// element is 16 bytes: `(name_ptr, name_len, value_ptr, value_len)`.
fn lowerFieldEntriesList(ci: *ComponentInstance, entries: []const HttpFieldEntry) !InterfaceValue.PtrLen {
    if (entries.len == 0) return .{ .ptr = 0, .len = 0 };
    const total: u32 = @intCast(entries.len * 16);
    const outer = ci.hostAllocGuest(total, 4) orelse return error.OutOfMemory;
    const dst = ci.writableGuestBytes(outer, total) orelse return error.OutOfMemory;
    var off: u32 = 0;
    for (entries) |e| {
        // See `lowerByteListList` (#538): wit-bindgen Vec lift
        // requires a non-null pointer even for empty lists.
        const name_ptr: u32 = if (e.name.len == 0)
            (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
        else
            (ci.hostAllocAndWrite(e.name, 1) orelse return error.OutOfMemory);
        const value_ptr: u32 = if (e.value.len == 0)
            (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
        else
            (ci.hostAllocAndWrite(e.value, 1) orelse return error.OutOfMemory);
        std.mem.writeInt(u32, dst[off..][0..4], name_ptr, .little);
        std.mem.writeInt(u32, dst[off + 4 ..][0..4], @intCast(e.name.len), .little);
        std.mem.writeInt(u32, dst[off + 8 ..][0..4], value_ptr, .little);
        std.mem.writeInt(u32, dst[off + 12 ..][0..4], @intCast(e.value.len), .little);
        off += 16;
    }
    return .{ .ptr = outer, .len = @intCast(entries.len) };
}

// ── wasi:sockets@0.3.0 async-payload type registry (#535) ──────────────────
//
// Async-func wrappers on the 0.3 sockets surface return `result<T, error-code>`
// shapes whose `T` arm carries either a list of `ip-address`es or a tuple of
// `(list<u8>, ip-socket-address)`. The executor's `future_read` rendezvous
// (#502) consumes `Future.payload` directly: the canonical-ABI-lowered byte
// stream for `result<T, error-code>` lives in `payload` so the read can
// `memcpy` it into the guest's destination pointer.
//
// Indices (consult `sockets_p3_local_types` below):
//    0: tuple<u8, u8, u8, u8>                                       — ipv4 octets
//    1: tuple<u16, u16, u16, u16, u16, u16, u16, u16>               — ipv6 groups
//    2: variant ip-address { ipv4(tuple<u8 x 4>), ipv6(tuple<u16 x 8>) }
//    3: list<ip-address>                                            — resolve-addresses ok arm
//    4: list<u8>                                                    — udp datagram bytes
//    5: record ipv4-socket-address { port: u16, address: tuple<u8 x 4> }
//    6: record ipv6-socket-address { port: u16, flow-info: u32,
//         address: tuple<u16 x 8>, scope-id: u32 }
//    7: variant ip-socket-address { ipv4, ipv6 }
//    8: tuple<list<u8>, ip-socket-address>                          — udp-receive ok arm
//    9: variant error-code (21 cases; all unit)
//   10: result<list<ip-address>, error-code>                         — resolve-addresses
//   11: result<tuple<list<u8>, ip-socket-address>, error-code>       — udp-receive
//   12: result<_, error-code>                                        — connect, udp-send, etc.

const sockets_p3_ipv4_octets_fields = [_]ctypes.ValType{ .u8, .u8, .u8, .u8 };
const sockets_p3_ipv6_groups_fields = [_]ctypes.ValType{ .u16, .u16, .u16, .u16, .u16, .u16, .u16, .u16 };
const sockets_p3_ip_address_cases = [_]ctypes.Case{
    .{ .name = "ipv4", .type = .{ .tuple = 0 } },
    .{ .name = "ipv6", .type = .{ .tuple = 1 } },
};
const sockets_p3_ipv4_sockaddr_fields = [_]ctypes.Field{
    .{ .name = "port", .type = .u16 },
    .{ .name = "address", .type = .{ .tuple = 0 } },
};
const sockets_p3_ipv6_sockaddr_fields = [_]ctypes.Field{
    .{ .name = "port", .type = .u16 },
    .{ .name = "flow-info", .type = .u32 },
    .{ .name = "address", .type = .{ .tuple = 1 } },
    .{ .name = "scope-id", .type = .u32 },
};
const sockets_p3_ip_sockaddr_cases = [_]ctypes.Case{
    .{ .name = "ipv4", .type = .{ .record = 5 } },
    .{ .name = "ipv6", .type = .{ .record = 6 } },
};
const sockets_p3_udp_receive_fields = [_]ctypes.ValType{
    .{ .list = 4 },
    .{ .variant = 7 },
};
// WIT 0.3 `wasi:sockets/types.error-code` is a 15-case variant ending in
// `other(option<string>)` (NOT the flat 21-case enum of 0.2). Case 14
// carries the option<string> payload so the canonical-ABI size envelope
// for the variant reserves space for ptr+len+option-disc — emitting case
// 14 with `payload=null` is `other(none)`; supplying a string is the
// diagnostic path used by `socketResultErrP3WithDiag`. The `other` arm
// references the `option<string>` typedef at index 13 below. (#563)
const sockets_p3_error_code_cases = [_]ctypes.Case{
    .{ .name = "access-denied", .type = null },
    .{ .name = "not-supported", .type = null },
    .{ .name = "invalid-argument", .type = null },
    .{ .name = "out-of-memory", .type = null },
    .{ .name = "timeout", .type = null },
    .{ .name = "invalid-state", .type = null },
    .{ .name = "address-not-bindable", .type = null },
    .{ .name = "address-in-use", .type = null },
    .{ .name = "remote-unreachable", .type = null },
    .{ .name = "connection-refused", .type = null },
    .{ .name = "connection-broken", .type = null },
    .{ .name = "connection-reset", .type = null },
    .{ .name = "connection-aborted", .type = null },
    .{ .name = "datagram-too-large", .type = null },
    // case 14: `other(option<string>)` — payload references the
    // option<string> typedef at index 13.
    .{ .name = "other", .type = .{ .option = 13 } },
};

const sockets_p3_local_types = [_]ctypes.TypeDef{
    .{ .tuple = .{ .fields = &sockets_p3_ipv4_octets_fields } }, // 0
    .{ .tuple = .{ .fields = &sockets_p3_ipv6_groups_fields } }, // 1
    .{ .variant = .{ .cases = &sockets_p3_ip_address_cases } }, // 2
    .{ .list = .{ .element = .{ .variant = 2 } } }, // 3
    .{ .list = .{ .element = .u8 } }, // 4
    .{ .record = .{ .fields = &sockets_p3_ipv4_sockaddr_fields } }, // 5
    .{ .record = .{ .fields = &sockets_p3_ipv6_sockaddr_fields } }, // 6
    .{ .variant = .{ .cases = &sockets_p3_ip_sockaddr_cases } }, // 7
    .{ .tuple = .{ .fields = &sockets_p3_udp_receive_fields } }, // 8
    .{ .variant = .{ .cases = &sockets_p3_error_code_cases } }, // 9
    .{ .result = .{ .ok = .{ .list = 3 }, .err = .{ .variant = 9 } } }, // 10
    .{ .result = .{ .ok = .{ .tuple = 8 }, .err = .{ .variant = 9 } } }, // 11
    .{ .result = .{ .ok = null, .err = .{ .variant = 9 } } }, // 12
    // option<string> — referenced by `other(option<string>)` arm of the
    // error-code variant. Must occupy the index named in
    // `sockets_p3_error_code_cases[14].type.option`. (#563)
    .{ .option = .{ .inner = .string } }, // 13
};

const SOCKETS_P3_IP_ADDRESS_VARIANT_IDX: u32 = 2;
const SOCKETS_P3_IP_ADDRESS_LIST_IDX: u32 = 3;
const SOCKETS_P3_IP_SOCKADDR_VARIANT_IDX: u32 = 7;
const SOCKETS_P3_UDP_RECEIVE_TUPLE_IDX: u32 = 8;
const SOCKETS_P3_RESULT_RESOLVE_IDX: u32 = 10;
const SOCKETS_P3_RESULT_UDP_RECV_IDX: u32 = 11;
const SOCKETS_P3_RESULT_UNIT_ERR_IDX: u32 = 12;
const SOCKETS_P3_OPTION_STRING_IDX: u32 = 13;
/// Discriminant of the `other(option<string>)` arm in the 0.3
/// error-code variant. Co-located with the case array so the helper
/// fall-through path can route unmapped errors here without an
/// off-by-one risk. (#563)
const SOCKETS_P3_ERROR_OTHER_DISC: u32 = 14;

fn socketsP3TypeRegistry() abi.TypeRegistry {
    return abi.TypeRegistry.fromTypes(&sockets_p3_local_types);
}

/// 0.3 async-func return shapes that `socketsLowerAsyncPayload` knows
/// how to lower. Mirrors `FsP3AsyncReturn`.
const SocketsP3AsyncReturn = enum {
    /// `result<_, error-code>` — connect, udp-send, etc.
    unit_err,
    /// `result<list<ip-address>, error-code>` — resolve-addresses ok arm.
    resolve_list_err,
    /// `result<tuple<list<u8>, ip-socket-address>, error-code>` — udp-receive ok arm.
    udp_receive_err,

    pub fn valType(self: SocketsP3AsyncReturn) ctypes.ValType {
        return switch (self) {
            .unit_err => .{ .result = SOCKETS_P3_RESULT_UNIT_ERR_IDX },
            .resolve_list_err => .{ .result = SOCKETS_P3_RESULT_RESOLVE_IDX },
            .udp_receive_err => .{ .result = SOCKETS_P3_RESULT_UDP_RECV_IDX },
        };
    }
};

/// Lower a fully-lifted `InterfaceValue` for the requested 0.3 sockets
/// async-func return shape into a canonical-ABI byte buffer suitable
/// for installation on `async_mod.Future.payload`. Owned by `allocator`;
/// the future-read rendezvous on the executor frees it after the guest
/// reads. Mirrors `fsP3LowerAsyncPayload` (#522 / PR #528).
fn socketsP3LowerAsyncPayload(
    allocator: Allocator,
    kind: SocketsP3AsyncReturn,
    val: InterfaceValue,
) ![]u8 {
    const reg = socketsP3TypeRegistry();
    const vt = kind.valType();
    const size = abi.sizeOfType(reg, vt);
    if (size == 0) return error.LowerError;
    const buf = try allocator.alloc(u8, size);
    errdefer allocator.free(buf);
    @memset(buf, 0);

    // Strip a stray ok-payload from `result<_, error-code>` (the same
    // 0.2-shape compatibility cleanup as `fsP3LowerAsyncPayload`).
    var effective = val;
    if (kind == .unit_err and val == .result_val and val.result_val.is_ok) {
        effective = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }
    try abi.storeValReg(buf, 0, vt, effective, reg);
    return buf;
}

// ── wasi:http@0.3.0 async-payload type registry (#589) ─────────────────────
//
// The P3 `wasi:http/client.send` and `wasi:http/handler.handle` host-imports
// settle their `result<own<response>, error-code>` return asynchronously via
// `canon.lower (async)` (#551 / #564). The executor's async-lower trampoline
// (`executor.zig` ~ line 5183) copies `Future.payload` bytes into the
// guest's `retptr`; the host must therefore pre-encode the canonical-ABI
// byte layout of `result<own<response>, error-code>` ahead of the settle.
//
// Naively assuming "result discriminant + 4-byte handle" underwrites the
// destination by 36 bytes (envelope is 40 bytes — see below) and a guest
// reading the response handle observes whatever uninitialised bytes land
// at the wrong offset. Routing through this type registry produces the
// same bytes wit-bindgen ≥ 0.45 would lower on the export side.
//
// Indices (consult `http_p3_local_types` below):
//    0: option<string>                                — internal-error etc.
//    1: option<u8>                                    — TLS-alert-id
//    2: option<u16>                                   — DNS info-code
//    3: option<u32>                                   — header/trailer-section-size
//    4: option<u64>                                   — body-size
//    5: record DNS-error-payload
//    6: record TLS-alert-received-payload
//    7: record field-size-payload
//    8: option<field-size-payload>                    — request/header-size arms
//    9: variant error-code                            (39 cases; matches 0.3 WIT)
//   10: result<own<response>, error-code>             — client.send / handler.handle ok arm
//   11: result<_, error-code>                         — unit-ok arms (future-trailers, transmission)
//
// The 39-case `error-code` variant is shape-equivalent to the 0.2 enum but
// with payloads on certain arms (DNS-error, TLS-alert-received, the various
// body / header / trailer-size arms, internal-error). The variant payload
// alignment is bumped to **8** by `option<u64>`; combined with the maximum
// payload size of 24 (`option<field-size-payload>`) the variant envelope is
// `alignUp(alignUp(1, 8) + 24, 8) = 32` bytes. Wrapping that in
// `result<own<response>, error-code>` yields a 40-byte envelope
// (`alignUp(alignUp(1, 8) + max(4, 32), 8) = 40`).
//
// The `mapHttpFetchError` table (#586) covers 17 distinct unit-payload
// codes; the payload-bearing arms (DNS-error etc.) are still emitted with
// `payload=null` and rely on the @memset(buf, 0) of the lower buffer to
// produce a semantically-valid "no diagnostic info" payload (zeroed
// `option<*>` == `none`). Declaring the payload arm types in this
// registry is what keeps the envelope size matching wit-bindgen.

const http_p3_dns_error_payload_fields = [_]ctypes.Field{
    .{ .name = "rcode", .type = .{ .option = 0 } },
    .{ .name = "info-code", .type = .{ .option = 2 } },
};

const http_p3_tls_alert_payload_fields = [_]ctypes.Field{
    .{ .name = "alert-id", .type = .{ .option = 1 } },
    .{ .name = "alert-message", .type = .{ .option = 0 } },
};

const http_p3_field_size_payload_fields = [_]ctypes.Field{
    .{ .name = "field-name", .type = .{ .option = 0 } },
    .{ .name = "field-size", .type = .{ .option = 3 } },
};

/// `wasi:http/types.error-code` (39 cases). WIT-declaration order so the
/// numeric discriminant matches `HttpErrorCode` (the 0.3 ordering, which
/// happens to coincide with 0.2's). Several arms carry payloads in the
/// 0.3 WIT — declared here so the variant envelope size matches what
/// wit-bindgen produces; the host only ever emits unit-payload codes and
/// relies on `@memset(buf, 0)` to leave the payload arm zeroed
/// (option<*> = none, record { option<*> = none } etc.).
const http_p3_error_code_cases = [_]ctypes.Case{
    .{ .name = "DNS-timeout", .type = null }, // 0
    .{ .name = "DNS-error", .type = .{ .record = 5 } }, // 1
    .{ .name = "destination-not-found", .type = null }, // 2
    .{ .name = "destination-unavailable", .type = null }, // 3
    .{ .name = "destination-IP-prohibited", .type = null }, // 4
    .{ .name = "destination-IP-unroutable", .type = null }, // 5
    .{ .name = "connection-refused", .type = null }, // 6
    .{ .name = "connection-terminated", .type = null }, // 7
    .{ .name = "connection-timeout", .type = null }, // 8
    .{ .name = "connection-read-timeout", .type = null }, // 9
    .{ .name = "connection-write-timeout", .type = null }, // 10
    .{ .name = "connection-limit-reached", .type = null }, // 11
    .{ .name = "TLS-protocol-error", .type = null }, // 12
    .{ .name = "TLS-certificate-error", .type = null }, // 13
    .{ .name = "TLS-alert-received", .type = .{ .record = 6 } }, // 14
    .{ .name = "HTTP-request-denied", .type = null }, // 15
    .{ .name = "HTTP-request-length-required", .type = null }, // 16
    .{ .name = "HTTP-request-body-size", .type = .{ .option = 4 } }, // 17
    .{ .name = "HTTP-request-method-invalid", .type = null }, // 18
    .{ .name = "HTTP-request-URI-invalid", .type = null }, // 19
    .{ .name = "HTTP-request-URI-too-long", .type = null }, // 20
    .{ .name = "HTTP-request-header-section-size", .type = .{ .option = 3 } }, // 21
    .{ .name = "HTTP-request-header-size", .type = .{ .option = 8 } }, // 22
    .{ .name = "HTTP-request-trailer-section-size", .type = .{ .option = 3 } }, // 23
    .{ .name = "HTTP-request-trailer-size", .type = .{ .record = 7 } }, // 24
    .{ .name = "HTTP-response-incomplete", .type = null }, // 25
    .{ .name = "HTTP-response-header-section-size", .type = .{ .option = 3 } }, // 26
    .{ .name = "HTTP-response-header-size", .type = .{ .record = 7 } }, // 27
    .{ .name = "HTTP-response-body-size", .type = .{ .option = 4 } }, // 28
    .{ .name = "HTTP-response-trailer-section-size", .type = .{ .option = 3 } }, // 29
    .{ .name = "HTTP-response-trailer-size", .type = .{ .record = 7 } }, // 30
    .{ .name = "HTTP-response-transfer-coding", .type = .{ .option = 0 } }, // 31
    .{ .name = "HTTP-response-content-coding", .type = .{ .option = 0 } }, // 32
    .{ .name = "HTTP-response-timeout", .type = null }, // 33
    .{ .name = "HTTP-upgrade-failed", .type = null }, // 34
    .{ .name = "HTTP-protocol-error", .type = null }, // 35
    .{ .name = "loop-detected", .type = null }, // 36
    .{ .name = "configuration-error", .type = null }, // 37
    .{ .name = "internal-error", .type = .{ .option = 0 } }, // 38
};

const http_p3_local_types = [_]ctypes.TypeDef{
    .{ .option = .{ .inner = .string } }, // 0: option<string>
    .{ .option = .{ .inner = .u8 } }, // 1: option<u8>
    .{ .option = .{ .inner = .u16 } }, // 2: option<u16>
    .{ .option = .{ .inner = .u32 } }, // 3: option<u32>
    .{ .option = .{ .inner = .u64 } }, // 4: option<u64>
    .{ .record = .{ .fields = &http_p3_dns_error_payload_fields } }, // 5: DNS-error-payload
    .{ .record = .{ .fields = &http_p3_tls_alert_payload_fields } }, // 6: TLS-alert-received-payload
    .{ .record = .{ .fields = &http_p3_field_size_payload_fields } }, // 7: field-size-payload
    .{ .option = .{ .inner = .{ .type_idx = 7 } } }, // 8: option<field-size-payload>
    .{ .variant = .{ .cases = &http_p3_error_code_cases } }, // 9: error-code
    // The `own<response>` resource type index passed to `.own` here is
    // not consulted by `sizeOfType` / `alignOfType` / `storeValReg` —
    // those treat every `.own` / `.borrow` as a 4-byte canonical handle
    // (see `canonical_abi.zig:247,265,824`). Any value works.
    .{ .result = .{ .ok = .{ .own = 0 }, .err = .{ .variant = 9 } } }, // 10: result<own<response>, error-code>
    .{ .result = .{ .ok = null, .err = .{ .variant = 9 } } }, // 11: result<_, error-code>
};

const HTTP_P3_ERROR_CODE_VARIANT_IDX: u32 = 9;
const HTTP_P3_RESULT_CLIENT_SEND_IDX: u32 = 10;
const HTTP_P3_RESULT_UNIT_ERR_IDX: u32 = 11;

fn httpP3TypeRegistry() abi.TypeRegistry {
    return abi.TypeRegistry.fromTypes(&http_p3_local_types);
}

/// 0.3 HTTP async-func return shapes that `httpP3LowerAsyncPayload`
/// knows how to lower. Mirrors `SocketsP3AsyncReturn`.
///
/// Both `client_send_ok` and `client_send_err` lower into the same
/// `result<own<response>, error-code>` envelope (40 bytes; see
/// the registry comment above) — the variants name the active arm
/// at the call site so the build helpers stay self-documenting.
const HttpP3AsyncReturn = enum {
    /// `result<own<response>, error-code>` — `client.send` /
    /// `handler.handle` ok arm.
    client_send_ok,
    /// `result<own<response>, error-code>` — `client.send` /
    /// `handler.handle` err arm.
    client_send_err,

    pub fn valType(self: HttpP3AsyncReturn) ctypes.ValType {
        return switch (self) {
            .client_send_ok, .client_send_err => .{ .result = HTTP_P3_RESULT_CLIENT_SEND_IDX },
        };
    }
};

/// Lower a fully-lifted `InterfaceValue` for the requested 0.3 HTTP
/// async-func return shape into a canonical-ABI byte buffer suitable
/// for installation on `async_mod.Future.payload`. Owned by `allocator`;
/// the executor's `future_read` rendezvous (or the async-lower
/// retptr copy on `settleFutureDeferred`) frees it after the guest
/// reads. Mirrors `socketsP3LowerAsyncPayload` (#535 / PR #578).
fn httpP3LowerAsyncPayload(
    allocator: Allocator,
    kind: HttpP3AsyncReturn,
    val: InterfaceValue,
) ![]u8 {
    const reg = httpP3TypeRegistry();
    const vt = kind.valType();
    const size = abi.sizeOfType(reg, vt);
    if (size == 0) return error.LowerError;
    const buf = try allocator.alloc(u8, size);
    errdefer allocator.free(buf);
    @memset(buf, 0);
    try abi.storeValReg(buf, 0, vt, val, reg);
    return buf;
}

/// Build a `result<own<response>, error-code>` ok-arm InterfaceValue
/// wrapping `response_handle`. Caller owns the returned tree and must
/// `deinit` it after passing through `httpP3LowerAsyncPayload`.
fn httpP3BuildClientSendOkIv(
    allocator: Allocator,
    response_handle: u32,
) !InterfaceValue {
    const ok_payload = try allocator.create(InterfaceValue);
    ok_payload.* = .{ .handle = response_handle };
    return InterfaceValue{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
}

/// Build a `result<own<response>, error-code>` err-arm InterfaceValue
/// carrying the given 0.3 `error-code` discriminant. `payload=null`
/// on the variant — the lowered buffer is `@memset(0)` first, so
/// payload-bearing arms (DNS-error, internal-error, etc.) get a
/// valid all-zero payload (`option<*>` = none, record { option<*>
/// = none } etc.). Caller owns the returned tree and must `deinit`
/// it after lowering.
fn httpP3BuildClientSendErrIv(
    allocator: Allocator,
    code: HttpErrorCode,
) !InterfaceValue {
    const err_payload = try allocator.create(InterfaceValue);
    err_payload.* = .{
        .variant_val = .{ .discriminant = @intFromEnum(code), .payload = null },
    };
    return InterfaceValue{ .result_val = .{ .is_ok = false, .payload = err_payload } };
}

const streams = @import("../wasi/preview2/streams.zig");
const wasi_p2_core = @import("../wasi/preview2/core.zig");

/// Captured stdout adapter. Owns its `OutputStream` and the `HostInstance`
/// objects exposed to the runtime via `populateProviders`.
///
/// Lifetime: caller `init`s, registers via `populateProviders`, then
/// retains the adapter until any `ComponentInstance` whose imports point
/// at the registered `HostInstance` is destroyed. `deinit` releases the
/// buffer and member maps.
/// `wasi:filesystem/types.descriptor-flags` (#181). Carries the access
/// + sync intent that the guest passed to `descriptor.open-at` and that
/// `descriptor.get-flags` reads back. Bit positions match the WIT order.
pub const FsDescriptorFlags = packed struct(u8) {
    read: bool = false,
    write: bool = false,
    file_integrity_sync: bool = false,
    data_integrity_sync: bool = false,
    requested_write_sync: bool = false,
    mutate_directory: bool = false,
    _pad: u2 = 0,

    pub fn fromBits(bits: u32) FsDescriptorFlags {
        return .{
            .read = (bits & 0b000001) != 0,
            .write = (bits & 0b000010) != 0,
            .file_integrity_sync = (bits & 0b000100) != 0,
            .data_integrity_sync = (bits & 0b001000) != 0,
            .requested_write_sync = (bits & 0b010000) != 0,
            .mutate_directory = (bits & 0b100000) != 0,
        };
    }

    pub fn toBits(self: FsDescriptorFlags) u32 {
        var out: u32 = 0;
        if (self.read) out |= 0b000001;
        if (self.write) out |= 0b000010;
        if (self.file_integrity_sync) out |= 0b000100;
        if (self.data_integrity_sync) out |= 0b001000;
        if (self.requested_write_sync) out |= 0b010000;
        if (self.mutate_directory) out |= 0b100000;
        return out;
    }

    /// Whether host writes against this descriptor must be flushed to
    /// stable storage (i.e. `file.sync()` after each flush boundary).
    /// Matches POSIX `O_SYNC`/`O_DSYNC`. `requested-write-sync`
    /// (`O_RSYNC`) is **read-side** in POSIX and not a write-sync trigger.
    pub fn needsWriteSync(self: FsDescriptorFlags) bool {
        return self.file_integrity_sync or self.data_integrity_sync;
    }
};

/// `wasi:filesystem/types.descriptor` resource — slot in the descriptor
/// table. Indices in `WasiCliAdapter.fs_descriptor_table` are guest
/// handles. Slots are nulled on `[resource-drop]descriptor`, except
/// `.preopen` slots which are persistent (a guest dropping a preopen
/// handle is treated as a no-op so subsequent calls to
/// `preopens.get-directories` and `descriptor.open-at` keep working).
///
/// Each variant carries the `descriptor-flags` the guest requested at
/// open time (#181). Preopens default to `read|write|mutate_directory`
/// so that `open-at` from a preopen retains its pre-#181 capabilities.
pub const FsDescriptor = union(enum) {
    /// Regular file or any other non-directory descriptor opened via
    /// `descriptor.open-at`. Owned — closed on resource-drop.
    file: FsFile,
    /// Directory descriptor opened via `descriptor.open-at` with the
    /// `directory` open-flag. Owned — closed on resource-drop.
    dir: FsDir,
    /// Preopen sandbox root — adapter-owned. Resource-drop is a no-op
    /// for preopens; the adapter closes them in `deinit`.
    preopen: FsDir,

    pub const FsFile = struct {
        file: std.Io.File,
        flags: FsDescriptorFlags = .{},
    };
    pub const FsDir = struct {
        dir: std.Io.Dir,
        flags: FsDescriptorFlags = .{},
    };

    pub fn flags(self: FsDescriptor) FsDescriptorFlags {
        return switch (self) {
            .file => |f| f.flags,
            .dir => |d| d.flags,
            .preopen => |d| d.flags,
        };
    }

    /// Underlying directory handle for any directory-shaped descriptor
    /// (`.dir` or `.preopen`). Returns null for `.file`.
    pub fn asDir(self: FsDescriptor) ?std.Io.Dir {
        return switch (self) {
            .dir => |d| d.dir,
            .preopen => |d| d.dir,
            .file => null,
        };
    }
};

pub const FsPreopen = struct {
    name: []const u8,
    dir_handle: u32,
};

/// `wasi:filesystem/types.directory-entry-stream` resource (#476). A
/// thin owner of a heap-allocated `std.Io.Dir.Iterator`. We heap-
/// allocate because the iterator embeds a ~2 KiB read-buffer field
/// whose self-referential pointer (`reader.buffer = &reader_buffer`)
/// is re-fixed by each `.next(io)` call — that re-fix is what makes
/// it valid for the struct to live in an `ArrayList` slot or to be
/// moved across deinit boundaries.
///
/// Indices in `WasiCliAdapter.dir_entry_stream_table` are guest
/// handles. The stream is independent of the descriptor that
/// produced it; dropping that descriptor must **not** invalidate the
/// stream.
pub const DirEntryStream = struct {
    iter: *std.Io.Dir.Iterator,
    descriptor_lease: ?FsDescriptorTable.Lease = null,
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
};

/// Close a descriptor's underlying handle. Used by both
/// `[resource-drop]descriptor` (for `.file` / `.dir`) and adapter
/// `deinit` (which also closes preopens).
fn closeFsDescriptor(d: FsDescriptor) void {
    const io = std.Io.Threaded.global_single_threaded.io();
    switch (d) {
        .file => |f| f.file.close(io),
        .dir => |d2| d2.dir.close(io),
        .preopen => |d2| d2.dir.close(io),
    }
}

/// `wasi:filesystem/types.error-code` discriminant indices, in the order
/// the WIT spec declares them. Used as `.variant_val.discriminant` for
/// the `result<_, error-code>` err arm.
const FsErrorCode = enum(u32) {
    access = 0,
    would_block = 1,
    already = 2,
    bad_descriptor = 3,
    busy = 4,
    deadlock = 5,
    quota = 6,
    exist = 7,
    file_too_large = 8,
    illegal_byte_sequence = 9,
    in_progress = 10,
    interrupted = 11,
    invalid = 12,
    io = 13,
    is_directory = 14,
    loop = 15,
    too_many_links = 16,
    message_size = 17,
    name_too_long = 18,
    no_device = 19,
    no_entry = 20,
    no_lock = 21,
    insufficient_memory = 22,
    insufficient_space = 23,
    not_directory = 24,
    not_empty = 25,
    not_recoverable = 26,
    unsupported = 27,
    no_tty = 28,
    no_such_device = 29,
    overflow = 30,
    not_permitted = 31,
    pipe = 32,
    read_only = 33,
    invalid_seek = 34,
    text_file_busy = 35,
    cross_device = 36,
};

/// `wasi:sockets/network.error-code` discriminants in WIT-declaration order
/// (37 variants). Used as `.variant_val.discriminant` for the err arm of
/// `result<_, error-code>` returns from sockets host fns.
const SocketErrorCode = enum(u32) {
    unknown = 0,
    access_denied = 1,
    not_supported = 2,
    invalid_argument = 3,
    out_of_memory = 4,
    timeout = 5,
    concurrency_conflict = 6,
    not_in_progress = 7,
    would_block = 8,
    invalid_state = 9,
    new_socket_limit = 10,
    address_not_bindable = 11,
    address_in_use = 12,
    remote_unreachable = 13,
    connection_refused = 14,
    connection_reset = 15,
    connection_aborted = 16,
    datagram_too_large = 17,
    name_unresolvable = 18,
    temporary_resolver_failure = 19,
    permanent_resolver_failure = 20,
};

/// IPv4 vs IPv6 — matches the discriminant order of `ip-address-family`.
const IpAddressFamily = enum(u32) {
    ipv4 = 0,
    ipv6 = 1,
};

const SocketKind = enum { tcp, udp };

const SocketState = enum { unbound, bound, listening, connected, closed };

/// Pending lifecycle-op result. WIT splits each blocking op into a
/// `start-X` / `finish-X` pair: `start` kicks off the work, `finish`
/// reads the result. Our `start-X` runs synchronously (since
/// `std.Io.net` is blocking) and stores the outcome here for the
/// matching `finish-X` to consume. `idle` means no in-flight op.
const PendingTcpOp = enum { idle, bind_done, listen_done, connect_done };

/// Adapter-side `tcp-socket` / `udp-socket` rep. TCP can hold a real
/// `std.Io.net.Server` once `start-listen` succeeds (#178 PR A).
/// UDP holds a `host_socket` after `start-bind` succeeds (#178 PR C).
pub const Socket = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    kind: SocketKind,
    family: IpAddressFamily,
    /// Monotonic adapter-local identity assigned by `pushSocket`.
    /// Pending operations retain this in addition to the recyclable
    /// table handle so a dropped socket cannot transfer an in-flight
    /// operation to a replacement that reuses the same slot.
    resource_generation: u64 = 0,
    state: SocketState = .unbound,
    /// Authorized local address recorded by `start-bind`. Refreshed
    /// from the kernel after `start-listen` (TCP) or immediately
    /// after the real bind syscall (UDP) so guests observe the
    /// ephemeral port when port=0 was requested.
    local_addr: ?std.Io.net.IpAddress = null,
    /// Active listening server. Owned by the rep; closed in
    /// `closeAll`. TCP only.
    server: ?std.Io.net.Server = null,
    /// Pending TCP lifecycle op. Always `.idle` for udp sockets.
    pending: PendingTcpOp = .idle,
    /// UDP datagram socket. Owned by the rep; closed in `closeAll`.
    host_socket: ?std.Io.net.Socket = null,
    /// Deep-copied allow-list from the network rep at bind time.
    /// Owned by the socket; freed in `closeAll`. Prevents UAF if
    /// the network resource is dropped before the socket.
    allow_list: []const IpCidr = &.{},
    /// Connected remote address set by `stream(some(remote))`.
    remote_addr: ?std.Io.net.IpAddress = null,
    /// Generation counter for `stream()` — each call bumps this;
    /// sub-resources record the value at creation. Stale streams
    /// whose generation != socket's return `invalid-state`.
    stream_generation: u32 = 0,
    /// TCP connected stream. Owned by the rep; closed in `closeAll`.
    tcp_stream: ?std.Io.net.Stream = null,
    /// `tcp-socket.receive` owns the socket's read half for the rest of
    /// the resource lifetime. A second call must return `invalid-state`.
    receive_started: bool = false,

    /// Requested listen backlog size. Stored on the rep by
    /// `set-listen-backlog-size` and consumed by `start-listen`.
    listen_backlog: ?u31 = null,

    // ----- Pending socket-option state (#561) ----------------------
    // The WIT spec lets guests set tcp/udp socket options before
    // bind/listen/connect, when there is no kernel fd to forward them
    // to. Setters write the requested value here; once a kernel fd
    // appears (via start-listen for TCP, start-connect for TCP, or
    // start-bind for UDP) `applyPendingSockOpts` flushes the
    // accumulated state via `setsockopt`. Getters return the rep
    // value first and only fall back to kernel `getsockopt` when the
    // rep is null.
    keep_alive_enabled: ?bool = null,
    keep_alive_idle_time: ?u64 = null,
    keep_alive_interval: ?u64 = null,
    keep_alive_count: ?u32 = null,
    hop_limit: ?u8 = null,
    send_buffer_size: ?u64 = null,
    receive_buffer_size: ?u64 = null,

    /// Returns the kernel fd for this socket, or null if no underlying
    /// socket exists yet (e.g., unbound state).
    pub fn getKernelFd(self: *const Socket) ?std.posix.fd_t {
        if (self.tcp_stream) |ts| return ts.socket.handle;
        if (self.server) |srv| return srv.socket.handle;
        if (self.host_socket) |hs| return hs.handle;
        return null;
    }

    /// Flush rep-tracked socket options (#561) onto a freshly opened
    /// kernel fd. Called from `tcpStartListen` / `tcpStartConnect` /
    /// `udpStartBind` after the underlying socket is created. Failures
    /// from `setsockopt` are swallowed: the rep value remains the
    /// source of truth and the corresponding getter still returns it.
    pub fn applyPendingSockOpts(self: *const Socket) void {
        const fd = self.getKernelFd() orelse return;
        if (self.keep_alive_enabled) |e| {
            _ = socketSetU32Opt(fd, SOL_SOCKET_OPT, SO_KEEPALIVE_OPT, if (e) 1 else 0);
        }
        if (self.keep_alive_idle_time) |ns| {
            const secs: u32 = @intCast(@min(ns / 1_000_000_000, std.math.maxInt(u32)));
            if (secs != 0) {
                _ = socketSetU32Opt(fd, IPPROTO_TCP_OPT, TCP_KEEPIDLE_OPT, secs);
            }
        }
        if (self.keep_alive_interval) |ns| {
            const secs: u32 = @intCast(@min(ns / 1_000_000_000, std.math.maxInt(u32)));
            if (secs != 0) {
                _ = socketSetU32Opt(fd, IPPROTO_TCP_OPT, TCP_KEEPINTVL_OPT, secs);
            }
        }
        if (self.keep_alive_count) |c| {
            _ = socketSetU32Opt(fd, IPPROTO_TCP_OPT, TCP_KEEPCNT_OPT, c);
        }
        if (self.hop_limit) |h| {
            _ = switch (self.family) {
                .ipv4 => socketSetU32Opt(fd, IPPROTO_IP_OPT, IP_TTL_OPT, @as(u32, h)),
                .ipv6 => socketSetU32Opt(fd, IPPROTO_IPV6_OPT, IPV6_UNICAST_HOPS_OPT, @as(u32, h)),
            };
        }
        if (self.send_buffer_size) |sz| {
            _ = socketSetU32Opt(fd, SOL_SOCKET_OPT, SO_SNDBUF_OPT, @intCast(@min(sz, std.math.maxInt(u32))));
        }
        if (self.receive_buffer_size) |sz| {
            _ = socketSetU32Opt(fd, SOL_SOCKET_OPT, SO_RCVBUF_OPT, @intCast(@min(sz, std.math.maxInt(u32))));
        }
    }

    /// Release any held kernel resources. Idempotent. Called from
    /// `[resource-drop]{tcp,udp}-socket` and adapter `deinit`.
    pub fn closeAll(self: *Socket, io: std.Io, allocator: Allocator) void {
        if (self.server) |*srv| srv.deinit(io);
        self.server = null;
        if (self.tcp_stream) |*ts| ts.close(io);
        self.tcp_stream = null;
        if (self.host_socket) |*hs| hs.close(io);
        self.host_socket = null;
        if (self.allow_list.len != 0) allocator.free(self.allow_list);
        self.allow_list = &.{};
        self.remote_addr = null;
    }
};

/// Rep for `wasi:sockets/udp.incoming-datagram-stream`. Each instance
/// is tied to a parent `Socket` via `parent_handle` and validated via
/// `generation` — if the socket's `stream_generation` has advanced
/// past this stream's, all operations return `invalid-state`.
pub const UdpIncomingStream = struct {
    parent_handle: u32,
    parent_lease: if (build_options.lib_wasi_threads) ?SocketTable.Lease else void =
        if (build_options.lib_wasi_threads) null else {},
    generation: u32,
    remote: ?std.Io.net.IpAddress,
};

/// Rep for `wasi:sockets/udp.outgoing-datagram-stream`. Tracks
/// `send_credit` for the WIT-mandated `check-send` / `send`
/// protocol: `send` traps if `check-send` was not called first
/// or if `datagrams.len > send_credit`.
pub const UdpOutgoingStream = struct {
    parent_handle: u32,
    parent_lease: if (build_options.lib_wasi_threads) ?SocketTable.Lease else void =
        if (build_options.lib_wasi_threads) null else {},
    generation: u32,
    remote: ?std.Io.net.IpAddress,
    send_credit: ?u64 = null,
};

/// CIDR block for the per-`network` allow-list (#180). Stored canonical:
/// host bits below the prefix are zeroed at parse time.
pub const IpCidr = union(enum) {
    ip4: struct { bytes: [4]u8, prefix: u6 },
    ip6: struct { bytes: [16]u8, prefix: u8 },

    pub const ParseError = error{
        InvalidCidr,
        InvalidPrefix,
        InvalidAddress,
    };

    /// Parse `"<addr>/<prefix>"`. The address half is parsed with port=0 by
    /// `Ip4Address.parse` / `Ip6Address.parse`; v4 is tried first. Prefix
    /// must be plain decimal (no leading `+`/`-`/zero-padding) within
    /// 0..=32 (v4) or 0..=128 (v6). Host bits are masked to zero so two
    /// textual variants of the same network compare equal.
    pub fn parse(text: []const u8) ParseError!IpCidr {
        const slash = std.mem.indexOfScalar(u8, text, '/') orelse return error.InvalidCidr;
        const addr_text = text[0..slash];
        const prefix_text = text[slash + 1 ..];
        if (addr_text.len == 0 or prefix_text.len == 0) return error.InvalidCidr;
        // Reject leading zeros / signs in prefix to keep canonical text.
        if (prefix_text[0] == '+' or prefix_text[0] == '-') return error.InvalidPrefix;
        if (prefix_text.len > 1 and prefix_text[0] == '0') return error.InvalidPrefix;
        for (prefix_text) |c| if (c < '0' or c > '9') return error.InvalidPrefix;
        // Reject bracketed IPv6 (`[::]/128`) — CIDR text is bare.
        if (addr_text[0] == '[') return error.InvalidAddress;

        if (std.Io.net.Ip4Address.parse(addr_text, 0)) |v4| {
            const p = std.fmt.parseInt(u8, prefix_text, 10) catch return error.InvalidPrefix;
            if (p > 32) return error.InvalidPrefix;
            var bytes = v4.bytes;
            maskV4(&bytes, @intCast(p));
            return .{ .ip4 = .{ .bytes = bytes, .prefix = @intCast(p) } };
        } else |_| {}
        if (std.Io.net.Ip6Address.parse(addr_text, 0)) |v6| {
            const p = std.fmt.parseInt(u8, prefix_text, 10) catch return error.InvalidPrefix;
            if (p > 128) return error.InvalidPrefix;
            var bytes = v6.bytes;
            maskV6(&bytes, p);
            return .{ .ip6 = .{ .bytes = bytes, .prefix = p } };
        } else |_| {}
        return error.InvalidAddress;
    }

    /// Same-family bit-prefix match. Mixed families never match — IPv4-
    /// mapped IPv6 addresses are matched as IPv6 only (callers receive an
    /// `IpAddress` already discriminated by the wasi:sockets layer).
    pub fn containsAddr(self: IpCidr, addr: std.Io.net.IpAddress) bool {
        return switch (self) {
            .ip4 => |c| switch (addr) {
                .ip4 => |a| matchPrefix(&c.bytes, &a.bytes, c.prefix),
                .ip6 => false,
            },
            .ip6 => |c| switch (addr) {
                .ip6 => |a| matchPrefix(&c.bytes, &a.bytes, c.prefix),
                .ip4 => false,
            },
        };
    }
};

fn maskV4(bytes: *[4]u8, prefix: u6) void {
    if (prefix >= 32) return;
    var i: usize = 0;
    var remaining: u8 = prefix;
    while (i < 4) : (i += 1) {
        if (remaining >= 8) {
            remaining -= 8;
        } else if (remaining == 0) {
            bytes[i] = 0;
        } else {
            const keep: u8 = @as(u8, 0xff) << @intCast(8 - remaining);
            bytes[i] &= keep;
            remaining = 0;
        }
    }
}

fn maskV6(bytes: *[16]u8, prefix: u8) void {
    if (prefix >= 128) return;
    var i: usize = 0;
    var remaining: u8 = prefix;
    while (i < 16) : (i += 1) {
        if (remaining >= 8) {
            remaining -= 8;
        } else if (remaining == 0) {
            bytes[i] = 0;
        } else {
            const keep: u8 = @as(u8, 0xff) << @intCast(8 - remaining);
            bytes[i] &= keep;
            remaining = 0;
        }
    }
}

fn matchPrefix(cidr_bytes: []const u8, addr_bytes: []const u8, prefix: u8) bool {
    var remaining: u8 = prefix;
    var i: usize = 0;
    while (remaining >= 8) : (i += 1) {
        if (cidr_bytes[i] != addr_bytes[i]) return false;
        remaining -= 8;
    }
    if (remaining == 0) return true;
    const mask: u8 = @as(u8, 0xff) << @intCast(8 - remaining);
    return (cidr_bytes[i] & mask) == (addr_bytes[i] & mask);
}

/// Adapter-side `network` rep (#180). Carries a per-instance allow-list of
/// CIDR blocks snapshotted from `WasiCliAdapter.sockets_allow_list_template`
/// at `instance-network` time; the snapshot is owned by the Network and
/// freed in `[resource-drop]network` / adapter `deinit`. Empty list = the
/// default deny-all capability for the 0.2 surface.
///
/// Note: the 0.3 sockets path does not go through a `Network` resource
/// (the 0.3 WIT dropped `network` entirely). It consults
/// `WasiCliAdapter.sockets_allow_list_template` directly via
/// `templateAllows` — see that helper for the empty-template semantics
/// (allow-all for raw sockets, deny-all for DNS / outbound HTTP). (#583 A1)
pub const Network = struct {
    allow_list: []const IpCidr = &.{},

    pub fn allows(self: Network, addr: std.Io.net.IpAddress) bool {
        for (self.allow_list) |c| if (c.containsAddr(addr)) return true;
        return false;
    }

    fn deinit(self: *Network, allocator: Allocator) void {
        if (self.allow_list.len != 0) allocator.free(self.allow_list);
        self.allow_list = &.{};
    }
};

/// Adapter-side `resolve-address-stream` rep. `pos` advances on each
/// `resolve-next-address` until `pos == results.len`, after which the
/// stream returns `option<ip-address>::none`. The slice and `self`
/// itself are owned by the adapter and freed in `deinit` /
/// `[resource-drop]resolve-address-stream`.
pub const ResolveAddressStream = struct {
    results: []std.Io.net.IpAddress,
    pos: usize,
    allocator: Allocator,
};

/// Lifetime-stable context for a `host_driver` attached to a socket-
/// backed `AsyncStream` (#535). The executor invokes the driver
/// callbacks with this opaque pointer; the callbacks unwrap it,
/// consult the fd, and (for accept) push new sockets through the
/// adapter. The adapter table publishes a self-lease in enabled builds;
/// `AsyncStream.deinit` invokes `on_destroy`, which retires that entry
/// only after the final callback lease is gone.
///
/// ## Cancel observation (#583 follow-up to #607)
///
/// `cancelled` is flipped by `cancelAllPendingAsyncOps` when the
/// guest issues `canon task.cancel`. The TCP receive drivers
/// (`tcpReceiveStreamOnRead` and the zero-copy
/// `tcpReceiveStreamOnReadInto`, #583 B2) poll it with
/// `.load(.acquire)` at entry and short-circuit with `.err` so the
/// executor's `stream.read` rendezvous closes the writable end and
/// the guest's next `stream.read` observes the natural DROPPED status.
///
/// Per-chunk cancel granularity: the executor's zero-copy
/// `stream.read` arm loops `on_read_into` up to 32 iterations per
/// guest-visible `stream.read`, and each driver invocation is capped
/// at 64 KiB by `tcpReceiveStreamOnReadInto`. A `task.cancel` issued
/// mid-multi-MiB receive is therefore observed within at most one
/// chunk's `recv(2)` latency, mirroring the per-chunk cadence
/// established by the FS drivers in #607 and the HTTP body-read
/// loop in #602. The kernel `recv(2)` syscall itself is atomic
/// from cancel's POV — a 64 KiB recv that already entered the
/// kernel runs to completion; any bytes it lands in the borrowed
/// guest-linmem slice are accounted to the executor's running
/// `total_bytes` counter and surfaced to the guest as
/// `.completed(partial_count)` before `s.write_closed` flips.
///
/// Atomic so a multi-threaded host can flip the flag mid-loop from
/// a separate cancel driver thread without UB. The flag lives on
/// every socket-stream ctx (receive, send, accept) but is observed
/// only by the receive drivers today; tcp-send / tcp-accept ignore
/// it and are tracked for a future PR if their executor loops grow
/// the same multi-chunk shape.
pub const SocketsP3StreamCtx = struct {
    adapter: *WasiCliAdapter,
    registry_handle: u32 = std.math.maxInt(u32),
    self_lease: ?SocketsP3StreamCtxTable.Lease = null,
    socket_handle: ?u32 = null,
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    fd: std.posix.fd_t,
    family: IpAddressFamily,
    cancelled: std.atomic.Value(bool) = .{ .raw = false },
    component_instance: ?*ComponentInstance = null,
    completion_future: ?u32 = null,
    send_failed: std.atomic.Value(bool) = .{ .raw = false },
};

/// Lifetime-stable context for a `host_driver` attached to an
/// `AsyncStream` created by `descriptor.write-via-stream` /
/// `descriptor.append-via-stream` (#571). The executor invokes
/// `writeViaStreamOnWrite` with this opaque pointer; the callback
/// looks up the underlying `FsDescriptor` (so a guest dropping the
/// descriptor while the stream is still live surfaces gracefully as
/// `.err`) and `pwrite(2)`s the guest's bytes at
/// `offset + bytes_written`, tracking the running offset.
///
/// Owned by `WasiCliAdapter.fs_write_stream_ctxs` until the attached
/// `AsyncStream` invokes its exact-once `on_destroy` callback.
pub const FsWriteStreamCtx = struct {
    adapter: *WasiCliAdapter,
    registry_handle: u32 = std.math.maxInt(u32),
    self_lease: ?FsWriteStreamCtxTable.Lease = null,
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    /// Guest-visible `descriptor` handle for the target file. We
    /// re-lookup on every callback instead of stashing a `std.Io.File`
    /// by value so a `[resource-drop]descriptor` mid-stream surfaces
    /// as an error instead of a UAF on the fd.
    desc_handle: u32,
    /// Base offset captured at `write-via-stream` call time. For
    /// `append-via-stream` we ignore this and re-stat each call.
    offset: u64,
    /// Running byte counter — sum of all bytes pwrite'd so far. The
    /// next `on_write` call writes at `offset + bytes_written`.
    bytes_written: u64,
    /// True if this driver was installed by `append-via-stream`. The
    /// `on_write` callback stats the file each call and writes at
    /// end-of-file instead of `offset + bytes_written`.
    append: bool,
    /// Flipped by the adapter's `cancelAllPendingAsyncOps` driver when
    /// the guest issues `canon task.cancel` (#583 B1, #602 follow-up).
    ///
    /// The drain loop in `fsWriteViaStreamOnWrite` polls this with
    /// `.load(.acquire)` between every `FS_CANCEL_POLL_CHUNK_BYTES`-
    /// sized `pwrite(2)` chunk and short-circuits with `.err` so the
    /// executor flips `read_closed = true` and the guest's next
    /// `stream.write` sees `DROPPED`. A multi-MiB guest buffer is
    /// split into 64 KiB chunks under the hood, so cancel is observed
    /// within at most one chunk's `pwrite(2)` latency — mirroring the
    /// per-chunk granularity the HTTP outbound body-read loop uses
    /// (#602). The kernel `pwrite(2)` syscall itself is atomic from
    /// cancel's POV (a 64 KiB write either lands fully or fails), so
    /// the chunk currently in flight always runs to completion.
    ///
    /// Atomic so a multi-threaded host can flip the flag mid-drain
    /// from a separate cancel driver / event loop thread without UB;
    /// the single-threaded executor path issues plain
    /// `.store(true, .release)` from `cancelAllPendingAsyncOps`.
    cancelled: std.atomic.Value(bool) = .{ .raw = false },
};

/// `AsyncStream` created by `descriptor.read-via-stream` (#573,
/// #583 B1). Today's `fsDescriptorReadViaStreamP3` eagerly pre-buffers
/// up to `FS_STREAM_BUFFER_CAP` bytes during the trampoline call and
/// closes the writable end before returning; the pre-buffer fill is
/// itself broken into `FS_CANCEL_POLL_CHUNK_BYTES`-sized
/// `readPositional` chunks so a `task.cancel` issued mid-fill is
/// observed within one chunk's latency (#583, #602 follow-up). The
/// lazy `fsReadViaStreamOnRead` callback exists so the
/// `cancelAllPendingAsyncOps` driver still has a uniform place to
/// observe cancellation for read streams once the writable end is
/// re-opened: the `cancelled` flag is flipped on `canon task.cancel`,
/// and `fsReadViaStreamOnRead` short-circuits with `.eof`. If a
/// future PR refactors read-via-stream into a chunked lazy drain (so
/// files > 64 MiB stream rather than truncate), the existing wire-up
/// automatically delivers cancel propagation through the same
/// callback at the same 64 KiB cadence.
pub const FsReadStreamCtx = struct {
    adapter: *WasiCliAdapter,
    registry_handle: u32 = std.math.maxInt(u32),
    self_lease: ?FsReadStreamCtxTable.Lease = null,
    /// Guest-visible `descriptor` handle for the source file. Kept
    /// for symmetry with `FsWriteStreamCtx` and so a future lazy
    /// re-fill can `pread(2)` further chunks without re-lookup
    /// races on a dropped descriptor.
    desc_handle: u32,
    /// Base offset captured at `read-via-stream` call time. Today
    /// only used for the eager pre-buffer; the lazy on_read path
    /// would add it to `bytes_read` for the next pread.
    offset: u64,
    /// Running byte counter — sum of all bytes pread'd so far. The
    /// next on_read call (if the eager mode is ever relaxed) would
    /// read at `offset + bytes_read`. Updated after every chunked
    /// pre-buffer fill in `fsDescriptorReadViaStreamP3`.
    bytes_read: u64 = 0,
    /// Set by `cancelAllPendingAsyncOps` (#583 B1, #602 follow-up).
    /// Polled with `.load(.acquire)` between every
    /// `FS_CANCEL_POLL_CHUNK_BYTES`-sized `readPositional` chunk in
    /// the eager pre-buffer loop and by `fsReadViaStreamOnRead` to
    /// surface `.eof` and close the stream cleanly. Mirrors the
    /// finer-grained cancel cadence the HTTP outbound body-read
    /// loop uses (#602).
    cancelled: std.atomic.Value(bool) = .{ .raw = false },
};

/// A `udp-socket.receive` call that found no datagram waiting on its
/// first non-blocking `recvfrom(2)` and so returned a `.pending`
/// future. The async event driver (`driveAsyncEvents`) polls the
/// recorded fd on every `waitable-set.wait` iteration and, when a
/// datagram arrives, lifts the `result<tuple<list<u8>,
/// ip-socket-address>, error-code>` payload into the future and
/// fires the WaitableSet wakeup so the guest's awaited `.receive()`
/// resolves (#576).
///
/// Mirrors the deferred-completion shape used by the `wasi:clocks`
/// timer-future infrastructure (#551): the host adapter parks the
/// future, the driver drives it on each event-loop tick, and the
/// trampoline's `async_lower_retptr` stash gets written when the
/// future settles.
pub const PendingUdpReceive = struct {
    future_handle: u32,
    sock_handle: u32,
    socket_generation: u64,
    /// Keeps the exact socket node retired-but-alive until the queued
    /// receive is settled or cancelled, preventing handle ABA.
    socket_lease: ?SocketTable.Lease = null,
    claimed: std.atomic.Value(bool) = .{ .raw = false },
    /// Flipped by `cancelAllPendingAsyncOps` when the guest issues
    /// `canon task.cancel` while this receive is parked (#583 B1).
    /// `completeReadyPendingUdpReceives` observes the flag on its
    /// next tick and settles the future with
    /// `STATUS_STARTED_CANCELLED` instead of waiting for a datagram.
    /// We do not pre-settle from the cancel driver itself so all
    /// future settlement (incl. memcpy into `async_lower_retptr`)
    /// stays funnelled through the same `settleFutureDeferred`
    /// helper used by the success path — race-free even if a
    /// datagram lands between cancel signal and next drive tick.
    cancelled: std.atomic.Value(bool) = .{ .raw = false },
};

/// Outcome captured by an outbound HTTP worker thread (#583 A2). Shared
/// across the worker thread and the adapter's drain side via a heap-
/// allocated `PendingHttpFetchShared`. The two threads coordinate
/// through `done` (worker → adapter signal) and `cancelled` (adapter →
/// worker advisory); the heap struct is freed only after the thread
/// has been joined, so a slow outbound fetch can never UAF even if
/// the guest cancels or the adapter tears down mid-flight.
pub const HttpFetchOutcome = union(enum) {
    /// Successful HTTP response. `body` is owned host-allocated bytes
    /// consumed into an `IncomingResponse` on settle; `status` is the
    /// numeric HTTP response status; `headers` is the wire-order list
    /// of `(name, value)` pairs the server emitted, with transport-
    /// managed headers (Content-Length, Transfer-Encoding, Connection,
    /// Keep-Alive, Trailer, Upgrade, TE, Host) stripped per the
    /// wasi:http WIT spec (#583 A4). Each entry's `name` and `value`
    /// are independently owned `[]u8` slices.
    success: struct {
        status: u16,
        body: []u8,
        headers: []HttpFieldEntry,
    },
    /// Transport / TLS / parse failure mapped to a
    /// `wasi:http/types.error-code` discriminant.
    failure: HttpErrorCode,
};

/// Free an owned `[]HttpFieldEntry` produced by the low-level outbound
/// HTTP path (`httpClientLowLevelFetch` / worker). Frees each entry's
/// name + value plus the backing slice. Used both on the worker side
/// when the guest has already dropped the future-incoming-response and
/// on the settle side once entries transfer into a `HttpFields`. The
/// helper exists so the lifetime contract is centralised — anywhere
/// that owns a `HttpFetchOutcome.success.headers` slice can free it
/// without re-deriving the layout. (#583 A4)
fn freeOwnedHttpHeaders(allocator: Allocator, headers: []HttpFieldEntry) void {
    for (headers) |e| {
        allocator.free(e.name);
        allocator.free(e.value);
    }
    allocator.free(headers);
}

/// Returns `true` for HTTP headers the host manages on behalf of the
/// guest and must therefore strip from the lifted `incoming-response`
/// header set per the wasi:http WIT spec (#583 A4):
///
///   * `Content-Length` — body framing; recomputable from the body
///     stream. The host owns the wire framing; the guest sees a
///     `stream<u8>`, not byte counts.
///   * `Transfer-Encoding` — likewise body framing (chunked, etc.).
///   * `Connection`, `Keep-Alive` — hop-by-hop connection lifecycle.
///   * `Trailer`, `TE` — hop-by-hop trailer negotiation. wasi:http
///     surfaces trailers via the `future-trailers` resource instead.
///   * `Upgrade` — protocol upgrade hop-by-hop.
///   * `Host` — request-only target authority (only relevant on the
///     outgoing side, kept here defensively for symmetry).
///
/// Comparison is ASCII case-insensitive per RFC 9110 §5.1.
fn isTransportManagedHeader(name: []const u8) bool {
    const managed = [_][]const u8{
        "content-length",
        "transfer-encoding",
        "connection",
        "keep-alive",
        "trailer",
        "te",
        "upgrade",
        "host",
    };
    for (managed) |m| {
        if (std.ascii.eqlIgnoreCase(name, m)) return true;
    }
    return false;
}

/// Heap-allocated state shared between the host's outbound-HTTP worker
/// thread and the adapter's drain side. The worker writes `outcome`
/// then publishes via `done.store(true, .release)`; the adapter checks
/// `done.load(.acquire)` from `drainPendingHttpFetches` and only frees
/// the struct after `thread.join()` returns, guaranteeing no UAF even
/// when the worker is still mid-fetch.
///
/// `cancelled` is an adapter → worker advisory polled by the worker
/// at every `std.http.Client.Request` phase boundary in
/// `httpClientLowLevelFetch` — pre-connect, pre-send, pre-receive-head,
/// pre-body-read, and per `http_cancel_body_chunk_bytes` body chunk
/// (#583 B1 follow-up). The drain side ALSO checks the flag post-
/// completion so a guest `task.cancel` that races a worker publish
/// is still honoured by surfacing `HTTP_request_denied` to the
/// future the guest awaits (#488 cancel-propagation pattern). (#583 A2)
pub const PendingHttpFetchShared = struct {
    done: std.atomic.Value(bool) = .{ .raw = false },
    cancelled: std.atomic.Value(bool) = .{ .raw = false },
    /// Worker fetches into this slot once before flipping `done`.
    /// Adapter takes ownership of `success.body` on settle and frees
    /// it after the guest consumes the incoming-response.
    outcome: HttpFetchOutcome = .{ .failure = .internal_error },
    /// Wakeable backend so the host block/poll loop can sleep on the
    /// worker's completion instead of busy-spinning (#833). The worker
    /// `signal()`s this right after publishing `done`; `pollableBackend`
    /// (P2) and `driveAsyncEvents` (P3) hand `read_fd` to `poll()` so the
    /// host thread parks until the round-trip finishes — matching
    /// wasmtime's "sleep on the socket" CPU profile. `null` for direct
    /// unit-test constructions / Windows (where the poll path is disabled).
    waker: ?Waker = null,
};

/// `wamr serve` graceful-shutdown state (#918). Set by the async-signal-safe
/// SIGINT/SIGTERM handler and observed by the accept loop in
/// `serveLoadedHttpComponent`. `http_shutdown_requested` is the source of
/// truth; `http_shutdown_wake_fd` is the write end of a self-pipe the
/// handler pokes to wake a `poll()` parked on the listener. Process-global
/// because a process serves at most one long-lived listener at a time; the
/// finite-`max_requests` unit-test path never installs the handler, so it
/// leaves these untouched.
var http_shutdown_requested: std.atomic.Value(bool) = .init(false);
var http_shutdown_wake_fd: std.atomic.Value(i32) = .init(-1);

/// The self-pipe waker the accept loop parks on and the signal handler
/// pokes. Owned by the arm/disarm pair below; the loop borrows its
/// `read_fd`. Process-global for the same single-listener reason as the
/// flag above. Only touched on the main (control-flow) path — never
/// inside the signal handler, which reads `http_shutdown_wake_fd` instead.
var http_shutdown_waker: ?Waker = null;
var http_shutdown_armed: bool = false;

/// Block SIGINT/SIGTERM on the calling (main) thread. Call this as early
/// as possible — *before* the multi-second component decode + JIT compile
/// — so a signal that races startup is held **pending** instead of being
/// lost. A blocked signal becomes pending even when its disposition is
/// `SIG_IGN` (the accept loop's process inherits `SIG_IGN` for SIGINT from
/// a background shell, and Zig's startup momentarily resets the
/// disposition via a `system(3)`-style helper); `armHttpShutdown` later
/// installs the real handler and unblocks, at which point the pending
/// signal is delivered to it. This is what makes the task's
/// `sleep 1; kill -INT` startup-race reproduction exit cleanly (#918).
/// A no-op on Windows (the `switch` keeps the POSIX arm out of the
/// Windows build).
pub fn blockHttpShutdownSignals() void {
    switch (builtin.os.tag) {
        .windows => return,
        else => setHttpShutdownSignalMask(std.posix.SIG.BLOCK),
    }
}

/// Unblock SIGINT/SIGTERM on the calling thread, delivering any instance
/// that went pending while blocked. Called by `armHttpShutdown` *after*
/// the handler is installed so a startup-race signal fires into the
/// handler rather than the (possibly `SIG_IGN`) startup disposition.
fn unblockHttpShutdownSignals() void {
    switch (builtin.os.tag) {
        .windows => return,
        else => setHttpShutdownSignalMask(std.posix.SIG.UNBLOCK),
    }
}

fn setHttpShutdownSignalMask(how: u32) void {
    switch (builtin.os.tag) {
        .windows => return,
        else => {
            var set = std.posix.sigemptyset();
            std.posix.sigaddset(&set, std.posix.SIG.INT);
            std.posix.sigaddset(&set, std.posix.SIG.TERM);
            std.posix.sigprocmask(how, &set, null);
        },
    }
}

/// Arm the portable `wamr serve` SIGINT/SIGTERM graceful-shutdown path.
/// Creates the self-pipe waker, publishes its write end for the handler,
/// installs the async-signal-safe handler, and finally unblocks the
/// signals (see `blockHttpShutdownSignals`). Call this *late* — right
/// before entering the accept loop, once all of startup's signal
/// manipulation is done — so the handler installed here survives to
/// service the shutdown. Idempotent and a no-op on Windows; pair with
/// `disarmHttpShutdown` on teardown.
pub fn armHttpShutdown() void {
    if (comptime builtin.os.tag == .windows) return;
    if (http_shutdown_armed) return;
    http_shutdown_armed = true;
    http_shutdown_requested.store(false, .release);
    http_shutdown_waker = Waker.init() catch null;
    if (http_shutdown_waker) |w| http_shutdown_wake_fd.store(w.write_fd, .release);
    installHttpShutdownHandler();
    // Deliver any SIGINT/SIGTERM that went pending during startup now that
    // the real handler is in place.
    unblockHttpShutdownSignals();
}

/// Tear down the shutdown waker installed by `armHttpShutdown`. Stops
/// publishing the write fd before closing it so a late signal can't write
/// into a closed / reused descriptor. Idempotent; no-op on Windows.
pub fn disarmHttpShutdown() void {
    if (comptime builtin.os.tag == .windows) return;
    http_shutdown_wake_fd.store(-1, .release);
    if (http_shutdown_waker) |*w| w.deinit();
    http_shutdown_waker = null;
    http_shutdown_armed = false;
}

/// Cross-platform self-pipe waker (#833). A worker thread that settles a
/// future without owning a pollable fd (outbound HTTP, future-trailers)
/// uses this so the host's `std.posix.poll`-based block/poll loop has a
/// real fd to sleep on: `signal()` writes one byte from the worker and
/// `poll()` on `read_fd` then returns. Exactly one byte is written per
/// fetch (one worker per pipe), and the host never reads the byte — it
/// closes both ends via `deinit()` once the settled future is observed —
/// so the pipe buffer never fills and the blocking `write` never stalls.
///
/// Unsupported on Windows — the host poll path (`waitForBackendEvents`) is
/// already a no-op there, so the pre-existing Windows busy-wait is out of
/// scope for this fix.
pub const Waker = struct {
    read_fd: std.posix.fd_t,
    write_fd: std.posix.fd_t,

    pub fn init() !Waker {
        if (comptime builtin.os.tag == .windows) return error.Unsupported;
        var fds: [2]std.posix.fd_t = undefined;
        switch (std.posix.errno(std.posix.system.pipe(&fds))) {
            .SUCCESS => {},
            else => return error.Unsupported,
        }
        // Best-effort close-on-exec so the pipe ends don't leak into any
        // child the host process spawns (mirrors the socket-create path).
        setCloexec(fds[0]);
        setCloexec(fds[1]);
        return .{ .read_fd = fds[0], .write_fd = fds[1] };
    }

    fn setCloexec(fd: std.posix.fd_t) void {
        if (comptime builtin.os.tag == .windows) return;
        while (true) switch (std.posix.errno(std.posix.system.fcntl(
            fd,
            std.posix.F.SETFD,
            @as(usize, std.posix.FD_CLOEXEC),
        ))) {
            .INTR => continue,
            else => break,
        };
    }

    /// Wake any `poll()` parked on `read_fd`. Called from the worker
    /// thread after `done.store(.release)`.
    pub fn signal(self: Waker) void {
        if (comptime builtin.os.tag == .windows) return;
        const byte = [_]u8{1};
        while (true) switch (std.posix.errno(std.posix.system.write(self.write_fd, &byte, 1))) {
            .INTR => continue,
            else => break,
        };
    }

    pub fn deinit(self: *Waker) void {
        if (comptime builtin.os.tag == .windows) return;
        _ = std.posix.system.close(self.read_fd);
        _ = std.posix.system.close(self.write_fd);
        self.read_fd = -1;
        self.write_fd = -1;
    }
};

/// One in-flight outbound HTTP fetch driven by a dedicated worker
/// thread. The future-incoming-response handle is settled by the
/// adapter's `drainPendingHttpFetches` driver once `shared.done` is
/// observed; the worker thread is `join()`ed at that point so the
/// shared heap struct can be safely freed. (#583 A2)
///
/// Mirrors the deferred-completion shape of `PendingUdpReceive`
/// (#576) but with a thread-driven completion source — Zig 0.16's
/// `std.http.Client.fetch` is blocking, and the spec-compliant
/// shape is a `.pending` future the guest can poll on.
pub const PendingHttpFetch = struct {
    armed: std.atomic.Value(bool) = .{ .raw = false },
    /// Handle into `WasiCliAdapter.http_future_responses` of the
    /// future-incoming-response the guest is awaiting.
    future_handle: u32,
    /// Worker thread executing the blocking `std.http.Client.fetch`.
    /// Joined exactly once by the adapter — either at drain time
    /// when `shared.done` is observed, or at adapter teardown.
    thread: ?std.Thread,
    /// Heap-allocated coordination block — outlives both threads up
    /// to the post-join free in `drainPendingHttpFetches` / `deinit`.
    shared: ?*PendingHttpFetchShared,
    /// Keeps the exact future node alive after a concurrent guest drop.
    /// A closing lease is never settled and prevents handle reuse until
    /// the worker has joined and the operation releases this reference.
    future_lease: ?FutureIncomingResponseTable.Lease,
};

/// One in-flight outbound HTTP fetch backing a P3 `client.send` /
/// `handler.handle` async-func call (#589). Mirrors `PendingHttpFetch`
/// but settles a `async_mod.Future` slot on the guest's
/// `ComponentInstance.futures` table (rather than the adapter-owned
/// `FutureIncomingResponse`) with canonical-ABI-lowered
/// `result<own<response>, error-code>` bytes via
/// `httpP3LowerAsyncPayload` + `settleFutureDeferred`.
///
/// The worker thread (`httpFetchWorker`) and the shared coordination
/// block (`PendingHttpFetchShared`) are reused unchanged from the
/// P2 path; only the settle side differs.
pub const PendingHttpFetchP3 = struct {
    armed: std.atomic.Value(bool) = .{ .raw = false },
    /// Handle into `ComponentInstance.futures` of the async-future
    /// the guest is awaiting via `canon.lower (async)`.
    future_handle: u32,
    /// `ComponentInstance` that owns the future slot. Stored so the
    /// drainer can write the canonical-ABI bytes back to the guest's
    /// `async_lower_retptr` and fire its WaitableSet wakeup. Borrowed
    /// — the adapter is registered as the `async_event_driver` on
    /// the same `ComponentInstance`, so this pointer outlives the
    /// pending entry.
    ci: *ComponentInstance,
    /// Worker thread executing the blocking `std.http.Client.fetch`.
    /// Joined exactly once by the adapter — either at drain time
    /// when `shared.done` is observed, or at adapter teardown.
    thread: ?std.Thread,
    /// Heap-allocated coordination block — outlives both threads up
    /// to the post-join free in `drainPendingHttpFetchesP3` / `deinit`.
    shared: ?*PendingHttpFetchShared,
};

/// Snapshot of an `OutgoingRequest` plus body bytes that the worker
/// thread needs to perform a `std.http.Client.fetch` independently
/// of the adapter (so the adapter is free to mutate / drop the
/// request resource without racing). Owned by the worker; freed
/// in `httpFetchWorker` after the fetch returns. (#583 A2)
const HttpFetchRequest = struct {
    allocator: Allocator,
    io: std.Io,
    url: []u8,
    method: std.http.Method,
    /// Scalar snapshot copied from the guest resource before the
    /// worker is spawned. Never points back into an adapter resource
    /// table, whose slot may be dropped while the worker is running.
    options: HttpFetchOptions,
    /// Header name/value slices, dupe'd into worker-owned memory.
    headers_buf: []std.http.Header,
    headers_names: [][]u8,
    headers_values: [][]u8,
    /// Optional request body bytes, owned host-allocated.
    payload: ?[]u8,
    /// The `PendingHttpFetchShared` slot the worker will publish
    /// its outcome through.
    shared: *PendingHttpFetchShared,

    fn deinit(self: *HttpFetchRequest) void {
        self.allocator.free(self.url);
        for (self.headers_names) |n| self.allocator.free(n);
        for (self.headers_values) |v| self.allocator.free(v);
        self.allocator.free(self.headers_names);
        self.allocator.free(self.headers_values);
        self.allocator.free(self.headers_buf);
        if (self.payload) |p| self.allocator.free(p);
    }
};

/// Worker-owned subset of `wasi:http/types.request-options` currently
/// implemented by the transport. Keeping this separate from
/// `RequestOptions` makes it impossible for a worker to borrow a guest
/// resource-table entry across adapter/worker lifetimes.
const HttpFetchOptions = struct {
    connect_timeout_ns: ?u64 = null,
    first_byte_timeout_ns: ?u64 = null,
    between_bytes_timeout_ns: ?u64 = null,

    fn fromRequestOptions(options: ?*const RequestOptions) HttpFetchOptions {
        const value = options orelse return .{};
        return .{
            .connect_timeout_ns = value.connect_timeout_ns,
            .first_byte_timeout_ns = value.first_byte_timeout_ns,
            .between_bytes_timeout_ns = value.between_bytes_timeout_ns,
        };
    }

    /// Convert the WIT nanosecond duration without narrowing. Zig's
    /// `Io.Duration.nanoseconds` is i96, so every u64 value is exactly
    /// representable, including `maxInt(u64)`.
    fn timeoutFromNs(ns: ?u64) std.Io.Timeout {
        const value = ns orelse return .none;
        return .{ .duration = .{
            .raw = .{ .nanoseconds = @as(i96, value) },
            .clock = .awake,
        } };
    }

    /// `request-options.connect-timeout`: budget for acquiring one
    /// hop's connection, i.e. DNS + TCP + (for `https`) the eager TLS
    /// handshake `Client.connectTcpOptions` performs inline.
    fn connectTimeout(self: HttpFetchOptions) std.Io.Timeout {
        return timeoutFromNs(self.connect_timeout_ns);
    }

    /// `request-options.first-byte-timeout`: budget for one hop's
    /// request transmission plus response-head arrival. Applied per
    /// redirect hop, so a slow chain cannot borrow an earlier hop's
    /// unused budget.
    fn firstByteTimeout(self: HttpFetchOptions) std.Io.Timeout {
        return timeoutFromNs(self.first_byte_timeout_ns);
    }

    /// `request-options.between-bytes-timeout`: budget for each
    /// individual body chunk read. A fresh deadline is derived per
    /// chunk, which is what "reset on progress" means — arriving bytes
    /// re-arm the window rather than draining a whole-body budget.
    fn betweenBytesTimeout(self: HttpFetchOptions) std.Io.Timeout {
        return timeoutFromNs(self.between_bytes_timeout_ns);
    }
};

const HttpConnectResult =
    std.http.Client.ConnectTcpError!*std.http.Client.Connection;

const HttpConnectDeadlineOutcome = union(enum) {
    connection: HttpConnectResult,
    deadline: std.Io.Cancelable!void,
    /// #616 A7 cancel lane for the DNS + TCP + TLS-handshake phase.
    cancel: anyerror!void,
};

/// Map a `std.Io.net.HostName.LookupError` to the closest
/// `wasi:sockets/network.error-code` variant. Most parse / nameserver
/// failures funnel into `permanent-resolver-failure`; transient errors
/// (cancelation, would-block) become `temporary-resolver-failure`;
/// "no such host" maps to `name-unresolvable`.
fn mapDnsError(err: anyerror) SocketErrorCode {
    return switch (err) {
        error.UnknownHostName, error.NoAddressReturned => .name_unresolvable,
        error.Canceled, error.WouldBlock => .temporary_resolver_failure,
        error.ResolvConfParseFailed,
        error.InvalidDnsARecord,
        error.InvalidDnsAAAARecord,
        error.InvalidDnsCnameRecord,
        error.NameServerFailure,
        error.DetectingNetworkConfigurationFailed,
        => .permanent_resolver_failure,
        else => .permanent_resolver_failure,
    };
}

/// Lower a Zig `std.Io.net.IpAddress` into the wasi:sockets
/// `ip-address` variant: `variant { ipv4(tuple<u8 x 4>), ipv6(tuple<u16 x 8>) }`.
/// Caller owns the returned `InterfaceValue` (free via `deinit`).
fn lowerIpAddress(allocator: Allocator, addr: std.Io.net.IpAddress) !InterfaceValue {
    switch (addr) {
        .ip4 => |v4| {
            const bytes = v4.bytes;
            const octets = try allocator.alloc(InterfaceValue, 4);
            errdefer allocator.free(octets);
            inline for (0..4) |i| octets[i] = .{ .u8 = bytes[i] };
            const tup = try allocator.create(InterfaceValue);
            errdefer allocator.destroy(tup);
            tup.* = .{ .tuple_val = octets };
            return .{ .variant_val = .{
                .discriminant = @intFromEnum(IpAddressFamily.ipv4),
                .payload = tup,
            } };
        },
        .ip6 => |v6| {
            const bytes = v6.bytes;
            const groups = try allocator.alloc(InterfaceValue, 8);
            errdefer allocator.free(groups);
            inline for (0..8) |i| {
                const hi: u16 = bytes[i * 2];
                const lo: u16 = bytes[i * 2 + 1];
                groups[i] = .{ .u16 = (hi << 8) | lo };
            }
            const tup = try allocator.create(InterfaceValue);
            errdefer allocator.destroy(tup);
            tup.* = .{ .tuple_val = groups };
            return .{ .variant_val = .{
                .discriminant = @intFromEnum(IpAddressFamily.ipv6),
                .payload = tup,
            } };
        },
    }
}

/// Lift a wasi:sockets `ip-socket-address` variant value into a Zig
/// `std.Io.net.IpAddress`. Validates the variant arm matches `family`
/// (returns `error.FamilyMismatch`); rejects malformed records that
/// don't match the WIT shape (returns `error.InvalidArgs`).
///
/// WIT (0.2.6):
///   record ipv4-socket-address { port: u16, address: tuple<u8,u8,u8,u8> }
///   record ipv6-socket-address { port: u16, flow-info: u32,
///                                 address: tuple<u16,u16,u16,u16,u16,u16,u16,u16>,
///                                 scope-id: u32 }
fn liftIpSocketAddress(
    val: InterfaceValue,
    family: IpAddressFamily,
) error{ InvalidArgs, FamilyMismatch }!std.Io.net.IpAddress {
    const variant = switch (val) {
        .variant_val => |v| v,
        else => return error.InvalidArgs,
    };
    const arm: IpAddressFamily = if (variant.discriminant == 0) .ipv4 else .ipv6;
    if (arm != family) return error.FamilyMismatch;
    const payload = variant.payload orelse return error.InvalidArgs;
    const fields = switch (payload.*) {
        .record_val => |r| r,
        else => return error.InvalidArgs,
    };
    switch (arm) {
        .ipv4 => {
            if (fields.len < 2) return error.InvalidArgs;
            const port: u16 = switch (fields[0]) {
                .u16 => |p| p,
                else => return error.InvalidArgs,
            };
            const addr_tuple = switch (fields[1]) {
                .tuple_val => |t| t,
                else => return error.InvalidArgs,
            };
            if (addr_tuple.len != 4) return error.InvalidArgs;
            var bytes: [4]u8 = undefined;
            inline for (0..4) |i| {
                bytes[i] = switch (addr_tuple[i]) {
                    .u8 => |b| b,
                    else => return error.InvalidArgs,
                };
            }
            return .{ .ip4 = .{ .bytes = bytes, .port = port } };
        },
        .ipv6 => {
            if (fields.len < 4) return error.InvalidArgs;
            const port: u16 = switch (fields[0]) {
                .u16 => |p| p,
                else => return error.InvalidArgs,
            };
            const flow: u32 = switch (fields[1]) {
                .u32 => |f| f,
                else => return error.InvalidArgs,
            };
            const addr_tuple = switch (fields[2]) {
                .tuple_val => |t| t,
                else => return error.InvalidArgs,
            };
            if (addr_tuple.len != 8) return error.InvalidArgs;
            // WIT scope-id is captured but the std type holds it as an
            // Interface (none/index/name). PR A drops the scope id; it
            // will round-trip as 0 in `lowerIpSocketAddress`. The
            // listen/bind paths that PR A exposes don't need scoped
            // addresses.
            _ = fields[3];
            var bytes: [16]u8 = undefined;
            inline for (0..8) |i| {
                const group: u16 = switch (addr_tuple[i]) {
                    .u16 => |g| g,
                    else => return error.InvalidArgs,
                };
                bytes[i * 2] = @intCast((group >> 8) & 0xff);
                bytes[i * 2 + 1] = @intCast(group & 0xff);
            }
            return .{ .ip6 = .{ .port = port, .bytes = bytes, .flow = flow } };
        },
    }
}

/// Lower a `std.Io.net.IpAddress` into a wasi:sockets
/// `ip-socket-address` variant. Caller owns the returned
/// `InterfaceValue` (free via `.deinit(allocator)`).
fn lowerIpSocketAddress(allocator: Allocator, addr: std.Io.net.IpAddress) !InterfaceValue {
    switch (addr) {
        .ip4 => |v4| {
            const octets = try allocator.alloc(InterfaceValue, 4);
            errdefer allocator.free(octets);
            inline for (0..4) |i| octets[i] = .{ .u8 = v4.bytes[i] };
            const fields = try allocator.alloc(InterfaceValue, 2);
            errdefer allocator.free(fields);
            fields[0] = .{ .u16 = v4.port };
            fields[1] = .{ .tuple_val = octets };
            const rec = try allocator.create(InterfaceValue);
            errdefer allocator.destroy(rec);
            rec.* = .{ .record_val = fields };
            return .{ .variant_val = .{
                .discriminant = @intFromEnum(IpAddressFamily.ipv4),
                .payload = rec,
            } };
        },
        .ip6 => |v6| {
            const groups = try allocator.alloc(InterfaceValue, 8);
            errdefer allocator.free(groups);
            inline for (0..8) |i| {
                const hi: u16 = v6.bytes[i * 2];
                const lo: u16 = v6.bytes[i * 2 + 1];
                groups[i] = .{ .u16 = (hi << 8) | lo };
            }
            const fields = try allocator.alloc(InterfaceValue, 4);
            errdefer allocator.free(fields);
            fields[0] = .{ .u16 = v6.port };
            fields[1] = .{ .u32 = v6.flow };
            fields[2] = .{ .tuple_val = groups };
            // PR A elides scope-id (Interface enum doesn't carry an
            // integer index in all variants); always lower as 0.
            fields[3] = .{ .u32 = 0 };
            const rec = try allocator.create(InterfaceValue);
            errdefer allocator.destroy(rec);
            rec.* = .{ .record_val = fields };
            return .{ .variant_val = .{
                .discriminant = @intFromEnum(IpAddressFamily.ipv6),
                .payload = rec,
            } };
        },
    }
}

/// Map an `IpAddress.BindError` to a `wasi:sockets/network.error-code`.
fn mapSocketBindError(err: anyerror) SocketErrorCode {
    return switch (err) {
        error.AddressInUse => .address_in_use,
        error.AddressUnavailable => .address_not_bindable,
        error.AddressFamilyUnsupported => .invalid_argument,
        error.SystemResources, error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded => .new_socket_limit,
        error.NetworkDown => .remote_unreachable,
        error.AccessDenied => .access_denied,
        else => .unknown,
    };
}

/// Open a kernel socket, bind to `address`, and getsockname for the
/// kernel-resolved local address. Wraps the result in the same
/// `std.Io.net.Socket` shape that `IpAddress.bind` returns so existing
/// `close`/`send`/`receive` paths work transparently.
///
/// Two parallel implementations, kept in sync by the unit tests
/// further down:
///   - POSIX (`linux`, `macos`, …): raw `socket(2)` / `setsockopt(2)` /
///     `bind(2)` / `getsockname(2)` syscalls via `std.posix.system`.
///   - Windows: raw `socket` / `setsockopt` / `bind` / `getsockname`
///     calls via the `ws2_32.dll` Winsock 2 API
///     (`bindAndGetsocknameWindows`). Mirrors the POSIX flow so
///     `sockets-tcp-bind::test_reuseaddr` passes when a Windows CI
///     worker eventually runs the p3 suite. (#583 A6)
///
/// The reason for not just calling `std.Io.net.IpAddress.bind` is
/// twofold:
///   1. A per-socket setsockopt phase between socket(2) and bind(2) is
///      required to mirror wasmtime's host-managed bind: we set
///      `SO_REUSEADDR=1` so a host that closed its first socket can
///      immediately rebind to the same kernel-assigned ephemeral port
///      while its accepted-child sockets are still in TIME_WAIT.
///      Required by `sockets-tcp-bind::test_reuseaddr`. SO_REUSEPORT
///      is intentionally NOT set — wasmtime doesn't either, and
///      setting it would let a concurrent active bind succeed, which
///      would in turn break the
///      `sockets-tcp-connect::test_explicit_bind_addrinuse` /
///      `sockets-udp-connect::test_explicit_bind_addrinuse` cases
///      (see wasmtime
///      `crates/wasi/src/sockets/util.rs::tcp_bind`). On Windows,
///      `SO_REUSEADDR` has SO_REUSEPORT-like semantics (it lets a
///      second socket *steal* an actively-bound port), but the host's
///      `bindWouldConflict` already gates active-bind reuse at the
///      adapter layer so the two `test_explicit_bind_addrinuse`
///      fixtures still surface `AddressInUse` correctly.
///   2. Centralising the `getsockname` step ensures the returned
///      `Socket.address` always carries the kernel-resolved ephemeral
///      port — defensive against stdlib drift where some
///      `netBindIp` variants might skip the getsockname refresh.
///
/// Returns a `BindWithReuseError` superset of the stdlib `BindError` —
/// `mapBindWithReuseError` collapses it back to a `SocketErrorCode`
/// without losing the host-specific access-denied / family-mismatch
/// classifications.
fn bindAndGetsockname(
    address: std.Io.net.IpAddress,
    mode: std.Io.net.Socket.Mode,
    protocol: ?std.Io.net.Protocol,
) BindWithReuseError!std.Io.net.Socket {
    const native_os = @import("builtin").os.tag;
    if (native_os == .windows) {
        return bindAndGetsocknameWindows(address, mode, protocol);
    }
    // POSIX path — raw syscalls so we can interleave setsockopt
    // between socket(2) and bind(2).
    const fam: std.posix.sa_family_t = switch (address) {
        .ip4 => std.posix.AF.INET,
        .ip6 => std.posix.AF.INET6,
    };
    const sock_type: u32 = switch (mode) {
        .stream => std.posix.SOCK.STREAM,
        .dgram => std.posix.SOCK.DGRAM,
        else => return error.SocketModeUnsupported,
    };
    const proto: u32 = if (protocol) |p| switch (p) {
        .tcp => std.posix.IPPROTO.TCP,
        .udp => std.posix.IPPROTO.UDP,
        else => 0,
    } else 0;
    // On Darwin (and Haiku) `SOCK.CLOEXEC` is a Zig-supplied shim — not a real
    // BSD kernel flag — so it must NOT be OR'd into the raw `socket(2)` type
    // argument or the kernel rejects it with EINVAL. Instead, do a bare
    // `socket(2)` and apply FD_CLOEXEC via `fcntl(F_SETFD, …)` afterwards.
    // This mirrors `std.Io.Threaded.openSocketPosix` (Threaded.zig:12243).
    const socket_flags_unsupported = switch (native_os) {
        .macos, .ios, .tvos, .watchos, .visionos, .driverkit, .maccatalyst, .haiku => true,
        else => false,
    };
    const flags: u32 = sock_type | if (socket_flags_unsupported) 0 else std.posix.SOCK.CLOEXEC;
    const sock_rc = std.posix.system.socket(fam, flags, proto);
    switch (std.posix.errno(sock_rc)) {
        .SUCCESS => {},
        .ACCES => return error.AccessDenied,
        .AFNOSUPPORT => return error.AddressFamilyUnsupported,
        .MFILE => return error.ProcessFdQuotaExceeded,
        .NFILE => return error.SystemFdQuotaExceeded,
        .NOBUFS, .NOMEM => return error.SystemResources,
        .PROTONOSUPPORT => return error.ProtocolUnsupportedBySystem,
        .INVAL => return error.ProtocolUnsupportedBySystem,
        else => return error.SystemResources,
    }
    const fd: std.posix.fd_t = @intCast(sock_rc);
    errdefer _ = std.posix.system.close(fd);

    if (socket_flags_unsupported) {
        while (true) switch (std.posix.errno(std.posix.system.fcntl(
            fd,
            std.posix.F.SETFD,
            @as(usize, std.posix.FD_CLOEXEC),
        ))) {
            .SUCCESS => break,
            .INTR => continue,
            else => return error.SystemResources,
        };
    }

    // SO_REUSEADDR is required by `sockets-tcp-bind::test_reuseaddr`
    // (around line 231 of the upstream fixture): the fixture binds to
    // an ephemeral port, drops the server (which had an established
    // accepted child), and immediately rebinds a fresh socket on the
    // same port. The accepted child sits in TIME_WAIT for ~60 s on
    // Linux, so without SO_REUSEADDR the rebind returns EADDRINUSE.
    // Linux's SO_REUSEADDR still refuses to bind on top of an
    // *actively-bound* port — neither socket in
    // `sockets-tcp-connect::test_explicit_bind_addrinuse` /
    // `sockets-udp-connect::test_explicit_bind_addrinuse` has been
    // dropped at that point, so those tests continue to surface
    // `AddressInUse` correctly even with REUSEADDR set on both fds
    // (because the active-bind path is unaffected by SO_REUSEADDR;
    // it's the TIME_WAIT / closed-fd path that REUSEADDR governs).
    // The `ComponentInstance.on_resource_drop` hook installed by
    // `runLoadedComponent` (also #575) ensures the host fd of the
    // first bind is released synchronously on guest drop so the
    // active-bind precondition for `test_explicit_bind_addrinuse`
    // remains intact: only the brief kernel TIME_WAIT window — which
    // REUSEADDR exists to bypass — is in play for `test_reuseaddr`.
    // Matches wasmtime's `crates/wasi/src/sockets/util.rs::tcp_bind`,
    // which sets SO_REUSEADDR unconditionally on POSIX. SO_REUSEPORT
    // is NOT set (wasmtime doesn't either, and it would let a
    // concurrent active bind succeed). (#575)
    _ = socketSetU32Opt(fd, SOL_SOCKET_OPT, SO_REUSEADDR_OPT, 1);

    // Build the sockaddr storage and call bind(2).
    var storage: std.posix.sockaddr.storage = std.mem.zeroes(std.posix.sockaddr.storage);
    var addr_len: std.posix.socklen_t = 0;
    switch (address) {
        .ip4 => |v4| {
            const sa_in: *std.posix.sockaddr.in = @ptrCast(@alignCast(&storage));
            sa_in.* = .{
                .family = std.posix.AF.INET,
                .port = std.mem.nativeToBig(u16, v4.port),
                .addr = @bitCast(v4.bytes),
                .zero = [_]u8{0} ** 8,
            };
            addr_len = @sizeOf(std.posix.sockaddr.in);
        },
        .ip6 => |v6| {
            const sa_in6: *std.posix.sockaddr.in6 = @ptrCast(@alignCast(&storage));
            sa_in6.* = .{
                .family = std.posix.AF.INET6,
                .port = std.mem.nativeToBig(u16, v6.port),
                .flowinfo = v6.flow,
                .addr = v6.bytes,
                .scope_id = 0,
            };
            addr_len = @sizeOf(std.posix.sockaddr.in6);
        },
    }
    const bind_rc = std.posix.system.bind(fd, @ptrCast(&storage), addr_len);
    switch (std.posix.errno(bind_rc)) {
        .SUCCESS => {},
        .ACCES => return error.AccessDenied,
        .ADDRINUSE => return error.AddressInUse,
        .ADDRNOTAVAIL => return error.AddressUnavailable,
        .AFNOSUPPORT => return error.AddressFamilyUnsupported,
        .NOBUFS, .NOMEM => return error.SystemResources,
        else => return error.SystemResources,
    }

    // getsockname → resolve ephemeral port.
    var got_storage: std.posix.sockaddr.storage = std.mem.zeroes(std.posix.sockaddr.storage);
    var got_len: std.posix.socklen_t = @sizeOf(std.posix.sockaddr.storage);
    const gs_rc = std.posix.system.getsockname(fd, @ptrCast(&got_storage), &got_len);
    if (std.posix.errno(gs_rc) != .SUCCESS) return error.SystemResources;

    const local: std.Io.net.IpAddress = switch (address) {
        .ip4 => blk: {
            const sa: *const std.posix.sockaddr.in = @ptrCast(@alignCast(&got_storage));
            break :blk .{ .ip4 = .{
                .bytes = @bitCast(sa.addr),
                .port = std.mem.bigToNative(u16, sa.port),
            } };
        },
        .ip6 => blk: {
            const sa: *const std.posix.sockaddr.in6 = @ptrCast(@alignCast(&got_storage));
            break :blk .{ .ip6 = .{
                .bytes = sa.addr,
                .port = std.mem.bigToNative(u16, sa.port),
                .flow = sa.flowinfo,
            } };
        },
    };
    return .{ .handle = fd, .address = local };
}

// ── Windows direct-Winsock externs (#583 A6) ────────────────────────
//
// `std.os.windows.ws2_32` in Zig 0.16.0 is a *types-and-constants*
// namespace — it intentionally exposes none of the actual `ws2_32.dll`
// procedure exports (`socket`, `bind`, `setsockopt`, `getsockname`,
// `closesocket`, `WSAStartup`, `WSAGetLastError`) because the stdlib
// `std.Io.Threaded` Windows socket backend bypasses Winsock entirely
// and talks to the AFD endpoint (\Device\Afd\Endpoint) via
// `NtCreateFile`/`NtDeviceIoControlFile`. That AFD path doesn't
// permit interleaving a `SO_REUSEADDR` `setsockopt` between socket
// creation and bind in the way `bindAndGetsockname` needs.
//
// We therefore declare the small set of Winsock 2 entry points we
// need here as private externs against `ws2_32.dll`. The set mirrors
// what wasmtime's `crates/wasi/src/sockets/util.rs::tcp_bind` reaches
// for on Windows (`socket2::Socket::new` + `set_reuse_address` +
// `bind` + `local_addr`).
//
// Calling these without a prior `WSAStartup` returns `WSANOTINITIALISED`
// (10093). `ensureWsaStartup` is a refcount-leaking idempotent
// initialiser — repeat calls are documented as safe by MSDN. We never
// call `WSACleanup` because the kernel reclaims the per-process
// Winsock state at process exit anyway.
const ws2_32_extern = struct {
    pub const SOCKET = usize;
    pub const INVALID_SOCKET: SOCKET = ~@as(usize, 0);
    pub const SOCKET_ERROR: c_int = -1;

    extern "ws2_32" fn WSAStartup(
        wVersionRequested: u16,
        lpWSAData: *anyopaque,
    ) callconv(.winapi) c_int;
    extern "ws2_32" fn WSAGetLastError() callconv(.winapi) c_int;
    extern "ws2_32" fn socket(
        af: c_int,
        type_: c_int,
        protocol: c_int,
    ) callconv(.winapi) SOCKET;
    extern "ws2_32" fn closesocket(s: SOCKET) callconv(.winapi) c_int;
    extern "ws2_32" fn bind(
        s: SOCKET,
        name: *const anyopaque,
        namelen: c_int,
    ) callconv(.winapi) c_int;
    extern "ws2_32" fn setsockopt(
        s: SOCKET,
        level: c_int,
        optname: c_int,
        optval: [*]const u8,
        optlen: c_int,
    ) callconv(.winapi) c_int;
    extern "ws2_32" fn getsockname(
        s: SOCKET,
        name: *anyopaque,
        namelen: *c_int,
    ) callconv(.winapi) c_int;
};

/// Selected `WSAGetLastError` codes that `bindAndGetsocknameWindows`
/// classifies. Numbered per MSDN; not exhaustive — anything else
/// collapses to `error.SystemResources` and is then mapped to
/// `unknown` by `mapSocketBindError`.
const WSAE = struct {
    pub const INTR: c_int = 10004;
    pub const ACCES: c_int = 10013;
    pub const FAULT: c_int = 10014;
    pub const INVAL: c_int = 10022;
    pub const MFILE: c_int = 10024;
    pub const NOBUFS: c_int = 10055;
    pub const ADDRINUSE: c_int = 10048;
    pub const ADDRNOTAVAIL: c_int = 10049;
    pub const AFNOSUPPORT: c_int = 10047;
    pub const SOCKTNOSUPPORT: c_int = 10044;
    pub const PROTONOSUPPORT: c_int = 10043;
};

/// Idempotent `WSAStartup(2.2)`. Safe to call concurrently — MSDN
/// guarantees repeated `WSAStartup` calls increment an internal
/// refcount and return immediately on subsequent calls. We never
/// pair them with `WSACleanup`; per-process Winsock state is
/// reclaimed at process exit.
var wsa_started: std.atomic.Value(u32) = .init(0);
fn ensureWsaStartup() void {
    if (wsa_started.load(.acquire) != 0) return;
    // `WSADATA` is 408 bytes on x86_64 (LPWSADATA in the SDK). The
    // 512-byte stack buffer is a deliberate over-allocation — we
    // never read the fields.
    var data: [512]u8 = undefined;
    _ = ws2_32_extern.WSAStartup(0x0202, @ptrCast(&data));
    wsa_started.store(1, .release);
}

/// Windows arm of `bindAndGetsockname`. Mirrors the POSIX flow via
/// direct `ws2_32.dll` calls so a `SO_REUSEADDR` `setsockopt` can be
/// interleaved between socket creation and `bind`. The returned
/// `std.Io.net.Socket.Handle` is the raw Winsock `SOCKET` cast to
/// `windows.HANDLE` (`?*anyopaque`) — `Socket.close` on the
/// `Threaded` backend forwards it to `CloseHandle`, which Windows
/// documents as a valid close for SOCKET handles (it delegates to
/// the kernel-mode AFD driver under the hood). (#583 A6)
fn bindAndGetsocknameWindows(
    address: std.Io.net.IpAddress,
    mode: std.Io.net.Socket.Mode,
    protocol: ?std.Io.net.Protocol,
) BindWithReuseError!std.Io.net.Socket {
    const windows = std.os.windows;
    const ws2_32 = windows.ws2_32;

    ensureWsaStartup();

    const family: c_int = switch (address) {
        .ip4 => ws2_32.AF.INET,
        .ip6 => ws2_32.AF.INET6,
    };
    const sock_type: c_int = switch (mode) {
        .stream => ws2_32.SOCK.STREAM,
        .dgram => ws2_32.SOCK.DGRAM,
        else => return error.SocketModeUnsupported,
    };
    const proto: c_int = if (protocol) |p| switch (p) {
        .tcp => ws2_32.IPPROTO.TCP,
        .udp => ws2_32.IPPROTO.UDP,
        else => 0,
    } else 0;

    const sock = ws2_32_extern.socket(family, sock_type, proto);
    if (sock == ws2_32_extern.INVALID_SOCKET) {
        return switch (ws2_32_extern.WSAGetLastError()) {
            WSAE.ACCES => error.AccessDenied,
            WSAE.AFNOSUPPORT => error.AddressFamilyUnsupported,
            WSAE.MFILE => error.ProcessFdQuotaExceeded,
            WSAE.NOBUFS => error.SystemResources,
            WSAE.PROTONOSUPPORT,
            WSAE.SOCKTNOSUPPORT,
            WSAE.INVAL,
            => error.ProtocolUnsupportedBySystem,
            else => error.SystemResources,
        };
    }
    errdefer _ = ws2_32_extern.closesocket(sock);

    // SO_REUSEADDR — required by `sockets-tcp-bind::test_reuseaddr`
    // (see `bindAndGetsockname` doc comment). Winsock semantics
    // differ from POSIX (it permits a *second* active bind to steal
    // the port), but the host's `bindWouldConflict` gate filters
    // those cases at the adapter layer, so the TIME_WAIT-rebind case
    // remains the one this option enables. Mirrors wasmtime's POSIX
    // `set_reuse_address(true)` call.
    const one: u32 = 1;
    const one_bytes = std.mem.toBytes(one);
    _ = ws2_32_extern.setsockopt(
        sock,
        ws2_32.SOL.SOCKET,
        ws2_32.SO.REUSEADDR,
        &one_bytes,
        @sizeOf(u32),
    );

    // Build the Winsock sockaddr_in / sockaddr_in6 and call bind.
    var storage: ws2_32.sockaddr.storage = std.mem.zeroes(ws2_32.sockaddr.storage);
    var addr_len: c_int = 0;
    switch (address) {
        .ip4 => |v4| {
            const sa_in: *ws2_32.sockaddr.in = @ptrCast(@alignCast(&storage));
            sa_in.* = .{
                .family = ws2_32.AF.INET,
                .port = std.mem.nativeToBig(u16, v4.port),
                .addr = @bitCast(v4.bytes),
            };
            addr_len = @sizeOf(ws2_32.sockaddr.in);
        },
        .ip6 => |v6| {
            const sa_in6: *ws2_32.sockaddr.in6 = @ptrCast(@alignCast(&storage));
            sa_in6.* = .{
                .family = ws2_32.AF.INET6,
                .port = std.mem.nativeToBig(u16, v6.port),
                .flowinfo = v6.flow,
                .addr = v6.bytes,
                .scope_id = 0,
            };
            addr_len = @sizeOf(ws2_32.sockaddr.in6);
        },
    }
    if (ws2_32_extern.bind(sock, @ptrCast(&storage), addr_len) == ws2_32_extern.SOCKET_ERROR) {
        return switch (ws2_32_extern.WSAGetLastError()) {
            WSAE.ACCES => error.AccessDenied,
            WSAE.ADDRINUSE => error.AddressInUse,
            WSAE.ADDRNOTAVAIL => error.AddressUnavailable,
            WSAE.AFNOSUPPORT => error.AddressFamilyUnsupported,
            WSAE.NOBUFS => error.SystemResources,
            WSAE.INVAL => error.AddressInUse,
            else => error.SystemResources,
        };
    }

    // getsockname — resolve the kernel-assigned ephemeral port for
    // the port-0 case (and confirm the bind for the explicit-port
    // case).
    var got_storage: ws2_32.sockaddr.storage = std.mem.zeroes(ws2_32.sockaddr.storage);
    var got_len: c_int = @sizeOf(ws2_32.sockaddr.storage);
    if (ws2_32_extern.getsockname(sock, @ptrCast(&got_storage), &got_len) == ws2_32_extern.SOCKET_ERROR) {
        return error.SystemResources;
    }

    const local: std.Io.net.IpAddress = switch (address) {
        .ip4 => blk: {
            const sa: *const ws2_32.sockaddr.in = @ptrCast(@alignCast(&got_storage));
            break :blk .{ .ip4 = .{
                .bytes = @bitCast(sa.addr),
                .port = std.mem.bigToNative(u16, sa.port),
            } };
        },
        .ip6 => blk: {
            const sa: *const ws2_32.sockaddr.in6 = @ptrCast(@alignCast(&got_storage));
            break :blk .{ .ip6 = .{
                .bytes = sa.addr,
                .port = std.mem.bigToNative(u16, sa.port),
                .flow = sa.flowinfo,
            } };
        },
    };

    // Cast the Winsock SOCKET (an opaque integer) to the
    // `std.posix.fd_t` shape Zig uses for socket handles on Windows
    // (`windows.HANDLE` = `?*anyopaque`). `Socket.close` →
    // `Threaded.netClose` → `windows.CloseHandle` correctly disposes
    // of the underlying AFD endpoint.
    const fd: std.Io.net.Socket.Handle = @ptrFromInt(sock);
    return .{ .handle = fd, .address = local };
}

/// Superset of `std.Io.net.IpAddress.BindError` carried through
/// `bindAndGetsockname` — adds `AccessDenied` (returned by socket(2)
/// EACCES on some POSIX systems) which the stdlib bind path lifts to
/// `error.Unexpected`. `mapSocketBindError` knows how to route
/// either.
const BindWithReuseError = std.Io.net.IpAddress.BindError || error{AccessDenied};

/// Build a raw POSIX `sockaddr_storage` from a Zig
/// `std.Io.net.IpAddress`. Returns the storage by value plus the
/// effective length (`sa_family_t` + family-specific tail) so the
/// caller can pass either to `bind(2)`, `connect(2)`, or
/// `getsockname(2)`. (#569)
fn ipAddressToPosixStorage(
    address: std.Io.net.IpAddress,
) struct { storage: std.posix.sockaddr.storage, len: std.posix.socklen_t } {
    var storage: std.posix.sockaddr.storage = std.mem.zeroes(std.posix.sockaddr.storage);
    var addr_len: std.posix.socklen_t = 0;
    switch (address) {
        .ip4 => |v4| {
            const sa_in: *std.posix.sockaddr.in = @ptrCast(@alignCast(&storage));
            sa_in.* = .{
                .family = std.posix.AF.INET,
                .port = std.mem.nativeToBig(u16, v4.port),
                .addr = @bitCast(v4.bytes),
                .zero = [_]u8{0} ** 8,
            };
            addr_len = @sizeOf(std.posix.sockaddr.in);
        },
        .ip6 => |v6| {
            const sa_in6: *std.posix.sockaddr.in6 = @ptrCast(@alignCast(&storage));
            sa_in6.* = .{
                .family = std.posix.AF.INET6,
                .port = std.mem.nativeToBig(u16, v6.port),
                .flowinfo = v6.flow,
                .addr = v6.bytes,
                .scope_id = 0,
            };
            addr_len = @sizeOf(std.posix.sockaddr.in6);
        },
    }
    return .{ .storage = storage, .len = addr_len };
}

/// Call `connect(2)` on a kernel UDP fd so the kernel records the
/// remote address and (for wildcard-bound sockets) refines the
/// outbound interface IP. Returns the same error set as
/// `std.Io.net.IpAddress.ConnectError` so callers can pipe straight
/// into `mapConnectError`. POSIX-only; Windows callers should skip
/// this path. (#569)
fn connectUdpKernel(
    fd: std.posix.fd_t,
    remote: std.Io.net.IpAddress,
) std.Io.net.IpAddress.ConnectError!void {
    const built = ipAddressToPosixStorage(remote);
    const rc = std.posix.system.connect(fd, @ptrCast(&built.storage), built.len);
    switch (std.posix.errno(rc)) {
        .SUCCESS => return,
        .ACCES, .PERM => return error.AccessDenied,
        .ADDRINUSE => return error.AddressUnavailable,
        .ADDRNOTAVAIL => return error.AddressUnavailable,
        .AFNOSUPPORT => return error.AddressFamilyUnsupported,
        .CONNREFUSED => return error.ConnectionRefused,
        .NETUNREACH, .NETDOWN => return error.NetworkUnreachable,
        .HOSTUNREACH => return error.HostUnreachable,
        .TIMEDOUT => return error.Timeout,
        .NOBUFS, .NOMEM => return error.SystemResources,
        else => return error.Unexpected,
    }
}

/// Call `getsockname(2)` on a kernel socket fd and return the
/// resolved `std.Io.net.IpAddress`. Returns `null` if the syscall
/// fails or the returned family doesn't match `expected_family` (a
/// belt-and-braces guard against a kernel returning AF_UNSPEC after
/// connect-then-disconnect). POSIX-only. (#569)
fn getsocknameKernel(
    fd: std.posix.fd_t,
    expected_family: IpAddressFamily,
) ?std.Io.net.IpAddress {
    var got_storage: std.posix.sockaddr.storage = std.mem.zeroes(std.posix.sockaddr.storage);
    var got_len: std.posix.socklen_t = @sizeOf(std.posix.sockaddr.storage);
    const rc = std.posix.system.getsockname(fd, @ptrCast(&got_storage), &got_len);
    if (std.posix.errno(rc) != .SUCCESS) return null;
    return switch (expected_family) {
        .ipv4 => blk: {
            const sa: *const std.posix.sockaddr.in = @ptrCast(@alignCast(&got_storage));
            if (sa.family != std.posix.AF.INET) break :blk null;
            break :blk .{ .ip4 = .{
                .bytes = @bitCast(sa.addr),
                .port = std.mem.bigToNative(u16, sa.port),
            } };
        },
        .ipv6 => blk: {
            const sa: *const std.posix.sockaddr.in6 = @ptrCast(@alignCast(&got_storage));
            if (sa.family != std.posix.AF.INET6) break :blk null;
            break :blk .{ .ip6 = .{
                .bytes = sa.addr,
                .port = std.mem.bigToNative(u16, sa.port),
                .flow = sa.flowinfo,
            } };
        },
    };
}

/// Map an `IpAddress.ListenError` to a `wasi:sockets/network.error-code`.
fn mapSocketListenError(err: anyerror) SocketErrorCode {
    return switch (err) {
        error.AddressInUse => .address_in_use,
        error.AddressUnavailable => .address_not_bindable,
        error.AddressFamilyUnsupported => .invalid_argument,
        error.SystemResources, error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded => .new_socket_limit,
        error.NetworkDown => .remote_unreachable,
        error.AccessDenied => .access_denied,
        else => .unknown,
    };
}

/// Map an `IpAddress.ConnectError` to a `wasi:sockets/network.error-code`.
fn mapConnectError(err: anyerror) SocketErrorCode {
    return switch (err) {
        error.ConnectionRefused => .connection_refused,
        error.ConnectionResetByPeer => .connection_reset,
        error.NetworkUnreachable, error.NetworkDown => .remote_unreachable,
        error.HostUnreachable => .remote_unreachable,
        error.Timeout => .timeout,
        error.AddressInUse => .address_in_use,
        error.AddressUnavailable => .address_not_bindable,
        error.AddressFamilyUnsupported => .invalid_argument,
        error.SystemResources, error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded => .new_socket_limit,
        error.AccessDenied => .access_denied,
        else => .unknown,
    };
}

/// Map a `Socket.SendError` to a `wasi:sockets/network.error-code`.
fn mapSocketSendError(err: anyerror) SocketErrorCode {
    return switch (err) {
        error.MessageOversize => .datagram_too_large,
        error.NetworkUnreachable, error.NetworkDown => .remote_unreachable,
        error.HostUnreachable => .remote_unreachable,
        error.ConnectionRefused => .connection_refused,
        error.ConnectionResetByPeer => .connection_reset,
        error.AccessDenied => .access_denied,
        error.AddressFamilyUnsupported => .invalid_argument,
        error.SystemResources => .out_of_memory,
        else => .unknown,
    };
}

/// Send one UDP datagram while respecting whether the kernel socket has
/// already been connected by `udpConnectP3`.
///
/// Root cause (#917): Darwin (BSD sockets) rejects `sendmsg` with
/// `msg_name != null` on a *connected* UDP socket with `EISCONN`,
/// whereas Linux silently accepts and ignores the redundant
/// destination. `Socket.send` is the connectionless API and always
/// fills `msg_name`, so on a kernel-connected socket the `Socket.send`
/// on `test_connected_*` fixtures traps on macOS. When the socket has
/// been `connect(2)`-ed we instead emit one destination-free `sendmsg`
/// via the connected write path (`netWrite`), which is exactly the
/// POSIX-correct way to send on a connected socket.
///
/// The workaround is gated to Darwin on purpose (justified
/// `builtin.os.tag` conditional): the connectionless `Socket.send`
/// path maps `EMSGSIZE` to `error.MessageOversize` (→ `datagram_too_large`),
/// but std's `netWrite` maps the same errno to `errnoBug` (a panic in
/// Debug / `error.Unexpected` in ReleaseSafe), so routing Linux — the
/// platform whose UDP fixtures already pass — through `netWrite` would
/// lose that error mapping for no benefit, since Linux does not raise
/// `EISCONN` here. Keeping Linux on the untouched, passing path avoids
/// any regression. Non-Darwin (Linux, Windows) therefore keeps using
/// the connectionless send.
fn sendUdpDatagram(
    socket: *const std.Io.net.Socket,
    io: std.Io,
    dest: *const std.Io.net.IpAddress,
    kernel_connected: bool,
    data: []const u8,
) anyerror!void {
    if (builtin.os.tag.isDarwin() and kernel_connected) {
        // A zero-length datagram is valid (`send([])`): `netWrite`
        // issues a `sendmsg` with an empty iovec and returns 0, which
        // equals `data.len`, so the length check below still passes.
        const chunks = [_][]const u8{data};
        const sent = try io.vtable.netWrite(io.userdata, socket.handle, &.{}, &chunks, 1);
        // Datagram sends are atomic: a success returns the whole
        // payload length. A short count should not happen for
        // SOCK_DGRAM, but if it ever did the datagram was truncated,
        // which is `datagram_too_large` semantics.
        if (sent != data.len) return error.MessageOversize;
        return;
    }
    try socket.send(io, dest, data);
}

/// Read a u32-valued socket option via `getsockopt(2)`. Returns the
/// kernel value on success, or `null` on error / unsupported platform.
fn socketGetU32Opt(fd: std.posix.fd_t, level: i32, optname: u32) ?u32 {
    const native_os = @import("builtin").os.tag;
    var val: u32 = 0;
    var optlen: std.posix.socklen_t = @sizeOf(u32);
    if (native_os == .linux) {
        const rc = std.os.linux.getsockopt(
            @intCast(fd),
            level,
            optname,
            @ptrCast(std.mem.asBytes(&val)),
            &optlen,
        );
        if (std.posix.errno(rc) != .SUCCESS) return null;
    } else if (native_os == .windows) {
        const windows = std.os.windows;
        if (level == SOL_SOCKET_OPT and (optname == SO_RCVBUF_OPT or optname == SO_SNDBUF_OPT)) {
            // Buffer sizes use AFD GET_INFORMATION with window-size info types
            var info = windows.AFD.INFORMATION{
                .InformationType = if (optname == SO_RCVBUF_OPT) .RECEIVE_WINDOW_SIZE else .SEND_WINDOW_SIZE,
                .Information = .{ .Ulong = 0 },
            };
            var iosb: windows.IO_STATUS_BLOCK = undefined;
            const status = windows.ntdll.NtDeviceIoControlFile(
                fd,
                null,
                null,
                null,
                &iosb,
                windows.IOCTL.AFD.GET_INFORMATION,
                @ptrCast(&info),
                @sizeOf(windows.AFD.INFORMATION),
                @ptrCast(&info),
                @sizeOf(windows.AFD.INFORMATION),
            );
            if (status == .PENDING) {
                _ = windows.ntdll.NtWaitForSingleObject(fd, .FALSE, null);
                if (iosb.u.Status != .SUCCESS) return null;
            } else if (status != .SUCCESS) {
                return null;
            }
            return info.Information.Ulong;
        }
        var info = windows.AFD.SOCKOPT_INFO{
            .mode = .get,
            .level = level,
            .optname = optname,
            .optval = @ptrCast(std.mem.asBytes(&val)),
            .optlen = @sizeOf(u32),
        };
        var iosb: windows.IO_STATUS_BLOCK = undefined;
        const status = windows.ntdll.NtDeviceIoControlFile(
            fd,
            null,
            null,
            null,
            &iosb,
            windows.IOCTL.AFD.SOCKOPT,
            @ptrCast(&info),
            @sizeOf(windows.AFD.SOCKOPT_INFO),
            @ptrCast(std.mem.asBytes(&val)),
            @sizeOf(u32),
        );
        if (status == .PENDING) {
            _ = windows.ntdll.NtWaitForSingleObject(fd, .FALSE, null);
            if (iosb.u.Status != .SUCCESS) return null;
        } else if (status != .SUCCESS) {
            return null;
        }
    } else {
        // macOS / other POSIX — use libc
        const rc = std.c.getsockopt(
            fd,
            level,
            optname,
            @ptrCast(&val),
            &optlen,
        );
        if (rc != 0) return null;
    }
    return val;
}

/// TCP keep-alive idle time socket option. macOS uses `TCP_KEEPALIVE`
/// (0x10) instead of Linux's `TCP_KEEPIDLE`.
const TCP_KEEPIDLE_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x10, // TCP_KEEPALIVE
    .linux => 4,
    .windows => 3, // TCP_KEEPALIVE (same function as Linux TCP_KEEPIDLE)
    else => 4,
};

/// IP-level socket option constants, defined portably since
/// `std.posix.IP`/`std.posix.IPV6` may be void on some platforms.
const IP_TTL_OPT: u32 = switch (@import("builtin").os.tag) {
    .linux => 2,
    .macos, .ios, .tvos, .watchos => 4,
    .windows => 4,
    else => 2,
};
const IPV6_UNICAST_HOPS_OPT: u32 = switch (@import("builtin").os.tag) {
    .linux => 16,
    .macos, .ios, .tvos, .watchos => 4,
    .windows => 4,
    else => 16,
};
const IPPROTO_IP_OPT: i32 = 0;
const IPPROTO_IPV6_OPT: i32 = 41;
const IPPROTO_TCP_OPT: i32 = 6;
const SOL_SOCKET_OPT: i32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0xffff,
    .windows => 0xffff,
    else => 1, // Linux
};
const SO_RCVBUF_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x1002,
    .windows => 0x1002,
    else => 8, // Linux
};
const SO_SNDBUF_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x1001,
    .windows => 0x1001,
    else => 7, // Linux
};
const SO_KEEPALIVE_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x0008,
    .windows => 0x0008,
    else => 9, // Linux
};
/// SO_REUSEADDR — set unconditionally on POSIX between `socket(2)` and
/// `bind(2)` by `bindAndGetsockname` so that an immediate rebind to a
/// TIME_WAIT port succeeds (required by
/// `sockets-tcp-bind::test_reuseaddr`). Matches wasmtime's
/// `crates/wasi/src/sockets/util.rs::tcp_bind`. (#575)
const SO_REUSEADDR_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x0004,
    .windows => 0x0004,
    else => 2, // Linux
};
const TCP_KEEPINTVL_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x101,
    .windows => 17,
    else => 5, // Linux
};
const TCP_KEEPCNT_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x102,
    .windows => 16,
    else => 6, // Linux
};

/// Set a u32-valued socket option via `setsockopt(2)`. Returns `null`
/// on success, or an error code on failure.
fn socketSetU32Opt(fd: std.posix.fd_t, level: i32, optname: u32, value: u32) ?SocketErrorCode {
    const native_os = @import("builtin").os.tag;
    const bytes = std.mem.toBytes(value);
    if (native_os == .windows) {
        const windows = std.os.windows;
        var iosb: windows.IO_STATUS_BLOCK = undefined;
        if (level == SOL_SOCKET_OPT and (optname == SO_RCVBUF_OPT or optname == SO_SNDBUF_OPT)) {
            // Buffer sizes use AFD SET_INFORMATION with window-size info types
            const status = windows.ntdll.NtDeviceIoControlFile(
                fd,
                null,
                null,
                null,
                &iosb,
                windows.IOCTL.AFD.SET_INFORMATION,
                @ptrCast(&windows.AFD.INFORMATION{
                    .InformationType = if (optname == SO_RCVBUF_OPT) .RECEIVE_WINDOW_SIZE else .SEND_WINDOW_SIZE,
                    .Information = .{ .Ulong = value },
                }),
                @sizeOf(windows.AFD.INFORMATION),
                null,
                0,
            );
            if (status == .PENDING) {
                _ = windows.ntdll.NtWaitForSingleObject(fd, .FALSE, null);
                if (iosb.u.Status != .SUCCESS) return .unknown;
            } else if (status != .SUCCESS) {
                return .unknown;
            }
            return null;
        }
        const status = windows.ntdll.NtDeviceIoControlFile(
            fd,
            null,
            null,
            null,
            &iosb,
            windows.IOCTL.AFD.SOCKOPT,
            @ptrCast(&windows.AFD.SOCKOPT_INFO{
                .mode = .set,
                .level = level,
                .optname = optname,
                .optval = @ptrCast(&bytes),
                .optlen = @sizeOf(u32),
            }),
            @sizeOf(windows.AFD.SOCKOPT_INFO),
            null,
            0,
        );
        if (status == .PENDING) {
            _ = windows.ntdll.NtWaitForSingleObject(fd, .FALSE, null);
            if (iosb.u.Status != .SUCCESS) return .unknown;
        } else if (status != .SUCCESS) {
            return .unknown;
        }
        return null;
    } else if (native_os == .linux) {
        const rc = std.os.linux.setsockopt(
            @intCast(fd),
            level,
            optname,
            @ptrCast(&bytes),
            @sizeOf(u32),
        );
        if (std.posix.errno(rc) != .SUCCESS) return .unknown;
        return null;
    } else {
        // macOS / other POSIX — use std.posix.setsockopt
        std.posix.setsockopt(fd, level, optname, &bytes) catch return .unknown;
        return null;
    }
}

/// Deep-copy a CIDR allow-list slice so the socket owns its own copy
/// (prevents UAF when the network resource is dropped first).
fn cloneAllowList(allocator: Allocator, src: []const IpCidr) ![]IpCidr {
    if (src.len == 0) return &.{};
    const dst = try allocator.alloc(IpCidr, src.len);
    @memcpy(dst, src);
    return dst;
}

/// Validate that `addr` is suitable as a send destination for the
/// given socket `family`. Returns `null` if valid, or the WIT
/// `error-code` discriminant to return on failure.
///
/// Checks (in WIT-mandated order):
///  1. family mismatch → `invalid-argument`
///  2. wildcard IP (0.0.0.0 / ::) → `invalid-argument`
///  3. port == 0 → `invalid-argument`
fn validateRemoteForSend(addr: std.Io.net.IpAddress, family: IpAddressFamily) ?SocketErrorCode {
    switch (addr) {
        .ip4 => |v4| {
            if (family != .ipv4) return .invalid_argument;
            if (std.mem.eql(u8, &v4.bytes, &.{ 0, 0, 0, 0 })) return .invalid_argument;
            if (v4.port == 0) return .invalid_argument;
        },
        .ip6 => |v6| {
            if (family != .ipv6) return .invalid_argument;
            if (std.mem.eql(u8, &v6.bytes, &(.{0} ** 16))) return .invalid_argument;
            if (v6.port == 0) return .invalid_argument;
        },
    }
    return null;
}

/// Map a Zig std.fs / std.posix error to the closest `error-code` variant.
/// Errors not represented map to `.io` so the guest still sees a
/// well-typed result rather than a host trap.
fn mapFsError(err: anyerror) FsErrorCode {
    return switch (err) {
        error.AccessDenied, error.PermissionDenied => .access,
        error.FileNotFound => .no_entry,
        error.NotDir => .not_directory,
        error.PathAlreadyExists => .exist,
        error.IsDir => .is_directory,
        error.NameTooLong => .name_too_long,
        error.SymLinkLoop => .loop,
        error.FileTooBig => .file_too_large,
        error.NoSpaceLeft => .insufficient_space,
        error.OutOfMemory => .insufficient_memory,
        error.DeviceBusy, error.FileBusy => .busy,
        error.WouldBlock => .would_block,
        error.BrokenPipe => .pipe,
        error.ReadOnlyFileSystem => .read_only,
        error.InvalidUtf8 => .illegal_byte_sequence,
        // #476: directory-mutation surface needs cross-device, not-empty,
        // unsupported-op, link-quota, disk-quota, and not-symlink mappings.
        error.CrossDevice => .cross_device,
        error.DirNotEmpty => .not_empty,
        error.OperationUnsupported => .unsupported,
        error.LinkQuotaExceeded => .too_many_links,
        error.DiskQuota => .quota,
        error.NotLink => .invalid,
        else => .io,
    };
}

/// `wasi:http/types.error-code` discriminant indices in WIT-declaration
/// order. Used as `.variant_val.discriminant` for `result<_, error-code>`
/// returns. Several variants carry payloads in the WIT (option<u64>,
/// option<string>, etc.); the adapter only ever returns no-payload
/// codes from default-deny stubs, so payload handling is deferred.
const HttpErrorCode = enum(u32) {
    DNS_timeout = 0,
    DNS_error = 1,
    destination_not_found = 2,
    destination_unavailable = 3,
    destination_IP_prohibited = 4,
    destination_IP_unroutable = 5,
    connection_refused = 6,
    connection_terminated = 7,
    connection_timeout = 8,
    connection_read_timeout = 9,
    connection_write_timeout = 10,
    connection_limit_reached = 11,
    TLS_protocol_error = 12,
    TLS_certificate_error = 13,
    TLS_alert_received = 14,
    HTTP_request_denied = 15,
    HTTP_request_length_required = 16,
    HTTP_request_body_size = 17,
    HTTP_request_method_invalid = 18,
    HTTP_request_URI_invalid = 19,
    HTTP_request_URI_too_long = 20,
    HTTP_request_header_section_size = 21,
    HTTP_request_header_size = 22,
    HTTP_request_trailer_section_size = 23,
    HTTP_request_trailer_size = 24,
    HTTP_response_incomplete = 25,
    HTTP_response_header_section_size = 26,
    HTTP_response_header_size = 27,
    HTTP_response_body_size = 28,
    HTTP_response_trailer_section_size = 29,
    HTTP_response_trailer_size = 30,
    HTTP_response_transfer_coding = 31,
    HTTP_response_content_coding = 32,
    HTTP_response_timeout = 33,
    HTTP_upgrade_failed = 34,
    HTTP_protocol_error = 35,
    loop_detected = 36,
    configuration_error = 37,
    internal_error = 38,
};

/// Map a `std.http.Client.FetchError` (or any error that reaches the
/// outbound-handler / `client.send` catch arm) onto the most specific
/// `wasi:http/types.error-code` variant we can name (#583 A3).
///
/// The full FetchError set is, transitively:
///   * `Uri.ParseError` — `InvalidFormat`, `UnexpectedCharacter`, `InvalidPort`.
///   * `Allocator.Error` — `OutOfMemory`.
///   * `HostName.LookupError` — DNS resolution failures.
///   * `IpAddress.ConnectError` / `IpAddress.BindError` — kernel-level
///     connect failures.
///   * `error{TlsInitializationFailed, CertificateBundleLoadFailure,
///     UnsupportedUriScheme, UriMissingHost}` from `Client.RequestError`.
///   * `Request.ReceiveHeadError` — HTTP/1.1 framing failures during the
///     response head parse.
///   * The leaf `error{StreamTooLong, WriteFailed, UnsupportedCompressionMethod}`
///     declared on `FetchError` itself.
///
/// Each *classified* error has its own arm below; truly-unknown errors
/// (`OutOfMemory`, `SystemResources`, `Canceled`, `Unexpected`, plus
/// anything new Zig adds to the FetchError set after this revision) fall
/// through the `else` arm to `internal_error`. The README sentence
/// promising this as follow-up work has been retired.
fn mapHttpFetchError(err: anyerror) HttpErrorCode {
    return switch (err) {
        // ── Connection-level transport (IpAddress.ConnectError) ──────────
        error.ConnectionRefused => .connection_refused,
        error.ConnectionResetByPeer,
        error.ReadFailed,
        error.WriteFailed,
        error.HttpRequestTruncated,
        error.HttpConnectionClosing,
        error.HttpChunkTruncated,
        => .connection_terminated,
        error.HostUnreachable,
        error.NetworkUnreachable,
        error.NetworkDown,
        => .destination_unavailable,
        error.Timeout => .connection_timeout,
        // Response-phase budgets (`first-byte-timeout` /
        // `between-bytes-timeout`) must not be reported as a
        // connection timeout: the connection succeeded and it is the
        // response that was too slow (#616 A1).
        error.HttpResponseTimeout => .HTTP_response_timeout,
        // Guest-initiated cancellation (#616 A7). The worker's own
        // cancel arm short-circuits before reaching this table, but the
        // cancel lane can also surface from paths that map errors
        // generically, and every one of them must agree with the
        // drainer's `HTTP_request_denied` disposition.
        error.HttpFetchCancelled => .HTTP_request_denied,
        error.AccessDenied => .destination_IP_prohibited,

        // ── TLS (ConnectTcpError remaps `Connection.Tls.create` failures
        //    to `TlsInitializationFailed`; the bundle-load case is its own
        //    arm of `RequestError`). ───────────────────────────────────────
        error.TlsInitializationFailed => .TLS_protocol_error,
        error.CertificateBundleLoadFailure => .TLS_certificate_error,

        // ── DNS / name resolution (`HostName.LookupError`) ─────────────────
        error.UnknownHostName,
        error.NameServerFailure,
        error.InvalidDnsARecord,
        error.InvalidDnsAAAARecord,
        error.InvalidDnsCnameRecord,
        error.ResolvConfParseFailed,
        error.DetectingNetworkConfigurationFailed,
        => .DNS_error,
        error.NoAddressReturned,
        error.AddressUnavailable,
        => .destination_not_found,

        // ── URI / request shape (`Uri.ParseError` + `RequestError`) ───────
        error.UnsupportedUriScheme,
        error.UriMissingHost,
        error.UnexpectedCharacter,
        error.InvalidFormat,
        error.InvalidPort,
        => .HTTP_request_URI_invalid,

        // ── HTTP/1.1 response framing (`Request.ReceiveHeadError`) ────────
        error.HttpHeadersInvalid,
        error.HttpChunkInvalid,
        error.HttpRedirectLocationMissing,
        error.HttpRedirectLocationInvalid,
        error.RedirectRequiresResend,
        => .HTTP_protocol_error,
        error.HttpHeadersOversize,
        error.HttpRedirectLocationOversize,
        => .HTTP_response_header_section_size,
        error.StreamTooLong => .HTTP_response_body_size,
        error.HttpContentEncodingUnsupported,
        error.UnsupportedCompressionMethod,
        => .HTTP_response_content_coding,
        error.TooManyHttpRedirects => .loop_detected,

        // Truly-unknown failures — intentional fallthrough. Every
        // classified path has its own arm above. Members reaching this
        // include `error.OutOfMemory`, `error.SystemResources`,
        // `error.ProcessFdQuotaExceeded`, `error.SystemFdQuotaExceeded`,
        // `error.Canceled`, `error.Unexpected`, and anything Zig adds to
        // `FetchError` after this audit.
        else => .internal_error,
    };
}

/// Successful low-level outbound HTTP fetch result. All three fields are
/// owned host-allocated slices: the caller takes ownership and is
/// responsible for freeing them (`freeOwnedHttpHeaders` for `headers`,
/// `allocator.free` for `body`). (#583 A4)
const HttpLowLevelFetchResult = struct {
    status: u16,
    headers: []HttpFieldEntry,
    body: []u8,
};

/// Per-chunk granularity for cancel polling inside the outbound body-
/// read loop (#583 B1 follow-up). The worker performs a
/// `cancelled.load(.acquire)` check before pumping each chunk, so a
/// guest-issued `task.cancel` is observed within at most one chunk's
/// I/O latency once body-streaming has begun. 64 KiB matches the
/// typical TCP receive-window granularity and keeps the syscall
/// overhead negligible relative to the cancel-observability win.
const http_cancel_body_chunk_bytes: usize = 64 * 1024;

/// Phase-boundary cancel check used by `httpClientLowLevelFetch`.
/// Returns `error.HttpFetchCancelled` if the worker's
/// `PendingHttpFetchShared.cancelled` advisory flag has been flipped
/// by the adapter's `cancelAllPendingAsyncOps` driver
/// (`task.cancel` propagation, #583 B1). `cancelled == null` (used
/// by call-sites that have no shared block, e.g. unit-tests that
/// drive the helper directly without spawning a worker) short-
/// circuits to success so the helper can still be exercised
/// out-of-band.
fn checkHttpCancel(cancelled: ?*std.atomic.Value(bool)) error{HttpFetchCancelled}!void {
    if (cancelled) |c| {
        if (c.load(.acquire)) return error.HttpFetchCancelled;
    }
}

/// Poll cadence bounds for the cancel lane (#616 A7).
///
/// The lane starts at `initial` and doubles up to `max`, so a cancel
/// that lands right after an operation blocks is observed in about a
/// millisecond, while a long-running transfer settles onto a 25 ms
/// cadence that costs ~40 timer wakeups per second per in-flight
/// fetch. Both numbers are far below any network round-trip, so the
/// guest-visible cancel latency is dominated by the wake itself.
const http_cancel_poll_initial_ns: u64 = 1 * std.time.ns_per_ms;
const http_cancel_poll_max_ns: u64 = 25 * std.time.ns_per_ms;

fn httpCancelPollTimeout(ns: u64) std.Io.Timeout {
    return .{ .duration = .{
        .raw = .{ .nanoseconds = @as(i96, ns) },
        .clock = .awake,
    } };
}

/// Cancel-lane body: returns once `cancelled` has been observed set.
///
/// This is the piece that turns the previously *advisory*
/// `checkHttpCancel` phase-boundary polls into cancellation that can
/// actually wake a blocked operation (#616 A7). Raced against the real
/// operation inside a `std.Io.Select`, its completion causes the
/// select to cancel the losing lane — and because every outbound
/// operation runs on Zig's Threaded-I/O backend, that cancellation
/// interrupts the in-flight `getaddrinfo` / `connect` / `read` /
/// `write` syscall instead of waiting for it to return on its own.
///
/// It is implemented as a bounded-backoff sleep rather than a
/// condition-variable wait for one specific reason: the lane must
/// itself be cancellable through `std.Io`. When the *operation* wins
/// the race, the select cancels this lane, and only an `Io`-aware
/// blocking primitive (`Timeout.sleep`) can be interrupted that way. A
/// `std.Thread.ResetEvent.wait` would leave the lane parked forever
/// on every successful request.
fn httpAwaitCancelSignal(io: std.Io, cancelled: *std.atomic.Value(bool)) anyerror!void {
    var backoff_ns = http_cancel_poll_initial_ns;
    while (!cancelled.load(.acquire)) {
        try std.Io.Timeout.sleep(httpCancelPollTimeout(backoff_ns), io);
        backoff_ns = @min(backoff_ns * 2, http_cancel_poll_max_ns);
    }
}

fn discardHttpConnectDeadlineTasks(
    client: *std.http.Client,
    select: *std.Io.Select(HttpConnectDeadlineOutcome),
) void {
    while (select.cancel()) |outcome| switch (outcome) {
        .connection => |result| if (result) |connection| {
            client.connection_pool.release(connection, client.io);
        } else |_| {},
        .deadline => |result| result catch {},
        .cancel => |result| result catch {},
    };
}

/// Race `Client.connectTcpOptions` against an absolute deadline. This
/// wrapper is required on Zig 0.16: `connectTcpOptions` accepts a
/// timeout field but does not forward it to `HostName.connect`.
/// Cancelling the losing connector interrupts the Threaded-I/O
/// connect syscall; its partial socket is closed by the stdlib's
/// existing cleanup path.
fn httpClientConnectBeforeDeadlineUsing(
    client: *std.http.Client,
    connect_options: std.http.Client.ConnectTcpOptions,
    deadline: std.Io.Timeout,
    cancelled: ?*std.atomic.Value(bool),
    comptime connect: anytype,
) anyerror!*std.http.Client.Connection {
    var outcome_buffer: [3]HttpConnectDeadlineOutcome = undefined;
    var select = std.Io.Select(HttpConnectDeadlineOutcome).init(
        client.io,
        &outcome_buffer,
    );
    if (deadline != .none) {
        try select.concurrent(
            .deadline,
            std.Io.Timeout.sleep,
            .{ deadline, client.io },
        );
    }
    // #616 A7: without this lane a cancel issued while the worker is
    // parked in `getaddrinfo` or a TCP/TLS handshake is not observed
    // until the connect returns on its own — which for an unroutable
    // host is the full OS SYN-retry period.
    if (cancelled) |flag| {
        select.concurrent(
            .cancel,
            httpAwaitCancelSignal,
            .{ client.io, flag },
        ) catch |err| {
            discardHttpConnectDeadlineTasks(client, &select);
            return err;
        };
    }
    select.concurrent(
        .connection,
        connect,
        .{ client, connect_options },
    ) catch |err| {
        discardHttpConnectDeadlineTasks(client, &select);
        return err;
    };

    const first = select.await() catch |err| {
        discardHttpConnectDeadlineTasks(client, &select);
        return err;
    };
    return switch (first) {
        .connection => |result| connected: {
            // Only void-returning guard lanes remain; they own no
            // resources, so discarding their cancelled results is safe.
            select.cancelDiscard();
            break :connected try result;
        },
        .deadline => |result| timed_out: {
            discardHttpConnectDeadlineTasks(client, &select);
            try result;
            break :timed_out error.Timeout;
        },
        .cancel => |result| aborted: {
            discardHttpConnectDeadlineTasks(client, &select);
            try result;
            break :aborted error.HttpFetchCancelled;
        },
    };
}

fn httpClientConnectBeforeDeadline(
    client: *std.http.Client,
    connect_options: std.http.Client.ConnectTcpOptions,
    deadline: std.Io.Timeout,
    cancelled: ?*std.atomic.Value(bool),
) anyerror!*std.http.Client.Connection {
    return httpClientConnectBeforeDeadlineUsing(
        client,
        connect_options,
        deadline,
        cancelled,
        std.http.Client.connectTcpOptions,
    );
}

/// Establish the initial request connection with the WIT connect
/// timeout. `Client.RequestOptions` has no timeout in Zig 0.16, so the
/// acquired connection is passed explicitly to `Client.request`.
///
/// The client in `httpClientLowLevelFetch` has never configured proxy
/// fields (both are null), and the old `Client.request` path therefore
/// connected directly too; using `connectTcpOptions` preserves that
/// behavior rather than silently bypassing an active proxy. TLS still
/// uses `std.http.Client.Connection.Tls`: the CA bundle initialization
/// normally performed by `Client.request` must happen before the
/// explicit TLS connection is acquired, which is why this function
/// rescans the bundle itself.
///
/// The TLS handshake is covered by this deadline. `connectTcpOptions`
/// builds an `https` connection through `Connection.Tls.create`, which
/// calls `std.crypto.tls.Client.init` inline; that constructor flushes
/// the ClientHello and reads server records through `finished`, so the
/// full handshake completes before `connectTcpOptions` returns and
/// therefore inside the raced budget. (An earlier revision of this
/// comment described the handshake as lazily performed during request
/// I/O; that is not how Zig 0.16 behaves.)
///
/// Redirect hops are covered too, because `httpClientLowLevelFetch`
/// drives redirects itself and routes every hop back through this
/// function, instead of letting `Request.receiveHead` reconnect via
/// the untimed `Client.connect`.
fn httpClientConnectWithTimeout(
    client: *std.http.Client,
    uri: std.Uri,
    timeout: std.Io.Timeout,
    cancelled: ?*std.atomic.Value(bool),
) anyerror!*std.http.Client.Connection {
    // Convert once so name lookup, TCP connection, and synchronous
    // setup consume one budget rather than resetting the duration.
    const deadline = timeout.toDeadline(client.io);
    const protocol = std.http.Client.Protocol.fromUri(uri) orelse
        return error.UnsupportedUriScheme;

    if (protocol == .tls and client.now == null) {
        var bundle: std.crypto.Certificate.Bundle = .empty;
        defer bundle.deinit(client.allocator);
        const now = std.Io.Clock.real.now(client.io);
        bundle.rescan(client.allocator, client.io, now) catch |err| switch (err) {
            error.Canceled => |e| return e,
            else => return error.CertificateBundleLoadFailure,
        };
        client.now = now;
        std.mem.swap(std.crypto.Certificate.Bundle, &client.ca_bundle, &bundle);
    }

    var host_name_buffer: [std.Io.net.HostName.max_len]u8 = undefined;
    const host = try uri.getHost(&host_name_buffer);
    const port: u16 = uri.port orelse switch (protocol) {
        .plain => 80,
        .tls => 443,
    };
    return httpClientConnectBeforeDeadline(
        client,
        .{
            .host = host,
            .port = port,
            .protocol = protocol,
            // Ignored by Zig 0.16, but retained for forward
            // compatibility. The Select race enforces it today.
            .timeout = deadline,
        },
        deadline,
        cancelled,
    );
}

/// Payload type of a raced response-phase operation, i.e. its return
/// type with any error union stripped.
fn HttpRacedPayload(comptime op: anytype) type {
    const Ret = @typeInfo(@TypeOf(op)).@"fn".return_type.?;
    return switch (@typeInfo(Ret)) {
        .error_union => |eu| eu.payload,
        else => Ret,
    };
}

fn HttpRaceOutcome(comptime op: anytype) type {
    return union(enum) {
        value: @typeInfo(@TypeOf(op)).@"fn".return_type.?,
        deadline: std.Io.Cancelable!void,
        /// #616 A7 cancel lane. Wins when the guest cancels (via
        /// `task.cancel` or by dropping the future/request resource)
        /// while the operation is still blocked.
        cancel: anyerror!void,
    };
}

/// Race a response-phase operation against a *relative* WIT budget.
///
/// Unlike `httpClientConnectBeforeDeadlineUsing`, which converts once
/// to an absolute deadline so DNS + TCP + TLS share a single connect
/// budget, this helper deliberately takes the relative duration and
/// starts a fresh timer per call. That is precisely the WIT
/// "reset on progress" semantic: each redirect hop gets its own
/// `first-byte-timeout`, and each body chunk that arrives re-arms the
/// `between-bytes-timeout` rather than drawing down a whole-response
/// budget.
///
/// Callers must not invoke this with `.none`; an unset WIT timeout has
/// to run the operation directly so no task is spawned and the
/// zero-configuration path keeps its current cost.
///
/// Budget expiry surfaces as `error.HttpResponseTimeout`, which
/// `mapHttpFetchError` maps to `HTTP_response_timeout` — response-phase
/// expiry must never be reported as `connection-timeout` (#616 A1).
/// The losing task is cancelled and joined before returning, so any
/// stack state it borrowed (`Request`, `Io.Writer`) is quiescent by the
/// time the caller unwinds.
fn httpAwaitBeforeDeadline(
    comptime op: anytype,
    io: std.Io,
    budget: std.Io.Timeout,
    cancelled: ?*std.atomic.Value(bool),
    op_args: std.meta.ArgsTuple(@TypeOf(op)),
) anyerror!HttpRacedPayload(op) {
    const U = HttpRaceOutcome(op);
    var outcome_buffer: [3]U = undefined;
    var select = std.Io.Select(U).init(io, &outcome_buffer);

    if (budget != .none) {
        try select.concurrent(.deadline, std.Io.Timeout.sleep, .{ budget, io });
    }
    if (cancelled) |flag| {
        select.concurrent(.cancel, httpAwaitCancelSignal, .{ io, flag }) catch |err| {
            select.cancelDiscard();
            return err;
        };
    }
    select.concurrent(.value, op, op_args) catch |err| {
        select.cancelDiscard();
        return err;
    };

    const first = select.await() catch |err| {
        select.cancelDiscard();
        return err;
    };
    return switch (first) {
        .value => |result| completed: {
            // Only void-returning guard lanes can remain; they own no
            // resources, so discarding their cancelled results is safe.
            select.cancelDiscard();
            break :completed try result;
        },
        .deadline => |result| expired: {
            select.cancelDiscard();
            try result;
            break :expired error.HttpResponseTimeout;
        },
        .cancel => |result| aborted: {
            select.cancelDiscard();
            try result;
            break :aborted error.HttpFetchCancelled;
        },
    };
}

/// Run `op` under the guest's response-phase budget and the cancel
/// signal, racing only the lanes that are actually armed.
///
/// With neither a WIT timeout nor a cancel flag the operation runs
/// inline, so the zero-configuration path keeps its original cost: no
/// task is spawned and no timer is armed. Any other combination goes
/// through `httpAwaitBeforeDeadline`, whose lanes are added
/// conditionally.
fn httpRunWithOptionalDeadline(
    comptime op: anytype,
    io: std.Io,
    budget: std.Io.Timeout,
    cancelled: ?*std.atomic.Value(bool),
    op_args: std.meta.ArgsTuple(@TypeOf(op)),
) anyerror!HttpRacedPayload(op) {
    if (budget == .none and cancelled == null) {
        return try @call(.auto, op, op_args);
    }
    return try httpAwaitBeforeDeadline(op, io, budget, cancelled, op_args);
}

/// Run `op` under the cancel signal alone — the request-transmission
/// phases have no WIT budget of their own, but must still be
/// interruptible (#616 A7). Runs inline when no cancel flag is armed.
fn httpRunGuarded(
    comptime op: anytype,
    io: std.Io,
    cancelled: ?*std.atomic.Value(bool),
    op_args: std.meta.ArgsTuple(@TypeOf(op)),
) anyerror!HttpRacedPayload(op) {
    return try httpRunWithOptionalDeadline(op, io, .none, cancelled, op_args);
}

/// Redirect hops followed for a repeatable (payload-free) outbound
/// request. Matches the `RedirectBehavior.init(3)` budget the adapter
/// previously handed to `Request.receiveHead`, so guest-visible
/// redirect behavior is unchanged; only the timing ownership moved.
const http_max_redirect_hops: u16 = 3;

/// Scratch space for resolving `Location` headers across a redirect
/// chain. RFC 9110 recommends supporting at least 8000 bytes of
/// redirect URI, and `Uri.resolveInPlace` consumes the buffer
/// monotonically (each hop's resolved URI keeps borrowing its own
/// region), so the budget covers the whole chain rather than one hop.
const http_redirect_buffer_bytes: usize = 8 * 1024;

/// Apply the RFC 9110 method rewrite a redirect implies. 303 always
/// downgrades to GET; 301/302 downgrade only a POST. Mirrors
/// `std.http.Client.Request.redirect` so guest-visible behavior does
/// not change now that the adapter owns the redirect loop.
fn httpRedirectMethod(status: std.http.Status, method: std.http.Method) std.http.Method {
    return switch (status) {
        .see_other => .GET,
        .moved_permanently, .found => if (method == .POST) .GET else method,
        else => method,
    };
}

/// Drive a single outbound HTTP request through the lower-level
/// `std.http.Client.request` / `Request.receiveHead` /
/// `Response.readerDecompressing` API and capture the full
/// `(status, headers, body)` triple — the equivalent of
/// `std.http.Client.fetch` but without the `FetchResult.status`-only
/// projection that discards the response header list.
///
/// Both the worker thread (`httpFetchWorker`) and the synchronous P3
/// `client.send` path call this helper so the two outbound surfaces
/// produce byte-identical lifted `incoming-response` resources. Errors
/// flow back through `mapHttpFetchError` for `error-code` mapping
/// (#583 A3 — the error set is the same union the old `fetch` path
/// returned, transitively).
///
/// On success the caller owns the returned `headers` (free with
/// `freeOwnedHttpHeaders`) and `body` (`allocator.free`). Headers
/// listed in `isTransportManagedHeader` (Content-Length,
/// Transfer-Encoding, Connection, Keep-Alive, Trailer, TE, Upgrade,
/// Host) are stripped so the lifted `incoming-response` exposes only
/// the application-level headers per the wasi:http WIT spec (#583 A4).
///
/// `cancelled` is an optional pointer into a worker-shared
/// `PendingHttpFetchShared.cancelled` atomic. When non-null the
/// helper polls `.load(.acquire)` at every phase boundary —
/// pre-connect, pre-send, pre-receive-head, pre-body-read, and
/// before each `http_cancel_body_chunk_bytes`-sized body chunk — so a
/// `task.cancel` issued by the guest is observed within at most one
/// I/O-syscall's latency rather than only at the worker's pre-fetch
/// check. Cancel surfaces as `error.HttpFetchCancelled`; callers in
/// the worker thread translate that to `HTTP_request_denied` (the
/// canonical "request was not delivered" 0.3 error-code) before
/// publishing the outcome. Connection / response cleanup on cancel
/// is handled by the existing `defer req.deinit()` chain — no
/// explicit close needed. Pass `null` if the caller has no shared
/// block (e.g. direct unit-test invocations). (#583 B1 follow-up)
///
/// Redirects are followed by this function rather than by
/// `Request.receiveHead` (#616 A1). Automatic redirects reconnect
/// through the untimed `Client.connect`, which left every hop after
/// the first outside the guest's `connect-timeout`, and put the whole
/// chain under a single response budget. Owning the loop lets each hop
/// re-run `httpClientConnectWithTimeout` and start a fresh
/// `first-byte-timeout`. The guest-visible policy is unchanged:
/// payload-free requests follow up to `http_max_redirect_hops` hops
/// and then fail with `error.TooManyHttpRedirects`, requests carrying a
/// payload are never redirected and surface the 3xx response as-is.
fn httpClientLowLevelFetch(
    allocator: Allocator,
    io: std.Io,
    url: []const u8,
    method: std.http.Method,
    extra_headers: []const std.http.Header,
    payload: ?[]const u8,
    options: HttpFetchOptions,
    cancelled: ?*std.atomic.Value(bool),
) anyerror!HttpLowLevelFetchResult {
    // Pre-connect sync point: bail before issuing any syscall if the
    // guest cancelled while the request was queued on the worker.
    try checkHttpCancel(cancelled);

    var client: std.http.Client = .{
        .allocator = allocator,
        .io = io,
    };
    defer client.deinit();

    // Redirect scratch. `Uri.resolveInPlace` consumes `aux_buf`
    // monotonically, so every hop's resolved URI keeps borrowing its
    // own region and earlier hops stay valid as resolution bases.
    var redirect_storage: [http_redirect_buffer_bytes]u8 = undefined;
    var aux_buf: []u8 = &redirect_storage;

    // `receiveHead` never resolves redirects for us now, so it needs no
    // buffer of its own.
    const no_redirect_buffer: []u8 = &.{};

    var uri = try std.Uri.parse(url);
    var hop_method = method;
    // A request carrying a payload is not repeatable, so it is never
    // redirected and the 3xx reaches the guest verbatim — the same
    // outcome the previous `.unhandled` redirect behavior produced.
    var hops_remaining: u16 = if (payload == null) http_max_redirect_hops else 0;

    while (true) {
        // Acquire this hop's connection ourselves whenever there is
        // anything to enforce — a WIT `connect-timeout`, a cancel
        // signal, or both — and transfer it to `Request`;
        // `Request.deinit` retains its existing cancellation,
        // connection-pool, and TLS cleanup. With neither, fall through
        // to `Client.request`'s own connection path so the
        // zero-configuration case is untouched.
        //
        // #616 A7 widened this from "connect-timeout set" to "guard
        // armed": DNS, TCP connect and the eager TLS handshake all
        // happen inside `connectTcpOptions`, so a cancel that arrives
        // while the worker is parked there is only observable if this
        // hop went through the raced helper.
        const connect_timeout = options.connectTimeout();
        const connection = if (connect_timeout == .none and cancelled == null)
            null
        else
            try httpClientConnectWithTimeout(&client, uri, connect_timeout, cancelled);
        var req = client.request(hop_method, uri, .{
            .extra_headers = extra_headers,
            .keep_alive = false,
            .connection = connection,
            // The adapter owns the redirect loop; see the doc comment.
            .redirect_behavior = .unhandled,
        }) catch |err| {
            if (connection) |conn| client.connection_pool.release(conn, io);
            return err;
        };
        defer req.deinit();

        // Pre-send sync point: connect / TLS handshake already done;
        // bail before pushing the request head + body on the wire if
        // the guest cancelled.
        try checkHttpCancel(cancelled);

        // Request transmission. Every wire-touching step is routed
        // through the guard so a cancel can interrupt a `write(2)`
        // that has blocked on a full socket send buffer — which is
        // exactly what happens when the peer stops reading a large
        // request body (#616 A7).
        //
        // The body is pushed in `http_cancel_body_chunk_bytes` slices
        // rather than one `writeAll`, so cancellation is polled
        // between request chunks and not only at the end of the whole
        // payload. The chunking is invisible on the wire: the writer
        // buffers and the framing is fixed by `content_length`.
        if (payload) |p| {
            req.transfer_encoding = .{ .content_length = p.len };
            var body_writer = try httpRunGuarded(
                std.http.Client.Request.sendBodyUnflushed,
                io,
                cancelled,
                .{ &req, &.{} },
            );
            var offset: usize = 0;
            while (offset < p.len) {
                const end = @min(offset + http_cancel_body_chunk_bytes, p.len);
                try httpRunGuarded(
                    std.Io.Writer.writeAll,
                    io,
                    cancelled,
                    .{ &body_writer.writer, p[offset..end] },
                );
                offset = end;
            }
            try httpRunGuarded(
                std.http.BodyWriter.end,
                io,
                cancelled,
                .{&body_writer},
            );
            try httpRunGuarded(
                std.http.Client.Connection.flush,
                io,
                cancelled,
                .{req.connection.?},
            );
        } else {
            try httpRunGuarded(
                std.http.Client.Request.sendBodiless,
                io,
                cancelled,
                .{&req},
            );
        }

        // Pre-receive-head sync point: request fully on the wire; bail
        // before blocking on the response.
        try checkHttpCancel(cancelled);

        // `first-byte-timeout` is armed per hop. The response head is
        // the observable proxy for "the first byte of the response" —
        // the same point Wasmtime bounds — and a fresh timer here is
        // what makes the budget per-hop rather than per-chain.
        var response = try httpRunWithOptionalDeadline(
            std.http.Client.Request.receiveHead,
            io,
            options.firstByteTimeout(),
            cancelled,
            .{ &req, no_redirect_buffer },
        );

        if (response.head.status.class() == .redirect and payload == null) {
            if (hops_remaining == 0) return error.TooManyHttpRedirects;

            const location = response.head.location orelse
                return error.HttpRedirectLocationMissing;
            if (location.len > aux_buf.len) return error.HttpRedirectLocationOversize;
            @memcpy(aux_buf[0..location.len], location);
            const next_uri = uri.resolveInPlace(location.len, &aux_buf) catch |err| switch (err) {
                error.NoSpaceLeft => return error.HttpRedirectLocationOversize,
                else => return error.HttpRedirectLocationInvalid,
            };

            // Suppress the body drain `Request.deinit` performs for a
            // half-read response. This hop's connection is never reused
            // (`keep_alive = false`), and that discard would be an
            // unbounded read sitting outside every WIT budget.
            if (req.connection) |conn| conn.closing = true;

            hop_method = httpRedirectMethod(response.head.status, hop_method);
            uri = next_uri;
            hops_remaining -= 1;
            continue;
        }

        // Snapshot headers BEFORE invoking `response.reader(...)` — that
        // call invalidates `response.head.bytes`, which the iterator
        // points into.
        var hdr_list: std.ArrayListUnmanaged(HttpFieldEntry) = .empty;
        errdefer {
            for (hdr_list.items) |e| {
                allocator.free(e.name);
                allocator.free(e.value);
            }
            hdr_list.deinit(allocator);
        }
        {
            var hit = response.head.iterateHeaders();
            while (hit.next()) |h| {
                // Trailers are not surfaced through `incoming-response.headers`
                // per the WIT spec — they have their own `future-trailers`
                // resource. Stop at the trailer boundary.
                if (hit.is_trailer) break;
                if (isTransportManagedHeader(h.name)) continue;
                const name_copy = try allocator.dupe(u8, h.name);
                errdefer allocator.free(name_copy);
                const value_copy = try allocator.dupe(u8, h.value);
                errdefer allocator.free(value_copy);
                try hdr_list.append(allocator, .{ .name = name_copy, .value = value_copy });
            }
        }

        const status_code: u16 = @intFromEnum(response.head.status);

        // Pre-body-read sync point: response head + headers captured;
        // bail before draining the body if the guest cancelled. Any
        // bytes the kernel has already buffered are abandoned by the
        // deferred `req.deinit()` close.
        try checkHttpCancel(cancelled);

        // Drain the body. HEAD / 1xx / 204 / 304 responses have no body
        // per RFC 9110; `Request.receiveHead` leaves the reader in `.ready`
        // for those and `response.reader(...)` short-circuits to `.ending`.
        var aw: std.Io.Writer.Allocating = .init(allocator);
        errdefer aw.deinit();

        const decompress_buffer: []u8 = switch (response.head.content_encoding) {
            .identity => &.{},
            .zstd => try allocator.alloc(u8, std.compress.zstd.default_window_len),
            .deflate, .gzip => try allocator.alloc(u8, std.compress.flate.max_window_len),
            .compress => return error.UnsupportedCompressionMethod,
        };
        defer if (decompress_buffer.len != 0) allocator.free(decompress_buffer);

        var transfer_buffer: [64]u8 = undefined;
        var decompress: std.http.Decompress = undefined;
        const body_reader = response.readerDecompressing(&transfer_buffer, &decompress, decompress_buffer);

        // Chunked body-read loop with per-chunk cancel polling. Equivalent
        // to `Reader.streamRemaining` but interleaves a
        // `cancelled.load(.acquire)` check at each
        // `http_cancel_body_chunk_bytes` boundary so a `task.cancel`
        // issued mid-body is observed within one chunk's latency. On
        // cancel the partial `aw` buffer is freed by its `errdefer`, so
        // any bytes already streamed are discarded cleanly.
        //
        // Each chunk is additionally bounded by `between-bytes-timeout`
        // with a freshly armed timer, so a chunk that arrives re-arms
        // the window: the budget is "time without progress", not a
        // whole-body allowance.
        const chunk_limit: std.Io.Limit = .limited(http_cancel_body_chunk_bytes);
        const between_bytes = options.betweenBytesTimeout();
        while (true) {
            try checkHttpCancel(cancelled);
            _ = httpRunWithOptionalDeadline(
                std.Io.Reader.stream,
                io,
                between_bytes,
                cancelled,
                .{ body_reader, &aw.writer, chunk_limit },
            ) catch |err| switch (err) {
                error.EndOfStream => break,
                error.ReadFailed => return response.bodyErr().?,
                else => |e| return e,
            };
        }

        var body_al = aw.toArrayList();
        const body = try body_al.toOwnedSlice(allocator);
        errdefer allocator.free(body);

        return .{
            .status = status_code,
            .headers = try hdr_list.toOwnedSlice(allocator),
            .body = body,
        };
    }
}

const max_http_header_bytes: usize = 64 * 1024;
const max_http_body_bytes: usize = 16 * 1024 * 1024;
const max_http_target_bytes: usize = 8192;

/// HTTP/1.1 incoming-handler limits (#583 A5). The header-section limit
/// matches Wasmtime's default `max-header-size = 16384` and is enforced
/// per-request on the live TCP accept path. The body limit aliases
/// `max_http_body_bytes` so a single 0.3 surface knob covers both.
const max_http_p3_header_section_bytes: usize = 16 * 1024;
const max_http_p3_body_bytes: usize = max_http_body_bytes;

/// Keep-alive idle timeout (#583 A5). When a connection is held open
/// between requests, the next request must arrive within this window
/// or the server closes the socket. Set just above the WASI testsuite's
/// own 5s request timeout so a healthy round-trip is never starved by
/// our own idle cap.
const http_p3_keep_alive_idle_seconds: i64 = 5;

/// `wasi:http/types.fields`: a multi-map of header name -> value bytes.
/// Each entry's name and value are owned host-allocated slices, freed
/// when the slot is dropped or the adapter deinits.
pub const HttpFieldEntry = struct {
    name: []u8,
    value: []u8,
};

pub const HttpFields = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    entries: std.ArrayListUnmanaged(HttpFieldEntry) = .empty,
    /// `[static]fields.from-list` returns mutable fields per WIT; the
    /// flag exists so a future implementation of header-immutability
    /// (e.g. fields owned by an incoming-request) has somewhere to
    /// record it. Default-deny stubs ignore it.
    immutable: bool = false,

    pub fn deinit(self: *HttpFields, allocator: Allocator) void {
        for (self.entries.items) |e| {
            allocator.free(e.name);
            allocator.free(e.value);
        }
        self.entries.deinit(allocator);
    }
};

/// Lift a `list<tuple<string, string>>` from guest memory into a fresh
/// allocator-owned slice of `HttpFieldEntry`. Used by
/// `[static]fields.from-list` (#174). Each list element is laid out as
/// four little-endian u32s — name.ptr, name.len, value.ptr, value.len —
/// for a 16-byte stride and 4-byte alignment, matching the canonical
/// ABI lowering used by `getEnvironment`.
///
/// On any out-of-bounds read the partially-allocated entries are freed
/// and `error.OutOfBoundsMemory` is returned, leaving no leaks.
fn liftFieldEntries(
    allocator: Allocator,
    mem: []const u8,
    list_ptr: u32,
    count: u32,
) ![]HttpFieldEntry {
    const stride: u32 = 16;
    const total = std.math.mul(u32, count, stride) catch return error.OutOfBoundsMemory;
    const list_end = std.math.add(u32, list_ptr, total) catch return error.OutOfBoundsMemory;
    if (list_end > mem.len) return error.OutOfBoundsMemory;

    const entries = try allocator.alloc(HttpFieldEntry, count);
    var filled: usize = 0;
    errdefer {
        for (entries[0..filled]) |e| {
            allocator.free(e.name);
            allocator.free(e.value);
        }
        allocator.free(entries);
    }

    while (filled < count) : (filled += 1) {
        const off = list_ptr + @as(u32, @intCast(filled)) * stride;
        const name_ptr = std.mem.readInt(u32, mem[off..][0..4], .little);
        const name_len = std.mem.readInt(u32, mem[off + 4 ..][0..4], .little);
        const val_ptr = std.mem.readInt(u32, mem[off + 8 ..][0..4], .little);
        const val_len = std.mem.readInt(u32, mem[off + 12 ..][0..4], .little);

        const name_end = std.math.add(u32, name_ptr, name_len) catch return error.OutOfBoundsMemory;
        if (name_end > mem.len) return error.OutOfBoundsMemory;
        const val_end = std.math.add(u32, val_ptr, val_len) catch return error.OutOfBoundsMemory;
        if (val_end > mem.len) return error.OutOfBoundsMemory;

        const raw_name = mem[name_ptr..name_end];
        const raw_value = mem[val_ptr..val_end];
        // `fields.from-list` rejects invalid names/values with
        // `header-error.invalid-syntax` (#538). The caller dispatches
        // on the returned `error.InvalidFieldSyntax` to lower a result
        // error variant.
        if (!isValidFieldName(raw_name)) return error.InvalidFieldSyntax;
        if (!isValidFieldValue(raw_value)) return error.InvalidFieldSyntax;

        const name_copy = try lowercaseFieldName(allocator, raw_name);
        errdefer allocator.free(name_copy);
        const val_copy = try allocator.dupe(u8, raw_value);
        entries[filled] = .{ .name = name_copy, .value = val_copy };
    }

    return entries;
}

/// RFC 9110 §5.6.2 `tchar` validation: a non-empty token where every
/// byte is one of `!`, `#`, `$`, `%`, `&`, `'`, `*`, `+`, `-`, `.`,
/// `^`, `_`, `` ` ``, `|`, `~`, ASCII digit, or ASCII letter. The
/// wasi:http@0.3.0 fixtures sweep every codepoint 0..1024 expecting
/// non-token names to return `header-error.invalid-syntax` (#538).
///
/// Comptime-generated 256-byte lookup table (#552). The hot path
/// becomes a single indexed load + compare per byte, which is ~6×
/// faster than the prior `switch` chain — http-fields validates
/// ≥1024 codepoints through this function on every run and the CI
/// 5-second budget needs the speed-up.
pub const tchar_lut: [256]bool = blk: {
    var t: [256]bool = @splat(false);
    for ("!#$%&'*+-.^_`|~") |c| t[c] = true;
    var c: u8 = '0';
    while (c <= '9') : (c += 1) t[c] = true;
    c = 'A';
    while (c <= 'Z') : (c += 1) t[c] = true;
    c = 'a';
    while (c <= 'z') : (c += 1) t[c] = true;
    break :blk t;
};

pub fn isValidFieldName(name: []const u8) bool {
    if (name.len == 0) return false;
    for (name) |c| {
        if (!tchar_lut[c]) return false;
    }
    return true;
}

/// RFC 9110 §5.6.2 `field-value` validation in the wit-bindgen flavour
/// used by the wasi-p3-testsuite: each byte must be SP (0x20), HTAB
/// (0x09), VCHAR (0x21..0x7E), or obs-text (0x80..0xFF). The empty
/// value is valid. The RFC's leading/trailing-whitespace constraint
/// is not enforced — the testsuite explicitly admits
/// `b" \t \t \t \t \t "` as a valid value (#538).
///
/// Comptime LUT (#552): the only invalid bytes are 0x00..0x08, 0x0A..0x1F, 0x7F.
pub const field_value_lut: [256]bool = blk: {
    var t: [256]bool = @splat(false);
    t[0x09] = true;
    t[0x20] = true;
    var c: u8 = 0x21;
    while (c <= 0x7E) : (c += 1) t[c] = true;
    c = 0x80;
    while (true) : (c += 1) {
        t[c] = true;
        if (c == 0xFF) break;
    }
    break :blk t;
};

pub fn isValidFieldValue(value: []const u8) bool {
    for (value) |c| {
        if (!field_value_lut[c]) return false;
    }
    return true;
}

/// RFC 3986 §3.3 `pchar` + `/` + `?` byte set, plus the testsuite
/// carve-out that admits raw UTF-8 (any byte ≥ 0x80) on the wire —
/// see `is_valid_path_char` in `http-request.rs`. Used by
/// `request.set-path-with-query` (#552).
pub const path_char_lut: [256]bool = blk: {
    var t: [256]bool = @splat(false);
    // unreserved: ALPHA / DIGIT / "-" / "." / "_" / "~"
    var c: u8 = '0';
    while (c <= '9') : (c += 1) t[c] = true;
    c = 'A';
    while (c <= 'Z') : (c += 1) t[c] = true;
    c = 'a';
    while (c <= 'z') : (c += 1) t[c] = true;
    for ("-._~") |b| t[b] = true;
    // pct-encoded intro
    t['%'] = true;
    // sub-delims
    for ("!$&'()*+,;=") |b| t[b] = true;
    // pchar extras
    for (":@") |b| t[b] = true;
    // path separator + query intro
    t['/'] = true;
    t['?'] = true;
    // Raw UTF-8 (testsuite carve-out)
    c = 0x80;
    while (true) : (c += 1) {
        t[c] = true;
        if (c == 0xFF) break;
    }
    break :blk t;
};

/// Validate a `path-with-query` byte string against RFC 3986 path-rootless
/// (with raw-UTF-8 carve-out). Empty is accepted by callers and rewritten
/// to `/`; this validator handles non-empty input. Rejects control bytes
/// (0x00..0x1F), DEL (0x7F), and ASCII non-pchar (SP, `"`, `<`, `>`, `[`,
/// `\`, `]`, `^`, `` ` ``, `{`, `|`, `}`, `#`).
pub fn isValidPathWithQuery(path: []const u8) bool {
    for (path) |c| {
        if (!path_char_lut[c]) return false;
    }
    return true;
}

/// `host`-byte set (RFC 3986 §3.2.2 reg-name): unreserved + pct-encoded
/// (`%`) + sub-delims. No `:` (port separator), no `@` (userinfo
/// separator), no `[`/`]` (we don't model IP-literal yet).
pub const host_char_lut: [256]bool = blk: {
    var t: [256]bool = @splat(false);
    var c: u8 = '0';
    while (c <= '9') : (c += 1) t[c] = true;
    c = 'A';
    while (c <= 'Z') : (c += 1) t[c] = true;
    c = 'a';
    while (c <= 'z') : (c += 1) t[c] = true;
    for ("-._~") |b| t[b] = true;
    t['%'] = true;
    for ("!$&'()*+,;=") |b| t[b] = true;
    break :blk t;
};

/// Validate `authority = [userinfo "@"] host [":" port]` per RFC 3986
/// §3.2 (with the simplification that IP-literal `[...]` is not yet
/// supported). Returns `true` for shapes the wasi-p3 `http-request`
/// fixture accepts (#552):
///   - `host`, `host:port`
///   - `userinfo@host`, `userinfo@host:port`
/// The userinfo is allowed to contain `:` (for `user:pass`) and pchar
/// bytes; the host must be a non-empty `reg-name`; `port` must be all
/// ASCII digits (possibly empty per the RFC, but the fixture rejects
/// `example.com:` so we require ≥1 digit). Rejects empty input.
pub fn isValidAuthority(authority: []const u8) bool {
    if (authority.len == 0) return false;
    // Locate the rightmost '@' for userinfo split — userinfo can
    // contain ':' so finding the *first* '@' isn't enough.
    var at_idx: ?usize = null;
    {
        var i: usize = authority.len;
        while (i > 0) {
            i -= 1;
            if (authority[i] == '@') {
                at_idx = i;
                break;
            }
        }
    }
    var hostport_start: usize = 0;
    if (at_idx) |ai| {
        // userinfo = *( unreserved / pct-encoded / sub-delims / ":" )
        const userinfo = authority[0..ai];
        if (userinfo.len == 0) return false; // "@..." invalid
        for (userinfo) |c| {
            if (!host_char_lut[c] and c != ':') return false;
        }
        hostport_start = ai + 1;
    }
    const hostport = authority[hostport_start..];
    if (hostport.len == 0) return false;
    // Split on the *last* ':' (host can't contain ':', but in our
    // simplified non-IP-literal world a colon means port).
    var colon_idx: ?usize = null;
    {
        var i: usize = hostport.len;
        while (i > 0) {
            i -= 1;
            if (hostport[i] == ':') {
                colon_idx = i;
                break;
            }
        }
    }
    const host = if (colon_idx) |ci| hostport[0..ci] else hostport;
    if (host.len == 0) return false;
    for (host) |c| {
        if (!host_char_lut[c]) return false;
    }
    if (colon_idx) |ci| {
        const port = hostport[ci + 1 ..];
        if (port.len == 0) return false; // testsuite rejects `example.com:`
        for (port) |c| {
            if (c < '0' or c > '9') return false; // `localhost:what`
        }
    }
    return true;
}

/// Lower-case ASCII normalisation for HTTP field names. The
/// wasi:http@0.3.0 fixtures expect case-insensitive matching plus
/// stable lower-cased read-back via `copy-all` (#538). Allocator-owned
/// returned slice.
pub fn lowercaseFieldName(allocator: Allocator, name: []const u8) ![]u8 {
    const out = try allocator.alloc(u8, name.len);
    for (name, 0..) |c, i| {
        out[i] = if (c >= 'A' and c <= 'Z') c + 32 else c;
    }
    return out;
}

/// ASCII case-insensitive equality. Used by `set-scheme` to fold
/// `Scheme::Other("HTTP")` back into the canonical `HTTP` variant
/// (#538).
pub fn asciiEqualIgnoreCase(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |ca, cb| {
        const la = if (ca >= 'A' and ca <= 'Z') ca + 32 else ca;
        const lb = if (cb >= 'A' and cb <= 'Z') cb + 32 else cb;
        if (la != lb) return false;
    }
    return true;
}

/// `wasi:http/types.outgoing-request`. The constructor borrows a
/// `fields` handle for headers; mutation goes through `set-*` methods
/// which the default-deny adapter accepts as ok no-ops (real header
/// validation is deferred). String fields are owned host slices.
pub const OutgoingRequest = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    method_disc: u32 = 0, // .get
    method_other: ?[]u8 = null,
    path_with_query: ?[]u8 = null,
    scheme_disc: ?u32 = null,
    scheme_other: ?[]u8 = null,
    authority: ?[]u8 = null,
    headers_handle: u32,
    body_consumed: bool = false,
    body_handle: ?u32 = null,

    pub fn deinit(self: *OutgoingRequest, allocator: Allocator) void {
        if (self.method_other) |s| allocator.free(s);
        if (self.path_with_query) |s| allocator.free(s);
        if (self.scheme_other) |s| allocator.free(s);
        if (self.authority) |s| allocator.free(s);
    }
};

/// `wasi:http/types.incoming-request`. Server mode constructs these from
/// accepted HTTP/1.1 requests; fields are owned by the adapter and exposed
/// through the usual resource handles.
pub const IncomingRequest = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    method_disc: u32 = 0, // .get
    method_other: ?[]u8 = null,
    path_with_query: ?[]u8 = null,
    scheme_disc: ?u32 = null,
    scheme_other: ?[]u8 = null,
    authority: ?[]u8 = null,
    headers_handle: u32 = 0,
    body_consumed: bool = false,
    /// Request body bytes owned by this request until `consume` transfers
    /// them to an `IncomingBody`.
    body_data: ?[]u8 = null,

    pub fn deinit(self: *IncomingRequest, allocator: Allocator) void {
        if (self.method_other) |s| allocator.free(s);
        if (self.path_with_query) |s| allocator.free(s);
        if (self.scheme_other) |s| allocator.free(s);
        if (self.authority) |s| allocator.free(s);
        if (self.body_data) |d| allocator.free(d);
    }
};

/// `wasi:http/types.incoming-response`. Used by the
/// `future-incoming-response.get` happy path once #149 follow-up wires
/// real outbound HTTP (#176).
pub const IncomingResponse = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    status: u16 = 0,
    headers_handle: u32 = 0,
    body_consumed: bool = false,
    /// Response body bytes owned by the adapter. Transferred to
    /// `IncomingBody` on `consume`, freed on drop if unconsumed.
    body_data: ?[]u8 = null,

    pub fn deinit(self: *IncomingResponse, allocator: Allocator) void {
        if (self.body_data) |d| allocator.free(d);
    }
};

/// `wasi:http/types.outgoing-response`.
pub const OutgoingResponse = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    status: u16 = 200,
    headers_handle: u32,
    body_consumed: bool = false,
    body_handle: ?u32 = null,
};

/// `wasi:http/types.incoming-body`. Holds readable body data
/// transferred from `IncomingResponse` on `consume`.
pub const IncomingBody = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    /// Owned body bytes. Freed on drop.
    data: ?[]u8 = null,
    stream_taken: bool = false,

    pub fn deinit(self: *IncomingBody, allocator: Allocator) void {
        if (self.data) |d| allocator.free(d);
        self.data = null;
    }
};

/// `wasi:http/types.outgoing-body`.
pub const OutgoingBody = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    /// Set for server-side response bodies so a live inbound response
    /// session can bind the body stream before response-outparam.set.
    parent_response_handle: ?u32 = null,
    /// Set by `[method]outgoing-body.write` to ensure a second call
    /// returns err per WIT contract.
    stream_taken: bool = false,
    /// Shared owner retained by the body so `finish` can read the bytes
    /// after the guest drops its own output-stream handle.
    stream_owner: ?*OutputStreamOwner = null,

    pub fn deinit(self: *OutgoingBody) void {
        if (self.stream_owner) |owner| owner.release();
        self.stream_owner = null;
    }
};

/// `wasi:http/types.future-incoming-response` (#149, #583 A2).
///
/// The guest awaits this future via `[method]future-incoming-response.subscribe`
/// (producing a `pollable`) and `[method]future-incoming-response.get`
/// (which consumes the result on the first ready call). The adapter
/// resolves the future asynchronously through `PendingHttpFetch`: the
/// real `std.http.Client.fetch` runs on a worker thread, and the
/// adapter's `drainPendingHttpFetches` driver transitions `state`
/// from `.pending` to `.ready_ok` / `.ready_err` once the worker
/// publishes its outcome. Synchronous denial paths (empty allow-list,
/// malformed request, invalid URL) still settle the future to
/// `.ready_err` immediately — only the actual fetch is deferred.
pub const FutureIncomingResponse = struct {
    pub const State = union(enum) {
        pending,
        ready_ok: u32, // incoming-response handle
        ready_err: u32, // HttpErrorCode discriminant
    };

    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    state: State,

    /// True on the second `.get()` call — the WIT says a future must
    /// return `err(())` (the outer result-of-result) once it has been
    /// consumed.
    polled: bool = false,
};

/// `wasi:http/types.future-trailers`. Default-deny resolves to
/// `some(ok(ok(none)))` (no trailers).
pub const FutureTrailers = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    polled: bool = false,
};

pub const UdpStreamPollRef = struct {
    handle: u32,
    parent_handle: u32,
    generation: u32,
};

/// Adapter-owned `wasi:io/poll.pollable` resource metadata.
pub const Pollable = union(enum) {
    immediate,
    monotonic_timer: u64,
    input_stream: u32,
    output_stream: u32,
    tcp_socket: u32,
    udp_socket: u32,
    udp_incoming_stream: UdpStreamPollRef,
    udp_outgoing_stream: UdpStreamPollRef,
    resolve_address_stream: u32,
    http_future_response: u32,
    http_future_trailers: u32,
    /// `wasi:clocks/monotonic-clock@0.2.x` polyfill on a P3 backend (#483):
    /// the pollable wraps a P3 timer-future handle. Goes ready when the
    /// associated `TimerFuture` fires (deadline ≤ `monotonicNs()`).
    /// Stored value is the future handle key into `ComponentInstance.futures`,
    /// which is also the lookup key in `WasiCliAdapter.timer_future_ready`.
    future_timer: u32,
};

const PollBackend = struct {
    fd: std.posix.fd_t,
    events: i16,
    guard: Guard,

    const Guard = union(enum) {
        input_stream: InputStreamTable.Lease,
        output_stream: OutputStreamTable.Lease,
        socket: SocketLease,
        udp_incoming: UdpIncomingStreamTable.Lease,
        udp_outgoing: UdpOutgoingStreamTable.Lease,
        http_future: struct {
            future: FutureIncomingResponseLease,
            operation: PendingHttpFetchTable.Lease,
        },
    };

    fn deinit(self: *PollBackend) void {
        switch (self.guard) {
            .input_stream => |*lease| lease.release(),
            .output_stream => |*lease| lease.release(),
            .socket => |*lease| lease.release(),
            .udp_incoming => |*lease| lease.release(),
            .udp_outgoing => |*lease| lease.release(),
            .http_future => |*guards| {
                guards.operation.release();
                guards.future.release();
            },
        }
    }
};

/// One pending P3 `wait-for` / `wait-until` timer future (#483).
///
/// The future handle lives in `ComponentInstance.futures`; the host
/// completes it when `deadline_ns <= monotonicNs()` by setting the
/// future state to `.ready` and waking any read-waitable.
pub const TimerFuture = struct {
    handle: u32,
    deadline_ns: u64,
};

/// `wasi:http/types.request-options`. Connect timeout is snapshotted
/// into `HttpFetchOptions` and applied to initial DNS/TCP connection
/// acquisition. Zig's lazy TLS handshake and automatic redirect
/// reconnects are not covered by that deadline. First-byte and
/// between-bytes values remain stored for WIT round-tripping only:
/// those phases require a deadline-aware HTTP/TLS reader and remain
/// #616 A1b / A7 work.
pub const RequestOptions = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    connect_timeout_ns: ?u64 = null,
    first_byte_timeout_ns: ?u64 = null,
    between_bytes_timeout_ns: ?u64 = null,
};

/// `wasi:http/types.response-outparam`. Server-side handoff slot. The
/// incoming server reads this after calling the guest's exported
/// `incoming-handler.handle` to decide which HTTP response to serialize.
pub const ResponseOutparam = struct {
    pub const State = union(enum) {
        unset,
        response: u32,
        err: u32,
    };

    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    state: State = .unset,
};

/// `wasi:http/types@0.3.0` unified request resource (#487).
/// Merges 0.2's `incoming-request` + `outgoing-request` into a single
/// resource. Body data lives in `ComponentInstance.streams`; trailers
/// and transmission-result live in `ComponentInstance.futures`. Field
/// strings are owned host slices.
pub const HttpRequestP3 = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    method_disc: u32 = 0, // .get
    method_other: ?[]u8 = null,
    path_with_query: ?[]u8 = null,
    scheme_disc: ?u32 = null,
    scheme_other: ?[]u8 = null,
    authority: ?[]u8 = null,
    headers_handle: u32 = 0,
    options_handle: ?u32 = null,
    /// Owned scalar snapshot taken by `request.new`. The child
    /// request-options resource may be dropped before this request is
    /// sent, so transport behavior must not depend on its table slot.
    fetch_options: HttpFetchOptions = .{},
    /// Handle into `ComponentInstance.streams` (AsyncStream) for the
    /// body stream<u8>. `null` means no body / zero-length.
    body_stream_handle: ?u32 = null,
    /// Handle into `ComponentInstance.futures` for
    /// `future<result<option<trailers>, error-code>>` (trailers channel).
    trailers_future_handle: u32 = 0,
    /// Handle into `ComponentInstance.futures` for
    /// `future<result<_, error-code>>` (transmission result).
    transmission_future_handle: u32 = 0,

    pub fn deinit(self: *HttpRequestP3, allocator: Allocator) void {
        if (self.method_other) |s| allocator.free(s);
        if (self.path_with_query) |s| allocator.free(s);
        if (self.scheme_other) |s| allocator.free(s);
        if (self.authority) |s| allocator.free(s);
    }
};

/// `wasi:http/types@0.3.0` unified response resource (#487).
/// Merges 0.2's `incoming-response` + `outgoing-response`.
pub const HttpResponseP3 = struct {
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    status: u16 = 200,
    headers_handle: u32 = 0,
    /// Handle into `ComponentInstance.streams` for body stream<u8>.
    body_stream_handle: ?u32 = null,
    /// Handle into `ComponentInstance.futures` for trailers future.
    trailers_future_handle: u32 = 0,
    /// Handle into `ComponentInstance.futures` for transmission future.
    transmission_future_handle: u32 = 0,

    pub fn deinit(_: *HttpResponseP3, _: Allocator) void {}
};

const http_live_response_buffer_bytes: usize = 64 * 1024;
const http_live_response_wait_ns: i64 = 10 * std.time.ns_per_ms;

const HttpLiveTerminal = enum(u32) {
    running,
    succeeded,
    client_disconnected,
    io_error,
    handler_error,
    response_error,
    shutdown,
    fallback,
};

const HttpConnectionInterrupt = struct {
    context: ?*anyopaque,
    callback: *const fn (?*anyopaque) void,

    fn run(self: HttpConnectionInterrupt) void {
        self.callback(self.context);
    }
};

const HttpWireWriter = struct {
    context: ?*anyopaque,
    write: *const fn (?*anyopaque, []const u8) streams.StreamResult,
};

const HttpTrailerSnapshot = struct {
    complete: bool = false,
    declaration: ?[]u8 = null,
    block: ?[]u8 = null,
    has_entries: bool = false,

    fn deinit(self: *HttpTrailerSnapshot, allocator: Allocator) void {
        if (self.declaration) |bytes| allocator.free(bytes);
        if (self.block) |bytes| allocator.free(bytes);
        self.* = .{};
    }
};

/// Per-request bridge between a guest-produced P3 body stream and the client
/// socket. Guest callbacks copy into a fixed-size ring; a dedicated writer
/// drains the ring concurrently. The writer never touches component or
/// adapter resource tables, so both conditional-resource specializations keep
/// their ownership rules while response memory stays bounded.
const InboundHttpResponseSession = struct {
    allocator: Allocator,
    adapter: *WasiCliAdapter,
    ci: *ComponentInstance,
    output: *streams.OutputStream,
    keep_alive: bool,
    interrupt: ?HttpConnectionInterrupt,
    wire_writer: ?HttpWireWriter,

    queue: []u8,
    queue_head: usize = 0,
    queue_len: usize = 0,
    max_buffered: usize = 0,
    produced_bytes: usize = 0,
    transmitted_bytes: usize = 0,

    mutex: platform.Mutex = .init,
    parking: parking_lot.ParkingLot = .init(),
    data_epoch: std.atomic.Value(u32) = .init(0),
    space_epoch: std.atomic.Value(u32) = .init(0),
    terminal_epoch: std.atomic.Value(u32) = .init(0),
    terminal: std.atomic.Value(u32) =
        .init(@intFromEnum(HttpLiveTerminal.running)),
    output_started: std.atomic.Value(bool) = .init(false),
    tx_settled: std.atomic.Value(bool) = .init(false),
    guest_cancel_propagated: std.atomic.Value(bool) = .init(false),

    writer_thread: ?std.Thread = null,
    p2_mode: bool = false,
    response_handle: ?u32 = null,
    p2_body_handle: ?u32 = null,
    body_stream_handle: ?u32 = null,
    trailers_future_handle: ?u32 = null,
    transmission_future_handle: ?u32 = null,
    head_bytes: ?[]u8 = null,
    trailer_bytes: ?[]u8 = null,
    head_ready: bool = false,
    trailers_ready: bool = false,
    body_closed: bool = false,
    handler_finished: bool = false,
    handler_validated: bool = false,
    use_chunked: bool = false,
    expected_content_length: ?usize = null,

    fn create(
        allocator: Allocator,
        adapter: *WasiCliAdapter,
        ci: *ComponentInstance,
        output: *streams.OutputStream,
        keep_alive: bool,
        interrupt: ?HttpConnectionInterrupt,
        wire_writer: ?HttpWireWriter,
    ) !*InboundHttpResponseSession {
        const self = try allocator.create(InboundHttpResponseSession);
        errdefer allocator.destroy(self);
        const queue = try allocator.alloc(u8, http_live_response_buffer_bytes);
        self.* = .{
            .allocator = allocator,
            .adapter = adapter,
            .ci = ci,
            .output = output,
            .keep_alive = keep_alive,
            .interrupt = interrupt,
            .wire_writer = wire_writer,
            .queue = queue,
        };
        return self;
    }

    fn start(self: *InboundHttpResponseSession) !void {
        if (comptime builtin.single_threaded) return error.ThreadsUnavailable;
        self.writer_thread = try std.Thread.spawn(
            .{},
            InboundHttpResponseSession.writerMain,
            .{self},
        );
    }

    fn destroy(self: *InboundHttpResponseSession) void {
        if (self.writer_thread != null) {
            _ = self.finishTerminal(.shutdown, true);
            self.waitAndJoin();
        }
        self.detachBodyStream();
        self.parking.deinit();
        if (self.head_bytes) |bytes| self.allocator.free(bytes);
        if (self.trailer_bytes) |bytes| self.allocator.free(bytes);
        self.allocator.free(self.queue);
        const allocator = self.allocator;
        allocator.destroy(self);
    }

    fn currentTerminal(self: *const InboundHttpResponseSession) HttpLiveTerminal {
        return @enumFromInt(self.terminal.load(.acquire));
    }

    fn hasOutputStarted(self: *const InboundHttpResponseSession) bool {
        return self.output_started.load(.acquire);
    }

    fn bufferedHighWater(self: *InboundHttpResponseSession) usize {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.max_buffered;
    }

    fn responseHeadCommitted(
        self: *InboundHttpResponseSession,
        response_handle: u32,
    ) bool {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.response_handle == response_handle and self.head_ready;
    }

    fn wakeAll(self: *InboundHttpResponseSession) void {
        _ = self.data_epoch.fetchAdd(1, .acq_rel);
        _ = self.space_epoch.fetchAdd(1, .acq_rel);
        _ = self.terminal_epoch.fetchAdd(1, .acq_rel);
        _ = self.parking.notify(&self.data_epoch.raw, std.math.maxInt(u32)) catch 0;
        _ = self.parking.notify(&self.space_epoch.raw, std.math.maxInt(u32)) catch 0;
        _ = self.parking.notify(&self.terminal_epoch.raw, std.math.maxInt(u32)) catch 0;
    }

    fn waitEpoch(
        self: *InboundHttpResponseSession,
        epoch: *std.atomic.Value(u32),
        observed: u32,
    ) void {
        _ = self.parking.wait32(
            &epoch.raw,
            observed,
            http_live_response_wait_ns,
        ) catch {
            platform.usleep(100);
            return;
        };
    }

    fn finishTerminal(
        self: *InboundHttpResponseSession,
        terminal: HttpLiveTerminal,
        interrupt: bool,
    ) bool {
        if (terminal == .running) return false;
        if (self.terminal.cmpxchgStrong(
            @intFromEnum(HttpLiveTerminal.running),
            @intFromEnum(terminal),
            .acq_rel,
            .acquire,
        ) != null) return false;
        self.wakeAll();
        if (interrupt) {
            if (self.interrupt) |connection| connection.run();
        }
        return true;
    }

    fn cancelForShutdown(self: *InboundHttpResponseSession) void {
        _ = self.finishTerminal(.shutdown, true);
    }

    fn enqueueRaw(
        self: *InboundHttpResponseSession,
        bytes: []const u8,
    ) bool {
        var offset: usize = 0;
        while (offset < bytes.len) {
            if (http_shutdown_requested.load(.acquire)) {
                self.cancelForShutdown();
                self.propagateTerminalToGuest();
                return false;
            }
            if (self.currentTerminal() != .running) {
                self.propagateTerminalToGuest();
                return false;
            }

            self.mutex.lock();
            const available = self.queue.len - self.queue_len;
            if (available == 0) {
                const observed = self.space_epoch.load(.acquire);
                self.mutex.unlock();
                self.waitEpoch(&self.space_epoch, observed);
                continue;
            }

            const take = @min(available, bytes.len - offset);
            const tail = (self.queue_head + self.queue_len) % self.queue.len;
            const first = @min(take, self.queue.len - tail);
            @memcpy(self.queue[tail .. tail + first], bytes[offset .. offset + first]);
            if (first < take) {
                @memcpy(
                    self.queue[0 .. take - first],
                    bytes[offset + first .. offset + take],
                );
            }
            self.queue_len += take;
            self.max_buffered = @max(self.max_buffered, self.queue_len);
            self.mutex.unlock();

            offset += take;
            _ = self.data_epoch.fetchAdd(1, .acq_rel);
            _ = self.parking.notify(&self.data_epoch.raw, 1) catch 0;
        }
        return true;
    }

    fn enqueuePrebuffered(
        self: *InboundHttpResponseSession,
        bytes: []const u8,
    ) bool {
        if (bytes.len == 0) return true;
        self.mutex.lock();
        defer self.mutex.unlock();
        if (bytes.len > self.queue.len - self.queue_len) return false;
        const tail = (self.queue_head + self.queue_len) % self.queue.len;
        const first = @min(bytes.len, self.queue.len - tail);
        @memcpy(self.queue[tail .. tail + first], bytes[0..first]);
        if (first < bytes.len) {
            @memcpy(self.queue[0 .. bytes.len - first], bytes[first..]);
        }
        self.queue_len += bytes.len;
        self.produced_bytes += bytes.len;
        self.max_buffered = @max(self.max_buffered, self.queue_len);
        _ = self.data_epoch.fetchAdd(1, .acq_rel);
        _ = self.parking.notify(&self.data_epoch.raw, 1) catch 0;
        return true;
    }

    fn dequeue(
        self: *InboundHttpResponseSession,
        dst: []u8,
    ) usize {
        self.mutex.lock();
        const take = @min(dst.len, self.queue_len);
        if (take == 0) {
            self.mutex.unlock();
            return 0;
        }
        const first = @min(take, self.queue.len - self.queue_head);
        @memcpy(dst[0..first], self.queue[self.queue_head .. self.queue_head + first]);
        if (first < take) {
            @memcpy(dst[first..take], self.queue[0 .. take - first]);
        }
        self.queue_head = (self.queue_head + take) % self.queue.len;
        self.queue_len -= take;
        self.mutex.unlock();
        _ = self.space_epoch.fetchAdd(1, .acq_rel);
        _ = self.parking.notify(&self.space_epoch.raw, 1) catch 0;
        return take;
    }

    fn appendFmt(
        self: *InboundHttpResponseSession,
        list: *std.ArrayListUnmanaged(u8),
        comptime fmt: []const u8,
        args: anytype,
    ) !void {
        const rendered = try std.fmt.allocPrint(self.allocator, fmt, args);
        defer self.allocator.free(rendered);
        try list.appendSlice(self.allocator, rendered);
    }

    fn snapshotTrailers(
        self: *InboundHttpResponseSession,
        future_handle: u32,
        force_complete: bool,
    ) !HttpTrailerSnapshot {
        var result: HttpTrailerSnapshot = .{};
        var fields_handle: ?u32 = null;

        var future_lease = self.ci.futures.acquire(future_handle) orelse {
            result.complete = true;
            return result;
        };
        const future = future_lease.value();
        const complete = future.state != .pending or future.write_closed;
        if (!complete and !force_complete) {
            future_lease.release();
            return result;
        }
        result.complete = true;
        if (complete) {
            if (future.payload) |payload| {
                if (payload.len >= 8 and payload[0] == 1) {
                    fields_handle = std.mem.readInt(
                        u32,
                        payload[4..8],
                        .little,
                    );
                }
            }
        }
        future_lease.release();

        const handle = fields_handle orelse return result;
        var fields_lease = self.adapter.lookupHttpFields(handle) orelse return result;
        defer fields_lease.release();
        const fields = fields_lease.value().*;

        var declaration: std.ArrayListUnmanaged(u8) = .empty;
        defer declaration.deinit(self.allocator);
        var block: std.ArrayListUnmanaged(u8) = .empty;
        defer block.deinit(self.allocator);
        var first = true;
        for (fields.entries.items) |entry| {
            if (WasiCliAdapter.isHopByHopOrFramingHeader(entry.name)) continue;
            if (!WasiCliAdapter.httpHeaderNameValid(entry.name) or
                !WasiCliAdapter.httpHeaderValueValid(entry.value))
            {
                continue;
            }
            if (first) {
                try declaration.appendSlice(self.allocator, "Trailer: ");
            } else {
                try declaration.appendSlice(self.allocator, ", ");
            }
            try declaration.appendSlice(self.allocator, entry.name);
            try self.appendFmt(
                &block,
                "{s}: {s}\r\n",
                .{ entry.name, entry.value },
            );
            first = false;
        }
        if (first) return result;
        try declaration.appendSlice(self.allocator, "\r\n");
        result.declaration = try declaration.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(result.declaration.?);
        result.block = try block.toOwnedSlice(self.allocator);
        result.has_entries = true;
        return result;
    }

    fn prepareP3Head(
        self: *InboundHttpResponseSession,
        response_handle: u32,
    ) !void {
        self.mutex.lock();
        const already_ready = self.head_ready;
        self.mutex.unlock();
        if (already_ready) return;

        var response_lease = self.adapter.lookupHttpResponseP3(response_handle) orelse
            return error.InvalidHandle;
        const response = response_lease.value().*;
        const status: u16 =
            if (response.status >= 100 and response.status <= 999)
                response.status
            else
                500;
        const headers_handle = response.headers_handle;
        const body_stream_handle = response.body_stream_handle;
        const trailers_future_handle = response.trailers_future_handle;
        const transmission_future_handle = response.transmission_future_handle;
        response_lease.release();

        var trailers = try self.snapshotTrailers(
            trailers_future_handle,
            false,
        );
        defer trailers.deinit(self.allocator);

        var head: std.ArrayListUnmanaged(u8) = .empty;
        defer head.deinit(self.allocator);
        try self.appendFmt(
            &head,
            "HTTP/1.1 {d} {s}\r\n",
            .{ status, WasiCliAdapter.httpResponseStatusReason(status) },
        );

        var content_length: ?usize = null;
        var fields_lease = self.adapter.lookupHttpFields(headers_handle);
        defer if (fields_lease) |*lease| lease.release();
        if (fields_lease) |*lease| {
            const fields = lease.value().*;
            for (fields.entries.items) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.name, "content-length")) {
                    const trimmed = std.mem.trim(u8, entry.value, " \t");
                    const parsed = std.fmt.parseInt(usize, trimmed, 10) catch
                        return error.InvalidContentLength;
                    if (content_length) |known| {
                        if (known != parsed) return error.InvalidContentLength;
                    } else {
                        content_length = parsed;
                    }
                    continue;
                }
                if (WasiCliAdapter.isHopByHopOrFramingHeader(entry.name)) continue;
                if (!WasiCliAdapter.httpHeaderNameValid(entry.name) or
                    !WasiCliAdapter.httpHeaderValueValid(entry.value))
                {
                    return error.InvalidHeader;
                }
                try self.appendFmt(
                    &head,
                    "{s}: {s}\r\n",
                    .{ entry.name, entry.value },
                );
            }
            fields.immutable = true;
        }
        if (trailers.declaration) |declaration| {
            try head.appendSlice(self.allocator, declaration);
        }

        const has_body = body_stream_handle != null;
        const use_chunked = trailers.has_entries or
            (!trailers.complete and has_body) or
            (has_body and content_length == null);
        const expected_content_length: ?usize = if (use_chunked)
            null
        else if (has_body)
            content_length orelse 0
        else
            0;

        if (use_chunked) {
            try head.appendSlice(self.allocator, "Transfer-Encoding: chunked\r\n");
        } else {
            try self.appendFmt(
                &head,
                "Content-Length: {d}\r\n",
                .{expected_content_length.?},
            );
        }
        try head.appendSlice(
            self.allocator,
            if (self.keep_alive)
                "Connection: keep-alive\r\n\r\n"
            else
                "Connection: close\r\n\r\n",
        );

        const owned_head = try head.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(owned_head);
        const owned_trailers = trailers.block;
        trailers.block = null;

        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.head_ready) {
            self.allocator.free(owned_head);
            if (owned_trailers) |bytes| self.allocator.free(bytes);
            return;
        }
        if (self.currentTerminal() != .running) {
            self.allocator.free(owned_head);
            if (owned_trailers) |bytes| self.allocator.free(bytes);
            return error.ResponseCancelled;
        }
        self.response_handle = response_handle;
        self.body_stream_handle = body_stream_handle;
        self.trailers_future_handle = trailers_future_handle;
        self.transmission_future_handle = transmission_future_handle;
        self.head_bytes = owned_head;
        self.head_ready = true;
        self.use_chunked = use_chunked;
        self.expected_content_length = expected_content_length;
        if (trailers.complete) {
            self.trailer_bytes = owned_trailers;
            self.trailers_ready = true;
        } else if (owned_trailers) |bytes| {
            self.allocator.free(bytes);
        }
        _ = self.data_epoch.fetchAdd(1, .acq_rel);
        _ = self.parking.notify(&self.data_epoch.raw, 1) catch 0;
    }

    fn prepareP2Head(
        self: *InboundHttpResponseSession,
        response_handle: u32,
    ) !void {
        self.mutex.lock();
        const already_ready = self.head_ready;
        self.mutex.unlock();
        if (already_ready) return;

        var response_lease = self.adapter.lookupOutgoingResponse(
            response_handle,
        ) orelse return error.InvalidHandle;
        const response = response_lease.value().*;
        const status: u16 =
            if (response.status >= 100 and response.status <= 999)
                response.status
            else
                500;
        const headers_handle = response.headers_handle;
        const body_handle = response.body_handle;
        response_lease.release();

        var head: std.ArrayListUnmanaged(u8) = .empty;
        defer head.deinit(self.allocator);
        try self.appendFmt(
            &head,
            "HTTP/1.1 {d} {s}\r\n",
            .{ status, WasiCliAdapter.httpResponseStatusReason(status) },
        );

        var content_length: ?usize = null;
        var fields_lease = self.adapter.lookupHttpFields(headers_handle);
        defer if (fields_lease) |*lease| lease.release();
        if (fields_lease) |*lease| {
            const fields = lease.value().*;
            for (fields.entries.items) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.name, "content-length")) {
                    const trimmed = std.mem.trim(u8, entry.value, " \t");
                    const parsed = std.fmt.parseInt(
                        usize,
                        trimmed,
                        10,
                    ) catch return error.InvalidContentLength;
                    if (content_length) |known| {
                        if (known != parsed) return error.InvalidContentLength;
                    } else {
                        content_length = parsed;
                    }
                    continue;
                }
                if (WasiCliAdapter.isHopByHopOrFramingHeader(entry.name)) continue;
                if (!WasiCliAdapter.httpHeaderNameValid(entry.name) or
                    !WasiCliAdapter.httpHeaderValueValid(entry.value))
                {
                    return error.InvalidHeader;
                }
                try self.appendFmt(
                    &head,
                    "{s}: {s}\r\n",
                    .{ entry.name, entry.value },
                );
            }
            fields.immutable = true;
        }

        const has_body = body_handle != null;
        const use_chunked = has_body and content_length == null;
        const expected_content_length: ?usize = if (use_chunked)
            null
        else if (has_body)
            content_length orelse 0
        else
            0;
        if (use_chunked) {
            try head.appendSlice(
                self.allocator,
                "Transfer-Encoding: chunked\r\n",
            );
        } else {
            try self.appendFmt(
                &head,
                "Content-Length: {d}\r\n",
                .{expected_content_length.?},
            );
        }
        try head.appendSlice(
            self.allocator,
            "Connection: close\r\n\r\n",
        );

        const owned_head = try head.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(owned_head);
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.head_ready) {
            self.allocator.free(owned_head);
            return;
        }
        if (self.currentTerminal() != .running) {
            self.allocator.free(owned_head);
            return error.ResponseCancelled;
        }
        self.p2_mode = true;
        self.response_handle = response_handle;
        self.p2_body_handle = body_handle;
        self.head_bytes = owned_head;
        self.head_ready = true;
        self.trailers_ready = true;
        self.use_chunked = use_chunked;
        self.expected_content_length = expected_content_length;
        _ = self.data_epoch.fetchAdd(1, .acq_rel);
        _ = self.parking.notify(&self.data_epoch.raw, 1) catch 0;
    }

    fn refreshTrailers(
        self: *InboundHttpResponseSession,
        force_complete: bool,
    ) void {
        self.mutex.lock();
        if (self.trailers_ready) {
            self.mutex.unlock();
            return;
        }
        const future_handle = self.trailers_future_handle;
        self.mutex.unlock();
        const handle = future_handle orelse return;

        var snapshot = self.snapshotTrailers(handle, force_complete) catch {
            if (force_complete) {
                self.mutex.lock();
                self.trailers_ready = true;
                self.mutex.unlock();
                self.wakeAll();
            }
            return;
        };
        defer snapshot.deinit(self.allocator);
        if (!snapshot.complete) return;

        const block = snapshot.block;
        snapshot.block = null;
        self.mutex.lock();
        if (!self.trailers_ready) {
            self.trailer_bytes = block;
            self.trailers_ready = true;
        } else if (block) |bytes| {
            self.allocator.free(bytes);
        }
        self.mutex.unlock();
        self.wakeAll();
    }

    fn attachP3Response(
        self: *InboundHttpResponseSession,
        response_handle: u32,
        body_stream_handle: ?u32,
        trailers_future_handle: u32,
        transmission_future_handle: u32,
    ) bool {
        self.mutex.lock();
        if (self.response_handle) |known| {
            const matches = known == response_handle;
            self.mutex.unlock();
            return matches;
        }
        self.response_handle = response_handle;
        self.body_stream_handle = body_stream_handle;
        self.trailers_future_handle = trailers_future_handle;
        self.transmission_future_handle = transmission_future_handle;
        self.mutex.unlock();

        const stream_handle = body_stream_handle orelse return true;
        var stream_lease = self.ci.streams.acquire(stream_handle) orelse {
            self.clearCandidate(response_handle);
            return false;
        };
        const stream = stream_lease.value();
        if (stream.host_handler != null or
            stream.host_driver != null or
            stream.buffer.items.len > self.queue.len)
        {
            stream_lease.release();
            self.clearCandidate(response_handle);
            return false;
        }

        const buffered = self.allocator.dupe(
            u8,
            stream.buffer.items,
        ) catch {
            stream_lease.release();
            self.clearCandidate(response_handle);
            return false;
        };
        const already_closed = stream.write_closed;
        const pending_writer = stream.pending_write != null;
        const write_waitable = stream.write_waitable;
        stream.pending_write = null;
        if (pending_writer) stream.write_ready = true;
        stream.buffer.deinit(self.ci.allocator);
        stream.buffer = .empty;
        stream.host_handler = .{
            .on_write = &InboundHttpResponseSession.onBodyWrite,
            .on_drop_writable = &InboundHttpResponseSession.onBodyClosed,
            .ctx = self,
        };
        stream_lease.release();
        if (pending_writer) {
            _ = self.ci.notifyWaitable(
                write_waitable,
                async_canon.packStatus(.completed, 0),
            );
        }

        if (!self.enqueuePrebuffered(buffered)) {
            self.allocator.free(buffered);
            self.detachBodyStream();
            self.clearCandidate(response_handle);
            return false;
        }
        self.allocator.free(buffered);
        if (already_closed) self.markBodyClosed();
        return true;
    }

    fn attachP2Response(
        self: *InboundHttpResponseSession,
        response_handle: u32,
        body_handle: ?u32,
    ) bool {
        self.mutex.lock();
        if (self.response_handle) |known| {
            const matches = self.p2_mode and known == response_handle and
                self.p2_body_handle == body_handle;
            self.mutex.unlock();
            return matches;
        }
        self.p2_mode = true;
        self.response_handle = response_handle;
        self.p2_body_handle = body_handle;
        self.mutex.unlock();
        return true;
    }

    fn attachP2Body(
        self: *InboundHttpResponseSession,
        response_handle: u32,
        body_handle: u32,
    ) bool {
        return self.attachP2Response(
            response_handle,
            body_handle,
        );
    }

    fn closeP2Body(
        self: *InboundHttpResponseSession,
        body_handle: u32,
    ) void {
        self.mutex.lock();
        const matches = self.p2_mode and
            self.p2_body_handle == body_handle;
        self.mutex.unlock();
        if (matches) self.markBodyClosed();
    }

    fn clearCandidate(
        self: *InboundHttpResponseSession,
        response_handle: u32,
    ) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.response_handle == response_handle and !self.head_ready) {
            self.response_handle = null;
            self.body_stream_handle = null;
            self.trailers_future_handle = null;
            self.transmission_future_handle = null;
        }
    }

    fn detachBodyStream(self: *InboundHttpResponseSession) void {
        self.mutex.lock();
        if (self.p2_mode) {
            const body_handle = self.p2_body_handle;
            self.mutex.unlock();
            const handle = body_handle orelse return;
            var body_lease = self.adapter.lookupOutgoingBody(handle) orelse return;
            const owner = body_lease.value().*.stream_owner;
            if (owner) |retained| retained.retain();
            body_lease.release();
            const retained = owner orelse return;
            defer retained.release();
            retained.operation_claim.acquire();
            defer retained.operation_claim.release();
            switch (retained.stream.sink) {
                .callback => |callback| {
                    if (callback.context == @as(?*anyopaque, @ptrCast(self))) {
                        retained.stream.sink = .closed;
                    }
                },
                else => {},
            }
            return;
        }
        const body_stream_handle = self.body_stream_handle;
        self.mutex.unlock();
        const handle = body_stream_handle orelse return;
        var stream_lease = self.ci.streams.acquire(handle) orelse return;
        const stream = stream_lease.value();
        if (stream.host_handler) |handler| {
            if (handler.ctx == @as(?*anyopaque, @ptrCast(self))) {
                stream.host_handler = null;
            }
        }
        stream_lease.release();
    }

    fn onBodyWrite(ctx: ?*anyopaque, bytes: []const u8) bool {
        const self: *InboundHttpResponseSession =
            @ptrCast(@alignCast(ctx.?));
        const response_handle = self.response_handle orelse return false;
        const prepare = if (self.p2_mode)
            self.prepareP2Head(response_handle)
        else
            self.prepareP3Head(response_handle);
        prepare catch {
            _ = self.finishTerminal(.response_error, false);
            self.propagateTerminalToGuest();
            return false;
        };

        self.mutex.lock();
        if (self.expected_content_length) |expected| {
            if (bytes.len > expected -| self.produced_bytes) {
                self.mutex.unlock();
                _ = self.finishTerminal(.response_error, true);
                self.propagateTerminalToGuest();
                return false;
            }
        }
        self.produced_bytes += bytes.len;
        self.mutex.unlock();

        if (!self.enqueueRaw(bytes)) return false;
        return true;
    }

    fn onBodyClosed(ctx: ?*anyopaque) void {
        const self: *InboundHttpResponseSession =
            @ptrCast(@alignCast(ctx.?));
        self.markBodyClosed();
    }

    fn markBodyClosed(self: *InboundHttpResponseSession) void {
        self.refreshTrailers(false);
        var length_matches = true;
        self.mutex.lock();
        self.body_closed = true;
        if (self.expected_content_length) |expected| {
            length_matches = self.produced_bytes == expected;
        }
        self.handler_validated = length_matches;
        self.mutex.unlock();
        if (!length_matches) {
            _ = self.finishTerminal(.response_error, true);
            return;
        }
        self.wakeAll();
    }

    fn attachReturnedResponse(
        self: *InboundHttpResponseSession,
        response_handle: u32,
    ) bool {
        self.mutex.lock();
        const candidate = self.response_handle;
        const has_queued = self.queue_len != 0 or self.produced_bytes != 0;
        self.mutex.unlock();
        if (candidate) |known| {
            if (known == response_handle) return true;
            if (!self.hasOutputStarted() and !has_queued) {
                _ = self.finishTerminal(.fallback, false);
            } else {
                _ = self.finishTerminal(.response_error, true);
            }
            return false;
        }

        var response_lease = self.adapter.lookupHttpResponseP3(response_handle) orelse {
            _ = self.finishTerminal(.response_error, false);
            return false;
        };
        const response = response_lease.value().*;
        const body_handle = response.body_stream_handle;
        const trailers_handle = response.trailers_future_handle;
        const transmission_handle = response.transmission_future_handle;
        response_lease.release();
        if (!self.attachP3Response(
            response_handle,
            body_handle,
            trailers_handle,
            transmission_handle,
        )) {
            _ = self.finishTerminal(.fallback, false);
            return false;
        }
        return true;
    }

    fn handlerReturned(
        self: *InboundHttpResponseSession,
        response_handle: u32,
    ) void {
        if (!self.attachReturnedResponse(response_handle)) return;
        self.mutex.lock();
        self.handler_finished = true;
        self.body_closed = true;
        self.mutex.unlock();
        self.prepareP3Head(response_handle) catch {
            _ = self.finishTerminal(.response_error, false);
            return;
        };
        self.refreshTrailers(true);

        var length_matches = true;
        self.mutex.lock();
        if (self.expected_content_length) |expected| {
            length_matches = self.produced_bytes == expected;
        }
        self.handler_validated = length_matches;
        self.mutex.unlock();
        if (!length_matches) {
            _ = self.finishTerminal(.response_error, true);
            return;
        }
        self.wakeAll();
    }

    fn handlerReturnedP2(
        self: *InboundHttpResponseSession,
        outparam_handle: u32,
    ) bool {
        var outparam_lease = self.adapter.lookupResponseOutparam(
            outparam_handle,
        ) orelse {
            _ = self.finishTerminal(.fallback, false);
            return false;
        };
        const outparam = outparam_lease.value().*;
        const state = outparam.state;
        outparam_lease.release();
        const response_handle = switch (state) {
            .response => |handle| handle,
            .unset, .err => {
                _ = self.finishTerminal(.fallback, false);
                return false;
            },
        };

        self.mutex.lock();
        const known_response = self.response_handle;
        const known_body = self.p2_body_handle;
        self.mutex.unlock();
        const body_handle = if (known_response == response_handle)
            known_body
        else blk: {
            var response_lease = self.adapter.lookupOutgoingResponse(
                response_handle,
            ) orelse {
                _ = self.finishTerminal(.fallback, false);
                return false;
            };
            const response = response_lease.value().*;
            const handle = response.body_handle;
            response_lease.release();
            break :blk handle;
        };
        if (!self.attachP2Response(response_handle, body_handle)) {
            self.mutex.lock();
            const response_started = self.head_ready or
                self.produced_bytes != 0 or
                self.queue_len != 0;
            self.mutex.unlock();
            _ = self.finishTerminal(
                if (response_started) .response_error else .fallback,
                response_started,
            );
            return false;
        }

        self.mutex.lock();
        self.handler_finished = true;
        self.body_closed = true;
        self.mutex.unlock();
        self.prepareP2Head(response_handle) catch {
            _ = self.finishTerminal(.response_error, false);
            return false;
        };

        var length_matches = true;
        self.mutex.lock();
        if (self.expected_content_length) |expected| {
            length_matches = self.produced_bytes == expected;
        }
        self.handler_validated = length_matches;
        self.mutex.unlock();
        if (!length_matches) {
            _ = self.finishTerminal(.response_error, true);
            return false;
        }
        self.wakeAll();
        return true;
    }

    fn handlerFailed(self: *InboundHttpResponseSession) void {
        self.mutex.lock();
        self.handler_finished = true;
        self.body_closed = true;
        const writer_may_be_in_io = self.head_ready and
            (self.produced_bytes != 0 or self.queue_len != 0);
        self.mutex.unlock();
        _ = self.finishTerminal(.handler_error, writer_may_be_in_io);
    }

    fn writeWire(
        self: *InboundHttpResponseSession,
        bytes: []const u8,
    ) !void {
        if (self.wire_writer) |writer| {
            return switch (writer.write(writer.context, bytes)) {
                .ok => |n| if (n == bytes.len) {} else error.IoError,
                .closed => error.HttpClientDisconnected,
                .err => error.IoError,
            };
        }
        try self.adapter.writeAllOutputStream(self.output, bytes);
    }

    fn writeBodyChunk(
        self: *InboundHttpResponseSession,
        bytes: []const u8,
    ) !void {
        if (!self.use_chunked) {
            try self.writeWire(bytes);
            return;
        }
        var size_buf: [32]u8 = undefined;
        const size_line = try std.fmt.bufPrint(&size_buf, "{x}\r\n", .{bytes.len});
        try self.writeWire(size_line);
        try self.writeWire(bytes);
        try self.writeWire("\r\n");
    }

    fn failWrite(
        self: *InboundHttpResponseSession,
        err: anyerror,
    ) void {
        const terminal: HttpLiveTerminal =
            if (err == error.HttpClientDisconnected)
                .client_disconnected
            else
                .io_error;
        _ = self.finishTerminal(terminal, false);
    }

    fn writerMain(self: *InboundHttpResponseSession) void {
        var chunk: [http_live_response_buffer_bytes]u8 = undefined;
        var head_written = false;

        while (self.currentTerminal() == .running) {
            if (!head_written) {
                self.mutex.lock();
                const may_write_head = self.head_ready and
                    (self.queue_len > 0 or self.handler_finished);
                const head = if (may_write_head) self.head_bytes else null;
                const observed = self.data_epoch.load(.acquire);
                self.mutex.unlock();
                if (head) |bytes| {
                    self.writeWire(bytes) catch |err| {
                        self.failWrite(err);
                        return;
                    };
                    self.output_started.store(true, .release);
                    head_written = true;
                    continue;
                }
                self.waitEpoch(&self.data_epoch, observed);
                continue;
            }

            const count = self.dequeue(&chunk);
            if (count > 0) {
                self.writeBodyChunk(chunk[0..count]) catch |err| {
                    self.failWrite(err);
                    return;
                };
                self.mutex.lock();
                self.transmitted_bytes += count;
                self.mutex.unlock();
                continue;
            }

            self.mutex.lock();
            const finished = self.handler_validated and self.body_closed;
            const trailers_ready = self.trailers_ready;
            const trailers = self.trailer_bytes;
            const observed = self.data_epoch.load(.acquire);
            self.mutex.unlock();
            if (finished and trailers_ready) {
                if (self.use_chunked) {
                    self.writeWire("0\r\n") catch |err| {
                        self.failWrite(err);
                        return;
                    };
                    if (trailers) |bytes| {
                        self.writeWire(bytes) catch |err| {
                            self.failWrite(err);
                            return;
                        };
                    }
                    self.writeWire("\r\n") catch |err| {
                        self.failWrite(err);
                        return;
                    };
                }
                _ = self.finishTerminal(.succeeded, false);
                return;
            }
            self.waitEpoch(&self.data_epoch, observed);
        }
    }

    fn waitAndJoin(self: *InboundHttpResponseSession) void {
        const thread = self.writer_thread orelse return;
        while (self.currentTerminal() == .running) {
            if (http_shutdown_requested.load(.acquire)) {
                self.cancelForShutdown();
            }
            const observed = self.terminal_epoch.load(.acquire);
            if (self.currentTerminal() != .running) break;
            self.waitEpoch(&self.terminal_epoch, observed);
        }
        thread.join();
        self.writer_thread = null;
    }

    fn settleTransmission(
        self: *InboundHttpResponseSession,
        succeeded: bool,
    ) bool {
        if (self.tx_settled.swap(true, .acq_rel)) return false;
        const handle = self.transmission_future_handle orelse return false;
        return settleHttpResponseTransmissionFuture(
            self.ci,
            handle,
            succeeded,
        );
    }

    fn propagateTerminalToGuest(self: *InboundHttpResponseSession) void {
        const terminal = self.currentTerminal();
        if (terminal == .running or terminal == .fallback) return;
        _ = self.settleTransmission(terminal == .succeeded);
        if (terminal == .succeeded) return;

        if (execution_context.current()) |thread_ctx| {
            if (self.guest_cancel_propagated.swap(true, .acq_rel)) return;
            thread_ctx.requestCancellation();
            if (thread_ctx.taskManager(async_mod.TaskManager)) |task_manager| {
                if (task_manager.currentTask()) |task_handle| {
                    task_manager.cancelTask(task_handle);
                }
            }
        }
        WasiCliAdapter.cancelAllPendingAsyncOps(
            self.adapter,
            self.ci,
            null,
            self.allocator,
        );
    }

    fn driveGuestEvents(self: *InboundHttpResponseSession) bool {
        if (http_shutdown_requested.load(.acquire)) {
            self.cancelForShutdown();
        }
        self.refreshTrailers(false);
        const terminal = self.currentTerminal();
        if (terminal == .running or terminal == .fallback) return false;
        const fired = self.settleTransmission(terminal == .succeeded);
        if (terminal != .succeeded) self.propagateTerminalToGuest();
        return fired;
    }
};

pub fn inboundHttpStreamBufferLimit(
    thread_ctx: ?*execution_context.ThreadExecutionContext,
) ?usize {
    const active = thread_ctx orelse return null;
    const session = active.hostTaskContext(
        InboundHttpResponseSession,
    ) orelse return null;
    if (session.currentTerminal() != .running) return null;
    return http_live_response_buffer_bytes;
}

fn settleHttpResponseTransmissionFuture(
    ci: *ComponentInstance,
    future_handle: u32,
    succeeded: bool,
) bool {
    var future_lease = ci.futures.acquire(future_handle) orelse return false;
    const future = future_lease.value();
    if (future.read_closed) {
        future_lease.release();
        return false;
    }
    future.pending_read = null;
    future.state = if (succeeded) .ready else .closed;
    future.write_closed = true;
    const registration = future.read_waitable;
    future_lease.release();
    _ = ci.notifyWaitable(
        registration,
        if (succeeded)
            async_canon.packStatus(.completed, 0)
        else
            async_canon.packStatus(.dropped, 0),
    );
    return true;
}

/// `(string, string)` pair forwarded to `wasi:cli/environment.get-environment`.
/// The slices are borrowed by the adapter — the caller is responsible for
/// keeping them alive across the run.
pub const EnvVar = struct {
    name: []const u8,
    value: []const u8,
};

/// Severity for `wasi:logging/logging.log` (#583 B5). Discriminant
/// order matches the WIT `enum level { trace, debug, info, warn,
/// error, critical }` so `@as(WasiLogLevel, @enumFromInt(d))` round-trips
/// the canonical-ABI `enum_val` discriminant directly.
///
/// Used both as the per-call argument from the guest and as the
/// `WasiCliAdapter.log_level` filter (lower → admit fewer calls).
pub const WasiLogLevel = enum(u32) {
    trace = 0,
    debug = 1,
    info = 2,
    warn = 3,
    err = 4,
    critical = 5,

    /// Parse a case-insensitive level name. Accepts both the WIT
    /// spelling (`error`) and the more common `err` shorthand.
    /// Returns `null` for unknown names — callers (CLI / env-var
    /// parsing) emit a usage-style diagnostic in that case.
    pub fn fromString(s: []const u8) ?WasiLogLevel {
        const eqlIgnoreCase = std.ascii.eqlIgnoreCase;
        if (eqlIgnoreCase(s, "trace")) return .trace;
        if (eqlIgnoreCase(s, "debug")) return .debug;
        if (eqlIgnoreCase(s, "info")) return .info;
        if (eqlIgnoreCase(s, "warn") or eqlIgnoreCase(s, "warning")) return .warn;
        if (eqlIgnoreCase(s, "error") or eqlIgnoreCase(s, "err")) return .err;
        if (eqlIgnoreCase(s, "critical") or eqlIgnoreCase(s, "fatal")) return .critical;
        return null;
    }

    /// Lowercase WIT spelling (`error`, not `err`) for inclusion in
    /// formatted log lines.
    pub fn name(self: WasiLogLevel) []const u8 {
        return switch (self) {
            .trace => "trace",
            .debug => "debug",
            .info => "info",
            .warn => "warn",
            .err => "error",
            .critical => "critical",
        };
    }

    /// Project onto `std.log.Level`. `trace`/`debug` collapse to
    /// `.debug` (std.log has no finer-grained level); `error`/`critical`
    /// collapse to `.err`. Mirrors the wasmtime adapter and matches
    /// the README compatibility note in `docs/wasi.md`.
    pub fn toStdLogLevel(self: WasiLogLevel) std.log.Level {
        return switch (self) {
            .trace, .debug => .debug,
            .info => .info,
            .warn => .warn,
            .err, .critical => .err,
        };
    }
};

/// `wasi:keyvalue/store@0.2.0-draft2` `bucket` resource (#583 B4).
///
/// A memory-store backed bucket. The `identifier` field is the name
/// the guest passed to `store.open(...)` — kept around so future
/// snapshot / debug logging surfaces can identify the bucket.
///
/// `entries` is a `std.StringHashMapUnmanaged([]const u8)` whose
/// keys and values are both owned by the adapter's allocator — `set`
/// duplicates both sides, `delete` frees both sides, and `deinit`
/// mops up any leftover entries when the bucket is dropped or when
/// the whole adapter tears down. The map's iteration order is
/// unspecified, which matches the WIT contract for `list-keys`.
pub const KeyvalueBucket = struct {
    identifier: []const u8,
    entries: std.StringHashMapUnmanaged([]const u8) = .empty,
    operation_claim: stable_resource.ConditionalOperationClaim = .init,

    pub fn deinit(self: *KeyvalueBucket, allocator: Allocator) void {
        var it = self.entries.iterator();
        while (it.next()) |e| {
            allocator.free(e.key_ptr.*);
            allocator.free(e.value_ptr.*);
        }
        self.entries.deinit(allocator);
        allocator.free(self.identifier);
    }
};

/// `wasi:keyvalue/store.error` variant discriminants in WIT-declaration
/// order. The `other` arm carries a `string` payload; the other two are
/// unit-typed.
pub const KeyvalueErrorTag = enum(u32) {
    no_such_store = 0,
    access_denied = 1,
    other = 2,
};

/// `wasi:keyvalue/atomics.cas-error` variant discriminants in
/// WIT-declaration order (#583 B4 follow-up). `store-error` carries
/// the inner `keyvalue/store.error`; `cas-failed` carries a fresh
/// `own<cas>` handle with an updated snapshot so the guest can
/// retry without re-issuing `cas.new`.
pub const KeyvalueCasErrorTag = enum(u32) {
    store_error = 0,
    cas_failed = 1,
};

/// Cap on a single bucket's key count — `list-keys` paginates above
/// this. The chosen value is small enough that exhausting it in a
/// single call is cheap and large enough that the pagination path is
/// rarely exercised in practice. Both `cursor`-driven continuation
/// and a fresh `list-keys(none)` call work correctly across paging
/// boundaries.
const KEYVALUE_LIST_KEYS_PAGE_SIZE: usize = 128;

/// `wasi:keyvalue/atomics.cas` resource rep (#583 B4 follow-up).
///
/// A CAS handle captures the bucket identifier + key + a snapshot of
/// the value at construction time. `atomics.swap` consumes the handle:
/// if the bucket's current value matches the snapshot, the new value
/// is written and the call returns `ok`; otherwise the handle is
/// re-snapshotted to the *current* value (per the WIT contract:
/// "Implementors MUST return a CAS handle that has been updated to
/// the latest version") and the same handle is lifted as the
/// `cas-error::cas-failed` payload so guests can retry without going
/// back through `cas.new`.
///
/// Lifetime: `key` and `observed` (when `is_observed` is true) are
/// owned by the adapter's allocator; `Cas.deinit` frees both. The
/// `bucket_handle` is the *guest* handle into `keyvalue_buckets`. If
/// the bucket is dropped while a CAS handle still points at it, the
/// CAS becomes stale — `swap` resolves the bucket via the table at
/// call time and lifts `no-such-store` if the slot is null.
pub const Cas = struct {
    bucket_handle: u32,
    key: []const u8,
    observed: []const u8,
    is_observed: bool,
    operation_claim: stable_resource.ConditionalOperationClaim = .init,

    pub fn deinit(self: *Cas, allocator: Allocator) void {
        allocator.free(self.key);
        if (self.is_observed) allocator.free(self.observed);
    }
};

/// `wasi:keyvalue` persistence-layer snapshot (#583 B4 follow-up).
///
/// Mirrors the JSON file at `WasiCliAdapter.keyvalue_store_path` —
/// keyed by bucket identifier, each entry holds the bucket's
/// key/value pairs as adapter-allocator-owned slices. The snapshot
/// is loaded eagerly in `setKeyvalueStorePath` and updated through
/// `persistedStoreEntry` / `persistedRemoveEntry` on every mutation;
/// `flushKeyvalueStore` then re-serialises the entire snapshot.
///
/// The default in-memory adapter never touches this map — it's only
/// populated when the CLI passes `--keyvalue-store=<path>` (or an
/// embedder calls `setKeyvalueStorePath` directly).
pub const PersistedBucket = struct {
    entries: std.StringHashMapUnmanaged([]const u8) = .empty,

    pub fn deinit(self: *PersistedBucket, allocator: Allocator) void {
        var it = self.entries.iterator();
        while (it.next()) |e| {
            allocator.free(e.key_ptr.*);
            allocator.free(e.value_ptr.*);
        }
        self.entries.deinit(allocator);
    }
};

/// `(string, string)` pair forwarded to
/// `wasi:config/store@0.2.0-rc.1.{get, get-all}` (#583 B6). Same lifetime
/// rules as `EnvVar` — the adapter borrows both slices and the caller
/// owns the storage for as long as the adapter is in use.
///
/// Keys are matched verbatim (case-sensitive) in `configStoreGet`; key
/// normalisation (e.g. stripping the `WAMR_CONFIG_` env-var prefix and
/// lower-casing) is the embedder's responsibility — `main.zig`'s
/// `runComponent` does this before calling `setConfigStore`.
pub const ConfigEntry = struct {
    name: []const u8,
    value: []const u8,
};

/// One-shot trace helpers used by `WasiCliAdapter.tracedAdapterCall`.
/// File-scoped because they don't touch adapter state — the wrapper
/// only forwards what `args` / `results` / the error happen to be.
/// All lines go through `std.log.warn` so they survive in release
/// builds without needing `WAMR_AOT_DEBUG=1`. (#715)
fn logAdapterEntry(
    comptime iface_short: []const u8,
    comptime member: []const u8,
    args: []const InterfaceValue,
    ci: *ComponentInstance,
    verbose: bool,
) void {
    if (args.len == 0) {
        std.debug.print("[adapter→] {s}/{s} args=()\n", .{ iface_short, member });
        return;
    }

    const summary = describeInterfaceValueList(args, ci, verbose, "arg");
    std.debug.print("[adapter→] {s}/{s} args.len={d}{s}\n", .{ iface_short, member, args.len, summary });
}

fn logAdapterExitOk(
    comptime iface_short: []const u8,
    comptime member: []const u8,
    results: []const InterfaceValue,
    ci: *ComponentInstance,
    verbose: bool,
) void {
    if (results.len == 0) {
        std.debug.print("[adapter←] {s}/{s} ok results=()\n", .{ iface_short, member });
        return;
    }

    const summary = describeInterfaceValueList(results, ci, verbose, "result");
    std.debug.print("[adapter←] {s}/{s} ok{s}\n", .{ iface_short, member, summary });
}

fn logAdapterExitErr(
    comptime iface_short: []const u8,
    comptime member: []const u8,
    err: anyerror,
) void {
    std.debug.print("[adapter←] {s}/{s} err={s}\n", .{
        iface_short,
        member,
        @errorName(err),
    });
}

const trace_hex_dump_bytes = 64;

fn describeInterfaceValue(v: InterfaceValue, ci: ?*const ComponentInstance, verbose: bool) []const u8 {
    const S = struct {
        threadlocal var buf: [256]u8 = undefined;
    };

    var fbs: std.Io.Writer = .fixed(&S.buf);
    fbs.print("{f}", .{InterfaceValueBrief{ .v = v }}) catch return @tagName(v);

    if (verbose and (v == .string or v == .list)) {
        if (ci) |ci_ptr| {
            if (describeHexDump(v, ci_ptr)) |hex| {
                fbs.writeAll("; hex=\"") catch return fbs.buffered();
                fbs.writeAll(hex) catch return fbs.buffered();
                fbs.writeByte('"') catch return fbs.buffered();
            }
        }
    }

    return fbs.buffered();
}

fn describeInterfaceValueList(
    values: []const InterfaceValue,
    ci: *ComponentInstance,
    verbose: bool,
    comptime label: []const u8,
) []const u8 {
    const S = struct {
        threadlocal var buf: [1024]u8 = undefined;
    };

    var fbs: std.Io.Writer = .fixed(&S.buf);
    for (values, 0..) |v, i| {
        fbs.print(" {s}{d}={s}", .{ label, i, describeInterfaceValue(v, ci, verbose) }) catch
            return fbs.buffered();
    }
    return fbs.buffered();
}

fn describeHexDump(v: InterfaceValue, ci: *const ComponentInstance) ?[]const u8 {
    const S = struct {
        threadlocal var buf: [trace_hex_dump_bytes * 3]u8 = undefined;
    };

    const ptr: u32 = switch (v) {
        .string => |sl| sl.ptr,
        .list => |sl| sl.ptr,
        else => return null,
    };
    const len: u32 = switch (v) {
        .string => |sl| sl.len,
        .list => |sl| sl.len,
        else => return null,
    };

    const byte_len = @min(len, trace_hex_dump_bytes);
    const bytes = ci.readGuestBytes(ptr, byte_len) orelse return null;

    var fbs: std.Io.Writer = .fixed(&S.buf);
    for (bytes, 0..) |byte, i| {
        if (i > 0) fbs.writeByte(' ') catch return null;
        fbs.print("{x:0>2}", .{byte}) catch return null;
    }
    return fbs.buffered();
}

const InterfaceValueBrief = struct {
    v: InterfaceValue,

    pub fn format(self: InterfaceValueBrief, writer: *std.Io.Writer) std.Io.Writer.Error!void {
        switch (self.v) {
            .bool => |b| try writer.print("bool({})", .{b}),
            .u8 => |x| try writer.print("u8({d})", .{x}),
            .s8 => |x| try writer.print("s8({d})", .{x}),
            .u16 => |x| try writer.print("u16({d})", .{x}),
            .s16 => |x| try writer.print("s16({d})", .{x}),
            .u32 => |x| try writer.print("u32({d})", .{x}),
            .s32 => |x| try writer.print("s32({d})", .{x}),
            .u64 => |x| try writer.print("u64({d})", .{x}),
            .s64 => |x| try writer.print("s64({d})", .{x}),
            .f32 => |x| try writer.print("f32(0x{x:0>8})", .{x}),
            .f64 => |x| try writer.print("f64(0x{x:0>16})", .{x}),
            .char => |x| try writer.print("char(U+{x})", .{x}),
            .handle => |h| try writer.print("handle({d})", .{h}),
            .string => |sl| try writer.print("string(ptr=0x{x},len={d})", .{ sl.ptr, sl.len }),
            .list => |sl| try writer.print("list(ptr=0x{x},len={d})", .{ sl.ptr, sl.len }),
            .enum_val => |d| try writer.print("enum({d})", .{d}),
            .variant_val => |vv| try writer.print("variant(disc={d})", .{vv.discriminant}),
            .option_val => |ov| try writer.print("option({s})", .{if (ov.is_some) "some" else "none"}),
            .result_val => |rv| {
                if (rv.payload) |p| {
                    switch (p.*) {
                        .variant_val => |vv| try writer.print(
                            "result({s},disc={d})",
                            .{ if (rv.is_ok) "ok" else "err", vv.discriminant },
                        ),
                        else => try writer.print(
                            "result({s},payload={s})",
                            .{ if (rv.is_ok) "ok" else "err", @tagName(p.*) },
                        ),
                    }
                } else {
                    try writer.print("result({s},no-payload)", .{if (rv.is_ok) "ok" else "err"});
                }
            },
            .record_val => |fields| try writer.print("record(len={d})", .{fields.len}),
            .tuple_val => |fields| try writer.print("tuple(len={d})", .{fields.len}),
            .flags_val => |words| try writer.print("flags(words={d})", .{words.len}),
        }
    }
};

const InputStreamResource = struct {
    stream: *streams.InputStream,
    owned: bool,
    owned_buffer: ?[]u8 = null,
    descriptor_lease: ?FsDescriptorTable.Lease = null,
    socket_lease: ?SocketTable.Lease = null,
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    shared_operation_claim: ?*stable_resource.ConditionalOperationClaim = null,

    fn claim(self: *InputStreamResource) *stable_resource.ConditionalOperationClaim {
        return self.shared_operation_claim orelse &self.operation_claim;
    }
};

const OutputStreamOwner = struct {
    allocator: Allocator,
    refs: stable_resource.ConditionalLifetimeRefCount =
        stable_resource.ConditionalLifetimeRefCount.init(1),
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    stream: *streams.OutputStream,

    fn retain(self: *OutputStreamOwner) void {
        self.refs.retain();
    }

    fn release(self: *OutputStreamOwner) void {
        if (!self.refs.release()) return;
        self.stream.deinit(self.allocator);
        self.allocator.destroy(self.stream);
        self.allocator.destroy(self);
    }
};

const OutputStreamResource = struct {
    stream: *streams.OutputStream,
    owned: bool,
    owner: ?*OutputStreamOwner = null,
    descriptor_lease: ?FsDescriptorTable.Lease = null,
    socket_lease: ?SocketTable.Lease = null,
    operation_claim: stable_resource.ConditionalOperationClaim = .init,
    shared_operation_claim: ?*stable_resource.ConditionalOperationClaim = null,

    fn claim(self: *OutputStreamResource) *stable_resource.ConditionalOperationClaim {
        if (self.owner) |owner| return &owner.operation_claim;
        return self.shared_operation_claim orelse &self.operation_claim;
    }
};

fn destroyInputStreamResource(
    allocator: Allocator,
    resource: *InputStreamResource,
) void {
    if (resource.descriptor_lease) |*lease| lease.release();
    if (resource.socket_lease) |*lease| lease.release();
    if (resource.owned) allocator.destroy(resource.stream);
    if (resource.owned_buffer) |buffer| allocator.free(buffer);
}

fn destroyOutputStreamResource(
    allocator: Allocator,
    resource: *OutputStreamResource,
) void {
    if (resource.descriptor_lease) |*lease| lease.release();
    if (resource.socket_lease) |*lease| lease.release();
    if (resource.owner) |owner| {
        owner.release();
    } else if (resource.owned) {
        resource.stream.deinit(allocator);
        allocator.destroy(resource.stream);
    }
}

fn destroyFsDescriptor(_: Allocator, descriptor: *FsDescriptor) void {
    closeFsDescriptor(descriptor.*);
}

fn destroyDirEntryStream(allocator: Allocator, stream: *DirEntryStream) void {
    allocator.destroy(stream.iter);
    if (stream.descriptor_lease) |*lease| lease.release();
}

fn destroyNetwork(allocator: Allocator, network: *Network) void {
    network.deinit(allocator);
}

fn destroySocket(allocator: Allocator, socket: *Socket) void {
    socket.closeAll(std.Io.Threaded.global_single_threaded.io(), allocator);
}

fn destroyUdpIncomingStream(allocator: Allocator, stream: **UdpIncomingStream) void {
    if (comptime build_options.lib_wasi_threads) {
        if (stream.*.parent_lease) |*lease| lease.release();
        stream.*.parent_lease = null;
    }
    allocator.destroy(stream.*);
}

fn destroyUdpOutgoingStream(allocator: Allocator, stream: **UdpOutgoingStream) void {
    if (comptime build_options.lib_wasi_threads) {
        if (stream.*.parent_lease) |*lease| lease.release();
        stream.*.parent_lease = null;
    }
    allocator.destroy(stream.*);
}

fn destroyResolveAddressStream(allocator: Allocator, stream: **ResolveAddressStream) void {
    allocator.free(stream.*.results);
    allocator.destroy(stream.*);
}

fn destroyHttpFields(allocator: Allocator, fields: **HttpFields) void {
    fields.*.deinit(allocator);
    allocator.destroy(fields.*);
}

fn destroyOutgoingRequest(allocator: Allocator, request: **OutgoingRequest) void {
