    /// `wasi:cli/types@0.3.x` — type-only interface (enum
    /// `error-code { io, illegal-byte-sequence, pipe }`). No function
    /// members; the `error-code` enum is lifted as a u8 discriminant
    /// in canonical ABI without host dispatch.
    pub fn populateWasiCliTypesP3(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        types_name: []const u8,
    ) !void {
        try providers.put(self.allocator, types_name, .{
            .host_instance = &self.cli_types_p3_iface,
        });
    }

    /// `wasi:cli/terminal-{stdin,stdout,stderr,input,output}@0.3.x`.
    /// Identical member surface to 0.2 — captured-buffer mode has no
    /// real TTY so `get-terminal-*` returns `none`.
    pub fn populateWasiCliTerminalP3(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        terminal_stdin_name: []const u8,
        terminal_stdout_name: []const u8,
        terminal_stderr_name: []const u8,
        terminal_input_name: []const u8,
        terminal_output_name: []const u8,
    ) !void {
        try self.cli_terminal_stdin_p3_iface.members.put(self.allocator, "get-terminal-stdin", .{
            .func = .{ .context = self, .call = &getTerminalNone },
        });
        try providers.put(self.allocator, terminal_stdin_name, .{
            .host_instance = &self.cli_terminal_stdin_p3_iface,
        });
        try self.cli_terminal_stdout_p3_iface.members.put(self.allocator, "get-terminal-stdout", .{
            .func = .{ .context = self, .call = &getTerminalNone },
        });
        try providers.put(self.allocator, terminal_stdout_name, .{
            .host_instance = &self.cli_terminal_stdout_p3_iface,
        });
        try self.cli_terminal_stderr_p3_iface.members.put(self.allocator, "get-terminal-stderr", .{
            .func = .{ .context = self, .call = &getTerminalNone },
        });
        try providers.put(self.allocator, terminal_stderr_name, .{
            .host_instance = &self.cli_terminal_stderr_p3_iface,
        });
        try self.cli_terminal_input_p3_iface.members.put(self.allocator, "[resource-drop]terminal-input", .{
            .func = .{ .context = self, .call = &noopResourceDrop },
        });
        try providers.put(self.allocator, terminal_input_name, .{
            .host_instance = &self.cli_terminal_input_p3_iface,
        });
        try self.cli_terminal_output_p3_iface.members.put(self.allocator, "[resource-drop]terminal-output", .{
            .func = .{ .context = self, .call = &noopResourceDrop },
        });
        try providers.put(self.allocator, terminal_output_name, .{
            .host_instance = &self.cli_terminal_output_p3_iface,
        });
    }

    /// `wasi:cli/stdin@0.3.x.read-via-stream:
    ///   () -> tuple<stream<u8>, future<result<_, error-code>>>`.
    ///
    /// Allocates a `stream<u8>` entry in `comp_inst.streams` and
    /// pre-seeds its FIFO with all currently available stdin bytes
    /// (drained eagerly because wamr's single-threaded executor has no
    /// scheduler that could deliver more bytes after this returns).
    /// The writable end is immediately closed so subsequent
    /// `stream.read` calls observe EOF once the buffer drains.
    ///
    /// The companion `future<result<_,error-code>>` is settled to
    /// `ok` (discriminant 0). It represents the eventual completion
    /// of the host-side producer; for the buffered model that's
    /// "now".
    fn stdinReadViaStreamP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;

        // 1. Allocate a stream<u8> handle in the per-instance table.
        //    Crucially, we do NOT eagerly drain stdin here (#537) —
        //    the test harness writes to stdin AFTER `run` starts, and
        //    eager `posix.read` on a still-open pipe would deadlock.
        //    Instead we install a host-attached `on_read` handler on
        //    the stream: bytes are pulled from `self.stdin` lazily,
        //    once per guest `stream.read`.
        const stream_handle = ci.allocAsyncHandle();

        const ctx = self.allocator.create(ReadViaStreamCtx) catch
            return error.OutOfMemory;
        ctx.* = .{ .adapter = self };

        var stream_entry = async_mod.AsyncStream{};
        stream_entry.host_handler = async_mod.HostStreamHandler{
            .on_read = &readViaStreamOnRead,
            .on_destroy = &readViaStreamOnDestroy,
            .ctx = ctx,
        };
        ci.streams.put(self.allocator, stream_handle, stream_entry) catch {
            self.allocator.destroy(ctx);
            stream_entry.deinit(self.allocator);
            return error.OutOfMemory;
        };
        errdefer _ = ci.streams.remove(stream_handle);

        // 2. Allocate a `future<result<_,error-code>>` already settled
        //    to ok. Lowered ABI for `result<_,error-code>` is a single
        //    discriminant byte (0 = ok). The payload is owned by the
        //    Future and freed when it transitions to .closed.
        const future_handle = ci.allocAsyncHandle();
        const ok_payload = self.allocator.alloc(u8, 1) catch return error.OutOfMemory;
        ok_payload[0] = 0;
        const fut_entry = async_mod.Future{ .state = .ready, .payload = ok_payload };
        ci.futures.put(self.allocator, future_handle, fut_entry) catch {
            self.allocator.free(ok_payload);
            return error.OutOfMemory;
        };
        errdefer _ = ci.futures.remove(future_handle);

        // 3. Build tuple<handle, handle>.
        const tuple = try allocator.alloc(InterfaceValue, 2);
        tuple[0] = .{ .handle = stream_handle };
        tuple[1] = .{ .handle = future_handle };
        results[0] = .{ .tuple_val = tuple };
    }

    const ReadViaStreamCtx = struct {
        adapter: *WasiCliAdapter,
    };

    /// `on_read` callback for `wasi:cli/stdin.read-via-stream` (#537).
    /// Synchronously reads from the host's stdin into the guest's
    /// destination buffer. Blocks on pipes; returns 0 on EOF; -1 on
    /// error.
    fn readViaStreamOnRead(ctx_opaque: ?*anyopaque, dst: []u8) i32 {
        const c: *ReadViaStreamCtx = @ptrCast(@alignCast(ctx_opaque.?));
        switch (c.adapter.stdin.read(dst)) {
            .ok => |n| return @intCast(n),
            .closed => return 0,
            .err => return -1,
        }
    }

    fn readViaStreamOnDestroy(ctx_opaque: ?*anyopaque) void {
        const c: *ReadViaStreamCtx = @ptrCast(@alignCast(ctx_opaque.?));
        c.adapter.allocator.destroy(c);
    }

    /// `wasi:cli/stdout@0.3.x.write-via-stream:
    ///   (stream<u8>) -> future<result<_, error-code>>`.
    fn stdoutWriteViaStreamP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        return writeViaStreamImplP3(self, &self.stdout, ci, args, results, allocator);
    }

    /// `wasi:cli/stderr@0.3.x.write-via-stream:
    ///   (stream<u8>) -> future<result<_, error-code>>`.
    fn stderrWriteViaStreamP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        return writeViaStreamImplP3(self, &self.stderr, ci, args, results, allocator);
    }

    /// Common body for `stdout.write-via-stream` / `stderr.write-via-stream`.
    /// Installs a host-attached sink on the guest's `stream<u8>` so every
    /// subsequent `stream.write` is forwarded synchronously to `target`.
    /// Returns an open `future<result<_,error-code>>` that settles to
    /// Ok when the guest finally calls `stream.drop-writable` (#537).
    ///
    /// WAMR has no async scheduler, so we can't asynchronously "pump"
    /// the stream — we instead rely on the executor's `stream.write`
    /// arm forwarding directly via `AsyncStream.host_handler`. This
    /// mirrors what a real async runtime would do with a long-lived
    /// `stream.read` parked on the host side.
    fn writeViaStreamImplP3(
        self: *WasiCliAdapter,
        target: *streams.OutputStream,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) !void {
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const stream_handle: u32 = switch (args[0]) {
            .handle, .u32 => |h| h,
            else => return error.InvalidArgs,
        };

        // Allocate the companion future first so we can capture its
        // handle inside the host-handler context.
        const future_handle = ci.allocAsyncHandle();
        const fut_entry = async_mod.Future{ .state = .pending, .payload = null };
        ci.futures.put(self.allocator, future_handle, fut_entry) catch
            return error.OutOfMemory;
        errdefer _ = ci.futures.remove(future_handle);

        const ctx = self.allocator.create(WriteViaStreamCtx) catch
            return error.OutOfMemory;
        ctx.* = .{
            .adapter = self,
            .target = target,
            .ci = ci,
            .future_handle = future_handle,
        };

        var handler_installed = false;
        var writer_already_closed = false;
        while (ci.streams.acquire(stream_handle)) |initial_lease| {
            var stream_lease = initial_lease;
            const s = stream_lease.value();
            if (s.buffer.items.len > 0) {
                var detached = s.buffer;
                s.buffer = .empty;
                stream_lease.release();
                defer detached.deinit(self.allocator);
                switch (target.write(detached.items, self.allocator)) {
                    .ok => {},
                    .err, .closed => {
                        self.allocator.destroy(ctx);
                        return error.IoError;
                    },
                }
                continue;
            }
            // Install host handler — every future `stream.write` from
            // the guest goes synchronously to `target`.
            s.host_handler = async_mod.HostStreamHandler{
                .on_write = &writeViaStreamOnWrite,
                .on_drop_writable = &writeViaStreamOnDropWritable,
                .on_destroy = &writeViaStreamOnDestroy,
                .ctx = ctx,
            };
            writer_already_closed = s.write_closed;
            handler_installed = true;
            stream_lease.release();
            break;
        }
        if (!handler_installed) {
            // Unknown stream handle — settle the future to ok so the
            // guest's await completes without panicking.
            writeViaStreamOnDropWritable(ctx);
            self.allocator.destroy(ctx);
        } else if (writer_already_closed) {
            // If the writer was already dropped (the synchronous "no
            // concurrent writer" case), settle the future immediately.
            writeViaStreamOnDropWritable(ctx);
        }

        results[0] = .{ .handle = future_handle };
    }

    const WriteViaStreamCtx = struct {
        adapter: *WasiCliAdapter,
        target: *streams.OutputStream,
        ci: *ComponentInstance,
        future_handle: u32,
    };

    fn writeViaStreamOnWrite(ctx_opaque: ?*anyopaque, bytes: []const u8) bool {
        const c: *WriteViaStreamCtx = @ptrCast(@alignCast(ctx_opaque.?));
        return switch (c.target.write(bytes, c.adapter.allocator)) {
            .ok => true,
            .err, .closed => false,
        };
    }

    fn writeViaStreamOnDropWritable(ctx_opaque: ?*anyopaque) void {
        const c: *WriteViaStreamCtx = @ptrCast(@alignCast(ctx_opaque.?));
        if (c.ci.futures.acquire(c.future_handle)) |initial_lease| {
            var future_lease = initial_lease;
            const fut = future_lease.value();
            // Settle as `Ok(())` (discriminant 0). The companion
            // `future<result<_,error-code>>` lift only inspects the
            // leading 1-byte discriminant: 0 selects the Ok arm and
            // the trailing payload bytes are unread.
            if (!fut.write_closed) {
                // If a reader already parked (the common case for
                // `futures::join!` over a host-future-await + a
                // stream writer), populate the parked destination
                // **before** delivering the wakeup event. wit-bindgen's
                // `WaitableOperation` lifts directly from the pointer
                // it passed to `future.read` at `start_read` time —
                // it does **not** re-call `future.read` after the
                // event — so writing the payload into a side heap
                // buffer would leave the guest's lift target
                // uninitialised and trigger a Rust enum-discriminant
                // panic (#550). Clear `pending_read` and skip the
                // heap buffer in that case.
                if (fut.pending_read) |pr| {
                    if (c.ci.writableGuestBytes(pr.guest_ptr, 1)) |dst| {
                        dst[0] = 0;
                    }
                    fut.pending_read = null;
                } else if (fut.payload == null) {
                    // No parked reader yet — buffer the discriminant so
                    // a subsequent `future.read` can copy it out.
                    if (c.adapter.allocator.alloc(u8, 1)) |buf| {
                        buf[0] = 0;
                        fut.payload = buf;
                    } else |_| {
                        // Out-of-memory fallback: leave payload null;
                        // the unit-type fast-path in `future_read`
                        // surfaces COMPLETED(0) which the guest's
                        // `result<_, error-code>` lift treats as Ok.
                    }
                }
                fut.state = .ready;
                fut.write_closed = true;
            }
            const registration = fut.read_waitable;
            future_lease.release();
            _ = c.ci.notifyWaitable(
                registration,
                async_canon.packStatus(.completed, 0),
            );
        }
        // NB: the ctx is NOT freed here — `stream.drop-readable` /
        // `stream.drop-writable` fire `on_destroy` once the stream
        // table entry is removed (both ends dropped). Freeing here
        // would race that destructor and break the executor's drop
        // sequence when the writer drops before the reader.
    }

    fn writeViaStreamOnDestroy(ctx_opaque: ?*anyopaque) void {
        const c: *WriteViaStreamCtx = @ptrCast(@alignCast(ctx_opaque.?));
        c.adapter.allocator.destroy(c);
    }

    fn pushPollable(self: *WasiCliAdapter, pollable: Pollable) !u32 {
        return self.pollable_table.publish(pollable);
    }

    fn lookupPollable(self: *WasiCliAdapter, handle: u32) ?Pollable {
        var lease = self.pollable_table.acquire(handle) orelse return null;
        defer lease.release();
        const value = lease.lock();
        defer lease.unlock();
        return value.*;
    }

    fn dropPollable(self: *WasiCliAdapter, handle: u32) void {
        _ = self.pollable_table.remove(handle);
    }

    fn pollInEvents() i16 {
        if (comptime builtin.os.tag == .windows) return 0;
        return @intCast(std.c.POLL.IN);
    }

    fn pollOutEvents() i16 {
        if (comptime builtin.os.tag == .windows) return 0;
        return @intCast(std.c.POLL.OUT);
    }

    fn pollReadyEvents(events: i16) i16 {
        if (comptime builtin.os.tag == .windows) return events;
        return events |
            @as(i16, @intCast(std.c.POLL.ERR)) |
            @as(i16, @intCast(std.c.POLL.HUP)) |
            @as(i16, @intCast(std.c.POLL.NVAL));
    }

    fn fdPollReady(fd: std.posix.fd_t, events: i16) bool {
        if (comptime builtin.os.tag == .windows) return true;
        var fds = [_]std.posix.pollfd{.{
            .fd = fd,
            .events = events,
            .revents = 0,
        }};
        const n = std.posix.poll(&fds, 0) catch return true;
        return n > 0 and (fds[0].revents & pollReadyEvents(events)) != 0;
    }

    fn pollableBackend(self: *WasiCliAdapter, pollable: Pollable) ?PollBackend {
        if (comptime builtin.os.tag == .windows) return null;
        switch (pollable) {
            .input_stream => |handle| {
                var lease = self.lookupInputStream(handle) orelse return null;
                const resource = lease.value();
                const claim = resource.claim();
                claim.acquire();
                const fd = switch (resource.stream.source) {
                    .fd => |value| value,
                    .tcp_stream => |value| value,
                    else => {
                        claim.release();
                        lease.release();
                        return null;
                    },
                };
                claim.release();
                return .{
                    .fd = fd,
                    .events = pollInEvents(),
                    .guard = .{ .input_stream = lease },
                };
            },
            .output_stream => |handle| {
                var lease = self.lookupStream(handle) orelse return null;
                const resource = lease.value();
                const claim = resource.claim();
                claim.acquire();
                const fd = switch (resource.stream.sink) {
                    .fd => |value| value,
                    .tcp_stream => |value| value,
                    else => {
                        claim.release();
                        lease.release();
                        return null;
                    },
                };
                claim.release();
                return .{
                    .fd = fd,
                    .events = pollOutEvents(),
                    .guard = .{ .output_stream = lease },
                };
            },
            .tcp_socket => |handle| {
                var socket_lease = self.lookupSocket(handle) orelse return null;
                const socket = socket_lease.value();
                const fd = socket.getKernelFd() orelse {
                    socket_lease.release();
                    return null;
                };
                const events = if (socket.state == .connected) pollInEvents() | pollOutEvents() else pollInEvents();
                socket_lease.releaseClaim();
                return .{
                    .fd = fd,
                    .events = events,
                    .guard = .{ .socket = socket_lease },
                };
            },
            .udp_incoming_stream => |ref| {
                var stream_lease = self.lookupUdpIncomingStream(ref.handle) orelse return null;
                const stream = stream_lease.value().*;
                if (stream.parent_handle != ref.parent_handle or stream.generation != ref.generation) {
                    stream_lease.release();
                    return null;
                }
                var socket_guard = self.lockUdpIncomingParent(stream) orelse {
                    stream_lease.release();
                    return null;
                };
                const socket = socket_guard.value();
                if (socket.stream_generation != ref.generation) {
                    socket_guard.release();
                    stream_lease.release();
                    return null;
                }
                const host_socket = socket.host_socket orelse {
                    socket_guard.release();
                    stream_lease.release();
                    return null;
                };
                socket_guard.release();
                return .{
                    .fd = host_socket.handle,
                    .events = pollInEvents(),
                    .guard = .{ .udp_incoming = stream_lease },
                };
            },
            .udp_outgoing_stream => |ref| {
                var stream_lease = self.lookupUdpOutgoingStream(ref.handle) orelse return null;
                const stream = stream_lease.value().*;
                if (stream.parent_handle != ref.parent_handle or stream.generation != ref.generation) {
                    stream_lease.release();
                    return null;
                }
                var socket_guard = self.lockUdpOutgoingParent(stream) orelse {
                    stream_lease.release();
                    return null;
                };
                const socket = socket_guard.value();
                if (socket.stream_generation != ref.generation) {
                    socket_guard.release();
                    stream_lease.release();
                    return null;
                }
                const host_socket = socket.host_socket orelse {
                    socket_guard.release();
                    stream_lease.release();
                    return null;
                };
                socket_guard.release();
                return .{
                    .fd = host_socket.handle,
                    .events = pollOutEvents(),
                    .guard = .{ .udp_outgoing = stream_lease },
                };
            },
            .http_future_response => |handle| {
                // An outbound HTTP fetch is settled by its worker thread,
                // not by an fd this adapter owns. Hand `poll()` the
                // fetch's self-pipe waker so the host sleeps until the
                // worker publishes its outcome instead of busy-spinning
                // (#833). Already-settled futures return null so the
                // `pollableIsReady` fast-path resolves the block instead.
                var future_lease = self.lookupFutureResponse(handle) orelse return null;
                const future = future_lease.lock().*;
                const pending = !future.polled and future.state == .pending;
                future_lease.unlock();
                if (!pending) {
                    future_lease.release();
                    return null;
                }
                future_lease.releaseClaim();
                const operation_handles = self.pending_http_fetches.snapshotHandles(
                    self.allocator,
                ) catch {
                    future_lease.release();
                    return null;
                };
                defer self.allocator.free(operation_handles);
                for (operation_handles) |operation_handle| {
                    var operation_lease = self.pending_http_fetches.acquire(
                        operation_handle,
                    ) orelse continue;
                    const entry = operation_lease.value();
                    if (entry.armed.load(.acquire) and entry.future_handle == handle) {
                        if (entry.shared) |shared| if (shared.waker) |w| {
                            return .{
                                .fd = w.read_fd,
                                .events = pollInEvents(),
                                .guard = .{ .http_future = .{
                                    .future = future_lease,
                                    .operation = operation_lease,
                                } },
                            };
                        };
                        operation_lease.release();
                        future_lease.release();
                        return null;
                    }
                    operation_lease.release();
                }
                future_lease.release();
                return null;
            },
            else => return null,
        }
    }

    fn pollableIsReady(self: *WasiCliAdapter, pollable: Pollable) bool {
        return switch (pollable) {
            .immediate => true,
            .monotonic_timer => |deadline| self.monotonicNs() >= deadline,
            .input_stream => |handle| blk: {
                var lease = self.lookupInputStream(handle) orelse break :blk true;
                defer lease.release();
                const resource = lease.value();
                const claim = resource.claim();
                claim.acquire();
                const ready = switch (resource.stream.source) {
                    .buffer, .host_file, .closed => true,
                    .fd => |fd| fdPollReady(fd, pollInEvents()),
                    .tcp_stream => |fd| fdPollReady(fd, pollInEvents()),
                    .tls => true,
                };
                claim.release();
                break :blk ready;
            },
            .output_stream => |handle| blk: {
                var lease = self.lookupStream(handle) orelse break :blk true;
                defer lease.release();
                const resource = lease.value();
                const claim = resource.claim();
                claim.acquire();
                const ready = switch (resource.stream.sink) {
                    .buffer, .host_file, .callback, .closed => true,
                    .fd => |fd| fdPollReady(fd, pollOutEvents()),
                    .tcp_stream => |fd| fdPollReady(fd, pollOutEvents()),
                    .tls => true,
                };
                claim.release();
                break :blk ready;
            },
            .tcp_socket => |handle| blk: {
                var socket_lease = self.lookupSocket(handle) orelse break :blk true;
                defer socket_lease.release();
                const socket = socket_lease.value();
                if (socket.pending != .idle or socket.state == .closed or socket.state == .unbound or socket.state == .bound) {
                    break :blk true;
                }
                const fd = socket.getKernelFd() orelse break :blk true;
                const events = if (socket.state == .connected) pollInEvents() | pollOutEvents() else pollInEvents();
                break :blk fdPollReady(fd, events);
            },
            .udp_socket => true,
            .udp_incoming_stream => |ref| blk: {
                var stream_lease = self.lookupUdpIncomingStream(ref.handle) orelse break :blk true;
                defer stream_lease.release();
                const stream = stream_lease.value().*;
                if (stream.parent_handle != ref.parent_handle or stream.generation != ref.generation) break :blk true;
                var socket_guard = self.lockUdpIncomingParent(stream) orelse break :blk true;
                defer socket_guard.release();
                const socket = socket_guard.value();
                if (socket.stream_generation != ref.generation) break :blk true;
                const host_socket = socket.host_socket orelse break :blk true;
                break :blk fdPollReady(host_socket.handle, pollInEvents());
            },
            .udp_outgoing_stream => |ref| blk: {
                var stream_lease = self.lookupUdpOutgoingStream(ref.handle) orelse break :blk true;
                defer stream_lease.release();
                const stream = stream_lease.value().*;
                if (stream.parent_handle != ref.parent_handle or stream.generation != ref.generation) break :blk true;
                var socket_guard = self.lockUdpOutgoingParent(stream) orelse break :blk true;
                defer socket_guard.release();
                const socket = socket_guard.value();
                if (socket.stream_generation != ref.generation) break :blk true;
                const host_socket = socket.host_socket orelse break :blk true;
                break :blk fdPollReady(host_socket.handle, pollOutEvents());
            },
            .resolve_address_stream => true,
            .http_future_response => |handle| blk: {
                var future_lease = self.lookupFutureResponse(handle) orelse break :blk true;
                defer future_lease.release();
                const future = future_lease.lock().*;
                const ready = future.polled or future.state != .pending;
                future_lease.unlock();
                break :blk ready;
            },
            .http_future_trailers => true,
            .future_timer => |fut_handle| blk: {
                self.async_state_claim.acquire();
                defer self.async_state_claim.release();
                break :blk self.timer_future_ready.get(fut_handle) orelse false;
            },
        };
    }

    fn pollableDeadline(self: *WasiCliAdapter, handle: u32) !?u64 {
        const pollable = self.lookupPollable(handle) orelse return error.InvalidHandle;
        return switch (pollable) {
            .monotonic_timer => |deadline| deadline,
            else => null,
        };
    }

    fn anyPollableReady(self: *WasiCliAdapter, handles: []const u32) !bool {
        // Settle any outbound HTTP fetches whose worker thread has
        // finished — observed transition (`.pending` → `.ready_*`)
        // is what the `.http_future_response` pollable variant
        // checks via `pollableIsReady`. (#583 A2)
        self.drainPendingHttpFetches();
        for (handles) |handle| {
            const pollable = self.lookupPollable(handle) orelse return error.InvalidHandle;
            if (self.pollableIsReady(pollable)) return true;
        }
        return false;
    }

    fn earliestTimerDeadline(self: *WasiCliAdapter, handles: []const u32) !?u64 {
        var earliest: ?u64 = null;
        for (handles) |handle| {
            if (try self.pollableDeadline(handle)) |deadline| {
                if (earliest == null or deadline < earliest.?) earliest = deadline;
            }
        }
        return earliest;
    }

    fn timeoutMsUntil(self: *WasiCliAdapter, deadline: u64) i32 {
        const now = self.monotonicNs();
        if (deadline <= now) return 0;
        const ns = deadline - now;
        const ms = (ns +| 999_999) / 1_000_000;
        if (ms > @as(u64, @intCast(std.math.maxInt(i32)))) return std.math.maxInt(i32);
        return @intCast(ms);
    }

    fn waitForBackendEvents(self: *WasiCliAdapter, handles: []const u32, timeout_ms: i32) !bool {
        if (comptime builtin.os.tag == .windows) return false;
        var fds: std.ArrayListUnmanaged(std.posix.pollfd) = .empty;
        defer fds.deinit(self.allocator);
        var backends: std.ArrayListUnmanaged(PollBackend) = .empty;
        defer {
            for (backends.items) |*backend| backend.deinit();
            backends.deinit(self.allocator);
        }
        try fds.ensureTotalCapacity(self.allocator, handles.len);
        try backends.ensureTotalCapacity(self.allocator, handles.len);
        for (handles) |handle| {
            const pollable = self.lookupPollable(handle) orelse return error.InvalidHandle;
            if (self.pollableBackend(pollable)) |backend| {
                fds.appendAssumeCapacity(.{
                    .fd = backend.fd,
                    .events = backend.events,
                    .revents = 0,
                });
                backends.appendAssumeCapacity(backend);
            }
        }
        if (fds.items.len == 0) return false;
        _ = std.posix.poll(fds.items, timeout_ms) catch return false;
        return true;
    }

    fn blockUntilAnyReady(self: *WasiCliAdapter, handles: []const u32) !void {
        while (!try self.anyPollableReady(handles)) {
            const earliest = try self.earliestTimerDeadline(handles);
            if (self.monotonic_clock_override != null) {
                if (earliest) |deadline| {
                    if (deadline > self.monotonic_clock_override.?) {
                        self.monotonic_clock_override = deadline;
                    }
                    continue;
                }
                return;
            }

            const timeout_ms: i32 = if (earliest) |deadline| self.timeoutMsUntil(deadline) else -1;
            const used_backend = try self.waitForBackendEvents(handles, timeout_ms);
            if (!used_backend) {
                if (earliest) |deadline| {
                    const now = self.monotonicNs();
                    if (deadline > now) {
                        const io = std.Io.Threaded.global_single_threaded.io();
                        const duration: std.Io.Clock.Duration = .{
                            .raw = .{ .nanoseconds = deadline - now },
                            .clock = .awake,
                        };
                        duration.sleep(io) catch {};
                    }
                } else {
                    return;
                }
            }
        }
    }

    fn readPollableHandlesFromArg(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        arg: InterfaceValue,
        allocator: Allocator,
    ) ![]u32 {
        _ = self;
        return switch (arg) {
            .list => |list| blk: {
                if (list.len == 0) break :blk try allocator.alloc(u32, 0);
                const byte_len = std.math.mul(u32, list.len, 4) catch return error.OutOfBoundsMemory;
                const bytes = ci.readGuestBytes(list.ptr, byte_len) orelse return error.OutOfBoundsMemory;
                const handles = try allocator.alloc(u32, list.len);
                errdefer allocator.free(handles);
                for (handles, 0..) |*handle, i| {
                    const off = i * 4;
                    handle.* = std.mem.readInt(u32, bytes[off..][0..4], .little);
                }
                break :blk handles;
            },
            else => return error.InvalidArgs,
        };
    }

    fn readyPollableIndices(self: *WasiCliAdapter, handles: []const u32, allocator: Allocator) ![]u32 {
        var ready: std.ArrayListUnmanaged(u32) = .empty;
        errdefer ready.deinit(allocator);
        for (handles, 0..) |handle, idx| {
            const pollable = self.lookupPollable(handle) orelse return error.InvalidHandle;
            if (self.pollableIsReady(pollable)) {
                try ready.append(allocator, @intCast(idx));
            }
        }
        return ready.toOwnedSlice(allocator);
    }

    fn lowerReadyIndexList(
        ci: *ComponentInstance,
        ready: []const u32,
        allocator: Allocator,
    ) !InterfaceValue {
        if (ready.len == 0) return .{ .list = .{ .ptr = 0, .len = 0 } };

        const bytes = try allocator.alloc(u8, ready.len * 4);
        defer allocator.free(bytes);
        for (ready, 0..) |idx, i| {
            std.mem.writeInt(u32, bytes[i * 4 ..][0..4], idx, .little);
        }
        const ptr = ci.hostAllocAndWrite(bytes, 1) orelse return error.OutOfMemory;
        return .{ .list = .{ .ptr = ptr, .len = @intCast(ready.len) } };
    }

    fn pollableResourceDrop(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        self.dropPollable(handle);
    }

    fn pollableReady(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const pollable = self.lookupPollable(handle) orelse return error.InvalidHandle;
        results[0] = .{ .bool = self.pollableIsReady(pollable) };
    }

    fn pollableBlock(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        _ = allocator;
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const handles = [_]u32{handle};
        try self.blockUntilAnyReady(&handles);
    }

    fn pollPoll(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0 or results.len == 0) return error.InvalidArgs;
        const handles = try self.readPollableHandlesFromArg(ci, args[0], allocator);
        defer allocator.free(handles);

        if (handles.len > 0) {
            try self.blockUntilAnyReady(handles);
        }
        const ready = try self.readyPollableIndices(handles, allocator);
        defer allocator.free(ready);
        results[0] = try lowerReadyIndexList(ci, ready, allocator);
    }

    /// Register `wasi:io/poll` and `wasi:io/error` host bindings.
    ///
    /// `pollable` handles are adapter resources backed by stream, clock,
    /// socket, DNS, or HTTP-future metadata.
    pub fn populateWasiIoPollError(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        io_poll_name: []const u8,
        io_error_name: []const u8,
    ) !void {
        try self.io_poll_iface.members.put(self.allocator, "[method]pollable.ready", .{
            .func = .{ .context = self, .call = &pollableReady },
        });
        try self.io_poll_iface.members.put(self.allocator, "[method]pollable.block", .{
            .func = .{ .context = self, .call = &pollableBlock },
        });
        try self.io_poll_iface.members.put(self.allocator, "poll", .{
            .func = .{ .context = self, .call = &pollPoll },
        });
        try self.io_poll_iface.members.put(self.allocator, "[resource-drop]pollable", .{
            .func = .{ .context = self, .call = &pollableResourceDrop },
        });
        try providers.put(self.allocator, io_poll_name, .{
            .host_instance = &self.io_poll_iface,
        });

        try self.io_error_iface.members.put(self.allocator, "[resource-drop]error", .{
            .func = .{ .context = self, .call = &noopResourceDrop },
        });
        // `[method]error.to-debug-string: (borrow<error>) -> string` (#583
        // audit arm). wamr does not maintain an io-error table — error
        // handles surface only as canonical-ABI sentinels — so this is a
        // best-effort opaque debug string. (Audit PR #604.)
        try self.io_error_iface.members.put(self.allocator, "[method]error.to-debug-string", .{
            .func = .{ .context = self, .call = &ioErrorToDebugString },
        });
        try providers.put(self.allocator, io_error_name, .{
            .host_instance = &self.io_error_iface,
        });
    }

    /// Register `wasi:io/streams@0.3.x` and `wasi:io/error@0.3.x` host
