    /// `(own<R>) -> ()` no-op — the host never produces non-stream
    /// resources on the happy path, so dropping one is purely guest-side
    /// bookkeeping that we can swallow.
    fn noopResourceDrop(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {}

    /// `wasi:random/random.get-random-bytes: (u64) -> list<u8>` (#147).
    fn getRandomBytes(
        _: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const want_u64 = switch (args[0]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        const want: usize = @min(want_u64, std.math.maxInt(usize));
        // Cap at 64 KiB — same cap `blockingRead` uses, prevents a hostile
        // guest from forcing a multi-exabyte host allocation.
        const capped: usize = @min(want, 64 * 1024);
        const buf = try allocator.alloc(u8, capped);
        defer allocator.free(buf);
        wasi_p2_core.Random.getRandomBytes(buf);
        const guest_ptr = ci.hostAllocAndWrite(buf, 1) orelse return error.IoError;
        results[0] = .{ .list = .{ .ptr = guest_ptr, .len = @intCast(capped) } };
    }

    /// `wasi:random/random.get-random-u64: () -> u64` (#147).
    fn getRandomU64(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        results[0] = .{ .u64 = wasi_p2_core.Random.getRandomU64() };
    }

    /// `wasi:random/insecure.get-insecure-random-bytes: (u64) -> list<u8>` (#147).
    fn getInsecureRandomBytes(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const want_u64 = switch (args[0]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        const want: usize = @min(want_u64, std.math.maxInt(usize));
        const capped: usize = @min(want, 64 * 1024);
        const buf = try allocator.alloc(u8, capped);
        defer allocator.free(buf);
        self.random_state_claim.acquire();
        self.ensureInsecurePrng().bytes(buf);
        self.random_state_claim.release();
        const guest_ptr = ci.hostAllocAndWrite(buf, 1) orelse return error.IoError;
        results[0] = .{ .list = .{ .ptr = guest_ptr, .len = @intCast(capped) } };
    }

    /// `wasi:random/insecure.get-insecure-random-u64: () -> u64` (#147).
    fn getInsecureRandomU64(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        self.random_state_claim.acquire();
        const value = self.ensureInsecurePrng().int(u64);
        self.random_state_claim.release();
        results[0] = .{ .u64 = value };
    }

    /// `wasi:random/insecure-seed.insecure-seed: () -> tuple<u64, u64>` (#147).
    /// Per spec semantics, this is meant to be called only once; subsequent
    /// calls return the same value (asserted by the `random` fixture in the
    /// wasi-p3-testsuite). We memoise on the adapter so both 0.2 and 0.3
    /// surfaces share a single cached pair. (#520)
    fn insecureSeed(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        self.random_state_claim.acquire();
        const pair = self.insecure_seed_cache orelse blk: {
            const p = [_]u64{
                wasi_p2_core.Random.getRandomU64(),
                wasi_p2_core.Random.getRandomU64(),
            };
            self.insecure_seed_cache = p;
            break :blk p;
        };
        self.random_state_claim.release();
        const fields = try allocator.alloc(InterfaceValue, 2);
        fields[0] = .{ .u64 = pair[0] };
        fields[1] = .{ .u64 = pair[1] };
        results[0] = .{ .tuple_val = fields };
    }

    /// Lazy-init view onto the adapter's insecure PRNG. Auto-seeds from
    /// the OS on first call; tests can pin a deterministic seed by
    /// writing `self.insecure_prng` directly first.
    fn ensureInsecurePrng(self: *WasiCliAdapter) std.Random {
        if (self.insecure_prng == null) {
            var seed_bytes: [8]u8 = undefined;
            wasi_p2_core.Random.getRandomBytes(&seed_bytes);
            const seed = std.mem.readInt(u64, &seed_bytes, .little);
            self.insecure_prng = std.Random.DefaultPrng.init(seed);
        }
        return self.insecure_prng.?.random();
    }

    // ── wasi:logging@0.1.x (#583 B5) ──────────────────────────────────
    //
    // The WIT (https://github.com/WebAssembly/wasi-logging, package
    // `wasi:logging@0.1.0-draft`) is small:
    //
    //   enum level { trace, debug, info, warn, error, critical }
    //   log: func(level: level, context: string, message: string)
    //
    // The host implementation routes guest log calls to:
    //   1. `std.log.scoped(.wasi_guest)` at the projected severity
    //      (see `WasiLogLevel.toStdLogLevel`). This lets embedders that
    //      install a custom `std.log.logFn` capture structured log
    //      records.
    //   2. The adapter's `self.stderr` sink — `initWithHostStdio`
    //      points this at the host process's stderr fd (live
    //      streaming); `init` (test path) buffers it for inspection.
    //      Direct stderr output is always emitted because std.log is
    //      compile-time gated by `std_options.log_level` in
    //      ReleaseFast builds.
    //
    // Host-side filtering uses `self.log_level` (default `.trace` =
    // admit-all). Calls strictly below the threshold are dropped
    // before formatting / writing.

    /// Register `wasi:logging/logging` (#583 B5). Members:
    ///   - `log: func(level: level, context: string, message: string)`.
    ///
    /// The 0.1 surface is the only published WIT today. A future 0.2
    /// revision would register against `logging_p2_iface` with the
    /// same backend; see `populateWasiProviders` for the
    /// version-multiplex.
    pub fn populateWasiLogging(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        logging_name: []const u8,
    ) !void {
        try self.logging_iface.members.put(self.allocator, "log", .{
            .func = .{ .context = self, .call = &wasiLog },
        });
        try providers.put(self.allocator, logging_name, .{
            .host_instance = &self.logging_iface,
        });
    }

    /// 0.2.x version-multiplex (#583 B5). Reserved for the day the
    /// upstream WIT publishes a `wasi:logging@0.2.x` package — today
    /// it's stub-equivalent to `populateWasiLogging`, registered
    /// against a separate HostInstance so 0.1 and 0.2 imports route
    /// independently (mirrors `wasi:random@0.2` vs `@0.3`).
    pub fn populateWasiLoggingP2(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        logging_name: []const u8,
    ) !void {
        try self.logging_p2_iface.members.put(self.allocator, "log", .{
            .func = .{ .context = self, .call = &wasiLog },
        });
        try providers.put(self.allocator, logging_name, .{
            .host_instance = &self.logging_p2_iface,
        });
    }

    /// `wasi:logging/logging.log: (level, string, string) -> ()` (#583 B5).
    ///
    /// Reads the three canonical-ABI arguments, applies the
    /// `self.log_level` filter, formats `[<level>] [<context>] <message>\n`
    /// and writes it to both `std.log.scoped(.wasi_guest)` and the
    /// adapter's `self.stderr` sink. Invalid arguments (wrong arity,
    /// out-of-range enum discriminant, out-of-bounds string pointer)
    /// surface as a host trap via the existing error path — the WIT
    /// `log` signature has no result so the guest sees a generic
    /// component-model trap on misuse.
    fn wasiLog(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3) return error.InvalidArgs;
        const disc: u32 = switch (args[0]) {
            .enum_val => |d| d,
            // Some lifters surface narrow enum discriminants as u8/u32
            // primitives. Accept those too for robustness.
            .u8 => |v| v,
            .u32 => |v| v,
            else => return error.InvalidArgs,
        };
        // Out-of-range discriminant → silently drop. The WIT enum has
        // six variants (0..=5); a guest passing 6+ has a codegen bug
        // but trapping the whole component over a log line would be
        // disproportionate. Mirror what real loggers do (drop + carry
        // on).
        if (disc > @intFromEnum(WasiLogLevel.critical)) return;
        const level: WasiLogLevel = @enumFromInt(disc);
        const ctx_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        const msg_pl = switch (args[2]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        // Filter below threshold *before* reading guest memory — saves
        // the read on hot trace-level calls in release builds where
        // the filter is set to `.info` or higher.
        if (@intFromEnum(level) < @intFromEnum(self.log_level)) return;
        const ctx_bytes = ci.readGuestBytes(ctx_pl.ptr, ctx_pl.len) orelse
            return error.OutOfBoundsMemory;
        const msg_bytes = ci.readGuestBytes(msg_pl.ptr, msg_pl.len) orelse
            return error.OutOfBoundsMemory;
        try self.emitWasiLog(level, ctx_bytes, msg_bytes, allocator);
    }

    /// Test-friendly entry into the formatter (#583 B5). Public so the
    /// unit tests can drive it without standing up a full
    /// ComponentInstance + guest linmem.
    pub fn emitWasiLog(
        self: *WasiCliAdapter,
        level: WasiLogLevel,
        context_bytes: []const u8,
        message_bytes: []const u8,
        allocator: Allocator,
    ) !void {
        if (@intFromEnum(level) < @intFromEnum(self.log_level)) return;
        // Format once, then emit to both std.log and the adapter's
        // stderr sink. The `wasi_guest` scope tag lets embedders'
        // `std.log.logFn` filter / route guest log lines distinctly
        // from host-internal logs.
        const line = try std.fmt.allocPrint(
            allocator,
            "[wasi_guest] [{s}] [{s}] {s}\n",
            .{ level.name(), context_bytes, message_bytes },
        );
        defer allocator.free(line);
        // Skip the `std.log` path under Zig's test runner — the
        // default test logger promotes `std.log.warn` / `std.log.err`
        // into test failures (see lib/std/testing.zig logFn). The
        // `self.stderr` write below still exercises the actual host
        // surface, which is what the WASI fixtures observe.
        if (!builtin.is_test) {
            const log = std.log.scoped(.wasi_guest);
            switch (level.toStdLogLevel()) {
                .debug => log.debug("[{s}] [{s}] {s}", .{ level.name(), context_bytes, message_bytes }),
                .info => log.info("[{s}] {s}", .{ context_bytes, message_bytes }),
                .warn => log.warn("[{s}] {s}", .{ context_bytes, message_bytes }),
                .err => log.err("[{s}] [{s}] {s}", .{ level.name(), context_bytes, message_bytes }),
            }
        }
        // Always also push to the adapter's stderr sink so the line
        // is visible regardless of build mode (std.log is compile-time
        // gated in ReleaseFast). For `initWithHostStdio` this is the
        // host process's real stderr fd; for `init` it's the captured
        // buffer that tests scan via `getStderrBytes`.
        self.stderr_operation_claim.acquire();
        defer self.stderr_operation_claim.release();
        switch (self.stderr.write(line, self.allocator)) {
            .ok, .err, .closed => {},
        }
    }

    /// `wasi:clocks/wall-clock.now: () -> datetime` (#146).
    /// Lifts UNIX-epoch nanos into `record { seconds: u64, nanoseconds: u32 }`.
    /// Honors `self.wall_clock_override` for deterministic tests.
    fn wallClockNow(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        const dt = self.wall_clock_override orelse readClockDatetime(.REALTIME);
        results[0] = try buildDatetimeRecord(allocator, dt);
    }

    /// `wasi:clocks/wall-clock.resolution: () -> datetime` (#146).
    /// Reports a 1-nanosecond resolution; conservative for any host that
    /// can read `nanoTimestamp`.
    fn wallClockResolution(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        results[0] = try buildDatetimeRecord(allocator, .{ .seconds = 0, .nanoseconds = 1 });
    }

    /// `wasi:clocks/monotonic-clock.now: () -> instant` (#146).
    /// `instant` lifts as a flat `u64`. Honors `monotonic_clock_override`.
    fn monotonicClockNow(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        results[0] = .{ .u64 = self.monotonicNs() };
    }

    /// `wasi:clocks/monotonic-clock.resolution: () -> duration` (#146).
    /// `duration` lifts as `u64`; we report 1ns.
    fn monotonicClockResolution(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        results[0] = .{ .u64 = 1 };
    }

    fn u64Arg(value: InterfaceValue) !u64 {
        return switch (value) {
            .u64 => |v| v,
            .s64 => |v| @bitCast(v),
            .u32 => |v| v,
            .s32 => |v| @as(u32, @bitCast(v)),
            else => error.InvalidArgs,
        };
    }

    /// `wasi:clocks/monotonic-clock.subscribe-instant: (instant) -> own<pollable>`.
    fn monotonicSubscribeInstant(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const deadline = try u64Arg(args[0]);
        const handle = try self.pushPollable(.{ .monotonic_timer = deadline });
        results[0] = .{ .handle = handle };
    }

    /// `wasi:clocks/monotonic-clock.subscribe-duration: (duration) -> own<pollable>`.
    fn monotonicSubscribeDuration(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const duration = try u64Arg(args[0]);
        const deadline = self.monotonicNs() +| duration;
        const handle = try self.pushPollable(.{ .monotonic_timer = deadline });
        results[0] = .{ .handle = handle };
    }

    /// Read the monotonic clock as nanoseconds. Honors
    /// `monotonic_clock_override` for tests.
    fn monotonicNs(self: *const WasiCliAdapter) u64 {
        if (self.monotonic_clock_override) |v| return v;
        return readClockNs(.MONOTONIC);
    }

    // ── wasi:clocks@0.3.0 (#483) ───────────────────────────────────────────
    //
    // The 0.3 monotonic-clock surface drops the `subscribe-instant` /
    // `subscribe-duration` `pollable` constructors and replaces them with
    // two `async func`s — `wait-for(duration)` and `wait-until(when)` —
    // each lowered as a host function returning a `future<()>` handle.
    // The host completes the future when the deadline elapses; readers
    // observe completion through `future.read` (unit-type fast-path in
    // `executor.zig`) or, for the 0.2 polyfill, through a wrapping
    // `.future_timer` pollable.

    /// `wasi:clocks/monotonic-clock@0.3.x.now: () -> mark` (#483).
    /// `mark` lifts as a flat `u64` (renamed from 0.2 `instant`; same wire).
    fn monotonicClockNowP3(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        results[0] = .{ .u64 = self.monotonicNs() };
    }

    /// `wasi:clocks/monotonic-clock@0.3.x.get-resolution: () -> duration` (#483).
    /// Renamed from 0.2 `resolution`; we report 1ns.
    fn monotonicClockGetResolutionP3(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        results[0] = .{ .u64 = 1 };
    }

    /// Allocate a `future<()>` in `ci.futures`. Deadlines already reached
    /// are ready immediately; future deadlines register a host-side timer
    /// in `self.timer_futures`. Returns the handle to lower as the
    /// `future<()>` result of `wait-for` / `wait-until`. (#483.)
    fn spawnTimerFuture(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        deadline_ns: u64,
    ) !u32 {
        const ready = deadline_ns <= self.monotonicNs();
        const handle = ci.allocAsyncHandle();
        try ci.futures.put(ci.allocator, handle, .{
            .elem_type_idx = 0, // unit type
            .state = if (ready) .ready else .pending,
            // Flagged so `executor.joinWaitable` knows to register this
            // handle as a `.subtask` waitable and `popReadyEvent` knows
            // to emit `EVENT_SUBTASK` with `STATUS_RETURNED` rather than
            // a `future.read` return-code (#551).
            .subtask_managed = true,
        });
        errdefer _ = ci.futures.remove(handle);
        if (!ready) {
            const timer_handle = try self.timer_futures.publish(.{
                .handle = handle,
                .deadline_ns = deadline_ns,
            });
            errdefer std.debug.assert(self.timer_futures.remove(timer_handle));
        }
        return handle;
    }

    /// `wasi:clocks/monotonic-clock@0.3.x.wait-for: async func(duration) -> future<()>`
    /// (#483). Returns a future handle that completes after `how-long` ns.
    fn monotonicWaitFor(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const duration = try u64Arg(args[0]);
        const deadline = self.monotonicNs() +| duration;
        const handle = try self.spawnTimerFuture(ci, deadline);
        results[0] = .{ .handle = handle };
    }

    /// `wasi:clocks/monotonic-clock@0.3.x.wait-until: async func(when: mark) -> future<()>`
    /// (#483). Returns a future handle that completes once the absolute
    /// deadline `when` has been reached.
    fn monotonicWaitUntil(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const when = try u64Arg(args[0]);
        const handle = try self.spawnTimerFuture(ci, when);
        results[0] = .{ .handle = handle };
    }

    /// `wasi:clocks/system-clock@0.3.x.now: () -> instant` (#483).
    ///
    /// `instant = record { seconds: s64, nanoseconds: u32 }`. Note `seconds`
    /// is **signed** in 0.3 (was `u64` in 0.2's `wall-clock.datetime`).
    /// Honors `wall_clock_override` for deterministic tests.
    fn systemClockNowP3(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        const dt = self.wall_clock_override orelse readClockDatetime(.REALTIME);
        const fields = try allocator.alloc(InterfaceValue, 2);
        fields[0] = .{ .s64 = @bitCast(dt.seconds) };
        fields[1] = .{ .u32 = dt.nanoseconds };
        results[0] = .{ .record_val = fields };
    }

    /// `wasi:clocks/system-clock@0.3.x.get-resolution: () -> duration` (#483).
    /// Renamed from 0.2 `wall-clock.resolution`; lifts as `u64` ns (1ns).
    fn systemClockGetResolutionP3(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        results[0] = .{ .u64 = 1 };
    }

    /// 0.2-on-0.3 polyfill (#483): a `subscribe-duration` registered as
    /// part of a P3-routed P2 guest world. Backed by a P3 timer-future
    /// rather than the 0.2 `.monotonic_timer` pollable, so the
    /// `completeDueTimerFutures` wakeup path drives both alike.
    fn subscribeDurationP3Polyfill(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const duration = try u64Arg(args[0]);
        const deadline = self.monotonicNs() +| duration;
        const fut_handle = try self.spawnTimerFuture(ci, deadline);
        self.async_state_claim.acquire();
        self.timer_future_ready.put(self.allocator, fut_handle, false) catch |err| {
            self.async_state_claim.release();
            return err;
        };
        self.async_state_claim.release();
        errdefer {
            self.async_state_claim.acquire();
            _ = self.timer_future_ready.remove(fut_handle);
            self.async_state_claim.release();
        }
        const ph = try self.pushPollable(.{ .future_timer = fut_handle });
        results[0] = .{ .handle = ph };
    }

    /// Drain any P3 timer-futures whose deadline has elapsed (#483, #551).
    /// Sets `Future.state = .ready`, wakes a registered read-waitable, and
    /// flips the `.future_timer` polyfill ready flag. Returns whether any
    /// timer fired. Safe to call from any polling site; idempotent.
    ///
    /// The `code` published on the WaitableSet payload depends on the
    /// future's `subtask_managed` flag: timer-futures minted by
    /// `wasi:clocks` `wait-for` / `wait-until` (subtask_managed=true)
    /// carry a wit-bindgen async-ABI `STATUS_RETURNED` discriminant so
    /// the guest's `Subtask` decoder finishes the await; legacy
    /// 0.2-on-0.3 polyfill timer-futures (subtask_managed=false) keep
    /// the `packStatus(.completed, 0)` shape consumed by the
    /// future/stream `ReturnCode` decoder. (#551.)
    pub fn completeDueTimerFutures(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        allocator: Allocator,
    ) bool {
        const now = self.monotonicNs();
        var fired = false;
        const handles = self.timer_futures.snapshotHandles(self.allocator) catch return false;
        defer self.allocator.free(handles);
        for (handles) |timer_handle| {
            var timer_lease = self.timer_futures.acquire(timer_handle) orelse continue;
            const tf = timer_lease.value().*;
            if (tf.deadline_ns > now) {
                timer_lease.release();
                continue;
            }
            timer_lease.release();
            if (!self.timer_futures.remove(timer_handle)) continue;
            if (ci.futures.acquire(tf.handle)) |initial_lease| {
                var future_lease = initial_lease;
                const fut = future_lease.value();
                fut.pending_read = null;
                fut.state = .ready;
                const registration = fut.read_waitable;
                const code: u32 = if (fut.subtask_managed)
                    executor_root.STATUS_RETURNED
                else
                    async_canon.packStatus(.completed, 0);
                future_lease.release();
                _ = allocator;
                _ = ci.notifyWaitable(registration, code);
            }
            self.async_state_claim.acquire();
            if (self.timer_future_ready.getPtr(tf.handle)) |slot| slot.* = true;
            self.async_state_claim.release();
            fired = true;
        }
        return fired;
    }

    fn componentFutureExists(ci: *ComponentInstance, handle: u32) bool {
        var lease = ci.futures.acquire(handle) orelse return false;
        lease.release();
        return true;
    }

    fn cancelComponentFuture(ci: *ComponentInstance, handle: u32) bool {
        var lease = ci.futures.acquire(handle) orelse return false;
        const future = lease.value();
        future.pending_read = null;
        future.state = .closed;
        future.write_closed = true;
        const registration = future.read_waitable;
        lease.release();
        _ = ci.notifyWaitable(
            registration,
            executor_root.STATUS_STARTED_CANCELLED,
        );
        return true;
    }

    /// Drain any pending `udp-socket.receive` futures whose backing fd
    /// has a datagram available, settling each future with the lifted
    /// `result<tuple<list<u8>, ip-socket-address>, error-code>` ok
    /// payload. Mirrors the timer-future settle path in
    /// `completeDueTimerFutures` — the future's `subtask_managed`
    /// flag (set by the async-lower trampoline) routes the wakeup
    /// through the `.subtask` waitable kind with `STATUS_RETURNED`
    /// so the guest's awaited `.receive()` resolves cleanly. (#576)
    ///
    /// Pending entries whose backing socket has been dropped / torn
    /// down are settled with `err(invalid_state)`. A successful
    /// recvfrom always consumes the entry; spurious wakeups (poll
    /// said ready but recvfrom would-block) leave the entry in place
    /// for the next tick.
    pub fn completeReadyPendingUdpReceives(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        allocator: Allocator,
    ) bool {
        var fired = false;
        const handles = self.pending_udp_receives.snapshotHandles(self.allocator) catch
            return false;
        defer self.allocator.free(handles);
        for (handles) |operation_handle| {
            var operation_lease = self.pending_udp_receives.acquire(operation_handle) orelse
                continue;
            const entry = operation_lease.value();
            const future_handle = entry.future_handle;
            const cancelled_before_poll = entry.cancelled.load(.acquire);
            const parent_closing = if (comptime build_options.lib_wasi_threads)
                if (entry.socket_lease) |*parent| parent.isClosing() else true
            else
                false;
            const future_missing = !componentFutureExists(ci, future_handle);
            if (future_missing or
                cancelled_before_poll or
                parent_closing)
            {
                if (entry.claimed.cmpxchgStrong(false, true, .acquire, .monotonic) != null) {
                    operation_lease.release();
                    continue;
                }
                operation_lease.release();
                if (!self.pending_udp_receives.remove(operation_handle)) continue;
                if (future_missing) continue;
                if (cancelled_before_poll) {
                    fired = cancelComponentFuture(ci, future_handle);
                } else {
                    self.settlePendingUdpReceiveErr(
                        ci,
                        future_handle,
                        .invalid_state,
                        allocator,
                    ) catch {};
                    fired = true;
                }
                continue;
            }

            var sock_lease = self.lookupSocket(entry.sock_handle) orelse {
                if (entry.claimed.cmpxchgStrong(false, true, .acquire, .monotonic) != null) {
                    operation_lease.release();
                    continue;
                }
                operation_lease.release();
                if (!self.pending_udp_receives.remove(operation_handle)) continue;
                self.settlePendingUdpReceiveErr(
                    ci,
                    future_handle,
                    .invalid_state,
                    allocator,
                ) catch {};
                fired = true;
                continue;
            };
            const sock = sock_lease.value();
            if (sock.resource_generation != entry.socket_generation or
                sock.kind != .udp or
                sock.host_socket == null)
            {
                sock_lease.release();
                if (entry.claimed.cmpxchgStrong(false, true, .acquire, .monotonic) != null) {
                    operation_lease.release();
                    continue;
                }
                operation_lease.release();
                if (!self.pending_udp_receives.remove(operation_handle)) continue;
                self.settlePendingUdpReceiveErr(
                    ci,
                    future_handle,
                    .invalid_state,
                    allocator,
                ) catch {};
                fired = true;
                continue;
            }
            const host_socket = sock.host_socket.?;
            if (!fdPollReady(host_socket.handle, pollInEvents())) {
                sock_lease.release();
                operation_lease.release();
                continue;
            }
            if (entry.claimed.cmpxchgStrong(false, true, .acquire, .monotonic) != null) {
                sock_lease.release();
                operation_lease.release();
                continue;
            }
            if (entry.cancelled.load(.acquire)) {
                sock_lease.release();
                operation_lease.release();
                if (!self.pending_udp_receives.remove(operation_handle)) continue;
                fired = cancelComponentFuture(ci, future_handle);
                continue;
            }
            const io = std.Io.Threaded.global_single_threaded.io();
            var buf: [65536]u8 = undefined;
            const recv_res = host_socket.receiveTimeout(io, &buf, .{
                .duration = .{ .raw = .{ .nanoseconds = 0 }, .clock = .awake },
            });
            sock_lease.release();
            if (entry.cancelled.load(.acquire)) {
                operation_lease.release();
                if (!self.pending_udp_receives.remove(operation_handle)) continue;
                fired = cancelComponentFuture(ci, future_handle);
                continue;
            }
            if (recv_res) |recv| {
                operation_lease.release();
                if (self.pending_udp_receives.remove(operation_handle)) {
                    self.settlePendingUdpReceiveOk(
                        ci,
                        future_handle,
                        recv.data,
                        recv.from,
                        allocator,
                    ) catch {
                        self.settlePendingUdpReceiveErr(
                            ci,
                            future_handle,
                            .unknown,
                            allocator,
                        ) catch {};
                    };
                    fired = true;
                }
            } else |_| {
                // Spurious poll wakeup — release the claim and retry on the
                // next event-loop tick.
                entry.claimed.store(false, .release);
                if (entry.cancelled.load(.acquire) and
                    entry.claimed.cmpxchgStrong(
                        false,
                        true,
                        .acquire,
                        .monotonic,
                    ) == null)
                {
                    operation_lease.release();
                    if (!self.pending_udp_receives.remove(operation_handle)) continue;
                    fired = cancelComponentFuture(ci, future_handle);
                } else {
                    operation_lease.release();
                }
            }
        }
        return fired;
    }

    /// Settle a pending `udp-socket.receive` future with an `ok` arm
    /// carrying the just-received datagram. Lowers the
    /// `tuple<list<u8>, ip-socket-address>` payload into the
    /// canonical-ABI byte buffer used by the executor's async-lower
    /// retptr copy and stashes it on `fut.payload` so the
    /// `Future.deinit` path frees it at drop time. (#576)
    fn settlePendingUdpReceiveOk(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        future_handle: u32,
        data: []const u8,
        remote: std.Io.net.IpAddress,
        allocator: Allocator,
    ) !void {
        _ = self;
        const ok_tuple = try socketsP3LowerUdpReceivePayload(ci, data, remote);
        defer {
            const fields = ok_tuple.tuple_val;
            fields[1].deinit(ci.allocator);
            ci.allocator.free(fields);
        }
        const ok_payload = try ci.allocator.create(InterfaceValue);
        defer ci.allocator.destroy(ok_payload);
        ok_payload.* = ok_tuple;
        const ok_result = InterfaceValue{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
        const payload_bytes = try socketsP3LowerAsyncPayload(ci.allocator, .udp_receive_err, ok_result);
        settleFutureDeferred(ci, future_handle, payload_bytes, allocator);
    }

    /// Settle a pending `udp-socket.receive` future with an `err`
    /// arm carrying the given `error-code` discriminant. Used for
    /// socket-torn-down and lowering-failure paths.
    fn settlePendingUdpReceiveErr(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        future_handle: u32,
        code: SocketErrorCode,
        allocator: Allocator,
    ) !void {
        _ = self;
        const val = try socketsP3BuildUnitErrResultIv(ci.allocator, false, code);
        defer val.deinit(ci.allocator);
        const payload_bytes = try socketsP3LowerAsyncPayload(ci.allocator, .udp_receive_err, val);
        settleFutureDeferred(ci, future_handle, payload_bytes, allocator);
    }

    /// Worker thread body for an outbound HTTP fetch (#583 A2).
    /// Drives the lower-level `std.http.Client.request` /
    /// `Request.receiveHead` / body-reader path via
    /// `httpClientLowLevelFetch` so the response header list is
    /// captured alongside the status line (#583 A4 — the previous
    /// `std.http.Client.fetch` projection discarded headers). Publishes
    /// the outcome to the shared heap struct so the adapter's drain
    /// side can pick it up. The worker owns `req` (deinit on return)
    /// but only borrows `req.shared` — the adapter holds the other
    /// reference and frees it once `thread.join()` has returned.
    ///
    /// Errors from the underlying client are mapped onto their
    /// specific `wasi:http/types.error-code` variant by
    /// `mapHttpFetchError` (#583 A3 — connect-refused, TLS, DNS,
    /// framing, URI-parse, etc. each get a dedicated arm; only truly-
    /// unclassified failures fall through to `internal_error`). The
    /// `httpClientSendP3` synchronous path uses the same helper, so
    /// both surfaces produce identical discriminants AND header sets.
    ///
    /// Cancel propagation (#583 B1 follow-up): the worker passes
    /// `&shared.cancelled` into `httpClientLowLevelFetch`; the helper
    /// polls that flag at every phase boundary (pre-connect,
    /// pre-send, pre-receive-head, pre-body-read, and on every
    /// `http_cancel_body_chunk_bytes`-sized body chunk) and surfaces
    /// cancellation as `error.HttpFetchCancelled`. We translate that
    /// sentinel to the `HTTP_request_denied` 0.3 error-code variant
    /// — the same discriminant the drainer surfaces when it observes
    /// `shared.cancelled` post-completion — so worker-side and
    /// drainer-side cancel paths produce identical guest-visible
    /// outcomes regardless of when in the fetch lifecycle the
    /// cancel landed.
    fn httpFetchWorker(req: *HttpFetchRequest) void {
        // Worker owns its *HttpFetchRequest — free both the inner
        // resources and the heap struct itself before returning.
        const alloc = req.allocator;
        defer alloc.destroy(req);
        defer req.deinit();
        const shared = req.shared;
        // Wake the host's block/poll loop once the outcome is published.
        // A top-level defer fires after every `done.store(.release)` path
        // below (pre-fetch cancel, cancel, error, success), so the host's
        // `poll()` on the waker fd always unparks. (#833)
        defer if (shared.waker) |w| w.signal();

        // Honor a pre-fetch cancel before doing any network work.
        // `httpClientLowLevelFetch`'s pre-connect check below would
        // catch this too, but bailing here saves the
        // `std.http.Client` init + URI parse on a guaranteed-cancel
        // outcome.
        if (shared.cancelled.load(.acquire)) {
            shared.outcome = .{ .failure = .HTTP_request_denied };
            shared.done.store(true, .release);
            return;
        }

        const result = httpClientLowLevelFetch(
            alloc,
            req.io,
            req.url,
            req.method,
            req.headers_buf,
            req.payload,
            req.options,
            &shared.cancelled,
        ) catch |err| switch (err) {
            // Phase-boundary cancel: surface as `HTTP_request_denied`,
            // mirroring the drainer's post-completion cancel arm so
            // guest observability is uniform regardless of which
            // side noticed cancellation first.
            error.HttpFetchCancelled => {
                shared.outcome = .{ .failure = .HTTP_request_denied };
                shared.done.store(true, .release);
                return;
            },
            // Funnel through the same error-mapping table the
            // synchronous P3 `client.send` path uses (#583 A3) so the
            // worker and the in-thread `httpClientSendP3` produce
            // identical `error-code` discriminants.
            else => |e| {
                shared.outcome = .{ .failure = mapHttpFetchError(e) };
                shared.done.store(true, .release);
                return;
            },
        };

        shared.outcome = .{ .success = .{
            .status = result.status,
            .body = result.body,
            .headers = result.headers,
        } };
        shared.done.store(true, .release);
    }

    /// Drain any pending outbound HTTP fetches whose worker thread has
    /// published an outcome. Settles each `FutureIncomingResponse` via
    /// the standard `state = .ready_ok` / `state = .ready_err`
    /// transition the P2 `future-incoming-response.get` path consumes,
    /// then joins the worker thread and frees the shared heap struct.
    ///
    /// A pending entry retains the exact future node. Guest drop removes
    /// the public handle immediately and marks that node closing; the
    /// drainer then discards the outcome instead of settling a replacement.
    pub fn drainPendingHttpFetches(self: *WasiCliAdapter) void {
        const handles = self.pending_http_fetches.snapshotHandles(self.allocator) catch
            return;
        defer self.allocator.free(handles);
        for (handles) |operation_handle| {
            var operation_lease = self.pending_http_fetches.acquire(operation_handle) orelse
                continue;
            const entry = operation_lease.value();
            if (!entry.armed.load(.acquire)) {
                operation_lease.release();
                continue;
            }
            const shared = entry.shared orelse {
                operation_lease.release();
                continue;
            };
            if (!shared.done.load(.acquire)) {
                operation_lease.release();
                continue;
            }
            if (!self.pending_http_fetches.remove(operation_handle)) {
                operation_lease.release();
                continue;
            }
            const locked_entry = operation_lease.lock();
            const thread = locked_entry.thread orelse {
                operation_lease.unlock();
                operation_lease.release();
                continue;
            };
            locked_entry.thread = null;
            operation_lease.unlock();
            // Worker has published — join is non-blocking.
            thread.join();
            self.settlePendingHttpFetch(entry);
            const cleanup_entry = operation_lease.lock();
            cleanup_entry.shared.?.outcome = .{ .failure = .internal_error };
            operation_lease.unlock();
            operation_lease.release();
        }
    }

    /// Translate a worker-published `HttpFetchOutcome` into the
    /// matching `FutureIncomingResponse.state` transition. If the
    /// future's slot has already been dropped (resource-drop on the
    /// guest side) the outcome is discarded — `.success.body` and
    /// `.success.headers` are freed here, otherwise they transfer
    /// ownership to the freshly allocated `IncomingResponse` /
    /// `HttpFields`.
    fn settlePendingHttpFetch(self: *WasiCliAdapter, entry: *PendingHttpFetch) void {
        const shared = entry.shared orelse return;
        const future_lease = if (entry.future_lease) |*lease| lease else {
            freePendingHttpOutcome(self.allocator, shared.outcome);
            return;
        };
        // Guest dropped the future — the retained lease keeps this exact
        // node alive, but closing resources must never receive completion.
        if (future_lease.isClosing()) {
            switch (shared.outcome) {
                .success => |s| {
                    self.allocator.free(s.body);
                    freeOwnedHttpHeaders(self.allocator, s.headers);
                },
                .failure => {},
            }
            return;
        }
        // Guest issued `task.cancel` mid-fetch (or adapter signalled
        // cancellation). Surface the cancel as `HTTP_request_denied`
        // — the closest WIT discriminant for "the request was not
        // delivered" without inventing new error-code variants.
        if (shared.cancelled.load(.acquire)) {
            switch (shared.outcome) {
                .success => |s| {
                    self.allocator.free(s.body);
                    freeOwnedHttpHeaders(self.allocator, s.headers);
                },
                .failure => {},
            }
            _ = setPendingHttpFutureState(
                entry,
                .{ .ready_err = @intFromEnum(HttpErrorCode.HTTP_request_denied) },
            );
            return;
        }
        switch (shared.outcome) {
            .success => |s| {
                const resp_fields = self.allocator.create(HttpFields) catch {
                    self.allocator.free(s.body);
                    freeOwnedHttpHeaders(self.allocator, s.headers);
                    _ = setPendingHttpFutureState(
                        entry,
                        .{ .ready_err = @intFromEnum(HttpErrorCode.internal_error) },
                    );
                    return;
                };
                // Transfer ownership of the worker-allocated header
                // entries into the `HttpFields` resource (#583 A4).
                // The slice backing `s.headers` was allocated with
                // `self.allocator` by `httpClientLowLevelFetch`, so it
                // is safe to splice in as the field's backing storage.
                resp_fields.* = .{
                    .entries = std.ArrayListUnmanaged(HttpFieldEntry).fromOwnedSlice(s.headers),
                };
                const resp_fields_handle = self.pushHttpFields(resp_fields) catch {
                    self.allocator.free(s.body);
                    resp_fields.deinit(self.allocator);
                    self.allocator.destroy(resp_fields);
                    _ = setPendingHttpFutureState(
                        entry,
                        .{ .ready_err = @intFromEnum(HttpErrorCode.internal_error) },
                    );
                    return;
                };
                const ir = self.allocator.create(IncomingResponse) catch {
                    self.allocator.free(s.body);
                    std.debug.assert(self.http_fields_table.remove(resp_fields_handle));
                    _ = setPendingHttpFutureState(
                        entry,
                        .{ .ready_err = @intFromEnum(HttpErrorCode.internal_error) },
                    );
                    return;
                };
                ir.* = .{
                    .status = s.status,
                    .headers_handle = resp_fields_handle,
                    .body_data = s.body,
                };
                const ir_handle = self.pushIncomingResponse(ir) catch {
                    self.allocator.free(s.body);
                    ir.body_data = null;
                    self.allocator.destroy(ir);
                    std.debug.assert(self.http_fields_table.remove(resp_fields_handle));
                    _ = setPendingHttpFutureState(
                        entry,
                        .{ .ready_err = @intFromEnum(HttpErrorCode.internal_error) },
                    );
                    return;
                };
                if (!setPendingHttpFutureState(entry, .{ .ready_ok = ir_handle })) {
                    std.debug.assert(self.http_incoming_responses.remove(ir_handle));
                    std.debug.assert(self.http_fields_table.remove(resp_fields_handle));
                }
            },
            .failure => |code| {
                _ = setPendingHttpFutureState(
                    entry,
                    .{ .ready_err = @intFromEnum(code) },
                );
            },
        }
    }

    fn setPendingHttpFutureState(
        entry: *PendingHttpFetch,
        state: FutureIncomingResponse.State,
    ) bool {
        const lease = if (entry.future_lease) |*future_lease| future_lease else return false;
        if (lease.isClosing()) return false;
        const future = lease.value().*;
        future.operation_claim.acquire();
        defer future.operation_claim.release();
        if (lease.isClosing()) return false;
        future.state = state;
        return true;
    }

    fn httpFetchOptionsP2(
        self: *WasiCliAdapter,
        args: []const InterfaceValue,
    ) HttpFetchOptions {
        if (args.len < 2) return .{};
        return switch (args[1]) {
            .option_val => |opt| if (opt.is_some and opt.payload != null) switch (opt.payload.?.*) {
                .handle => |h| self.snapshotRequestOptionsP2(h),
                else => .{},
            } else .{},
            else => .{},
        };
    }

    fn snapshotRequestOptionsP2(self: *WasiCliAdapter, handle: u32) HttpFetchOptions {
        var lease = self.lookupRequestOptions(handle) orelse return .{};
        defer lease.release();
        const options = lease.lock().*;
        const snapshot = HttpFetchOptions.fromRequestOptions(options);
        lease.unlock();
        return snapshot;
    }

    fn snapshotRequestOptionsP3(self: *WasiCliAdapter, handle: u32) HttpFetchOptions {
        var lease = self.lookupRequestOptionsP3(handle) orelse return .{};
        defer lease.release();
        const options = lease.lock().*;
        const snapshot = HttpFetchOptions.fromRequestOptions(options);
        lease.unlock();
        return snapshot;
    }

    fn httpFetchOptionsP3(
        _: *WasiCliAdapter,
        request: *const HttpRequestP3,
    ) HttpFetchOptions {
        return request.fetch_options;
    }

    /// Mint a `.pending` `FutureIncomingResponse`, snapshot the
    /// outgoing request into worker-owned memory, and spawn a worker
    /// thread that drives `std.http.Client.fetch` to completion.
    /// Returns the future handle the guest observes via
    /// `result<own<future-incoming-response>, error-code>`.
    /// (#583 A2)
    fn spawnHttpFetchPending(
        self: *WasiCliAdapter,
        url: []const u8,
        method: std.http.Method,
        headers: []const std.http.Header,
        payload: ?[]const u8,
        options: HttpFetchOptions,
    ) !u32 {
        const url_copy = try self.allocator.dupe(u8, url);
        errdefer self.allocator.free(url_copy);

        const names = try self.allocator.alloc([]u8, headers.len);
        errdefer self.allocator.free(names);
        const values = try self.allocator.alloc([]u8, headers.len);
        errdefer self.allocator.free(values);
        const header_buf = try self.allocator.alloc(std.http.Header, headers.len);
        errdefer self.allocator.free(header_buf);

        var dup_filled: usize = 0;
        errdefer {
            for (names[0..dup_filled]) |n| self.allocator.free(n);
            for (values[0..dup_filled]) |v| self.allocator.free(v);
        }
        while (dup_filled < headers.len) : (dup_filled += 1) {
            names[dup_filled] = try self.allocator.dupe(u8, headers[dup_filled].name);
            values[dup_filled] = try self.allocator.dupe(u8, headers[dup_filled].value);
            header_buf[dup_filled] = .{
                .name = names[dup_filled],
                .value = values[dup_filled],
            };
        }

        const payload_copy: ?[]u8 = if (payload) |p|
            try self.allocator.dupe(u8, p)
        else
            null;
        errdefer if (payload_copy) |p| self.allocator.free(p);

        const shared = try self.allocator.create(PendingHttpFetchShared);
        errdefer self.allocator.destroy(shared);
        shared.* = .{};
        // Self-pipe waker so the host can sleep on this fetch's
        // completion instead of busy-spinning (#833). Pipe-creation
        // failure (or Windows) degrades to a `null` waker — correctness
        // is unaffected, only the old re-poll cadence returns.
        shared.waker = Waker.init() catch null;
        errdefer if (shared.waker) |*w| w.deinit();

        const req = try self.allocator.create(HttpFetchRequest);
        errdefer self.allocator.destroy(req);
        req.* = .{
            .allocator = self.allocator,
            .io = self.http_worker_io.io(),
            .url = url_copy,
            .method = method,
            .options = options,
            .headers_buf = header_buf,
            .headers_names = names,
            .headers_values = values,
            .payload = payload_copy,
            .shared = shared,
        };

        // Mint the `.pending` future first so a thread-spawn failure
        // doesn't strand the shared struct on a non-existent slot.
        const fut = try self.allocator.create(FutureIncomingResponse);
        var fut_owned = true;
        errdefer if (fut_owned) self.allocator.destroy(fut);
        fut.* = .{ .state = .pending };
        const fh = try self.pushFutureResponse(fut);
        fut_owned = false;
        var future_lease = self.http_future_responses.acquire(fh).?;
        errdefer future_lease.release();
        errdefer std.debug.assert(self.http_future_responses.remove(fh));

        // Publish an unarmed stable operation before spawning. Event
        // drivers skip it until thread/shared ownership is installed, so
        // allocation failure can still roll back without a live worker.
        const published_operation = try self.pending_http_fetches.publishLeased(.{
            .future_handle = fh,
            .thread = null,
            .shared = null,
            .future_lease = null,
        });
        const operation_handle = published_operation.handle;
        errdefer _ = self.pending_http_fetches.remove(operation_handle);
        var operation_lease = published_operation.lease;
        errdefer operation_lease.release();

        const thread = std.Thread.spawn(.{}, httpFetchWorker, .{req}) catch |err| {
            return err;
        };
        const operation = operation_lease.lock();
        operation.thread = thread;
        operation.shared = shared;
        operation.future_lease = future_lease;
        operation_lease.unlock();
        operation.armed.store(true, .release);
        operation_lease.release();
        return fh;
    }

    /// Mint a `.pending` `async_mod.Future` on `ci.futures`, snapshot
    /// the outgoing request into worker-owned memory, and spawn a
    /// worker thread that drives `std.http.Client.fetch` to
    /// completion (#589). Returns the future handle the guest
    /// observes in `results[0]` of the `canon.lower (async)`
    /// trampoline; the executor stashes its `async_lower_retptr`
    /// onto the same slot if the trampoline observes the future
    /// `.pending`, and `drainPendingHttpFetchesP3` writes the
    /// canonical-ABI-lowered `result<own<response>, error-code>`
    /// bytes back to that retptr when the worker publishes its
    /// outcome.
    ///
    /// Mirrors `spawnHttpFetchPending` but for the P3 path; the
    /// worker thread / coordination block are reused verbatim.
    fn spawnHttpFetchPendingP3(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        url: []const u8,
        method: std.http.Method,
        headers: []const std.http.Header,
        payload: ?[]const u8,
        options: HttpFetchOptions,
    ) !u32 {
        const url_copy = try self.allocator.dupe(u8, url);
        errdefer self.allocator.free(url_copy);

        const names = try self.allocator.alloc([]u8, headers.len);
        errdefer self.allocator.free(names);
        const values = try self.allocator.alloc([]u8, headers.len);
        errdefer self.allocator.free(values);
        const header_buf = try self.allocator.alloc(std.http.Header, headers.len);
        errdefer self.allocator.free(header_buf);

        var dup_filled: usize = 0;
        errdefer {
            for (names[0..dup_filled]) |n| self.allocator.free(n);
            for (values[0..dup_filled]) |v| self.allocator.free(v);
        }
        while (dup_filled < headers.len) : (dup_filled += 1) {
            names[dup_filled] = try self.allocator.dupe(u8, headers[dup_filled].name);
            values[dup_filled] = try self.allocator.dupe(u8, headers[dup_filled].value);
            header_buf[dup_filled] = .{
                .name = names[dup_filled],
                .value = values[dup_filled],
            };
        }

        const payload_copy: ?[]u8 = if (payload) |p|
            try self.allocator.dupe(u8, p)
        else
            null;
        errdefer if (payload_copy) |p| self.allocator.free(p);

        const shared = try self.allocator.create(PendingHttpFetchShared);
        errdefer self.allocator.destroy(shared);
        shared.* = .{};
        // Self-pipe waker so the host can sleep on this fetch's
        // completion instead of re-polling on a 1ms cadence (#833).
        shared.waker = Waker.init() catch null;
        errdefer if (shared.waker) |*w| w.deinit();

        const req = try self.allocator.create(HttpFetchRequest);
        errdefer self.allocator.destroy(req);
        req.* = .{
            .allocator = self.allocator,
            .io = self.http_worker_io.io(),
            .url = url_copy,
            .method = method,
            .options = options,
            .headers_buf = header_buf,
            .headers_names = names,
            .headers_values = values,
            .payload = payload_copy,
            .shared = shared,
        };

        // Mint the `.pending` async future on `ci.futures` first so a
        // thread-spawn failure doesn't strand the shared struct.
        const fh = ci.allocAsyncHandle();
        try ci.futures.put(ci.allocator, fh, .{
            .elem_type_idx = 0,
            .state = .pending,
        });
        errdefer _ = ci.futures.remove(fh);

        const published_operation = try self.pending_http_fetches_p3.publishLeased(.{
            .future_handle = fh,
            .ci = ci,
            .thread = null,
            .shared = null,
        });
        const operation_handle = published_operation.handle;
        errdefer _ = self.pending_http_fetches_p3.remove(operation_handle);
        var operation_lease = published_operation.lease;
        errdefer operation_lease.release();

        const thread = std.Thread.spawn(.{}, httpFetchWorker, .{req}) catch |err| {
            return err;
        };
        const operation = operation_lease.lock();
        operation.thread = thread;
        operation.shared = shared;
        operation_lease.unlock();
        operation.armed.store(true, .release);
        operation_lease.release();
        return fh;
    }

    /// Drain any pending P3 outbound HTTP fetches whose worker thread
    /// has published an outcome. Lowers the
    /// `result<own<response>, error-code>` envelope via
    /// `httpP3LowerAsyncPayload` and settles the `ci.futures` slot
    /// via `settleFutureDeferred` — the executor's stashed
    /// `async_lower_retptr` is written, the future transitions to
    /// `.ready`, and the WaitableSet wakeup fires. The worker
    /// thread is `join()`ed before the shared heap struct is
    /// freed. (#589)
    pub fn drainPendingHttpFetchesP3(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        allocator: Allocator,
    ) void {
        const handles = self.pending_http_fetches_p3.snapshotHandles(self.allocator) catch
            return;
        defer self.allocator.free(handles);
        for (handles) |operation_handle| {
            var operation_lease = self.pending_http_fetches_p3.acquire(operation_handle) orelse
                continue;
            const entry = operation_lease.value();
            if (!entry.armed.load(.acquire)) {
                operation_lease.release();
                continue;
            }
            // Only drain entries that belong to the `ComponentInstance`
            // currently driving — `pending_http_fetches_p3` is a single
            // adapter-level list shared across CIs (today's adapter
            // serves one CI at a time, but the guardrail is cheap).
            if (entry.ci != ci) {
                operation_lease.release();
                continue;
            }
            const shared = entry.shared orelse {
                operation_lease.release();
                continue;
            };
            if (!shared.done.load(.acquire)) {
                operation_lease.release();
                continue;
            }
            if (!self.pending_http_fetches_p3.remove(operation_handle)) {
                operation_lease.release();
                continue;
            }
            const locked_entry = operation_lease.lock();
            const thread = locked_entry.thread orelse {
                operation_lease.unlock();
                operation_lease.release();
                continue;
            };
            locked_entry.thread = null;
            operation_lease.unlock();
            // Worker has published — join is non-blocking.
            thread.join();
            self.settlePendingHttpFetchP3(entry, allocator);
            const cleanup_entry = operation_lease.lock();
            cleanup_entry.shared.?.outcome = .{ .failure = .internal_error };
            operation_lease.unlock();
            operation_lease.release();
        }
    }

    /// Translate a worker-published `HttpFetchOutcome` into the
    /// canonical-ABI lowered envelope and settle the future via
    /// `settleFutureDeferred`. On success this also builds the host
    /// `HttpResponseP3` resource, body stream, headers, and
    /// trailers/transmission futures so the guest can consume the
    /// response normally; on failure the envelope just carries the
    /// error-code variant. (#589)
    ///
    /// Both `success.body` and `success.headers` are worker-owned
    /// (allocated via `httpClientLowLevelFetch` per #583 A4) and
    /// transfer into the response resources on the happy path. On
    /// any failure path along the way both are freed here so the
    /// shared block can be torn down without leaks.
    fn settlePendingHttpFetchP3(
        self: *WasiCliAdapter,
        entry: *PendingHttpFetchP3,
        allocator: Allocator,
    ) void {
        const ci = entry.ci;
        const shared = entry.shared orelse return;
        var existence_lease = ci.futures.acquire(entry.future_handle) orelse {
            // Future slot already gone (guest dropped). Discard
            // outcome resources and bail.
            switch (shared.outcome) {
                .success => |s| {
                    self.allocator.free(s.body);
                    freeOwnedHttpHeaders(self.allocator, s.headers);
                },
                .failure => {},
            }
            return;
        };
        existence_lease.release();

        // task.cancel mid-fetch: settle as HTTP_request_denied, the
        // closest WIT discriminant for "request was not delivered".
        // Mirrors `settlePendingHttpFetch` for the P2 path.
        if (shared.cancelled.load(.acquire)) {
            switch (shared.outcome) {
                .success => |s| {
                    self.allocator.free(s.body);
                    freeOwnedHttpHeaders(self.allocator, s.headers);
                },
                .failure => {},
            }
            const bytes = self.lowerHttpP3ClientSendErr(.HTTP_request_denied) catch {
                closeFutureAfterSettleFailure(ci, entry.future_handle);
                return;
            };
            settleFutureDeferred(ci, entry.future_handle, bytes, allocator);
            return;
        }

        switch (shared.outcome) {
            .success => |s| {
                const resp_h = self.buildHttpResponseP3FromBody(ci, s.status, s.body, s.headers) catch {
                    self.allocator.free(s.body);
                    freeOwnedHttpHeaders(self.allocator, s.headers);
                    const bytes = self.lowerHttpP3ClientSendErr(.internal_error) catch {
                        closeFutureAfterSettleFailure(ci, entry.future_handle);
                        return;
                    };
                    settleFutureDeferred(ci, entry.future_handle, bytes, allocator);
                    return;
                };
                // Ownership of `s.body` and `s.headers` transferred
                // into the response resources by
                // `buildHttpResponseP3FromBody` — do NOT free here.
                const bytes = self.lowerHttpP3ClientSendOk(resp_h) catch {
                    const bytes_err = self.lowerHttpP3ClientSendErr(.internal_error) catch {
                        closeFutureAfterSettleFailure(ci, entry.future_handle);
                        return;
                    };
                    settleFutureDeferred(ci, entry.future_handle, bytes_err, allocator);
                    return;
                };
                settleFutureDeferred(ci, entry.future_handle, bytes, allocator);
            },
            .failure => |code| {
                const bytes = self.lowerHttpP3ClientSendErr(code) catch {
                    closeFutureAfterSettleFailure(ci, entry.future_handle);
                    return;
                };
                settleFutureDeferred(ci, entry.future_handle, bytes, allocator);
            },
        }
    }

    /// Build an `HttpResponseP3` resource plus its body stream,
    /// headers, and trailers/transmission futures from the worker's
    /// published outcome. On success both `body` and `headers`
    /// ownership transfers into the response resources — caller must
    /// NOT free them on the happy path. On failure the caller is
    /// responsible for freeing both. (#589 / #583 A4)
    fn buildHttpResponseP3FromBody(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        status: u16,
        body: []u8,
        headers: []HttpFieldEntry,
    ) !u32 {
        // Body stream — pre-filled + write-closed (guest reads to EOF).
        const body_stream_h = ci.allocAsyncHandle();
        var body_stream: async_mod.AsyncStream = .{ .elem_type_idx = 0 };
        body_stream.buffer = std.ArrayListUnmanaged(u8).fromOwnedSlice(body);
        body_stream.write_closed = true;
        try ci.streams.put(ci.allocator, body_stream_h, body_stream);
        errdefer _ = ci.streams.remove(body_stream_h);

        // Trailers future — settled to `ok(none)`; the lower-level
        // outbound path does not surface trailers yet.
        const trailers_h = try allocReadyUnitFuture(ci);
        errdefer _ = ci.futures.remove(trailers_h);

        // Lift response headers into an `HttpFields` resource (#583 A4).
        // `headers` was allocated with `self.allocator` by
        // `httpClientLowLevelFetch`, so it splices directly as the
        // field's backing storage; transport-managed headers
        // (Content-Length, Connection, …) are already stripped by
        // `isTransportManagedHeader`.
        const resp_fields = try self.allocator.create(HttpFields);
        resp_fields.* = .{
            .entries = std.ArrayListUnmanaged(HttpFieldEntry).fromOwnedSlice(headers),
        };
        const resp_fields_h = self.pushHttpFields(resp_fields) catch |err| {
            resp_fields.deinit(self.allocator);
            self.allocator.destroy(resp_fields);
            return err;
        };

        const tx_h = try allocReadyUnitFuture(ci);
        errdefer _ = ci.futures.remove(tx_h);

        const resp = try self.allocator.create(HttpResponseP3);
        errdefer self.allocator.destroy(resp);
        resp.* = .{
            .status = status,
            .headers_handle = resp_fields_h,
            .body_stream_handle = body_stream_h,
            .trailers_future_handle = trailers_h,
            .transmission_future_handle = tx_h,
        };
        const resp_h = try self.pushHttpResponseP3(resp);
        return resp_h;
    }

    /// Lower a `result<own<response>, error-code>` ok-arm envelope for
    /// `response_handle`. Owned by `self.allocator`; the executor
    /// frees the bytes on future-slot deinit. (#589)
    fn lowerHttpP3ClientSendOk(self: *WasiCliAdapter, response_handle: u32) ![]u8 {
        const val = try httpP3BuildClientSendOkIv(self.allocator, response_handle);
        defer val.deinit(self.allocator);
        return try httpP3LowerAsyncPayload(self.allocator, .client_send_ok, val);
    }

    /// Lower a `result<own<response>, error-code>` err-arm envelope
    /// for `code`. Owned by `self.allocator`; the executor frees the
    /// bytes on future-slot deinit. (#589)
    fn lowerHttpP3ClientSendErr(self: *WasiCliAdapter, code: HttpErrorCode) ![]u8 {
        const val = try httpP3BuildClientSendErrIv(self.allocator, code);
        defer val.deinit(self.allocator);
        return try httpP3LowerAsyncPayload(self.allocator, .client_send_err, val);
    }

    /// Mint an already-settled P3 future whose payload is the
    /// canonical-ABI envelope for a `result<own<response>,
    /// error-code>` err-arm. Used by the synchronous deny paths
    /// (`httpClientSendP3` empty-allow-list / bad-URI rejections)
    /// so they return `.handle` like the deferred path — the
    /// `canon.lower (async)` trampoline collapses ready futures
    /// to `STATUS_RETURNED` with `mem[retptr..] := payload` so
    /// the guest observes the error synchronously. (#589)
    fn spawnReadyHttpP3ClientSendErrFuture(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        code: HttpErrorCode,
    ) !u32 {
        const bytes = try self.lowerHttpP3ClientSendErr(code);
        const fh = ci.allocAsyncHandle();
        ci.futures.put(ci.allocator, fh, .{
            .elem_type_idx = 0,
            .payload = bytes,
            .state = .ready,
            .write_closed = true,
        }) catch |err| {
            self.allocator.free(bytes);
            return err;
        };
        return fh;
    }

    /// Park in `poll()` on the self-pipe waker fds of in-flight HTTP
    /// fetches until a worker signals its waker or `cap_ns.*` elapses,
    /// instead of waking on a fixed re-poll cadence and burning CPU
    /// (#833). Returns `true` if it parked on a waker poll (the caller
    /// then skips its own sleep). A pending fetch lacking a waker
    /// (pipe-init failure) shortens `cap_ns.*` to `http_repoll_ns` so
    /// the caller's cadence fallback still observes it promptly.
    ///
    /// Windows has no `poll()` path (`std.posix.pollfd` does not exist
    /// there), so the body is `comptime`-gated off on Windows — mirroring
    /// `waitForBackendEvents` — and only the cadence shortening applies.
    fn parkOnHttpWakers(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        cap_ns: *u64,
        http_repoll_ns: u64,
    ) bool {
        if (comptime builtin.os.tag == .windows) {
            const pending = self.pending_http_fetches.publishedCount() > 0 or
                self.pending_http_fetches_p3.publishedCount() > 0;
            if (pending) cap_ns.* = @min(cap_ns.*, http_repoll_ns);
            return false;
        }
        const p2_handles = self.pending_http_fetches.snapshotHandles(self.allocator) catch {
            cap_ns.* = @min(cap_ns.*, http_repoll_ns);
            return false;
        };
        defer self.allocator.free(p2_handles);
        const p3_handles = self.pending_http_fetches_p3.snapshotHandles(self.allocator) catch {
            cap_ns.* = @min(cap_ns.*, http_repoll_ns);
            return false;
        };
        defer self.allocator.free(p3_handles);

        var waker_fds: std.ArrayListUnmanaged(std.posix.pollfd) = .empty;
        defer waker_fds.deinit(self.allocator);
        var p2_guards: std.ArrayListUnmanaged(PendingHttpFetchTable.Lease) = .empty;
        defer {
            for (p2_guards.items) |*lease| lease.release();
            p2_guards.deinit(self.allocator);
        }
        var p3_guards: std.ArrayListUnmanaged(PendingHttpFetchP3Table.Lease) = .empty;
        defer {
            for (p3_guards.items) |*lease| lease.release();
            p3_guards.deinit(self.allocator);
        }
        waker_fds.ensureTotalCapacity(
            self.allocator,
            p2_handles.len + p3_handles.len,
        ) catch {
            cap_ns.* = @min(cap_ns.*, http_repoll_ns);
            return false;
        };
        p2_guards.ensureTotalCapacity(self.allocator, p2_handles.len) catch {
            cap_ns.* = @min(cap_ns.*, http_repoll_ns);
            return false;
        };
        p3_guards.ensureTotalCapacity(self.allocator, p3_handles.len) catch {
            cap_ns.* = @min(cap_ns.*, http_repoll_ns);
            return false;
        };

        var http_without_waker = false;
        for (p2_handles) |handle| {
            var lease = self.pending_http_fetches.acquire(handle) orelse continue;
            const entry = lease.value();
            if (!entry.armed.load(.acquire)) {
                lease.release();
                continue;
            }
            if (entry.shared) |shared| if (shared.waker) |waker| {
                waker_fds.appendAssumeCapacity(.{
                    .fd = waker.read_fd,
                    .events = pollInEvents(),
                    .revents = 0,
                });
                p2_guards.appendAssumeCapacity(lease);
                continue;
            };
            lease.release();
            http_without_waker = true;
        }
        for (p3_handles) |handle| {
            var lease = self.pending_http_fetches_p3.acquire(handle) orelse continue;
            const entry = lease.value();
            if (!entry.armed.load(.acquire) or entry.ci != ci) {
                lease.release();
                continue;
            }
            if (entry.shared) |shared| if (shared.waker) |waker| {
                waker_fds.appendAssumeCapacity(.{
                    .fd = waker.read_fd,
                    .events = pollInEvents(),
                    .revents = 0,
                });
                p3_guards.appendAssumeCapacity(lease);
                continue;
            };
            lease.release();
            http_without_waker = true;
        }
        if (http_without_waker) cap_ns.* = @min(cap_ns.*, http_repoll_ns);
        if (waker_fds.items.len == 0) return false;
        // Block until any worker signals its waker or the cap (timer
        // deadline / UDP re-poll budget / hint) elapses.
        const timeout_ms: i32 = blk: {
            const ms = (cap_ns.* +| 999_999) / 1_000_000;
            if (ms > @as(u64, @intCast(std.math.maxInt(i32)))) break :blk std.math.maxInt(i32);
            break :blk @intCast(ms);
        };
        _ = std.posix.poll(waker_fds.items, timeout_ms) catch {};
        return true;
    }

    /// `ComponentInstance.async_event_driver` hook (#551). Advances the
    /// host monotonic clock (honoring `monotonic_clock_override` so unit
    /// tests stay deterministic) and drains any due timer-futures into
    /// the WaitableSet they were joined to via `waitable.join`. Also
    /// drives any pending `udp-socket.receive` futures via
    /// `completeReadyPendingUdpReceives` so a datagram landing in the
    /// kernel queue resolves the guest's awaited `.receive()` (#576),
    /// and any pending outbound HTTP fetches via
    /// `drainPendingHttpFetches` so an awaited
    /// `future-incoming-response` settles once the worker thread
    /// publishes its outcome (#583 A2). When the caller is blocking on
    /// `waitable-set.wait` and `wait_for_ns_hint` is non-null, this
    /// routine sleeps the host thread until the earliest pending
    /// deadline or the hint, whichever comes first.
    ///
    /// The sleep is bounded by the hint so tests with mocked clocks
    /// (override set) don't actually block on host time. Returns whether
    /// any host event was delivered.
    pub fn driveAsyncEvents(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        wait_for_ns_hint: ?u64,
        allocator: Allocator,
    ) bool {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        const live_response = self.activeInboundHttpResponse(ci);

        // Drain anything already due first — the common case for
        // `wait-for(0)` / `wait-until(past)` and for tests that
        // pre-advance `monotonic_clock_override`.
        var fired = if (live_response) |session|
            session.driveGuestEvents()
        else
            false;
        if (self.completeDueTimerFutures(ci, allocator)) fired = true;
        if (executor_root.drivePendingHostStreamReads(ci, allocator)) fired = true;
        // Drain any pending UDP `recvfrom`s whose fd is now readable.
        // Runs before the optional sleep so a datagram already in the
        // kernel queue resolves synchronously without spending the
        // hint budget. (#576)
        if (self.completeReadyPendingUdpReceives(ci, allocator)) fired = true;

        // Caller asked us not to block (poll variant); return immediately.
        const hint_ns = wait_for_ns_hint orelse {
            // Drain pending HTTP fetches whose worker has finished —
            // the poll-variant caller wants any already-settled
            // futures observed before it returns. (#583 A2 / #589)
            self.drainPendingHttpFetches();
            self.drainPendingHttpFetchesP3(ci, allocator);
            return fired;
        };
        if (fired) {
            self.drainPendingHttpFetches();
            self.drainPendingHttpFetchesP3(ci, allocator);
            return fired;
        }

        // Determine the soonest pending deadline so we can sleep just
        // long enough to fire it. If `monotonic_clock_override` is set
        // (tests), don't sleep — the test mutates the override manually
        // and re-enters `driveAsyncEvents` to deliver.
        if (self.monotonic_clock_override != null) {
            self.drainPendingHttpFetches();
            self.drainPendingHttpFetchesP3(ci, allocator);
            return false;
        }
        const have_udp_pending = self.pending_udp_receives.publishedCount() > 0;
        const have_http_pending = self.pending_http_fetches.publishedCount() > 0 or
            self.pending_http_fetches_p3.publishedCount() > 0;
        const have_stream_pending = executor_root.hasPendingHostStreamReads(ci);
        const have_live_response = if (live_response) |session|
            session.currentTerminal() == .running
        else
            false;
        if (self.timer_futures.publishedCount() == 0 and
            !have_udp_pending and
            !have_http_pending and
            !have_stream_pending and
            !have_live_response)
        {
            return false;
        }

        const now = self.monotonicNs();
        var soonest: u64 = std.math.maxInt(u64);
        const timer_handles = self.timer_futures.snapshotHandles(self.allocator) catch
            return false;
        defer self.allocator.free(timer_handles);
        for (timer_handles) |timer_handle| {
            var timer_lease = self.timer_futures.acquire(timer_handle) orelse continue;
            const deadline = timer_lease.value().deadline_ns;
            timer_lease.release();
            if (deadline < soonest) soonest = deadline;
        }
        // If we have pending UDP receives, cap the sleep at a short
        // budget so we re-poll the fd within the hint window even if
        // no timer is set. The kernel doesn't notify us of socket
        // readiness from `sleep`, so we re-enter to call
        // `fdPollReady` again.
        const udp_repoll_ns: u64 = 1 * std.time.ns_per_ms;
        // Pending HTTP fetches lacking a self-pipe waker (pipe-init
        // failure / Windows) fall back to a short re-poll cadence; ones
        // with a waker are slept on directly via `poll()` below (#833).
        const http_repoll_ns: u64 = 1 * std.time.ns_per_ms;
        var cap_ns: u64 = hint_ns;
        if (soonest != std.math.maxInt(u64)) {
            const delta_ns: u64 = if (soonest > now) soonest - now else 0;
            cap_ns = @min(cap_ns, delta_ns);
        }
        if (have_udp_pending) cap_ns = @min(cap_ns, udp_repoll_ns);
        if (have_stream_pending) cap_ns = @min(cap_ns, udp_repoll_ns);
        if (have_live_response) cap_ns = @min(cap_ns, udp_repoll_ns);

        // Park in `poll()` on the self-pipe waker fds of in-flight HTTP
        // fetches until a worker publishes its outcome, instead of
        // waking on a fixed 1ms cadence and burning CPU (#833). A fetch
        // with no waker (pipe-init failure / Windows) keeps the old
        // short re-poll, so `cap_ns` is shortened accordingly. The
        // waker-poll lives in `parkOnHttpWakers` so the `std.posix`
        // poll machinery is never referenced on Windows (which has no
        // `pollfd` type), matching the `waitForBackendEvents` guard.
        const parked = self.parkOnHttpWakers(ci, &cap_ns, http_repoll_ns);
        if (!parked) {
            if (cap_ns == 0 and soonest == std.math.maxInt(u64) and !have_udp_pending and !have_http_pending) return false;
            if (cap_ns > 0) {
                const io = std.Io.Threaded.global_single_threaded.io();
                const duration: std.Io.Clock.Duration = .{
                    .raw = .{ .nanoseconds = cap_ns },
                    .clock = .awake,
                };
                duration.sleep(io) catch {};
            }
        }
        var post = self.completeDueTimerFutures(ci, allocator);
        if (self.completeReadyPendingUdpReceives(ci, allocator)) post = true;
        if (executor_root.drivePendingHostStreamReads(ci, allocator)) post = true;
        // Drain HTTP last so worker outcomes published during the
        // sleep window are observed on this same tick. (#583 A2 / #589)
        self.drainPendingHttpFetches();
        self.drainPendingHttpFetchesP3(ci, allocator);
        if (live_response) |session| {
            if (session.driveGuestEvents()) post = true;
        }
        return post;
    }

    /// `ComponentInstance.async_cancel_driver` hook (#551, #583 B1).
    /// Invoked from the `task.cancel` canon-builtin path when the
    /// guest cancels the currently-executing task. Cancels every
    /// host-side async operation the adapter owns:
    ///
    ///   * **Timer futures** — settle `state = .closed`,
    ///     `write_closed = true` and fire `STATUS_STARTED_CANCELLED`.
    ///     (#551, original landing for `wasi:clocks/wait-for`.)
    ///   * **Pending UDP receives** — settle the parked
    ///     `udp-socket.receive` future with `STATUS_STARTED_CANCELLED`
    ///     and remove the entry so the next `driveAsyncEvents` tick
    ///     does not try to `recvfrom(2)` again.
    ///   * **FS write-via-stream / append-via-stream contexts** —
    ///     flip `cancelled` so the next `fsWriteViaStreamOnWrite`
    ///     chunk returns `.err` and the executor closes the read
    ///     end with DROPPED.
    ///   * **FS read-via-stream contexts** — flip `cancelled` so the
    ///     (currently armed-but-dormant) `fsReadViaStreamOnRead`
    ///     short-circuits with `.eof` if ever invoked.
    ///   * **TCP-receive stream contexts** (#583 follow-up to #607) —
    ///     flip `cancelled` so the next `tcpReceiveStreamOnRead` /
    ///     `tcpReceiveStreamOnReadInto` chunk returns `.err` and the
    ///     executor closes the writable end of the receive stream.
    ///     The flag is per-`SocketsP3StreamCtx`, shared with the
    ///     tcp-send / tcp-accept driver shapes but observed only by
    ///     the receive drivers today. Each guest-visible `stream.read`
    ///     loops the driver up to 32 times (each call ≤ 64 KiB), so
    ///     cancel is observed within at most one chunk's `recv(2)`
    ///     latency — matching the FS / HTTP cadence.
    ///   * **Pending outbound HTTP fetches** — flip the per-fetch
    ///     `shared.cancelled` atomic. The worker polls this flag at
    ///     every `std.http.Client.Request` phase boundary
    ///     (pre-connect, pre-send, pre-receive-head, pre-body-read,
    ///     and on every `http_cancel_body_chunk_bytes`-sized body
    ///     chunk) and surfaces cancellation as
    ///     `error.HttpFetchCancelled`, which it then translates to
    ///     the `HTTP_request_denied` 0.3 error-code variant. Cancel
    ///     is still best-effort *within* a phase — a blocking
    ///     `recv(2)` waiting for the next header byte is not
    ///     interrupted from another thread — but observability is
    ///     bounded to one phase's I/O latency rather than the whole
    ///     fetch. As a belt-and-braces, the drainer
    ///     (`settlePendingHttpFetch` /
    ///     `settlePendingHttpFetchP3`) also checks
    ///     `shared.cancelled` post-completion and overrides a wire-success outcome
    ///     with `HTTP_request_denied` if the cancel signal landed
    ///     after the worker had already published `done` (#583 B1
    ///     follow-up; the original #583 B1 landing observed cancel
    ///     only at the pre-fetch check).
    ///
    /// The `task_handle` argument is reserved for a future per-task
    /// owner-tracking refactor; today we cancel every pending op the
    /// adapter owns. Single-task guests (which is what every fixture
    /// driven by `wasi:cli@0.3.x.run` is) hit the same behaviour either
    /// way.
    pub fn cancelAllPendingAsyncOps(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        task_handle: ?u32,
        allocator: Allocator,
    ) void {
        _ = task_handle;
        _ = allocator;
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));

        // ── Timer futures (#551) ──────────────────────────────────
        if (self.timer_futures.snapshotHandles(self.allocator)) |handles| {
            defer self.allocator.free(handles);
            for (handles) |timer_handle| {
                var timer_lease = self.timer_futures.acquire(timer_handle) orelse continue;
                const tf = timer_lease.value().*;
                timer_lease.release();
                if (!self.timer_futures.remove(timer_handle)) continue;
                _ = cancelComponentFuture(ci, tf.handle);
                self.async_state_claim.acquire();
                if (self.timer_future_ready.getPtr(tf.handle)) |slot| slot.* = true;
                self.async_state_claim.release();
            }
        } else |_| {}

        // ── Pending UDP receives (#583 B1) ────────────────────────
        // Settle each parked `udp-socket.receive` future with the
        // cancel disposition. We do not lower a result payload (the
        // guest's awaited Subtask sees `STATUS_STARTED_CANCELLED`
        // before the payload is consumed); we just close the future
        // and fire the waitable. Note: future may be subtask-managed
        // or plain-future depending on the call-site shape — flipping
        // both state + write_closed handles both decoder paths.
        if (self.pending_udp_receives.snapshotHandles(self.allocator)) |handles| {
            defer self.allocator.free(handles);
            for (handles) |operation_handle| {
                var operation_lease = self.pending_udp_receives.acquire(operation_handle) orelse
                    continue;
                const entry = operation_lease.value();
                entry.cancelled.store(true, .release);
                if (entry.claimed.cmpxchgStrong(false, true, .acquire, .monotonic) == null) {
                    const future_handle = entry.future_handle;
                    operation_lease.release();
                    if (self.pending_udp_receives.remove(operation_handle)) {
                        _ = cancelComponentFuture(ci, future_handle);
                    }
                } else {
                    operation_lease.release();
                }
            }
        } else |_| {}

        // ── Filesystem stream contexts (#583 B1, #602 follow-up) ──
        // Flip the cancel flag on every adapter-owned FS stream ctx.
        // The on_read / on_write callbacks poll the flag with
        // `.load(.acquire)` between every `FS_CANCEL_POLL_CHUNK_BYTES`-
        // sized pwrite/pread chunk and short-circuit so a multi-MiB
        // drain is interrupted within at most one chunk's syscall
        // latency — mirrors the HTTP body-read cadence from #602.
        if (self.fs_write_stream_ctxs.snapshotHandles(self.allocator)) |handles| {
            defer self.allocator.free(handles);
            for (handles) |handle| {
                var lease = self.fs_write_stream_ctxs.acquire(handle) orelse continue;
                lease.value().*.cancelled.store(true, .release);
                lease.release();
            }
        } else |_| {}
        if (self.fs_read_stream_ctxs.snapshotHandles(self.allocator)) |handles| {
            defer self.allocator.free(handles);
            for (handles) |handle| {
                var lease = self.fs_read_stream_ctxs.acquire(handle) orelse continue;
                lease.value().*.cancelled.store(true, .release);
                lease.release();
            }
        } else |_| {}

        // ── Socket-stream contexts (#583 follow-up to #607) ───────
        // Flip the cancel flag on every adapter-owned socket stream
        // ctx. Observed today by the tcp-receive drivers
        // (`tcpReceiveStreamOnRead` / `tcpReceiveStreamOnReadInto`)
        // which poll it at entry and short-circuit with `.err`. The
        // executor's zero-copy `stream.read` arm loops the driver up
        // to 32 times per guest call, each invocation bounded at 64
        // KiB — so cancel is observed within at most one chunk's
        // `recv(2)` latency, matching the FS / HTTP cadence. The
        // tcp-send / tcp-accept drivers ignore the flag today (each
        // does a single bounded syscall per call); they're tracked
        // for a future PR if their executor loops grow the same
        // multi-chunk shape.
        if (self.sockets_p3_stream_ctxs.snapshotHandles(self.allocator)) |handles| {
            defer self.allocator.free(handles);
            for (handles) |handle| {
                var lease = self.sockets_p3_stream_ctxs.acquire(handle) orelse continue;
                lease.value().*.cancelled.store(true, .release);
                lease.release();
            }
        } else |_| {}

        // ── Outbound HTTP fetches (#583 B1) ───────────────────────
        // `shared.cancelled` is an `Atomic.Value(bool)` so the worker
        // thread can read it lock-free at every `std.http.Client.Request`
        // phase boundary — `httpClientLowLevelFetch` calls
        // `checkHttpCancel` pre-connect, pre-send, pre-receive-head,
        // pre-body-read, and on every `http_cancel_body_chunk_bytes`
        // body chunk (#583 B1 follow-up). The drainer
        // (`settlePendingHttpFetch`) re-checks the flag as a belt-
        // and-braces, so even a cancel that races a worker
        // completion still surfaces as `HTTP_request_denied`.
        if (self.pending_http_fetches.snapshotHandles(self.allocator)) |handles| {
            defer self.allocator.free(handles);
            for (handles) |operation_handle| {
                var lease = self.pending_http_fetches.acquire(operation_handle) orelse continue;
                const entry = lease.value();
                if (entry.armed.load(.acquire)) {
                    if (entry.shared) |shared| shared.cancelled.store(true, .release);
                }
                lease.release();
            }
        } else |_| {}
        if (self.pending_http_fetches_p3.snapshotHandles(self.allocator)) |handles| {
            defer self.allocator.free(handles);
            for (handles) |operation_handle| {
                var lease = self.pending_http_fetches_p3.acquire(operation_handle) orelse continue;
                const entry = lease.value();
                if (entry.armed.load(.acquire) and entry.ci == ci) {
                    if (entry.shared) |shared| shared.cancelled.store(true, .release);
                }
                lease.release();
            }
        } else |_| {}
    }

    /// Backwards-compatibility alias. The cancel driver used to only
    /// cover timer futures (#551); broader subsystems were added in
    /// #583 B1 via `cancelAllPendingAsyncOps`. Callers that pinned
    /// the old symbol (third-party host integrations, tests) keep
    /// working.
    pub const cancelAllPendingTimers = cancelAllPendingAsyncOps;

    /// `ComponentInstance.async_future_drop_driver` hook (#616 A7).
    ///
    /// A P3 guest that stops caring about an outbound HTTP response
    /// does not call `task.cancel` — it simply drops the readable end
    /// of the future. Without this hook the worker thread stayed
    /// blocked in `connect` / `receiveHead` / body-read until the
    /// server or the OS gave up, holding a thread, a socket, and a TLS
    /// session for a result nobody would ever read.
    ///
    /// Raising `shared.cancelled` both settles the advisory
    /// phase-boundary checks and wakes the cancel lane armed by
    /// `httpAwaitCancelSignal`, so an already-blocked syscall is
    /// interrupted rather than merely noticed at the next phase.
    ///
    /// Only P3 entries need this: the P2 path flips the same flag from
    /// its own future-drop handling.
    pub fn cancelPendingHttpFetchForFuture(
        ctx: ?*anyopaque,
        ci: *ComponentInstance,
        future_handle: u32,
    ) void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx orelse return));
        if (self.pending_http_fetches_p3.snapshotHandles(self.allocator)) |handles| {
            defer self.allocator.free(handles);
            for (handles) |operation_handle| {
                var lease = self.pending_http_fetches_p3.acquire(operation_handle) orelse continue;
                const entry = lease.value();
                if (entry.armed.load(.acquire) and
                    entry.ci == ci and
                    entry.future_handle == future_handle)
                {
                    if (entry.shared) |shared| shared.cancelled.store(true, .release);
                }
                lease.release();
            }
        } else |_| {}
    }

    fn allocStreamHandle(self: *WasiCliAdapter, stream: *streams.OutputStream) !u32 {
        const shared_claim = if (stream == &self.stdout)
            &self.stdout_operation_claim
        else if (stream == &self.stderr)
            &self.stderr_operation_claim
        else
            null;
        return self.stream_table.publish(.{
            .stream = stream,
            .owned = false,
            .shared_operation_claim = shared_claim,
        });
    }

    fn allocOwnedStreamHandle(
        self: *WasiCliAdapter,
        stream: *streams.OutputStream,
        descriptor_lease: ?FsDescriptorTable.Lease,
        socket_lease: ?SocketTable.Lease,
    ) !u32 {
        const owner = try self.allocator.create(OutputStreamOwner);
        errdefer self.allocator.destroy(owner);
        owner.* = .{
            .allocator = self.allocator,
            .stream = stream,
        };
        return self.stream_table.publish(.{
            .stream = stream,
            .owned = true,
            .owner = owner,
            .descriptor_lease = descriptor_lease,
            .socket_lease = socket_lease,
        });
    }

    fn lookupStream(self: *WasiCliAdapter, handle: u32) ?OutputStreamTable.Lease {
        return self.stream_table.acquire(handle);
    }

    /// HostFunc callback for `(list<u8>) -> ()`. Pulls the (ptr, len)
    /// list arg out of guest memory via `ComponentInstance.readGuestBytes`
    /// and appends to `self.stdout`.
    fn writeBytes(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        _ = results;
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const list = switch (args[0]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        const bytes = ci.readGuestBytes(list.ptr, list.len) orelse
            return error.OutOfBoundsMemory;
        self.stdout_operation_claim.acquire();
        defer self.stdout_operation_claim.release();
        switch (self.stdout.write(bytes, self.allocator)) {
            .ok => {},
            .err, .closed => return error.IoError,
        }
    }

    /// `wasi:cli/stdout.get-stdout: () -> own<output-stream>`. Returns a
    /// fresh handle into the adapter's stream table, pointing at the
    /// captured stdout buffer.
    fn getStdoutHandle(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        const handle = try self.allocStreamHandle(&self.stdout);
        results[0] = .{ .handle = handle };
    }

    /// `wasi:cli/stderr.get-stderr: () -> own<output-stream>`. Mirror of
    /// `getStdoutHandle` for the captured stderr buffer.
    fn getStderrHandle(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        const handle = try self.allocStreamHandle(&self.stderr);
        results[0] = .{ .handle = handle };
    }

    /// `wasi:cli/exit.exit: (result<_, _>) -> ()`. The arg is a
    /// `result<_, _>` discriminant where `0` (ok) → exit 0, `1` (err) →
    /// exit 1. Sets `self.exit_code` then traps so the run unwinds.
    fn cliExit(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        const code: u32 = if (args.len > 0) switch (args[0]) {
            .result_val => |rv| if (rv.is_ok) @as(u32, 0) else 1,
            else => 0,
        } else 0;
        self.exit_state_claim.acquire();
        self.exit_code = code;
        self.exit_state_claim.release();
        // #760: pin the code in TLS so the AOT host-import dispatcher
        // can call `std.process.exit(code)` on this `error.WasiExit`
        // rather than writing the post-#714 sentinel into the guest's
        // return slot (which causes the wit-bindgen WASIp1 adapter to
        // trip its "host exit implementation didn't exit!" assertion).
        // The interpreter path is unchanged — it keeps reading
        // `self.exit_code` from `runLoadedComponent`'s catch arm.
        recordPendingWasiExit(code);
        return error.WasiExit;
    }

    /// `wasi:cli/exit.exit-with-code: (u8) -> ()`. Sets the exit code
    /// and traps. Mirrors `cliExit` for the typed-code form added in
    /// later WASI 0.2 drafts.
    fn cliExitWithCode(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        const code: u32 = if (args.len > 0) switch (args[0]) {
            .u8 => |v| @intCast(v),
            .u32 => |v| v,
            .u64 => |v| @truncate(v),
            else => 0,
        } else 0;
        self.exit_state_claim.acquire();
        self.exit_code = code;
        self.exit_state_claim.release();
        // #760: see `cliExit` above for the TLS handoff rationale.
        recordPendingWasiExit(code);
        return error.WasiExit;
    }

    /// `wasi:cli/environment.get-environment: () -> list<tuple<string,string>>`.
    /// Returns an empty list (canonical pair `ptr=0, len=0`).
    fn getEnvironment(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;

        const n = self.env.len;
        if (n == 0) {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        }

        // Each tuple<string, string>: name.ptr@0:u32, name.len@4:u32,
        // value.ptr@8:u32, value.len@12:u32. Stride = 16, align = 4.
        const stride: usize = 16;
        const scratch = try allocator.alloc(u8, n * stride);
        defer allocator.free(scratch);

        for (self.env, 0..) |e, i| {
            const name_ptr = ci.hostAllocAndWrite(e.name, 1) orelse return error.IoError;
            const value_ptr = ci.hostAllocAndWrite(e.value, 1) orelse return error.IoError;
            const off = i * stride;
            std.mem.writeInt(u32, scratch[off..][0..4], name_ptr, .little);
            std.mem.writeInt(u32, scratch[off + 4 ..][0..4], @intCast(e.name.len), .little);
            std.mem.writeInt(u32, scratch[off + 8 ..][0..4], value_ptr, .little);
            std.mem.writeInt(u32, scratch[off + 12 ..][0..4], @intCast(e.value.len), .little);
        }

        const list_ptr = ci.hostAllocAndWrite(scratch, 4) orelse return error.IoError;
        results[0] = .{ .list = .{ .ptr = list_ptr, .len = @intCast(n) } };
    }

    /// `wasi:cli/environment.get-arguments: () -> list<string>`. Forwards
    /// `self.argv`; empty when no caller invoked `setArguments`.
    fn getArguments(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;

        const n = self.argv.len;
        if (n == 0) {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        }

        // Each string element: ptr@0:u32, len@4:u32. Stride = 8, align = 4.
        const stride: usize = 8;
        const scratch = try allocator.alloc(u8, n * stride);
        defer allocator.free(scratch);

        for (self.argv, 0..) |s, i| {
            const s_ptr = ci.hostAllocAndWrite(s, 1) orelse return error.IoError;
            const off = i * stride;
            std.mem.writeInt(u32, scratch[off..][0..4], s_ptr, .little);
            std.mem.writeInt(u32, scratch[off + 4 ..][0..4], @intCast(s.len), .little);
        }

        const list_ptr = ci.hostAllocAndWrite(scratch, 4) orelse return error.IoError;
        results[0] = .{ .list = .{ .ptr = list_ptr, .len = @intCast(n) } };
    }

    /// `wasi:cli/environment.initial-cwd: () -> option<string>`. None.
    fn initialCwd(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        results[0] = .{ .option_val = .{ .is_some = false, .payload = null } };
    }

    /// `wasi:cli/terminal-*.get-terminal-*: () -> option<terminal-*>`.
    /// Captured-buffer mode has no TTY → return `none`.
    fn getTerminalNone(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        results[0] = .{ .option_val = .{ .is_some = false, .payload = null } };
    }

    /// `wasi:io/streams.[method]output-stream.blocking-write-and-flush:
    ///   (own<output-stream>, list<u8>) -> result<_, stream-error>`.
    /// Looks up the handle, writes the guest bytes through, and returns
    /// the canonical "ok" discriminant. (The error arm is unreachable in
    /// captured-buffer mode and is omitted from the synthetic fixture's
    /// `result<_, _>` type — this keeps the flat lower path on the
    /// no-payload fast path.)
    fn blockingWriteAndFlush(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const list = switch (args[1]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        var stream_lease = self.lookupStream(handle) orelse return error.InvalidHandle;
        defer stream_lease.release();
        const resource = stream_lease.value();
        const claim = resource.claim();
        claim.acquire();
        defer claim.release();
        const stream = resource.stream;
        const bytes = ci.readGuestBytes(list.ptr, list.len) orelse
            return error.OutOfBoundsMemory;
        switch (stream.write(bytes, self.allocator)) {
            .ok => {},
            .err, .closed => return error.IoError,
        }
        // `blocking-write-and-flush` semantically includes a flush.
        // Honor `descriptor-flags` sync bits for host-file sinks (#181).
        switch (stream.flush()) {
            .ok => {},
            .err, .closed => return error.IoError,
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `[method]output-stream.write: (borrow<output-stream>, list<u8>)
    ///   -> result<_, stream-error>`. Same write semantics as
    /// `blocking-write-and-flush`; the captured buffer never blocks.
    fn outputStreamWrite(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const list = switch (args[1]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        var stream_lease = self.lookupStream(handle) orelse return error.InvalidHandle;
        defer stream_lease.release();
        const resource = stream_lease.value();
        const claim = resource.claim();
        claim.acquire();
        defer claim.release();
        const stream = resource.stream;
        const bytes = ci.readGuestBytes(list.ptr, list.len) orelse
            return error.OutOfBoundsMemory;
        switch (stream.write(bytes, self.allocator)) {
            .ok => {},
            .err, .closed => return error.IoError,
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `[method]output-stream.check-write: (borrow<output-stream>)
    ///   -> result<u64, stream-error>`. The captured buffer can always
    /// accept; report a generous chunk so the guest writes in one call.
    fn outputStreamCheckWrite(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        _ = ctx_opaque;
        if (args.len == 0 or results.len == 0) return error.InvalidArgs;
        const payload = try allocator.create(InterfaceValue);
        payload.* = .{ .u64 = 64 * 1024 };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = payload } };
    }

    /// `[method]output-stream.blocking-flush: (borrow<output-stream>)
    ///   -> result<_, stream-error>`. For captured buffers, fd-backed,
    /// or non-sync host-file streams this is a no-op. Host-file streams
    /// opened with `file-integrity-sync` / `data-integrity-sync` (#181)
    /// issue `file.sync()` here so writes reach stable storage.
    fn outputStreamBlockingFlush(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var stream_lease = self.lookupStream(handle) orelse return error.InvalidHandle;
        defer stream_lease.release();
        const resource = stream_lease.value();
        const claim = resource.claim();
        claim.acquire();
        defer claim.release();
        const stream = resource.stream;
        switch (stream.flush()) {
            .ok => {},
            .err, .closed => return error.IoError,
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `[method]output-stream.subscribe: (borrow<output-stream>)
    ///   -> own<pollable>`.
    fn outputStreamSubscribe(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0 or results.len == 0) return error.InvalidArgs;
        const stream_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var stream_lease = self.lookupStream(stream_handle) orelse
            return error.InvalidHandle;
        stream_lease.release();
        const poll_handle = try self.pushPollable(.{ .output_stream = stream_handle });
        results[0] = .{ .handle = poll_handle };
    }

    /// `[method]input-stream.subscribe: (borrow<input-stream>)
    ///   -> own<pollable>`.
    fn inputStreamSubscribe(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0 or results.len == 0) return error.InvalidArgs;
        const stream_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var stream_lease = self.lookupInputStream(stream_handle) orelse
            return error.InvalidHandle;
        stream_lease.release();
        const poll_handle = try self.pushPollable(.{ .input_stream = stream_handle });
        results[0] = .{ .handle = poll_handle };
