    /// `wasi:io/streams.[resource-drop]output-stream: (own<output-stream>) -> ()`.
    /// Marks the handle's slot inactive. Stdout itself is not closed —
    /// the same buffer can be reopened with another `get-stdout`.
    fn dropOutputStream(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        _ = self.stream_table.remove(handle);
    }

    fn allocInputStreamHandle(self: *WasiCliAdapter, stream: *streams.InputStream) !u32 {
        return self.input_stream_table.publish(.{
            .stream = stream,
            .owned = false,
            .shared_operation_claim = if (stream == &self.stdin)
                &self.stdin_operation_claim
            else
                null,
        });
    }

    fn allocOwnedInputStreamHandle(
        self: *WasiCliAdapter,
        stream: *streams.InputStream,
        owned_buffer: ?[]u8,
        descriptor_lease: ?FsDescriptorTable.Lease,
        socket_lease: ?SocketTable.Lease,
    ) !u32 {
        return self.input_stream_table.publish(.{
            .stream = stream,
            .owned = true,
            .owned_buffer = owned_buffer,
            .descriptor_lease = descriptor_lease,
            .socket_lease = socket_lease,
        });
    }

    fn lookupInputStream(self: *WasiCliAdapter, handle: u32) ?InputStreamTable.Lease {
        return self.input_stream_table.acquire(handle);
    }

    const TcpStreamPair = struct {
        input: u32,
        output: u32,
    };

    fn createTcpStreamPair(
        self: *WasiCliAdapter,
        socket_handle: u32,
        fd: std.posix.fd_t,
    ) !TcpStreamPair {
        const input = try self.allocator.create(streams.InputStream);
        input.* = streams.InputStream.fromTcpStream(fd);
        var input_parent = self.socket_table.acquire(socket_handle) orelse {
            self.allocator.destroy(input);
            return error.InvalidHandle;
        };
        const input_handle = self.allocOwnedInputStreamHandle(
            input,
            null,
            null,
            input_parent,
        ) catch |err| {
            input_parent.release();
            self.allocator.destroy(input);
            return err;
        };
        errdefer std.debug.assert(self.input_stream_table.remove(input_handle));

        const output = try self.allocator.create(streams.OutputStream);
        output.* = streams.OutputStream.toTcpStream(fd);
        var output_parent = self.socket_table.acquire(socket_handle) orelse {
            output.deinit(self.allocator);
            self.allocator.destroy(output);
            return error.InvalidHandle;
        };
        const output_handle = self.allocOwnedStreamHandle(
            output,
            null,
            output_parent,
        ) catch |err| {
            output_parent.release();
            output.deinit(self.allocator);
            self.allocator.destroy(output);
            return err;
        };
        return .{ .input = input_handle, .output = output_handle };
    }

    /// `wasi:cli/stdin.get-stdin: () -> own<input-stream>`.
    fn getStdinHandle(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        const handle = try self.allocInputStreamHandle(&self.stdin);
        results[0] = .{ .handle = handle };
    }

    /// `wasi:io/streams.[method]input-stream.blocking-read:
    ///   (borrow<input-stream>, u64) -> result<list<u8>, stream-error>`.
    /// Reads up to `len` bytes from the captured stdin into a freshly
    /// guest-allocated buffer (via `cabi_realloc`) and returns the list
    /// in the ok arm. End-of-stream surfaces as the closed variant in
    /// the err arm with payload omitted (caller's `result_val.payload`
    /// is `null` — the canonical-ABI store path zero-fills the payload
    /// slots that aren't populated).
    fn blockingRead(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const want_u64 = switch (args[1]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        var stream_lease = self.lookupInputStream(handle) orelse return error.InvalidHandle;
        defer stream_lease.release();
        const resource = stream_lease.value();
        const claim = resource.claim();
        claim.acquire();
        defer claim.release();
        const stream = resource.stream;

        const want: usize = @min(want_u64, std.math.maxInt(usize));
        // Cap at a sane upper bound so an unbounded request from the guest
        // (Rust's read_line passes 0xFFFF_FFFF_FFFF_FFFF) doesn't allocate
        // a multi-exabyte host buffer. 64 KiB matches the canonical-ABI
        // chunk used by wit-bindgen.
        const capped: usize = @min(want, 64 * 1024);

        const buf = try allocator.alloc(u8, capped);
        defer allocator.free(buf);

        switch (stream.read(buf)) {
            .ok => |n| {
                const guest_ptr = ci.hostAllocAndWrite(buf[0..n], 1) orelse return error.IoError;
                const list_val = try allocator.create(InterfaceValue);
                list_val.* = .{ .list = .{ .ptr = guest_ptr, .len = @intCast(n) } };
                results[0] = .{ .result_val = .{ .is_ok = true, .payload = list_val } };
            },
            .closed => {
                // err arm; payload (stream-error variant) zero-fills.
                results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
            },
            .err => return error.IoError,
        }
    }

    /// `wasi:io/streams.[resource-drop]input-stream: (own<input-stream>) -> ()`.
    fn dropInputStream(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        _ = self.input_stream_table.remove(handle);
    }

    // ── #583 audit arms (PR #604): wasi:io/streams@0.2 missing methods ──

    /// Largest single-call read used by the skip / splice host paths.
    /// Matches the cap that `blockingRead` uses. Guests can issue another
    /// call if `len` exceeds the cap — every WIT method here returns the
    /// actual bytes consumed in the ok arm.
    const STREAM_SCRATCH_CAP: usize = 64 * 1024;

    /// `wasi:io/streams.[method]input-stream.skip:
    ///   (borrow<input-stream>, u64) -> result<u64, stream-error>` and
    /// `[method]input-stream.blocking-skip:
    ///   (borrow<input-stream>, u64) -> result<u64, stream-error>`.
    ///
    /// Read up to `len` bytes from the stream and discard them.
    /// Backed by the same `InputStream.read` path as `blockingRead`,
    /// since wamr's captured-buffer / fd / host-file / tcp sources are
    /// all already blocking-on-data — the WIT distinction between
    /// `skip` and `blocking-skip` therefore collapses to a single
    /// host helper (see `populateWasiCliRun`, which wires both names
    /// to this fn).
    fn inputStreamSkip(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const want_u64 = switch (args[1]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        var stream_lease = self.lookupInputStream(handle) orelse return error.InvalidHandle;
        defer stream_lease.release();
        const resource = stream_lease.value();
        const claim = resource.claim();
        claim.acquire();
        defer claim.release();
        const stream = resource.stream;

        const want: usize = @min(want_u64, std.math.maxInt(usize));
        const capped: usize = @min(want, STREAM_SCRATCH_CAP);

        const buf = try allocator.alloc(u8, capped);
        defer allocator.free(buf);

        switch (stream.read(buf)) {
            .ok => |n| {
                const payload = try allocator.create(InterfaceValue);
                payload.* = .{ .u64 = @intCast(n) };
                results[0] = .{ .result_val = .{ .is_ok = true, .payload = payload } };
            },
            .closed => {
                // err arm; payload (stream-error variant) zero-fills —
                // same convention as `blockingRead`.
                results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
            },
            .err => return error.IoError,
        }
    }

    /// `wasi:io/streams.[method]output-stream.write-zeroes:
    ///   (borrow<output-stream>, u64) -> result<_, stream-error>`.
    ///
    /// Write up to `len` zero bytes to the stream. Mirrors
    /// `outputStreamWrite` — synthesises a zeroed scratch buffer of
    /// the requested length (capped at `STREAM_SCRATCH_CAP`) and
    /// pushes it through `OutputStream.write`. The WIT `write` and
    /// `write-zeroes` share the same precondition contract
    /// (`check-write` first) and the same error mapping.
    fn outputStreamWriteZeroes(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const want_u64 = switch (args[1]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        var stream_lease = self.lookupStream(handle) orelse return error.InvalidHandle;
        defer stream_lease.release();
        const resource = stream_lease.value();
        const claim = resource.claim();
        claim.acquire();
        defer claim.release();
        const stream = resource.stream;

        const want: usize = @min(want_u64, std.math.maxInt(usize));
        const capped: usize = @min(want, STREAM_SCRATCH_CAP);

        const buf = try allocator.alloc(u8, capped);
        defer allocator.free(buf);
        @memset(buf, 0);

        switch (stream.write(buf, self.allocator)) {
            .ok => {},
            .err, .closed => return error.IoError,
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `wasi:io/streams.[method]output-stream.blocking-write-zeroes-and-flush:
    ///   (borrow<output-stream>, u64) -> result<_, stream-error>`.
    ///
    /// Loops `outputStreamWriteZeroes` chunks until all `len` bytes
    /// have been written, then flushes — combines the `write-zeroes`
    /// payload synthesis with the trailing flush done by
    /// `blockingWriteAndFlush`.
    fn outputStreamBlockingWriteZeroesAndFlush(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const want_u64 = switch (args[1]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        var stream_lease = self.lookupStream(handle) orelse return error.InvalidHandle;
        defer stream_lease.release();
        const resource = stream_lease.value();
        const claim = resource.claim();
        claim.acquire();
        defer claim.release();
        const stream = resource.stream;

        var remaining: usize = @min(want_u64, std.math.maxInt(usize));
        if (remaining > 0) {
            const chunk_sz: usize = @min(remaining, STREAM_SCRATCH_CAP);
            const buf = try allocator.alloc(u8, chunk_sz);
            defer allocator.free(buf);
            @memset(buf, 0);
            while (remaining > 0) {
                const n = @min(remaining, chunk_sz);
                switch (stream.write(buf[0..n], self.allocator)) {
                    .ok => {},
                    .err, .closed => return error.IoError,
                }
                remaining -= n;
            }
        }
        switch (stream.flush()) {
            .ok => {},
            .err, .closed => return error.IoError,
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `wasi:io/streams.[method]output-stream.splice:
    ///   (borrow<output-stream>, borrow<input-stream>, u64)
    ///   -> result<u64, stream-error>`.
    ///
    /// Uses Linux `splice(2)` when both streams expose compatible host
    /// descriptors without risking a blocking call. Unsupported endpoint
    /// pairs and other platforms retain the buffer-through path.
    fn outputStreamSplice(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        return outputStreamSpliceCommon(ctx_opaque, ci, args, results, allocator, .nonblocking);
    }

    /// `wasi:io/streams.[method]output-stream.blocking-splice`.
    /// Waits for descriptor readiness and retries `EAGAIN`.
    fn outputStreamBlockingSplice(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        return outputStreamSpliceCommon(ctx_opaque, ci, args, results, allocator, .blocking);
    }

    fn outputStreamSpliceCommon(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
        mode: streams.SpliceMode,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;
        const out_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const in_handle = switch (args[1]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const want_u64 = switch (args[2]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        var dst_lease = self.lookupStream(out_handle) orelse return error.InvalidHandle;
        defer dst_lease.release();
        var src_lease = self.lookupInputStream(in_handle) orelse return error.InvalidHandle;
        defer src_lease.release();
        const src_resource = src_lease.value();
        const dst_resource = dst_lease.value();
        const src_claim = src_resource.claim();
        const dst_claim = dst_resource.claim();
        src_claim.acquire();
        defer src_claim.release();
        dst_claim.acquire();
        defer dst_claim.release();
        const src = src_resource.stream;
        const dst = dst_resource.stream;

        const want: usize = @min(want_u64, std.math.maxInt(usize));
        const capped: usize = @min(want, STREAM_SCRATCH_CAP);

        const n_read: usize = switch (streams.splice(src, dst, capped, mode)) {
            .ok => |n| n,
            .closed => {
                results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
                return;
            },
            .err => return error.IoError,
            .unsupported => buffered: {
                const buf = try allocator.alloc(u8, capped);
                defer allocator.free(buf);

                const n = switch (src.read(buf)) {
                    .ok => |read_n| read_n,
                    .closed => {
                        results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
                        return;
                    },
                    .err => return error.IoError,
                };

                switch (dst.write(buf[0..n], self.allocator)) {
                    .ok => {},
                    .err, .closed => return error.IoError,
                }
                break :buffered n;
            },
        };

        const payload = try allocator.create(InterfaceValue);
        payload.* = .{ .u64 = @intCast(n_read) };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = payload } };
    }

    /// `wasi:io/error.[method]error.to-debug-string:
    ///   (borrow<error>) -> string` (#583 audit arm; PR #604).
    ///
    /// wamr does not maintain an io-error table — every host fn that
    /// would surface a `wasi:io/error` instance currently returns
    /// `error.IoError` at the Zig layer and is mapped to a canonical-ABI
    /// trap rather than a real handle. The method is bound so a guest
    /// importing it links cleanly; the body returns an opaque
    /// host-side description that includes the raw handle bits as a
    /// best-effort debug aid.
    fn ioErrorToDebugString(
        _: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const msg = try std.fmt.allocPrint(
            allocator,
            "wasi:io error (opaque host handle #{d})",
            .{handle},
        );
        defer allocator.free(msg);
        const guest_ptr = ci.hostAllocAndWrite(msg, 1) orelse return error.IoError;
        results[0] = .{ .string = .{ .ptr = guest_ptr, .len = @intCast(msg.len) } };
    }

    /// `wasi:sockets/network.network-error-code:
    ///   (borrow<error>) -> option<error-code>` (#583 audit arm; PR #604).
    ///
    /// Free function (not a method) that attempts to downcast a
    /// `wasi:io/error` borrow into a sockets-specific `error-code`.
    /// wamr does not track io-error provenance (see
    /// `ioErrorToDebugString`), so this always returns `none`. A guest
    /// using `network-error-code` purely to discriminate sockets-vs-
    /// other errors will treat any wamr-emitted io-error as non-sockets
    /// — which is correct for the *opaque* error wamr currently
    /// surfaces, since sockets paths return typed `error-code` payloads
    /// directly rather than going through the io-error indirection.
    fn socketsNetworkErrorCode(
        _: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        _ = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        results[0] = .{ .option_val = .{ .is_some = false, .payload = null } };
    }

    // ── wasi:filesystem (#145) ─────────────────────────────────────────────

    /// Append `dir` to the descriptor table as a `.preopen` slot and
    /// register it in `fs_preopens` under `name`. Returns the descriptor
    /// handle (slot index) so callers can pre-bake guest expectations.
    /// The adapter takes ownership of `dir` (closed in `deinit`); `name`
    /// is duplicated.
    pub fn addPreopen(self: *WasiCliAdapter, name: []const u8, dir: std.Io.Dir) !u32 {
        const slot_idx = try self.fs_descriptor_table.publish(.{
            .preopen = .{
                .dir = dir,
                // Per the 0.3 WIT, a preopen directory descriptor
                // exposes `read | mutate-directory` capabilities — the
                // `write` bit is reserved for file descriptors. Children
                // opened from this preopen still receive whatever
                // `open-at` flags the guest passes (subject to the
                // post-#181 mutate-directory check). (#564.)
                .flags = .{ .read = true, .mutate_directory = true },
            },
        });
        errdefer std.debug.assert(self.fs_descriptor_table.remove(slot_idx));
        const dup_name = try self.allocator.dupe(u8, name);
        errdefer self.allocator.free(dup_name);
        self.fs_preopens_claim.acquire();
        self.fs_preopens.append(
            self.allocator,
            .{ .name = dup_name, .dir_handle = slot_idx },
        ) catch |err| {
            self.fs_preopens_claim.release();
            return err;
        };
        self.fs_preopens_claim.release();
        return slot_idx;
    }

    /// Register `wasi:filesystem/preopens` (#145).
    ///
    /// Single member `get-directories: () -> list<tuple<own<descriptor>, string>>`.
    /// Each tuple element is laid out in guest memory as 12 bytes:
    ///   +0  handle: u32
    ///   +4  string-ptr: u32
    ///   +8  string-len: u32
    /// (`record max-align = 4`, see `canonical_abi.zig:336-343`.)
    pub fn populateWasiFilesystemPreopens(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        interface_name: []const u8,
    ) !void {
        try self.fs_preopens_iface.members.put(self.allocator, "get-directories", .{
            .func = .{
                .context = self,
                .call = tracedAdapterCall("filesystem/preopens", "get-directories", &fsGetDirectories),
            },
        });
        try providers.put(self.allocator, interface_name, .{
            .host_instance = &self.fs_preopens_iface,
        });
    }

