            .{ .name = "[method]descriptor.set-times", .call = &fsDescriptorSetTimesP3 },
            .{ .name = "[method]descriptor.set-times-at", .call = &fsDescriptorSetTimesAtP3 },
            .{ .name = "[method]descriptor.stat", .call = &fsDescriptorStatP3 },
