    /// `[method]descriptor.remove-directory-at: (borrow<descriptor>, string)
    ///   -> result<_, error-code>`.
    ///
    /// Maps `error.DirNotEmpty` → `error-code.not-empty`.
    fn fsDescriptorRemoveDirectoryAt(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const path_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };

        var d_lease = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        defer d_lease.release();
        const d = d_lease.value();
        const base_dir: std.Io.Dir = d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };
        if (!d.flags().mutate_directory) {
            results[0] = try fsResultErr(allocator, .read_only);
            return;
        }

        const path_bytes = ci.readGuestBytes(path_pl.ptr, path_pl.len) orelse
            return error.OutOfBoundsMemory;

        if (validateSandboxPath(path_bytes)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        // Linux `unlinkat(.., AT_REMOVEDIR)` returns `EINVAL` for path
        // `.` or any path ending in `.` / `..`, which the Zig stdlib
        // panics on as a "programmer bug". Guard explicitly so the
        // guest sees `Err(ErrorCode::Invalid)` per `filesystem-mkdir-rmdir`
        // (line 73-75 `Err(Invalid | Access)`). (#571.)
        if (pathLastComponentIsDot(path_bytes)) {
            results[0] = try fsResultErr(allocator, .invalid);
            return;
        }
        if (checkPathSymlinks(base_dir, path_bytes, false)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }

        const io = std.Io.Threaded.global_single_threaded.io();
        base_dir.deleteDir(io, path_bytes) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        const ok_payload = try allocator.create(InterfaceValue);
        ok_payload.* = .{ .tuple_val = &.{} };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
    }

    /// `[method]descriptor.rename-at: (borrow<descriptor>, string,
    ///   borrow<descriptor>, string) -> result<_, error-code>`.
    ///
    /// Lifts two descriptor handles (source parent + destination parent) and
    /// requires `mutate_directory` on **both**. Sandbox-validates both paths.
    /// Cross-filesystem moves surface as `error-code.cross-device`.
    fn fsDescriptorRenameAt(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 4 or results.len == 0) return error.InvalidArgs;

        const old_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const old_path_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        const new_handle = switch (args[2]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const new_path_pl = switch (args[3]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };

        var old_lease = self.lookupFsDescriptor(old_handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        defer old_lease.release();
        const old_d = old_lease.value();
        const old_dir: std.Io.Dir = old_d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };
        if (!old_d.flags().mutate_directory) {
            results[0] = try fsResultErr(allocator, .read_only);
            return;
        }

        var new_lease = self.lookupFsDescriptor(new_handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        defer new_lease.release();
        const new_d = new_lease.value();
        const new_dir: std.Io.Dir = new_d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };
        if (!new_d.flags().mutate_directory) {
            results[0] = try fsResultErr(allocator, .read_only);
            return;
        }

        const old_path_bytes = ci.readGuestBytes(old_path_pl.ptr, old_path_pl.len) orelse
            return error.OutOfBoundsMemory;
        const new_path_bytes = ci.readGuestBytes(new_path_pl.ptr, new_path_pl.len) orelse
            return error.OutOfBoundsMemory;

        if (validateSandboxPath(old_path_bytes)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        if (validateSandboxPath(new_path_bytes)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        if (checkPathSymlinks(old_dir, old_path_bytes, false)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        if (checkPathSymlinks(new_dir, new_path_bytes, false)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }

        // POSIX `EINVAL`: renaming to or from a path whose final
        // component is `.` or `..`. Hosts disagree on the reported
        // errno, so normalize before hitting the syscall. (#616 D3.)
        if (pathLastComponentIsDot(old_path_bytes) or
            pathLastComponentIsDot(new_path_bytes))
        {
            results[0] = try fsResultErr(allocator, .invalid);
            return;
        }

        const io = std.Io.Threaded.global_single_threaded.io();
        std.Io.Dir.rename(old_dir, old_path_bytes, new_dir, new_path_bytes, io) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        const ok_payload = try allocator.create(InterfaceValue);
        ok_payload.* = .{ .tuple_val = &.{} };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
    }

    /// `[method]descriptor.link-at: (borrow<descriptor>, path-flags, string,
    ///   borrow<descriptor>, string) -> result<_, error-code>`.
    ///
    /// Hard-links `old-path` (relative to the first descriptor) at
    /// `new-path` (relative to the second). `path-flags.symlink-follow`
    /// is forwarded into `HardLinkOptions.follow_symlinks`. Requires
    /// `mutate_directory` on **both** base descriptors.
    fn fsDescriptorLinkAt(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 5 or results.len == 0) return error.InvalidArgs;

        const old_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const path_flags: u32 = switch (args[1]) {
            .flags_val => |w| if (w.len == 0) 0 else w[0],
            .u32 => |v| v,
            else => 0,
        };
        const follow_symlinks = (path_flags & 0b1) != 0;
        const old_path_pl = switch (args[2]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        const new_handle = switch (args[3]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const new_path_pl = switch (args[4]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };

        var old_lease = self.lookupFsDescriptor(old_handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        defer old_lease.release();
        const old_d = old_lease.value();
        const old_dir: std.Io.Dir = old_d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };
        if (!old_d.flags().mutate_directory) {
            results[0] = try fsResultErr(allocator, .read_only);
            return;
        }

        var new_lease = self.lookupFsDescriptor(new_handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        defer new_lease.release();
        const new_d = new_lease.value();
        const new_dir: std.Io.Dir = new_d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };
        if (!new_d.flags().mutate_directory) {
            results[0] = try fsResultErr(allocator, .read_only);
            return;
        }

        const old_path_bytes = ci.readGuestBytes(old_path_pl.ptr, old_path_pl.len) orelse
            return error.OutOfBoundsMemory;
        const new_path_bytes = ci.readGuestBytes(new_path_pl.ptr, new_path_pl.len) orelse
            return error.OutOfBoundsMemory;

        if (validateSandboxPath(old_path_bytes)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        if (validateSandboxPath(new_path_bytes)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        if (checkPathSymlinks(old_dir, old_path_bytes, follow_symlinks)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        if (checkPathSymlinks(new_dir, new_path_bytes, false)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }

        const io = std.Io.Threaded.global_single_threaded.io();
        std.Io.Dir.hardLink(old_dir, old_path_bytes, new_dir, new_path_bytes, io, .{
            .follow_symlinks = follow_symlinks,
        }) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        const ok_payload = try allocator.create(InterfaceValue);
        ok_payload.* = .{ .tuple_val = &.{} };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
    }

    /// `[method]descriptor.symlink-at: (borrow<descriptor>, string, string)
    ///   -> result<_, error-code>`.
    ///
    /// WIT parameter order: `old-path` is the symlink **target** (the
    /// string contents stored in the link), `new-path` is the **link
    /// name** that gets created. The target is *not* sandbox-validated
    /// because a symlink may legitimately point outside the preopen
    /// (resolution-time validation in `open-at` re-checks the resolved
    /// path); the link path is.
    fn fsDescriptorSymlinkAt(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        // WIT `old-path` = symlink target (link contents). NOT a path on
        // the host — just a string stored verbatim in the symlink inode.
        const target_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        // WIT `new-path` = the link name to create, relative to `handle`.
        const link_pl = switch (args[2]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };

        var d_lease = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        defer d_lease.release();
        const d = d_lease.value();
        const base_dir: std.Io.Dir = d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };
        if (!d.flags().mutate_directory) {
            results[0] = try fsResultErr(allocator, .read_only);
            return;
        }

        const target_bytes = ci.readGuestBytes(target_pl.ptr, target_pl.len) orelse
            return error.OutOfBoundsMemory;
        const link_bytes = ci.readGuestBytes(link_pl.ptr, link_pl.len) orelse
            return error.OutOfBoundsMemory;

        // Only the link path is constrained to the sandbox; the symlink
        // target (link contents) is intentionally unconstrained — see
        // doc-comment.
        if (validateSandboxPath(link_bytes)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        if (checkPathSymlinks(base_dir, link_bytes, false)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }

        const io = std.Io.Threaded.global_single_threaded.io();
        base_dir.symLink(io, target_bytes, link_bytes, .{}) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        const ok_payload = try allocator.create(InterfaceValue);
        ok_payload.* = .{ .tuple_val = &.{} };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
    }

    /// `[method]descriptor.readlink-at: (borrow<descriptor>, string)
    ///   -> result<string, error-code>`.
    ///
    /// Reads the contents of the symlink at `path` (relative to the base
    /// descriptor) into a 4 KiB scratch buffer; copies the result into
    /// guest memory via `hostAllocAndWrite`. Returns `.name_too_long` if
    /// the link target exceeds the buffer (no incremental read API in
    /// std.Io.Dir).
    fn fsDescriptorReadlinkAt(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const path_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };

        var d_lease = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        defer d_lease.release();
        const d = d_lease.value();
        const base_dir: std.Io.Dir = d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };

        const path_bytes = ci.readGuestBytes(path_pl.ptr, path_pl.len) orelse
            return error.OutOfBoundsMemory;

        if (validateSandboxPath(path_bytes)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        if (checkPathSymlinks(base_dir, path_bytes, false)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }

        var buf: [4096]u8 = undefined;
        const io = std.Io.Threaded.global_single_threaded.io();
        const n = base_dir.readLink(io, path_bytes, &buf) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };
        // If the kernel reports the full buffer is used, the actual link
        // target may be longer — report .name_too_long rather than return
        // a silently truncated path.
        if (n == buf.len) {
            results[0] = try fsResultErr(allocator, .name_too_long);
            return;
        }

        const guest_ptr = ci.hostAllocAndWrite(buf[0..n], 1) orelse {
            results[0] = try fsResultErr(allocator, .insufficient_memory);
            return;
        };
        results[0] = try fsResultOk(allocator, .{
            .string = .{ .ptr = guest_ptr, .len = @intCast(n) },
        });
    }

    /// `[method]descriptor.read-directory: (borrow<descriptor>)
    ///   -> result<own<directory-entry-stream>, error-code>` (#476).
    ///
    /// Heap-allocates a `std.Io.Dir.Iterator` (the struct embeds a 2 KiB
    /// read buffer whose self-pointer is fixed up by each `.next()`) and
    /// installs it in `dir_entry_stream_table`. Requires `flags.read` on
    /// the base descriptor; the iterator is independent of that
    /// descriptor's lifetime, mirroring the WIT spec.
    fn fsDescriptorReadDirectory(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };

        var d_lease = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        var descriptor_active = true;
        defer if (descriptor_active) d_lease.release();
        const d = d_lease.value();
        const base_dir: std.Io.Dir = d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };
        if (!d.flags().read) {
            results[0] = try fsResultErr(allocator, .access);
            return;
        }

        const iter = self.allocator.create(std.Io.Dir.Iterator) catch {
            results[0] = try fsResultErr(allocator, .insufficient_memory);
            return;
        };
        iter.* = base_dir.iterate();

        var descriptor_lease: ?FsDescriptorTable.Lease = null;
        if (comptime build_options.lib_wasi_threads) {
            descriptor_lease = d_lease;
            descriptor_active = false;
        }
        const new_handle = self.dir_entry_stream_table.publish(.{
            .iter = iter,
            .descriptor_lease = descriptor_lease,
        }) catch {
            if (descriptor_lease) |*lease| lease.release();
            self.allocator.destroy(iter);
            results[0] = try fsResultErr(allocator, .insufficient_memory);
            return;
        };
        errdefer _ = self.dir_entry_stream_table.remove(new_handle);

        results[0] = try fsResultOk(allocator, .{ .handle = new_handle });
    }

    /// `[method]directory-entry-stream.read-directory-entry: (borrow<...>)
    ///   -> result<option<directory-entry>, error-code>` (#476).
    ///
    /// Returns `option::none` on end-of-iteration. Each entry is a
    /// record `{ type: descriptor-type, name: string }`. The `name` is
    /// copied into guest memory via `hostAllocAndWrite` before yielding
    /// back to the guest — the iterator's read buffer may be overwritten
    /// by the next `.next()` call.
    ///
    /// On Windows, directory entry names are WTF-8 (not strict UTF-8).
    /// Names that aren't valid UTF-8 are surfaced as
    /// `error-code.illegal-byte-sequence` rather than handed to the guest
    /// as a malformed WIT `string`.
    fn fsDirectoryEntryStreamReadDirectoryEntry(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };

        var stream_lease = self.dir_entry_stream_table.acquire(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        defer stream_lease.release();
        const stream = stream_lease.value();

        const io = std.Io.Threaded.global_single_threaded.io();
        stream.operation_claim.acquire();
        const maybe_entry = stream.iter.next(io) catch |err| {
            stream.operation_claim.release();
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        if (maybe_entry) |entry| {
            if (!std.unicode.utf8ValidateSlice(entry.name)) {
                stream.operation_claim.release();
                results[0] = try fsResultErr(allocator, .illegal_byte_sequence);
                return;
            }
            const entry_kind = entry.kind;
            const entry_name = allocator.dupe(u8, entry.name) catch {
                stream.operation_claim.release();
                results[0] = try fsResultErr(allocator, .insufficient_memory);
                return;
            };
            stream.operation_claim.release();
            defer allocator.free(entry_name);

            const dt: DescType = switch (entry_kind) {
                .directory => .directory,
                .file => .regular_file,
                .block_device => .block_device,
                .character_device => .character_device,
                .named_pipe => .fifo,
                .sym_link => .symbolic_link,
                .unix_domain_socket => .socket,
                else => .unknown,
            };

            // Always go through `hostAllocAndWrite`, even when the entry
            // name is empty, so the returned string ptr matches the
            // `TwoAllocs` pin the wit-component preview1 adapter installs
            // around `read-directory-entry` (it asserts
            // `name.as_ptr() == temporary_data`). `std.fs.Dir.Iterator`
            // never yields a zero-length name today, but mirror the #715
            // `fd_read` fix here for symmetry/defence in depth.
            const name_ptr: u32 = ci.hostAllocAndWrite(entry_name, 1) orelse {
                results[0] = try fsResultErr(allocator, .insufficient_memory);
                return;
            };

            const fields = try allocator.alloc(InterfaceValue, 2);
            fields[0] = .{ .variant_val = .{
                .discriminant = @intFromEnum(dt),
                .payload = null,
            } };
            fields[1] = .{ .string = .{ .ptr = name_ptr, .len = @intCast(entry_name.len) } };

            const some_payload = try allocator.create(InterfaceValue);
            some_payload.* = .{ .record_val = fields };
            results[0] = try fsResultOk(allocator, .{ .option_val = .{
                .is_some = true,
                .payload = some_payload,
            } });
            return;
        }
        stream.operation_claim.release();

        // End of iteration → option::none inside Ok arm.
        results[0] = try fsResultOk(allocator, .{ .option_val = .{
            .is_some = false,
            .payload = null,
        } });
    }

    /// `[resource-drop]directory-entry-stream: (own<...>) -> ()` (#476).
    fn fsDirectoryEntryStreamDrop(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        _ = self.dir_entry_stream_table.remove(handle);
    }

    /// `filesystem-error-code: (borrow<error>) -> option<error-code>` (#476).
    ///
    /// Free function (not a descriptor method). Today the host never lifts
    /// a real `io.error` resource into a guest `borrow<error>`, so the
    /// only thing this can legitimately answer is `option::none`. The
    /// shape is registered for completeness and to satisfy guests that
    /// blindly imports this name.
    fn fsFilesystemErrorCode(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        results[0] = .{ .option_val = .{ .is_some = false, .payload = null } };
    }

    // ── wasi:filesystem@0.3.0-* P3 surface (#484, #522) ──────────────────
    //
    // The 0.3 WIT replaces the 0.2 sync `descriptor.*` methods with
    // `async func` returning `future<result<...>>`, and replaces the P2
    // `input-stream`/`output-stream` resources with canonical
    // `stream<u8>` handles. The host implementations below consume those
    // surfaces inline and complete each call synchronously — every
    // returned future is allocated `.ready` with its canonical-ABI
    // payload bytes pre-populated, so a guest `future.read` succeeds
    // without parking and memcpys the lowered result into its dst.
    //
    // The canonical lowering uses the synthetic `fs_p3_local_types`
    // registry declared at module scope; the executor's `future_read`
    // arm (`src/component/executor.zig`) already memcpys
    // `Future.payload.len` bytes into the guest's dst when the future
    // is `.ready` — no executor changes are required.
    //
    // The same simplification applies to `stream<u8>`: read-via-stream
    // pre-buffers up to a chunk of file data into the AsyncStream FIFO
    // and marks the writable end closed (the stream is fully ready for
    // the guest to drain via canon `stream.read`); write-via-stream
    // drains whatever bytes the guest already pushed into the stream
    // FIFO at call time.

    /// Allocate an already-ready `future<...>` slot in `ci.futures` and
    /// return its handle. `payload_bytes` is the canonical-ABI lowered
    /// payload (caller-owned via `ci.allocator`; ownership transfers to
    /// the future slot — the executor's `future_read` arm frees it on
    /// consumption). Pass `null` for unit-typed futures
    /// (`future<()>`) where the executor's fast-path returns zero
    /// bytes copied to the guest.
    fn spawnReadyFsFuture(ci: *ComponentInstance, payload_bytes: ?[]u8) !u32 {
        const handle = ci.allocAsyncHandle();
        ci.futures.put(ci.allocator, handle, .{
            .elem_type_idx = 0,
            .payload = payload_bytes,
            .state = .ready,
            .write_closed = true,
        }) catch |err| {
            if (payload_bytes) |bytes| ci.allocator.free(bytes);
            return err;
        };
        return handle;
    }

    /// Helper for the 21 Tier-A `async func` wrappers: invoke the
    /// existing 0.2 sync body (which writes a `result<X, error-code>`
    /// `InterfaceValue` into a local results slot), lower the value
    /// into canonical-ABI bytes for `kind`, install the byte buffer on
    /// a ready future, and write the future handle into `results[0]`.
    /// (#484, #522 — payload lift)
    fn fsCompleteAsyncSync(
        ci: *ComponentInstance,
        results: []InterfaceValue,
        sync_body: *const fn (?*anyopaque, *ComponentInstance, []const InterfaceValue, []InterfaceValue, Allocator) anyerror!void,
        ctx_opaque: ?*anyopaque,
        args: []const InterfaceValue,
        allocator: Allocator,
        kind: FsP3AsyncReturn,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        var inner_results: [1]InterfaceValue = .{.{ .u32 = 0 }};
        try sync_body(ctx_opaque, ci, args, &inner_results, allocator);
        defer inner_results[0].deinit(allocator);

        // 0.2 stat results carry `.u64` seconds; 0.3 spec uses signed
        // `instant.seconds`. Patch the InterfaceValue tag before lowering.
        if (kind == .desc_stat_err) fsP3FixupStatRecord(inner_results[0]);

        // Lower into a canonical-ABI byte buffer allocated against
        // `ci.allocator` so the `Future`/executor lifecycle frees it.
        const payload = try fsP3LowerAsyncPayload(ci.allocator, kind, inner_results[0]);
        const handle = try spawnReadyFsFuture(ci, payload);
        results[0] = .{ .handle = handle };
    }

    // ── Tier A: async-func wrappers over the 0.2 sync bodies ───────────

    fn fsDescriptorAdviseP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorAdvise, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorCreateDirectoryAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorCreateDirectoryAt, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorGetFlagsP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorGetFlags, ctx, args, allocator, .desc_flags_err);
    }
    fn fsDescriptorGetTypeP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorGetType, ctx, args, allocator, .desc_type_err);
    }
    fn fsDescriptorIsSameObjectP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorIsSameObject, ctx, args, allocator, .just_bool);
    }
    fn fsDescriptorLinkAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorLinkAt, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorMetadataHashP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorMetadataHash, ctx, args, allocator, .metadata_hash_err);
    }
    fn fsDescriptorMetadataHashAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorMetadataHashAt, ctx, args, allocator, .metadata_hash_err);
    }
    fn fsDescriptorOpenAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorOpenAt, ctx, args, allocator, .desc_err);
    }
    fn fsDescriptorReadlinkAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorReadlinkAt, ctx, args, allocator, .string_err);
    }
    fn fsDescriptorRemoveDirectoryAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorRemoveDirectoryAt, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorRenameAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorRenameAt, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorSetSizeP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorSetSize, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorSetTimesP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorSetTimes, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorSetTimesAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorSetTimesAt, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorStatP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorStat, ctx, args, allocator, .desc_stat_err);
    }
    fn fsDescriptorStatAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorStatAt, ctx, args, allocator, .desc_stat_err);
    }
    fn fsDescriptorSymlinkAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorSymlinkAt, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorSyncP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorSync, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorSyncDataP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorSyncData, ctx, args, allocator, .unit_err);
    }
    fn fsDescriptorUnlinkFileAtP3(ctx: ?*anyopaque, ci: *ComponentInstance, args: []const InterfaceValue, results: []InterfaceValue, allocator: Allocator) anyerror!void {
        try fsCompleteAsyncSync(ci, results, &fsDescriptorUnlinkFileAt, ctx, args, allocator, .unit_err);
    }

    // ── Tier B: canonical stream<u8> read/write/append ─────────────────

    /// Cap on the number of bytes pre-buffered into the canonical
    /// `stream<u8>` returned by `read-via-stream`. Mirrors the 64 MiB
    /// chunk used by the 0.2 positional `read` (see `fsDescriptorRead`).
    /// Beyond this, guests must invoke the function again at a later
    /// offset — exactly the semantics of the 0.2 P2 input-stream once
    /// `BUFFER_FILL_MAX` is reached.
    const FS_STREAM_BUFFER_CAP: usize = 64 * 1024 * 1024;

    /// Per-chunk granularity for cancel polling inside the FS stream
    /// drain loops (#583 B1, #602 follow-up). The `pwrite(2)` /
    /// `pread(2)` drivers split any guest buffer larger than this into
    /// chunks of this size and re-check `ctx.cancelled.load(.acquire)`
    /// between chunks, so a `task.cancel` issued mid-multi-MiB
    /// transfer is observed within at most one chunk's syscall
    /// latency. 64 KiB matches the HTTP outbound body-read cadence
    /// (`http_cancel_body_chunk_bytes`) and is large enough that the
    /// per-chunk syscall overhead is negligible relative to the
    /// cancel-observability win. The kernel syscall itself is atomic
    /// from cancel's POV — a 64 KiB pwrite either lands fully or
    /// fails — so the chunk currently in flight always completes
    /// before cancel is honoured.
    const FS_CANCEL_POLL_CHUNK_BYTES: usize = 64 * 1024;

    /// Allocate an empty closed `stream<u8>` slot. Used on the error
    /// arm of `read-via-stream` so the returned tuple's stream handle
    /// is well-typed (a `stream.read` against it yields the standard
    /// "stream-end" outcome immediately).
    fn spawnEmptyClosedStream(ci: *ComponentInstance) !u32 {
        const handle = ci.allocAsyncHandle();
        try ci.streams.put(ci.allocator, handle, .{
            .elem_type_idx = 0,
            .state = .closed,
            .read_closed = false,
            .write_closed = true,
        });
        return handle;
    }

    /// Build the canonical-ABI bytes for a `result<_, error-code>::ok`
    /// payload. Owned by `ci.allocator`. The bytes are pre-zeroed past
    /// the discriminant so the `_` arm has no observable state.
    fn fsP3UnitOkPayload(ci: *ComponentInstance) ![]u8 {
        const val = InterfaceValue{ .result_val = .{ .is_ok = true, .payload = null } };
        return fsP3LowerAsyncPayload(ci.allocator, .unit_err, val);
    }

    /// Build the canonical-ABI bytes for a `result<_, error-code>::err(code)`
    /// payload. Owned by `ci.allocator`.
    fn fsP3UnitErrPayload(ci: *ComponentInstance, code: FsErrorCode) ![]u8 {
        var err_variant = InterfaceValue{ .variant_val = .{
            .discriminant = @intFromEnum(code),
            .payload = null,
        } };
        const val = InterfaceValue{ .result_val = .{ .is_ok = false, .payload = &err_variant } };
        return fsP3LowerAsyncPayload(ci.allocator, .unit_err, val);
    }

    /// Spawn a ready `future<result<_, error-code>>` that resolves to ok.
    fn spawnReadyOkFsFuture(ci: *ComponentInstance) !u32 {
        const payload = try fsP3UnitOkPayload(ci);
        errdefer ci.allocator.free(payload);
        return try spawnReadyFsFuture(ci, payload);
    }

    /// Spawn a ready `future<result<_, error-code>>` that resolves to err.
    fn spawnReadyErrFsFuture(ci: *ComponentInstance, code: FsErrorCode) !u32 {
        const payload = try fsP3UnitErrPayload(ci, code);
        errdefer ci.allocator.free(payload);
        return try spawnReadyFsFuture(ci, payload);
    }

    /// Build the `tuple<stream<u8>, future<...>>` returned by
    /// `read-via-stream` on an error path: a closed empty stream plus a
    /// ready future that already carries the canonical `err(code)`
    /// payload bytes the guest will observe via `future.read`.
    fn fsReadStreamErrorTuple(
        ci: *ComponentInstance,
        allocator: Allocator,
        code: FsErrorCode,
    ) !InterfaceValue {
        const stream_handle = try spawnEmptyClosedStream(ci);
        errdefer _ = ci.streams.remove(stream_handle);
        const future_handle = try spawnReadyErrFsFuture(ci, code);
        errdefer _ = ci.futures.remove(future_handle);
        const fields = try allocator.alloc(InterfaceValue, 2);
        fields[0] = .{ .handle = stream_handle };
        fields[1] = .{ .handle = future_handle };
        return .{ .tuple_val = fields };
    }

    /// `[method]descriptor.read-via-stream: func(offset: filesize)
    ///   -> tuple<stream<u8>, future<result<_, error-code>>>` (#484, #522).
    ///
    /// The host pread()s up to `FS_STREAM_BUFFER_CAP` bytes from the
    /// file at `offset` into a freshly-allocated `AsyncStream`. The
    /// stream's `write_closed` flag is set so a subsequent guest
    /// `stream.read` observes EOF once the FIFO is drained. The
    /// returned future carries the canonical-ABI ok/err payload bytes
    /// so `future.read` lifts the proper `result<_, error-code>` to the
    /// guest at rendezvous time.
    fn fsDescriptorReadViaStreamP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const offset: u64 = switch (args[1]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };

        var d_lease = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsReadStreamErrorTuple(ci, allocator, .bad_descriptor);
            return;
        };
        defer d_lease.release();
        const d = d_lease.value();
        const fs_file: FsDescriptor.FsFile = switch (d.*) {
            .file => |f| f,
            .dir, .preopen => {
                results[0] = try fsReadStreamErrorTuple(ci, allocator, .is_directory);
                return;
            },
        };
        if (!fs_file.flags.read) {
            results[0] = try fsReadStreamErrorTuple(ci, allocator, .access);
            return;
        }

        // Allocate the canonical stream slot and pre-buffer file bytes.
        const stream_handle = ci.allocAsyncHandle();
        var slot: async_mod.AsyncStream = .{
            .elem_type_idx = 0,
            // Pin byte stride (#571 / PR #573 pattern). `stream<u8>`
            // resolves to size 1 in the guest's component-local
            // registry, but cross-instance type-idx resolution can
            // silently regress; the hint keeps `stream.read t`
            // draining in the right units.
            .elem_size_hint = 1,
            .state = .open,
            .read_closed = false,
            // Mark the writable end closed up-front: the host has
            // already streamed everything it intends to into the FIFO.
            .write_closed = true,
        };
        errdefer slot.deinit(ci.allocator);

        const buf_chunk = try allocator.alloc(u8, FS_CANCEL_POLL_CHUNK_BYTES);
        defer allocator.free(buf_chunk);

        // Pre-validate offset: Zig's `readPositional` panics on EINVAL
        // (Linux pread with a negative offset). Cap at i64::MAX —
        // `pread(2)` takes a signed `off_t`, so anything past that wraps
        // negative and is meaningless. Per `filesystem-io` fixture, the
        // guest expects `Err(ErrorCode::Invalid)` for `pread(_, _, u64::MAX)`.
        // We surface this by closing the stream + spawning an err future.
        if (offset > @as(u64, @bitCast(@as(i64, std.math.maxInt(i64))))) {
            try ci.streams.put(ci.allocator, stream_handle, slot);
            errdefer _ = ci.streams.remove(stream_handle);
            const err_future = try spawnReadyErrFsFuture(ci, .invalid);
            errdefer _ = ci.futures.remove(err_future);
            const fields_e = try allocator.alloc(InterfaceValue, 2);
            fields_e[0] = .{ .handle = stream_handle };
            fields_e[1] = .{ .handle = err_future };
            results[0] = .{ .tuple_val = fields_e };
            return;
        }

        // (#583 B1, #602 follow-up) Allocate the cancel-aware
        // host_driver ctx BEFORE the eager-prebuffer fill so its
        // `cancelled` flag is visible to a peer-thread cancel driver
        // mid-fill. The fill helper below polls
        // `read_ctx.cancelled.load(.acquire)` between every
        // `FS_CANCEL_POLL_CHUNK_BYTES`-sized `readPositional(2)`, so
        // a `task.cancel` issued while the host is part-way through a
        // multi-MiB pre-buffer is observed within one chunk's pread
        // latency — mirroring the HTTP outbound body-read cadence
        // from #602.
        const read_ctx = try self.allocFsReadStreamCtx(handle, offset);
        fsEagerPreBufferChunked(fs_file, read_ctx, &slot, offset, buf_chunk, ci.allocator);

        // (#583 B1) The cancel-aware host_driver wiring lets the
        // adapter-wide `cancelAllPendingAsyncOps` driver surface
        // `canon task.cancel` on read streams. With `write_closed =
        // true` set above the executor only drains the buffered
        // bytes and never re-enters the driver in steady state — the
        // wiring is "armed but dormant", primed for the lazy-chunked
        // drain refactor (which will leave `write_closed` false and
        // dispatch the driver on FIFO exhaustion).
        slot.elem_size_hint = 1;
        slot.host_driver = .{
            .context = read_ctx,
            .on_read = &fsReadViaStreamOnRead,
            .on_destroy = &fsReadStreamCtxOnDestroy,
        };

        try ci.streams.put(ci.allocator, stream_handle, slot);
        errdefer _ = ci.streams.remove(stream_handle);

        const future_handle = try spawnReadyOkFsFuture(ci);
        errdefer _ = ci.futures.remove(future_handle);
        const fields = try allocator.alloc(InterfaceValue, 2);
        fields[0] = .{ .handle = stream_handle };
        fields[1] = .{ .handle = future_handle };
        results[0] = .{ .tuple_val = fields };
    }

    /// Allocate a heap-stable `FsReadStreamCtx` and stash it on
    /// `fs_read_stream_ctxs` so the executor's `*AsyncStream` can
    /// hold a stable `host_driver.context` pointer for the lifetime
    /// of the stream. Mirrors `allocFsWriteStreamCtx`. (#583 B1)
    fn allocFsReadStreamCtx(
        self: *WasiCliAdapter,
        desc_handle: u32,
        offset: u64,
    ) !*FsReadStreamCtx {
        const ctx = try self.allocator.create(FsReadStreamCtx);
        ctx.* = .{
            .adapter = self,
            .desc_handle = desc_handle,
            .offset = offset,
            .bytes_read = 0,
            .cancelled = .{ .raw = false },
        };
        if (comptime build_options.lib_wasi_threads) {
            const published = self.fs_read_stream_ctxs.publishLeased(ctx) catch {
                self.allocator.destroy(ctx);
                return error.OutOfMemory;
            };
            ctx.registry_handle = published.handle;
            ctx.self_lease = published.lease;
        } else {
            ctx.registry_handle = self.fs_read_stream_ctxs.publish(ctx) catch {
                self.allocator.destroy(ctx);
                return error.OutOfMemory;
            };
        }
        return ctx;
    }

    /// Eagerly fill a `read-via-stream` slot's pre-buffer with up to
    /// `FS_STREAM_BUFFER_CAP` bytes from `fs_file` at `base_offset`,
    /// splitting the drain into `FS_CANCEL_POLL_CHUNK_BYTES`-sized
    /// `readPositional(2)` chunks and polling
    /// `ctx.cancelled.load(.acquire)` between every chunk so a
    /// peer-thread cancel driver can interrupt the fill within one
    /// chunk's pread latency (#583 B1, #602 follow-up).
    ///
    /// `scratch` must be at least `FS_CANCEL_POLL_CHUNK_BYTES` bytes;
    /// only the first chunk-sized prefix is touched per iteration.
    ///
    /// Side effects: appends drained bytes to `slot.buffer` and
    /// updates `ctx.bytes_read` after each chunk via `@atomicStore`
    /// so peer threads watching the running counter see contiguous
    /// progress. Returns silently on cancel, short read, EOF, or any
    /// `readPositional` / `appendSlice` error — the pre-buffer is
    /// best-effort and mirrors the prior single-syscall behaviour of
    /// swallowing read errors as zero bytes drained.
    fn fsEagerPreBufferChunked(
        fs_file: FsDescriptor.FsFile,
        ctx: *FsReadStreamCtx,
        slot: *async_mod.AsyncStream,
        base_offset: u64,
        scratch: []u8,
        list_allocator: Allocator,
    ) void {
        std.debug.assert(scratch.len >= FS_CANCEL_POLL_CHUNK_BYTES);
        const io = std.Io.Threaded.global_single_threaded.io();
        var total: u64 = 0;
        const max_total: u64 = @as(u64, FS_STREAM_BUFFER_CAP);
        while (total < max_total) {
            if (ctx.cancelled.load(.acquire)) break;
            const remaining: u64 = max_total - total;
            const chunk_len: usize = @intCast(@min(
                remaining,
                @as(u64, FS_CANCEL_POLL_CHUNK_BYTES),
            ));
            const chunk_offset: u64 = base_offset +% total;
            const n: usize = fs_file.file.readPositional(
                io,
                &.{scratch[0..chunk_len]},
                chunk_offset,
            ) catch 0;
            if (n == 0) break;
            // Best-effort: if the slot's buffer can't grow we bail
            // the same way a `readPositional` error does — the bytes
            // already drained stay; the rest is abandoned.
            slot.buffer.appendSlice(list_allocator, scratch[0..n]) catch break;
            total += @as(u64, n);
            // Atomic store so a peer thread watching `bytes_read`
            // sees the running counter advance without UB.
            @atomicStore(u64, &ctx.bytes_read, total, .release);
            if (n < chunk_len) break; // short read => EOF reached
        }
    }

    /// `host_driver.on_read` for a `descriptor.read-via-stream`
    /// `stream<u8>` slot (#583 B1). Today's eager pre-buffer leaves
    /// `write_closed = true`, so the executor never actually fires
    /// this callback in steady state — but it is the cancel
    /// observation point for the read path, so when
    /// `cancelAllPendingAsyncOps` flips `ctx.cancelled` the next
    /// `stream.read` (should the writable end ever be re-opened) will
    /// see `.eof` and close the read end cleanly. Returning `.eof`
    /// triggers `s.write_closed = true` in the executor.
    fn fsReadViaStreamOnRead(
        opaque_ctx: ?*anyopaque,
        _: *async_mod.AsyncStream,
        _: Allocator,
    ) async_mod.HostStreamAction {
        const ctx: *FsReadStreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        if (ctx.cancelled.load(.acquire)) return .eof;
        // No lazy refill yet — pre-buffer fully filled by the
        // trampoline. Treat as EOF so the executor closes the
        // writable end naturally.
        return .eof;
    }

    /// `[method]descriptor.write-via-stream: func(data: stream<u8>,
    ///   offset: filesize) -> future<result<_, error-code>>` (#484).
    ///
    /// Drains whatever bytes the guest already pushed into the
    /// canonical stream's FIFO and pwrites them at `offset`. The
    /// returned future is ready immediately. Any bytes the guest
    /// `stream.write`s after this call returns will accumulate in the
    /// AsyncStream FIFO; flushing them is a wave-D concern.
    fn fsDescriptorWriteViaStreamP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;
        const desc_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const stream_handle = switch (args[1]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const offset: u64 = switch (args[2]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        try fsWriteFromStream(self, ci, desc_handle, stream_handle, offset, false, results);
        _ = allocator;
    }

    /// `[method]descriptor.append-via-stream: func(data: stream<u8>)
    ///   -> future<result<_, error-code>>` (#484). Same as
    ///   `write-via-stream` with `append = true`.
    fn fsDescriptorAppendViaStreamP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const desc_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const stream_handle = switch (args[1]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        try fsWriteFromStream(self, ci, desc_handle, stream_handle, 0, true, results);
        _ = allocator;
    }

    /// Common helper: install a `host_driver.on_write` on the guest's
    /// `stream<u8>` so subsequent `stream.write`s pwrite into `fs_file`
    /// at `offset + bytes_written` (or end-of-file when `append` is
    /// set). Any bytes the guest pre-buffered into the stream FIFO
    /// before calling `write-via-stream` / `append-via-stream` are
    /// drained eagerly through the same path so the running offset
    /// stays consistent with the install-time invariants.
    ///
    /// The companion `future<result<_,error-code>>` settles to ok
    /// immediately — per-write failures surface to the guest through
    /// `read_closed = true` on the stream, which causes the next
    /// `stream.write` to return DROPPED (the guest's `StreamResult`
    /// loop in `pwrite` then breaks out and reports the partial
    /// `written` count).
    fn fsWriteFromStream(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        desc_handle: u32,
        stream_handle: u32,
        offset: u64,
        append: bool,
        results: []InterfaceValue,
    ) !void {
        const future_handle: u32 = blk: {
            var d_lease = self.lookupFsDescriptor(desc_handle) orelse {
                break :blk try spawnReadyErrFsFuture(ci, .bad_descriptor);
            };
            defer d_lease.release();
            const d = d_lease.value();
            const fs_file: FsDescriptor.FsFile = switch (d.*) {
                .file => |f| f,
                .dir, .preopen => break :blk try spawnReadyErrFsFuture(ci, .is_directory),
            };
            if (!fs_file.flags.write) break :blk try spawnReadyErrFsFuture(ci, .access);

            const ctx = try self.allocFsWriteStreamCtx(desc_handle, offset, append);
            var stream_lease = ci.streams.acquire(stream_handle) orelse {
                fsWriteStreamCtxOnDestroy(ctx);
                break :blk try spawnReadyErrFsFuture(ci, .bad_descriptor);
            };

            while (true) {
                const slot = stream_lease.value();
                // Pin byte stride (#571 / PR #573 pattern). `stream<u8>`
                // resolves to size 1 in the guest's component-local
                // registry, but cross-instance type-idx resolution can
                // silently regress; the hint keeps `stream.read t` /
                // `stream.write t` draining in the right units.
                slot.elem_size_hint = 1;

                if (slot.buffer.items.len == 0) {
                    // Install the driver so subsequent guest writes flow
                    // through the zero-copy pwrite callback.
                    slot.host_driver = .{
                        .context = ctx,
                        .on_write = &fsWriteViaStreamOnWrite,
                        .on_write_from = &fsWriteViaStreamOnWriteFrom,
                        .on_destroy = &fsWriteStreamCtxOnDestroy,
                    };
                    stream_lease.release();
                    break;
                }

                var detached = slot.buffer;
                slot.buffer = .empty;
                stream_lease.release();
                defer detached.deinit(ci.allocator);
                const action = fsWriteViaStreamOnWriteFrom(ctx, detached.items);
                switch (action) {
                    .progressed => {},
                    .would_block => {},
                    .eof, .err => {
                        if (ci.streams.acquire(stream_handle)) |failed_lease| {
                            var final_lease = failed_lease;
                            final_lease.value().read_closed = true;
                            final_lease.release();
                        }
                        fsWriteStreamCtxOnDestroy(ctx);
                        break :blk try spawnReadyErrFsFuture(ci, .io);
                    },
                }
                stream_lease = ci.streams.acquire(stream_handle) orelse
                    break :blk try spawnReadyErrFsFuture(ci, .bad_descriptor);
            }

            break :blk try spawnReadyOkFsFuture(ci);
        };
        results[0] = .{ .handle = future_handle };
    }

    /// Allocate a heap-stable `FsWriteStreamCtx` and stash it on
    /// `fs_write_stream_ctxs` so the executor's `*AsyncStream` can
    /// hold a stable `host_driver.context` pointer for the lifetime
    /// of the stream.
    fn allocFsWriteStreamCtx(
        self: *WasiCliAdapter,
        desc_handle: u32,
        offset: u64,
        append: bool,
    ) !*FsWriteStreamCtx {
        const ctx = try self.allocator.create(FsWriteStreamCtx);
        ctx.* = .{
            .adapter = self,
            .desc_handle = desc_handle,
            .offset = offset,
            .bytes_written = 0,
            .append = append,
            .cancelled = .{ .raw = false },
        };
        if (comptime build_options.lib_wasi_threads) {
            const published = self.fs_write_stream_ctxs.publishLeased(ctx) catch {
                self.allocator.destroy(ctx);
                return error.OutOfMemory;
            };
            ctx.registry_handle = published.handle;
            ctx.self_lease = published.lease;
        } else {
            ctx.registry_handle = self.fs_write_stream_ctxs.publish(ctx) catch {
                self.allocator.destroy(ctx);
                return error.OutOfMemory;
            };
        }
        return ctx;
    }

    /// `host_driver.on_write_from` for a `descriptor.write-via-stream`
    /// / `descriptor.append-via-stream` `stream<u8>` slot (#583 B2
    /// follow-up). Zero-copy variant of `fsWriteViaStreamOnWrite`:
    /// `src` is a borrowed slice of guest linmem already validated by
    /// the executor (`readGuestBytes(guest_ptr, byte_len)` against
    /// `memory.size`), so we `pwriteAll(2)` directly from guest
    /// memory at `offset + bytes_written` (or end-of-file in append
    /// mode), advancing the running counter so the next chunk lands
    /// contiguously.
    ///
    /// Multi-MiB guest buffers are split into
    /// `FS_CANCEL_POLL_CHUNK_BYTES`-sized chunks; the cancel flag is
    /// polled with `.load(.acquire)` between every chunk so a
    /// `task.cancel` issued mid-drain is observed within one chunk's
    /// `pwrite(2)` latency (#583 B1, #602 follow-up). The first
    /// chunk's pwrite is uninterruptible — a kernel `pwrite(2)` of
    /// N bytes is atomic from cancel's POV — but every chunk after
    /// that is preceded by a cancel poll. Returning `.err` mid-buffer
    /// preserves `bytes_written` exactly at the cancel-observation
    /// point: the file on disk holds the bytes from the chunks that
    /// completed before cancel was seen, with no partial-chunk tear.
    ///
    /// Re-looks up the underlying `FsDescriptor` each call: if the
    /// guest dropped the descriptor while the stream is still live,
    /// the lookup fails and we surface `.err` rather than UAF the fd.
    fn fsWriteViaStreamOnWriteFrom(
        opaque_ctx: ?*anyopaque,
        src: []const u8,
    ) async_mod.HostStreamAction {
        const ctx: *FsWriteStreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        ctx.operation_claim.acquire();
        defer ctx.operation_claim.release();
        // (#583 B1) Pre-entry cancel check: bail before any pwrite(2)
        // if the guest already cancelled. Returning `.err` makes the
        // executor flip `read_closed = true` so the guest's next
        // `stream.write` returns DROPPED, matching the wit-bindgen
        // `Subtask` "cancelled mid-stream" decoder path.
        if (ctx.cancelled.load(.acquire)) return .err;
        if (src.len == 0) return .progressed;
        var d_lease = ctx.adapter.lookupFsDescriptor(ctx.desc_handle) orelse return .err;
        defer d_lease.release();
        const d = d_lease.value();
        const fs_file: FsDescriptor.FsFile = switch (d.*) {
            .file => |f| f,
            .dir, .preopen => return .err,
        };
        if (!fs_file.flags.write) return .err;
        const io = std.Io.Threaded.global_single_threaded.io();

        // (#583, #602 follow-up) Chunked pwrite drain with per-chunk
        // cancel polling. Splits the guest's buffer into
        // `FS_CANCEL_POLL_CHUNK_BYTES` (64 KiB) slices; between each
        // pwrite we re-check `ctx.cancelled` so a mid-drain
        // `task.cancel` is observed within one chunk's latency. The
        // first chunk is uninterruptible (the pre-entry check above
        // is the only opportunity to skip it) — every subsequent
        // chunk is preceded by a poll. Mirrors the HTTP body-read
        // pattern from #602.
        var written_this_call: usize = 0;
        while (written_this_call < src.len) {
            // Skip the poll on the very first chunk — the pre-entry
            // check already covered that case. Polling between
            // chunks limits the worst-case "after cancel was set"
            // wasted work to one in-flight pwrite.
            if (written_this_call > 0 and ctx.cancelled.load(.acquire)) return .err;
            const remaining = src.len - written_this_call;
            const chunk_len = @min(remaining, FS_CANCEL_POLL_CHUNK_BYTES);
            const chunk = src[written_this_call..][0..chunk_len];
            const write_offset: u64 = if (ctx.append) blk: {
                // Append mode: position at the current end-of-file
                // for every chunk so concurrent extenders (other
                // descriptors pointing at the same inode) don't
                // clobber bytes we just wrote. Best-effort: a stat
                // failure surfaces as `.err`.
                const stat = fs_file.file.stat(io) catch return .err;
                break :blk stat.size;
            } else ctx.offset +% ctx.bytes_written;
            fs_file.file.writePositionalAll(io, chunk, write_offset) catch return .err;
            // Use an atomic store so observers (e.g. a peer thread
            // running the cancel driver) see the running counter
            // advance without UB on the cross-thread read.
            @atomicStore(u64, &ctx.bytes_written, ctx.bytes_written + @as(u64, chunk_len), .release);
            written_this_call += chunk_len;
        }
        return .progressed;
    }

    /// Legacy `host_driver.on_write` shape for a
    /// `descriptor.write-via-stream` slot. Retained for back-compat
    /// with the eager pre-buffer drain at install time and unit-test
    /// callers that invoke the driver callback directly. Delegates
    /// straight to the `on_write_from` zero-copy variant — both
    /// pointers are installed on the same driver entry so the
    /// executor sees the thinner signature first.
    fn fsWriteViaStreamOnWrite(
        opaque_ctx: ?*anyopaque,
        _: *async_mod.AsyncStream,
        bytes: []const u8,
        _: Allocator,
    ) async_mod.HostStreamAction {
        return fsWriteViaStreamOnWriteFrom(opaque_ctx, bytes);
    }

    // ── Tier C: canonical stream<directory-entry> ──────────────────────

    /// `[method]descriptor.read-directory: func()
    ///   -> tuple<stream<directory-entry>, future<result<_, error-code>>>`
    /// (#484, #522).
    ///
    /// Eagerly enumerates the directory via `std.Io.Dir.Iterator` (the
    /// iterator embeds a ~2 KiB read buffer with a self-pointer that
    /// `.next()` re-fixes each call — heap allocation is safe). Each
    /// entry is lowered into the canonical `directory-entry` record
    /// layout `{ type: descriptor-type, name: string }` and appended to
    /// the AsyncStream FIFO so guests can `stream.read` one entry per
    /// rendezvous. The writable end is closed up-front so a subsequent
    /// drain observes stream-end naturally; the companion future
    /// settles to `ok` (or `err(code)` on enumeration failure).
    fn fsDescriptorReadDirectoryP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const desc_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };

        var d_lease = self.lookupFsDescriptor(desc_handle) orelse {
            results[0] = try fsReadDirectoryErrorTuple(ci, allocator, .bad_descriptor);
            return;
        };
        defer d_lease.release();
        const d = d_lease.value();
        const base_dir: std.Io.Dir = d.asDir() orelse {
            results[0] = try fsReadDirectoryErrorTuple(ci, allocator, .not_directory);
            return;
        };
        if (!d.flags().read) {
            results[0] = try fsReadDirectoryErrorTuple(ci, allocator, .access);
            return;
        }

        // Allocate the canonical stream<directory-entry> slot. The
        // element size is computed from `fs_p3_local_types[DIRECTORY_ENTRY_IDX]`
        // — the executor's `stream.read t` op carries the guest's
        // `directory-entry` type idx, which has the same canonical
        // layout (string + variant<8>). Each guest read consumes one
        // entry-worth of bytes from the FIFO.
        const stream_handle = ci.allocAsyncHandle();
        const reg = fsP3TypeRegistry();
        const entry_t: ctypes.ValType = .{ .record = FS_P3_DIRECTORY_ENTRY_IDX };
        const entry_size = abi.sizeOfType(reg, entry_t);
        var slot: async_mod.AsyncStream = .{
            .elem_type_idx = 0,
            // `directory-entry` lives in the wasi:filesystem typespace
            // and is reached through the host's `fs_p3_local_types`
            // registry. The component-local `TypeRegistry` for the
            // guest doesn't always carry a resolvable size for it (the
            // stream's `t` is a cross-instance type-idx) — pin the
            // stride here so `stream.read t` drains in the same units
            // we lowered. (#571.)
            .elem_size_hint = entry_size,
            .state = .open,
            .read_closed = false,
            .write_closed = true, // host streams the whole listing upfront.
        };
        errdefer slot.deinit(ci.allocator);

        // Heap-allocate the iterator: its struct embeds a ~2 KiB read
        // buffer whose self-pointer is fixed up on every `.next()`
        // call, so moving it into the heap is safe (memory note
        // verified at lib/std/Io/Dir.zig:180-209).
        const iter = try ci.allocator.create(std.Io.Dir.Iterator);
        defer ci.allocator.destroy(iter);
        iter.* = base_dir.iterate();

        const io = std.Io.Threaded.global_single_threaded.io();
        var enum_err: ?FsErrorCode = null;
        while (true) {
            const maybe_entry = iter.next(io) catch |err| {
                enum_err = mapFsError(err);
                break;
            };
            const entry = maybe_entry orelse break;
            // Skip names that aren't valid UTF-8 — WIT `string` is
            // strict UTF-8 (mirrors the 0.2 `read-directory-entry`
            // surfacing of `illegal-byte-sequence`).
            if (!std.unicode.utf8ValidateSlice(entry.name)) {
                enum_err = .illegal_byte_sequence;
                break;
            }

            const dt: DescType = switch (entry.kind) {
                .directory => .directory,
                .file => .regular_file,
                .block_device => .block_device,
                .character_device => .character_device,
                .named_pipe => .fifo,
                .sym_link => .symbolic_link,
                .unix_domain_socket => .socket,
                else => .unknown,
            };

            // Copy the name into guest memory so the lowered string
            // ptr survives past this iteration (the iterator buffer is
            // overwritten on the next call).
            const name_ptr: u32 = if (entry.name.len == 0)
                0
            else
                (ci.hostAllocAndWrite(entry.name, 1) orelse {
                    enum_err = .insufficient_memory;
                    break;
                });

            const type_variant = InterfaceValue{
                .variant_val = .{
                    // Transcode the 0.2-shape `DescType` discriminant to
                    // the 0.3 wire ordering (#571 follow-up to #564). The
                    // 0.3 `descriptor-type` variant drops 0.2's leading
                    // `unknown` and shifts each remaining case down by one
                    // — see `descTypeToP3Disc`. Without this, the guest
                    // mis-interprets the kind tag and wit-bindgen's variant
                    // reader can synthesize a `NonNull::new_unchecked` UB
                    // on a string-payload variant that should have had a
                    // different disc.
                    .discriminant = descTypeToP3Disc(@intFromEnum(dt)),
                    .payload = null,
                },
            };
            const record_fields = [_]InterfaceValue{
                type_variant,
                .{ .string = .{ .ptr = name_ptr, .len = @intCast(entry.name.len) } },
            };
            const record_val = InterfaceValue{ .record_val = &record_fields };

            // Lower this entry into a per-entry buffer and append to
            // the stream FIFO. We allocate inline rather than via the
            // helper because the bytes immediately move into the
            // long-lived FIFO.
            const slot_buf = try allocator.alloc(u8, entry_size);
            defer allocator.free(slot_buf);
            @memset(slot_buf, 0);
            abi.storeValReg(slot_buf, 0, entry_t, record_val, reg) catch {
                enum_err = .io;
                break;
            };
            try slot.buffer.appendSlice(ci.allocator, slot_buf);
        }

        try ci.streams.put(ci.allocator, stream_handle, slot);
        errdefer _ = ci.streams.remove(stream_handle);

        const future_handle: u32 = if (enum_err) |code|
            try spawnReadyErrFsFuture(ci, code)
        else
            try spawnReadyOkFsFuture(ci);
        errdefer _ = ci.futures.remove(future_handle);

        const fields = try allocator.alloc(InterfaceValue, 2);
        fields[0] = .{ .handle = stream_handle };
        fields[1] = .{ .handle = future_handle };
        results[0] = .{ .tuple_val = fields };
    }

    /// Mirror of `fsReadStreamErrorTuple` for the `read-directory` shape.
    fn fsReadDirectoryErrorTuple(
        ci: *ComponentInstance,
        allocator: Allocator,
        code: FsErrorCode,
    ) !InterfaceValue {
        const stream_handle = try spawnEmptyClosedStream(ci);
        errdefer _ = ci.streams.remove(stream_handle);
        const future_handle = try spawnReadyErrFsFuture(ci, code);
        errdefer _ = ci.futures.remove(future_handle);
        const fields = try allocator.alloc(InterfaceValue, 2);
        fields[0] = .{ .handle = stream_handle };
        fields[1] = .{ .handle = future_handle };
        return .{ .tuple_val = fields };
    }

    /// `wasi:filesystem/types.[resource-drop]descriptor: (own<descriptor>) -> ()`.
    /// Preopen slots are persistent — drop is a no-op so subsequent calls
    /// to `preopens.get-directories` and `descriptor.open-at` continue
    /// to work.
    fn fsDescriptorDrop(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var lease = self.fs_descriptor_table.acquire(handle) orelse return;
        const is_preopen = lease.value().* == .preopen;
        lease.release();
        if (!is_preopen) _ = self.fs_descriptor_table.remove(handle);
    }

    // ── wasi:sockets/* (#148) ──────────────────────────────────────────────
    //
    // Default-deny capability model: every method that would touch the
    // network returns `error-code.access-denied` (or, for resolution,
    // `name-unresolvable`). Pure getters (e.g. `address-family`,
    // `is-listening`) read the adapter-side `Socket` rep so they can
    // answer without IO. The TODOs throughout flag the code paths the
    // future allow-list capability work will fill in.

    /// Build a `result<X, error-code>` err InterfaceValue. Caller-owned via
    /// `allocator`. Mirrors `fsResultErr` but specialized to sockets'
    /// error-code variant indices.
    fn socketResultErr(allocator: Allocator, code: SocketErrorCode) !InterfaceValue {
        const payload = try allocator.create(InterfaceValue);
        payload.* = .{ .variant_val = .{ .discriminant = @intFromEnum(code), .payload = null } };
        return .{ .result_val = .{ .is_ok = false, .payload = payload } };
    }

    /// Map our internal `SocketErrorCode` (matches WASI 0.2 `enum`
    /// numbering with `unknown=0`) to the WASI 0.3 `variant error-code`
    /// discriminant from `wasi:sockets/types@0.3.0-rc-2026-03-15`. 0.3
    /// dropped `unknown` and shifted all subsequent cases down by one,
    /// and also dropped a handful of P2-specific cases (`concurrency-
    /// conflict`, `not-in-progress`, `would-block`, `new-socket-limit`,
    /// `name-unresolvable`, `temporary-resolver-failure`, `permanent-
    /// resolver-failure`) which we collapse onto the `other(none)`
    /// catch-all (case 14). (#520 wave 2)
    pub fn socketCodeToP3Disc(code: SocketErrorCode) u32 {
        return switch (code) {
            .unknown => 14, // other(none)
            .access_denied => 0,
            .not_supported => 1,
            .invalid_argument => 2,
            .out_of_memory => 3,
            .timeout => 4,
            .concurrency_conflict => 14,
            .not_in_progress => 14,
            .would_block => 14,
            .invalid_state => 5,
            .new_socket_limit => 14,
            .address_not_bindable => 6,
            .address_in_use => 7,
            .remote_unreachable => 8,
            .connection_refused => 9,
            .connection_reset => 11,
            .connection_aborted => 12,
            .datagram_too_large => 13,
            // DNS-only cases on `wasi:sockets/ip-name-lookup` —
            // callers using this helper for the `types` variant should
            // never hit these; `other(none)` is the safe fallback.
            .name_unresolvable => 14,
            .temporary_resolver_failure => 14,
            .permanent_resolver_failure => 14,
        };
    }

    /// P3-aware variant of `socketResultErr` that emits WIT 0.3
    /// `variant error-code` discriminants. Use from any host fn
    /// targeting `wasi:sockets/types@0.3.0-rc-2026-03-15`. (#520 wave 2)
    fn socketResultErrP3(allocator: Allocator, code: SocketErrorCode) !InterfaceValue {
        const payload = try allocator.create(InterfaceValue);
        payload.* = .{ .variant_val = .{
            .discriminant = socketCodeToP3Disc(code),
            .payload = null,
        } };
        return .{ .result_val = .{ .is_ok = false, .payload = payload } };
    }

    /// Diagnostic-carrying variant of `socketResultErrP3`. When `code`
    /// maps to the `other(option<string>)` arm (discriminant 14) and a
    /// non-empty `diag` is provided, the host-side string is copied
    /// into guest linear memory via `ci.hostAllocAndWrite` and attached
    /// as `option::some(diag)`. For any non-`other` arm `diag` is
    /// ignored — those cases are unit per the 0.3 WIT spec and adding
    /// payload bytes would shift the variant's encoded length and
    /// scramble the guest's variant lift. Falls back to `other(none)`
    /// if the diagnostic is null/empty or guest allocation fails so
    /// the caller never observes a partially-populated value. (#563)
    fn socketResultErrP3WithDiag(
        ci: *ComponentInstance,
        allocator: Allocator,
        code: SocketErrorCode,
        diag: ?[]const u8,
    ) !InterfaceValue {
        const disc = socketCodeToP3Disc(code);
        const payload = try allocator.create(InterfaceValue);
        if (disc == SOCKETS_P3_ERROR_OTHER_DISC) {
            if (diag) |msg| {
                if (msg.len != 0) {
                    if (ci.hostAllocAndWrite(msg, 1)) |ptr| {
                        const str_iv = try allocator.create(InterfaceValue);
                        str_iv.* = .{ .string = .{ .ptr = ptr, .len = @intCast(msg.len) } };
                        const opt_iv = try allocator.create(InterfaceValue);
                        opt_iv.* = .{ .option_val = .{ .is_some = true, .payload = str_iv } };
                        payload.* = .{ .variant_val = .{
                            .discriminant = disc,
                            .payload = opt_iv,
                        } };
                        return .{ .result_val = .{ .is_ok = false, .payload = payload } };
                    }
                }
            }
            const none_iv = try allocator.create(InterfaceValue);
            none_iv.* = .{ .option_val = .{ .is_some = false, .payload = null } };
            payload.* = .{ .variant_val = .{
                .discriminant = disc,
                .payload = none_iv,
            } };
            return .{ .result_val = .{ .is_ok = false, .payload = payload } };
        }
        payload.* = .{ .variant_val = .{
            .discriminant = disc,
            .payload = null,
        } };
        return .{ .result_val = .{ .is_ok = false, .payload = payload } };
    }

    /// Build a `result<X, error-code>` ok InterfaceValue.
    fn socketResultOk(allocator: Allocator, value: InterfaceValue) !InterfaceValue {
        const payload = try allocator.create(InterfaceValue);
        payload.* = value;
        return .{ .result_val = .{ .is_ok = true, .payload = payload } };
    }

    /// In-place remap the err-discriminant of a `result<_, error-code>`
    /// from the 0.2 `enum` numbering used by `socketResultErr` to the
    /// 0.3 `variant` numbering expected by `wasi:sockets/types@0.3.0-*`
    /// guests. Used by `p3SocketWrapper` to share property setters /
    /// getters between the 0.2 and 0.3 binding tables (#561).
    fn remapSocketErrDiscToP3(results: []InterfaceValue) void {
        if (results.len == 0) return;
        switch (results[0]) {
            .result_val => |rv| {
                if (rv.is_ok) return;
                const pl = rv.payload orelse return;
                const mutable_pl: *InterfaceValue = @constCast(pl);
                switch (mutable_pl.*) {
                    .variant_val => |*vv| {
                        const code: SocketErrorCode = @enumFromInt(vv.discriminant);
                        vv.discriminant = socketCodeToP3Disc(code);
                    },
                    else => {},
                }
            },
            else => {},
        }
    }

    /// Comptime wrapper that adapts a 0.2-style host function (one
    /// that emits `socketResultErr` discriminants) to the 0.3 binding
    /// table (#561). Returns a struct whose `call` member is a fn
    /// pointer suitable for `ImportBinding.func.call`.
    fn p3SocketWrapper(comptime inner: fn (
        ?*anyopaque,
        *ComponentInstance,
        []const InterfaceValue,
        []InterfaceValue,
        Allocator,
    ) anyerror!void) type {
        return struct {
            pub fn call(
                ctx_opaque: ?*anyopaque,
                ci: *ComponentInstance,
                args: []const InterfaceValue,
                results: []InterfaceValue,
                allocator: Allocator,
            ) anyerror!void {
                try inner(ctx_opaque, ci, args, results, allocator);
                remapSocketErrDiscToP3(results);
            }
        };
    }

    fn lookupSocket(self: *WasiCliAdapter, handle: u32) ?SocketLease {
        var table_lease = self.socket_table.acquire(handle) orelse return null;
        const socket = table_lease.value();
        socket.operation_claim.acquire();
        return .{ .table_lease = table_lease, .socket = socket };
    }

    fn pushSocket(self: *WasiCliAdapter, s: Socket) !u32 {
        var socket = s;
        self.resource_id_mutex.lock();
        socket.resource_generation = self.next_socket_generation;
        self.next_socket_generation +%= 1;
        if (self.next_socket_generation == 0) self.next_socket_generation = 1;
        self.resource_id_mutex.unlock();
        return self.socket_table.publish(socket);
    }

    fn pushNetwork(self: *WasiCliAdapter, n: Network) !u32 {
        return self.network_table.publish(n);
    }

    /// Decode a wire handle into a `network_table` slot index, or null
    /// for out-of-range. Internal slot indices are 0-based; the canon
    /// ABI's `.own/.borrow` resource-handle offset (#520 wave 2) is
    /// applied at the lift/lower boundary in `canonical_abi.zig`, not
    /// here. Kept as a helper for the network-allow-list lookups.
    fn lookupNetworkSlot(self: *WasiCliAdapter, handle: u32) ?NetworkTable.Lease {
        return self.network_table.acquire(handle);
    }

    fn pushResolveStream(self: *WasiCliAdapter, s: *ResolveAddressStream) !u32 {
        return self.resolve_streams.publish(s);
    }

    fn pushUdpIncomingStream(self: *WasiCliAdapter, s: *UdpIncomingStream) !u32 {
        return self.udp_incoming_streams.publish(s);
    }

    fn lookupUdpIncomingStream(self: *WasiCliAdapter, h: u32) ?UdpIncomingStreamTable.Lease {
        return self.udp_incoming_streams.acquire(h);
    }

    fn lockUdpIncomingParent(
        self: *WasiCliAdapter,
        stream: *UdpIncomingStream,
    ) ?UdpParentSocketGuard {
        if (comptime build_options.lib_wasi_threads) {
            var parent = if (stream.parent_lease) |*lease| lease else return null;
            const socket = parent.value();
            socket.operation_claim.acquire();
            return .{ .socket = socket };
        }
        const lease = self.lookupSocket(stream.parent_handle) orelse return null;
        return .{ .socket = lease.socket, .owned_lease = lease };
    }

    fn pushUdpOutgoingStream(self: *WasiCliAdapter, s: *UdpOutgoingStream) !u32 {
        return self.udp_outgoing_streams.publish(s);
    }

    fn lookupUdpOutgoingStream(self: *WasiCliAdapter, h: u32) ?UdpOutgoingStreamTable.Lease {
        return self.udp_outgoing_streams.acquire(h);
    }

    fn lockUdpOutgoingParent(
        self: *WasiCliAdapter,
        stream: *UdpOutgoingStream,
    ) ?UdpParentSocketGuard {
        if (comptime build_options.lib_wasi_threads) {
            var parent = if (stream.parent_lease) |*lease| lease else return null;
            const socket = parent.value();
            socket.operation_claim.acquire();
            return .{ .socket = socket };
        }
        const lease = self.lookupSocket(stream.parent_handle) orelse return null;
        return .{ .socket = lease.socket, .owned_lease = lease };
    }

    /// Generic `(...) -> result<_, error-code>` access-denied stub. Used as
    /// the body of every default-deny socket method.
    fn socketDenyAccess(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        results[0] = try socketResultErr(allocator, .access_denied);
    }

    /// `(own<R>) -> ()` no-op resource drop that nulls the matching slot in
    /// the socket table.
    fn socketResourceDrop(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        self.closeSocketByHandle(handle);
    }

    /// Close and null out the `socket_table[handle]` slot if it holds a
    /// tcp / udp socket. Idempotent; safe to call on already-null or
    /// out-of-range slots. Used by both the
    /// `[resource-drop]{tcp,udp}-socket` host fn member (legacy path,
    /// only fires when the import is wired as a regular `canon.lower`)
    /// and the `ComponentInstance.on_resource_drop` synchronous hook
    /// (#575) — the latter is the path actually exercised by
    /// wit-bindgen-generated guests which lower `[resource-drop]X` to a
    /// `(canon resource.drop $T)` canon-builtin rather than a host fn
    /// import.
    fn closeSocketByHandle(self: *WasiCliAdapter, handle: u32) void {
        _ = self.socket_table.remove(handle);
    }

    /// Returns true if any other live socket in `socket_table` is
    /// already bound to (or listening on) an address that conflicts
    /// with `requested`. Conflict here mirrors the TCP/UDP wit-spec
    /// expectation surfaced by the
    /// `test_explicit_bind_addrinuse` fixtures: two non-listening
    /// bindings on the same port surface `AddressInUse`, regardless of
    /// whether the kernel would accept the bind under SO_REUSEADDR.
    ///
    /// Match rule:
    ///   - Skip the requesting socket itself (`exclude_handle`).
    ///   - Skip null / unbound slots.
    ///   - If the request carries `port = 0`, no conflict — the kernel
    ///     will hand out a fresh ephemeral port.
    ///   - Otherwise, conflict iff some other slot has the same family
    ///     and a `local_addr.port` equal to the requested port. We
    ///     deliberately ignore the IP byte string: localhost-only
    ///     fixtures bind to 127.0.0.1 / ::1 (or the wildcard), and the
    ///     kernel itself would treat `127.0.0.1:N` vs `INADDR_ANY:N`
    ///     as conflicting at the active-bind layer. Cross-family
    ///     mismatches (v4 vs v6) never conflict.
    const BindConflictCheck = enum {
        clear,
        conflict,
        busy,
    };

    fn bindWouldConflict(
        self: *WasiCliAdapter,
        requested: std.Io.net.IpAddress,
        exclude_handle: u32,
    ) BindConflictCheck {
        const req_port: u16 = switch (requested) {
            .ip4 => |v4| v4.port,
            .ip6 => |v6| v6.port,
        };
        if (req_port == 0) return .clear;
        const req_is_v4 = switch (requested) {
            .ip4 => true,
            .ip6 => false,
        };
        const handles = self.socket_table.snapshotHandles(self.allocator) catch return .busy;
        defer self.allocator.free(handles);
        for (handles) |handle| {
            if (handle == exclude_handle) continue;
            var table_lease = self.socket_table.acquire(handle) orelse continue;
            const socket = table_lease.value();
            if (!socket.operation_claim.tryAcquire()) {
                table_lease.release();
                return .busy;
            }
            const maybe_local = socket.local_addr;
            socket.operation_claim.release();
            table_lease.release();
            const la = maybe_local orelse continue;
            const la_port: u16 = switch (la) {
                .ip4 => |v4| v4.port,
                .ip6 => |v6| v6.port,
            };
            if (la_port != req_port) continue;
            const la_is_v4 = switch (la) {
                .ip4 => true,
                .ip6 => false,
            };
            if (la_is_v4 != req_is_v4) continue;
            return .conflict;
        }
        return .clear;
    }

    /// `ComponentInstance.on_resource_drop` hook (#575). Invoked from
    /// `dispatchCanonBuiltin.resource_drop` after every guest
    /// `canon resource.drop` so the adapter can release kernel-side
    /// state synchronously. The `handle` parameter is the canon-ABI
    /// **wire** value (rep + 1 — see
    /// `canonical_abi.encodeResourceWireAbi`) pushed by the guest
    /// before the canon op, so we decode it back to a rep before
    /// indexing into `socket_table`. WAMR's host fns return reps
    /// directly as wire handles (no `canon resource.new` wrapping),
    /// so `decodeResourceWireAbi` simply subtracts one. We restrict
    /// the cleanup to slots that hold a tcp / udp socket via
    /// `closeSocketByHandle` so a drop of a non-socket resource
    /// (network, descriptor, http resource, …) that shares a numeric
    /// value with a live socket slot leaves the socket untouched.
    fn onResourceDrop(
        ctx: ?*anyopaque,
        _: *ComponentInstance,
        _: u32,
        handle: u32,
    ) void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx.?));
        const rep = abi.decodeResourceWireAbi(handle);
        self.closeSocketByHandle(rep);
    }

    fn networkResourceDrop(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        _ = self.network_table.remove(handle);
    }

    /// `wasi:sockets/instance-network.instance-network: () -> own<network>`.
    /// Snapshots the adapter's CIDR allow-list template (#180) into the new
    /// Network. The snapshot is independent: subsequent
    /// `setSocketsAllowList` calls do not mutate already-issued Networks.
    fn instanceNetwork(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        const snapshot = try self.cloneSocketsAllowList();
        errdefer if (snapshot.len != 0) self.allocator.free(snapshot);
        const h = try self.pushNetwork(.{ .allow_list = snapshot });
        results[0] = .{ .handle = h };
    }

    /// `wasi:sockets/tcp-create-socket.create-tcp-socket:
    ///   (ip-address-family) -> result<own<tcp-socket>, error-code>`.
    fn createTcpSocket(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const fam_disc: u32 = switch (args[0]) {
            .enum_val => |d| d,
            .u32 => |d| d,
            .variant_val => |v| v.discriminant,
            else => return error.InvalidArgs,
        };
        const fam: IpAddressFamily = if (fam_disc == 0) .ipv4 else .ipv6;
        const h = try self.pushSocket(.{ .kind = .tcp, .family = fam });
        results[0] = try socketResultOk(allocator, .{ .handle = h });
    }

