    /// `[method]incoming-datagram-stream.receive:
    ///   (borrow<incoming-datagram-stream>, u64) ->
    ///     result<list<incoming-datagram>, error-code>` (#178).
    ///
    /// Non-blocking receive per WIT: never blocks, never returns
    /// `would-block`. Uses a zero-duration timeout; Timeout maps to
    /// "no data available, return list so far".
    fn incomingDatagramReceive(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const stream_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const max_results: u64 = switch (args[1]) {
            .u64 => |v| v,
            .u32 => |v| @as(u64, v),
            else => return error.InvalidArgs,
        };
        var in_stream_lease = self.lookupUdpIncomingStream(stream_handle) orelse {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        };
        defer in_stream_lease.release();
        const in_stream = in_stream_lease.value().*;
        var socket_guard = self.lockUdpIncomingParent(in_stream) orelse {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        };
        defer socket_guard.release();
        const s = socket_guard.value();
        // Generation check — stale stream.
        if (in_stream.generation != s.stream_generation) {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        }
        if (max_results == 0) {
            // WIT: max_results==0 → ok([]).
            results[0] = try socketResultOk(allocator, .{ .list = .{ .ptr = 0, .len = 0 } });
            return;
        }
        const host_socket = s.host_socket orelse {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        };
        const io = std.Io.Threaded.global_single_threaded.io();
        const cap: usize = @min(@as(usize, @intCast(@min(max_results, 16))), 16);
        var collected: std.ArrayListUnmanaged(InterfaceValue) = .empty;
        defer collected.deinit(allocator);
        var discard_budget: usize = 32;
        var buf: [65536]u8 = undefined;
        while (collected.items.len < cap and discard_budget > 0) {
            const msg = host_socket.receiveTimeout(io, &buf, .{
                .duration = .{ .raw = .{ .nanoseconds = 0 }, .clock = .awake },
            }) catch {
                // Zero-duration timeout: any error (Timeout on Linux,
                // WouldBlock/Canceled on Windows IOCP) means "no data
                // available." WIT mandates receive never blocks and
                // never returns would-block, so we stop accumulating.
                break;
            };
            // Connected-receive filtering: drop datagrams not from
            // the connected remote.
            if (in_stream.remote) |expected_remote| {
                const matches = switch (msg.from) {
                    .ip4 => |from_v4| switch (expected_remote) {
                        .ip4 => |exp_v4| std.mem.eql(u8, &from_v4.bytes, &exp_v4.bytes) and from_v4.port == exp_v4.port,
                        .ip6 => false,
                    },
                    .ip6 => |from_v6| switch (expected_remote) {
                        .ip6 => |exp_v6| std.mem.eql(u8, &from_v6.bytes, &exp_v6.bytes) and from_v6.port == exp_v6.port,
                        .ip4 => false,
                    },
                };
                if (!matches) {
                    discard_budget -= 1;
                    continue;
                }
            }
            // Build incoming-datagram record: { data: list<u8>, remote-address: ip-socket-address }.
            // Lower the data slice into guest memory directly so the
            // record value already carries the canonical `.list = PtrLen`
            // shape (issue #402).
            const data_ptr: u32 = if (msg.data.len == 0) 0 else (ci.hostAllocAndWrite(msg.data, 1) orelse return error.OutOfMemory);
            const remote_iv = try lowerIpSocketAddress(allocator, msg.from);
            const rec = try allocator.alloc(InterfaceValue, 2);
            rec[0] = .{ .list = .{ .ptr = data_ptr, .len = @intCast(msg.data.len) } };
            rec[1] = remote_iv;
            try collected.append(allocator, .{ .record_val = rec });
        }
        if (collected.items.len == 0) {
            results[0] = try socketResultOk(allocator, .{ .list = .{ .ptr = 0, .len = 0 } });
            return;
        }
        // Lower the outer `list<incoming-datagram>` into a single guest
        // buffer via storeValReg using the file-local socket type registry.
        const reg = socketTypeRegistry();
        const elem_t: ctypes.ValType = .{ .record = SOCKET_INCOMING_DG_RECORD_IDX };
        const elem_size = abi.sizeOfType(reg, elem_t);
        const elem_align = abi.alignOfType(reg, elem_t);
        const total = std.math.mul(u32, elem_size, @intCast(collected.items.len)) catch return error.OutOfMemory;
        const list_ptr = ci.hostAllocGuest(total, elem_align) orelse return error.OutOfMemory;
        const dst = ci.writableGuestBytes(list_ptr, total) orelse return error.OutOfMemory;
        var off: u32 = 0;
        for (collected.items) |dg_iv| {
            abi.storeValReg(dst, off, elem_t, dg_iv, reg) catch return error.InvalidArgs;
            off += elem_size;
        }
        // Free per-element host heap (record_val slices, variant payloads)
        // now that bytes are written into guest memory.
        for (collected.items) |dg_iv| dg_iv.deinit(allocator);
        results[0] = try socketResultOk(allocator, .{ .list = .{ .ptr = list_ptr, .len = @intCast(collected.items.len) } });
    }

    /// `[method]outgoing-datagram-stream.check-send:
    ///   (borrow<outgoing-datagram-stream>) -> result<u64, error-code>`
    /// (#178).
    fn outgoingCheckSend(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const stream_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var out_stream_lease = self.lookupUdpOutgoingStream(stream_handle) orelse {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        };
        defer out_stream_lease.release();
        const out_slot = out_stream_lease.lock();
        const out_stream = out_slot.*;
        const generation = out_stream.generation;
        out_stream_lease.unlock();
        var socket_guard = self.lockUdpOutgoingParent(out_stream) orelse {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        };
        defer socket_guard.release();
        const s = socket_guard.value();
        if (generation != s.stream_generation) {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        }
        out_stream_lease.lock().*.send_credit = 8;
        out_stream_lease.unlock();
        results[0] = try socketResultOk(allocator, .{ .u64 = 8 });
    }

    /// `[method]outgoing-datagram-stream.send:
    ///   (borrow<outgoing-datagram-stream>, list<outgoing-datagram>)
    ///     -> result<u64, error-code>` (#178).
    ///
    /// WIT-mandated invariants:
    ///  - Traps if `check-send` was not called first (send_credit == null).
    ///  - Traps if `datagrams.len > send_credit`.
    ///  - Partial-success: failure at index `i` returns `err` if i==0,
    ///    else `ok(i)`.
    fn outgoingSend(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const stream_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const datagrams_pl = switch (args[1]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        var out_stream_lease = self.lookupUdpOutgoingStream(stream_handle) orelse {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        };
        defer out_stream_lease.release();
        const out_slot = out_stream_lease.lock();
        const out_stream = out_slot.*;
        const credit = out_stream.send_credit orelse {
            out_stream_lease.unlock();
            return error.Trap;
        };
        if (datagrams_pl.len > credit) {
            out_stream_lease.unlock();
            return error.Trap;
        }
        out_stream.send_credit = null;
        const generation = out_stream.generation;
        const remote = out_stream.remote;
        out_stream_lease.unlock();

        var socket_guard = self.lockUdpOutgoingParent(out_stream) orelse {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        };
        defer socket_guard.release();
        const s = socket_guard.value();
        if (generation != s.stream_generation) {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        }

        if (datagrams_pl.len == 0) {
            results[0] = try socketResultOk(allocator, .{ .u64 = 0 });
            return;
        }

        // Lift the canonical `list<outgoing-datagram>` from guest memory
        // into a host slice of `.record_val` (#402). Inner `data: list<u8>`
        // remains a `.list = PtrLen` reference; we read its bytes from
        // the same memory below.
        const reg = socketTypeRegistry();
        const elem_t: ctypes.ValType = .{ .record = SOCKET_OUTGOING_DG_RECORD_IDX };
        const elem_size = abi.sizeOfType(reg, elem_t);
        // Resolve a contiguous byte view that covers all datagram records.
        // Prefer test_mem when active so unit tests don't require a real
        // canonical memory.
        const total_bytes: u32 = @as(u32, @intCast(datagrams_pl.len)) * elem_size;
        const list_bytes = ci.readGuestBytes(datagrams_pl.ptr, total_bytes) orelse {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        };
        const datagrams = try allocator.alloc(InterfaceValue, datagrams_pl.len);
        defer {
            for (datagrams) |d| d.deinit(allocator);
            allocator.free(datagrams);
        }
        for (0..datagrams_pl.len) |i| {
            const off = @as(u32, @intCast(i)) * elem_size;
            datagrams[i] = abi.loadValReg(list_bytes, off, elem_t, reg, allocator) catch {
                results[0] = try socketResultErr(allocator, .invalid_argument);
                return;
            };
        }

        const host_socket = s.host_socket orelse {
            results[0] = try socketResultErr(allocator, .invalid_state);
            return;
        };
        const io = std.Io.Threaded.global_single_threaded.io();

        var sent: u64 = 0;
        for (datagrams) |dg_iv| {
            const dg_fields = switch (dg_iv) {
                .record_val => |r| r,
                else => {
                    if (sent == 0) {
                        results[0] = try socketResultErr(allocator, .invalid_argument);
                        return;
                    }
                    results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                    return;
                },
            };
            // WIT outgoing-datagram: { data: list<u8>, remote-address: option<ip-socket-address> }
            if (dg_fields.len < 2) {
                if (sent == 0) {
                    results[0] = try socketResultErr(allocator, .invalid_argument);
                    return;
                }
                results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                return;
            }
            // Extract data bytes — `.list = PtrLen` after loadValReg.
            const data_pl = switch (dg_fields[0]) {
                .list => |pl| pl,
                else => {
                    if (sent == 0) {
                        results[0] = try socketResultErr(allocator, .invalid_argument);
                        return;
                    }
                    results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                    return;
                },
            };
            const data_buf = if (data_pl.len == 0)
                try allocator.alloc(u8, 0)
            else blk: {
                const src = ci.readGuestBytes(data_pl.ptr, data_pl.len) orelse {
                    if (sent == 0) {
                        results[0] = try socketResultErr(allocator, .invalid_argument);
                        return;
                    }
                    results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                    return;
                };
                break :blk try allocator.dupe(u8, src);
            };
            defer allocator.free(data_buf);

            // Determine destination address.
            var dest: std.Io.net.IpAddress = undefined;
            var has_per_dg_remote = false;
            switch (dg_fields[1]) {
                .variant_val => |v| {
                    if (v.discriminant == 1) {
                        if (v.payload) |p| {
                            dest = liftIpSocketAddress(p.*, s.family) catch {
                                if (sent == 0) {
                                    results[0] = try socketResultErr(allocator, .invalid_argument);
                                    return;
                                }
                                results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                                return;
                            };
                            has_per_dg_remote = true;
                        }
                    }
                },
                .option_val => |opt| {
                    if (opt.payload) |p| {
                        dest = liftIpSocketAddress(p.*, s.family) catch {
                            if (sent == 0) {
                                results[0] = try socketResultErr(allocator, .invalid_argument);
                                return;
                            }
                            results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                            return;
                        };
                        has_per_dg_remote = true;
                    }
                },
                else => {},
            }

            if (remote != null) {
                // Connected mode: per-datagram remote must be none
                // or exactly equal to the connected remote.
                if (has_per_dg_remote) {
                    const matches = switch (dest) {
                        .ip4 => |dv4| switch (remote.?) {
                            .ip4 => |rv4| std.mem.eql(u8, &dv4.bytes, &rv4.bytes) and dv4.port == rv4.port,
                            .ip6 => false,
                        },
                        .ip6 => |dv6| switch (remote.?) {
                            .ip6 => |rv6| std.mem.eql(u8, &dv6.bytes, &rv6.bytes) and dv6.port == rv6.port,
                            .ip4 => false,
                        },
                    };
                    if (!matches) {
                        if (sent == 0) {
                            results[0] = try socketResultErr(allocator, .invalid_argument);
                            return;
                        }
                        results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                        return;
                    }
                }
                dest = remote.?;
            } else {
                // Unconnected mode: per-datagram remote is required.
                if (!has_per_dg_remote) {
                    if (sent == 0) {
                        results[0] = try socketResultErr(allocator, .invalid_argument);
                        return;
                    }
                    results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                    return;
                }
                // Validate the per-datagram remote.
                if (validateRemoteForSend(dest, s.family)) |code| {
                    if (sent == 0) {
                        results[0] = try socketResultErr(allocator, code);
                        return;
                    }
                    results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                    return;
                }
                // Allow-list check.
                if (s.allow_list.len > 0) {
                    var allowed = false;
                    for (s.allow_list) |c| {
                        if (c.containsAddr(dest)) {
                            allowed = true;
                            break;
                        }
                    }
                    if (!allowed) {
                        if (sent == 0) {
                            results[0] = try socketResultErr(allocator, .access_denied);
                            return;
                        }
                        results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                        return;
                    }
                } else {
                    if (sent == 0) {
                        results[0] = try socketResultErr(allocator, .access_denied);
                        return;
                    }
                    results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                    return;
                }
            }

            // Actual send.
            host_socket.send(io, &dest, data_buf) catch |err| {
                if (sent == 0) {
                    results[0] = try socketResultErr(allocator, mapSocketSendError(err));
                    return;
                }
                results[0] = try socketResultOk(allocator, .{ .u64 = sent });
                return;
            };
            sent += 1;
        }
        results[0] = try socketResultOk(allocator, .{ .u64 = sent });
    }

    /// `[resource-drop]incoming-datagram-stream` (#178).
    fn udpIncomingStreamDrop(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        _ = self.udp_incoming_streams.remove(handle);
    }

