    // ===== wasi:sockets@0.3.0 (#486) =====

    // The 0.3.0 surface collapses the six 0.2 socket interfaces into
    // two: `wasi:sockets/types@0.3.0-*` (every tcp-socket and udp-socket
    // method plus the static constructors) and
    // `wasi:sockets/ip-name-lookup@0.3.0-*` (a single async
    // `resolve-addresses` call). Key 0.3 changes:
    //
    //  - The `network` / `instance-network` resources are gone:
    //    `bind` / `connect` no longer take a network handle.
    //  - The TCP `start-X` / `finish-X` lifecycle pairs collapse to
    //    single calls (`bind` is sync; `connect` is `async func`).
    //  - `tcp-socket.listen` returns `stream<tcp-socket>` instead of
    //    being a 2-phase `start-listen` + `finish-listen` + `accept`.
    //  - `tcp-socket.send` / `receive` move from sibling `wasi:io`
    //    streams to a `stream<u8>` + `future<result<_, error-code>>`
    //    pair.
    //  - `udp-socket` adds `connect` / `disconnect`; `send` / `receive`
    //    are `async func` that take/return raw byte lists rather than
    //    `incoming-datagram-stream` / `outgoing-datagram-stream`
    //    sub-resources.
    //  - All getters are renamed with a `get-` prefix
    //    (`local-address` → `get-local-address`, etc.).
    //  - `subscribe` and `shutdown` are gone (no pollables in 0.3).
    //  - `resolve-addresses` returns `list<ip-address>` directly via
    //    an async subtask — no `resolve-address-stream` sub-resource.
    //
    // Sync ops (bind, getters, setters, static constructors,
    // udp-socket.connect/disconnect, resource-drop) are wired through
    // to real implementations: `bind` uses the adapter-level
    // `sockets_allow_list_template` directly (since there is no
    // network rep), getters/setters reuse the existing 0.2 callbacks
    // unchanged, and the static constructors wrap `pushSocket` like
    // the 0.2 `create-tcp-socket` / `create-udp-socket` did. Async
    // / stream ops (`tcp-socket.connect` / `listen` / `send` /
    // `receive`, `udp-socket.send` / `receive`,
    // `ip-name-lookup.resolve-addresses`) require host integration
    // with the canonical-ABI subtask + stream/future runtime
    // (#478/#502/#505) which the adapter does not yet drive end to
    // end. Those bindings exist (so guests linking against the 0.3
    // surface satisfy their imports) and return
    // `error-code.access-denied` synchronously, matching the
    // default-deny posture of the 0.2 surface when no allow-list /
    // network capability has been provisioned.

    /// `[static]tcp-socket.create: (ip-address-family) ->
    ///   result<tcp-socket, error-code>`. Same body as the 0.2
    /// `create-tcp-socket` callback — only the WIT key differs.
    fn tcpCreateP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        return createTcpSocket(ctx_opaque, ci, args, results, allocator);
    }

    /// `[static]udp-socket.create: (ip-address-family) ->
    ///   result<udp-socket, error-code>`.
    fn udpCreateP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        return createUdpSocket(ctx_opaque, ci, args, results, allocator);
    }

    /// `[method]tcp-socket.bind: (borrow<tcp-socket>, ip-socket-address)
    ///   -> result<_, error-code>` (#486, #563).
    ///
    /// Collapses 0.2 `start-bind` + `finish-bind` into one synchronous
    /// call and drops the `borrow<network>` parameter — 0.3 has no
    /// network resource. Allow-list checking consults the adapter-level
    /// `sockets_allow_list_template` directly.
    ///
    /// 0.3 semantics (#563):
    ///   - Multicast / broadcast / IPv4-mapped-IPv6 addresses are
    ///     rejected with `invalid-argument` via `isUnicastAddress`.
    ///   - The kernel `bind(2)` is performed eagerly so a request for
    ///     port=0 returns an ephemeral assignment that `local-address`
    ///     can read back. The bound `host_socket` is held on the rep so
    ///     `tcpListenP3` can transition it to listening in-place
    ///     instead of opening a fresh fd.
    fn tcpBindP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const sock_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var s_lease = self.lookupSocket(sock_handle) orelse {
            results[0] = try socketResultErrP3(allocator, .invalid_state);
            return;
        };
        defer s_lease.release();
        const s = s_lease.value();
        if (s.kind != .tcp or s.state != .unbound) {
            results[0] = try socketResultErrP3(allocator, .invalid_state);
            return;
        }
        const local = liftIpSocketAddress(args[1], s.family) catch |err| switch (err) {
            error.FamilyMismatch => {
                results[0] = try socketResultErrP3(allocator, .invalid_argument);
                return;
            },
            error.InvalidArgs => return error.InvalidArgs,
        };
        if (!isUnicastAddress(local)) {
            results[0] = try socketResultErrP3(allocator, .invalid_argument);
            return;
        }
        // Userspace bind-conflict check: refuse a bind that would
        // collide with another live socket's `local_addr` in the same
        // adapter. Required to preserve the
        // `sockets-tcp-connect::test_explicit_bind_addrinuse` /
        // `sockets-udp-connect::test_explicit_bind_addrinuse`
        // semantics on Linux: the kernel `SO_REUSEADDR` we set in
        // `bindAndGetsockname` would otherwise let two non-listening
        // bindings coexist on the same port, swallowing the
        // `AddressInUse` the fixture expects. Sockets dropped by the
        // guest are removed by the `ComponentInstance.on_resource_drop`
        // hook (#575), so this check only matches live resources;
        // `sockets-tcp-bind::test_reuseaddr`'s rebind after the
        // server resource drops still succeeds. (#575)
        switch (self.bindWouldConflict(local, sock_handle)) {
            .clear => {},
            .conflict => {
                results[0] = try socketResultErrP3WithDiag(
                    ci,
                    allocator,
                    .address_in_use,
                    "address_in_use",
                );
                return;
            },
            .busy => {
                results[0] = try socketResultErrP3(
                    allocator,
                    .concurrency_conflict,
                );
                return;
            },
        }
        // 0.3 dropped the per-network allow-list at bind: the kernel
        // already enforces what's bindable (returns AddressNotBindable
        // for RFC 5737 test addresses, etc.) and the capability model
        // is enforced on the outbound `connect` / `send` paths instead
        // via `templateAllows`. Skipping the allow-list here matches
        // the wasi-p3-testsuite `test_not_bindable` expectation, which
        // expects `address-not-bindable` from the kernel rather than
        // a pre-syscall `access-denied`. (#563, #583 A1)
        // Real kernel bind so port=0 yields ephemeral assignment and
        // `local-address` returns the kernel-chosen port. The bound
        // fd is held on the rep — `tcpListenP3` transitions it to
        // listening in-place via `listenOnBoundFd` (POSIX) or, on
        // Windows, closes it and re-opens via `IpAddress.listen` with
        // the now-known address. (#563)
        //
        // SO_REUSEADDR is set on the fresh fd BEFORE bind so a
        // subsequent bind to the same port while it's in TIME_WAIT
        // succeeds — required by the 0.3 spec and exercised by
        // `sockets-tcp-bind::test_reuseaddr`. (#569, #575)
        const host_socket = bindAndGetsockname(local, .stream, .tcp) catch |err| {
            results[0] = try socketResultErrP3WithDiag(ci, allocator, mapSocketBindError(err), @errorName(err));
            return;
        };
        s.host_socket = host_socket;
        s.local_addr = host_socket.address;
        s.state = .bound;
        results[0] = try socketResultOk(allocator, .{ .tuple_val = &.{} });
    }

    /// `[method]udp-socket.bind: (borrow<udp-socket>, ip-socket-address)
    ///   -> result<_, error-code>` (#486, #563). 0.3 collapses the 0.2
    /// start/finish pair and drops the network handle. Multicast and
    /// broadcast addresses are rejected with `invalid-argument`; the
    /// kernel bind is performed eagerly so `local-address` observes
    /// the ephemeral port when port=0 was requested.
    fn udpBindP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const sock_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var s_lease = self.lookupSocket(sock_handle) orelse {
            results[0] = try socketResultErrP3(allocator, .invalid_state);
            return;
        };
        defer s_lease.release();
        const s = s_lease.value();
        if (s.kind != .udp or s.state != .unbound) {
            results[0] = try socketResultErrP3(allocator, .invalid_state);
            return;
        }
        const local = liftIpSocketAddress(args[1], s.family) catch |err| switch (err) {
            error.FamilyMismatch => {
                results[0] = try socketResultErrP3(allocator, .invalid_argument);
                return;
            },
            error.InvalidArgs => return error.InvalidArgs,
        };
        if (!isUnicastAddress(local)) {
            results[0] = try socketResultErrP3(allocator, .invalid_argument);
            return;
        }
        // Userspace bind-conflict check (#575) — see `tcpBindP3` for
        // the rationale: SO_REUSEADDR on Linux otherwise lets two
        // non-listening bindings coexist, breaking the
        // `sockets-udp-connect::test_explicit_bind_addrinuse` case.
        switch (self.bindWouldConflict(local, sock_handle)) {
            .clear => {},
            .conflict => {
                results[0] = try socketResultErrP3WithDiag(
                    ci,
                    allocator,
                    .address_in_use,
                    "address_in_use",
                );
                return;
            },
            .busy => {
                results[0] = try socketResultErrP3(
                    allocator,
                    .concurrency_conflict,
                );
                return;
            },
        }
        // See `tcpBindP3` (#563, #583 A1): no allow-list at bind in 0.3.
        // SO_REUSEADDR preset so a subsequent UDP bind to a port
        // that just transitioned through `disconnect`/drop succeeds —
        // mirrors the TCP path so cross-family behavior is consistent. (#569, #575)
        const host_socket = bindAndGetsockname(local, .dgram, .udp) catch |err| {
            results[0] = try socketResultErrP3WithDiag(ci, allocator, mapSocketBindError(err), @errorName(err));
            return;
        };
        s.host_socket = host_socket;
        s.local_addr = host_socket.address;
        s.state = .bound;
        results[0] = try socketResultOk(allocator, .{ .tuple_val = &.{} });
    }

    /// `[method]udp-socket.connect: (borrow<udp-socket>,
    ///   ip-socket-address) -> result<_, error-code>` (#486, #563).
    /// 0.3-only. Records the remote address; subsequent `send` calls
    /// use it as the implicit destination. Multicast / broadcast /
    /// wildcard-with-non-zero-port are rejected with `invalid-argument`
    /// per the WIT contract.
    fn udpConnectP3(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const sock_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var s_lease = self.lookupSocket(sock_handle) orelse {
            results[0] = try socketResultErrP3(allocator, .invalid_state);
            return;
        };
        defer s_lease.release();
        const s = s_lease.value();
        if (s.kind != .udp) {
            results[0] = try socketResultErrP3(allocator, .invalid_state);
            return;
        }
        const remote = liftIpSocketAddress(args[1], s.family) catch |err| switch (err) {
            error.FamilyMismatch => {
                results[0] = try socketResultErrP3(allocator, .invalid_argument);
                return;
            },
            error.InvalidArgs => return error.InvalidArgs,
        };
        if (!isUnicastAddress(remote)) {
            results[0] = try socketResultErrP3(allocator, .invalid_argument);
            return;
        }
        // Connect requires a fully-specified unicast remote: an
        // unspecified address (`0.0.0.0` / `::`) and / or port=0 are
        // both `invalid-argument` per the 0.3 WIT spec
        // (`sockets-udp-connect.rs` `test_unspecified_remote_addr` /
        // `test_connect_0_port`). (#563)
        if (socketAddrIsUnspecified(remote) or socketPort(remote) == 0) {
            results[0] = try socketResultErrP3(allocator, .invalid_argument);
            return;
        }
        // Allow-list gate (#583 A1). Empty template = allow-all; a
        // non-empty template must contain the remote address or this
        // returns `access-denied` before the kernel `connect(2)`.
        if (!self.templateAllowsAddress(remote)) {
            results[0] = try socketResultErrP3(allocator, .access_denied);
            return;
        }
        // Implicit bind: 0.3 WIT requires `connect` on an unbound UDP
        // socket to bind to a kernel-chosen ephemeral port before
        // recording the remote. `sockets-udp-connect::test_implicit_bind`
        // then reads `get-local-address` and expects a non-zero port.
        // (#569)
        if (s.host_socket == null) {
            const wildcard: std.Io.net.IpAddress = switch (s.family) {
                .ipv4 => .{ .ip4 = .{ .bytes = .{ 0, 0, 0, 0 }, .port = 0 } },
                .ipv6 => .{ .ip6 = .{ .bytes = [_]u8{0} ** 16, .port = 0, .flow = 0 } },
            };
            const host_socket = bindAndGetsockname(wildcard, .dgram, .udp) catch |err| {
                results[0] = try socketResultErrP3(allocator, mapSocketBindError(err));
                return;
            };
            s.host_socket = host_socket;
            s.local_addr = host_socket.address;
            s.state = .bound;
        }
        // Real kernel `connect(2)` on the UDP socket so the kernel's
        // routing table can refine `local_addr` from the wildcard to
        // the actual outbound interface IP (e.g. `0.0.0.0` →
        // `127.0.0.1` when the remote is loopback). The
        // `sockets-udp-connect::test_implicit_bind` fixture asserts
        // `local_addr.ip_addr() == remote.ip_addr()` after connect.
        // POSIX-only — Windows leaves `local_addr` as the wildcard;
        // the cross-compile sweep stays green because the WIT spec
        // doesn't require an interface-refined local-addr post-connect.
        // (#569)
        if (@import("builtin").os.tag != .windows) {
            connectUdpKernel(s.host_socket.?.handle, remote) catch |err| {
                results[0] = try socketResultErrP3(allocator, mapConnectError(err));
                return;
            };
            // Refresh local_addr from getsockname now that the kernel
            // has resolved the outbound interface.
            if (getsocknameKernel(s.host_socket.?.handle, s.family)) |refreshed| {
                s.local_addr = refreshed;
                s.host_socket.?.address = refreshed;
            }
        }
        s.remote_addr = remote;
        results[0] = try socketResultOk(allocator, .{ .tuple_val = &.{} });
    }

    /// `[method]udp-socket.disconnect: (borrow<udp-socket>) ->
    ///   result<_, error-code>` (#486). Clears the remote address set by
    /// a prior `connect`.
    fn udpDisconnectP3(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const sock_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var s_lease = self.lookupSocket(sock_handle) orelse {
            results[0] = try socketResultErrP3(allocator, .invalid_state);
            return;
        };
        defer s_lease.release();
        const s = s_lease.value();
        if (s.kind != .udp or s.remote_addr == null) {
            results[0] = try socketResultErrP3(allocator, .invalid_state);
            return;
        }
        s.remote_addr = null;
        results[0] = try socketResultOk(allocator, .{ .tuple_val = &.{} });
    }

    /// Default-deny placeholder for 0.3 async sockets methods, retained
    /// for callers that still want a synchronous `access_denied` rejection
    /// (test fixtures, host-fn smoke tests). Production bindings replace
    /// this with the real I/O wrappers below.
    fn socketsP3AccessDenied(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        if (results.len == 0) return error.InvalidArgs;
        results[0] = try socketResultErr(allocator, .access_denied);
    }

    /// Adapter-level allow-list match for the 0.3 sockets path. The 0.2
    /// surface still consults a per-`network` allow-list snapshot via
    /// `Network.allows()`; 0.3 dropped the `network` resource so this
    /// helper reads the adapter-level template directly. (#583 A1)
    ///
    /// Semantics:
    ///   * Empty template → allow-all. The embedder has not opted into
    ///     a capability restriction, so kernel I/O is unrestricted (the
    ///     kernel still enforces routability / bindability separately).
    ///   * Non-empty template → only addresses contained in at least
    ///     one CIDR are permitted; everything else returns
    ///     `error-code::access-denied` before the syscall.
    ///
    /// Discrete service surfaces (`resolveAddressesP3`,
    /// `httpOutgoingHandlerHandle`, the 0.3 HTTP client) still gate
    /// "empty template = deny-all" explicitly — DNS and outbound HTTP
    /// require an explicit opt-in even when raw sockets are
    /// unrestricted.
    fn templateAllows(template: []const IpCidr, addr: std.Io.net.IpAddress) bool {
        if (template.len == 0) return true;
        for (template) |cidr| if (cidr.containsAddr(addr)) return true;
        return false;
    }

    // ── 0.3 async-future encoding helpers ────────────────────────────────
    //
    // The 0.3 socket bindings deliver their results through `Future`
    // entries in `ci.futures`. The executor's `future_read` rendezvous
    // (#502) consumes `Future.payload` directly: a writer that buffered
    // bytes ahead of the reader gets memcpy'd straight into the guest's
    // destination pointer. We pre-encode the canonical-ABI layout for
    // each 0.3 sockets async-return shape (`SocketsP3AsyncReturn`) here
    // so the host-side I/O can deliver a settled future without driving
    // a real subtask. Routing through the type registry (#564 wave) is
    // essential — the 0.3 `error-code` is a `variant` carrying an
    // `other(option<string>)` arm (NOT the flat 0.2 enum), so a naive
    // 2-byte `[disc, code]` payload underwrites the destination by 18
    // bytes and writes the err code at the wrong offset (payload offset
    // is alignUp(1, 4) = 4, NOT 1). (#569)

    /// Build a `result_val` InterfaceValue for the requested
    /// `is_ok` / `code` combination, suitable for feeding into
    /// `socketsP3LowerAsyncPayload`. The caller owns the returned
    /// `InterfaceValue` tree and must `deinit` it after lowering.
    fn socketsP3BuildUnitErrResultIv(
        allocator: Allocator,
        is_ok: bool,
        code: SocketErrorCode,
    ) !InterfaceValue {
        if (is_ok) {
            return InterfaceValue{ .result_val = .{ .is_ok = true, .payload = null } };
        }
        const disc = socketCodeToP3Disc(code);
        var err_arm_payload: ?*InterfaceValue = null;
        if (disc == SOCKETS_P3_ERROR_OTHER_DISC) {
            // Arm 14 is `other(option<string>)`. Emit `other(none)` so
            // the lowering visits the option discriminant byte at the
            // right offset (a `payload=null` here would leave the inner
            // option's `is_some` byte unwritten — fine since we
            // @memset(buf, 0) the buffer first, but explicit is safer).
            const opt_iv = try allocator.create(InterfaceValue);
            opt_iv.* = .{ .option_val = .{ .is_some = false, .payload = null } };
            err_arm_payload = opt_iv;
        }
        const err_iv = try allocator.create(InterfaceValue);
        err_iv.* = .{ .variant_val = .{ .discriminant = disc, .payload = err_arm_payload } };
        return InterfaceValue{ .result_val = .{ .is_ok = false, .payload = err_iv } };
    }

    /// Allocate a settled `future<result<_, error-code>>` whose payload
    /// is the canonical-ABI byte layout for the requested outcome.
    /// Routes through `socketsP3LowerAsyncPayload` with the `.unit_err`
    /// kind so the buffer is sized for the full 0.3 `result<_, error-
    /// code>` envelope (20 bytes: disc(1) + pad(3) + error-code variant
    /// (16)) with the 0.3 variant discriminant numbering. (#569)
    fn socketReadyResultFuture(
        ci: *ComponentInstance,
        is_ok: bool,
        code: SocketErrorCode,
    ) !u32 {
        return socketReadyAsyncErrFuture(ci, .unit_err, is_ok, code);
    }

    /// Generalised settled-future builder for any
    /// `SocketsP3AsyncReturn` shape. `is_ok` only meaningfully selects
    /// between the ok arm (returns the shape's default ok payload)
    /// and the err arm with `code`; callers that need a populated ok
    /// arm (e.g. udp-receive's ok tuple) should build the value
    /// directly and use `socketsP3LowerAsyncPayload` + `spawnReadyFutureBytes`.
    fn socketReadyAsyncErrFuture(
        ci: *ComponentInstance,
        kind: SocketsP3AsyncReturn,
        is_ok: bool,
        code: SocketErrorCode,
    ) !u32 {
        const val = try socketsP3BuildUnitErrResultIv(ci.allocator, is_ok, code);
        defer val.deinit(ci.allocator);
        const payload_bytes = try socketsP3LowerAsyncPayload(ci.allocator, kind, val);
        const h = ci.allocAsyncHandle();
        ci.futures.put(ci.allocator, h, .{
            .elem_type_idx = 0,
            .payload = payload_bytes,
            .state = .ready,
            .write_closed = true,
        }) catch |err| {
            ci.allocator.free(payload_bytes);
            return err;
        };
        return h;
    }

    /// Allocate a settled future whose `state = .ready` and `payload = null`.
    /// The executor's unit-type fast-path (#487) returns "returned, 1
    /// element" without writing to the destination — guests reading this
    /// observe whatever bytes happen to live in the destination slot
    /// (typically zeroed by the canonical-ABI realloc path on first use).
    /// Used for result types whose ok-arm carries data the wave-D
    /// canon-lower-of-async-func follow-up will lift end-to-end.
    fn socketReadyUnitFuture(ci: *ComponentInstance) !u32 {
        const h = ci.allocAsyncHandle();
        try ci.futures.put(ci.allocator, h, .{
            .elem_type_idx = 0,
            .state = .ready,
            .write_closed = true,
        });
        return h;
    }

    /// Allocate a settled future whose `payload` carries the canonical-
    /// ABI bytes for a `result<T, error-code>` shape. Ownership of
    /// `payload_bytes` transfers to the future slot — the executor frees
    /// it after the guest's `future_read` rendezvous. (#535)
    fn spawnReadyFutureBytes(ci: *ComponentInstance, payload_bytes: []u8) !u32 {
        const h = ci.allocAsyncHandle();
        ci.futures.put(ci.allocator, h, .{
            .elem_type_idx = 0,
            .payload = payload_bytes,
            .state = .ready,
            .write_closed = true,
        }) catch |err| {
            ci.allocator.free(payload_bytes);
            return err;
        };
        return h;
    }

    /// Settle a previously-`.pending` future deferred-completion style:
    /// write the just-lowered `payload_bytes` to the trampoline's
    /// stashed `async_lower_retptr` (so the guest observes the result
    /// where it expects to read it), pin the bytes on the future slot
    /// for drop-time freeing, transition `state = .ready`, and fire
    /// the WaitableSet wakeup the guest will see on its next
    /// `waitable-set.{wait,poll}`. Mirrors the timer-future settle
    /// path in `completeDueTimerFutures` but with payload copy out
    /// for the async-with-result shape. (#576)
    fn settleFutureDeferred(
        ci: *ComponentInstance,
        future_handle: u32,
        payload_bytes: []u8,
        allocator: Allocator,
    ) void {
        var future_lease = ci.futures.acquire(future_handle) orelse {
            ci.allocator.free(payload_bytes);
            return;
        };
        const fut = future_lease.value();
        if (fut.async_lower_retptr) |retptr| {
            if (ci.writableGuestBytes(retptr, @intCast(payload_bytes.len))) |dst| {
                @memcpy(dst, payload_bytes);
            }
        }
        if (fut.payload) |old| ci.allocator.free(old);
        fut.payload = payload_bytes;
        fut.state = .ready;
        fut.write_closed = true;
        const registration = fut.read_waitable;
        const code: u32 = if (fut.subtask_managed)
            executor_root.STATUS_RETURNED
        else
            async_canon.packStatus(.completed, 0);
        future_lease.release();
        _ = allocator;
        _ = ci.notifyWaitable(registration, code);
    }

    fn closeFutureAfterSettleFailure(
        ci: *ComponentInstance,
        future_handle: u32,
    ) void {
        var future_lease = ci.futures.acquire(future_handle) orelse return;
        const future = future_lease.value();
        future.state = .ready;
        future.write_closed = true;
        future_lease.release();
    }

    /// Lower a slice of `std.Io.net.IpAddress` values into a contiguous
    /// canonical-ABI `list<ip-address>` block in guest memory. Returns
    /// the guest pointer at the start of the block; the caller pairs it
    /// with `addrs.len` to produce the `.list{.ptr, .len}` InterfaceValue
    /// the future-payload lowering consumes. (#535)
    fn socketsP3LowerIpAddressList(
        ci: *ComponentInstance,
        addrs: []const std.Io.net.IpAddress,
    ) !u32 {
        const reg = socketsP3TypeRegistry();
        const elem_t: ctypes.ValType = .{ .variant = SOCKETS_P3_IP_ADDRESS_VARIANT_IDX };
        const elem_size = abi.sizeOfType(reg, elem_t);
        const elem_align = abi.alignOfType(reg, elem_t);
        if (addrs.len == 0) return 0;
        const total = std.math.mul(u32, elem_size, @intCast(addrs.len)) catch return error.OutOfMemory;
        const list_ptr = ci.hostAllocGuest(total, elem_align) orelse return error.OutOfMemory;
        const dst = ci.writableGuestBytes(list_ptr, total) orelse return error.OutOfMemory;
        @memset(dst, 0);
        var off: u32 = 0;
        for (addrs) |a| {
            const iv = try lowerIpAddress(ci.allocator, a);
            defer iv.deinit(ci.allocator);
            abi.storeValReg(dst, off, elem_t, iv, reg) catch return error.LowerError;
            off += elem_size;
        }
        return list_ptr;
    }

    /// Lower a single `std.Io.net.IpAddress` + datagram payload into the
    /// canonical-ABI `tuple<list<u8>, ip-socket-address>` block in guest
    /// memory. Returns the guest pointer at the start of the block;
    /// caller wraps it in `.list{.ptr, .len}` if the canonical lowering
    /// needs an outer pointer. (#535)
    fn socketsP3LowerUdpReceivePayload(
        ci: *ComponentInstance,
        bytes: []const u8,
        remote: std.Io.net.IpAddress,
    ) !InterfaceValue {
        // Stage the data list bytes inside guest memory (so the canonical
        // `list<u8>` lowering can store the (ptr, len) reference).
        const data_ptr: u32 = if (bytes.len == 0)
            0
        else
            (ci.hostAllocAndWrite(bytes, 1) orelse return error.OutOfMemory);
        const data_iv = InterfaceValue{ .list = .{ .ptr = data_ptr, .len = @intCast(bytes.len) } };
        const remote_iv = try lowerIpSocketAddress(ci.allocator, remote);
        const fields = try ci.allocator.alloc(InterfaceValue, 2);
        fields[0] = data_iv;
        fields[1] = remote_iv;
        return .{ .tuple_val = fields };
    }

    /// Allocate a fresh `stream<u8>` slot. Pre-buffers `bytes` (may be
    /// empty) and marks the writable end closed when `eof` is true so a
    /// subsequent `stream.read` observes EOF after the FIFO drains.
    fn socketAllocByteStream(
        ci: *ComponentInstance,
        bytes: []const u8,
        eof: bool,
    ) !u32 {
        var slot: async_mod.AsyncStream = .{
            .elem_type_idx = 0,
            .state = .open,
            .read_closed = false,
            .write_closed = eof,
        };
        errdefer slot.deinit(ci.allocator);
        if (bytes.len > 0) try slot.buffer.appendSlice(ci.allocator, bytes);
        const h = ci.allocAsyncHandle();
        try ci.streams.put(ci.allocator, h, slot);
        return h;
    }

    // ── 0.3 sockets host stream drivers (#535) ──────────────────────────
    //
    // The 0.3 surface returns `stream<u8>` (tcp.receive / tcp.send) and
    // `stream<tcp-socket>` (tcp.listen) handles to the guest. The single-
    // shot host fn (#519) buffered at most one syscall worth of data into
    // the FIFO before returning. The 0.3 spec demands continuous I/O —
    // every `stream.read` should be able to drain new bytes off the fd,
    // every `stream.write` should push to the fd, every `accept(2)` on
    // the listener should land on the stream FIFO.
    //
    // We implement this by installing an `async_mod.HostStreamDriver` on
    // each socket-backed stream slot. The executor's `stream.read` /
    // `stream.write` paths invoke the driver before parking / buffering
    // so a long-lived host fd can keep the FIFO fed without a per-call
    // host fn dispatch (mirrors the filesystem `descriptor.read` /
    // `descriptor.write` continuous-stream pattern from #522 / PR #528).

    /// Allocate a long-lived driver context owned by the adapter. The
    /// returned pointer stays valid until adapter `deinit`.
    fn allocSocketsP3StreamCtx(
        self: *WasiCliAdapter,
        socket_handle: ?u32,
        fd: std.posix.fd_t,
        family: IpAddressFamily,
    ) !*SocketsP3StreamCtx {
        const ctx = try self.allocator.create(SocketsP3StreamCtx);
        ctx.* = .{
            .adapter = self,
            .socket_handle = socket_handle,
            .fd = fd,
            .family = family,
        };
        if (comptime build_options.lib_wasi_threads) {
            const published = self.sockets_p3_stream_ctxs.publishLeased(ctx) catch {
                self.allocator.destroy(ctx);
                return error.OutOfMemory;
            };
            ctx.registry_handle = published.handle;
            ctx.self_lease = published.lease;
        } else {
            ctx.registry_handle = self.sockets_p3_stream_ctxs.publish(ctx) catch {
                self.allocator.destroy(ctx);
                return error.OutOfMemory;
            };
        }
        return ctx;
    }

    fn socketsP3StreamCtxOnDestroy(opaque_ctx: ?*anyopaque) void {
        const ctx: *SocketsP3StreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        if (comptime build_options.lib_wasi_threads) {
            var lease = ctx.self_lease orelse return;
            ctx.self_lease = null;
            _ = ctx.adapter.sockets_p3_stream_ctxs.remove(ctx.registry_handle);
            lease.release();
        } else {
            _ = ctx.adapter.sockets_p3_stream_ctxs.remove(ctx.registry_handle);
        }
    }

    fn fsWriteStreamCtxOnDestroy(opaque_ctx: ?*anyopaque) void {
        const ctx: *FsWriteStreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        if (comptime build_options.lib_wasi_threads) {
            var lease = ctx.self_lease orelse return;
            ctx.self_lease = null;
            _ = ctx.adapter.fs_write_stream_ctxs.remove(ctx.registry_handle);
            lease.release();
        } else {
            _ = ctx.adapter.fs_write_stream_ctxs.remove(ctx.registry_handle);
        }
    }

    fn fsReadStreamCtxOnDestroy(opaque_ctx: ?*anyopaque) void {
        const ctx: *FsReadStreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        if (comptime build_options.lib_wasi_threads) {
            var lease = ctx.self_lease orelse return;
            ctx.self_lease = null;
            _ = ctx.adapter.fs_read_stream_ctxs.remove(ctx.registry_handle);
            lease.release();
        } else {
            _ = ctx.adapter.fs_read_stream_ctxs.remove(ctx.registry_handle);
        }
    }

    /// `host_driver.on_read` for a TCP-receive `stream<u8>` slot. Reads
    /// up to 64 KiB from the connected fd non-blockingly and appends the
    /// bytes to the FIFO. Returns `.progressed` on byte append, `.eof`
    /// when the peer closed the fd, `.would_block` when no data is
    /// available yet.
    ///
    /// Retained as a fallback for the zero-copy `on_read_into` variant
    /// below: the executor reaches this path when the guest destination
    /// can't be addressed as a contiguous slice (`u32` overflow on
    /// `max_count * elem_size`, out-of-bounds `(ptr, len)`).
    ///
    /// (#583 follow-up to #607) Polls `ctx.cancelled.load(.acquire)`
    /// at entry and short-circuits with `.err` so the executor
    /// closes the writable end and the guest's next `stream.read`
    /// observes the `STATUS_STARTED_CANCELLED` / DROPPED disposition.
    /// The legacy `on_read` executor loop breaks after the first
    /// successful `.progressed` (FIFO becomes non-empty), so cancel
    /// observation at entry is per-call here — but symmetry with the
    /// zero-copy `on_read_into` path (where the executor loops up to
    /// 32 chunks per `stream.read`) keeps the two callbacks aligned.
    fn tcpReceiveStreamOnRead(
        opaque_ctx: ?*anyopaque,
        stream: *async_mod.AsyncStream,
        allocator: Allocator,
    ) async_mod.HostStreamAction {
        const ctx: *SocketsP3StreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        ctx.operation_claim.acquire();
        defer ctx.operation_claim.release();
        if (ctx.cancelled.load(.acquire)) return .err;
        var parent = lockSocketContext(ctx) orelse return .eof;
        defer parent.release();
        if (!fdPollReady(ctx.fd, pollInEvents())) return .would_block;
        const io = std.Io.Threaded.global_single_threaded.io();
        var buf: [64 * 1024]u8 = undefined;
        var iovecs = [_][]u8{&buf};
        const n = io.vtable.netRead(io.userdata, ctx.fd, &iovecs) catch return .err;
        if (n == 0) return .eof;
        stream.buffer.appendSlice(allocator, buf[0..n]) catch return .err;
        return .progressed;
    }

    /// Zero-copy `host_driver.on_read_into` for a TCP-receive
    /// `stream<u8>` slot (#583 B2). Reads directly into the
    /// guest-supplied destination — no intermediate stack/heap
    /// scratch buffer. The executor has already validated that
    /// `dst` is a borrowed slice into guest linmem with
    /// `dst.len <= memory.size - guest_ptr`.
    ///
    /// Caps the per-call read at `min(dst.len, 64 KiB)` to mirror the
    /// production `tcpReceiveStreamOnRead` ceiling — keeps a single
    /// non-blocking syscall bounded so the executor stays responsive.
    ///
    /// ## Per-chunk cancel polling (#583 follow-up to #607)
    ///
    /// The executor's zero-copy `stream.read` arm calls this driver up
    /// to 32 times per guest-visible `stream.read`, each call bounded
    /// at 64 KiB above — i.e. the executor itself is the multi-chunk
    /// drain loop, with this driver supplying one chunk per
    /// invocation. Polling `ctx.cancelled.load(.acquire)` at entry
    /// therefore IS the per-chunk cancel poll: a `task.cancel` issued
    /// mid-multi-MiB receive is observed within at most one chunk's
    /// `recv(2)` latency, matching the cadence the FS drivers (#607)
    /// and HTTP outbound body-read (#602) settled on.
    ///
    /// On cancel: return `.{ .action = .err }` with the default
    /// `bytes_written = 0`. The executor's loop then:
    ///   * sets `s.write_closed = true`,
    ///   * breaks out of the chunk loop,
    ///   * if any prior iteration of the same `stream.read` already
    ///     deposited bytes into the guest slice, the executor's
    ///     `if (total_bytes > 0)` branch surfaces them as
    ///     `completed(partial_count)` — partial-byte accounting is
    ///     handled by the executor's running `total_bytes`, the
    ///     driver does not need to thread it.
    ///   * the NEXT guest `stream.read` finds `s.write_closed` and
    ///     receives `dropped(0)` — i.e. the wit-bindgen `Subtask`
    ///     "cancelled mid-stream" decoder path.
    ///
    /// Zero-copy safety: the borrowed guest slice is only ever
    /// written-to by an in-flight kernel `recv(2)`. Since we short-
    /// circuit BEFORE the syscall, no kernel write races the cancel
    /// observation — the bytes the executor sees in the guest slice
    /// are exactly the ones the prior iterations' `recv(2)` calls
    /// landed there.
    fn tcpReceiveStreamOnReadInto(
        opaque_ctx: ?*anyopaque,
        dst: []u8,
    ) async_mod.HostStreamReadInto {
        const ctx: *SocketsP3StreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        ctx.operation_claim.acquire();
        defer ctx.operation_claim.release();
        if (ctx.cancelled.load(.acquire)) return .{ .action = .err };
        if (dst.len == 0) return .{ .action = .would_block };
        var parent = lockSocketContext(ctx) orelse return .{ .action = .eof };
        defer parent.release();
        if (!fdPollReady(ctx.fd, pollInEvents())) return .{ .action = .would_block };
        const cap = @min(dst.len, 64 * 1024);
        const io = std.Io.Threaded.global_single_threaded.io();
        var iovecs = [_][]u8{dst[0..cap]};
        const n = io.vtable.netRead(io.userdata, ctx.fd, &iovecs) catch
            return .{ .action = .err };
        if (n == 0) return .{ .action = .eof };
        return .{ .action = .progressed, .bytes_written = @intCast(n) };
    }

    fn shutdownTcpStreamHalf(
        ctx: *SocketsP3StreamCtx,
        how: std.Io.net.ShutdownHow,
    ) bool {
        ctx.operation_claim.acquire();
        defer ctx.operation_claim.release();
        const io = std.Io.Threaded.global_single_threaded.io();
        var parent = lockSocketContext(ctx) orelse return false;
        defer parent.release();
        var stream = parent.value().tcp_stream orelse return false;
        stream.shutdown(io, how) catch return false;
        return true;
    }

    fn lockSocketContext(ctx: *SocketsP3StreamCtx) ?SocketLease {
        const handle = ctx.socket_handle orelse return null;
        var parent = ctx.adapter.lookupSocket(handle) orelse return null;
        const socket = parent.value();
        const matches = if (socket.tcp_stream) |stream|
            stream.socket.handle == ctx.fd
        else if (socket.server) |server|
            server.socket.handle == ctx.fd
        else
            false;
        if (!matches) {
            parent.release();
            return null;
        }
        return parent;
    }

    fn tcpReceiveStreamOnDropReadable(opaque_ctx: ?*anyopaque) void {
        const ctx: *SocketsP3StreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        _ = shutdownTcpStreamHalf(ctx, .recv);
    }

    /// `host_driver.on_write_from` for a TCP-send `stream<u8>` slot
    /// (#583 B2 follow-up). Pushes the guest-provided bytes
    /// synchronously to the connected fd. The `src` slice is borrowed
    /// from guest linmem and validated by the executor before the
    /// call — no scratch FIFO involvement on either side. Returns
    /// `.progressed` on success, `.err` on syscall error so the
    /// executor marks `read_closed = true` and surfaces `cancelled`
    /// to the guest's next `stream.write`.
    fn tcpSendStreamOnWriteFrom(
        opaque_ctx: ?*anyopaque,
        src: []const u8,
    ) async_mod.HostStreamAction {
        const ctx: *SocketsP3StreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        ctx.operation_claim.acquire();
        defer ctx.operation_claim.release();
        if (src.len == 0) return .progressed;
        var parent = lockSocketContext(ctx) orelse return .eof;
        defer parent.release();
        const io = std.Io.Threaded.global_single_threaded.io();
        const slices = [_][]const u8{src};
        _ = io.vtable.netWrite(io.userdata, ctx.fd, &.{}, &slices, 1) catch {
            ctx.send_failed.store(true, .release);
            return .err;
        };
        return .progressed;
    }

    /// Legacy `host_driver.on_write` shape for a TCP-send `stream<u8>`
    /// slot. Retained for back-compat with callers that invoke the
    /// driver callback directly (unit tests) and for symmetry with
    /// `on_read`'s fatter signature. Delegates straight to the
    /// `on_write_from` zero-copy variant — both pointers are
    /// installed on the same driver entry so the executor sees the
    /// thinner signature first.
    fn tcpSendStreamOnWrite(
        opaque_ctx: ?*anyopaque,
        _: *async_mod.AsyncStream,
        bytes: []const u8,
        _: Allocator,
    ) async_mod.HostStreamAction {
        return tcpSendStreamOnWriteFrom(opaque_ctx, bytes);
    }

    fn settleTcpSendFuture(ctx: *SocketsP3StreamCtx) void {
        const ci = ctx.component_instance orelse return;
        const future_handle = ctx.completion_future orelse return;
        var state_lease = ci.futures.acquire(future_handle) orelse return;
        if (state_lease.value().state != .pending) {
            state_lease.release();
            return;
        }
        state_lease.release();

        const payload = ci.allocator.alloc(u8, 20) catch {
            var failed_lease = ci.futures.acquire(future_handle) orelse return;
            const future = failed_lease.value();
            future.state = .closed;
            future.write_closed = true;
            const registration = future.read_waitable;
            failed_lease.release();
            _ = ci.notifyWaitable(
                registration,
                async_canon.packStatus(.dropped, 0),
            );
            return;
        };
        @memset(payload, 0);
        if (ctx.send_failed.load(.acquire)) {
            payload[0] = 1;
            payload[4] = @intCast(socketCodeToP3Disc(.unknown));
        }

        var future_lease = ci.futures.acquire(future_handle) orelse {
            ci.allocator.free(payload);
            return;
        };
        const future = future_lease.value();
        if (future.state != .pending) {
            future_lease.release();
            ci.allocator.free(payload);
            return;
        }
        if (future.pending_read) |pending| {
            if (ci.writableGuestBytes(pending.guest_ptr, @intCast(payload.len))) |dst| {
                @memcpy(dst, payload);
                ci.allocator.free(payload);
            } else {
                ci.allocator.free(payload);
                future.state = .closed;
                future.write_closed = true;
                const registration = future.read_waitable;
                future_lease.release();
                _ = ci.notifyWaitable(
                    registration,
                    async_canon.packStatus(.dropped, 0),
                );
                return;
            }
            future.pending_read = null;
        } else {
            future.payload = payload;
        }
        future.state = .ready;
        future.write_closed = true;
        const registration = future.read_waitable;
        future_lease.release();
        _ = ci.notifyWaitable(
            registration,
            async_canon.packStatus(.completed, 0),
        );
    }

    fn tcpSendStreamOnDropWritable(opaque_ctx: ?*anyopaque) void {
        const ctx: *SocketsP3StreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        if (!shutdownTcpStreamHalf(ctx, .send)) ctx.send_failed.store(true, .release);
        settleTcpSendFuture(ctx);
    }

    /// `host_driver.on_read` for a `stream<tcp-socket>` slot produced
    /// by `tcp-socket.listen`. Non-blocking-accepts the listener fd
    /// once per call, allocates a fresh `Socket` rep, and appends the
    /// resulting u32 handle (canonical-ABI little-endian) to the FIFO
    /// so the guest's `stream.read t` rendezvous sees a new element.
    fn tcpAcceptStreamOnRead(
        opaque_ctx: ?*anyopaque,
        stream: *async_mod.AsyncStream,
        allocator: Allocator,
    ) async_mod.HostStreamAction {
        const ctx: *SocketsP3StreamCtx = @ptrCast(@alignCast(opaque_ctx.?));
        ctx.operation_claim.acquire();
        defer ctx.operation_claim.release();
        if (!fdPollReady(ctx.fd, pollInEvents())) return .would_block;
        const io = std.Io.Threaded.global_single_threaded.io();
        var parent = lockSocketContext(ctx) orelse return .eof;
        var server = parent.value().server orelse {
            parent.release();
            return .eof;
        };
        const accepted = server.accept(io) catch {
            parent.release();
            return .would_block;
        };
        parent.release();
        const new_handle = ctx.adapter.pushSocket(.{
            .kind = .tcp,
            .family = ctx.family,
            .state = .connected,
            .tcp_stream = accepted,
            .remote_addr = accepted.socket.address,
        }) catch {
            var owned = accepted;
            owned.close(io);
            return .err;
        };
        var handle_bytes: [4]u8 = undefined;
        // Apply the resource-handle wire offset (`slot + 1`) so the
        // guest's wit-bindgen `Resource<TcpSocket>` constructor doesn't
        // trip its `handle != 0` debug assertion. (#520 wave 2)
        std.mem.writeInt(u32, &handle_bytes, abi.encodeResourceWireAbi(new_handle), .little);
        stream.buffer.appendSlice(allocator, &handle_bytes) catch {
            std.debug.assert(ctx.adapter.socket_table.remove(new_handle));
            return .err;
        };
        return .progressed;
    }

    /// Reject IPv4-mapped IPv6 (`::ffff:0:0/96`) per the WIT contract —
    /// connect MUST surface `invalid-argument` for these even when the
    /// caller's family is IPv6.
    fn socketAddrIsIpv4MappedIpv6(addr: std.Io.net.IpAddress) bool {
        return switch (addr) {
            .ip6 => |v6| blk: {
                // First 10 bytes are zero, bytes 10..11 are 0xff 0xff.
                var i: usize = 0;
                while (i < 10) : (i += 1) {
                    if (v6.bytes[i] != 0) break :blk false;
                }
                break :blk v6.bytes[10] == 0xff and v6.bytes[11] == 0xff;
            },
            else => false,
        };
    }

    /// Returns true for an unspecified address (`0.0.0.0` / `::`).
    fn socketAddrIsUnspecified(addr: std.Io.net.IpAddress) bool {
        return switch (addr) {
            .ip4 => |v4| std.mem.allEqual(u8, &v4.bytes, 0),
            .ip6 => |v6| std.mem.allEqual(u8, &v6.bytes, 0),
        };
    }

    /// True for IPv4 multicast (`224/4`) / limited broadcast
    /// (`255.255.255.255`) / IPv6 multicast (`ff00::/8`).
    fn socketAddrIsNonUnicast(addr: std.Io.net.IpAddress) bool {
        return switch (addr) {
            .ip4 => |v4| (v4.bytes[0] >= 224 and v4.bytes[0] <= 239) or
                (v4.bytes[0] == 255 and v4.bytes[1] == 255 and
                    v4.bytes[2] == 255 and v4.bytes[3] == 255),
            .ip6 => |v6| v6.bytes[0] == 0xff,
        };
    }

    /// True iff `addr` is a unicast address per the 0.3 WIT spec —
    /// i.e., NOT IPv4 multicast (`224.0.0.0/4`), NOT IPv4 limited
    /// broadcast (`255.255.255.255`), NOT IPv6 multicast (`ff00::/8`),
    /// and NOT an IPv4-mapped-IPv6 form (`::ffff:0:0/96`). Both
    /// `bind` and `connect` MUST reject non-unicast addresses with
    /// `invalid-argument`. The unspecified address (`0.0.0.0` /
    /// `::`) is still considered unicast for bind purposes — it's a
    /// valid wildcard — and is rejected separately by `connect` via
    /// `socketAddrIsUnspecified`. (#563)
    pub fn isUnicastAddress(addr: std.Io.net.IpAddress) bool {
        return !socketAddrIsNonUnicast(addr) and !socketAddrIsIpv4MappedIpv6(addr);
    }

    /// True iff `a` and `b` denote the same IP socket address
    /// (family, IP bytes, port). Used by `udpSendP3` to reject a
    /// `some(remote)` that disagrees with a prior `connect`. (#569)
    fn ipAddressEquals(a: std.Io.net.IpAddress, b: std.Io.net.IpAddress) bool {
        return switch (a) {
            .ip4 => |v4a| switch (b) {
                .ip4 => |v4b| v4a.port == v4b.port and std.mem.eql(u8, &v4a.bytes, &v4b.bytes),
                .ip6 => false,
            },
            .ip6 => |v6a| switch (b) {
                .ip4 => false,
                .ip6 => |v6b| v6a.port == v6b.port and std.mem.eql(u8, &v6a.bytes, &v6b.bytes),
            },
        };
    }

    /// True iff the host platform exposes `listen(2)` on an existing
    /// bound socket fd. POSIX has it; Windows uses an AFD IOCTL
    /// instead and we don't reuse host_socket there — see
    /// `tcpListenP3` for the cross-platform fall-back. (#563)
    const can_reuse_bound_socket_for_listen: bool = blk: {
        const tag = @import("builtin").os.tag;
        break :blk tag != .windows and @hasDecl(std.posix.system, "listen");
    };

    /// POSIX `listen(2)` on an already-bound socket fd. Used to
    /// transition a TCP socket from `bound` → `listening` while
    /// preserving the kernel-assigned ephemeral port from
    /// `tcpBindP3`. Returns `null` on success or a mapped error code.
    /// Compiles to an `unreachable`-free no-op on Windows so the
    /// cross-compile sweep (`aarch64-macos`, `x86_64-windows`,
    /// `x86_64-linux`) stays clean. (#563)
    fn listenOnBoundFd(handle: std.posix.fd_t, backlog: u31) ?SocketErrorCode {
        if (comptime !can_reuse_bound_socket_for_listen) return .not_supported;
        const rc = std.posix.system.listen(handle, backlog);
        return switch (std.posix.errno(rc)) {
            .SUCCESS => null,
            .ADDRINUSE => .address_in_use,
            .BADF => .invalid_state,
            .NOTSOCK => .invalid_state,
            .OPNOTSUPP => .not_supported,
            else => .unknown,
        };
    }

    /// `[method]tcp-socket.connect: async func(remote-address)
    ///   -> result<_, error-code>` (#519).
    ///
    /// Async-func host import. The canonical-ABI lower-of-async-func
    /// surface produces a `future<R>` handle: we run the host-side
    /// blocking `connect(2)` synchronously and settle a pre-encoded
    /// `result<_, error-code>` future in `ci.futures`. WIT-mandated
    /// argument validation runs before the syscall:
    ///   - family mismatch       → invalid-argument
    ///   - IPv4-mapped IPv6 dest → invalid-argument
    ///   - non-unicast dest      → invalid-argument
    ///   - unspecified dest      → invalid-argument
    ///   - port == 0             → invalid-argument
    ///   - socket already connecting/connected/listening → invalid-state
    ///   - allow-list deny       → access-denied (non-empty template
    ///                              not containing the destination —
    ///                              empty template is allow-all per
    ///                              `templateAllows`, #583 A1)
    fn tcpConnectP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const sock_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var s_lease = self.lookupSocket(sock_handle) orelse {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_state) };
            return;
        };
        defer s_lease.release();
        const s = s_lease.value();
        if (s.kind != .tcp) {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_state) };
            return;
        }
        const remote = liftIpSocketAddress(args[1], s.family) catch |err| switch (err) {
            error.FamilyMismatch => {
                results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_argument) };
                return;
            },
            error.InvalidArgs => return error.InvalidArgs,
        };
        if (!isUnicastAddress(remote) or
            socketAddrIsUnspecified(remote) or
            socketPort(remote) == 0)
        {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_argument) };
            return;
        }
        // Spec: only `unbound` and `bound` admit a fresh connect.
        // `connecting`, `connected`, `listening` and `closed` reject.
        switch (s.state) {
            .unbound, .bound => {},
            else => {
                results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_state) };
                return;
            },
        }
        // Allow-list gate (#583 A1). Empty template = allow-all; a
        // non-empty template must contain the remote address or this
        // returns `access-denied` synchronously into the future.
        if (!self.templateAllowsAddress(remote)) {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .access_denied) };
            return;
        }
        const io = std.Io.Threaded.global_single_threaded.io();
        // Release any `host_socket` left over from a prior `bind` —
        // `IpAddress.connect` opens a fresh fd and we'd otherwise leak
        // the bound one. Reusing the bound fd for connect() would
        // preserve the source-port pin, but that path requires a raw
        // POSIX connect on the bound socket and isn't required by the
        // sockets-tcp-bind fixture; deferred until #563 follow-ups. (#563)
        if (s.host_socket) |*hs| {
            hs.close(io);
            s.host_socket = null;
        }
        const stream = std.Io.net.IpAddress.connect(&remote, io, .{
            .mode = .stream,
        }) catch |err| {
            s.state = .closed;
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, mapConnectError(err)) };
            return;
        };
        s.tcp_stream = stream;
        s.local_addr = stream.socket.address;
        s.remote_addr = remote;
        s.state = .connected;
        results[0] = .{ .handle = try socketReadyResultFuture(ci, true, .unknown) };
    }

    /// `[method]tcp-socket.listen: func()
    ///   -> result<stream<tcp-socket>, error-code>` (#519, #535, #563).
    ///
    /// Synchronous. Performs the kernel `listen(2)` and returns a
    /// `stream<tcp-socket>` handle. The stream's `host_driver` (#535)
    /// runs `accept(2)` on each guest `stream.read` so multi-connection
    /// listeners admit a connection per rendezvous without per-call
    /// host-fn dispatch. Pre-fills the FIFO with any backlog already
    /// queued at listen time.
    ///
    /// 0.3 listen-reuse (#563): when `tcpBindP3` has already opened a
    /// `host_socket` for this rep, transition that same fd to listening
    /// in-place via `listenOnBoundFd` (POSIX `listen(2)`). This
    /// preserves the kernel-assigned ephemeral port observed by
    /// `local-address` between bind and listen. On Windows
    /// (`listenOnBoundFd` unavailable) we fall back to closing the
    /// bound fd and re-running `IpAddress.listen` with the recorded
    /// `local_addr` — the kernel may pick a different ephemeral port in
    /// that rare path but the cross-compile sweep stays green.
    fn tcpListenP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const sock_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var s_lease = self.lookupSocket(sock_handle) orelse {
            results[0] = try socketResultErrP3(allocator, .invalid_state);
            return;
        };
        var socket_active = true;
        defer if (socket_active) s_lease.release();
        const s = s_lease.value();
        if (s.kind != .tcp) {
            results[0] = try socketResultErrP3(allocator, .invalid_state);
            return;
        }
        switch (s.state) {
            .unbound, .bound => {},
            else => {
                results[0] = try socketResultErrP3(allocator, .invalid_state);
                return;
            },
        }
        const io = std.Io.Threaded.global_single_threaded.io();
        const backlog: u31 = s.listen_backlog orelse 128;
        // Listen-reuse path: prefer the bound `host_socket` so the
        // kernel-assigned ephemeral port from `tcpBindP3` carries over
        // into the listening state. (#563)
        var server: ?std.Io.net.Server = null;
        if (s.host_socket) |host_socket| {
            if (comptime can_reuse_bound_socket_for_listen) {
                if (listenOnBoundFd(host_socket.handle, backlog)) |code| {
                    // listen(2) failure: surface the mapped code with
                    // a diagnostic payload via the `other` arm so the
                    // fixture can decode the cause.
                    results[0] = try socketResultErrP3WithDiag(ci, allocator, code, "listen on bound fd failed");
                    return;
                }
                server = .{
                    .socket = host_socket,
                    .options = if (std.Io.net.Server.AcceptOptions != void)
                        .{ .mode = .stream, .protocol = .tcp }
                    else {},
                };
                // Ownership of the fd moves to `s.server`; clear the
                // `host_socket` slot so `closeAll` doesn't double-close.
                s.host_socket = null;
            } else {
                // Windows: stdlib has no listen-on-bound-fd path.
                // Close the bound fd and fall through to a fresh
                // `IpAddress.listen` with the recorded local_addr.
                var hs_mut = host_socket;
                hs_mut.close(io);
                s.host_socket = null;
            }
        }
        if (server == null) {
            // Implicit-bind: WIT-mandated fallback when `bind` was
            // not called. Open a fresh server fd via the stdlib
            // path. Also used for the Windows fall-back above.
            const local: std.Io.net.IpAddress = s.local_addr orelse switch (s.family) {
                .ipv4 => std.Io.net.IpAddress{ .ip4 = .{ .bytes = .{ 0, 0, 0, 0 }, .port = 0 } },
                .ipv6 => std.Io.net.IpAddress{ .ip6 = .{
                    .bytes = [_]u8{0} ** 16,
                    .port = 0,
                    .flow = 0,
                } },
            };
            server = std.Io.net.IpAddress.listen(&local, io, .{
                .kernel_backlog = backlog,
            }) catch |err| {
                results[0] = try socketResultErrP3WithDiag(ci, allocator, mapSocketListenError(err), @errorName(err));
                return;
            };
        }
        s.server = server.?;
        s.local_addr = server.?.socket.address;
        s.state = .listening;
        const family = s.family;
        const local_addr = s.local_addr;

        // Install an accept-loop driver on the stream so each guest
        // `stream.read t` invocation can pop a fresh connection off
        // the backlog (#535). Pre-drain any queued connections so
        // a guest that connect()s before reading still sees them.
        const driver_ctx = try self.allocSocketsP3StreamCtx(
            sock_handle,
            server.?.socket.handle,
            family,
        );
        const stream_h = ci.allocAsyncHandle();
        ci.streams.put(ci.allocator, stream_h, .{
            .elem_type_idx = 0,
            .state = .open,
            .host_driver = .{
                .context = driver_ctx,
                .on_read = &tcpAcceptStreamOnRead,
                .on_destroy = &socketsP3StreamCtxOnDestroy,
            },
        }) catch |err| {
            socketsP3StreamCtxOnDestroy(driver_ctx);
            return err;
        };
        errdefer _ = ci.streams.remove(stream_h);
        s_lease.release();
        socket_active = false;
        // Non-blocking accept attempt to pre-fill the stream (the driver
        // path will keep adding as more arrive on subsequent reads).
        if (fdPollReady(server.?.socket.handle, pollInEvents())) {
            var accept_server = server.?;
            if (accept_server.accept(io)) |accepted| {
                const new_handle = self.pushSocket(.{
                    .kind = .tcp,
                    .family = family,
                    .state = .connected,
                    .tcp_stream = accepted,
                    .remote_addr = accepted.socket.address,
                    .local_addr = local_addr,
                }) catch {
                    var owned = accepted;
                    owned.close(io);
                    return error.OutOfMemory;
                };
                if (ci.streams.acquire(stream_h)) |initial_lease| {
                    var stream_lease = initial_lease;
                    defer stream_lease.release();
                    const slot = stream_lease.value();
                    var handle_bytes: [4]u8 = undefined;
                    // Apply the resource-handle wire offset
                    // (`slot + 1`); see `accept_driver` above. (#520
                    // wave 2)
                    std.mem.writeInt(u32, &handle_bytes, abi.encodeResourceWireAbi(new_handle), .little);
                    slot.buffer.appendSlice(ci.allocator, &handle_bytes) catch |err| {
                        _ = self.socket_table.remove(new_handle);
                        return err;
                    };
                }
            } else |_| {}
        }

        const payload = try allocator.create(InterfaceValue);
        payload.* = .{ .handle = stream_h };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = payload } };
    }

    /// `[method]tcp-socket.send: func(data: stream<u8>)
    ///   -> future<result<_, error-code>>` (#519, #535).
    ///
    /// Synchronous. Attaches an `on_write` host driver to the guest's
    /// `stream<u8>` so subsequent stream-writes flow straight to the
    /// connected fd (#535). Drains any bytes the guest already pushed
    /// into the FIFO before the call. The returned future settles when
    /// the guest drops the stream's writable end, after the driver
    /// propagates the TCP half-close; write errors select its error arm.
    fn tcpSendP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const sock_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const stream_handle = switch (args[1]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var s_lease = self.lookupSocket(sock_handle) orelse {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_state) };
            return;
        };
        defer s_lease.release();
        const s = s_lease.value();
        if (s.kind != .tcp or s.state != .connected) {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_state) };
            return;
        }
        const stream = s.tcp_stream orelse {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_state) };
            return;
        };
        var existence_lease = ci.streams.acquire(stream_handle) orelse {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_state) };
            return;
        };
        existence_lease.release();
        const driver_ctx = try self.allocSocketsP3StreamCtx(
            sock_handle,
            stream.socket.handle,
            s.family,
        );
        const future_handle = ci.allocAsyncHandle();
        ci.futures.put(ci.allocator, future_handle, .{
            .elem_type_idx = 0,
            .state = .pending,
        }) catch |err| {
            socketsP3StreamCtxOnDestroy(driver_ctx);
            return err;
        };
        errdefer _ = ci.futures.remove(future_handle);
        driver_ctx.component_instance = ci;
        driver_ctx.completion_future = future_handle;

        var driver_installed = false;
        var writer_already_closed = false;
        while (ci.streams.acquire(stream_handle)) |initial_lease| {
            var stream_lease = initial_lease;
            const slot = stream_lease.value();
            // Drain any bytes the guest pre-buffered (e.g. wrote into
            // the stream before calling `send`) straight to the fd.
            if (slot.buffer.items.len > 0) {
                var detached = slot.buffer;
                slot.buffer = .empty;
                stream_lease.release();
                defer detached.deinit(ci.allocator);
                const io = std.Io.Threaded.global_single_threaded.io();
                const slices = [_][]const u8{detached.items};
                _ = io.vtable.netWrite(io.userdata, stream.socket.handle, &.{}, &slices, 1) catch |err| {
                    if (ci.streams.acquire(stream_handle)) |failed_lease| {
                        var final_lease = failed_lease;
                        final_lease.value().read_closed = true;
                        final_lease.release();
                    }
                    _ = ci.futures.remove(future_handle);
                    socketsP3StreamCtxOnDestroy(driver_ctx);
                    results[0] = .{
                        .handle = try socketReadyResultFuture(
                            ci,
                            false,
                            mapSocketSendError(err),
                        ),
                    };
                    return;
                };
                continue;
            }
            // Attach the driver so subsequent guest writes flow to fd.
            // Both callback shapes are installed: the executor prefers
            // the thinner `on_write_from` (zero-copy, #583 B2
            // follow-up) which drops the unused `*AsyncStream` /
            // `Allocator` parameters. `on_write` remains as a
            // delegation shim so unit tests that invoke the driver
            // callback directly still work.
            slot.host_driver = .{
                .context = driver_ctx,
                .on_write = &tcpSendStreamOnWrite,
                .on_write_from = &tcpSendStreamOnWriteFrom,
                .on_drop_writable = &tcpSendStreamOnDropWritable,
                .on_destroy = &socketsP3StreamCtxOnDestroy,
            };
            writer_already_closed = slot.write_closed;
            driver_installed = true;
            stream_lease.release();
            break;
        }
        if (!driver_installed) {
            driver_ctx.send_failed.store(true, .release);
            settleTcpSendFuture(driver_ctx);
            socketsP3StreamCtxOnDestroy(driver_ctx);
        } else if (writer_already_closed) {
            tcpSendStreamOnDropWritable(driver_ctx);
        }
        results[0] = .{ .handle = future_handle };
    }

    /// `[method]tcp-socket.receive: func()
    ///   -> tuple<stream<u8>, future<result<_, error-code>>>` (#519, #535).
    ///
    /// Synchronous. Returns a `stream<u8>` whose `host_driver.on_read`
    /// (#535) pumps `netRead`s from the connected fd into the FIFO on
    /// each guest `stream.read`. The companion future settles to
    /// `result::ok` immediately; per-read errors are surfaced through
    /// `write_closed = true` on the stream so a subsequent `stream.read`
    /// observes the natural stream-end status (`cancelled`).
    fn tcpReceiveP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const sock_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };

        // Build error-arm tuple: closed stream + settled-err future.
        const buildErrTuple = struct {
            fn run(ic: *ComponentInstance, alloc: Allocator, code: SocketErrorCode) !InterfaceValue {
                const sh = try socketAllocByteStream(ic, &.{}, true);
                const fh = try socketReadyResultFuture(ic, false, code);
                const fields = try alloc.alloc(InterfaceValue, 2);
                fields[0] = .{ .handle = sh };
                fields[1] = .{ .handle = fh };
                return .{ .tuple_val = fields };
            }
        }.run;

        var s_lease = self.lookupSocket(sock_handle) orelse {
            results[0] = try buildErrTuple(ci, allocator, .invalid_state);
            return;
        };
        defer s_lease.release();
        const s = s_lease.value();
        if (s.kind != .tcp or s.state != .connected) {
            results[0] = try buildErrTuple(ci, allocator, .invalid_state);
            return;
        }
        if (s.receive_started) {
            results[0] = try buildErrTuple(ci, allocator, .invalid_state);
            return;
        }
        const stream = s.tcp_stream orelse {
            results[0] = try buildErrTuple(ci, allocator, .invalid_state);
            return;
        };
        s.receive_started = true;

        // Install a long-lived receive driver on the stream. The driver
        // does a non-blocking netRead per invocation so the executor's
        // `stream.read` rendezvous can keep draining as long as bytes
        // are arriving on the fd (no per-call host-fn dispatch needed).
        //
        // Both callbacks are installed: the executor prefers
        // `on_read_into` (zero-copy, #583 B2) for the common case
        // where the guest's destination is addressable as a borrowed
        // linmem slice; `on_read` remains a fallback when the
        // requested length overflows `u32` or extends past
        // `memory.size`.
        const driver_ctx = try self.allocSocketsP3StreamCtx(
            sock_handle,
            stream.socket.handle,
            s.family,
        );
        const stream_h = ci.allocAsyncHandle();
        ci.streams.put(ci.allocator, stream_h, .{
            .elem_type_idx = 0,
            .state = .open,
            .host_driver = .{
                .context = driver_ctx,
                .on_read = &tcpReceiveStreamOnRead,
                .on_read_into = &tcpReceiveStreamOnReadInto,
                .on_drop_readable = &tcpReceiveStreamOnDropReadable,
                .on_destroy = &socketsP3StreamCtxOnDestroy,
            },
        }) catch |err| {
            socketsP3StreamCtxOnDestroy(driver_ctx);
            return err;
        };
        errdefer _ = ci.streams.remove(stream_h);
        // Pre-buffer anything already pending on the fd at call time so
        // tests that send-then-receive without a yield still see data.
        if (fdPollReady(stream.socket.handle, pollInEvents())) {
            const io = std.Io.Threaded.global_single_threaded.io();
            var buf: [64 * 1024]u8 = undefined;
            var iovecs = [_][]u8{&buf};
            const n = io.vtable.netRead(io.userdata, stream.socket.handle, &iovecs) catch 0;
            if (n > 0) if (ci.streams.acquire(stream_h)) |initial_lease| {
                var stream_lease = initial_lease;
                defer stream_lease.release();
                try stream_lease.value().buffer.appendSlice(ci.allocator, buf[0..n]);
            };
        }
        const future_h = try socketReadyResultFuture(ci, true, .unknown);
        errdefer _ = ci.futures.remove(future_h);
        const fields = try allocator.alloc(InterfaceValue, 2);
        fields[0] = .{ .handle = stream_h };
        fields[1] = .{ .handle = future_h };
        results[0] = .{ .tuple_val = fields };
    }

    /// `[method]udp-socket.send: async func(data: list<u8>,
    ///   remote-address: option<ip-socket-address>)
    ///   -> result<_, error-code>` (#519).
    ///
    /// Async-func host import. Performs the host-side `sendto(2)`
    /// synchronously and settles the returned future. Uses the
    /// socket's `remote_addr` (set by `connect`) when the caller
    /// passes `none`.
    fn udpSendP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;
        const sock_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const data_pl = switch (args[1]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        var s_lease = self.lookupSocket(sock_handle) orelse {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_state) };
            return;
        };
        defer s_lease.release();
        const s = s_lease.value();
        if (s.kind != .udp) {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_state) };
            return;
        }
        // WIT mandates the address-validation pass run BEFORE the
        // bound-state check so a wrong-family destination on an
        // unbound socket surfaces `invalid-argument` (not
        // `invalid-state`). `sockets-udp-send::test_wrong_address_family`
        // exercises this exact ordering. (#569)
        const remote_opt = switch (args[2]) {
            .option_val => |o| o,
            else => return error.InvalidArgs,
        };
        const dest: std.Io.net.IpAddress = if (remote_opt.is_some) blk: {
            const payload = remote_opt.payload orelse {
                results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_argument) };
                return;
            };
            const remote = liftIpSocketAddress(payload.*, s.family) catch |err| switch (err) {
                error.FamilyMismatch => {
                    results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_argument) };
                    return;
                },
                error.InvalidArgs => return error.InvalidArgs,
            };
            // Non-unicast destinations are rejected as invalid-argument
            // (WIT-mandated pre-syscall check). Unspecified address is
            // also pre-rejected per WIT. (#569)
            if (!isUnicastAddress(remote) or socketAddrIsUnspecified(remote)) {
                results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_argument) };
                return;
            }
            // Port=0 destination: the WIT spec text says
            // `invalid-argument`, but the
            // `sockets-udp-send::test_remote_addr_with_port_0` fixture
            // expects `address-not-bindable` (matching the kernel's
            // EADDRNOTAVAIL response on sendmsg). Synthesize that error
            // here without round-tripping through the kernel — sendto
            // with port=0 is undefined on some platforms. (#569)
            if (socketPort(remote) == 0) {
                results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .address_not_bindable) };
                return;
            }
            if (s.remote_addr) |connected_remote| {
                if (!ipAddressEquals(connected_remote, remote)) {
                    // WIT: `invalid-argument` when send's `some(remote)`
                    // disagrees with a prior `connect`.
                    results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_argument) };
                    return;
                }
            }
            break :blk remote;
        } else (s.remote_addr orelse {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_argument) };
            return;
        });
        // Allow-list gate (#583 A1). Re-checked per datagram so a
        // connected socket's pre-cleared remote still cannot escape
        // a tightened allow-list mid-run. Empty template = allow-all.
        if (!self.templateAllowsAddress(dest)) {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .access_denied) };
            return;
        }
        // Implicit bind: WIT requires `send` on an unbound UDP socket
        // to bind to a kernel-chosen ephemeral port before the sendmsg.
        // `sockets-udp-send::test_implicit_bind` then asserts
        // `get-local-address().is_ok()`. (#569)
        if (s.host_socket == null) {
            const wildcard: std.Io.net.IpAddress = switch (s.family) {
                .ipv4 => .{ .ip4 = .{ .bytes = .{ 0, 0, 0, 0 }, .port = 0 } },
                .ipv6 => .{ .ip6 = .{ .bytes = [_]u8{0} ** 16, .port = 0, .flow = 0 } },
            };
            const host_socket = bindAndGetsockname(wildcard, .dgram, .udp) catch |err| {
                results[0] = .{ .handle = try socketReadyResultFuture(ci, false, mapSocketBindError(err)) };
                return;
            };
            s.host_socket = host_socket;
            s.local_addr = host_socket.address;
            s.state = .bound;
        }
        const data_bytes: []const u8 = if (data_pl.len == 0)
            &.{}
        else
            (ci.readGuestBytes(data_pl.ptr, data_pl.len) orelse {
                results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .invalid_argument) };
                return;
            });
        const io = std.Io.Threaded.global_single_threaded.io();
        sendUdpDatagram(&s.host_socket.?, io, &dest, s.remote_addr != null, data_bytes) catch |err| {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, mapSocketSendError(err)) };
            return;
        };
        results[0] = .{ .handle = try socketReadyResultFuture(ci, true, .unknown) };
    }

    /// `[method]udp-socket.receive: async func()
    ///   -> result<tuple<list<u8>, ip-socket-address>, error-code>`
    /// (#519, #535, #576).
    ///
    /// Async-func host import. Issues a non-blocking `recvfrom(2)`
    /// once. If a datagram is already waiting in the kernel queue,
    /// lifts the resulting `tuple<list<u8>, ip-socket-address>` into
    /// the future payload synchronously via the 0.3 sockets
    /// canonical-ABI lowering (#535) and settles the future
    /// `.ready`. If the fd would block, mints a `.pending` future
    /// and registers it on `pending_udp_receives` — the adapter's
    /// `driveAsyncEvents` hook re-polls the fd on every
    /// `waitable-set.wait` tick and settles the future as soon as a
    /// datagram arrives (#576), unblocking guests that drive
    /// `receive` concurrently with `send` (e.g. `futures::join!`).
    /// Hard error states (`invalid_state` for an unbound socket,
    /// wrong kind, or unknown handle) still surface through a
    /// settled err-future immediately.
    fn udpReceiveP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const sock_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var s_lease = self.lookupSocket(sock_handle) orelse {
            // udp-receive's err arm carries a `result<tuple<list<u8>,
            // ip-socket-address>, error-code>` envelope (44 bytes), not
            // the 20-byte `result<_, error-code>` shape — use the
            // shape-aware err-future builder so the payload is sized
            // and laid out for the actual return type. (#569)
            results[0] = .{ .handle = try socketReadyAsyncErrFuture(ci, .udp_receive_err, false, .invalid_state) };
            return;
        };
        defer s_lease.release();
        const s = s_lease.value();
        if (s.kind != .udp or s.host_socket == null) {
            results[0] = .{ .handle = try socketReadyAsyncErrFuture(ci, .udp_receive_err, false, .invalid_state) };
            return;
        }
        const io = std.Io.Threaded.global_single_threaded.io();
        var buf: [65536]u8 = undefined;
        const recv_res = s.host_socket.?.receiveTimeout(io, &buf, .{
            .duration = .{ .raw = .{ .nanoseconds = 0 }, .clock = .awake },
        });
        if (recv_res) |recv| {
            const data = recv.data;
            const remote = recv.from;
            const ok_tuple = try socketsP3LowerUdpReceivePayload(ci, data, remote);
            defer {
                // Free the host-side tuple fields owned by ci.allocator.
                const fields = ok_tuple.tuple_val;
                fields[1].deinit(ci.allocator);
                ci.allocator.free(fields);
            }
            const ok_payload = try ci.allocator.create(InterfaceValue);
            defer ci.allocator.destroy(ok_payload);
            ok_payload.* = ok_tuple;
            const ok_result = InterfaceValue{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
            const payload_bytes = try socketsP3LowerAsyncPayload(ci.allocator, .udp_receive_err, ok_result);
            const handle = try spawnReadyFutureBytes(ci, payload_bytes);
            results[0] = .{ .handle = handle };
            return;
        } else |_| {
            // No datagram waiting — park the receive on a `.pending`
            // future and register it with the async event driver so
            // the next inbound packet completes the future from
            // `completeReadyPendingUdpReceives`. (#576)
            const fh = ci.allocAsyncHandle();
            try ci.futures.put(ci.allocator, fh, .{
                .elem_type_idx = 0,
                .state = .pending,
            });
            errdefer _ = ci.futures.remove(fh);
            var socket_parent = self.socket_table.acquire(sock_handle) orelse
                return error.InvalidHandle;
            _ = self.pending_udp_receives.publish(.{
                .future_handle = fh,
                .sock_handle = sock_handle,
                .socket_generation = s.resource_generation,
                .socket_lease = socket_parent,
            }) catch |err| {
                socket_parent.release();
                return err;
            };
            results[0] = .{ .handle = fh };
            return;
        }
    }

    /// `wasi:sockets/ip-name-lookup@0.3.0-*.resolve-addresses:
    ///   async func(name: string) -> result<list<ip-address>, error-code>`
    /// (#519, #535).
    ///
    /// Async-func host import. Runs `std.Io.net.HostName.lookup` against
    /// the host resolver synchronously, lifts the resulting addresses
    /// into the future payload via canonical-ABI lowering (#535), and
    /// settles `ci.futures` at `.ready` so the executor's `future_read`
    /// rendezvous can deliver them. The adapter-level
    /// `sockets_allow_list_template` gates the lookup (empty = deny-all).
    fn resolveAddressesP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const name_pl = switch (args[0]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        if (!self.hasSocketsAllowList()) {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .name_unresolvable) };
            return;
        }
        const name_bytes: []const u8 = if (name_pl.len == 0)
            ""
        else
            (ci.readGuestBytes(name_pl.ptr, name_pl.len) orelse {
                results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .name_unresolvable) };
                return;
            });
        const host = std.Io.net.HostName.init(name_bytes) catch {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .name_unresolvable) };
            return;
        };
        const io = std.Io.Threaded.global_single_threaded.io();
        var queue_buf: [32]std.Io.net.HostName.LookupResult = undefined;
        var queue: std.Io.Queue(std.Io.net.HostName.LookupResult) = .init(&queue_buf);
        host.lookup(io, &queue, .{ .port = 0 }) catch |err| {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, mapDnsError(err)) };
            return;
        };
        // Collect each `address` entry. Drop the canonical_name (the
        // 0.3 surface only returns the address list).
        var addrs: std.ArrayListUnmanaged(std.Io.net.IpAddress) = .empty;
        defer addrs.deinit(ci.allocator);
        while (queue.getOneUncancelable(io)) |item| {
            switch (item) {
                .address => |a| addrs.append(ci.allocator, a) catch return error.OutOfMemory,
                .canonical_name => {},
            }
        } else |drain_err| switch (drain_err) {
            error.Closed => {},
        }
        if (addrs.items.len == 0) {
            results[0] = .{ .handle = try socketReadyResultFuture(ci, false, .name_unresolvable) };
            return;
        }

        // Lower the list<ip-address> into guest memory: each element is a
        // canonical-ABI `variant<ipv4(tuple<u8 x 4>), ipv6(tuple<u16 x 8>)>`
        // whose layout we mirror in `sockets_p3_local_types`. The outer
        // list pointer + length goes into the future payload buffer.
        const list_ptr = try socketsP3LowerIpAddressList(ci, addrs.items);
        const list_iv = InterfaceValue{ .list = .{ .ptr = list_ptr, .len = @intCast(addrs.items.len) } };
        const ok_payload = try ci.allocator.create(InterfaceValue);
        defer ci.allocator.destroy(ok_payload);
        ok_payload.* = list_iv;
        const ok_result = InterfaceValue{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
        const payload_bytes = try socketsP3LowerAsyncPayload(ci.allocator, .resolve_list_err, ok_result);
        const handle = try spawnReadyFutureBytes(ci, payload_bytes);
        results[0] = .{ .handle = handle };
    }

    /// Extract the port from any IpAddress family — std doesn't expose
    /// this uniformly across `.ip4` / `.ip6` arms.
    fn socketPort(addr: std.Io.net.IpAddress) u16 {
        return switch (addr) {
            .ip4 => |v4| v4.port,
            .ip6 => |v6| v6.port,
        };
    }

    /// Register `wasi:sockets/types@0.3.0-*` (#486). Binds all 26
    /// tcp-socket members + 16 udp-socket members under their 0.3 WIT
    /// names. Sync ops route to real implementations (sometimes shared
    /// with the 0.2 callback, sometimes a new P3-specific function);
    /// async / stream ops route to the default-deny stub described
    /// above.
    pub fn populateWasiSocketsTypesP3(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        interface_name: []const u8,
    ) !void {
        const M = struct {
            name: []const u8,
            call: *const fn (?*anyopaque, *ComponentInstance, []const InterfaceValue, []InterfaceValue, Allocator) anyerror!void,
        };
        const members = [_]M{
            // ── tcp-socket static + lifecycle ────────────────────
            .{ .name = "[static]tcp-socket.create", .call = &tcpCreateP3 },
            .{ .name = "[method]tcp-socket.bind", .call = &tcpBindP3 },
            .{ .name = "[method]tcp-socket.connect", .call = &tcpConnectP3 },
            .{ .name = "[method]tcp-socket.listen", .call = &tcpListenP3 },
            .{ .name = "[method]tcp-socket.send", .call = &tcpSendP3 },
            .{ .name = "[method]tcp-socket.receive", .call = &tcpReceiveP3 },
            // ── tcp-socket renamed getters (delegate to 0.2, P3-remapped) ─
            .{ .name = "[method]tcp-socket.get-local-address", .call = &p3SocketWrapper(tcpLocalAddress).call },
            .{ .name = "[method]tcp-socket.get-remote-address", .call = &p3SocketWrapper(tcpRemoteAddress).call },
            .{ .name = "[method]tcp-socket.get-is-listening", .call = &p3SocketWrapper(tcpIsListening).call },
            .{ .name = "[method]tcp-socket.get-address-family", .call = &p3SocketWrapper(socketAddressFamily).call },
            .{ .name = "[method]tcp-socket.set-listen-backlog-size", .call = &p3SocketWrapper(tcpSetListenBacklogSize).call },
            .{ .name = "[method]tcp-socket.get-keep-alive-enabled", .call = &p3SocketWrapper(tcpGetKeepAliveEnabled).call },
            .{ .name = "[method]tcp-socket.set-keep-alive-enabled", .call = &p3SocketWrapper(tcpSetKeepAliveEnabled).call },
            .{ .name = "[method]tcp-socket.get-keep-alive-idle-time", .call = &p3SocketWrapper(tcpGetKeepAliveIdleTime).call },
            .{ .name = "[method]tcp-socket.set-keep-alive-idle-time", .call = &p3SocketWrapper(tcpSetKeepAliveIdleTime).call },
            .{ .name = "[method]tcp-socket.get-keep-alive-interval", .call = &p3SocketWrapper(tcpGetKeepAliveInterval).call },
            .{ .name = "[method]tcp-socket.set-keep-alive-interval", .call = &p3SocketWrapper(tcpSetKeepAliveInterval).call },
            .{ .name = "[method]tcp-socket.get-keep-alive-count", .call = &p3SocketWrapper(tcpGetKeepAliveCount).call },
            .{ .name = "[method]tcp-socket.set-keep-alive-count", .call = &p3SocketWrapper(tcpSetKeepAliveCount).call },
            .{ .name = "[method]tcp-socket.get-hop-limit", .call = &p3SocketWrapper(socketGetHopLimit).call },
            .{ .name = "[method]tcp-socket.set-hop-limit", .call = &p3SocketWrapper(socketSetHopLimit).call },
            .{ .name = "[method]tcp-socket.get-receive-buffer-size", .call = &p3SocketWrapper(socketGetReceiveBufferSize).call },
            .{ .name = "[method]tcp-socket.set-receive-buffer-size", .call = &p3SocketWrapper(socketSetReceiveBufferSize).call },
            .{ .name = "[method]tcp-socket.get-send-buffer-size", .call = &p3SocketWrapper(socketGetSendBufferSize).call },
            .{ .name = "[method]tcp-socket.set-send-buffer-size", .call = &p3SocketWrapper(socketSetSendBufferSize).call },
            .{ .name = "[resource-drop]tcp-socket", .call = &socketResourceDrop },
            // ── udp-socket static + lifecycle ────────────────────
            .{ .name = "[static]udp-socket.create", .call = &udpCreateP3 },
            .{ .name = "[method]udp-socket.bind", .call = &udpBindP3 },
            .{ .name = "[method]udp-socket.connect", .call = &udpConnectP3 },
            .{ .name = "[method]udp-socket.disconnect", .call = &udpDisconnectP3 },
            .{ .name = "[method]udp-socket.send", .call = &udpSendP3 },
            .{ .name = "[method]udp-socket.receive", .call = &udpReceiveP3 },
            // ── udp-socket renamed getters (delegate to 0.2, P3-remapped) ─
            .{ .name = "[method]udp-socket.get-local-address", .call = &p3SocketWrapper(udpLocalAddress).call },
            .{ .name = "[method]udp-socket.get-remote-address", .call = &p3SocketWrapper(udpRemoteAddress).call },
            .{ .name = "[method]udp-socket.get-address-family", .call = &p3SocketWrapper(socketAddressFamily).call },
            .{ .name = "[method]udp-socket.get-unicast-hop-limit", .call = &p3SocketWrapper(socketGetHopLimit).call },
            .{ .name = "[method]udp-socket.set-unicast-hop-limit", .call = &p3SocketWrapper(socketSetHopLimit).call },
            .{ .name = "[method]udp-socket.get-receive-buffer-size", .call = &p3SocketWrapper(socketGetReceiveBufferSize).call },
            .{ .name = "[method]udp-socket.set-receive-buffer-size", .call = &p3SocketWrapper(socketSetReceiveBufferSize).call },
            .{ .name = "[method]udp-socket.get-send-buffer-size", .call = &p3SocketWrapper(socketGetSendBufferSize).call },
            .{ .name = "[method]udp-socket.set-send-buffer-size", .call = &p3SocketWrapper(socketSetSendBufferSize).call },
            .{ .name = "[resource-drop]udp-socket", .call = &socketResourceDrop },
        };
        for (members) |m| {
            try self.sockets_types_p3_iface.members.put(self.allocator, m.name, .{
                .func = .{ .context = self, .call = m.call },
            });
        }
        try providers.put(self.allocator, interface_name, .{
            .host_instance = &self.sockets_types_p3_iface,
        });
    }

    /// Register `wasi:sockets/ip-name-lookup@0.3.0-*` (#486). The 0.3
    /// surface is a single `resolve-addresses: async func(name: string)
    /// -> result<list<ip-address>, error-code>` — no network arg, no
    /// stream sub-resource. Returns access-denied today (default-deny);
    /// real lookup is gated behind the same allow-list capability the
    /// 0.2 path uses.
    pub fn populateWasiSocketsIpNameLookupP3(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        interface_name: []const u8,
    ) !void {
        try self.sockets_ip_name_lookup_p3_iface.members.put(self.allocator, "resolve-addresses", .{
            .func = .{ .context = self, .call = &resolveAddressesP3 },
        });
        try providers.put(self.allocator, interface_name, .{
            .host_instance = &self.sockets_ip_name_lookup_p3_iface,
        });
    }

    // ----- wasi:http (#149) -----

    /// `wasi:http/types.header-error` variant — produced by mutation
    /// methods on `fields` that reject syntactically-invalid or
    /// forbidden names/values, or that target an immutable view
    /// (#538). Discriminants match the WIT case order at
    /// `tests/wasi-testsuite/.../wasi-http-0.3.0-rc-2026-03-15/package.wit`.
    pub const HeaderErrorCode = enum(u32) {
        invalid_syntax = 0,
        forbidden = 1,
        immutable = 2,
        size_exceeded = 3,
        // `other(option<string>)` has discriminant 4 but our default
        // adapters don't synthesise it.
    };

    /// Build a `result<X, header-error>` err InterfaceValue (#538).
    fn httpHeaderErr(allocator: Allocator, code: HeaderErrorCode) !InterfaceValue {
        const payload = try allocator.create(InterfaceValue);
        payload.* = .{ .variant_val = .{ .discriminant = @intFromEnum(code), .payload = null } };
        return .{ .result_val = .{ .is_ok = false, .payload = payload } };
    }

    /// Build a `result<X, http error-code>` err InterfaceValue.
    fn httpResultErr(allocator: Allocator, code: HttpErrorCode) !InterfaceValue {
        const payload = try allocator.create(InterfaceValue);
        payload.* = .{ .variant_val = .{ .discriminant = @intFromEnum(code), .payload = null } };
        return .{ .result_val = .{ .is_ok = false, .payload = payload } };
    }

    fn httpResultOk(allocator: Allocator, value: InterfaceValue) !InterfaceValue {
        const payload = try allocator.create(InterfaceValue);
        payload.* = value;
        return .{ .result_val = .{ .is_ok = true, .payload = payload } };
    }

    fn httpBytesValue(ci: *ComponentInstance, bytes: []const u8) !InterfaceValue {
        // Empty strings still need a non-null pointer to satisfy
        // wit-bindgen 0.45's `NonNull::new_unchecked` precondition
        // on lifted `String`/`Vec<u8>` (#538).
        const ptr = if (bytes.len == 0)
            (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
        else
            (ci.hostAllocAndWrite(bytes, 1) orelse return error.OutOfMemory);
        return .{ .string = .{ .ptr = ptr, .len = @intCast(bytes.len) } };
    }

    fn httpOptionBytes(ci: *ComponentInstance, allocator: Allocator, maybe_bytes: ?[]const u8) !InterfaceValue {
        const bytes = maybe_bytes orelse
            return .{ .option_val = .{ .is_some = false, .payload = null } };
        const payload = try allocator.create(InterfaceValue);
        payload.* = try httpBytesValue(ci, bytes);
        return .{ .option_val = .{ .is_some = true, .payload = payload } };
    }

    fn httpVariantWithOptionalBytes(
        ci: *ComponentInstance,
        allocator: Allocator,
        discriminant: u32,
        maybe_bytes: ?[]const u8,
    ) !InterfaceValue {
        const payload: ?*InterfaceValue = if (maybe_bytes) |bytes| blk: {
            const p = try allocator.create(InterfaceValue);
            p.* = try httpBytesValue(ci, bytes);
            break :blk p;
        } else null;
        return .{ .variant_val = .{ .discriminant = discriminant, .payload = payload } };
    }

    // Generic table push/lookup helpers for http resources. We reuse
    // the slot-reuse pattern from sockets so the table doesn't grow
    // unbounded as guests churn handles. Slot 0 is reserved as the
    // "null handle" — wit-bindgen 0.45 asserts `handle != 0` on every
    // host-returned resource handle (#538), so we always allocate
    // from index 1.
    //
    // Combined with the canon-ABI lift/lower `encodeResourceWire` /
    // `decodeResourceWire` offset (#520 wave 2 / PR #560), this gives
    // a defence-in-depth wire convention for every http host table
    // (#562):
    //
    //   wire = host_slot + 1 (applied by executor.zig / canonical_abi.zig)
    //
    //  Reserving slot 0 here means that if a guest does pass `wire = 0`
    //  (e.g. via wit-bindgen's `Option<Resource<T>>::None` round-trip
    //  bug, or a hand-written wasm passing a sentinel), the canon-ABI
    //  lift maps `wire 0 → slot 0`, and `lookup*` finds a null slot
    //  and returns null. Without the slot-0 reservation, a 0-based
    //  table would silently return the first allocated entry for a
    //  null wire — the precise bug PR #560 fixed for sockets +
    //  filesystem and that this PR extends to the http tables listed
    //  in #562 (`http_outgoing_responses`, `http_outgoing_requests`,
    //  `http_outgoing_bodies`, `http_incoming_responses`,
    //  `http_incoming_requests`, `http_incoming_bodies`, `http_fields`,
    //  `http_future_trailers` — and, for symmetry,
    //  `http_future_responses`, `http_response_outparams`, and
    //  `http_request_options`).
    fn pushHttpFields(self: *WasiCliAdapter, f: *HttpFields) !u32 {
        return self.http_fields_table.publish(f);
    }
    fn lookupHttpFields(self: *WasiCliAdapter, h: u32) ?HttpFieldsLease {
        const lease = self.http_fields_table.acquire(h) orelse return null;
        return lockPointerLease(HttpFieldsTable, HttpFields, lease);
    }
    fn pushOutgoingRequest(self: *WasiCliAdapter, r: *OutgoingRequest) !u32 {
        return self.http_outgoing_requests.publish(r);
    }
    fn lookupOutgoingRequest(self: *WasiCliAdapter, h: u32) ?OutgoingRequestLease {
        const lease = self.http_outgoing_requests.acquire(h) orelse return null;
        return lockPointerLease(OutgoingRequestTable, OutgoingRequest, lease);
    }
    fn pushIncomingRequest(self: *WasiCliAdapter, r: *IncomingRequest) !u32 {
        return self.http_incoming_requests.publish(r);
    }
    fn lookupIncomingRequest(self: *WasiCliAdapter, h: u32) ?IncomingRequestLease {
        const lease = self.http_incoming_requests.acquire(h) orelse return null;
        return lockPointerLease(IncomingRequestTable, IncomingRequest, lease);
    }
    fn pushOutgoingResponse(self: *WasiCliAdapter, r: *OutgoingResponse) !u32 {
        return self.http_outgoing_responses.publish(r);
    }
    fn lookupOutgoingResponse(self: *WasiCliAdapter, h: u32) ?OutgoingResponseLease {
        const lease = self.http_outgoing_responses.acquire(h) orelse return null;
        return lockPointerLease(OutgoingResponseTable, OutgoingResponse, lease);
    }
    fn pushOutgoingBody(self: *WasiCliAdapter, b: *OutgoingBody) !u32 {
        return self.http_outgoing_bodies.publish(b);
    }
    fn pushFutureResponse(self: *WasiCliAdapter, f: *FutureIncomingResponse) !u32 {
        return self.http_future_responses.publish(f);
    }
    fn lookupFutureResponse(self: *WasiCliAdapter, h: u32) ?FutureIncomingResponseLease {
        const lease = self.http_future_responses.acquire(h) orelse return null;
        return lockPointerLease(
            FutureIncomingResponseTable,
            FutureIncomingResponse,
            lease,
        );
    }
    fn pushFutureTrailers(self: *WasiCliAdapter, f: *FutureTrailers) !u32 {
        return self.http_future_trailers.publish(f);
    }
    fn lookupFutureTrailers(self: *WasiCliAdapter, h: u32) ?FutureTrailersLease {
        const lease = self.http_future_trailers.acquire(h) orelse return null;
        return lockPointerLease(FutureTrailersTable, FutureTrailers, lease);
    }
    fn pushRequestOptions(self: *WasiCliAdapter, r: *RequestOptions) !u32 {
        return self.http_request_options.publish(r);
    }
    fn lookupRequestOptions(self: *WasiCliAdapter, h: u32) ?RequestOptionsLease {
        const lease = self.http_request_options.acquire(h) orelse return null;
        return lockPointerLease(RequestOptionsTable, RequestOptions, lease);
    }
    fn pushResponseOutparam(self: *WasiCliAdapter, r: *ResponseOutparam) !u32 {
        return self.http_response_outparams.publish(r);
    }
    fn lookupResponseOutparam(self: *WasiCliAdapter, h: u32) ?ResponseOutparamLease {
        const lease = self.http_response_outparams.acquire(h) orelse return null;
        return lockPointerLease(ResponseOutparamTable, ResponseOutparam, lease);
    }
    fn pushIncomingResponse(self: *WasiCliAdapter, r: *IncomingResponse) !u32 {
        return self.http_incoming_responses.publish(r);
    }
    fn lookupIncomingResponse(self: *WasiCliAdapter, h: u32) ?IncomingResponseLease {
        const lease = self.http_incoming_responses.acquire(h) orelse return null;
        return lockPointerLease(IncomingResponseTable, IncomingResponse, lease);
    }
    fn pushIncomingBody(self: *WasiCliAdapter, b: *IncomingBody) !u32 {
        return self.http_incoming_bodies.publish(b);
    }
    fn lookupIncomingBody(self: *WasiCliAdapter, h: u32) ?IncomingBodyLease {
        const lease = self.http_incoming_bodies.acquire(h) orelse return null;
        return lockPointerLease(IncomingBodyTable, IncomingBody, lease);
    }
    fn lookupOutgoingBody(self: *WasiCliAdapter, h: u32) ?OutgoingBodyLease {
        const lease = self.http_outgoing_bodies.acquire(h) orelse return null;
        return lockPointerLease(OutgoingBodyTable, OutgoingBody, lease);
    }

    fn copyOutgoingBodyBytes(self: *WasiCliAdapter, handle: u32) !?[]u8 {
        var body_lease = self.lookupOutgoingBody(handle) orelse return null;
        defer body_lease.release();
        const body = body_lease.lock().*;
        defer body_lease.unlock();
        const owner = body.stream_owner orelse return null;
        owner.operation_claim.acquire();
        defer owner.operation_claim.release();
        return try self.allocator.dupe(u8, owner.stream.getBufferContents());
    }

    fn removeAllResources(self: *WasiCliAdapter, table: anytype) void {
        const handles = table.snapshotHandles(self.allocator) catch
            @panic("failed to snapshot adapter resource handles");
        defer self.allocator.free(handles);
        for (handles) |handle| _ = table.remove(handle);
    }

    fn cleanupHttpResources(self: *WasiCliAdapter) void {
        const outgoing_body_handles = self.http_outgoing_bodies.snapshotHandles(self.allocator) catch
            @panic("failed to snapshot outgoing-body handles");
        defer self.allocator.free(outgoing_body_handles);
        for (outgoing_body_handles) |handle| {
            var lease = self.lookupOutgoingBody(handle) orelse continue;
            const body = lease.lock().*;
            const owner = body.stream_owner;
            body.stream_owner = null;
            lease.unlock();
            if (owner) |owned| owned.release();
            lease.release();
        }

        self.removeAllResources(&self.http_fields_table);
        self.removeAllResources(&self.http_outgoing_requests);
        self.removeAllResources(&self.http_incoming_requests);
        self.removeAllResources(&self.http_outgoing_responses);
        self.removeAllResources(&self.http_incoming_responses);
        self.removeAllResources(&self.http_request_options);
        self.removeAllResources(&self.http_response_outparams);
        self.removeAllResources(&self.http_incoming_bodies);
        self.removeAllResources(&self.http_outgoing_bodies);
        self.removeAllResources(&self.http_future_responses);
        self.removeAllResources(&self.http_future_trailers);
    }

    // --- helpers for extracting bytes from InterfaceValue args ---

    /// Extract a byte slice from an InterfaceValue that is either a
    /// `.string` PtrLen or a `.list` PtrLen (both pointing into guest
    /// memory). Returns null on invalid encoding or out-of-bounds
    /// guest memory.
    fn extractArgBytes(ci: *ComponentInstance, arg: InterfaceValue) ?[]const u8 {
        switch (arg) {
            .string => |pl| {
                if (pl.len == 0) return "";
                return ci.readGuestBytes(pl.ptr, pl.len);
            },
            .list => |pl| {
                if (pl.len == 0) return "";
                return ci.readGuestBytes(pl.ptr, pl.len);
            },
            else => return null,
        }
    }

    /// Like `extractArgBytes` but allocates a copy.
    fn extractArgBytesAlloc(
        alloc: Allocator,
        ci: *ComponentInstance,
        arg: InterfaceValue,
    ) !?[]u8 {
        switch (arg) {
            .string => |pl| {
                if (pl.len == 0) return try alloc.dupe(u8, "");
                const src = ci.readGuestBytes(pl.ptr, pl.len) orelse return null;
                return try alloc.dupe(u8, src);
            },
            .list => |pl| {
                if (pl.len == 0) return try alloc.dupe(u8, "");
                const src = ci.readGuestBytes(pl.ptr, pl.len) orelse return null;
                return try alloc.dupe(u8, src);
            },
            else => return null,
        }
    }

    // --- fields ---

    /// `[constructor]fields() -> own<fields>`.
    fn httpFieldsConstructor(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        const f = try self.allocator.create(HttpFields);
        f.* = .{};
        const h = try self.pushHttpFields(f);
        results[0] = .{ .handle = h };
    }

    /// `[static]fields.from-list(list<tuple<field-name, field-value>>)
    ///   -> result<own<fields>, header-error>`.
    ///
    /// The argument is a guest-memory list of `tuple<string, string>`
    /// records. Each element is laid out as four u32s — name.ptr,
    /// name.len, value.ptr, value.len — for a 16-byte stride. We lift
    /// each tuple, copy both strings into adapter-owned heap, and
    /// populate the new `HttpFields.entries`. No header validation is
    /// performed today (a follow-up may reject `.invalid_syntax` per
    /// RFC 7230); guests that round-trip through `entries` get back
    /// what they passed in.
    fn httpFieldsFromList(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0 or results.len == 0) return error.InvalidArgs;
        const list = switch (args[0]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };

        // Lift+validate the input list FIRST so that on
        // `header-error.invalid-syntax` we don't leak the
        // `HttpFields` slot.
        var lifted_entries: []HttpFieldEntry = &.{};
        if (list.len > 0) {
            const mem = ci.canonicalMemory() orelse return error.OutOfBoundsMemory;
            lifted_entries = liftFieldEntries(self.allocator, mem.bytes(), list.ptr, list.len) catch |e| switch (e) {
                error.InvalidFieldSyntax => {
                    results[0] = try httpHeaderErr(allocator, .invalid_syntax);
                    return;
                },
                else => return e,
            };
        }
        errdefer {
            for (lifted_entries) |entry| {
                self.allocator.free(entry.name);
                self.allocator.free(entry.value);
            }
            if (lifted_entries.len > 0) self.allocator.free(lifted_entries);
        }

        const f = try self.allocator.create(HttpFields);
        f.* = .{};
        if (lifted_entries.len > 0) {
            f.entries = .{ .items = lifted_entries, .capacity = lifted_entries.len };
            lifted_entries = &.{}; // ownership transferred — disarm errdefer
        }
        errdefer {
            f.deinit(self.allocator);
            self.allocator.destroy(f);
        }

        const h = try self.pushHttpFields(f);
        results[0] = try httpResultOk(allocator, .{ .handle = h });
    }

    /// `[method]fields.entries(borrow<fields>)
    ///   -> list<tuple<field-name, field-value>>`. Returns the stored
    /// entries as InterfaceValue list of tuples, each tuple containing
    /// a list_val of u8 for name and a list_val of u8 for value.
    fn httpFieldsEntries(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => {
                results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
                return;
            },
        };

        var f_lease = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        };
        defer f_lease.release();
        const f = f_lease.value().*;

        // Lower into canonical `list<tuple<list<u8>, list<u8>>>` PtrLen
        // form (issue #402): each entry is 16 bytes of (ptr,len) pairs
        // backed by guest memory.
        results[0] = .{ .list = try lowerFieldEntriesList(ci, f.entries.items) };
    }

    /// `[method]fields.get(borrow<fields>, field-name)
    ///   -> list<field-value>`.
    fn httpFieldsGet(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var f_lease = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        };
        defer f_lease.release();
        const f = f_lease.value().*;

        // Read name from arg
        const name_bytes: ?[]const u8 = extractArgBytes(ci, args[1]);
        const name_alloc = if (name_bytes == null) try extractArgBytesAlloc(self.allocator, ci, args[1]) else null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const name = name_bytes orelse (name_alloc orelse {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        });

        // `get` on an invalid name returns an empty list — no error
        // (per `test_invalid_field_name` in `http-fields.rs`, #538).
        if (!isValidFieldName(name)) {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        }

        // Fast path: empty entries — return empty list without
        // allocating a lowercase buffer (#552 hot-path budget).
        if (f.entries.items.len == 0) {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        }

        // ASCII case-insensitive compare against each (already-
        // lowercase) entry, avoiding a per-call lowercase allocation
        // for the input name. Collect matching values into a temporary
        // slice so we can hand it to the byte-list-of-byte-lists
        // lowerer in one shot.
        var matches: std.ArrayListUnmanaged([]const u8) = .empty;
        defer matches.deinit(self.allocator);
        for (f.entries.items) |e| {
            if (asciiEqualIgnoreCase(e.name, name)) {
                try matches.append(self.allocator, e.value);
            }
        }
        results[0] = .{ .list = try lowerByteListList(ci, matches.items) };
    }

    /// `[method]fields.has(borrow<fields>, field-name) -> bool`.
    fn httpFieldsHas(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var f_lease = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .bool = false };
            return;
        };
        defer f_lease.release();
        const f = f_lease.value().*;

        const name_bytes: ?[]const u8 = extractArgBytes(ci, args[1]);
        const name_alloc = if (name_bytes == null) try extractArgBytesAlloc(self.allocator, ci, args[1]) else null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const name = name_bytes orelse (name_alloc orelse {
            results[0] = .{ .bool = false };
            return;
        });

        // `has` on an invalid name returns false (no error).
        if (!isValidFieldName(name)) {
            results[0] = .{ .bool = false };
            return;
        }

        // Fast paths: empty entry list (the http-fields fixture
        // sweeps 1024 codepoints through a fresh `Fields::new()` so
        // most calls land here) — and ASCII case-insensitive compare
        // against each (already-lowercase) stored entry, both
        // avoiding the per-call lowercase-buffer allocation (#552).
        if (f.entries.items.len == 0) {
            results[0] = .{ .bool = false };
            return;
        }
        for (f.entries.items) |e| {
            if (asciiEqualIgnoreCase(e.name, name)) {
                results[0] = .{ .bool = true };
                return;
            }
        }
        results[0] = .{ .bool = false };
    }

    /// `[method]fields.append(borrow<fields>, field-name, field-value)
    ///   -> result<_, header-error>`.
    fn httpFieldsAppend(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var f_lease = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        defer f_lease.release();
        const f = f_lease.value().*;
        if (f.immutable) {
            results[0] = try httpHeaderErr(allocator, .immutable);
            return;
        }

        // Lift name+value views first so we can validate before
        // committing any allocations (#538).
        const name_view: ?[]const u8 = extractArgBytes(ci, args[1]);
        const value_view: ?[]const u8 = extractArgBytes(ci, args[2]);
        const name_alloc = if (name_view == null)
            try extractArgBytesAlloc(self.allocator, ci, args[1])
        else
            null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const value_alloc = if (value_view == null)
            try extractArgBytesAlloc(self.allocator, ci, args[2])
        else
            null;
        defer if (value_alloc) |v| self.allocator.free(v);
        const name = name_view orelse (name_alloc orelse {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        });
        const value = value_view orelse (value_alloc orelse {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        });

        if (!isValidFieldName(name) or !isValidFieldValue(value)) {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        }

        const lower_name = try lowercaseFieldName(self.allocator, name);
        errdefer self.allocator.free(lower_name);
        const val_copy = try self.allocator.dupe(u8, value);
        errdefer self.allocator.free(val_copy);

        try f.entries.append(self.allocator, .{ .name = lower_name, .value = val_copy });
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `[method]fields.set(borrow<fields>, field-name, list<field-value>)
    ///   -> result<_, header-error>`.
    fn httpFieldsSet(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var f_lease = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        defer f_lease.release();
        const f = f_lease.value().*;
        if (f.immutable) {
            results[0] = try httpHeaderErr(allocator, .immutable);
            return;
        }

        const name_bytes: ?[]const u8 = extractArgBytes(ci, args[1]);
        const name_alloc = if (name_bytes == null) try extractArgBytesAlloc(self.allocator, ci, args[1]) else null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const name = name_bytes orelse (name_alloc orelse {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        });

        if (!isValidFieldName(name)) {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        }

        // Add new entries from the list of values: canonical
        // `list<list<u8>>` is laid out in guest memory as
        // `n × (u32 ptr, u32 len)` pairs (issue #402).
        const vals_pl = switch (args[2]) {
            .list => |pl| pl,
            else => {
                results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
                return;
            },
        };

        // Validate ALL values before committing any mutation — `set`
        // is atomic per the WIT semantics. We pre-scan values to catch
        // an invalid one without partially clobbering `f.entries`.
        if (vals_pl.len > 0) {
            const mem_for_scan = ci.canonicalMemory() orelse {
                results[0] = try httpHeaderErr(allocator, .invalid_syntax);
                return;
            };
            const stride0: u32 = 8;
            const total0 = std.math.mul(u32, vals_pl.len, stride0) catch return error.InvalidArgs;
            const list_end0 = std.math.add(u32, vals_pl.ptr, total0) catch return error.InvalidArgs;
            if (list_end0 > mem_for_scan.byteLen()) return error.OutOfBoundsMemory;
            var sc: u32 = 0;
            while (sc < vals_pl.len) : (sc += 1) {
                const off = vals_pl.ptr + sc * stride0;
                const inner_ptr = std.mem.readInt(u32, mem_for_scan.data[off..][0..4], .little);
                const inner_len = std.mem.readInt(u32, mem_for_scan.data[off + 4 ..][0..4], .little);
                const inner_bytes: []const u8 = if (inner_len == 0) "" else blk: {
                    const end = std.math.add(u32, inner_ptr, inner_len) catch return error.OutOfBoundsMemory;
                    if (end > mem_for_scan.byteLen()) return error.OutOfBoundsMemory;
                    break :blk mem_for_scan.data[inner_ptr..end];
                };
                if (!isValidFieldValue(inner_bytes)) {
                    results[0] = try httpHeaderErr(allocator, .invalid_syntax);
                    return;
                }
            }
        }

        // Validation succeeded — remove existing entries with this
        // name. Skip the remove walk if the entry list is empty
        // (#552 hot-path budget).
        if (f.entries.items.len > 0) {
            httpFieldsRemoveByNameInsensitive(f, self.allocator, name);
        }

        if (vals_pl.len == 0) {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        }
        const mem = ci.canonicalMemory() orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        const stride: u32 = 8;
        var i: u32 = 0;
        while (i < vals_pl.len) : (i += 1) {
            const off = vals_pl.ptr + i * stride;
            const inner_ptr = std.mem.readInt(u32, mem.data[off..][0..4], .little);
            const inner_len = std.mem.readInt(u32, mem.data[off + 4 ..][0..4], .little);
            const inner_bytes: []const u8 = if (inner_len == 0)
                ""
            else blk: {
                const end = std.math.add(u32, inner_ptr, inner_len) catch return error.OutOfBoundsMemory;
                if (end > mem.byteLen()) return error.OutOfBoundsMemory;
                break :blk mem.data[inner_ptr..end];
            };

            const lower_name = try lowercaseFieldName(self.allocator, name);
            errdefer self.allocator.free(lower_name);
            const val_copy = try self.allocator.dupe(u8, inner_bytes);
            try f.entries.append(self.allocator, .{ .name = lower_name, .value = val_copy });
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `[method]fields.delete(borrow<fields>, field-name)
    ///   -> result<_, header-error>`.
    fn httpFieldsDelete(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var f_lease = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        defer f_lease.release();
        const f = f_lease.value().*;
        if (f.immutable) {
            results[0] = try httpHeaderErr(allocator, .immutable);
            return;
        }

        const name_bytes: ?[]const u8 = extractArgBytes(ci, args[1]);
        const name_alloc = if (name_bytes == null) try extractArgBytesAlloc(self.allocator, ci, args[1]) else null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const name = name_bytes orelse (name_alloc orelse {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        });

        if (!isValidFieldName(name)) {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        }

        // Fast path: empty entries — nothing to remove, no need to
        // build a lowercase buffer (#552 hot-path budget).
        if (f.entries.items.len == 0) {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        }

        httpFieldsRemoveByNameInsensitive(f, self.allocator, name);
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// Remove all entries whose (lowercase) name ASCII-case-matches
    /// `query`. Avoids the per-call lowercase allocation that
    /// `httpFieldsRemoveByName` would require (#552).
    fn httpFieldsRemoveByNameInsensitive(f: *HttpFields, alloc: Allocator, query: []const u8) void {
        var i: usize = 0;
        while (i < f.entries.items.len) {
            if (asciiEqualIgnoreCase(f.entries.items[i].name, query)) {
                alloc.free(f.entries.items[i].name);
                alloc.free(f.entries.items[i].value);
                _ = f.entries.swapRemove(i);
            } else {
                i += 1;
            }
        }
    }

    /// Remove all entries with the given name from an HttpFields.
    /// `name` is expected to be lowercased by the caller — entries
    /// in the table are always lowercase (#538).
    fn httpFieldsRemoveByName(f: *HttpFields, alloc: Allocator, name: []const u8) void {
        var i: usize = 0;
        while (i < f.entries.items.len) {
            if (std.mem.eql(u8, f.entries.items[i].name, name)) {
                alloc.free(f.entries.items[i].name);
                alloc.free(f.entries.items[i].value);
                _ = f.entries.swapRemove(i);
            } else {
                i += 1;
            }
        }
    }

    /// `[method]fields.clone(borrow<fields>) -> own<fields>`.
    fn httpFieldsClone(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0 or results.len == 0) return error.InvalidArgs;
        const src_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };

        const f = try self.allocator.create(HttpFields);
        f.* = .{};
        errdefer {
            f.deinit(self.allocator);
            self.allocator.destroy(f);
        }

        // Deep-copy the source's entries — clone returns a mutable
        // owned `fields` that subsequent mutations on the original
        // must not affect (and vice versa). #538: prior implementation
        // returned an empty `fields`, dropping the entries that the
        // http-fields wasi-p3-testsuite fixture round-trips through
        // `Fields::from_list(...).clone()`.
        if (self.lookupHttpFields(src_handle)) |owned_lease| {
            var src_lease = owned_lease;
            defer src_lease.release();
            const src = src_lease.value().*;
            if (src.entries.items.len > 0) {
                const copied = try self.allocator.alloc(HttpFieldEntry, src.entries.items.len);
                var filled: usize = 0;
                errdefer {
                    for (copied[0..filled]) |e| {
                        self.allocator.free(e.name);
                        self.allocator.free(e.value);
                    }
                    self.allocator.free(copied);
                }
                while (filled < src.entries.items.len) : (filled += 1) {
                    const e = src.entries.items[filled];
                    const name_copy = try self.allocator.dupe(u8, e.name);
                    errdefer self.allocator.free(name_copy);
                    const value_copy = try self.allocator.dupe(u8, e.value);
                    copied[filled] = .{ .name = name_copy, .value = value_copy };
                }
                f.entries = .{ .items = copied, .capacity = copied.len };
            }
        }

        const h = try self.pushHttpFields(f);
        results[0] = .{ .handle = h };
    }

