    /// `[method]outgoing-body.write(borrow)
    ///   -> result<own<output-stream>, _>`. Creates a buffer-backed
    /// output stream and stores it on the body for later retrieval.
    fn httpOutgoingBodyWrite(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var body_lease = self.lookupOutgoingBody(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
            return;
        };
        defer body_lease.release();
        const body = body_lease.lock().*;
        if (body.stream_taken) {
            body_lease.unlock();
            results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
            return;
        }
        body.stream_taken = true;
        const parent_response_handle = body.parent_response_handle;
        body_lease.unlock();

        const s = self.allocator.create(streams.OutputStream) catch |err| {
            const rollback = body_lease.lock().*;
            rollback.stream_taken = false;
            body_lease.unlock();
            return err;
        };
        const live_response = self.activeInboundHttpResponse(ci);
        const live_attached = if (live_response) |session|
            if (parent_response_handle) |response_handle|
                session.attachP2Body(response_handle, handle)
            else
                false
        else
            false;
        s.* = if (live_attached)
            streams.OutputStream.toCallback(.{
                .context = live_response.?,
                .write = struct {
                    fn write(
                        context: ?*anyopaque,
                        bytes: []const u8,
                    ) streams.StreamResult {
                        return if (InboundHttpResponseSession.onBodyWrite(
                            context,
                            bytes,
                        ))
                            .{ .ok = bytes.len }
                        else
                            .{ .closed = {} };
                    }
                }.write,
            })
        else
            streams.OutputStream.toBuffer();
        const sh = self.allocOwnedStreamHandle(s, null, null) catch |err| {
            s.deinit(self.allocator);
            self.allocator.destroy(s);
            const rollback = body_lease.lock().*;
            rollback.stream_taken = false;
            body_lease.unlock();
            return err;
        };
        var stream_lease = self.stream_table.acquire(sh).?;
        const owner = stream_lease.value().owner.?;
        owner.retain();
        stream_lease.release();
        const update = body_lease.lock().*;
        update.stream_owner = owner;
        body_lease.unlock();
        errdefer {
            const rollback = body_lease.lock().*;
            if (rollback.stream_owner) |owned| owned.release();
            rollback.stream_owner = null;
            rollback.stream_taken = false;
            body_lease.unlock();
            std.debug.assert(self.stream_table.remove(sh));
        }
        results[0] = try httpResultOk(allocator, .{ .handle = sh });
    }

