    /// `wasi:http/types.http-error-code(err: borrow<io-error>)
    ///   -> option<error-code>` (#583 A5).
    ///
    /// Downcasts a borrowed `wasi:io/error.error` handle to the HTTP
    /// `error-code` variant it originated from, if any. The host
    /// keeps a separate `http_io_errors` map (handle → `HttpErrorCode`)
    /// that HTTP code can register into when it surfaces a failure as
    /// an io-error rather than as a typed `result<_, error-code>`.
    ///
    /// Returns `some(code)` if the handle is registered in the map,
    /// `none` otherwise — the spec is explicit that "not all
    /// io-errors are http-related errors", so an unknown handle
    /// (including the synthetic null handle 0) is a successful `none`,
    /// not a fault. The variant payload is `null`: payload-bearing
    /// arms (DNS-error, internal-error, etc.) zero-fill in the
    /// canonical-ABI lower (see the comment on
    /// `http_p3_error_code_cases`), giving a valid all-`none` payload.
    fn httpErrorCodeFreeFn(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            .u32 => |h| h,
            else => return error.InvalidArgs,
        };
        self.async_state_claim.acquire();
        const maybe_code = self.http_io_errors.get(handle);
        self.async_state_claim.release();
        const code = maybe_code orelse {
            results[0] = .{ .option_val = .{ .is_some = false, .payload = null } };
            return;
        };
        const inner = try allocator.create(InterfaceValue);
        inner.* = .{
            .variant_val = .{ .discriminant = @intFromEnum(code), .payload = null },
        };
        results[0] = .{ .option_val = .{ .is_some = true, .payload = inner } };
    }

    /// `[static]response-outparam.set(own<response-outparam>,
    ///   result<own<outgoing-response>, error-code>)`.
    fn httpResponseOutparamSet(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var outparam_lease = self.lookupResponseOutparam(handle) orelse
            return error.InvalidHandle;
        defer outparam_lease.release();
        const outparam = outparam_lease.lock().*;
        switch (outparam.state) {
            .unset => {},
            else => {
                outparam_lease.unlock();
                return error.InvalidState;
            },
        }

        var selected_response: ?u32 = null;
        switch (args[1]) {
            .result_val => |rv| {
                const payload = rv.payload orelse {
                    outparam_lease.unlock();
                    return error.InvalidArgs;
                };
                if (rv.is_ok) {
                    const response_handle = switch (payload.*) {
                        .handle => |h| h,
                        else => {
                            outparam_lease.unlock();
                            return error.InvalidArgs;
                        },
                    };
                    outparam.state = .{ .response = response_handle };
                    selected_response = response_handle;
                } else {
                    outparam.state = .{ .err = switch (payload.*) {
                        .variant_val => |v| v.discriminant,
                        .enum_val => |d| d,
                        .u32 => |d| d,
                        else => {
                            outparam_lease.unlock();
                            return error.InvalidArgs;
                        },
                    } };
                }
            },
            .handle => |h| {
                outparam.state = .{ .response = h };
                selected_response = h;
            },
            .variant_val => |v| outparam.state = .{ .err = v.discriminant },
            .enum_val => |d| outparam.state = .{ .err = d },
            .u32 => |d| outparam.state = .{ .err = d },
            else => {
                outparam_lease.unlock();
                return error.InvalidArgs;
            },
        }
        outparam_lease.unlock();

        if (selected_response) |response_handle| {
            if (self.activeInboundHttpResponse(ci)) |session| {
                var response_lease = self.lookupOutgoingResponse(
                    response_handle,
                ) orelse return;
                const body_handle = response_lease.value().*.body_handle;
                response_lease.release();
                _ = session.attachP2Response(response_handle, body_handle);
            }
        }
    }

    fn httpResponseOutparamDrop(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        _ = self.http_response_outparams.remove(handle);
    }

    // --- outgoing-handler ---

    /// `wasi:http/outgoing-handler.handle(own<outgoing-request>,
    ///   option<own<request-options>>)
    ///   -> result<own<future-incoming-response>, error-code>`.
    ///
    /// Performs a real outbound HTTP/HTTPS request via
    /// `std.http.Client.fetch` when `sockets_allow_list_template` is
    /// non-empty. TLS is delegated to `std.crypto.tls` (#521 — the
    /// earlier `HTTP_protocol_error` short-circuit added by #477 /
    /// #501 has been removed now that Zig 0.16 ships a working TLS
    /// client).
    ///
    /// (#583 A2) The host mints a `.pending` `FutureIncomingResponse`
    /// and dispatches the blocking fetch onto a worker thread; the
    /// adapter's `drainPendingHttpFetches` driver (invoked from
    /// `driveAsyncEvents` and `anyPollableReady`) settles the future
    /// once the worker publishes its outcome. The guest's
    /// `pollable.block` over `future-incoming-response.subscribe` is
    /// no longer a no-op. The empty allow-list / malformed-request /
    /// invalid-URL paths still settle the future to `.ready_err`
    /// synchronously — only the actual network round-trip is deferred.
    ///
    /// (#583 A3) Transport / TLS / DNS / parse failures returned by
    /// the worker thread are routed through `mapHttpFetchError` so
    /// each classified `std.http.Client.FetchError` member lands on
    /// its specific `wasi:http/types.error-code` variant
    /// (`connection_refused`, `TLS_protocol_error`, `DNS_error`, …),
    /// with `internal_error` reserved for genuinely unclassified
    /// errors. See `mapHttpFetchError` for the full table.
    fn httpOutgoingHandlerHandle(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;

        // Extract request handle
        const req_handle: u32 = if (args.len > 0) switch (args[0]) {
            .handle => |h| h,
            else => 0,
        } else 0;

        // Deny when allow-list is empty — synchronous ready-err.
        if (!self.hasSocketsAllowList()) {
            return httpHandlerDeny(self, results, allocator, .HTTP_request_denied);
        }

        var req_lease = self.lookupOutgoingRequest(req_handle) orelse {
            return httpHandlerDeny(self, results, allocator, .HTTP_request_denied);
        };
        defer req_lease.release();
        const r = req_lease.value().*;

        // Build scheme string. `std.http.Client.fetch` handles `http`
        // and `https` natively (TLS via `std.crypto.tls`, #521). Any
        // other scheme value falls through to `Uri.parse`, which will
        // reject it in the worker and surface as `internal_error`.
        const scheme: []const u8 = if (r.scheme_disc) |d| switch (d) {
            0 => "http",
            1 => "https",
            else => if (r.scheme_other) |s| s else "https",
        } else "https";

        const authority = r.authority orelse {
            return httpHandlerDeny(self, results, allocator, .HTTP_request_URI_invalid);
        };
        const path = r.path_with_query orelse "/";

        // Build URL
        const url = std.fmt.allocPrint(self.allocator, "{s}://{s}{s}", .{ scheme, authority, path }) catch {
            return httpHandlerDeny(self, results, allocator, .internal_error);
        };
        defer self.allocator.free(url);

        // Map WIT method discriminant to std.http.Method
        const method: std.http.Method = switch (r.method_disc) {
            0 => .GET,
            1 => .HEAD,
            2 => .POST,
            3 => .PUT,
            4 => .DELETE,
            5 => .CONNECT,
            6 => .OPTIONS,
            7 => .TRACE,
            8 => .PATCH,
            else => .GET,
        };

        // Collect request headers
        var headers_fields_lease = self.lookupHttpFields(r.headers_handle);
        defer if (headers_fields_lease) |*lease| lease.release();
        var extra_hdrs: std.ArrayListUnmanaged(std.http.Header) = .empty;
        defer extra_hdrs.deinit(self.allocator);
        if (headers_fields_lease) |*lease| {
            const hf = lease.value().*;
            for (hf.entries.items) |e| {
                extra_hdrs.append(self.allocator, .{
                    .name = e.name,
                    .value = e.value,
                }) catch break;
            }
        }

        // Get body payload bytes (if any). Borrowed slice — the
        // worker spawns with its own duped copy below.
        var payload: ?[]const u8 = null;
        var payload_owned: ?[]u8 = null;
        defer if (payload_owned) |contents| self.allocator.free(contents);
        if (r.body_handle) |bh| {
            if (try self.copyOutgoingBodyBytes(bh)) |contents| {
                payload_owned = contents;
                if (contents.len > 0) payload = contents;
            }
        }

        // Snapshot the option resource before spawning. The
        // option<own<request-options>> handle may be dropped as soon
        // as this host call returns, so the worker must only receive
        // scalar-owned state.
        const fetch_options = self.httpFetchOptionsP2(args);

        // Spawn worker that drives the fetch off-thread. Returns the
        // freshly minted `.pending` future handle the guest will
        // poll on via `future-incoming-response.subscribe`. Worker
        // failures (alloc, thread spawn) collapse to a synchronous
        // ready-err future so the caller always observes a usable
        // handle. The blocking `std.http.Client.fetch` itself runs
        // on the worker thread and routes its classified errors
        // through `mapHttpFetchError` (#583 A3) before publishing.
        const fh = self.spawnHttpFetchPending(
            url,
            method,
            extra_hdrs.items,
            payload,
            fetch_options,
        ) catch {
            return httpHandlerDeny(self, results, allocator, .internal_error);
        };
        results[0] = try httpResultOk(allocator, .{ .handle = fh });
    }

    /// Helper: return a denied-style future from the outgoing handler.
    fn httpHandlerDeny(
        self: *WasiCliAdapter,
        results: []InterfaceValue,
        allocator: Allocator,
        code: HttpErrorCode,
    ) anyerror!void {
        const fut = try self.allocator.create(FutureIncomingResponse);
        fut.* = .{ .state = .{ .ready_err = @intFromEnum(code) } };
        const h = try self.pushFutureResponse(fut);
        results[0] = try httpResultOk(allocator, .{ .handle = h });
    }

    const HttpTargetParts = struct {
        scheme_disc: u32,
        authority: ?[]const u8,
        path_with_query: []const u8,
    };

    fn httpHeaderEnd(bytes: []const u8) ?usize {
        const idx = std.mem.indexOf(u8, bytes, "\r\n\r\n") orelse return null;
        return idx + 4;
    }

    fn httpMethodDiscriminant(method: []const u8) u32 {
        if (std.mem.eql(u8, method, "GET")) return 0;
        if (std.mem.eql(u8, method, "HEAD")) return 1;
        if (std.mem.eql(u8, method, "POST")) return 2;
        if (std.mem.eql(u8, method, "PUT")) return 3;
        if (std.mem.eql(u8, method, "DELETE")) return 4;
        if (std.mem.eql(u8, method, "CONNECT")) return 5;
        if (std.mem.eql(u8, method, "OPTIONS")) return 6;
        if (std.mem.eql(u8, method, "TRACE")) return 7;
        if (std.mem.eql(u8, method, "PATCH")) return 8;
        return 9;
    }

    fn splitHttpTarget(target: []const u8) HttpTargetParts {
        const Prefix = struct { text: []const u8, scheme: u32 };
        const prefixes = [_]Prefix{
            .{ .text = "http://", .scheme = 0 },
            .{ .text = "https://", .scheme = 1 },
        };
        for (prefixes) |prefix| {
            if (!std.mem.startsWith(u8, target, prefix.text)) continue;
            const rest = target[prefix.text.len..];
            const slash = std.mem.indexOfScalar(u8, rest, '/') orelse rest.len;
            return .{
                .scheme_disc = prefix.scheme,
                .authority = rest[0..slash],
                .path_with_query = if (slash < rest.len) rest[slash..] else "/",
            };
        }
        return .{
            .scheme_disc = 0,
            .authority = null,
            .path_with_query = target,
        };
    }

    fn httpContentLengthFromHeaderBlock(header_block: []const u8) !usize {
        var lines = std.mem.splitSequence(u8, header_block, "\r\n");
        _ = lines.next() orelse return error.HttpBadRequest;
        var content_length: ?usize = null;
        while (lines.next()) |line| {
            if (line.len == 0) break;
            if (line[0] == ' ' or line[0] == '\t') return error.HttpBadRequest;
            const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.HttpBadRequest;
            const name = std.mem.trim(u8, line[0..colon], " \t");
            const value = std.mem.trim(u8, line[colon + 1 ..], " \t");
            if (name.len == 0) return error.HttpBadRequest;
            if (std.ascii.eqlIgnoreCase(name, "transfer-encoding") and
                !std.ascii.eqlIgnoreCase(value, "identity"))
            {
                return error.HttpUnsupportedTransferCoding;
            }
            if (std.ascii.eqlIgnoreCase(name, "content-length")) {
                const parsed = std.fmt.parseInt(usize, value, 10) catch return error.HttpBadRequest;
                if (content_length) |prev| {
                    if (prev != parsed) return error.HttpBadRequest;
                } else {
                    content_length = parsed;
                }
            }
        }
        return content_length orelse 0;
    }

    /// Framing info derived from a parsed HTTP/1.1 request header
    /// block — used by the 0.3 incoming-handler path (#583 A5) to
    /// decide between Content-Length framing, chunked decoding, and
    /// whether the connection should stay open for another round trip.
    const HttpRequestBodyKind = union(enum) {
        /// No body declared — treat as a zero-length body.
        none,
        /// `Content-Length: N` — read exactly N bytes for the body.
        content_length: usize,
        /// `Transfer-Encoding: chunked` — stream-decode chunks until
        /// the terminating `0\r\n\r\n`. Body length is unknown
        /// up-front and bounded by `max_http_p3_body_bytes`.
        chunked,
    };
    const HttpRequestHeaderInfo = struct {
        body_kind: HttpRequestBodyKind,
        /// Connection-scoped keep-alive after this round-trip. HTTP/1.1
        /// defaults to true (RFC 7230 §6.3) unless `Connection: close`
        /// is set; HTTP/1.0 defaults to false unless `Connection:
        /// keep-alive` is set.
        keep_alive: bool,
    };

    /// Parse the request-line + headers for framing & keep-alive
    /// info. Used by `readIncomingRequestP3FromStream` (#583 A5) to
    /// honor chunked transfer-encoding requests and keep the TCP
    /// connection alive across multiple round-trips. The mirror
    /// `httpContentLengthFromHeaderBlock` stays for the 0.2 surface
    /// where chunked is still unsupported.
    pub fn httpRequestHeaderInfoFromBlock(header_block: []const u8) !HttpRequestHeaderInfo {
        var lines = std.mem.splitSequence(u8, header_block, "\r\n");
        const request_line = lines.next() orelse return error.HttpBadRequest;
        const is_http_10 = std.mem.endsWith(u8, request_line, " HTTP/1.0");

        var content_length: ?usize = null;
        var transfer_chunked = false;
        var seen_other_transfer_coding = false;
        var keep_alive_hint: ?bool = null;

        while (lines.next()) |line| {
            if (line.len == 0) break;
            if (line[0] == ' ' or line[0] == '\t') return error.HttpBadRequest;
            const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.HttpBadRequest;
            const name = std.mem.trim(u8, line[0..colon], " \t");
            const value = std.mem.trim(u8, line[colon + 1 ..], " \t");
            if (name.len == 0) return error.HttpBadRequest;
            if (std.ascii.eqlIgnoreCase(name, "transfer-encoding")) {
                var tokens = std.mem.tokenizeAny(u8, value, ", \t");
                while (tokens.next()) |tok| {
                    if (std.ascii.eqlIgnoreCase(tok, "chunked")) {
                        transfer_chunked = true;
                    } else if (!std.ascii.eqlIgnoreCase(tok, "identity")) {
                        seen_other_transfer_coding = true;
                    }
                }
            } else if (std.ascii.eqlIgnoreCase(name, "content-length")) {
                const parsed = std.fmt.parseInt(usize, value, 10) catch return error.HttpBadRequest;
                if (content_length) |prev| {
                    if (prev != parsed) return error.HttpBadRequest;
                } else {
                    content_length = parsed;
                }
            } else if (std.ascii.eqlIgnoreCase(name, "connection")) {
                var tokens = std.mem.tokenizeAny(u8, value, ", \t");
                while (tokens.next()) |tok| {
                    if (std.ascii.eqlIgnoreCase(tok, "close")) {
                        keep_alive_hint = false;
                    } else if (std.ascii.eqlIgnoreCase(tok, "keep-alive")) {
                        keep_alive_hint = true;
                    }
                }
            }
        }
        if (seen_other_transfer_coding) return error.HttpUnsupportedTransferCoding;

        // RFC 7230 §3.3.3 rule 3: when both Transfer-Encoding and
        // Content-Length are present, the latter is ignored (and the
        // sender is treated as a smuggling attempt). We honor chunked.
        const body_kind: HttpRequestBodyKind = if (transfer_chunked)
            .chunked
        else if (content_length) |n|
            .{ .content_length = n }
        else
            .none;

        const keep_alive = if (keep_alive_hint) |h| h else !is_http_10;
        return .{ .body_kind = body_kind, .keep_alive = keep_alive };
    }

    /// Buffered line + exact-bytes reader over an `InputStream`
    /// (#583 A5). Keep-alive and chunked transfer-encoding need to
    /// read line-delimited framing then a body whose length depends
    /// on those lines; this shim absorbs any over-read tail so we
    /// don't lose bytes between framing and body phases.
    pub const BufferedLineReader = struct {
        allocator: Allocator,
        stream: *streams.InputStream,
        buf: std.ArrayListUnmanaged(u8) = .empty,
        pos: usize = 0,
        /// True once at least one byte has been consumed for the
        /// current request — used by the keep-alive loop to detect
        /// "client closed cleanly before sending a new request" vs
        /// "client tore the connection mid-request".
        any_bytes_consumed: bool = false,

        fn deinit(self: *BufferedLineReader) void {
            self.buf.deinit(self.allocator);
        }

        fn refill(self: *BufferedLineReader) !bool {
            var tmp: [4096]u8 = undefined;
            switch (self.stream.read(&tmp)) {
                .ok => |n| {
                    if (n == 0) return false;
                    try self.buf.appendSlice(self.allocator, tmp[0..n]);
                    return true;
                },
                .closed => return false,
                .err => return error.IoError,
            }
        }

        /// Read a single CRLF-terminated line (excluding the CRLF).
        /// Returns `error.HttpConnectionIdleClose` if the stream
        /// closes before any byte of this line is read; bubbles
        /// `error.HttpBadRequest` if it closes mid-line.
        fn readLine(self: *BufferedLineReader, max_total: usize) ![]const u8 {
            const start_consumed = self.any_bytes_consumed;
            while (true) {
                if (std.mem.indexOfPos(u8, self.buf.items, self.pos, "\r\n")) |idx| {
                    const line = self.buf.items[self.pos..idx];
                    self.pos = idx + 2;
                    self.any_bytes_consumed = true;
                    return line;
                }
                if (self.buf.items.len - self.pos > max_total) return error.HttpRequestHeaderTooLarge;
                const got = try self.refill();
                if (!got) {
                    if (!start_consumed and self.buf.items.len == self.pos) {
                        return error.HttpConnectionIdleClose;
                    }
                    return error.HttpBadRequest;
                }
            }
        }

        /// Read exactly `n` bytes, appending into `dst`.
        fn readExactAppend(
            self: *BufferedLineReader,
            dst: *std.ArrayListUnmanaged(u8),
            n: usize,
            max_total: usize,
        ) !void {
            var remaining = n;
            while (remaining > 0) {
                const avail = self.buf.items.len - self.pos;
                if (avail > 0) {
                    const take = @min(avail, remaining);
                    if (dst.items.len + take > max_total) return error.HttpRequestBodyTooLarge;
                    try dst.appendSlice(self.allocator, self.buf.items[self.pos..][0..take]);
                    self.pos += take;
                    remaining -= take;
                    self.any_bytes_consumed = true;
                    continue;
                }
                const got = try self.refill();
                if (!got) return error.HttpBadRequest;
            }
        }

        /// Compact the internal buffer (drop already-consumed bytes).
        /// Called between requests on a keep-alive connection so the
        /// next round-trip starts from offset 0.
        fn compact(self: *BufferedLineReader) void {
            if (self.pos == 0) return;
            const tail = self.buf.items.len - self.pos;
            if (tail > 0) {
                std.mem.copyForwards(u8, self.buf.items[0..tail], self.buf.items[self.pos..]);
            }
            self.buf.shrinkRetainingCapacity(tail);
            self.pos = 0;
            self.any_bytes_consumed = false;
        }
    };

    /// Read one complete HTTP/1.1 request from `stream` and create an
    /// `incoming-request` resource. First-slice server mode supports
    /// Content-Length bodies and closes after one response.
    pub fn readIncomingRequestFromStream(
        self: *WasiCliAdapter,
        stream: *streams.InputStream,
    ) !u32 {
        var bytes: std.ArrayListUnmanaged(u8) = .empty;
        defer bytes.deinit(self.allocator);

        var header_end: ?usize = null;
        var tmp: [4096]u8 = undefined;
        while (header_end == null) {
            const n = switch (stream.read(&tmp)) {
                .ok => |count| count,
                .closed => return error.HttpBadRequest,
                .err => return error.IoError,
            };
            try bytes.appendSlice(self.allocator, tmp[0..n]);
            if (bytes.items.len > max_http_header_bytes) return error.HttpRequestHeaderTooLarge;
            header_end = httpHeaderEnd(bytes.items);
        }

        const end = header_end.?;
        const body_len = try httpContentLengthFromHeaderBlock(bytes.items[0..end]);
        if (body_len > max_http_body_bytes) return error.HttpRequestBodyTooLarge;
        const total_len = std.math.add(usize, end, body_len) catch return error.HttpRequestBodyTooLarge;
        while (bytes.items.len < total_len) {
            const n = switch (stream.read(&tmp)) {
                .ok => |count| count,
                .closed => return error.HttpBadRequest,
                .err => return error.IoError,
            };
            try bytes.appendSlice(self.allocator, tmp[0..n]);
            if (bytes.items.len > total_len) break;
        }
        if (bytes.items.len < total_len) return error.HttpBadRequest;
        return self.createIncomingRequestFromHttpBytes(bytes.items[0..total_len]);
    }

    /// Parse a complete HTTP/1.1 request and create an `incoming-request`
    /// resource. This is used by both the TCP server loop and unit tests.
    pub fn createIncomingRequestFromHttpBytes(
        self: *WasiCliAdapter,
        request_bytes: []const u8,
    ) !u32 {
        const header_end = httpHeaderEnd(request_bytes) orelse return error.HttpBadRequest;
        if (header_end > max_http_header_bytes) return error.HttpRequestHeaderTooLarge;
        const header_block = request_bytes[0..header_end];
        const body_len = try httpContentLengthFromHeaderBlock(header_block);
        if (body_len > max_http_body_bytes) return error.HttpRequestBodyTooLarge;
        const total_len = std.math.add(usize, header_end, body_len) catch return error.HttpRequestBodyTooLarge;
        if (request_bytes.len < total_len) return error.HttpBadRequest;

        var lines = std.mem.splitSequence(u8, header_block[0 .. header_end - 4], "\r\n");
        const request_line = lines.next() orelse return error.HttpBadRequest;
        var tokens = std.mem.tokenizeScalar(u8, request_line, ' ');
        const method = tokens.next() orelse return error.HttpBadRequest;
        const target = tokens.next() orelse return error.HttpBadRequest;
        const version = tokens.next() orelse return error.HttpBadRequest;
        if (tokens.next() != null) return error.HttpBadRequest;
        if (method.len == 0 or target.len == 0) return error.HttpBadRequest;
        if (target.len > max_http_target_bytes) return error.HttpRequestUriTooLong;
        if (!std.mem.eql(u8, version, "HTTP/1.1")) return error.HttpBadRequest;

        const target_parts = splitHttpTarget(target);
        var host_header: ?[]const u8 = null;

        const fields = try self.allocator.create(HttpFields);
        fields.* = .{ .immutable = true };
        var fields_owned = true;
        errdefer if (fields_owned) {
            fields.deinit(self.allocator);
            self.allocator.destroy(fields);
        };

        while (lines.next()) |line| {
            if (line.len == 0) break;
            if (line[0] == ' ' or line[0] == '\t') return error.HttpBadRequest;
            const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.HttpBadRequest;
            const name = std.mem.trim(u8, line[0..colon], " \t");
            const value = std.mem.trim(u8, line[colon + 1 ..], " \t");
            if (name.len == 0) return error.HttpBadRequest;
            const name_copy = try self.allocator.dupe(u8, name);
            const value_copy = self.allocator.dupe(u8, value) catch |err| {
                self.allocator.free(name_copy);
                return err;
            };
            fields.entries.append(self.allocator, .{ .name = name_copy, .value = value_copy }) catch |err| {
                self.allocator.free(name_copy);
                self.allocator.free(value_copy);
                return err;
            };
            if (std.ascii.eqlIgnoreCase(name, "host") and host_header == null) {
                host_header = value_copy;
            }
        }

        var method_other: ?[]u8 = null;
        errdefer if (method_other) |s| self.allocator.free(s);
        const method_disc = httpMethodDiscriminant(method);
        if (method_disc == 9) method_other = try self.allocator.dupe(u8, method);

        var path_copy: ?[]u8 = try self.allocator.dupe(u8, target_parts.path_with_query);
        errdefer if (path_copy) |s| self.allocator.free(s);

        var authority_copy: ?[]u8 = null;
        errdefer if (authority_copy) |s| self.allocator.free(s);
        const authority = target_parts.authority orelse host_header;
        if (authority) |a| authority_copy = try self.allocator.dupe(u8, a);

        var body_copy: ?[]u8 = null;
        errdefer if (body_copy) |s| self.allocator.free(s);
        if (body_len > 0) {
            body_copy = try self.allocator.dupe(u8, request_bytes[header_end..total_len]);
        }

        const fields_handle = try self.pushHttpFields(fields);
        fields_owned = false;
        errdefer {
            if (self.http_fields_table.withdraw(fields_handle)) |withdrawn| {
                std.debug.assert(withdrawn == fields);
                withdrawn.deinit(self.allocator);
                self.allocator.destroy(withdrawn);
            }
        }

        const req = try self.allocator.create(IncomingRequest);
        errdefer {
            req.deinit(self.allocator);
            self.allocator.destroy(req);
        }
        req.* = .{
            .method_disc = method_disc,
            .method_other = method_other,
            .path_with_query = path_copy,
            .scheme_disc = target_parts.scheme_disc,
            .authority = authority_copy,
            .headers_handle = fields_handle,
            .body_data = body_copy,
        };
        method_other = null;
        path_copy = null;
        authority_copy = null;
        body_copy = null;

        return self.pushIncomingRequest(req);
    }

    fn httpResponseStatusReason(status: u16) []const u8 {
        return switch (status) {
            200 => "OK",
            201 => "Created",
            202 => "Accepted",
            204 => "No Content",
            400 => "Bad Request",
            404 => "Not Found",
            405 => "Method Not Allowed",
            413 => "Payload Too Large",
            414 => "URI Too Long",
            431 => "Request Header Fields Too Large",
            500 => "Internal Server Error",
            501 => "Not Implemented",
            502 => "Bad Gateway",
            503 => "Service Unavailable",
            else => "OK",
        };
    }

    fn httpHeaderNameValid(name: []const u8) bool {
        if (name.len == 0) return false;
        for (name) |c| {
            if (std.ascii.isAlphanumeric(c)) continue;
            switch (c) {
                '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~' => {},
                else => return false,
            }
        }
        return true;
    }

    fn httpHeaderValueValid(value: []const u8) bool {
        for (value) |c| {
            if (c == '\t') continue;
            if (c < 0x20 or c == 0x7f) return false;
        }
        return true;
    }

    fn httpStatusFromError(code: u32) u16 {
        return switch (@as(HttpErrorCode, @enumFromInt(@min(code, @intFromEnum(HttpErrorCode.internal_error))))) {
            .HTTP_request_length_required => 411,
            .HTTP_request_body_size => 413,
            .HTTP_request_method_invalid,
            .HTTP_request_URI_invalid,
            .HTTP_request_header_section_size,
            .HTTP_request_header_size,
            .HTTP_request_trailer_section_size,
            .HTTP_request_trailer_size,
            .HTTP_protocol_error,
            => 400,
            .HTTP_request_URI_too_long => 414,
            .destination_not_found => 502,
            .destination_unavailable => 503,
            else => 500,
        };
    }

    /// Largest slice handed to the client socket in one write.
    ///
    /// Bounds how far a response can run past a disconnect before the
    /// host notices, and bounds the kernel-side queueing a single
    /// guest response can demand (#616 A8). 64 KiB matches the
    /// outbound body-chunk size and comfortably exceeds a TLS record,
    /// so it costs no extra syscalls in the common case.
    const http_response_chunk_bytes: usize = http_live_response_buffer_bytes;

    fn writeAllOutputStream(
        self: *WasiCliAdapter,
        out: *streams.OutputStream,
        bytes: []const u8,
    ) !void {
        switch (out.write(bytes, self.allocator)) {
            .ok => |n| if (n != bytes.len) return error.IoError,
            // `.closed` is the peer hanging up, which is a normal
            // client behaviour rather than a server fault; callers
            // must distinguish it so they can abandon the response and
            // drop keep-alive instead of reporting an error (#616 A8).
            .closed => return error.HttpClientDisconnected,
            .err => return error.IoError,
        }
    }

    /// Write a response body to the client in bounded slices.
    ///
    /// A single `writeAll` of a large body hands everything to the
    /// socket layer at once, so a client that disappears part-way
    /// through is only noticed after the whole transfer has been
    /// attempted. Slicing the write means a disconnect surfaces within
    /// one chunk, and the host never queues an unbounded amount of a
    /// guest's response at once (#616 A8).
    ///
    /// The wire bytes are identical: this only changes how many
    /// `write` calls carry them.
    fn writeHttpBodyChunked(
        self: *WasiCliAdapter,
        out: *streams.OutputStream,
        body: []const u8,
    ) !void {
        var offset: usize = 0;
        while (offset < body.len) {
            const end = @min(offset + http_response_chunk_bytes, body.len);
            try self.writeAllOutputStream(out, body[offset..end]);
            offset = end;
        }
    }

    fn writeHttpSimpleResponse(
        self: *WasiCliAdapter,
        out: *streams.OutputStream,
        status: u16,
        body: []const u8,
    ) !void {
        const status_line = try std.fmt.allocPrint(
            self.allocator,
            "HTTP/1.1 {d} {s}\r\nContent-Length: {d}\r\nConnection: close\r\n\r\n",
            .{ status, httpResponseStatusReason(status), body.len },
        );
        defer self.allocator.free(status_line);
        try self.writeAllOutputStream(out, status_line);
        try self.writeAllOutputStream(out, body);
    }

    /// Serialize a `response-outparam` result as an HTTP/1.1 response.
    pub fn writeHttpResponseFromOutparam(
        self: *WasiCliAdapter,
        out: *streams.OutputStream,
        outparam_handle: u32,
    ) !void {
        var outparam_lease = self.lookupResponseOutparam(outparam_handle) orelse {
            return self.writeHttpSimpleResponse(out, 500, "missing response outparam\n");
        };
        defer outparam_lease.release();
        const outparam = outparam_lease.value().*;
        switch (outparam.state) {
            .unset => return self.writeHttpSimpleResponse(out, 500, "handler did not set response\n"),
            .err => |code| return self.writeHttpSimpleResponse(out, httpStatusFromError(code), "handler returned error\n"),
            .response => |response_handle| {
                var response_lease = self.lookupOutgoingResponse(response_handle) orelse {
                    return self.writeHttpSimpleResponse(out, 500, "invalid response handle\n");
                };
                defer response_lease.release();
                const response = response_lease.value().*;
                const status: u16 = if (response.status >= 100 and response.status <= 999) response.status else 500;
                var body_owned: ?[]u8 = null;
                defer if (body_owned) |bytes| self.allocator.free(bytes);
                if (response.body_handle) |body_handle| {
                    body_owned = try self.copyOutgoingBodyBytes(body_handle) orelse {
                        return self.writeHttpSimpleResponse(out, 500, "invalid body handle\n");
                    };
                }
                const body: []const u8 = if (body_owned) |bytes| bytes else "";
                var response_fields_lease = self.lookupHttpFields(response.headers_handle);
                defer if (response_fields_lease) |*lease| lease.release();
                if (response_fields_lease) |*lease| {
                    const fields = lease.value().*;
                    for (fields.entries.items) |entry| {
                        if (std.ascii.eqlIgnoreCase(entry.name, "content-length") or
                            std.ascii.eqlIgnoreCase(entry.name, "connection"))
                        {
                            continue;
                        }
                        if (!httpHeaderNameValid(entry.name) or !httpHeaderValueValid(entry.value)) {
                            return self.writeHttpSimpleResponse(out, 500, "invalid response header\n");
                        }
                    }
                }

                const status_line = try std.fmt.allocPrint(
                    self.allocator,
                    "HTTP/1.1 {d} {s}\r\n",
                    .{ status, httpResponseStatusReason(status) },
                );
                defer self.allocator.free(status_line);
                try self.writeAllOutputStream(out, status_line);

                if (response_fields_lease) |*lease| {
                    const fields = lease.value().*;
                    for (fields.entries.items) |entry| {
                        if (std.ascii.eqlIgnoreCase(entry.name, "content-length") or
                            std.ascii.eqlIgnoreCase(entry.name, "connection"))
                        {
                            continue;
                        }
                        const line = try std.fmt.allocPrint(
                            self.allocator,
                            "{s}: {s}\r\n",
                            .{ entry.name, entry.value },
                        );
                        defer self.allocator.free(line);
                        try self.writeAllOutputStream(out, line);
                    }
                }

                const trailer = try std.fmt.allocPrint(
                    self.allocator,
                    "Content-Length: {d}\r\nConnection: close\r\n\r\n",
                    .{body.len},
                );
                defer self.allocator.free(trailer);
                try self.writeAllOutputStream(out, trailer);
                try self.writeHttpBodyChunked(out, body);
            },
        }
    }

    // --- incoming-handler ---

    /// `wasi:http/incoming-handler.handle(own<incoming-request>,
    ///   own<response-outparam>)`. Servers normally export this; the
    /// host providing it as an import is unusual but legal. No-op.
    fn httpIncomingHandlerHandle(
        _: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {}

    // ───────────────────────────────────────────────────────────────────
    // wasi:http@0.3.0 (#487) — resource collapse 11→4, async handlers,
    // stream<u8> bodies, future<option<trailers>> on response.
    // ───────────────────────────────────────────────────────────────────

    /// Reserve handle slot 0 of `table`. Component-model resource
    fn pushHttpRequestP3(self: *WasiCliAdapter, r: *HttpRequestP3) !u32 {
        return self.http_requests_p3.publish(r);
    }
    fn lookupHttpRequestP3(self: *WasiCliAdapter, h: u32) ?HttpRequestP3Lease {
        const lease = self.http_requests_p3.acquire(h) orelse return null;
        return lockPointerLease(HttpRequestP3Table, HttpRequestP3, lease);
    }
    fn pushHttpResponseP3(self: *WasiCliAdapter, r: *HttpResponseP3) !u32 {
        return self.http_responses_p3.publish(r);
    }
    fn lookupHttpResponseP3(self: *WasiCliAdapter, h: u32) ?HttpResponseP3Lease {
        const lease = self.http_responses_p3.acquire(h) orelse return null;
        return lockPointerLease(HttpResponseP3Table, HttpResponseP3, lease);
    }

    fn activeInboundHttpResponse(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
    ) ?*InboundHttpResponseSession {
        const thread_ctx = execution_context.current() orelse return null;
        const session = thread_ctx.hostTaskContext(
            InboundHttpResponseSession,
        ) orelse return null;
        if (session.adapter != self or session.ci != ci) return null;
        return session;
    }

    fn pushRequestOptionsP3(self: *WasiCliAdapter, r: *RequestOptions) !u32 {
        return self.http_request_options_p3.publish(r);
    }
    fn lookupRequestOptionsP3(self: *WasiCliAdapter, h: u32) ?RequestOptionsLease {
        const lease = self.http_request_options_p3.acquire(h) orelse return null;
        return lockPointerLease(RequestOptionsTable, RequestOptions, lease);
    }

    /// Allocate a unit-type future entry in `ci.futures` and immediately
    /// mark it ready. Used by `httpClientSendP3` for transmission and
    /// trailers futures that complete synchronously alongside the
    /// fetch. `read_closed` stays false so guests can still read it.
    fn allocReadyUnitFuture(ci: *ComponentInstance) !u32 {
        const h = ci.allocAsyncHandle();
        try ci.futures.put(ci.allocator, h, .{
            .elem_type_idx = 0,
            .state = .ready,
            .write_closed = true,
        });
        return h;
    }

    /// Allocate a pending unit-type future entry in `ci.futures`.
    fn allocPendingUnitFuture(ci: *ComponentInstance) !u32 {
        const h = ci.allocAsyncHandle();
        try ci.futures.put(ci.allocator, h, .{
            .elem_type_idx = 0,
            .state = .pending,
        });
        return h;
    }

    /// Allocate an empty (write-closed/EOF) byte stream entry. The
    /// guest reads zero bytes and then sees EOF.
    fn allocEmptyByteStream(ci: *ComponentInstance) !u32 {
        const h = ci.allocAsyncHandle();
        try ci.streams.put(ci.allocator, h, .{
            .elem_type_idx = 0,
            .write_closed = true,
        });
        return h;
    }

    /// Drain a `stream<u8>` handle into a host byte slice (caller-owned).
    /// Returns null + 0-len if the handle is unknown. The stream's
    /// internal buffer is moved into the returned slice.
    fn drainByteStream(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        handle: u32,
    ) !?[]u8 {
        var stream_lease = ci.streams.acquire(handle) orelse return null;
        defer stream_lease.release();
        const s = stream_lease.value();
        if (s.buffer.items.len == 0) return try self.allocator.alloc(u8, 0);
        const out = try self.allocator.dupe(u8, s.buffer.items);
        s.buffer.clearRetainingCapacity();
        return out;
    }

    // --- fields.get-and-delete (new in 0.3) ---

    /// `[method]fields.get-and-delete: (field-name)
    ///   -> result<list<field-value>, header-error>` (#487).
    /// Atomically reads-and-removes all entries matching `name`.
    fn httpFieldsGetAndDelete(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var f_lease = self.lookupHttpFields(handle) orelse {
            results[0] = try httpResultOk(allocator, .{ .list = .{ .ptr = 0, .len = 0 } });
            return;
        };
        defer f_lease.release();
        const f = f_lease.value().*;
        if (f.immutable) {
            results[0] = try httpHeaderErr(allocator, .immutable);
            return;
        }

        const name_bytes: ?[]const u8 = extractArgBytes(ci, args[1]);
        const name_alloc = if (name_bytes == null) try extractArgBytesAlloc(self.allocator, ci, args[1]) else null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const name = name_bytes orelse (name_alloc orelse {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        });

        if (!isValidFieldName(name)) {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        }

        // Fast path: empty entries — return Ok(empty list) without
        // allocating a lowercase buffer (#552 hot-path budget).
        if (f.entries.items.len == 0) {
            results[0] = try httpResultOk(allocator, .{ .list = .{ .ptr = 0, .len = 0 } });
            return;
        }

        var matches: std.ArrayListUnmanaged([]const u8) = .empty;
        defer matches.deinit(self.allocator);
        for (f.entries.items) |e| {
            if (asciiEqualIgnoreCase(e.name, name)) {
                try matches.append(self.allocator, e.value);
            }
        }
        const list_val = try lowerByteListList(ci, matches.items);

        // Now remove the entries. Free the duped name/value backing.
        httpFieldsRemoveByNameInsensitive(f, self.allocator, name);

        results[0] = try httpResultOk(allocator, .{ .list = list_val });
    }

    // --- request (unified, P3) ---

    /// `[static]request.new: (headers, contents: option<stream<u8>>,
    ///   trailers: future<result<option<trailers>,error-code>>,
    ///   options: option<request-options>)
    ///   -> tuple<request, future<result<_,error-code>>>` (#487).
    fn httpRequestNewP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 4 or results.len == 0) return error.InvalidArgs;

        const headers_handle: u32 = switch (args[0]) {
            .handle => |h| h,
            else => 0,
        };
        const body_handle: ?u32 = switch (args[1]) {
            .option_val => |opt| if (opt.is_some and opt.payload != null) blk: {
                break :blk switch (opt.payload.?.*) {
                    .handle => |h| h,
                    else => null,
                };
            } else null,
            else => null,
        };
        const trailers_handle: u32 = switch (args[2]) {
            .handle => |h| h,
            else => try allocReadyUnitFuture(ci),
        };
        const options_handle: ?u32 = switch (args[3]) {
            .option_val => |opt| if (opt.is_some and opt.payload != null) blk: {
                break :blk switch (opt.payload.?.*) {
                    .handle => |h| h,
                    else => null,
                };
            } else null,
            else => null,
        };
        const fetch_options = if (options_handle) |h|
            self.snapshotRequestOptionsP3(h)
        else
            HttpFetchOptions{};

        // Pre-allocate a pending transmission future. Real send sets
        // it to ready; for the constructor path it stays pending until
        // the request is sent or dropped.
        const tx_handle = try allocPendingUnitFuture(ci);

        // Per WIT, headers given to `request.new` (and accessed later
        // via `get-headers`) become an immutable view. The wasi-p3
        // `http-request` fixture's `test_immutable_headers` confirms
        // this with an `append` on the borrow returned by
        // `get-headers` (#538). The fields' underlying owner is
        // transferred here; we mark it immutable in place.
        if (self.lookupHttpFields(headers_handle)) |owned_lease| {
            var fields_lease = owned_lease;
            const fields = fields_lease.lock().*;
            fields.immutable = true;
            fields_lease.unlock();
            fields_lease.release();
        }

        const r = try self.allocator.create(HttpRequestP3);
        r.* = .{
            .headers_handle = headers_handle,
            .body_stream_handle = body_handle,
            .trailers_future_handle = trailers_handle,
            .transmission_future_handle = tx_handle,
            .options_handle = options_handle,
            .fetch_options = fetch_options,
        };
        const rh = try self.pushHttpRequestP3(r);

        const tuple_fields = try allocator.alloc(InterfaceValue, 2);
        tuple_fields[0] = .{ .handle = rh };
        tuple_fields[1] = .{ .handle = tx_handle };
        results[0] = .{ .tuple_val = tuple_fields };
    }

    fn httpRequestGetMethodP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var r_lease = self.lookupHttpRequestP3(handle) orelse {
            results[0] = .{ .variant_val = .{ .discriminant = 0, .payload = null } };
            return;
        };
        defer r_lease.release();
        const r = r_lease.value().*;
        if (r.method_disc == 9 and r.method_other != null) {
            results[0] = try httpVariantWithOptionalBytes(ci, allocator, 9, r.method_other);
            return;
        }
        results[0] = .{ .variant_val = .{ .discriminant = r.method_disc, .payload = null } };
    }

    fn httpRequestSetMethodP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var r_lease = self.lookupHttpRequestP3(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        defer r_lease.release();
        const r = r_lease.value().*;

        var disc: u32 = 0;
        var other_view: ?[]const u8 = null;
        var other_alloc: ?[]u8 = null;
        defer if (other_alloc) |s| self.allocator.free(s);

        switch (args[1]) {
            .variant_val => |v| {
                disc = v.discriminant;
                if (v.discriminant == 9 and v.payload != null) {
                    other_view = extractArgBytes(ci, v.payload.?.*);
                    if (other_view == null) {
                        other_alloc = try extractArgBytesAlloc(self.allocator, ci, v.payload.?.*);
                    }
                }
            },
            .enum_val => |d| disc = d,
            .u32 => |d| disc = d,
            else => {
                results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
                return;
            },
        }

        // `Method::Other(name)` requires `name` to be a non-empty
        // RFC 7230 token. The canonical tokens GET/HEAD/.../PATCH
        // round-trip to the matching canonical discriminant (#538).
        if (disc == 9) {
            const name = other_view orelse (other_alloc orelse "");
            if (!isValidFieldName(name)) {
                results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
                return;
            }
            const canonical: ?u32 = blk: {
                if (asciiEqualIgnoreCase(name, "GET")) break :blk 0;
                if (asciiEqualIgnoreCase(name, "HEAD")) break :blk 1;
                if (asciiEqualIgnoreCase(name, "POST")) break :blk 2;
                if (asciiEqualIgnoreCase(name, "PUT")) break :blk 3;
                if (asciiEqualIgnoreCase(name, "DELETE")) break :blk 4;
                if (asciiEqualIgnoreCase(name, "CONNECT")) break :blk 5;
                if (asciiEqualIgnoreCase(name, "OPTIONS")) break :blk 6;
                if (asciiEqualIgnoreCase(name, "TRACE")) break :blk 7;
                if (asciiEqualIgnoreCase(name, "PATCH")) break :blk 8;
                break :blk null;
            };
            if (canonical) |cd| {
                r.method_disc = cd;
                if (r.method_other) |s| self.allocator.free(s);
                r.method_other = null;
            } else {
                r.method_disc = 9;
                if (r.method_other) |s| self.allocator.free(s);
                r.method_other = try self.allocator.dupe(u8, name);
            }
        } else if (disc <= 8) {
            r.method_disc = disc;
            if (r.method_other) |s| self.allocator.free(s);
            r.method_other = null;
        } else {
            results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
            return;
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    fn httpRequestGetPathP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var r_lease = self.lookupHttpRequestP3(handle) orelse {
            results[0] = .{ .option_val = .{ .is_some = false, .payload = null } };
            return;
        };
        defer r_lease.release();
        const r = r_lease.value().*;
        results[0] = try httpOptionBytes(ci, allocator, r.path_with_query);
    }

    fn httpRequestSetPathP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var r_lease = self.lookupHttpRequestP3(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        defer r_lease.release();
        const r = r_lease.value().*;

        // Lift the new value into a borrowed view (preferred) or
        // adapter-owned alloc; validate BEFORE clobbering the existing
        // `path_with_query` so a rejected set leaves state intact.
        var new_view: ?[]const u8 = null;
        var new_alloc: ?[]u8 = null;
        defer if (new_alloc) |s| self.allocator.free(s);
        var has_new: bool = false;

        switch (args[1]) {
            .option_val => |opt| {
                if (opt.is_some and opt.payload != null) {
                    new_view = extractArgBytes(ci, opt.payload.?.*);
                    if (new_view == null) {
                        new_alloc = try extractArgBytesAlloc(self.allocator, ci, opt.payload.?.*);
                    }
                    has_new = true;
                }
            },
            else => {
                new_view = extractArgBytes(ci, args[1]);
                if (new_view == null) {
                    new_alloc = try extractArgBytesAlloc(self.allocator, ci, args[1]);
                }
                has_new = true;
            },
        }

        if (has_new) {
            const bytes = new_view orelse (new_alloc orelse "");
            // Per wasi:http@0.3.0 (wasi-http#178 comment), the empty
            // path is admitted but normalised to "/" on set so that
            // `get-path-with-query` returns the canonical absolute
            // form (#552).
            const stored: []const u8 = if (bytes.len == 0) "/" else bytes;
            if (bytes.len != 0 and !isValidPathWithQuery(bytes)) {
                results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
                return;
            }
            const dup = try self.allocator.dupe(u8, stored);
            if (r.path_with_query) |old| self.allocator.free(old);
            r.path_with_query = dup;
        } else {
            if (r.path_with_query) |old| self.allocator.free(old);
            r.path_with_query = null;
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    fn httpRequestGetSchemeP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var r_lease = self.lookupHttpRequestP3(handle) orelse {
            results[0] = .{ .option_val = .{ .is_some = false, .payload = null } };
            return;
        };
        defer r_lease.release();
        const r = r_lease.value().*;
        const disc = r.scheme_disc orelse {
            results[0] = .{ .option_val = .{ .is_some = false, .payload = null } };
            return;
        };
        const inner = try allocator.create(InterfaceValue);
        inner.* = try httpVariantWithOptionalBytes(ci, allocator, disc, if (disc == 2) r.scheme_other else null);
        results[0] = .{ .option_val = .{ .is_some = true, .payload = inner } };
    }

    fn httpRequestSetSchemeP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var r_lease = self.lookupHttpRequestP3(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        defer r_lease.release();
        const r = r_lease.value().*;

        // Decompose `option<scheme>`:
        //   .option_val (is_some=false)          → store None
        //   .option_val payload=&variant_val     → use the variant
        //   .variant_val direct                  → backward-compat
        var new_disc: ?u32 = null;
        var new_other_view: ?[]const u8 = null;
        var new_other_alloc: ?[]u8 = null;
        defer if (new_other_alloc) |s| self.allocator.free(s);

        const variant_iv: ?InterfaceValue = switch (args[1]) {
            .option_val => |opt| if (opt.is_some and opt.payload != null) opt.payload.?.* else null,
            .variant_val, .enum_val, .u32 => args[1],
            else => null,
        };
        if (variant_iv) |v| {
            switch (v) {
                .variant_val => |vv| {
                    new_disc = vv.discriminant;
                    if (vv.discriminant == 2 and vv.payload != null) {
                        new_other_view = extractArgBytes(ci, vv.payload.?.*);
                        if (new_other_view == null) {
                            new_other_alloc = try extractArgBytesAlloc(self.allocator, ci, vv.payload.?.*);
                        }
                    }
                },
                .enum_val => |d| new_disc = d,
                .u32 => |d| new_disc = d,
                else => {},
            }
        }

        if (new_disc) |raw_disc| {
            // RFC 3986 §3.1: `scheme = ALPHA *(ALPHA / DIGIT / "+" /
            // "-" / ".")`. The wasi-p3 `http-request` fixture's
            // `test_schemes` checks single-char input (first byte
            // ASCII-alpha → ok, anything else → err); the byte
            // validator below also rejects multi-char inputs that
            // contain non-scheme bytes (e.g. `http://` — the
            // embedded colon / slash break the rule) per #552.
            if (raw_disc == 2) {
                const other_bytes = new_other_view orelse (new_other_alloc orelse "");
                // Empty `Other` is invalid.
                if (other_bytes.len == 0) {
                    results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
                    return;
                }
                // The first byte must be ASCII-ALPHA per RFC 3986.
                const first = other_bytes[0];
                if (!((first >= 'a' and first <= 'z') or (first >= 'A' and first <= 'Z'))) {
                    results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
                    return;
                }
                // Subsequent bytes must each be ALPHA / DIGIT / "+" /
                // "-" / ".". Reject anything outside that set —
                // notably ":" and "/" which appear in URL fragments
                // a guest might accidentally pass (#552).
                for (other_bytes[1..]) |c| {
                    const is_alpha = (c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z');
                    const is_digit = c >= '0' and c <= '9';
                    const is_sym = c == '+' or c == '-' or c == '.';
                    if (!(is_alpha or is_digit or is_sym)) {
                        results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
                        return;
                    }
                }
                // Normalise `Other("http")` / `Other("https")` to the
                // canonical `HTTP` / `HTTPS` variant.
                if (asciiEqualIgnoreCase(other_bytes, "http")) {
                    r.scheme_disc = 0;
                    if (r.scheme_other) |s| self.allocator.free(s);
                    r.scheme_other = null;
                } else if (asciiEqualIgnoreCase(other_bytes, "https")) {
                    r.scheme_disc = 1;
                    if (r.scheme_other) |s| self.allocator.free(s);
                    r.scheme_other = null;
                } else {
                    r.scheme_disc = 2;
                    if (r.scheme_other) |s| self.allocator.free(s);
                    r.scheme_other = try self.allocator.dupe(u8, other_bytes);
                }
            } else {
                r.scheme_disc = raw_disc;
                if (r.scheme_other) |s| self.allocator.free(s);
                r.scheme_other = null;
            }
        } else {
            r.scheme_disc = null;
            if (r.scheme_other) |s| self.allocator.free(s);
            r.scheme_other = null;
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    fn httpRequestGetAuthorityP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
