        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var r_lease = self.lookupHttpResponseP3(handle) orelse {
            results[0] = .{ .u16 = 200 };
            return;
        };
        defer r_lease.release();
        const r = r_lease.value().*;
        results[0] = .{ .u16 = r.status };
    }

    fn httpResponseSetStatusCodeP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        if (self.activeInboundHttpResponse(ci)) |session| {
            if (session.responseHeadCommitted(handle)) {
                results[0] = .{ .result_val = .{
                    .is_ok = false,
                    .payload = null,
                } };
                return;
            }
        }
        var r_lease = self.lookupHttpResponseP3(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        defer r_lease.release();
        const r = r_lease.value().*;
        const new_status: u16 = switch (args[1]) {
            .u16 => |v| v,
            .u32 => |v| @intCast(v & 0xFFFF),
            .s32 => |v| @intCast(@as(u32, @bitCast(v)) & 0xFFFF),
            else => r.status,
        };
        // Per RFC 9110 §15, HTTP status codes are 3-digit integers in
        // the range [100, 599]. The `http-response` wasi-p3-testsuite
        // fixture exercises rejection of 0, 42, 600, 1000, 69, 65535
        // (#538). `set-status-code` returns `result<_, _>` — bare
        // result with no payloads.
        if (new_status < 100 or new_status > 599) {
            results[0] = .{ .result_val = .{ .is_ok = false, .payload = null } };
            return;
        }
        r.status = new_status;
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

