    // --- handler.handle (P3) — host-import for middleware composition ---

    /// `wasi:http/handler@0.3.0.handle: async func(request) ->
    /// result<response, error-code>` as an *imported* function (#538).
    ///
    /// Components that act as HTTP servers EXPORT this function via
    /// `wasi:http/service` / `wasi:http/middleware`; importing it is
    /// the middleware-composition path where the inner handler is
    /// chained into another component's downstream handler. From the
    /// host side this is shape-equivalent to `wasi:http/client.send`:
    /// the guest hands us a `request`, we synthesise a `response`. We
    /// forward to `httpClientSendP3` so the same fetch path is used —
    /// real chained-handler composition is a follow-up that wires the
    /// guest's exported handler in as the upstream target.
    ///
    /// The result type is `result<response, error-code>` — same shape
    /// as `client.send` — so we can reuse its err encoding and ok
    /// payload directly.
    fn httpHandlerHandleP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        return httpClientSendP3(ctx_opaque, ci, args, results, allocator);
    }

    // --- client.send (P3) — host-provided outbound HTTP ---

    /// `wasi:http/client.send: async func(request) -> result<response, error-code>`
    /// (#487 / #589). Deferred-completion implementation built on top
    /// of the lower-level `std.http.Client.request` /
    /// `Request.receiveHead` outbound path (#583 A4):
    ///
    /// 1. The synchronous deny paths (no allow-list, bad request handle,
    ///    bad URI, allocation failure) mint a settled future whose
    ///    payload is the canonical-ABI-lowered err-arm envelope so the
    ///    `canon.lower (async)` trampoline still sees a `.handle` in
    ///    `results[0]` (the `STATUS_RETURNED` fast path copies the
    ///    bytes straight into the guest's `retptr`).
    /// 2. The real-fetch path mints a `.pending` future via
    ///    `spawnHttpFetchPendingP3`; the worker thread drives the
    ///    blocking `httpClientLowLevelFetch` (the same helper #594
    ///    introduced for the P2 path) and publishes its outcome —
    ///    status + body + response headers — via the
    ///    `PendingHttpFetchShared` block. The drainer
    ///    (`drainPendingHttpFetchesP3`, invoked from `driveAsyncEvents`)
    ///    lowers the `result<own<response>, error-code>` envelope
    ///    into the future's payload and calls `settleFutureDeferred`,
    ///    which copies the bytes to the trampoline's stashed
    ///    `async_lower_retptr` and fires the WaitableSet wakeup.
    ///
    /// Both `http://` and `https://` are accepted — TLS is provided by
    /// `std.crypto.tls` (#521). Connect/TLS/parse failures are mapped
    /// onto specific 0.3 `error-code` variants by `mapHttpFetchError`
    /// (#586) on the worker thread.
    fn httpClientSendP3(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        _ = allocator;
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;

        const req_handle: u32 = if (args.len > 0) switch (args[0]) {
            .handle => |h| h,
            else => 0,
        } else 0;
        var r_lease = self.lookupHttpRequestP3(req_handle) orelse {
            return self.httpClientSendP3DenyDeferred(ci, results, .HTTP_request_denied);
        };
        defer r_lease.release();
        const r = r_lease.value().*;

        if (!self.hasSocketsAllowList()) {
            return self.httpClientSendP3DenyDeferred(ci, results, .HTTP_request_denied);
        }

        // Scheme — `http` and `https` are both supported (#521).
        // `std.http.Client` handles TLS via `std.crypto.tls`.
        const scheme: []const u8 = if (r.scheme_disc) |d| switch (d) {
            0 => "http",
            1 => "https",
            else => if (r.scheme_other) |s| s else "https",
        } else "https";

        const authority = r.authority orelse {
            return self.httpClientSendP3DenyDeferred(ci, results, .HTTP_request_URI_invalid);
        };
        const path = r.path_with_query orelse "/";

        const url = std.fmt.allocPrint(self.allocator, "{s}://{s}{s}", .{ scheme, authority, path }) catch {
            return self.httpClientSendP3DenyDeferred(ci, results, .internal_error);
        };
        defer self.allocator.free(url);

        const method: std.http.Method = switch (r.method_disc) {
            0 => .GET,
            1 => .HEAD,
            2 => .POST,
            3 => .PUT,
            4 => .DELETE,
            5 => .CONNECT,
            6 => .OPTIONS,
            7 => .TRACE,
            8 => .PATCH,
            else => .GET,
        };

        var extra_hdrs: std.ArrayListUnmanaged(std.http.Header) = .empty;
        defer extra_hdrs.deinit(self.allocator);
        var headers_fields_lease = self.lookupHttpFields(r.headers_handle);
        defer if (headers_fields_lease) |*lease| lease.release();
        if (headers_fields_lease) |*lease| {
            const hf = lease.value().*;
            for (hf.entries.items) |e| {
                extra_hdrs.append(self.allocator, .{ .name = e.name, .value = e.value }) catch break;
            }
        }

        // Drain the body stream (if any) into a contiguous buffer; the
        // worker dupes it into its own owned snapshot below.
        var body_buf: ?[]u8 = null;
        defer if (body_buf) |b| self.allocator.free(b);
        if (r.body_stream_handle) |sh| {
            body_buf = self.drainByteStream(ci, sh) catch null;
        }
        const payload: ?[]const u8 = if (body_buf) |b| (if (b.len > 0) b else null) else null;

        // Mark the request's transmission future ready synchronously —
        // we've snapshotted the body for transport. (Mirrors the
        // pre-#589 synchronous behaviour so guests awaiting this
        // future on the request side still resolve.)
        if (ci.futures.acquire(r.transmission_future_handle)) |initial_lease| {
            var future_lease = initial_lease;
            const tx = future_lease.value();
            tx.state = .ready;
            tx.write_closed = true;
            future_lease.release();
        }

        // `request.new` retains only the resource handle. Copy the
        // scalar timeout now so dropping/cloning request-options
        // cannot race the worker.
        const fetch_options = self.httpFetchOptionsP3(r);

        const fh = self.spawnHttpFetchPendingP3(
            ci,
            url,
            method,
            extra_hdrs.items,
            payload,
            fetch_options,
        ) catch {
            return self.httpClientSendP3DenyDeferred(ci, results, .internal_error);
        };
        results[0] = .{ .handle = fh };
    }

    /// Synchronous deny path for `httpClientSendP3`: mint a settled
    /// P3 future whose payload is the canonical-ABI-lowered err
    /// envelope, return `.handle` so the trampoline observes the
    /// same shape as the deferred path. On lowering failure falls
    /// through to a `.result_val` so the host caller's path still
    /// completes (the trampoline degrades to `STATUS_RETURNED`
    /// with handle=0 and the guest reads zeroed memory — better
    /// than a trap on a default-deny rejection). (#589)
    fn httpClientSendP3DenyDeferred(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        results: []InterfaceValue,
        code: HttpErrorCode,
    ) anyerror!void {
        const fh = self.spawnReadyHttpP3ClientSendErrFuture(ci, code) catch {
            // Lowering / allocation failure — fall back to the legacy
            // `.result_val` shape so non-trampoline callers (the unit
            // tests pre-#589) still see a usable shape. The trampoline
            // collapses this to `STATUS_RETURNED` handle=0, which is
            // observably a denied request — acceptable for an
            // exceptional code path. The deferred-completion
            // trampoline-shape requirement still holds for the
            // happy-deny path above.
            const err_payload = try self.allocator.create(InterfaceValue);
            err_payload.* = .{ .variant_val = .{ .discriminant = @intFromEnum(code), .payload = null } };
            results[0] = .{ .result_val = .{ .is_ok = false, .payload = err_payload } };
            return;
        };
        results[0] = .{ .handle = fh };
    }

    /// Result of dispatching a guest-exported `incoming-handler.handle`.
    /// Flat lowering of `result<own<response>, error-code>` is
    /// `[discriminant, payload]` — 0 → ok with response handle, 1 →
    /// err with error-code discriminant. (#570 / #487)
    pub const HandleP3Outcome = struct {
        is_ok: bool,
        /// When `is_ok` is true this is the response handle; when
        /// false it is the `error-code` enum discriminant.
        payload: u32,

        /// Decode a canonical-ABI flat result tuple deposited on a
        /// task by `canon task.return` into a typed `HandleP3Outcome`.
        ///
        /// The flat representation produced by wit-bindgen ≥ 0.45 for
        /// `result<own<response>, error-code>` is `[disc, payload, ...]`:
        ///
        ///   * `disc`: 0 for Ok, 1 for Err.
        ///   * `payload`: for Ok, the canon-ABI wire-encoded
        ///     `own<response>` handle (`slot + 1`, see #562); for Err,
        ///     the `error-code` variant discriminant (plain i32).
        ///
        /// Any trailing slots are the variant-join padding for the
        /// (much wider) `error-code` arm — ignored by this decoder
        /// since the relevant data is always in the first two slots.
        /// Defensive fallbacks: empty `flat` → `(is_ok=false,
        /// internal_error)`; len==1 → `(is_ok=disc==0, internal_error)`.
        /// Factored out of `dispatchHttpHandlerP3` so the decode is
        /// unit-testable in isolation (#570).
        pub fn fromTaskReturnValues(flat: []const u32) HandleP3Outcome {
            const disc: u32 = if (flat.len > 0) flat[0] else 1;
            const raw_payload: u32 = if (flat.len > 1)
                flat[1]
            else
                @intFromEnum(HttpErrorCode.internal_error);
            const is_ok = disc == 0;
            const payload: u32 = if (is_ok)
                executor_root.decodeResourceWire(raw_payload)
            else
                raw_payload;
            return .{ .is_ok = is_ok, .payload = payload };
        }
    };

    /// Drive a guest-exported `wasi:http/incoming-handler@0.3.0.handle:
    /// async func(request) -> result<response, error-code>` via the
    /// async-lifted canonical ABI (#487 / #538 / #570). Used by the
    /// host server dispatch path — the wasi-p3-testsuite `http-service`
    /// fixture invokes this from inside the TCP-accept loop. Exposed
    /// at module scope so the unit tests can exercise the request →
    /// response round-trip without standing up a real socket.
    ///
    /// The guest delivers its result via `canon task.return` which
    /// deposits the lowered flat values on the owning task; this
    /// function reads them back out of `task.return_values`.
    pub fn dispatchHttpHandlerP3(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        export_dotted_name: []const u8,
        request_handle: u32,
        allocator: Allocator,
    ) !HandleP3Outcome {
        return self.dispatchHttpHandlerP3WithLiveResponse(
            ci,
            export_dotted_name,
            request_handle,
            null,
            allocator,
        );
    }

    fn dispatchHttpHandlerP3WithLiveResponse(
        _: *WasiCliAdapter,
        ci: *ComponentInstance,
        export_dotted_name: []const u8,
        request_handle: u32,
        live_response: ?*InboundHttpResponseSession,
        allocator: Allocator,
    ) !HandleP3Outcome {
        // Validate the export resolves to a callable local first so
        // unit tests get a precise error rather than a generic
        // FunctionNotFound from inside the async dispatcher.
        const exported = ci.getExport(export_dotted_name) orelse return error.NoHandleExport;
        switch (exported) {
            .local => {},
            else => return error.ForwardedExportUnsupported,
        }

        var task_mgr = async_mod.TaskManager{};
        defer task_mgr.deinit(allocator);

        const args: [1]InterfaceValue = .{.{ .handle = request_handle }};
        const task_handle = executor_root.callComponentFuncAsyncWithHostTaskContext(
            ci,
            export_dotted_name,
            &args,
            &task_mgr,
            null,
            if (live_response) |session| @ptrCast(session) else null,
            allocator,
        ) catch |e| return e;

        const return_values = try task_mgr.copyReturnValues(task_handle, allocator) orelse
            return error.NoHandleExport;
        defer allocator.free(return_values);
        return HandleP3Outcome.fromTaskReturnValues(return_values);
    }

    /// Build a `HttpRequestP3` from a complete HTTP/1.1 request byte
    /// buffer (`request_bytes`) and register it in the adapter's P3
    /// request table. The request body (if any) is materialised as a
    /// `stream<u8>` handle in `ci.streams` so the guest can read it
    /// through the canonical-ABI rendezvous. Trailers and transmission
    /// futures are pre-settled (ready/unit) — the wasi-testsuite
    /// `http-service` fixture's handler does not surface trailers.
    /// Mirrors `createIncomingRequestFromHttpBytes` for the unified
    /// 0.3 resource. (#570)
    ///
    /// Content-Length framing only: a `Transfer-Encoding: chunked`
    /// request must come through `readIncomingRequestP3FromStream`
    /// which stream-decodes the chunks into a contiguous body buffer
    /// before calling the shared `buildHttpRequestP3FromHeaderAndBody`
    /// builder (#583 A5).
    pub fn createIncomingRequestP3FromHttpBytes(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        request_bytes: []const u8,
    ) !u32 {
        const header_end = httpHeaderEnd(request_bytes) orelse return error.HttpBadRequest;
        if (header_end > max_http_p3_header_section_bytes) return error.HttpRequestHeaderTooLarge;
        const header_block = request_bytes[0..header_end];
        const info = try httpRequestHeaderInfoFromBlock(header_block);
        const body_len: usize = switch (info.body_kind) {
            .none => 0,
            .content_length => |n| n,
            // Chunked framing requires streaming decode; this
            // entrypoint only sees flattened bodies.
            .chunked => return error.HttpUnsupportedTransferCoding,
        };
        if (body_len > max_http_p3_body_bytes) return error.HttpRequestBodyTooLarge;
        const total_len = std.math.add(usize, header_end, body_len) catch return error.HttpRequestBodyTooLarge;
        if (request_bytes.len < total_len) return error.HttpBadRequest;
        const built = try self.buildHttpRequestP3FromHeaderAndBody(
            ci,
            header_block,
            request_bytes[header_end..total_len],
        );
        return built.request_handle;
    }

    /// Outcome of `buildHttpRequestP3FromHeaderAndBody` /
    /// `readIncomingRequestP3FromStreamWithInfo`. Splits the resource
    /// handle from the connection-scoped keep-alive flag so the
    /// caller (`serveOneHttpConnectionP3Stream`) can decide whether
    /// to loop for another request or close the socket (#583 A5).
    pub const HttpRequestP3Read = struct {
        request_handle: u32,
        keep_alive: bool,
    };

    /// Build a P3 incoming-request from already-separated header /
    /// body slices. Shared between the Content-Length and chunked
    /// request decode paths — the chunked path passes a freshly
    /// reassembled `body_bytes` slice that no longer carries
    /// `Transfer-Encoding: chunked` semantics on the wire.
    fn buildHttpRequestP3FromHeaderAndBody(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        header_block: []const u8,
        body_bytes: []const u8,
    ) !HttpRequestP3Read {
        if (header_block.len < 4 or !std.mem.endsWith(u8, header_block, "\r\n\r\n")) {
            return error.HttpBadRequest;
        }
        const info = try httpRequestHeaderInfoFromBlock(header_block);

        // The header block (everything up through the final `\r\n\r\n`)
        // is `header_block`; strip the trailing blank line before
        // splitting so the headers loop doesn't observe an empty
        // sentinel entry. Mirrors `createIncomingRequestFromHttpBytes`.
        var lines = std.mem.splitSequence(u8, header_block[0 .. header_block.len - 4], "\r\n");
        const request_line = lines.next() orelse return error.HttpBadRequest;
        var tokens = std.mem.tokenizeScalar(u8, request_line, ' ');
        const method = tokens.next() orelse return error.HttpBadRequest;
        const target = tokens.next() orelse return error.HttpBadRequest;
        const version = tokens.next() orelse return error.HttpBadRequest;
        if (tokens.next() != null) return error.HttpBadRequest;
        if (method.len == 0 or target.len == 0) return error.HttpBadRequest;
        if (target.len > max_http_target_bytes) return error.HttpRequestUriTooLong;
        if (!std.mem.eql(u8, version, "HTTP/1.1") and !std.mem.eql(u8, version, "HTTP/1.0")) {
            return error.HttpBadRequest;
        }

        const target_parts = splitHttpTarget(target);
        var host_header: ?[]const u8 = null;

        const fields = try self.allocator.create(HttpFields);
        fields.* = .{ .immutable = true };
        var fields_owned = true;
        errdefer if (fields_owned) {
            fields.deinit(self.allocator);
            self.allocator.destroy(fields);
        };

        while (lines.next()) |line| {
            if (line.len == 0) break;
            if (line[0] == ' ' or line[0] == '\t') return error.HttpBadRequest;
            const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.HttpBadRequest;
            const name = std.mem.trim(u8, line[0..colon], " \t");
            const value = std.mem.trim(u8, line[colon + 1 ..], " \t");
            if (name.len == 0) return error.HttpBadRequest;
            // Drop transport-managed framing headers from the guest's
            // view so chunked-decoded requests look identical to a
            // Content-Length-framed body of the same length (#583 A5).
            if (std.ascii.eqlIgnoreCase(name, "transfer-encoding")) continue;
            const name_copy = try self.allocator.dupe(u8, name);
            const value_copy = self.allocator.dupe(u8, value) catch |err| {
                self.allocator.free(name_copy);
                return err;
            };
            fields.entries.append(self.allocator, .{ .name = name_copy, .value = value_copy }) catch |err| {
                self.allocator.free(name_copy);
                self.allocator.free(value_copy);
                return err;
            };
            if (std.ascii.eqlIgnoreCase(name, "host") and host_header == null) {
                host_header = value_copy;
            }
        }

        var method_other: ?[]u8 = null;
        errdefer if (method_other) |s| self.allocator.free(s);
        const method_disc = httpMethodDiscriminant(method);
        if (method_disc == 9) method_other = try self.allocator.dupe(u8, method);

        const path_copy = try self.allocator.dupe(u8, target_parts.path_with_query);
        var path_owned: ?[]u8 = path_copy;
        errdefer if (path_owned) |s| self.allocator.free(s);

        var authority_copy: ?[]u8 = null;
        errdefer if (authority_copy) |s| self.allocator.free(s);
        const authority = target_parts.authority orelse host_header;
        if (authority) |a| authority_copy = try self.allocator.dupe(u8, a);

        const fields_handle = try self.pushHttpFields(fields);
        fields_owned = false;
        errdefer {
            if (self.http_fields_table.withdraw(fields_handle)) |withdrawn| {
                std.debug.assert(withdrawn == fields);
                withdrawn.deinit(self.allocator);
                self.allocator.destroy(withdrawn);
            }
        }

        // Materialise the body as a stream<u8> in `ci.streams`. Even
        // empty bodies allocate a stream so the guest can call
        // `request.consume-body` without conditional logic. `write_closed`
        // = true signals EOF so the first read returns 0 bytes.
        const body_handle = ci.allocAsyncHandle();
        var body_stream: async_mod.AsyncStream = .{ .elem_type_idx = 0 };
        if (body_bytes.len > 0) {
            body_stream.buffer.appendSlice(ci.allocator, body_bytes) catch |e| {
                body_stream.deinit(ci.allocator);
                return e;
            };
        }
        body_stream.write_closed = true;
        ci.streams.put(ci.allocator, body_handle, body_stream) catch |e| {
            body_stream.deinit(ci.allocator);
            return e;
        };
        errdefer _ = ci.streams.remove(body_handle);

        const trailers_handle = try allocReadyUnitFuture(ci);
        errdefer _ = ci.futures.remove(trailers_handle);
        const tx_handle = try allocReadyUnitFuture(ci);
        errdefer _ = ci.futures.remove(tx_handle);

        const r = try self.allocator.create(HttpRequestP3);
        r.* = .{
            .method_disc = method_disc,
            .method_other = method_other,
            .path_with_query = path_owned,
            .scheme_disc = target_parts.scheme_disc, // default 0 (http)
            .authority = authority_copy,
            .headers_handle = fields_handle,
            .body_stream_handle = body_handle,
            .trailers_future_handle = trailers_handle,
            .transmission_future_handle = tx_handle,
        };
        method_other = null;
        path_owned = null;
        authority_copy = null;
        const handle = self.pushHttpRequestP3(r) catch |err| {
            r.deinit(self.allocator);
            self.allocator.destroy(r);
            return err;
        };
        return .{ .request_handle = handle, .keep_alive = info.keep_alive };
    }

    /// Stream-decode a `Transfer-Encoding: chunked` body off
    /// `reader` into `dst`. Each chunk is `<hex-size>[;<ext>]\r\n
    /// <bytes>\r\n` repeated until the terminating `0\r\n
    /// [<trailers>]\r\n`. Trailers (if any) are silently consumed —
    /// the P3 incoming-request resource pre-allocates a unit-ready
    /// trailers future today so guest-side trailer reads return
    /// none. (#583 A5)
    fn readChunkedBody(
        _: *WasiCliAdapter,
        reader: *BufferedLineReader,
        dst: *std.ArrayListUnmanaged(u8),
        max_total: usize,
    ) !void {
        const chunk_size_max_line: usize = 256;
        while (true) {
            const size_line = try reader.readLine(chunk_size_max_line);
            const semi = std.mem.indexOfScalar(u8, size_line, ';') orelse size_line.len;
            const size_hex = std.mem.trim(u8, size_line[0..semi], " \t");
            if (size_hex.len == 0) return error.HttpBadRequest;
            const chunk_size = std.fmt.parseInt(usize, size_hex, 16) catch return error.HttpBadRequest;
            if (chunk_size == 0) {
                // Drain optional trailer field lines until the final
                // CRLF. We currently discard them — the P3 resource
                // exposes a ready unit-trailers future to the guest.
                while (true) {
                    const tl = try reader.readLine(max_http_p3_header_section_bytes);
                    if (tl.len == 0) return;
                }
            }
            if (chunk_size > max_total or dst.items.len + chunk_size > max_total) {
                return error.HttpRequestBodyTooLarge;
            }
            try reader.readExactAppend(dst, chunk_size, max_total);
            const crlf = try reader.readLine(2);
            if (crlf.len != 0) return error.HttpBadRequest;
        }
    }

    /// Serialize an already-complete `HttpResponseP3` as HTTP/1.1.
    /// This is the compatibility fallback for responses whose stream
    /// could not be associated with the live bridge. It drains the body
    /// `stream<u8>` (if any) into a contiguous response body, then emits a
    /// `Content-Length`-framed response (when the guest set
    /// `Content-Length` in `headers`) or a `Transfer-Encoding: chunked`
    /// response (when the body length is unknown pre-write). Trailers
    /// supplied via the guest's `future<option<trailers>>` are lifted
    /// into the chunked trailer block. (#570 / #583 A5)
    /// Settle a response's transmission future as failed (#616 A8).
    ///
    /// In `wasi:http@0.3` the response carries a transmission future
    /// so the guest can learn whether its response actually reached
    /// the client. Until now the inbound serve path never wrote to it:
    /// a response abandoned mid-flight looked identical to one
    /// delivered in full. Closing it without a ready payload gives the
    /// guest the failure signal the WIT promises.
    fn failHttpResponseTransmission(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        response_handle: u32,
    ) void {
        var response_lease = self.lookupHttpResponseP3(response_handle) orelse return;
        defer response_lease.release();
        const response = response_lease.value().*;
        _ = settleHttpResponseTransmissionFuture(
            ci,
            response.transmission_future_handle,
            false,
        );
    }

    fn succeedHttpResponseTransmission(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        response_handle: u32,
    ) void {
        var response_lease = self.lookupHttpResponseP3(response_handle) orelse return;
        defer response_lease.release();
        const response = response_lease.value().*;
        _ = settleHttpResponseTransmissionFuture(
            ci,
            response.transmission_future_handle,
            true,
        );
    }

    pub fn writeHttpResponseP3FromHandle(
        self: *WasiCliAdapter,
        out: *streams.OutputStream,
        ci: *ComponentInstance,
        response_handle: u32,
        keep_alive: bool,
    ) !void {
        var response_lease = self.lookupHttpResponseP3(response_handle) orelse {
            return self.writeHttpSimpleResponse(out, 500, "invalid response handle\n");
        };
        defer response_lease.release();
        const response = response_lease.value().*;

        const status: u16 = if (response.status >= 100 and response.status <= 999) response.status else 500;

        // Drain the body stream<u8> if present. Empty streams (no
        // contents pushed by the guest) yield a zero-length body
        // without a Content-Length error.
        var body_owned: ?[]u8 = null;
        defer if (body_owned) |b| self.allocator.free(b);
        if (response.body_stream_handle) |sh| {
            body_owned = self.drainByteStream(ci, sh) catch null;
        }
        const body: []const u8 = if (body_owned) |b| b else "";

        // Validate response header name/value bytes before emitting.
        // Skip transport-managed headers (we set Content-Length /
        // Transfer-Encoding / Connection / Trailer ourselves).
        var guest_set_content_length = false;
        var response_fields_lease = self.lookupHttpFields(response.headers_handle);
        defer if (response_fields_lease) |*lease| lease.release();
        const response_fields: ?*HttpFields = if (response_fields_lease) |*lease|
            lease.value().*
        else
            null;
        if (response_fields) |fields| {
            for (fields.entries.items) |entry| {
                if (isHopByHopOrFramingHeader(entry.name)) {
                    if (std.ascii.eqlIgnoreCase(entry.name, "content-length")) {
                        guest_set_content_length = true;
                    }
                    continue;
                }
                if (!httpHeaderNameValid(entry.name) or !httpHeaderValueValid(entry.value)) {
                    return self.writeHttpSimpleResponse(out, 500, "invalid response header\n");
                }
            }
        }

        // Extract optional guest-supplied trailer fields out of the
        // trailers future payload. `payload == null` (the ready-unit
        // future from `allocReadyUnitFuture`) is the no-trailers fast
        // path; a `some(<fields_handle>)` payload lifts into the
        // chunked trailer block.
        var trailer_fields_lease = self.lookupTrailerFieldsFromFuture(
            ci,
            response.trailers_future_handle,
        );
        defer if (trailer_fields_lease) |*lease| lease.release();
        const trailer_fields: ?*HttpFields = if (trailer_fields_lease) |*lease|
            lease.value().*
        else
            null;
        const has_trailer_entries = if (trailer_fields) |tf| tf.entries.items.len > 0 else false;
        const has_body_stream = response.body_stream_handle != null;

        // Frame selection: prefer identity framing when the guest's
        // headers carry a Content-Length, or when there is no body
        // stream and no trailers to emit. Switch to chunked when the
        // body length is unknown pre-write (no Content-Length) or
        // when guest-supplied trailers need to be carried in the
        // trailer block (RFC 7230 §4.1.2 forbids trailers on
        // identity-framed responses). (#583 A5)
        const use_chunked = has_trailer_entries or (has_body_stream and !guest_set_content_length);

        const status_line = try std.fmt.allocPrint(
            self.allocator,
            "HTTP/1.1 {d} {s}\r\n",
            .{ status, httpResponseStatusReason(status) },
        );
        defer self.allocator.free(status_line);
        try self.writeAllOutputStream(out, status_line);

        if (response_fields) |fields| {
            for (fields.entries.items) |entry| {
                if (isHopByHopOrFramingHeader(entry.name)) continue;
                const line = try std.fmt.allocPrint(
                    self.allocator,
                    "{s}: {s}\r\n",
                    .{ entry.name, entry.value },
                );
                defer self.allocator.free(line);
                try self.writeAllOutputStream(out, line);
            }
        }

        // Per RFC 7230 §4.4, a `Trailer:` header must declare the
        // names that will appear after the body. Generate one
        // listing every trailer key so downstream caches can decide
        // whether they need to keep them.
        if (trailer_fields) |tf| {
            if (tf.entries.items.len > 0) {
                var trailer_decl: std.ArrayListUnmanaged(u8) = .empty;
                defer trailer_decl.deinit(self.allocator);
                try trailer_decl.appendSlice(self.allocator, "Trailer: ");
                var first = true;
                for (tf.entries.items) |entry| {
                    if (isHopByHopOrFramingHeader(entry.name)) continue;
                    if (!first) try trailer_decl.appendSlice(self.allocator, ", ");
                    try trailer_decl.appendSlice(self.allocator, entry.name);
                    first = false;
                }
                try trailer_decl.appendSlice(self.allocator, "\r\n");
                if (!first) try self.writeAllOutputStream(out, trailer_decl.items);
            }
        }

        const framing = if (use_chunked) "Transfer-Encoding: chunked\r\n" else "";
        const connection_header = if (keep_alive) "Connection: keep-alive\r\n" else "Connection: close\r\n";

        if (use_chunked) {
            try self.writeAllOutputStream(out, framing);
            try self.writeAllOutputStream(out, connection_header);
            try self.writeAllOutputStream(out, "\r\n");
            if (body.len > 0) {
                const size_line = try std.fmt.allocPrint(self.allocator, "{x}\r\n", .{body.len});
                defer self.allocator.free(size_line);
                try self.writeAllOutputStream(out, size_line);
                try self.writeHttpBodyChunked(out, body);
                try self.writeAllOutputStream(out, "\r\n");
            }
            try self.writeAllOutputStream(out, "0\r\n");
            if (trailer_fields) |tf| {
                for (tf.entries.items) |entry| {
                    if (isHopByHopOrFramingHeader(entry.name)) continue;
                    if (!httpHeaderNameValid(entry.name) or !httpHeaderValueValid(entry.value)) continue;
                    const tl = try std.fmt.allocPrint(
                        self.allocator,
                        "{s}: {s}\r\n",
                        .{ entry.name, entry.value },
                    );
                    defer self.allocator.free(tl);
                    try self.writeAllOutputStream(out, tl);
                }
            }
            try self.writeAllOutputStream(out, "\r\n");
        } else {
            const trailer = try std.fmt.allocPrint(
                self.allocator,
                "Content-Length: {d}\r\n{s}\r\n",
                .{ body.len, connection_header },
            );
            defer self.allocator.free(trailer);
            try self.writeAllOutputStream(out, trailer);
            try self.writeHttpBodyChunked(out, body);
        }
    }

    /// Names that the HTTP/1.1 transport layer manages itself —
    /// guests must not be allowed to set these directly on a
    /// `wasi:http/types.fields` and have us emit them on the wire,
    /// or smuggling / framing-confusion bugs become possible (#583
    /// A5). Trailers passing through `writeHttpResponseP3FromHandle`
    /// are filtered through the same predicate so a guest can't
    /// stuff a `Content-Length` into the trailer block.
    fn isHopByHopOrFramingHeader(name: []const u8) bool {
        const names = [_][]const u8{
            "connection",         "keep-alive",
            "transfer-encoding",  "content-length",
            "trailer",            "upgrade",
            "proxy-authenticate", "proxy-authorization",
            "te",                 "host",
        };
        for (names) |n| {
            if (std.ascii.eqlIgnoreCase(name, n)) return true;
        }
        return false;
    }

    /// Decode the trailers `future<option<own<trailers>>>`'s
    /// canonical-ABI payload into a borrowed `*HttpFields` pointer
    /// when the guest wrote `some(<fields_handle>)`. Returns `null`
    /// for the no-trailers fast path (no payload set, or `none`
    /// discriminant). Mirrors the canon-ABI layout of `option<T>`:
    /// 1-byte discriminant + 3 bytes of padding + 4-byte handle.
    fn lookupTrailerFieldsFromFuture(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        future_handle: u32,
    ) ?HttpFieldsLease {
        var future_lease = ci.futures.acquire(future_handle) orelse return null;
        const fut = future_lease.value();
        const payload = fut.payload orelse {
            future_lease.release();
            return null;
        };
        if (payload.len < 8 or payload[0] != 1) {
            future_lease.release();
            return null;
        }
        const handle = std.mem.readInt(u32, payload[4..8], .little);
        future_lease.release();
        return self.lookupHttpFields(handle);
    }

    /// Read a complete HTTP request from `stream`, build an
    /// `HttpRequestP3`, and return its handle. Used by both the live
    /// accept loop (`serveOneHttpConnectionP3`) and unit tests.
    /// Bounded by `max_http_p3_header_section_bytes` /
    /// `max_http_p3_body_bytes` — oversized requests trap with the
    /// corresponding error so the caller can lower a 413 / 431
    /// response without dispatching the guest. Honors chunked
    /// transfer-encoding and the Connection header so the
    /// `serveOneHttpConnectionP3Stream` keep-alive loop knows
    /// whether to read another request after the response. (#570 /
    /// #583 A5)
    pub fn readIncomingRequestP3FromStream(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        stream: *streams.InputStream,
    ) !HttpRequestP3Read {
        var reader: BufferedLineReader = .{ .allocator = self.allocator, .stream = stream };
        defer reader.deinit();
        return self.readIncomingRequestP3FromBufferedReader(ci, &reader);
    }

    /// Sibling of `readIncomingRequestP3FromStream` that reuses a
    /// caller-owned `BufferedLineReader` so any over-read tail
    /// (pipelined requests, residual chunked trailers) carries
    /// across keep-alive round-trips. Internal to
    /// `serveOneHttpConnectionP3Stream`.
    pub fn readIncomingRequestP3FromBufferedReader(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        reader: *BufferedLineReader,
    ) !HttpRequestP3Read {
        // Reset the per-request "have we consumed any bytes yet"
        // flag so the very-first `readLine` can surface a clean
        // idle-close to the keep-alive caller when the client
        // closes between requests (#583 A5).
        reader.any_bytes_consumed = false;

        // Accumulate header block lines into a fresh buffer so the
        // parser can run against contiguous `\r\n`-delimited bytes
        // ending in the conventional blank-line terminator.
        var hdr_bytes: std.ArrayListUnmanaged(u8) = .empty;
        defer hdr_bytes.deinit(self.allocator);

        // First line — surface idle-close cleanly so the keep-alive
        // loop can exit without writing a response.
        const first_line = try reader.readLine(max_http_p3_header_section_bytes);
        try hdr_bytes.appendSlice(self.allocator, first_line);
        try hdr_bytes.appendSlice(self.allocator, "\r\n");

        while (true) {
            const line = try reader.readLine(max_http_p3_header_section_bytes);
            try hdr_bytes.appendSlice(self.allocator, line);
            try hdr_bytes.appendSlice(self.allocator, "\r\n");
            if (line.len == 0) break;
            if (hdr_bytes.items.len > max_http_p3_header_section_bytes) return error.HttpRequestHeaderTooLarge;
        }
        if (hdr_bytes.items.len > max_http_p3_header_section_bytes) return error.HttpRequestHeaderTooLarge;

        const info = try httpRequestHeaderInfoFromBlock(hdr_bytes.items);

        var body_bytes: std.ArrayListUnmanaged(u8) = .empty;
        defer body_bytes.deinit(self.allocator);
        switch (info.body_kind) {
            .none => {},
            .content_length => |n| {
                if (n > max_http_p3_body_bytes) return error.HttpRequestBodyTooLarge;
                try reader.readExactAppend(&body_bytes, n, max_http_p3_body_bytes);
            },
            .chunked => {
                try self.readChunkedBody(reader, &body_bytes, max_http_p3_body_bytes);
            },
        }

        return self.buildHttpRequestP3FromHeaderAndBody(ci, hdr_bytes.items, body_bytes.items);
    }

    /// Free every per-connection P3 resource (`HttpRequestP3`,
    /// `HttpResponseP3`, `RequestOptions`) and reset the handle
    /// tables. Mirrors `cleanupHttpResources` for the 0.2 surface.
    /// The connection-scoped invariant: each accepted socket owns
    /// its own request/response pair and the streams/futures held in
    /// `ci.streams` / `ci.futures`; clearing the adapter side ensures
    /// the next connection starts from a clean handle namespace.
    /// (#570)
    fn cleanupHttpResourcesP3(self: *WasiCliAdapter) void {
        self.removeAllResources(&self.http_requests_p3);
        self.removeAllResources(&self.http_responses_p3);
        self.removeAllResources(&self.http_request_options_p3);
    }

    /// Per-connection cleanup for the P3 dispatch path: drops the 0.3
    /// resource tables and the shared `HttpFields` / 0.2 leftovers.
    pub fn cleanupHttpResourcesAllVersions(self: *WasiCliAdapter) void {
        self.cleanupHttpResources();
        self.cleanupHttpResourcesP3();
    }

    /// Drive a single accepted connection through the P3 incoming
    /// handler. Loops while `Connection: keep-alive` semantics allow,
    /// parsing each HTTP/1.1 request into an `HttpRequestP3`,
    /// dispatching `incoming-handler.handle` via the async-lifted
    /// ABI, then serializing the resulting `result<response,
    /// error-code>` back to the socket. Closes the socket on
    /// `Connection: close`, idle-stream close, parse error, or
    /// dispatch trap (graceful 503). (#570 / #583 A5)
    pub fn serveOneHttpConnectionP3Stream(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        handler_name: []const u8,
        input: *streams.InputStream,
        output: *streams.OutputStream,
    ) void {
        self.serveOneHttpConnectionP3StreamInterruptible(
            ci,
            handler_name,
            input,
            output,
            null,
        );
    }

    fn serveOneHttpConnectionP3StreamInterruptible(
        self: *WasiCliAdapter,
        ci: *ComponentInstance,
        handler_name: []const u8,
        input: *streams.InputStream,
        output: *streams.OutputStream,
        interrupt: ?HttpConnectionInterrupt,
    ) void {
        var reader: BufferedLineReader = .{ .allocator = self.allocator, .stream = input };
        defer reader.deinit();

        while (true) {
            const parsed = self.readIncomingRequestP3FromBufferedReader(ci, &reader) catch |err| {
                if (err == error.HttpConnectionIdleClose) {
                    // Client closed cleanly between requests — no
                    // response, just exit.
                    return;
                }
                self.writeHttpSimpleResponse(
                    output,
                    statusForRequestReadError(err),
                    "bad request\n",
                ) catch {};
                return;
            };

            const live_response: ?*InboundHttpResponseSession = live: {
                const session = InboundHttpResponseSession.create(
                    self.allocator,
                    self,
                    ci,
                    output,
                    parsed.keep_alive,
                    interrupt,
                    null,
                ) catch break :live null;
                session.start() catch {
                    session.destroy();
                    break :live null;
                };
                break :live session;
            };

            const outcome = self.dispatchHttpHandlerP3WithLiveResponse(
                ci,
                handler_name,
                parsed.request_handle,
                live_response,
                self.allocator,
            ) catch {
                // Dispatch trapped — graceful 503 instead of
                // propagating up to the accept loop (#583 A5).
                var output_started = false;
                var terminal: HttpLiveTerminal = .handler_error;
                if (live_response) |session| {
                    session.handlerFailed();
                    session.waitAndJoin();
                    session.propagateTerminalToGuest();
                    output_started = session.hasOutputStarted();
                    terminal = session.currentTerminal();
                    session.destroy();
                }
                if (!output_started and terminal != .client_disconnected and
                    terminal != .shutdown)
                {
                    self.writeHttpSimpleResponse(
                        output,
                        503,
                        "service unavailable\n",
                    ) catch {};
                }
                cancelAllPendingAsyncOps(self, ci, null, self.allocator);
                self.cleanupHttpResourcesAllVersions();
                return;
            };

            if (!outcome.is_ok) {
                const code: u16 = httpStatusFromError(outcome.payload);
                // Errored responses always close — the error code
                // semantics imply the connection state is suspect.
                var output_started = false;
                var terminal: HttpLiveTerminal = .handler_error;
                if (live_response) |session| {
                    session.handlerFailed();
                    session.waitAndJoin();
                    session.propagateTerminalToGuest();
                    output_started = session.hasOutputStarted();
                    terminal = session.currentTerminal();
                    session.destroy();
                }
                if (!output_started and terminal != .client_disconnected and
                    terminal != .shutdown)
                {
                    self.writeHttpSimpleResponse(
                        output,
                        code,
                        "handler returned error\n",
                    ) catch {};
                }
                cancelAllPendingAsyncOps(self, ci, null, self.allocator);
                self.cleanupHttpResourcesAllVersions();
                return;
            }

            var live_terminal: HttpLiveTerminal = .fallback;
            var live_output_started = false;
            if (live_response) |session| {
                session.handlerReturned(outcome.payload);
                session.waitAndJoin();
                session.propagateTerminalToGuest();
                live_terminal = session.currentTerminal();
                live_output_started = session.hasOutputStarted();
                session.destroy();
            }

            if (live_terminal == .fallback) {
                self.writeHttpResponseP3FromHandle(
                    output,
                    ci,
                    outcome.payload,
                    parsed.keep_alive,
                ) catch |err| {
                    self.failHttpResponseTransmission(ci, outcome.payload);
                    if (err == error.HttpClientDisconnected) {
                        cancelAllPendingAsyncOps(
                            self,
                            ci,
                            null,
                            self.allocator,
                        );
                    }
                    self.cleanupHttpResourcesAllVersions();
                    return;
                };
                self.succeedHttpResponseTransmission(ci, outcome.payload);
                live_terminal = .succeeded;
            }

            if (live_terminal != .succeeded) {
                if (live_terminal == .response_error and
                    !live_output_started)
                {
                    self.writeHttpSimpleResponse(
                        output,
                        500,
                        "invalid response\n",
                    ) catch {};
                }
                cancelAllPendingAsyncOps(self, ci, null, self.allocator);
                self.cleanupHttpResourcesAllVersions();
                return;
            }

            // Per-request resource tables are owned by the handler
            // dispatch — reset them so the next round-trip starts
            // from clean handle tables. Streams/futures registered
            // on the component instance persist for the connection;
            // each request allocates fresh ones.
            self.cleanupHttpResourcesAllVersions();
            if (!parsed.keep_alive) return;
            reader.compact();
        }
    }

    /// Register `wasi:http/types@0.3.0-*` (#487).
    pub fn populateWasiHttpTypesP3(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        iface_name: []const u8,
    ) !void {
        const M = struct {
            name: []const u8,
            call: *const fn (?*anyopaque, *ComponentInstance, []const InterfaceValue, []InterfaceValue, Allocator) anyerror!void,
        };
        const members = [_]M{
            // fields (mostly reused from 0.2)
            .{ .name = "[constructor]fields", .call = &httpFieldsConstructor },
            .{ .name = "[static]fields.from-list", .call = &httpFieldsFromList },
            .{ .name = "[method]fields.get", .call = &httpFieldsGet },
            .{ .name = "[method]fields.has", .call = &httpFieldsHas },
            .{ .name = "[method]fields.set", .call = &httpFieldsSet },
            .{ .name = "[method]fields.delete", .call = &httpFieldsDelete },
            .{ .name = "[method]fields.get-and-delete", .call = &httpFieldsGetAndDelete },
            .{ .name = "[method]fields.append", .call = &httpFieldsAppend },
            .{ .name = "[method]fields.copy-all", .call = &httpFieldsEntries },
            .{ .name = "[method]fields.clone", .call = &httpFieldsClone },
            .{ .name = "[resource-drop]fields", .call = &httpFieldsDrop },
            // request (unified)
            .{ .name = "[static]request.new", .call = &httpRequestNewP3 },
            .{ .name = "[method]request.get-method", .call = &httpRequestGetMethodP3 },
            .{ .name = "[method]request.set-method", .call = &httpRequestSetMethodP3 },
            .{ .name = "[method]request.get-path-with-query", .call = &httpRequestGetPathP3 },
            .{ .name = "[method]request.set-path-with-query", .call = &httpRequestSetPathP3 },
            .{ .name = "[method]request.get-scheme", .call = &httpRequestGetSchemeP3 },
            .{ .name = "[method]request.set-scheme", .call = &httpRequestSetSchemeP3 },
            .{ .name = "[method]request.get-authority", .call = &httpRequestGetAuthorityP3 },
            .{ .name = "[method]request.set-authority", .call = &httpRequestSetAuthorityP3 },
            .{ .name = "[method]request.get-options", .call = &httpRequestGetOptionsP3 },
            .{ .name = "[method]request.get-headers", .call = &httpRequestGetHeadersP3 },
            .{ .name = "[static]request.consume-body", .call = &httpRequestConsumeBodyP3 },
            .{ .name = "[resource-drop]request", .call = &httpRequestDropP3 },
            // request-options (renamed timeout getters/setters)
            .{ .name = "[constructor]request-options", .call = &httpRequestOptionsConstructorP3 },
            .{ .name = "[method]request-options.get-connect-timeout", .call = &httpRequestOptionsGetConnectTimeoutP3 },
            .{ .name = "[method]request-options.set-connect-timeout", .call = &httpRequestOptionsSetConnectTimeoutP3 },
            .{ .name = "[method]request-options.get-first-byte-timeout", .call = &httpRequestOptionsGetFirstByteTimeoutP3 },
            .{ .name = "[method]request-options.set-first-byte-timeout", .call = &httpRequestOptionsSetFirstByteTimeoutP3 },
            .{ .name = "[method]request-options.get-between-bytes-timeout", .call = &httpRequestOptionsGetBetweenBytesTimeoutP3 },
            .{ .name = "[method]request-options.set-between-bytes-timeout", .call = &httpRequestOptionsSetBetweenBytesTimeoutP3 },
            .{ .name = "[method]request-options.clone", .call = &httpRequestOptionsCloneP3 },
            .{ .name = "[resource-drop]request-options", .call = &httpRequestOptionsDropP3 },
            // response (unified)
            .{ .name = "[static]response.new", .call = &httpResponseNewP3 },
            .{ .name = "[method]response.get-status-code", .call = &httpResponseGetStatusCodeP3 },
            .{ .name = "[method]response.set-status-code", .call = &httpResponseSetStatusCodeP3 },
            .{ .name = "[method]response.get-headers", .call = &httpResponseGetHeadersP3 },
            .{ .name = "[static]response.consume-body", .call = &httpResponseConsumeBodyP3 },
            .{ .name = "[resource-drop]response", .call = &httpResponseDropP3 },
        };
        for (members) |m| {
            try self.http_types_p3_iface.members.put(self.allocator, m.name, .{
                .func = .{ .context = self, .call = m.call },
            });
        }
        try providers.put(self.allocator, iface_name, .{
            .host_instance = &self.http_types_p3_iface,
        });
    }

