        };
        for (members) |m| {
            try self.http_types_iface.members.put(self.allocator, m.name, .{
                .func = .{ .context = self, .call = m.call },
            });
        }
        try providers.put(self.allocator, interface_name, .{
            .host_instance = &self.http_types_iface,
        });
    }

