    /// Lookup a `KeyvalueBucket` by guest handle. Returns `null` if
    /// the slot index is out of range or has been dropped.
    fn lookupKeyvalueBucket(self: *WasiCliAdapter, handle: u32) ?KeyvalueBucketTable.Lease {
        return self.keyvalue_buckets.acquire(handle);
    }

    /// Insert a fresh `KeyvalueBucket` into the table. Reuses a
    /// nulled slot if any exists, otherwise appends. Returns the
    /// slot index (== guest handle).
    fn pushKeyvalueBucket(self: *WasiCliAdapter, b: *KeyvalueBucket) !u32 {
        return self.keyvalue_buckets.publish(b);
    }

    /// Lookup a `Cas` by guest handle. Returns `null` if the slot
    /// index is out of range or the CAS has been dropped / consumed
    /// by a successful `swap`.
    fn lookupCas(self: *WasiCliAdapter, handle: u32) ?CasTable.Lease {
        return self.cas_table.acquire(handle);
    }

    /// Insert a fresh `Cas` into the table. Reuses a nulled slot if
    /// any exists, otherwise appends. Returns the slot index
    /// (== guest handle).
    fn pushCas(self: *WasiCliAdapter, c: *Cas) !u32 {
        return self.cas_table.publish(c);
    }

    /// Build a `result<X, keyvalue/store.error>` err lift with the
    /// unit-typed `no-such-store` or `access-denied` variant. The
    /// returned `InterfaceValue` is allocator-owned.
    fn keyvalueResultErrSimple(allocator: Allocator, tag: KeyvalueErrorTag) !InterfaceValue {
        std.debug.assert(tag != .other);
        const err_payload = try allocator.create(InterfaceValue);
        err_payload.* = .{ .variant_val = .{
            .discriminant = @intFromEnum(tag),
            .payload = null,
        } };
        return .{ .result_val = .{ .is_ok = false, .payload = err_payload } };
    }

    /// Build a `result<X, keyvalue/store.error>` err lift with the
    /// `other(string)` payload. The string is `hostAllocAndWrite`'d
    /// into guest linear memory through `ci`.
    fn keyvalueResultErrOther(
        ci: *ComponentInstance,
        allocator: Allocator,
        message: []const u8,
    ) !InterfaceValue {
        const ptr = ci.hostAllocAndWrite(message, 1) orelse return error.OutOfMemory;
        const string_val = try allocator.create(InterfaceValue);
        string_val.* = .{ .string = .{ .ptr = ptr, .len = @intCast(message.len) } };
        const err_payload = try allocator.create(InterfaceValue);
        err_payload.* = .{ .variant_val = .{
            .discriminant = @intFromEnum(KeyvalueErrorTag.other),
            .payload = string_val,
        } };
        return .{ .result_val = .{ .is_ok = false, .payload = err_payload } };
    }

    /// Build a `result<X, error>` ok lift carrying `value`. Moves the
    /// caller-supplied `value` into a fresh `*InterfaceValue` payload.
    fn keyvalueResultOk(allocator: Allocator, value: InterfaceValue) !InterfaceValue {
        const payload = try allocator.create(InterfaceValue);
        payload.* = value;
        return .{ .result_val = .{ .is_ok = true, .payload = payload } };
    }

    /// `wasi:keyvalue/store.open: (identifier: string) -> result<own<bucket>, error>`.
    ///
    /// Opens (or creates on first access) the bucket named
    /// `identifier`. Identifiers are case-sensitive and the same
    /// identifier may be opened multiple times — each call returns a
    /// fresh handle, with all opens sharing the same backing storage
    /// keyed by identifier. The bucket lives until every handle to it
    /// is dropped *and* the adapter itself tears down; we don't
    /// proactively GC empty buckets.
    fn keyvalueStoreOpen(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const ident_pl = switch (args[0]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        const ident_bytes = if (ident_pl.len == 0)
            @as([]const u8, "")
        else
            ci.readGuestBytes(ident_pl.ptr, ident_pl.len) orelse
                return error.OutOfBoundsMemory;

        // The bucket's identifier + all entries are owned by the
        // adapter's allocator so `bucket.deinit(self.allocator)`
        // (called by `keyvalueBucketDrop` and `WasiCliAdapter.deinit`)
        // matches the alloc side. Don't reuse the canon-ABI
        // `allocator` parameter here — it's per-call and would
        // produce a cross-allocator free.
        const ident_copy = try self.allocator.dupe(u8, ident_bytes);
        errdefer self.allocator.free(ident_copy);
        const bucket = try self.allocator.create(KeyvalueBucket);
        errdefer self.allocator.destroy(bucket);
        bucket.* = .{ .identifier = ident_copy };

        // Persistence mode (#583 B4 follow-up): if a snapshot for
        // this identifier exists, hydrate the bucket's `entries`
        // from it. Both keys and values are duplicated so the
        // bucket and the persistence layer have independent
        // ownership — `bucket.deinit` frees the bucket side,
        // `keyvalue_persisted.deinit` frees the snapshot side.
        self.keyvalue_state_claim.acquire();
        defer self.keyvalue_state_claim.release();
        if (self.keyvalue_persisted.get(ident_bytes)) |snap| {
            bucket.entries.ensureTotalCapacity(self.allocator, snap.entries.count()) catch {
                bucket.deinit(self.allocator);
                self.allocator.destroy(bucket);
                results[0] = try keyvalueResultErrOther(ci, allocator, "insufficient memory");
                return;
            };
            var it = snap.entries.iterator();
            while (it.next()) |e| {
                const k_dup = self.allocator.dupe(u8, e.key_ptr.*) catch {
                    bucket.deinit(self.allocator);
                    self.allocator.destroy(bucket);
                    results[0] = try keyvalueResultErrOther(ci, allocator, "insufficient memory");
                    return;
                };
                const v_dup = self.allocator.dupe(u8, e.value_ptr.*) catch {
                    self.allocator.free(k_dup);
                    bucket.deinit(self.allocator);
                    self.allocator.destroy(bucket);
                    results[0] = try keyvalueResultErrOther(ci, allocator, "insufficient memory");
                    return;
                };
                bucket.entries.putAssumeCapacity(k_dup, v_dup);
            }
        }

        const handle = self.pushKeyvalueBucket(bucket) catch {
            bucket.deinit(self.allocator);
            self.allocator.destroy(bucket);
            results[0] = try keyvalueResultErrOther(ci, allocator, "insufficient memory");
            return;
        };
        results[0] = try keyvalueResultOk(allocator, .{ .handle = handle });
    }

    /// `[method]bucket.get: (borrow<bucket>, key: string) -> result<option<list<u8>>, error>`.
    fn keyvalueBucketGet(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const key_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        var bucket_lease = self.lookupKeyvalueBucket(handle) orelse {
            results[0] = try keyvalueResultErrSimple(allocator, .no_such_store);
            return;
        };
        defer bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        defer bucket.operation_claim.release();
        const key_bytes = if (key_pl.len == 0)
            @as([]const u8, "")
        else
            ci.readGuestBytes(key_pl.ptr, key_pl.len) orelse
                return error.OutOfBoundsMemory;
        if (bucket.entries.get(key_bytes)) |val| {
            const guest_ptr: u32 = if (val.len == 0)
                (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
            else
                (ci.hostAllocAndWrite(val, 1) orelse return error.OutOfMemory);
            const list_val = try allocator.create(InterfaceValue);
            list_val.* = .{ .list = .{ .ptr = guest_ptr, .len = @intCast(val.len) } };
            results[0] = try keyvalueResultOk(allocator, .{ .option_val = .{
                .is_some = true,
                .payload = list_val,
            } });
        } else {
            results[0] = try keyvalueResultOk(allocator, .{ .option_val = .{
                .is_some = false,
                .payload = null,
            } });
        }
    }

    /// `[method]bucket.set: (borrow<bucket>, key: string, value: list<u8>) -> result<_, error>`.
    fn keyvalueBucketSet(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const key_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        const value_pl = switch (args[2]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        var bucket_lease = self.lookupKeyvalueBucket(handle) orelse {
            results[0] = try keyvalueResultErrSimple(allocator, .no_such_store);
            return;
        };
        defer bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        defer bucket.operation_claim.release();
        const key_bytes = if (key_pl.len == 0)
            @as([]const u8, "")
        else
            ci.readGuestBytes(key_pl.ptr, key_pl.len) orelse
                return error.OutOfBoundsMemory;
        const value_bytes = if (value_pl.len == 0)
            @as([]const u8, "")
        else
            ci.readGuestBytes(value_pl.ptr, value_pl.len) orelse
                return error.OutOfBoundsMemory;
        try bucketStoreEntry(self, bucket, key_bytes, value_bytes);
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// Insert `key` → `value` into `bucket`, replacing any existing
    /// entry. Both inputs are duplicated through the adapter's
    /// allocator; the previous key+value (if any) are freed. Also
    /// mirrors the write into the persistence snapshot (if any) +
    /// flushes the snapshot to disk (#583 B4 follow-up).
    fn bucketStoreEntry(
        self: *WasiCliAdapter,
        bucket: *KeyvalueBucket,
        key: []const u8,
        value: []const u8,
    ) !void {
        const new_value = try self.allocator.dupe(u8, value);
        errdefer self.allocator.free(new_value);
        const gop = try bucket.entries.getOrPut(self.allocator, key);
        if (gop.found_existing) {
            self.allocator.free(gop.value_ptr.*);
            gop.value_ptr.* = new_value;
        } else {
            const key_copy = self.allocator.dupe(u8, key) catch |err| {
                _ = bucket.entries.remove(key);
                return err;
            };
            gop.key_ptr.* = key_copy;
            gop.value_ptr.* = new_value;
        }
        try self.persistedStoreEntry(bucket.identifier, key, value);
    }

    /// Remove `key` from `bucket`, freeing the owned key and value
    /// byte slices. Returns whether the entry was present. Also
    /// mirrors the removal into the persistence snapshot (#583 B4
    /// follow-up) — persistence flush is invoked unconditionally
    /// so a no-op delete still produces a stable on-disk view.
    fn bucketRemoveEntry(
        self: *WasiCliAdapter,
        bucket: *KeyvalueBucket,
        key: []const u8,
    ) bool {
        const present = if (bucket.entries.fetchRemove(key)) |entry| blk: {
            self.allocator.free(entry.key);
            self.allocator.free(entry.value);
            break :blk true;
        } else false;
        self.persistedRemoveEntry(bucket.identifier, key) catch {};
        return present;
    }

    /// `[method]bucket.delete: (borrow<bucket>, key: string) -> result<_, error>`.
    fn keyvalueBucketDelete(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const key_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        var bucket_lease = self.lookupKeyvalueBucket(handle) orelse {
            results[0] = try keyvalueResultErrSimple(allocator, .no_such_store);
            return;
        };
        defer bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        defer bucket.operation_claim.release();
        const key_bytes = if (key_pl.len == 0)
            @as([]const u8, "")
        else
            ci.readGuestBytes(key_pl.ptr, key_pl.len) orelse
                return error.OutOfBoundsMemory;
        // Per WIT: "If the key does not exist in the store, it does
        // nothing." — succeed either way.
        _ = bucketRemoveEntry(self, bucket, key_bytes);
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `[method]bucket.exists: (borrow<bucket>, key: string) -> result<bool, error>`.
    fn keyvalueBucketExists(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const key_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        var bucket_lease = self.lookupKeyvalueBucket(handle) orelse {
            results[0] = try keyvalueResultErrSimple(allocator, .no_such_store);
            return;
        };
        defer bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        defer bucket.operation_claim.release();
        const key_bytes = if (key_pl.len == 0)
            @as([]const u8, "")
        else
            ci.readGuestBytes(key_pl.ptr, key_pl.len) orelse
                return error.OutOfBoundsMemory;
        const present = bucket.entries.contains(key_bytes);
        results[0] = try keyvalueResultOk(allocator, .{ .bool = present });
    }

    /// `[method]bucket.list-keys: (borrow<bucket>, cursor: option<string>) -> result<key-response, error>`.
    ///
    /// `key-response` is a record `{ keys: list<string>, cursor: option<string> }`.
    /// Pagination uses a base-10 ASCII u64 cursor in `cursor` —
    /// it's the index of the *next* key in the bucket's iteration
    /// order. Iteration order is the HashMap's natural order, which
    /// is unspecified per WIT.
    fn keyvalueBucketListKeys(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const cursor_opt = switch (args[1]) {
            .option_val => |o| o,
            else => return error.InvalidArgs,
        };
        var bucket_lease = self.lookupKeyvalueBucket(handle) orelse {
            results[0] = try keyvalueResultErrSimple(allocator, .no_such_store);
            return;
        };
        defer bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        defer bucket.operation_claim.release();

        var start_index: usize = 0;
        if (cursor_opt.is_some) {
            const cursor_val = cursor_opt.payload orelse {
                results[0] = try keyvalueResultErrOther(ci, allocator, "malformed cursor");
                return;
            };
            const cursor_pl = switch (cursor_val.*) {
                .string => |pl| pl,
                else => {
                    results[0] = try keyvalueResultErrOther(ci, allocator, "malformed cursor");
                    return;
                },
            };
            const cursor_bytes = if (cursor_pl.len == 0)
                @as([]const u8, "")
            else
                ci.readGuestBytes(cursor_pl.ptr, cursor_pl.len) orelse
                    return error.OutOfBoundsMemory;
            start_index = std.fmt.parseInt(usize, cursor_bytes, 10) catch {
                results[0] = try keyvalueResultErrOther(ci, allocator, "malformed cursor");
                return;
            };
        }

        // Snapshot the current key set in iteration order so the
        // cursor index has a stable meaning across the page boundary.
        // This is O(n) per `list-keys` call but the spec already
        // warns that the operation is expensive and the memory store
        // is bounded by the adapter's lifetime.
        var all_keys: std.ArrayListUnmanaged([]const u8) = .empty;
        defer all_keys.deinit(allocator);
        try all_keys.ensureTotalCapacityPrecise(allocator, bucket.entries.count());
        var it = bucket.entries.keyIterator();
        while (it.next()) |k| try all_keys.append(allocator, k.*);

        const total = all_keys.items.len;
        if (start_index > total) start_index = total;
        const end_index = @min(total, start_index +| KEYVALUE_LIST_KEYS_PAGE_SIZE);
        const page = all_keys.items[start_index..end_index];

        // Build `list<string>` for `keys` by writing the page into
        // guest linear memory: a `string` element is 8 bytes
        // (ptr + len), packed contiguously.
        const stride: u32 = 8;
        const list_ptr: u32 = if (page.len == 0)
            0
        else
            (ci.hostAllocGuest(@intCast(page.len * stride), 4) orelse return error.OutOfMemory);
        if (page.len != 0) {
            const dst = ci.writableGuestBytes(list_ptr, @intCast(page.len * stride)) orelse
                return error.OutOfMemory;
            var off: u32 = 0;
            for (page) |k| {
                const key_ptr: u32 = if (k.len == 0)
                    (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
                else
                    (ci.hostAllocAndWrite(k, 1) orelse return error.OutOfMemory);
                std.mem.writeInt(u32, dst[off..][0..4], key_ptr, .little);
                std.mem.writeInt(u32, dst[off + 4 ..][0..4], @intCast(k.len), .little);
                off += stride;
            }
        }

        const cursor_field: InterfaceValue = if (end_index < total) blk: {
            // Lift the next-page cursor as a decimal-ASCII string.
            var buf: [32]u8 = undefined;
            const s = std.fmt.bufPrint(&buf, "{d}", .{end_index}) catch unreachable;
            const ptr = ci.hostAllocAndWrite(s, 1) orelse return error.OutOfMemory;
            const some_val = try allocator.create(InterfaceValue);
            some_val.* = .{ .string = .{ .ptr = ptr, .len = @intCast(s.len) } };
            break :blk .{ .option_val = .{ .is_some = true, .payload = some_val } };
        } else .{ .option_val = .{ .is_some = false, .payload = null } };

        const record_fields = try allocator.alloc(InterfaceValue, 2);
        record_fields[0] = .{ .list = .{ .ptr = list_ptr, .len = @intCast(page.len) } };
        record_fields[1] = cursor_field;
        results[0] = try keyvalueResultOk(allocator, .{ .record_val = record_fields });
    }

    /// `[resource-drop]bucket: (own<bucket>) -> ()`.
    fn keyvalueBucketDrop(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        _ = self.keyvalue_buckets.remove(handle);
    }

    /// `wasi:keyvalue/atomics.increment: (borrow<bucket>, key: string, delta: s64) -> result<s64, error>`.
    ///
    /// Atomic read-modify-write of the s64 at `key`. The host-side
    /// "atomicity" is trivial: the adapter is single-threaded with
    /// respect to component-instance dispatch, so the whole call
    /// happens between executor ticks and no other guest can
    /// interleave.
    ///
    /// Missing-key semantics per WIT: "creates a new key-value pair
    /// with the value set to the given delta". The value is stored
    /// as a little-endian s64 byte array so a subsequent `bucket.get`
    /// can read it back (callers that mix `set` and `increment` on
    /// the same key SHOULD use the same encoding — the adapter
    /// doesn't validate the existing bytes beyond requiring exactly
    /// 8 bytes).
    fn keyvalueAtomicsIncrement(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const key_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        const delta = switch (args[2]) {
            .s64 => |v| v,
            else => return error.InvalidArgs,
        };
        var bucket_lease = self.lookupKeyvalueBucket(handle) orelse {
            results[0] = try keyvalueResultErrSimple(allocator, .no_such_store);
            return;
        };
        defer bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        defer bucket.operation_claim.release();
        const key_bytes = if (key_pl.len == 0)
            @as([]const u8, "")
        else
            ci.readGuestBytes(key_pl.ptr, key_pl.len) orelse
                return error.OutOfBoundsMemory;

        const current: i64 = if (bucket.entries.get(key_bytes)) |existing| blk: {
            if (existing.len != 8) {
                results[0] = try keyvalueResultErrOther(
                    ci,
                    allocator,
                    "existing value is not an 8-byte little-endian s64",
                );
                return;
            }
            break :blk std.mem.readInt(i64, existing[0..8], .little);
        } else 0;

        const next = std.math.add(i64, current, delta) catch {
            results[0] = try keyvalueResultErrOther(ci, allocator, "increment overflow");
            return;
        };

        var encoded: [8]u8 = undefined;
        std.mem.writeInt(i64, &encoded, next, .little);
        try bucketStoreEntry(self, bucket, key_bytes, &encoded);
        results[0] = try keyvalueResultOk(allocator, .{ .s64 = next });
    }

    /// Build a `cas-error::store-error(error::other(string))` lift.
    /// Owned by `allocator` (the per-call canon-ABI allocator).
    fn keyvalueCasErrStoreOther(
        ci: *ComponentInstance,
        allocator: Allocator,
        message: []const u8,
    ) !InterfaceValue {
        const ptr = ci.hostAllocAndWrite(message, 1) orelse return error.OutOfMemory;
        const string_val = try allocator.create(InterfaceValue);
        string_val.* = .{ .string = .{ .ptr = ptr, .len = @intCast(message.len) } };
        const inner_err = try allocator.create(InterfaceValue);
        inner_err.* = .{ .variant_val = .{
            .discriminant = @intFromEnum(KeyvalueErrorTag.other),
            .payload = string_val,
        } };
        const cas_err = try allocator.create(InterfaceValue);
        cas_err.* = .{ .variant_val = .{
            .discriminant = @intFromEnum(KeyvalueCasErrorTag.store_error),
            .payload = inner_err,
        } };
        return .{ .result_val = .{ .is_ok = false, .payload = cas_err } };
    }

    /// Build a `cas-error::store-error(error::<simple-tag>)` lift
    /// (i.e. `no-such-store` / `access-denied`).
    fn keyvalueCasErrStoreSimple(
        allocator: Allocator,
        tag: KeyvalueErrorTag,
    ) !InterfaceValue {
        std.debug.assert(tag != .other);
        const inner_err = try allocator.create(InterfaceValue);
        inner_err.* = .{ .variant_val = .{
            .discriminant = @intFromEnum(tag),
            .payload = null,
        } };
        const cas_err = try allocator.create(InterfaceValue);
        cas_err.* = .{ .variant_val = .{
            .discriminant = @intFromEnum(KeyvalueCasErrorTag.store_error),
            .payload = inner_err,
        } };
        return .{ .result_val = .{ .is_ok = false, .payload = cas_err } };
    }

    /// `wasi:keyvalue/atomics.swap: (own<cas>, list<u8>) -> result<_, cas-error>`.
    ///
    /// Atomic test-and-set against the in-memory bucket entry:
    ///
    ///   - If the bucket's current value byte-for-byte matches the
    ///     snapshot captured at `cas.new` time, the bucket is
    ///     updated with the new value, the persistence layer is
    ///     flushed (when `--keyvalue-store=<path>` is in effect),
    ///     the CAS handle is consumed (slot nulled, rep freed) and
    ///     the call lifts `result::ok`.
    ///   - On mismatch the CAS rep is *not* freed — its snapshot
    ///     is re-bound to the *current* bucket value (per the WIT:
    ///     "Implementors MUST return a CAS handle that has been
    ///     updated to the latest version") and the same handle is
    ///     lifted under the `cas-error::cas-failed(cas)` arm so
    ///     guests can retry without going through `cas.new` again.
    ///   - If the CAS handle is invalid (out-of-range / already
    ///     consumed) or its bucket has been dropped, the call lifts
    ///     `cas-error::store-error(error)` (#583 B4 follow-up).
    fn keyvalueAtomicsSwap(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const cas_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const value_pl = switch (args[1]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        var cas_lease = self.lookupCas(cas_handle) orelse {
            results[0] = try keyvalueCasErrStoreOther(ci, allocator, "invalid cas handle");
            return;
        };
        var cas_active = true;
        defer if (cas_active) cas_lease.release();
        const cas_rep = cas_lease.value().*;
        cas_rep.operation_claim.acquire();
        var cas_claimed = true;
        defer if (cas_claimed) cas_rep.operation_claim.release();
        var bucket_lease = self.lookupKeyvalueBucket(cas_rep.bucket_handle) orelse {
            results[0] = try keyvalueCasErrStoreSimple(allocator, .no_such_store);
            return;
        };
        var bucket_active = true;
        defer if (bucket_active) bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        var bucket_claimed = true;
        defer if (bucket_claimed) bucket.operation_claim.release();
        const new_value_bytes = if (value_pl.len == 0)
            @as([]const u8, "")
        else
            ci.readGuestBytes(value_pl.ptr, value_pl.len) orelse
                return error.OutOfBoundsMemory;

        const current_opt: ?[]const u8 = bucket.entries.get(cas_rep.key);
        const matches = blk: {
            if (cas_rep.is_observed) {
                const cur = current_opt orelse break :blk false;
                break :blk std.mem.eql(u8, cur, cas_rep.observed);
            } else {
                break :blk (current_opt == null);
            }
        };

        if (matches) {
            // Atomic write — also mirrors into the persistence
            // snapshot via `bucketStoreEntry`.
            try bucketStoreEntry(self, bucket, cas_rep.key, new_value_bytes);
            // Consume the CAS handle.
            bucket.operation_claim.release();
            bucket_claimed = false;
            bucket_lease.release();
            bucket_active = false;
            cas_rep.operation_claim.release();
            cas_claimed = false;
            cas_lease.release();
            cas_active = false;
            _ = self.cas_table.remove(cas_handle);
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        }

        // Mismatch: re-snapshot the CAS to the current bucket value
        // and lift it under `cas-error::cas-failed(cas)`.
        if (cas_rep.is_observed) {
            self.allocator.free(cas_rep.observed);
            cas_rep.is_observed = false;
            cas_rep.observed = "";
        }
        if (current_opt) |cur| {
            const dup = self.allocator.dupe(u8, cur) catch {
                results[0] = try keyvalueCasErrStoreOther(ci, allocator, "insufficient memory");
                return;
            };
            cas_rep.observed = dup;
            cas_rep.is_observed = true;
        }
        const new_cas_handle = try allocator.create(InterfaceValue);
        new_cas_handle.* = .{ .handle = cas_handle };
        const cas_err = try allocator.create(InterfaceValue);
        cas_err.* = .{ .variant_val = .{
            .discriminant = @intFromEnum(KeyvalueCasErrorTag.cas_failed),
            .payload = new_cas_handle,
        } };
        results[0] = .{ .result_val = .{ .is_ok = false, .payload = cas_err } };
    }

    /// `[static]cas.new: (borrow<bucket>, key: string) -> result<own<cas>, error>`.
    ///
    /// Snapshot the bucket's value at `key` (or `null` if absent)
    /// and return a fresh CAS handle. The snapshot is byte-stable
    /// across other guests' writes — `atomics.swap` then compares
    /// the bucket's *current* value to this snapshot to decide
    /// whether the test-and-set succeeds. (#583 B4 follow-up)
    fn keyvalueCasNew(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const bucket_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const key_pl = switch (args[1]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        var bucket_lease = self.lookupKeyvalueBucket(bucket_handle) orelse {
            results[0] = try keyvalueResultErrSimple(allocator, .no_such_store);
            return;
        };
        defer bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        defer bucket.operation_claim.release();
        const key_bytes = if (key_pl.len == 0)
            @as([]const u8, "")
        else
            ci.readGuestBytes(key_pl.ptr, key_pl.len) orelse
                return error.OutOfBoundsMemory;

        const key_copy = try self.allocator.dupe(u8, key_bytes);
        errdefer self.allocator.free(key_copy);

        var observed_copy: []u8 = &.{};
        var is_observed = false;
        if (bucket.entries.get(key_bytes)) |existing| {
            observed_copy = try self.allocator.dupe(u8, existing);
            is_observed = true;
        }
        errdefer if (is_observed) self.allocator.free(observed_copy);

        const cas_rep = try self.allocator.create(Cas);
        errdefer self.allocator.destroy(cas_rep);
        cas_rep.* = .{
            .bucket_handle = bucket_handle,
            .key = key_copy,
            .observed = if (is_observed) observed_copy else "",
            .is_observed = is_observed,
        };
        const handle = self.pushCas(cas_rep) catch {
            cas_rep.deinit(self.allocator);
            self.allocator.destroy(cas_rep);
            results[0] = try keyvalueResultErrOther(ci, allocator, "insufficient memory");
            return;
        };
        results[0] = try keyvalueResultOk(allocator, .{ .handle = handle });
    }

    /// `[method]cas.current: (borrow<cas>) -> result<option<list<u8>>, error>`.
    ///
    /// Lift the snapshot captured by `cas.new` — `option::some(bytes)`
    /// if the key was present at constructor time, `option::none`
    /// otherwise. Stays stable across other writes to the same
    /// bucket; `swap` is the only call that mutates the snapshot
    /// (on CAS-failed retry). (#583 B4 follow-up)
    fn keyvalueCasCurrent(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const cas_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        var cas_lease = self.lookupCas(cas_handle) orelse {
            results[0] = try keyvalueResultErrOther(ci, allocator, "invalid cas handle");
            return;
        };
        defer cas_lease.release();
        const cas_rep = cas_lease.value().*;
        cas_rep.operation_claim.acquire();
        defer cas_rep.operation_claim.release();
        if (!cas_rep.is_observed) {
            results[0] = try keyvalueResultOk(allocator, .{ .option_val = .{
                .is_some = false,
                .payload = null,
            } });
            return;
        }
        const observed = cas_rep.observed;
        const guest_ptr: u32 = if (observed.len == 0)
            (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
        else
            (ci.hostAllocAndWrite(observed, 1) orelse return error.OutOfMemory);
        const list_val = try allocator.create(InterfaceValue);
        list_val.* = .{ .list = .{ .ptr = guest_ptr, .len = @intCast(observed.len) } };
        results[0] = try keyvalueResultOk(allocator, .{ .option_val = .{
            .is_some = true,
            .payload = list_val,
        } });
    }

    /// `[resource-drop]cas: (own<cas>) -> ()`.
    ///
    /// Frees the CAS rep + its owned key/snapshot slices and nulls
    /// the table slot. Idempotent — drops on already-consumed (e.g.
    /// after a successful `swap`) or invalid handles are silently
    /// ignored. (#583 B4 follow-up)
    fn keyvalueCasDrop(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        _ = self.cas_table.remove(handle);
    }

    /// `wasi:keyvalue/batch.get-many: (borrow<bucket>, list<string>) -> result<list<option<tuple<string, list<u8>>>>, error>`.
    fn keyvalueBatchGetMany(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const keys_pl = switch (args[1]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        var bucket_lease = self.lookupKeyvalueBucket(handle) orelse {
            results[0] = try keyvalueResultErrSimple(allocator, .no_such_store);
            return;
        };
        defer bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        defer bucket.operation_claim.release();

        // Each `string` element is 8 bytes (ptr + len) in linear memory.
        const stride: u32 = 8;
        const keys_count = keys_pl.len;
        const keys_bytes: []const u8 = if (keys_count == 0)
            &.{}
        else
            (ci.readGuestBytes(keys_pl.ptr, keys_count * stride) orelse
                return error.OutOfBoundsMemory);

        // `list<option<tuple<string, list<u8>>>>` in linear memory.
        // Per the canonical ABI each `option<T>` is `1 + sizeof(T)`
        // bytes with alignment max(1, align(T)). The inner tuple is
        // `{ string (8B), list<u8> (8B) }` with 4-byte alignment, so
        // the option is laid out as: discriminant @0:u8, padding to
        // @4, tuple_str_ptr @4:u32, tuple_str_len @8:u32, tuple_list_ptr
        // @12:u32, tuple_list_len @16:u32 — 20 bytes total. Align 4.
        const opt_stride: u32 = 20;
        const out_total: u32 = @intCast(keys_count * opt_stride);
        const out_ptr: u32 = if (keys_count == 0)
            0
        else
            (ci.hostAllocGuest(out_total, 4) orelse return error.OutOfMemory);
        if (keys_count > 0) {
            const dst = ci.writableGuestBytes(out_ptr, out_total) orelse
                return error.OutOfMemory;
            @memset(dst, 0);
            var idx: u32 = 0;
            while (idx < keys_count) : (idx += 1) {
                const in_off = idx * stride;
                const k_ptr = std.mem.readInt(u32, keys_bytes[in_off..][0..4], .little);
                const k_len = std.mem.readInt(u32, keys_bytes[in_off + 4 ..][0..4], .little);
                const k_bytes = if (k_len == 0)
                    @as([]const u8, "")
                else
                    ci.readGuestBytes(k_ptr, k_len) orelse return error.OutOfBoundsMemory;
                const out_off = idx * opt_stride;
                if (bucket.entries.getEntry(k_bytes)) |entry| {
                    const stored_value = entry.value_ptr.*;
                    // Re-emit the key as a fresh `hostAllocAndWrite`
                    // so the lifted tuple is self-contained (the
                    // guest's input pointer might get freed before
                    // the result is read).
                    const k_out_ptr: u32 = if (k_bytes.len == 0)
                        (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
                    else
                        (ci.hostAllocAndWrite(k_bytes, 1) orelse return error.OutOfMemory);
                    const v_out_ptr: u32 = if (stored_value.len == 0)
                        (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
                    else
                        (ci.hostAllocAndWrite(stored_value, 1) orelse return error.OutOfMemory);
                    dst[out_off] = 1; // option::some discriminant.
                    std.mem.writeInt(u32, dst[out_off + 4 ..][0..4], k_out_ptr, .little);
                    std.mem.writeInt(u32, dst[out_off + 8 ..][0..4], @intCast(k_bytes.len), .little);
                    std.mem.writeInt(u32, dst[out_off + 12 ..][0..4], v_out_ptr, .little);
                    std.mem.writeInt(u32, dst[out_off + 16 ..][0..4], @intCast(stored_value.len), .little);
                } else {
                    // option::none — discriminant 0, rest is undefined
                    // but cleared by the @memset above.
                    dst[out_off] = 0;
                }
            }
        }
        results[0] = try keyvalueResultOk(allocator, .{ .list = .{
            .ptr = out_ptr,
            .len = @intCast(keys_count),
        } });
    }

    /// `wasi:keyvalue/batch.set-many: (borrow<bucket>, list<tuple<string, list<u8>>>) -> result<_, error>`.
    fn keyvalueBatchSetMany(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const list_pl = switch (args[1]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        var bucket_lease = self.lookupKeyvalueBucket(handle) orelse {
            results[0] = try keyvalueResultErrSimple(allocator, .no_such_store);
            return;
        };
        defer bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        defer bucket.operation_claim.release();

        // Each `tuple<string, list<u8>>` is 16 bytes in linear memory.
        const stride: u32 = 16;
        const count = list_pl.len;
        const list_bytes: []const u8 = if (count == 0)
            &.{}
        else
            (ci.readGuestBytes(list_pl.ptr, count * stride) orelse
                return error.OutOfBoundsMemory);

        var idx: u32 = 0;
        while (idx < count) : (idx += 1) {
            const off = idx * stride;
            const k_ptr = std.mem.readInt(u32, list_bytes[off..][0..4], .little);
            const k_len = std.mem.readInt(u32, list_bytes[off + 4 ..][0..4], .little);
            const v_ptr = std.mem.readInt(u32, list_bytes[off + 8 ..][0..4], .little);
            const v_len = std.mem.readInt(u32, list_bytes[off + 12 ..][0..4], .little);
            const k_bytes = if (k_len == 0)
                @as([]const u8, "")
            else
                ci.readGuestBytes(k_ptr, k_len) orelse return error.OutOfBoundsMemory;
            const v_bytes = if (v_len == 0)
                @as([]const u8, "")
            else
                ci.readGuestBytes(v_ptr, v_len) orelse return error.OutOfBoundsMemory;
            try bucketStoreEntry(self, bucket, k_bytes, v_bytes);
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `wasi:keyvalue/batch.delete-many: (borrow<bucket>, list<string>) -> result<_, error>`.
    fn keyvalueBatchDeleteMany(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const keys_pl = switch (args[1]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        var bucket_lease = self.lookupKeyvalueBucket(handle) orelse {
            results[0] = try keyvalueResultErrSimple(allocator, .no_such_store);
            return;
        };
        defer bucket_lease.release();
        const bucket = bucket_lease.value().*;
        bucket.operation_claim.acquire();
        defer bucket.operation_claim.release();
        const stride: u32 = 8;
        const count = keys_pl.len;
        const keys_bytes: []const u8 = if (count == 0)
            &.{}
        else
            (ci.readGuestBytes(keys_pl.ptr, count * stride) orelse
                return error.OutOfBoundsMemory);
        var idx: u32 = 0;
        while (idx < count) : (idx += 1) {
            const off = idx * stride;
            const k_ptr = std.mem.readInt(u32, keys_bytes[off..][0..4], .little);
            const k_len = std.mem.readInt(u32, keys_bytes[off + 4 ..][0..4], .little);
            const k_bytes = if (k_len == 0)
                @as([]const u8, "")
            else
                ci.readGuestBytes(k_ptr, k_len) orelse return error.OutOfBoundsMemory;
            _ = bucketRemoveEntry(self, bucket, k_bytes);
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    // ── wasi:keyvalue persistence layer (#583 B4 follow-up) ─────────────
    //
    // Optional file-backed snapshot of every `KeyvalueBucket`. Enabled
    // by `setKeyvalueStorePath` (wired to the `--keyvalue-store=<path>`
    // CLI flag in `main.zig`). When disabled (`keyvalue_store_path ==
    // null`, the default), `persistedStoreEntry` / `persistedRemoveEntry`
    // / `flushKeyvalueStore` are all no-ops and the runtime behaves
    // exactly like PR #601 (in-memory only).
    //
    // File format — JSON object whose top-level keys are bucket
    // identifiers; each value is itself an object mapping key strings
    // to **base64-encoded** value bytes (so binary values survive a
    // round-trip without forcing UTF-8 on the wire). Empty buckets are
    // serialised as `"name": {}`.
    //
    //   ```json
    //   {
    //     "primary":  { "alpha": "dmFsdWU=", "beta": "YnVm" },
    //     "counters": { "hits":  "AwAAAAAAAAA=" }
    //   }
    //   ```
    //
    // The serialiser writes the entire JSON document on every mutation
    // — `set` / `delete` / successful `swap` / `increment` /
    // `batch.set-many` / `batch.delete-many` all flush. This is the
    // simplest correct MVP; an atomic-rename (write to `<path>.tmp`,
    // then `rename`) is documented in `docs/wasi.md` as future
    // hardening.

    /// Lookup or lazily create a `PersistedBucket` for `identifier`.
    /// The identifier slice is copied into the adapter's allocator
    /// on first insert (so the caller can pass borrowed bytes); the
    /// returned pointer is stable for the lifetime of the adapter.
    fn persistedBucketGetOrCreate(self: *WasiCliAdapter, identifier: []const u8) !*PersistedBucket {
        const gop = try self.keyvalue_persisted.getOrPut(self.allocator, identifier);
        if (!gop.found_existing) {
            const key_dup = self.allocator.dupe(u8, identifier) catch |err| {
                _ = self.keyvalue_persisted.remove(identifier);
                return err;
            };
            const bucket = self.allocator.create(PersistedBucket) catch |err| {
                self.allocator.free(key_dup);
                _ = self.keyvalue_persisted.remove(identifier);
                return err;
            };
            bucket.* = .{};
            gop.key_ptr.* = key_dup;
            gop.value_ptr.* = bucket;
        }
        return gop.value_ptr.*;
    }

    /// Mirror a `bucketStoreEntry` write into the persistence
    /// snapshot. No-op when `keyvalue_store_path == null`. Synchronously
    /// rewrites the file via `flushKeyvalueStore`.
    fn persistedStoreEntry(
        self: *WasiCliAdapter,
        identifier: []const u8,
        key: []const u8,
        value: []const u8,
    ) !void {
        self.keyvalue_state_claim.acquire();
        defer self.keyvalue_state_claim.release();
        if (self.keyvalue_store_path == null) return;
        const bucket = try self.persistedBucketGetOrCreate(identifier);
        const new_value = try self.allocator.dupe(u8, value);
        errdefer self.allocator.free(new_value);
        const gop = try bucket.entries.getOrPut(self.allocator, key);
        if (gop.found_existing) {
            self.allocator.free(gop.value_ptr.*);
            gop.value_ptr.* = new_value;
        } else {
            const key_copy = self.allocator.dupe(u8, key) catch |err| {
                _ = bucket.entries.remove(key);
                return err;
            };
            gop.key_ptr.* = key_copy;
            gop.value_ptr.* = new_value;
        }
        try self.flushKeyvalueStore();
    }

    /// Mirror a `bucketRemoveEntry` into the persistence snapshot.
    /// No-op when `keyvalue_store_path == null`. Synchronously
    /// rewrites the file via `flushKeyvalueStore`.
    fn persistedRemoveEntry(
        self: *WasiCliAdapter,
        identifier: []const u8,
        key: []const u8,
    ) !void {
        self.keyvalue_state_claim.acquire();
        defer self.keyvalue_state_claim.release();
        if (self.keyvalue_store_path == null) return;
        if (self.keyvalue_persisted.get(identifier)) |bucket| {
            if (bucket.entries.fetchRemove(key)) |entry| {
                self.allocator.free(entry.key);
                self.allocator.free(entry.value);
            }
        }
        try self.flushKeyvalueStore();
    }

    /// Serialise `keyvalue_persisted` to `keyvalue_store_path` as
    /// the JSON object documented above. Synchronous + non-atomic —
    /// the file may be observed in a half-written state if the host
    /// crashes mid-write; that's the documented MVP trade-off.
    /// No-op when `keyvalue_store_path == null`.
    fn flushKeyvalueStore(self: *WasiCliAdapter) !void {
        const path = self.keyvalue_store_path orelse return;

        var aw: std.Io.Writer.Allocating = .init(self.allocator);
        defer aw.deinit();
        var stringify: std.json.Stringify = .{ .writer = &aw.writer, .options = .{} };
        try stringify.beginObject();

        // Stable iteration order isn't promised by the underlying
        // HashMap; that's fine for the JSON consumer (we don't claim
        // line-stable diffs as an MVP feature).
        var bit = self.keyvalue_persisted.iterator();
        while (bit.next()) |bkv| {
            try stringify.objectField(bkv.key_ptr.*);
            try stringify.beginObject();
            var eit = bkv.value_ptr.*.entries.iterator();
            while (eit.next()) |ekv| {
                try stringify.objectField(ekv.key_ptr.*);
                const value_bytes = ekv.value_ptr.*;
                const enc_len = std.base64.standard.Encoder.calcSize(value_bytes.len);
                const enc_buf = try self.allocator.alloc(u8, enc_len);
                defer self.allocator.free(enc_buf);
                const encoded = std.base64.standard.Encoder.encode(enc_buf, value_bytes);
                try stringify.write(encoded);
            }
            try stringify.endObject();
        }
        try stringify.endObject();

        const io = std.Io.Threaded.global_single_threaded.io();
        try std.Io.Dir.cwd().writeFile(io, .{
            .sub_path = path,
            .data = aw.written(),
        });
    }

    /// Enable the file-backed persistence layer (`--keyvalue-store=<path>`).
    ///
    /// If `path` already exists, its JSON contents are parsed and
    /// loaded into `keyvalue_persisted` so subsequent `open` calls
    /// hydrate from the snapshot. A missing file is *not* an error —
    /// the persistence layer is activated empty and the file is
    /// created on the first flush. The path slice is duplicated
    /// into the adapter's allocator. (#583 B4 follow-up)
    ///
    /// Errors:
    ///   - `error.KeyvalueStoreInvalidJson` — file is not valid JSON
    ///   - `error.KeyvalueStoreInvalidRoot` — root is not an object
    ///   - `error.KeyvalueStoreInvalidBucket` — a bucket entry is
    ///     not an object
    ///   - `error.KeyvalueStoreInvalidValueType` — a value is not a
    ///     string
    ///   - `error.KeyvalueStoreInvalidBase64` — a value isn't valid
    ///     base64
    ///   - allocator failures bubble up unchanged.
    pub fn setKeyvalueStorePath(self: *WasiCliAdapter, path: []const u8) !void {
        self.keyvalue_state_claim.acquire();
        defer self.keyvalue_state_claim.release();
        const path_dup = try self.allocator.dupe(u8, path);
        errdefer self.allocator.free(path_dup);
        if (self.keyvalue_store_path) |old| self.allocator.free(old);
        self.keyvalue_store_path = path_dup;

        const cwd = std.Io.Dir.cwd();
        const io = std.Io.Threaded.global_single_threaded.io();
        const bytes = cwd.readFileAlloc(io, path, self.allocator, @enumFromInt(8 * 1024 * 1024)) catch |err| switch (err) {
            error.FileNotFound => return, // first run — leave snapshot empty
            else => return err,
        };
        defer self.allocator.free(bytes);

        var parsed = std.json.parseFromSlice(std.json.Value, self.allocator, bytes, .{}) catch {
            return error.KeyvalueStoreInvalidJson;
        };
        defer parsed.deinit();

        switch (parsed.value) {
            .object => |obj| {
                var bit = obj.iterator();
                while (bit.next()) |bkv| {
                    const inner = switch (bkv.value_ptr.*) {
                        .object => |o| o,
                        else => return error.KeyvalueStoreInvalidBucket,
                    };
                    const bucket = try self.persistedBucketGetOrCreate(bkv.key_ptr.*);
                    var eit = inner.iterator();
                    while (eit.next()) |ekv| {
                        const value_str = switch (ekv.value_ptr.*) {
                            .string => |s| s,
                            else => return error.KeyvalueStoreInvalidValueType,
                        };
                        const dec_len = std.base64.standard.Decoder.calcSizeForSlice(value_str) catch {
                            return error.KeyvalueStoreInvalidBase64;
                        };
                        const value_dup = try self.allocator.alloc(u8, dec_len);
                        errdefer self.allocator.free(value_dup);
                        std.base64.standard.Decoder.decode(value_dup, value_str) catch {
                            return error.KeyvalueStoreInvalidBase64;
                        };
                        const key_dup = try self.allocator.dupe(u8, ekv.key_ptr.*);
                        errdefer self.allocator.free(key_dup);
                        const gop = try bucket.entries.getOrPut(self.allocator, key_dup);
                        if (gop.found_existing) {
                            self.allocator.free(key_dup);
                            self.allocator.free(gop.value_ptr.*);
                            gop.value_ptr.* = value_dup;
                        } else {
                            gop.key_ptr.* = key_dup;
                            gop.value_ptr.* = value_dup;
                        }
                    }
                }
            },
            else => return error.KeyvalueStoreInvalidRoot,
        }
    }

    // ── wasi:config/store@0.2.0-rc.1 — adapter (#583 B6) ────────────────
    //
    // Layered configuration source for guest components. The interface
    // is two methods: `get(key) -> result<option<string>, error>` and
    // `get-all() -> result<list<tuple<string, string>>, error>`.
    //
    // The backing slice (`self.config_store`) is populated by the
    // embedder (e.g. `main.zig`'s `runComponent`) via `setConfigStore`.
    // wamr's CLI assembles it from two layers, in order:
    //
    //   1. Environment variables prefixed with `WAMR_CONFIG_` — the
    //      prefix is stripped and the remainder lower-cased
    //      (e.g. `WAMR_CONFIG_API_KEY=…` → `api_key=…`).
    //   2. A JSON file passed via `--config-store=<path>` containing a
    //      flat `{ "key": "value", … }` object.
    //
    // Precedence: **file overrides env** (the more deliberate
    // per-invocation override wins over a global default). The merge is
    // done in `main.zig` before calling `setConfigStore`; this adapter
    // only sees the final flat list.
    //
    // The host returns the `Ok` arm exclusively — every key is treated
    // as a successful lookup whose value is `Some/None`. The `error`
    // variant arms (`upstream(string)`, `io(string)`) are reserved for
    // future backends (Vault / Kubernetes / etc.) and are never
    // surfaced by the in-memory store. Documented in `docs/wasi.md`.
    //
    // WIT version pinned: `wasi:config@0.2.0-rc.1` (the only currently
    // published version — see `https://github.com/WebAssembly/wasi-config`).
    // The version-multiplex in `populateWasiProviders` routes any
    // `wasi:config/store@…` import (regardless of `@x.y.z` suffix) onto
    // this same host instance, so future 0.3.x / 0.4.x revisions that
    // keep the same method shape will continue to work without code
    // changes here. If a future revision breaks `result<option<string>,
    // error>` / `result<list<tuple<...>>, error>` we'll split the
    // populator like `populateWasiCliEnvironmentP3`.

    /// Register `wasi:config/store@0.2.0-rc.1.{get, get-all}` (#583 B6).
    pub fn populateWasiConfigStore(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        interface_name: []const u8,
    ) !void {
        try self.config_store_iface.members.put(self.allocator, "get", .{
            .func = .{ .context = self, .call = &configStoreGet },
        });
        try self.config_store_iface.members.put(self.allocator, "get-all", .{
            .func = .{ .context = self, .call = &configStoreGetAll },
        });
        try providers.put(self.allocator, interface_name, .{
            .host_instance = &self.config_store_iface,
        });
    }

    /// Pure data-layer lookup for `wasi:config/store.get` — walks
    /// `self.config_store` in registration order and returns the value
    /// for the first entry whose `name` matches `key` verbatim
    /// (case-sensitive). Returns `null` for missing keys. Exposed so
    /// unit tests can exercise the layered-precedence merge without
    /// constructing a `ComponentInstance`.
    pub fn lookupConfig(self: *const WasiCliAdapter, key: []const u8) ?[]const u8 {
        for (self.config_store) |entry| {
            if (std.mem.eql(u8, entry.name, key)) return entry.value;
        }
        return null;
    }

    /// `wasi:config/store.get: (key: string) -> result<option<string>, error>`.
    /// The in-memory store never errors — every lookup is `Ok(Some)` or
    /// `Ok(None)`. Caller-trampoline owns the returned value and
    /// deinits via the same allocator.
    fn configStoreGet(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const key_pl = switch (args[0]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        const key_bytes = ci.readGuestBytes(key_pl.ptr, key_pl.len) orelse
            return error.OutOfBoundsMemory;

        if (self.lookupConfig(key_bytes)) |value| {
            const value_ptr = ci.hostAllocAndWrite(value, 1) orelse
                return error.OutOfMemory;
            const str_iv = try allocator.create(InterfaceValue);
            errdefer allocator.destroy(str_iv);
            str_iv.* = .{ .string = .{ .ptr = value_ptr, .len = @intCast(value.len) } };
            const some_iv = try allocator.create(InterfaceValue);
            errdefer allocator.destroy(some_iv);
            some_iv.* = .{ .option_val = .{ .is_some = true, .payload = str_iv } };
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = some_iv } };
            return;
        }

        const none_iv = try allocator.create(InterfaceValue);
        errdefer allocator.destroy(none_iv);
        none_iv.* = .{ .option_val = .{ .is_some = false, .payload = null } };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = none_iv } };
    }

    /// `wasi:config/store.get-all: () -> result<list<tuple<string, string>>, error>`.
    /// Returns the merged store in registration order (env entries
    /// followed by file overrides, with file winning per the precedence
    /// rule documented above). The in-memory store never errors.
    fn configStoreGetAll(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;

        const n = self.config_store.len;
        const list_iv = try allocator.create(InterfaceValue);
        errdefer allocator.destroy(list_iv);

        if (n == 0) {
            list_iv.* = .{ .list = .{ .ptr = 0, .len = 0 } };
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = list_iv } };
            return;
        }

        // Each tuple<string, string>: name.ptr@0:u32, name.len@4:u32,
        // value.ptr@8:u32, value.len@12:u32. Stride = 16, align = 4.
        // Same layout as `getEnvironment`'s tuple list.
        const stride: usize = 16;
        const scratch = try allocator.alloc(u8, n * stride);
        defer allocator.free(scratch);

        for (self.config_store, 0..) |e, i| {
            const name_ptr = ci.hostAllocAndWrite(e.name, 1) orelse return error.OutOfMemory;
            const value_ptr = ci.hostAllocAndWrite(e.value, 1) orelse return error.OutOfMemory;
            const off = i * stride;
            std.mem.writeInt(u32, scratch[off..][0..4], name_ptr, .little);
            std.mem.writeInt(u32, scratch[off + 4 ..][0..4], @intCast(e.name.len), .little);
            std.mem.writeInt(u32, scratch[off + 8 ..][0..4], value_ptr, .little);
            std.mem.writeInt(u32, scratch[off + 12 ..][0..4], @intCast(e.value.len), .little);
        }

        const list_ptr = ci.hostAllocAndWrite(scratch, 4) orelse return error.OutOfMemory;
        list_iv.* = .{ .list = .{ .ptr = list_ptr, .len = @intCast(n) } };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = list_iv } };
    }
};

/// `wasi:clocks/wall-clock.datetime`: a record of `(seconds: u64, nanoseconds: u32)`.
pub const Datetime = struct {
    seconds: u64,
    nanoseconds: u32,
};

/// Read a POSIX clock and lift it into a `Datetime`. On failure (or where
/// `clock_gettime` is unavailable, e.g. Windows / freestanding), returns
/// the zero datetime — sufficient for the spec contract on those targets
/// (host clocks are never observed by the unit tests, which use the
/// adapter's deterministic-clock injection paths). Both fields are
/// clamped to valid ranges (`seconds >= 0`, `nanoseconds < 1e9`).
fn readClockDatetime(clock_id: ClockId) Datetime {
    if (!have_posix_clock) return .{ .seconds = 0, .nanoseconds = 0 };
    var ts: std.posix.timespec = undefined;
    const rc = std.posix.system.clock_gettime(clock_id, &ts);
    if (std.posix.errno(rc) != .SUCCESS) return .{ .seconds = 0, .nanoseconds = 0 };
    const secs: u64 = if (ts.sec < 0) 0 else @intCast(ts.sec);
    const nsec_raw = ts.nsec;
    const nsec: u32 = if (nsec_raw < 0)
        0
    else if (nsec_raw >= 1_000_000_000)
        999_999_999
    else
        @intCast(nsec_raw);
    return .{ .seconds = secs, .nanoseconds = nsec };
}

/// Read a POSIX clock and flatten to nanoseconds since its epoch. Used for
/// `monotonic-clock.now`, where preview-2's `instant` is a flat `u64`.
fn readClockNs(clock_id: ClockId) u64 {
    const dt = readClockDatetime(clock_id);
    return dt.seconds *% 1_000_000_000 +% @as(u64, dt.nanoseconds);
}

/// Cross-platform alias for the host clock-id type. On POSIX targets it
/// is `std.posix.clockid_t`; on Windows `std.posix.clockid_t` is `void`
/// and `clock_gettime` is unusable, so we substitute a plain enum so
/// `.REALTIME` / `.MONOTONIC` enum literals at the call sites still
/// compile. `readClockDatetime` short-circuits before consulting the
/// value on those targets, so the substitute never reaches the syscall.
const have_posix_clock = @import("builtin").os.tag != .windows and
    @hasDecl(std.posix.system, "clock_gettime");
const ClockId = if (have_posix_clock)
    std.posix.clockid_t
else
    enum { REALTIME, MONOTONIC };

/// Allocate an `InterfaceValue` carrying a `record { seconds: u64, nanoseconds: u32 }`
/// shape. Caller (the trampoline) `deinit`s the result via the same allocator.
fn buildDatetimeRecord(allocator: Allocator, dt: Datetime) !InterfaceValue {
    const fields = try allocator.alloc(InterfaceValue, 2);
    fields[0] = .{ .u64 = dt.seconds };
    fields[1] = .{ .u32 = dt.nanoseconds };
    return .{ .record_val = fields };
}

/// Convert `std.Io.Timestamp` (i96 nanoseconds since UNIX epoch) into the
/// WIT `datetime { seconds: u64, nanoseconds: u32 }` record. Negative
/// epoch values clamp to `{0,0}` (WIT u64 cannot represent pre-1970).
/// Seconds saturate at u64 max for far-future timestamps.
fn ioTimestampToDatetime(ts: std.Io.Timestamp) Datetime {
    if (ts.nanoseconds <= 0) return .{ .seconds = 0, .nanoseconds = 0 };
    const NS_PER_S: i96 = 1_000_000_000;
    const secs_i96 = @divTrunc(ts.nanoseconds, NS_PER_S);
    const nsec_i96 = @mod(ts.nanoseconds, NS_PER_S);
    const secs: u64 = if (secs_i96 > std.math.maxInt(u64))
        std.math.maxInt(u64)
    else
        @intCast(secs_i96);
    const nsec: u32 = @intCast(nsec_i96);
    return .{ .seconds = secs, .nanoseconds = nsec };
}

/// Lift an optional `Io.Timestamp` into the WIT `option<datetime>`.
/// `null` becomes `option::none`; non-null becomes `option::some(datetime)`.
fn buildOptionalDatetime(allocator: Allocator, maybe_ts: ?std.Io.Timestamp) !InterfaceValue {
    if (maybe_ts) |ts| {
        const dt_iv = try allocator.create(InterfaceValue);
        dt_iv.* = try buildDatetimeRecord(allocator, ioTimestampToDatetime(ts));
        return .{ .option_val = .{ .is_some = true, .payload = dt_iv } };
    } else {
        return .{ .option_val = .{ .is_some = false, .payload = null } };
    }
}

/// Lift the host `Io.File.Stat` into the WIT `descriptor-stat` record.
/// Field order matches the WIT declaration:
///   { type, link-count, size, data-access-timestamp,
///     data-modification-timestamp, status-change-timestamp }.
fn buildDescriptorStatRecord(
    allocator: Allocator,
    st: std.Io.File.Stat,
) !InterfaceValue {
    const dt: WasiCliAdapter.DescType = switch (st.kind) {
        .directory => .directory,
        .file => .regular_file,
        .block_device => .block_device,
        .character_device => .character_device,
        .named_pipe => .fifo,
        .sym_link => .symbolic_link,
        .unix_domain_socket => .socket,
        else => .unknown,
    };
    const fields = try allocator.alloc(InterfaceValue, 6);
    fields[0] = .{ .variant_val = .{ .discriminant = @intFromEnum(dt), .payload = null } };
    fields[1] = .{ .u64 = @intCast(st.nlink) };
    fields[2] = .{ .u64 = st.size };
    fields[3] = try buildOptionalDatetime(allocator, st.atime);
    fields[4] = try buildOptionalDatetime(allocator, st.mtime);
    fields[5] = try buildOptionalDatetime(allocator, st.ctime);
    return .{ .record_val = fields };
}

/// Lift the WIT `new-timestamp` variant into `std.Io.File.SetTimestamp`.
/// Discriminant order per the canonical `wasi:filesystem` WIT:
///   0 = no-change → `.unchanged`
///   1 = now       → `.now`
///   2 = timestamp(datetime) → `.new`
fn liftNewTimestamp(arg: InterfaceValue) !std.Io.File.SetTimestamp {
    const v = switch (arg) {
        .variant_val => |v| v,
        else => return error.InvalidArgs,
    };
    switch (v.discriminant) {
        0 => return .unchanged,
        1 => return .now,
        2 => {
            const payload = v.payload orelse return error.InvalidArgs;
            const record = switch (payload.*) {
                .record_val => |r| r,
                else => return error.InvalidArgs,
            };
            if (record.len < 2) return error.InvalidArgs;
            // `seconds` is `s64` in `wasi:clocks@0.3.0-rc-2026-03-15`
            // `system-clock.instant` (negative pre-epoch instants are
            // representable); the older 0.2 `wall-clock.datetime` shape
            // declared it as `u64`. Accept either tag so the lift works
            // regardless of which wit-bindgen vintage produced the
            // component (the wasi-testsuite `filesystem-stat` fixture
            // builds against the 0.3 shape, exercising `.s64`). (`#571`.)
            const secs_i96: i96 = switch (record[0]) {
                .s64 => |x| @intCast(x),
                .u64 => |x| @intCast(x),
                else => return error.InvalidArgs,
            };
            const nsec_u32: u32 = switch (record[1]) {
                .u32 => |x| x,
                .s32 => |x| @bitCast(x),
                else => return error.InvalidArgs,
            };
            const nsec_i96: i96 = @intCast(nsec_u32);
            return .{ .new = .{ .nanoseconds = secs_i96 * 1_000_000_000 + nsec_i96 } };
        },
        else => return error.InvalidArgs,
    }
}

/// Map the WIT `advice` enum (#475) to the host POSIX_FADV constant.
/// The WIT enum order is `(normal, sequential, random, will-need,
/// dont-need, no-reuse)`, which intentionally differs from the POSIX
/// order: `normal=0, random=1, sequential=2, willneed=3, dontneed=4,
/// noreuse=5`. Returns an `usize` because `std.os.linux.fadvise`
/// declares its `advice` parameter as `usize`.
fn mapWitAdviceToLinuxFadv(wit_advice: u32) usize {
    if (builtin.os.tag != .linux) return 0;
    const F = std.os.linux.POSIX_FADV;
    return switch (wit_advice) {
        0 => F.NORMAL,
        1 => F.SEQUENTIAL,
        2 => F.RANDOM,
        3 => F.WILLNEED,
        4 => F.DONTNEED,
        5 => F.NOREUSE,
        else => F.NORMAL,
    };
}

/// `wasi:filesystem/types.metadata-hash-value` record lift (#475).
/// Layout per WIT: `record { lower: u64, upper: u64 }`.
fn buildMetadataHashRecord(allocator: Allocator, lower: u64, upper: u64) !InterfaceValue {
    const fields = try allocator.alloc(InterfaceValue, 2);
    fields[0] = .{ .u64 = lower };
    fields[1] = .{ .u64 = upper };
    return .{ .record_val = fields };
}

/// Best-effort u64 view of `Stat.inode`. The host type is `u64` on
/// Linux/WASI/macOS and `i64` on Windows; we preserve the bit pattern
/// in both cases so the hash is stable for repeated stat()s of the
/// same file.
fn inodeToU64(inode: anytype) u64 {
    const T = @TypeOf(inode);
    if (T == u64) return inode;
    if (T == i64) return @bitCast(inode);
    return @intCast(inode);
}

/// Pack a `Stat` into a deterministic byte view and FNV-1a-128 hash it
/// (#475). The view covers the four fields the WIT spec calls out
/// (inode, size, mtime, ctime). All values are written little-endian
/// so the hash is host-architecture-independent.
fn computeMetadataHash(st: std.Io.File.Stat) u128 {
    var buf: [56]u8 = @splat(0);
    std.mem.writeInt(u64, buf[0..8], inodeToU64(st.inode), .little);
    std.mem.writeInt(u64, buf[8..16], st.size, .little);
    std.mem.writeInt(i128, buf[16..32], @intCast(st.mtime.nanoseconds), .little);
    std.mem.writeInt(i128, buf[32..48], @intCast(st.ctime.nanoseconds), .little);
    // nlink as the last 8 bytes — cheap extra entropy so unrelated
    // files with the same (inode mod u64, size, mtime, ctime) tuple
    // still hash distinctly when nlink differs.
    std.mem.writeInt(u64, buf[48..56], @intCast(st.nlink), .little);
    return std.hash.Fnv1a_128.hash(&buf);
}

/// Best-effort `Stat.inode` lookup for `is-same-object` (#475). Returns
/// `null` if the host `std.Io` vtable cannot stat this descriptor
/// (e.g. a directory on a target whose `dirStat` is unimplemented).
fn statFsDescriptorInode(d: FsDescriptor, io: std.Io) ?u64 {
    return switch (d) {
        .file => |f| if (f.file.stat(io)) |st| inodeToU64(st.inode) else |_| null,
        .dir => |dir| if (dir.dir.stat(io)) |st| inodeToU64(st.inode) else |_| null,
        .preopen => |dir| if (dir.dir.stat(io)) |st| inodeToU64(st.inode) else |_| null,
    };
}

// ── Top-level CLI dispatch ─────────────────────────────────────────────────

const ctypes_root = @import("types.zig");
const component_loader = @import("loader.zig");
const executor_root = @import("executor.zig");
const abi_root = @import("canonical_abi.zig");

pub const RunComponentError = error{
    LoadFailed,
    InstantiateFailed,
    /// `Options.aot_only` was set on the component instantiation, but
    /// at least one core has an import / wiring requirement the AOT
    /// runtime cannot satisfy yet. The `[aot reject] ...` log lines
    /// above this error name the failing core + import. Distinct from
    /// `InstantiateFailed` so the CLI surfaces a clean "AOT cannot
    /// run this component" message and exits nonzero — no silent
    /// interp fallback in `wamr run`. See issue #644.
    AotImportUnresolvable,
    LinkFailed,
    /// A deferred core-module `(start ...)` directive trapped while
    /// `linkImports` was draining the pending starts — typically a
    /// `_initialize`-style fixup that reaches an import wamr does not
    /// fully support (issue #308 surfaces this distinct from `LinkFailed`).
    StartTrapped,
    NoRunExport,
    Trap,
    OutOfMemory,
};

pub const RunOutcome = struct {
    /// The component exited normally. `is_ok=true` means run returned ok;
    /// false means the component returned `result::error(_)` or
    /// trapped via `wasi:cli/exit.exit{,-with-code}` / preview1
    /// `proc_exit` with a nonzero code.
    is_ok: bool,
    /// Numeric exit code recorded when the component called
    /// `wasi:cli/exit.exit-with-code(rc)` (or the preview1
    /// `proc_exit(rc)` path, which the wasm-tools adapter rewrites into
    /// `exit-with-code`). `null` on a normal return — callers should
    /// fall back to `is_ok` in that case. When set, the CLI translates
    /// it into the host process exit code (saturated to `u8`).
    exit_code: ?u32 = null,
};

/// Whether a component import name matches a WASI interface prefix,
/// allowing a trailing `@<version>` (e.g. `@0.2.6`).
fn matchesWasiPrefix(import_name: []const u8, prefix: []const u8) bool {
    if (!std.mem.startsWith(u8, import_name, prefix)) return false;
    const rest = import_name[prefix.len..];
    return rest.len == 0 or rest[0] == '@';
}

/// WASI surface version (#481). Derived from the `@x.y.z` suffix on
/// a component import name. Routing P2 vs P3 imports to different
/// host instances lets a single `WasiCliAdapter` host both surfaces
/// simultaneously — required for the 0.2 → 0.3 polyfill path.
pub const WasiVersion = enum { unspecified, p2, p3 };

/// Classify the WASI surface version from a component import name
/// like `wasi:io/streams@0.3.0-rc-2026-03-15`. Names without an `@`
/// suffix are `.unspecified` (caller decides default; for legacy
/// bare names we treat them as `.p2`-equivalent). Anything outside
/// the 0.2 / 0.3 majors is `.unspecified`.
pub fn wasiVersion(import_name: []const u8) WasiVersion {
    const at = std.mem.indexOfScalar(u8, import_name, '@') orelse return .unspecified;
    const ver = import_name[at + 1 ..];
    if (std.mem.startsWith(u8, ver, "0.3")) return .p3;
    if (std.mem.startsWith(u8, ver, "0.2")) return .p2;
    return .unspecified;
}

/// Find the callable export name for
/// `wasi:http/incoming-handler.handle`. `ComponentInstance` registers
/// exported instance members under `<instance-export>/<member>`, so a
/// component exporting `wasi:http/incoming-handler@0.2.6` with a `handle`
/// member is callable as `wasi:http/incoming-handler@0.2.6/handle`.
/// The returned slice is allocator-owned.
pub fn findHttpIncomingHandlerExportName(
    component: *const ctypes_root.Component,
    inst: *const ComponentInstance,
    allocator: Allocator,
) !?[]const u8 {
    for (component.exports) |exp| {
        if (exp.desc != .instance) continue;
        if (!matchesWasiPrefix(exp.name, "wasi:http/incoming-handler")) continue;
        const dotted = try std.fmt.allocPrint(allocator, "{s}/handle", .{exp.name});
        if (inst.getExport(dotted) != null) return dotted;
        allocator.free(dotted);
    }
    return null;
}

/// P3 variant of `findHttpIncomingHandlerExportName` — returns the
/// `@0.3.x`-versioned (or unversioned, for hand-authored test
/// fixtures) `wasi:http/handler.handle` export. `wasi:http@0.3.0`
/// collapsed 0.2's `incoming-handler` / `outgoing-handler` into a
/// single `wasi:http/handler` interface (#487), so the export shape
/// for a server is `wasi:http/handler@0.3.0-rc-…/handle`. A 0.2
/// `wasi:http/incoming-handler` export falls through to the legacy
/// synchronous handler dispatch path (`serveOneHttpConnection`).
/// Allocator-owned string. (#570 / #538 — http-service end-to-end.)
pub fn findHttpIncomingHandlerExportNameP3(
    component: *const ctypes_root.Component,
    inst: *const ComponentInstance,
    allocator: Allocator,
) !?[]const u8 {
    // Match either `wasi:http/handler` (0.3 unified) or
    // `wasi:http/incoming-handler` (transitional / hand-authored
    // test fixtures) at the @0.3.x version band.
    for (component.exports) |exp| {
        if (exp.desc != .instance) continue;
        const is_handler = matchesWasiPrefix(exp.name, "wasi:http/handler");
        const is_incoming = matchesWasiPrefix(exp.name, "wasi:http/incoming-handler");
        if (!is_handler and !is_incoming) continue;
        const v = wasiVersion(exp.name);
        if (v != .p3 and v != .unspecified) continue;
        const dotted = try std.fmt.allocPrint(allocator, "{s}/handle", .{exp.name});
        if (inst.getExport(dotted) != null) return dotted;
        allocator.free(dotted);
    }
    return null;
}

/// Bind WASI cli/run-style imports for `component` against `adapter`.
///
/// Walks every top-level instance import and, for each name that
/// matches a known WASI interface (with or without a `@<version>`
/// suffix), binds the corresponding `HostInstance` from the adapter.
/// Imports that don't match are left for the caller to wire (and will
/// cause `linkImports` to fail with `MissingImport` — by design).
pub fn populateWasiProviders(
    adapter: *WasiCliAdapter,
    component: *const ctypes_root.Component,
    providers: *std.StringHashMapUnmanaged(ImportBinding),
) !void {
    var matched_stdout: ?[]const u8 = null;
    var matched_stderr: ?[]const u8 = null;
    var matched_stdin: ?[]const u8 = null;
    var matched_exit: ?[]const u8 = null;
    var matched_environment: ?[]const u8 = null;
    var matched_terminal_stdin: ?[]const u8 = null;
    var matched_terminal_stdout: ?[]const u8 = null;
    var matched_terminal_stderr: ?[]const u8 = null;
    var matched_terminal_input: ?[]const u8 = null;
    var matched_terminal_output: ?[]const u8 = null;
    // #482: P3 cli matches. Populated only when an `@0.3.x` import
    // appears alongside (or instead of) the legacy 0.2 surface.
    var matched_stdout_p3: ?[]const u8 = null;
    var matched_stderr_p3: ?[]const u8 = null;
    var matched_stdin_p3: ?[]const u8 = null;
    var matched_exit_p3: ?[]const u8 = null;
    var matched_environment_p3: ?[]const u8 = null;
    var matched_cli_types_p3: ?[]const u8 = null;
    var matched_terminal_stdin_p3: ?[]const u8 = null;
    var matched_terminal_stdout_p3: ?[]const u8 = null;
    var matched_terminal_stderr_p3: ?[]const u8 = null;
    var matched_terminal_input_p3: ?[]const u8 = null;
    var matched_terminal_output_p3: ?[]const u8 = null;
    var matched_streams: ?[]const u8 = null;
    var matched_streams_p3: ?[]const u8 = null;
    var matched_poll: ?[]const u8 = null;
    var matched_error: ?[]const u8 = null;
    var matched_error_p3: ?[]const u8 = null;
    var matched_wall_clock: ?[]const u8 = null;
    var matched_monotonic_clock: ?[]const u8 = null;
    var matched_monotonic_clock_p3: ?[]const u8 = null;
    var matched_system_clock_p3: ?[]const u8 = null;
    var matched_clocks_types_p3: ?[]const u8 = null;
    var matched_random: ?[]const u8 = null;
    var matched_random_insecure: ?[]const u8 = null;
    var matched_random_insecure_seed: ?[]const u8 = null;
    var matched_random_p3: ?[]const u8 = null;
    var matched_random_insecure_p3: ?[]const u8 = null;
    var matched_random_insecure_seed_p3: ?[]const u8 = null;
    var matched_fs_types: ?[]const u8 = null;
    var matched_fs_preopens: ?[]const u8 = null;
    var matched_fs_types_p3: ?[]const u8 = null;
    var matched_fs_preopens_p3: ?[]const u8 = null;
    var matched_sockets_network: ?[]const u8 = null;
    var matched_sockets_instance_network: ?[]const u8 = null;
    var matched_sockets_tcp: ?[]const u8 = null;
    var matched_sockets_tcp_create: ?[]const u8 = null;
    var matched_sockets_udp: ?[]const u8 = null;
    var matched_sockets_udp_create: ?[]const u8 = null;
    var matched_sockets_ip_name_lookup: ?[]const u8 = null;
    var matched_sockets_types_p3: ?[]const u8 = null;
    var matched_sockets_ip_name_lookup_p3: ?[]const u8 = null;
    var matched_http_types: ?[]const u8 = null;
    var matched_http_outgoing_handler: ?[]const u8 = null;
    var matched_http_incoming_handler: ?[]const u8 = null;
    var matched_http_types_p3: ?[]const u8 = null;
    var matched_http_handler_p3: ?[]const u8 = null;
    var matched_http_client_p3: ?[]const u8 = null;
    // wasi:logging@0.1.x (#583 B5). The upstream WIT publishes the
    // `wasi:logging/logging` interface as `@0.1.0-draft`; the `_p2`
    // slot is reserved for a possible `@0.2.x` revision and routes
    // independently. `wasiVersion` returns `.unspecified` for
    // `0.1.x` and `.p2` for `0.2.x` — we treat both as the "default"
    // 0.1 binding unless an explicit `@0.2.x` import is present.
    var matched_logging: ?[]const u8 = null;
    var matched_logging_p2: ?[]const u8 = null;
    // #583 B4: wasi:keyvalue@0.2.x interfaces. No 0.3 namespace yet —
    // upstream still ships only `@0.2.0-draft2`. When 0.3 lands we'll
    // split the matched names by `wasiVersion` like the other
    // version-multiplexed families above; for now both 0.2 and any
    // future 0.3 imports route to the same HostInstance values.
    var matched_keyvalue_store: ?[]const u8 = null;
    var matched_keyvalue_atomics: ?[]const u8 = null;
    var matched_keyvalue_batch: ?[]const u8 = null;
    // #583 B6: wasi:config/store@0.2.0-rc.1. Single interface, single
    // host instance — the version-multiplex accepts any `@x.y.z` suffix
    // since the only published WIT (0.2.0-rc.1) and any near-future
    // revisions all share the same `get` / `get-all` method shape.
    var matched_config_store: ?[]const u8 = null;
    for (component.imports) |imp| {
        if (imp.desc != .instance) continue;
        // wasi:cli/* — version-multiplex onto either the 0.2 (P2) or
        // 0.3 (P3) HostInstance set. `terminal-input` aliases against
        // `terminal-stdin/output` only via the more-specific prefix
        // matcher (`matchesWasiPrefix`), so the order doesn't matter.
        if (matchesWasiPrefix(imp.name, "wasi:cli/stdout")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_stdout_p3 = matched_stdout_p3 orelse imp.name,
                else => matched_stdout = matched_stdout orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:cli/stderr")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_stderr_p3 = matched_stderr_p3 orelse imp.name,
                else => matched_stderr = matched_stderr orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:cli/stdin")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_stdin_p3 = matched_stdin_p3 orelse imp.name,
                else => matched_stdin = matched_stdin orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:cli/exit")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_exit_p3 = matched_exit_p3 orelse imp.name,
                else => matched_exit = matched_exit orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:cli/environment")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_environment_p3 = matched_environment_p3 orelse imp.name,
                else => matched_environment = matched_environment orelse imp.name,
            }
        }
        // `wasi:cli/types` is new in 0.3 — no 0.2 counterpart.
        if (matched_cli_types_p3 == null and matchesWasiPrefix(imp.name, "wasi:cli/types") and wasiVersion(imp.name) == .p3)
            matched_cli_types_p3 = imp.name;
        if (matchesWasiPrefix(imp.name, "wasi:cli/terminal-stdin")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_terminal_stdin_p3 = matched_terminal_stdin_p3 orelse imp.name,
                else => matched_terminal_stdin = matched_terminal_stdin orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:cli/terminal-stdout")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_terminal_stdout_p3 = matched_terminal_stdout_p3 orelse imp.name,
                else => matched_terminal_stdout = matched_terminal_stdout orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:cli/terminal-stderr")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_terminal_stderr_p3 = matched_terminal_stderr_p3 orelse imp.name,
                else => matched_terminal_stderr = matched_terminal_stderr orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:cli/terminal-input")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_terminal_input_p3 = matched_terminal_input_p3 orelse imp.name,
                else => matched_terminal_input = matched_terminal_input orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:cli/terminal-output")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_terminal_output_p3 = matched_terminal_output_p3 orelse imp.name,
                else => matched_terminal_output = matched_terminal_output orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:io/streams")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_streams_p3 = matched_streams_p3 orelse imp.name,
                else => matched_streams = matched_streams orelse imp.name,
            }
        }
        if (matched_poll == null and matchesWasiPrefix(imp.name, "wasi:io/poll"))
            matched_poll = imp.name;
        if (matchesWasiPrefix(imp.name, "wasi:io/error")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_error_p3 = matched_error_p3 orelse imp.name,
                else => matched_error = matched_error orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:clocks/wall-clock")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_system_clock_p3 = matched_system_clock_p3 orelse imp.name,
                else => matched_wall_clock = matched_wall_clock orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:clocks/monotonic-clock")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_monotonic_clock_p3 = matched_monotonic_clock_p3 orelse imp.name,
                else => matched_monotonic_clock = matched_monotonic_clock orelse imp.name,
            }
        }
        // 0.3 renamed `wall-clock` → `system-clock` (#483). Some 0.3 WIT
        // revisions retain the old `wall-clock` spelling (handled above).
        if (matched_system_clock_p3 == null and
            matchesWasiPrefix(imp.name, "wasi:clocks/system-clock"))
            matched_system_clock_p3 = imp.name;
        // #534: wasi:clocks/types@0.3 — a type-only instance holding
        // `duration` (and, in newer revisions, `instant`). Components
        // emitted by recent rustc toolchains import this top-level
        // even when the monotonic/system clock interfaces alias the
        // types from it. P3-only; no 0.2 counterpart.
        if (matched_clocks_types_p3 == null and
            matchesWasiPrefix(imp.name, "wasi:clocks/types") and
            wasiVersion(imp.name) == .p3)
            matched_clocks_types_p3 = imp.name;
        // `wasi:random/insecure-seed` shares the `wasi:random/insecure`
        // prefix, so test the more-specific name first. #485 splits each
        // interface by version so 0.2 and 0.3 imports route to different
        // HostInstances.
        if (matchesWasiPrefix(imp.name, "wasi:random/insecure-seed")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_random_insecure_seed_p3 = matched_random_insecure_seed_p3 orelse imp.name,
                else => matched_random_insecure_seed = matched_random_insecure_seed orelse imp.name,
            }
        } else if (matchesWasiPrefix(imp.name, "wasi:random/insecure")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_random_insecure_p3 = matched_random_insecure_p3 orelse imp.name,
                else => matched_random_insecure = matched_random_insecure orelse imp.name,
            }
        } else if (matchesWasiPrefix(imp.name, "wasi:random/random")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_random_p3 = matched_random_p3 orelse imp.name,
                else => matched_random = matched_random orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:filesystem/types")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_fs_types_p3 = matched_fs_types_p3 orelse imp.name,
                else => matched_fs_types = matched_fs_types orelse imp.name,
            }
        }
        if (matchesWasiPrefix(imp.name, "wasi:filesystem/preopens")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_fs_preopens_p3 = matched_fs_preopens_p3 orelse imp.name,
                else => matched_fs_preopens = matched_fs_preopens orelse imp.name,
            }
        }
        // wasi:sockets/* (#148). `instance-network` shares the
        // `wasi:sockets/` prefix with `network`, so probe more-specific
        // names first to avoid an aliasing match.
        if (matched_sockets_instance_network == null and matchesWasiPrefix(imp.name, "wasi:sockets/instance-network"))
            matched_sockets_instance_network = imp.name;
        if (matched_sockets_tcp_create == null and matchesWasiPrefix(imp.name, "wasi:sockets/tcp-create-socket"))
            matched_sockets_tcp_create = imp.name;
        if (matched_sockets_udp_create == null and matchesWasiPrefix(imp.name, "wasi:sockets/udp-create-socket"))
            matched_sockets_udp_create = imp.name;
        if (matchesWasiPrefix(imp.name, "wasi:sockets/ip-name-lookup")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_sockets_ip_name_lookup_p3 = matched_sockets_ip_name_lookup_p3 orelse imp.name,
                else => matched_sockets_ip_name_lookup = matched_sockets_ip_name_lookup orelse imp.name,
            }
        }
        // wasi:sockets/types is new in 0.3 — collapses tcp + tcp-create
        // + udp + udp-create. No 0.2 alias, but version-gate anyway.
        if (matched_sockets_types_p3 == null and
            matchesWasiPrefix(imp.name, "wasi:sockets/types") and
            wasiVersion(imp.name) == .p3)
            matched_sockets_types_p3 = imp.name;
        if (matched_sockets_tcp == null and matchesWasiPrefix(imp.name, "wasi:sockets/tcp"))
            matched_sockets_tcp = imp.name;
        if (matched_sockets_udp == null and matchesWasiPrefix(imp.name, "wasi:sockets/udp"))
            matched_sockets_udp = imp.name;
        if (matched_sockets_network == null and matchesWasiPrefix(imp.name, "wasi:sockets/network"))
            matched_sockets_network = imp.name;
        // wasi:http/* (#149). `outgoing-handler` and `incoming-handler`
        // share the `wasi:http/` prefix with `types`, but `matchesWasiPrefix`
        // matches at interface-name granularity so order doesn't matter.
        if (matched_http_outgoing_handler == null and matchesWasiPrefix(imp.name, "wasi:http/outgoing-handler"))
            matched_http_outgoing_handler = imp.name;
        if (matched_http_incoming_handler == null and matchesWasiPrefix(imp.name, "wasi:http/incoming-handler"))
            matched_http_incoming_handler = imp.name;
        // wasi:http@0.3.0 (#487). New `handler`/`client` interfaces have
        // distinct prefixes from the 0.2 `incoming-handler`/`outgoing-handler`
        // (matchesWasiPrefix matches at interface granularity), so order
        // is irrelevant. `types` is split by `@version` so 0.2 and 0.3
        // imports route to different HostInstances.
        if (matched_http_handler_p3 == null and matchesWasiPrefix(imp.name, "wasi:http/handler"))
            matched_http_handler_p3 = imp.name;
        if (matched_http_client_p3 == null and matchesWasiPrefix(imp.name, "wasi:http/client"))
            matched_http_client_p3 = imp.name;
        if (matchesWasiPrefix(imp.name, "wasi:http/types")) {
            switch (wasiVersion(imp.name)) {
                .p3 => matched_http_types_p3 = matched_http_types_p3 orelse imp.name,
                else => matched_http_types = matched_http_types orelse imp.name,
            }
        }
        // wasi:logging (#583 B5). The 0.1 WIT lives under
        // `wasi:logging/logging`; route a `@0.2.x` import (when /if
        // upstream publishes one) to a separate HostInstance so both
        // versions can coexist on the same component.
        if (matchesWasiPrefix(imp.name, "wasi:logging/logging")) {
            switch (wasiVersion(imp.name)) {
                .p2 => matched_logging_p2 = matched_logging_p2 orelse imp.name,
                else => matched_logging = matched_logging orelse imp.name,
            }
        }
        // #583 B4: wasi:keyvalue/* — `store`, `atomics`, `batch`. The
        // memory-store backend handles every supported version band;
        // any version routes to the same HostInstance. Probe more-
        // specific names first so `atomics` doesn't alias `store`.
        if (matched_keyvalue_atomics == null and matchesWasiPrefix(imp.name, "wasi:keyvalue/atomics"))
            matched_keyvalue_atomics = imp.name;
        if (matched_keyvalue_batch == null and matchesWasiPrefix(imp.name, "wasi:keyvalue/batch"))
            matched_keyvalue_batch = imp.name;
        if (matched_keyvalue_store == null and matchesWasiPrefix(imp.name, "wasi:keyvalue/store"))
            matched_keyvalue_store = imp.name;
        // wasi:config/store@0.2.0-rc.1 (#583 B6). All versions route
        // to the same single host instance — the interface shape is
        // stable across 0.2.x and (if it ships) 0.3.x.
        if (matched_config_store == null and matchesWasiPrefix(imp.name, "wasi:config/store"))
            matched_config_store = imp.name;
    }
    // Always populate every interface's members so the adapter's
    // HostInstance maps are well-formed; only register providers for
    // the names the component actually imports so `linkImports`
    // strict-checking surfaces unrelated misses.
    try adapter.populateWasiCliRun(
        providers,
        matched_stdout orelse "wasi:cli/stdout",
        matched_streams orelse "wasi:io/streams",
    );
    if (matched_stdout == null) _ = providers.remove("wasi:cli/stdout");
    if (matched_streams == null) _ = providers.remove("wasi:io/streams");

    try adapter.populateWasiCliStderr(
        providers,
        matched_stderr orelse "wasi:cli/stderr",
    );
    if (matched_stderr == null) _ = providers.remove("wasi:cli/stderr");

    try adapter.populateWasiCliStdin(
        providers,
        matched_stdin orelse "wasi:cli/stdin",
    );
    if (matched_stdin == null) _ = providers.remove("wasi:cli/stdin");

    try adapter.populateWasiCliExit(
        providers,
        matched_exit orelse "wasi:cli/exit",
    );
    if (matched_exit == null) _ = providers.remove("wasi:cli/exit");

    try adapter.populateWasiCliEnvironment(
        providers,
        matched_environment orelse "wasi:cli/environment",
    );
    if (matched_environment == null) _ = providers.remove("wasi:cli/environment");

    try adapter.populateWasiCliTerminal(
        providers,
        matched_terminal_stdin orelse "wasi:cli/terminal-stdin",
        matched_terminal_stdout orelse "wasi:cli/terminal-stdout",
        matched_terminal_stderr orelse "wasi:cli/terminal-stderr",
        matched_terminal_input orelse "wasi:cli/terminal-input",
        matched_terminal_output orelse "wasi:cli/terminal-output",
    );
    if (matched_terminal_stdin == null) _ = providers.remove("wasi:cli/terminal-stdin");
    if (matched_terminal_stdout == null) _ = providers.remove("wasi:cli/terminal-stdout");
    if (matched_terminal_stderr == null) _ = providers.remove("wasi:cli/terminal-stderr");
    if (matched_terminal_input == null) _ = providers.remove("wasi:cli/terminal-input");
    if (matched_terminal_output == null) _ = providers.remove("wasi:cli/terminal-output");

    // #482: wasi:cli@0.3.0 — register the P3 cli surface only when
    // the component imports any P3 cli interface. We always call into
    // `populateWasiCliP3` (it registers all members on the P3 ifaces
    // unconditionally so they're well-formed for tests) but synthesise
    // dummy provider names for unmatched imports and prune them
    // immediately, mirroring the 0.2 pattern above.
    {
        const any_p3 = matched_stdin_p3 != null or matched_stdout_p3 != null or
            matched_stderr_p3 != null or matched_exit_p3 != null or
            matched_environment_p3 != null or matched_cli_types_p3 != null or
            matched_terminal_stdin_p3 != null or matched_terminal_stdout_p3 != null or
            matched_terminal_stderr_p3 != null or matched_terminal_input_p3 != null or
            matched_terminal_output_p3 != null;
        if (any_p3) {
            const default_ver = "@0.3.0";
            const stdin_p3 = matched_stdin_p3 orelse "wasi:cli/stdin" ++ default_ver;
            const stdout_p3 = matched_stdout_p3 orelse "wasi:cli/stdout" ++ default_ver;
            const stderr_p3 = matched_stderr_p3 orelse "wasi:cli/stderr" ++ default_ver;
            const exit_p3 = matched_exit_p3 orelse "wasi:cli/exit" ++ default_ver;
            const env_p3 = matched_environment_p3 orelse "wasi:cli/environment" ++ default_ver;
            const types_p3 = matched_cli_types_p3 orelse "wasi:cli/types" ++ default_ver;
            const t_stdin_p3 = matched_terminal_stdin_p3 orelse "wasi:cli/terminal-stdin" ++ default_ver;
            const t_stdout_p3 = matched_terminal_stdout_p3 orelse "wasi:cli/terminal-stdout" ++ default_ver;
            const t_stderr_p3 = matched_terminal_stderr_p3 orelse "wasi:cli/terminal-stderr" ++ default_ver;
            const t_input_p3 = matched_terminal_input_p3 orelse "wasi:cli/terminal-input" ++ default_ver;
            const t_output_p3 = matched_terminal_output_p3 orelse "wasi:cli/terminal-output" ++ default_ver;
            try adapter.populateWasiCliP3(
                providers,
                stdin_p3,
                stdout_p3,
                stderr_p3,
                exit_p3,
                env_p3,
                types_p3,
                t_stdin_p3,
                t_stdout_p3,
                t_stderr_p3,
                t_input_p3,
                t_output_p3,
            );
            if (matched_stdin_p3 == null) _ = providers.remove(stdin_p3);
            if (matched_stdout_p3 == null) _ = providers.remove(stdout_p3);
            if (matched_stderr_p3 == null) _ = providers.remove(stderr_p3);
            if (matched_exit_p3 == null) _ = providers.remove(exit_p3);
            if (matched_environment_p3 == null) _ = providers.remove(env_p3);
            if (matched_cli_types_p3 == null) _ = providers.remove(types_p3);
            if (matched_terminal_stdin_p3 == null) _ = providers.remove(t_stdin_p3);
            if (matched_terminal_stdout_p3 == null) _ = providers.remove(t_stdout_p3);
            if (matched_terminal_stderr_p3 == null) _ = providers.remove(t_stderr_p3);
            if (matched_terminal_input_p3 == null) _ = providers.remove(t_input_p3);
            if (matched_terminal_output_p3 == null) _ = providers.remove(t_output_p3);
        }
    }

    try adapter.populateWasiIoPollError(
        providers,
        matched_poll orelse "wasi:io/poll",
        matched_error orelse "wasi:io/error",
    );
    if (matched_poll == null) _ = providers.remove("wasi:io/poll");
    if (matched_error == null) _ = providers.remove("wasi:io/error");

    // #481: separately bind any `wasi:io/streams@0.3.x` and
    // `wasi:io/error@0.3.x` imports. The 0.3 surface has no methods —
    // these are stub-only registrations for guest binding
    // satisfaction. The P3 stream<u8> machinery itself lives in the
    // canonical-ABI (#478/#505), not on the adapter.
    try adapter.populateWasiIoStreamsP3(
        providers,
        matched_streams_p3 orelse "wasi:io/streams@0.3.0",
        matched_error_p3 orelse "wasi:io/error@0.3.0",
    );
    if (matched_streams_p3 == null) _ = providers.remove("wasi:io/streams@0.3.0");
    if (matched_error_p3 == null) _ = providers.remove("wasi:io/error@0.3.0");

    try adapter.populateWasiClocksWallClock(
        providers,
        matched_wall_clock orelse "wasi:clocks/wall-clock",
    );
    if (matched_wall_clock == null) _ = providers.remove("wasi:clocks/wall-clock");

    try adapter.populateWasiClocksMonotonicClock(
        providers,
        matched_monotonic_clock orelse "wasi:clocks/monotonic-clock",
    );
    if (matched_monotonic_clock == null) _ = providers.remove("wasi:clocks/monotonic-clock");

    // #483: P3 clocks (monotonic + system).
    if (matched_monotonic_clock_p3) |name| {
        try adapter.populateWasiClocksMonotonicClockP3(providers, name);
    }
    if (matched_system_clock_p3) |name| {
        try adapter.populateWasiClocksSystemClockP3(providers, name);
    }
    // #534: P3 clocks/types — type-only instance, no functions. Wire
    // only when imported so `linkImports`'s strict-checking still
    // catches accidental unmatched imports elsewhere.
    if (matched_clocks_types_p3) |name| {
        try adapter.populateWasiClocksTypesP3(providers, name);
    }

    try adapter.populateWasiRandomRandom(
        providers,
        matched_random orelse "wasi:random/random",
    );
    if (matched_random == null) _ = providers.remove("wasi:random/random");

    try adapter.populateWasiRandomInsecure(
        providers,
        matched_random_insecure orelse "wasi:random/insecure",
    );
    if (matched_random_insecure == null) _ = providers.remove("wasi:random/insecure");

    try adapter.populateWasiRandomInsecureSeed(
        providers,
        matched_random_insecure_seed orelse "wasi:random/insecure-seed",
    );
    if (matched_random_insecure_seed == null) _ = providers.remove("wasi:random/insecure-seed");

    // wasi:random@0.3.0 (#485). Conditionally bind only when the
    // component imports the 0.3 surface — no fallback-and-remove dance
    // is needed because the 0.2.x calls above already keep the adapter
    // HostInstance maps populated.
    if (matched_random_p3) |name| {
        try adapter.populateWasiRandomRandomP3(providers, name);
    }
    if (matched_random_insecure_p3) |name| {
        try adapter.populateWasiRandomInsecureP3(providers, name);
    }
    if (matched_random_insecure_seed_p3) |name| {
        try adapter.populateWasiRandomInsecureSeedP3(providers, name);
    }

    try adapter.populateWasiFilesystemTypes(
        providers,
        matched_fs_types orelse "wasi:filesystem/types",
    );
    if (matched_fs_types == null) _ = providers.remove("wasi:filesystem/types");

    try adapter.populateWasiFilesystemPreopens(
        providers,
        matched_fs_preopens orelse "wasi:filesystem/preopens",
    );
    if (matched_fs_preopens == null) _ = providers.remove("wasi:filesystem/preopens");

    // wasi:filesystem@0.3.0 (#484). Conditionally bind only when the
    // component imports the 0.3 surface — same pattern as wave-B
    // wasi:random@0.3.0 (#485).
    if (matched_fs_types_p3) |name| {
        try adapter.populateWasiFilesystemTypesP3(providers, name);
    }
    if (matched_fs_preopens_p3) |name| {
        try adapter.populateWasiFilesystemPreopensP3(providers, name);
    }

    try adapter.populateWasiSocketsNetwork(
        providers,
        matched_sockets_network orelse "wasi:sockets/network",
    );
    if (matched_sockets_network == null) _ = providers.remove("wasi:sockets/network");

    try adapter.populateWasiSocketsInstanceNetwork(
        providers,
        matched_sockets_instance_network orelse "wasi:sockets/instance-network",
    );
    if (matched_sockets_instance_network == null) _ = providers.remove("wasi:sockets/instance-network");

    try adapter.populateWasiSocketsTcp(
        providers,
        matched_sockets_tcp orelse "wasi:sockets/tcp",
    );
    if (matched_sockets_tcp == null) _ = providers.remove("wasi:sockets/tcp");

    try adapter.populateWasiSocketsTcpCreateSocket(
        providers,
        matched_sockets_tcp_create orelse "wasi:sockets/tcp-create-socket",
    );
    if (matched_sockets_tcp_create == null) _ = providers.remove("wasi:sockets/tcp-create-socket");

    try adapter.populateWasiSocketsUdp(
        providers,
        matched_sockets_udp orelse "wasi:sockets/udp",
    );
    if (matched_sockets_udp == null) _ = providers.remove("wasi:sockets/udp");

    try adapter.populateWasiSocketsUdpCreateSocket(
        providers,
        matched_sockets_udp_create orelse "wasi:sockets/udp-create-socket",
    );
    if (matched_sockets_udp_create == null) _ = providers.remove("wasi:sockets/udp-create-socket");

    try adapter.populateWasiSocketsIpNameLookup(
        providers,
        matched_sockets_ip_name_lookup orelse "wasi:sockets/ip-name-lookup",
    );
    if (matched_sockets_ip_name_lookup == null) _ = providers.remove("wasi:sockets/ip-name-lookup");

    // wasi:sockets@0.3.0 (#486). Conditionally bind only the 0.3
    // surface a guest actually imports — same pattern as #485 random.
    if (matched_sockets_types_p3) |name| {
        try adapter.populateWasiSocketsTypesP3(providers, name);
    }
    if (matched_sockets_ip_name_lookup_p3) |name| {
        try adapter.populateWasiSocketsIpNameLookupP3(providers, name);
    }

    try adapter.populateWasiHttpTypes(
        providers,
        matched_http_types orelse "wasi:http/types",
    );
    if (matched_http_types == null) _ = providers.remove("wasi:http/types");

    try adapter.populateWasiHttpOutgoingHandler(
        providers,
        matched_http_outgoing_handler orelse "wasi:http/outgoing-handler",
    );
    if (matched_http_outgoing_handler == null) _ = providers.remove("wasi:http/outgoing-handler");

    try adapter.populateWasiHttpIncomingHandler(
        providers,
        matched_http_incoming_handler orelse "wasi:http/incoming-handler",
    );
    if (matched_http_incoming_handler == null) _ = providers.remove("wasi:http/incoming-handler");

    // wasi:http@0.3.0 (#487). Conditionally bind only when imported.
    if (matched_http_types_p3) |name| {
        try adapter.populateWasiHttpTypesP3(providers, name);
    }
    if (matched_http_handler_p3) |name| {
        try adapter.populateWasiHttpHandlerP3(providers, name);
    }
    if (matched_http_client_p3) |name| {
        try adapter.populateWasiHttpClientP3(providers, name);
    }

    // wasi:logging@0.1.x (#583 B5). Conditionally bound — same pattern
    // as wasi:random@0.3.0 above. The host adapter shares a single
    // `wasiLog` callback between the 0.1 and the reserved 0.2.x slot.
    if (matched_logging) |name| {
        try adapter.populateWasiLogging(providers, name);
    }
    if (matched_logging_p2) |name| {
        try adapter.populateWasiLoggingP2(providers, name);
    }

    // wasi:keyvalue@0.2.x (#583 B4). Memory-store backed; one
    // HostInstance per `{store, atomics, batch}` interface, routed
    // by exact import name. No 0.3 namespace yet — upstream still
    // ships `@0.2.0-draft2`. When 0.3 lands the same HostInstance
    // values can serve both, mirroring how the `wasi:cli/run` block
    // shares state across versions.
    if (matched_keyvalue_store) |name| {
        try adapter.populateWasiKeyvalueStore(providers, name);
    }
    if (matched_keyvalue_atomics) |name| {
        try adapter.populateWasiKeyvalueAtomics(providers, name);
    }
    if (matched_keyvalue_batch) |name| {
        try adapter.populateWasiKeyvalueBatch(providers, name);
    }

    // wasi:config/store@0.2.0-rc.1 (#583 B6). Conditionally bind only
    // when the component imports it — same pattern as wasi:random@0.3.0.
    if (matched_config_store) |name| {
        try adapter.populateWasiConfigStore(providers, name);
    }
}

/// Run an already-loaded component. See `runComponentBytes` for the
/// byte-level entry point and the policy notes that apply equally here.
///
/// `opts.precompiled_cores` opts individual embedded core modules into
/// the AOT runtime (#625 / #642). Empty slice (the default) keeps every
/// core on the interpreter — byte-identical to the pre-#642 behaviour.
/// `opts.aot_only = true` (set by `wamr run`) turns the legacy silent
/// interp fallback into a typed `error.AotImportUnresolvable` instead
/// (see issue #644).
pub fn runLoadedComponent(
    component: *const ctypes_root.Component,
    allocator: Allocator,
    adapter: *WasiCliAdapter,
    opts: core_backend.Options,
) RunComponentError!RunOutcome {
    const inst = instance_mod.instantiateWithOptions(
        component,
        allocator,
        opts,
    ) catch |err| switch (err) {
        error.AotImportUnresolvable => return error.AotImportUnresolvable,
        else => return error.InstantiateFailed,
    };
    defer inst.deinit();

    var providers: std.StringHashMapUnmanaged(ImportBinding) = .empty;
    // The provider populators allocate hashmap entries via `self.allocator`
    // (the adapter's allocator) — keep the deinit consistent with that so
    // hand-rolled callers like `runComponentBytes` (which pass an arena)
    // don't leak the underlying hashmap storage.
    defer providers.deinit(adapter.allocator);

    populateWasiProviders(adapter, component, &providers) catch return error.OutOfMemory;
    inst.linkImports(providers) catch |err| switch (err) {
        // Distinguish a deferred-start trap from a true import-wiring
        // failure so the CLI can produce a clearer diagnostic. The
        // `[component init trap] ...` line was already printed from
        // `runDeferredCoreStarts` before we got here.
        error.StartFunctionFailed => return error.StartTrapped,
        else => return error.LinkFailed,
    };

    if (inst.getExport("run") == null) {
        return error.NoRunExport;
    }

    var results: [1]abi_root.InterfaceValue = undefined;
    if (executor_root.callComponentFunc(inst, "run", &.{}, &results, allocator)) |_| {
        return .{ .is_ok = switch (results[0]) {
            .result_val => |rv| rv.is_ok,
            else => true,
        } };
    } else |err| {
        // `wasi:cli/exit.{exit, exit-with-code}` traps after stashing
        // a code on the adapter; translate that into a normal outcome
        // that carries the numeric exit code so the CLI can mirror it
        // into the host process exit code (see issue #436).
        if (adapter.exit_code) |code| return .{ .is_ok = code == 0, .exit_code = code };
        if (debugAotEnabled()) {
            std.debug.print("[aot-debug] runComponent_2 trap from callComponentFunc(\"run\"): {s}\n", .{@errorName(err)});
        }
        return error.Trap;
    }
}

/// Load + instantiate + run a component binary, mapping its `run` export
/// to a normalized outcome the CLI can turn into an exit code.
///
/// Phase 3 narrow scope:
///   - Recognizes the run entrypoint as a top-level component export
///     named exactly `"run"` (matching the hand-authored 2B-hello fixture).
///     Real WASI components nest `run` inside an exported
///     `wasi:cli/run` *instance*; lifting that into our `exported_funcs`
///     map requires the indexspace work tracked under `142-1b-indexspaces`
///     and is deferred. Until then, real Rust components are rejected
///     with `error.NoRunExport` rather than silently mis-exiting.
///   - Binds WASI imports against `adapter`'s `wasi:cli/stdout` +
///     `wasi:io/streams` interfaces; any other instance import will
///     surface as `error.LinkFailed` from `linkImports`.
///   - The `run` export must return `result<_,_>`. Trapping inside `run`
///     surfaces as `error.Trap` from this function.
pub fn runComponentBytes(
    data: []const u8,
    allocator: Allocator,
    adapter: *WasiCliAdapter,
    opts: core_backend.Options,
) RunComponentError!RunOutcome {
    const component_storage = allocator.create(ctypes_root.Component) catch return error.OutOfMemory;
    defer allocator.destroy(component_storage);
    component_storage.* = component_loader.load(data, allocator) catch return error.LoadFailed;
    // Route components that expose a `wasi:cli/run@0.3.x` instance export
    // through the async-lifted P3 dispatch path. Components without a 0.3
    // run export (bare `run`, or 0.2-only) keep the legacy synchronous
    // path. This is the CLI's single entry point for both WASI surfaces —
    // host adapters were already version-multiplexed by #481/#510 via
    // `populateWasiProviders`; the missing piece was teaching the CLI to
    // call the right export. (#520)
    if (hasWasiCliRunP3Export(component_storage)) {
        return runLoadedComponentP3(component_storage, allocator, adapter, opts);
    }
    return runLoadedComponent(component_storage, allocator, adapter, opts);
}

/// Return true iff the top-level component exports a `wasi:cli/run@0.3.x`
/// instance. Used by `runComponentBytes` to choose between the legacy
/// synchronous and the async-lifted P3 dispatch paths without having to
/// instantiate the component first.
pub fn hasWasiCliRunP3Export(component: *const ctypes_root.Component) bool {
    for (component.exports) |exp| {
        if (exp.desc != .instance) continue;
        if (!matchesWasiPrefix(exp.name, "wasi:cli/run")) continue;
        if (wasiVersion(exp.name) == .p3) return true;
    }
    return false;
}

// ── wasi:cli/run@0.3.0 entry-point (#482) ──────────────────────────────
//
// `run.run` is `async func() -> result<_, _>`. It's an *export*, not
// an import — the host locates it via the component's instance-export
// table and calls it through the async-lifted dispatch path
// (`callComponentFuncAsync` → `callComponentFuncByLocalAsyncLifted`,
// `executor.zig:351`/`:1435`). The callee invokes `canon task.return`
// to deposit the lowered `result<_,_>` discriminant on the
// owning task; this code reads it back from `task.return_values`.

/// Locate the 0.3 async run export. Returns an allocator-owned string
/// of the form `"wasi:cli/run@<version>/run"`, or null if no
/// `wasi:cli/run` export with a callable `run` member is present.
/// Mirrors `findHttpIncomingHandlerExportName`.
pub fn findRunP3ExportName(
    component: *const ctypes_root.Component,
    inst: *const ComponentInstance,
    allocator: Allocator,
) !?[]const u8 {
    for (component.exports) |exp| {
        if (exp.desc != .instance) continue;
        if (!matchesWasiPrefix(exp.name, "wasi:cli/run")) continue;
        // Only treat 0.3 (or unspecified, for hand-authored test
        // fixtures) as P3. A 0.2 `wasi:cli/run` export should fall
        // through to the legacy synchronous path.
        const v = wasiVersion(exp.name);
        if (v != .p3 and v != .unspecified) continue;
        const dotted = try std.fmt.allocPrint(allocator, "{s}/run", .{exp.name});
        if (inst.getExport(dotted) != null) return dotted;
        allocator.free(dotted);
    }
    return null;
}

/// P3 variant of `runLoadedComponent`. Wires WASI imports the same
/// way, then dispatches the exported `wasi:cli/run@.../run` through
/// the async-lifted task path. Settles the resulting task's
/// `return_values` (lowered `result<_,_>` is a single u32 discriminant
/// where 0 = ok, 1 = err) into a `RunOutcome`.
///
/// `wasi:cli/exit.{exit, exit-with-code}` traps stash the requested
/// code on the adapter exactly the same way as the 0.2 path; we
/// surface it as a normal `RunOutcome` carrying that code.
pub fn runLoadedComponentP3(
    component: *const ctypes_root.Component,
    allocator: Allocator,
    adapter: *WasiCliAdapter,
    opts: core_backend.Options,
) RunComponentError!RunOutcome {
    const inst = instance_mod.instantiateWithOptions(
        component,
        allocator,
        opts,
    ) catch |err| switch (err) {
        error.AotImportUnresolvable => return error.AotImportUnresolvable,
        else => return error.InstantiateFailed,
    };
    defer inst.deinit();

    var providers: std.StringHashMapUnmanaged(ImportBinding) = .empty;
    defer providers.deinit(adapter.allocator);
    populateWasiProviders(adapter, component, &providers) catch return error.OutOfMemory;
    inst.linkImports(providers) catch |err| switch (err) {
        error.StartFunctionFailed => return error.StartTrapped,
        else => return error.LinkFailed,
    };

    // Install the adapter's async-event driver so `waitable-set.wait`
    // can advance time / drain `wasi:clocks` timers (#551). Same for the
    // task.cancel propagation hook used by `multi-clock-wait`. Cleared
    // implicitly when `inst.deinit()` runs at function exit.
    inst.async_event_driver = &WasiCliAdapter.driveAsyncEvents;
    inst.async_event_driver_ctx = adapter;
    inst.async_cancel_driver = &WasiCliAdapter.cancelAllPendingTimers;
    inst.async_future_drop_driver = &WasiCliAdapter.cancelPendingHttpFetchForFuture;
    // Synchronous resource-drop hook so guest drops of `tcp-socket` /
    // `udp-socket` release their kernel fd immediately (#575). Without
    // this, the listener fd from `sockets-tcp-bind::test_reuseaddr`
    // lingers until adapter `deinit` and prevents the next bind on the
    // same ephemeral port from succeeding even with SO_REUSEADDR.
    inst.on_resource_drop = &WasiCliAdapter.onResourceDrop;
    inst.on_resource_drop_ctx = adapter;

    const run_name = (findRunP3ExportName(component, inst, allocator) catch return error.OutOfMemory) orelse
        return error.NoRunExport;
    defer allocator.free(run_name);

    var task_mgr = async_mod.TaskManager{};
    defer task_mgr.deinit(allocator);

    const task_handle = executor_root.callComponentFuncAsync(
        inst,
        run_name,
        &.{},
        &task_mgr,
        null,
        allocator,
    ) catch |e| {
        // Translate exit-trap into a normal outcome so the CLI can
        // mirror it into the host process exit code.
        if (adapter.exit_code) |code| return .{ .is_ok = code == 0, .exit_code = code };
        return switch (e) {
            error.FunctionNotFound => error.NoRunExport,
            error.OutOfMemory => error.OutOfMemory,
            else => error.Trap,
        };
    };

    if (adapter.exit_code) |code| return .{ .is_ok = code == 0, .exit_code = code };

    const return_values = try task_mgr.copyReturnValues(task_handle, allocator) orelse
        return error.Trap;
    defer allocator.free(return_values);
    if (return_values.len == 0) return error.Trap;
    // Lowered `result<_, _>` flat representation: a single i32
    // discriminant (`0 = ok`, `1 = err`).
    const is_ok = return_values[0] == 0;
    return .{ .is_ok = is_ok };
}

pub fn runComponentBytesP3(
    data: []const u8,
    allocator: Allocator,
    adapter: *WasiCliAdapter,
    opts: core_backend.Options,
) RunComponentError!RunOutcome {
    const component_storage = allocator.create(ctypes_root.Component) catch return error.OutOfMemory;
    defer allocator.destroy(component_storage);
    component_storage.* = component_loader.load(data, allocator) catch return error.LoadFailed;
    return runLoadedComponentP3(component_storage, allocator, adapter, opts);
}

pub const ServeHttpOptions = struct {
    listen_address: std.Io.net.IpAddress,
    /// Null means serve forever. Tests can set a finite count.
    max_requests: ?usize = null,
    /// If true, write a `Listening on <ip:port>\n` line to stdout after
    /// the socket is bound — useful for ephemeral-port (`:0`) flows where
    /// the caller can't know the resolved port in advance. The driver
    /// scrapes this line to discover where to connect.
    announce_listening: bool = false,
    /// Optional HTTPS termination config (#583 follow-up to PR #595,
    /// completed in #609). When set, the cert + key have been parsed at
    /// startup into a `tls.config.CertKeyPair` and the listener wraps each
    /// accepted fd in a server-side TLS handshake (via the `cataggar/tls.zig`
    /// dependency) before serving HTTP/1.1 over the encrypted stream. When
    /// null (default), the listener serves plaintext HTTP/1.1 — byte-for-byte
    /// the PR #580 + #595 path.
    tls_config: ?*HttpsTlsConfig = null,
};

/// HTTPS termination configuration for the `wasi:http/handler@0.3.0`
/// incoming-handler listener (`serveLoadedHttpComponent`). Parsed at
/// startup from `--tls-cert=<path>` + `--tls-key=<path>` (or the
/// combined `--tls-pem=<path>`) and threaded through `ServeHttpOptions`
/// so the listener can wrap each accepted fd in a TLS server stream.
///
/// Server-side TLS is provided by the pure-Zig `cataggar/tls.zig`
/// dependency (TLS 1.3, RSA + ECDSA server certificates) — upstream Zig
/// std ships only `std.crypto.tls.Client`. The cert / key are parsed and
/// validated at startup (catching `ENOENT`, malformed PEM, key/cert
/// mismatch, etc. before bind) and the resulting `cert_key_pair` is reused
/// across every accepted connection. The post-`accept(2)` handshake is
/// driven by `TlsServerConn.handshake` (see #609).
///
/// Lifetimes: `cert_bundle` owns the DER-encoded certificate chain
/// (a `std.crypto.Certificate.Bundle`, deinit via `deinit(allocator)`).
/// `cert_key_pair` owns its own DER bundle + parsed private key and is the
/// material actually fed to the handshake. `private_key_pem` is the raw PEM
/// bytes for the private key (PKCS#8 / RSA / EC). All are duplicated at
/// `load` time from the on-disk files; the source files can be deleted
/// afterwards without affecting the running server.
pub const HttpsTlsConfig = struct {
    cert_bundle: std.crypto.Certificate.Bundle,
    /// Parsed cert chain + private key, ready to hand to the TLS server
    /// handshake (`tls.server`). Built at `load` time from the cert + key
    /// PEM. Supports RSA and ECDSA server keys.
    cert_key_pair: tls.config.CertKeyPair,
    private_key_pem: []u8,
    /// One of `pkcs8`, `rsa`, `ec`. Sniffed from the BEGIN marker
    /// in `private_key_pem`. The handshake engine cares; the
    /// loader records it so callers can early-reject unsupported
    /// key types in the future.
    private_key_kind: PrivateKeyKind,
    /// Owning allocator. Used by `deinit` to free `private_key_pem`
    /// and tear down `cert_bundle` / `cert_key_pair`.
    allocator: std.mem.Allocator,

    pub const PrivateKeyKind = enum { pkcs8, rsa, ec };

    pub const LoadError = error{
        TlsCertFileNotFound,
        TlsKeyFileNotFound,
        TlsCertReadFailed,
        TlsKeyReadFailed,
        TlsCertParseFailed,
        TlsKeyParseFailed,
        TlsCertEmpty,
        TlsKeyEmpty,
        OutOfMemory,
    };

    /// Load and parse a separate cert + key pair from disk.
    /// `cert_path` must point at a PEM file containing one or more
    /// `-----BEGIN CERTIFICATE-----` blocks (the first block is the
    /// leaf; subsequent blocks form the intermediate chain).
    /// `key_path` must point at a PEM file containing exactly one
    /// `-----BEGIN (PKCS8|RSA|EC) PRIVATE KEY-----` block.
    ///
    /// Both files are slurped into memory; the cert PEM is parsed
    /// into DER via `std.crypto.Certificate.Bundle.addCertsFromFile`,
    /// the key PEM is retained as-is for the handshake engine to
    /// parse (deferred to `handshake()` so the loader stays
    /// independent of the handshake's key-format expectations).
    pub fn loadFromPaths(
        allocator: std.mem.Allocator,
        cert_path: []const u8,
        key_path: []const u8,
    ) LoadError!HttpsTlsConfig {
        const io = std.Io.Threaded.global_single_threaded.io();
        const now = std.Io.Timestamp.zero;

        var bundle: std.crypto.Certificate.Bundle = .empty;
        errdefer bundle.deinit(allocator);

        const cwd = std.Io.Dir.cwd();
        bundle.addCertsFromFilePath(allocator, io, now, cwd, cert_path) catch |err| switch (err) {
            error.FileNotFound => return error.TlsCertFileNotFound,
            error.OutOfMemory => return error.OutOfMemory,
            error.MissingEndCertificateMarker => return error.TlsCertParseFailed,
            else => return error.TlsCertReadFailed,
        };
        if (bundle.bytes.items.len == 0) return error.TlsCertEmpty;

        const key_bytes = cwd.readFileAlloc(io, key_path, allocator, @enumFromInt(1 * 1024 * 1024)) catch |err| switch (err) {
            error.FileNotFound => return error.TlsKeyFileNotFound,
            error.OutOfMemory => return error.OutOfMemory,
            else => return error.TlsKeyReadFailed,
        };
        errdefer allocator.free(key_bytes);

        const kind = sniffPrivateKeyKind(key_bytes) orelse return error.TlsKeyParseFailed;

        // Re-read the cert bytes (the bundle parser above retained only the
        // decoded DER, not the source PEM) so the tls.zig CertKeyPair parser
        // can build its own bundle + parsed private key for the handshake.
        const cert_bytes = cwd.readFileAlloc(io, cert_path, allocator, @enumFromInt(1 * 1024 * 1024)) catch |err| switch (err) {
            error.FileNotFound => return error.TlsCertFileNotFound,
            error.OutOfMemory => return error.OutOfMemory,
            else => return error.TlsCertReadFailed,
        };
        defer allocator.free(cert_bytes);

        var cert_key_pair = buildCertKeyPair(allocator, io, cert_bytes, key_bytes) catch |err| return err;
        errdefer cert_key_pair.deinit(allocator);

        return .{
            .cert_bundle = bundle,
            .cert_key_pair = cert_key_pair,
            .private_key_pem = key_bytes,
            .private_key_kind = kind,
            .allocator = allocator,
        };
    }

    /// Load a combined PEM file containing both the certificate
    /// chain and the private key in any order. Convenience wrapper
    /// for the common `cert+key.pem` deployment shape.
    pub fn loadFromCombinedPath(
        allocator: std.mem.Allocator,
        pem_path: []const u8,
    ) LoadError!HttpsTlsConfig {
        const io = std.Io.Threaded.global_single_threaded.io();
        const now = std.Io.Timestamp.zero;

        var bundle: std.crypto.Certificate.Bundle = .empty;
        errdefer bundle.deinit(allocator);

        const cwd = std.Io.Dir.cwd();
        bundle.addCertsFromFilePath(allocator, io, now, cwd, pem_path) catch |err| switch (err) {
            error.FileNotFound => return error.TlsCertFileNotFound,
            error.OutOfMemory => return error.OutOfMemory,
            error.MissingEndCertificateMarker => return error.TlsCertParseFailed,
            else => return error.TlsCertReadFailed,
        };
        if (bundle.bytes.items.len == 0) return error.TlsCertEmpty;

        // Re-read the file to extract the private-key block (the
        // bundle parser ignores non-CERTIFICATE blocks).
        const full_bytes = cwd.readFileAlloc(io, pem_path, allocator, @enumFromInt(2 * 1024 * 1024)) catch |err| switch (err) {
            error.FileNotFound => return error.TlsCertFileNotFound,
            error.OutOfMemory => return error.OutOfMemory,
            else => return error.TlsKeyReadFailed,
        };
        defer allocator.free(full_bytes);

        const key_pem = extractPrivateKeyBlock(allocator, full_bytes) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.TlsKeyEmpty => return error.TlsKeyEmpty,
            error.TlsKeyParseFailed => return error.TlsKeyParseFailed,
        };
        errdefer allocator.free(key_pem);
        const kind = sniffPrivateKeyKind(key_pem) orelse return error.TlsKeyParseFailed;

        // `full_bytes` carries both the CERTIFICATE and PRIVATE KEY blocks;
        // the tls.zig cert parser ignores non-CERTIFICATE blocks, so we can
        // hand it the whole file as the cert slice.
        var cert_key_pair = buildCertKeyPair(allocator, io, full_bytes, key_pem) catch |err| return err;
        errdefer cert_key_pair.deinit(allocator);

        return .{
            .cert_bundle = bundle,
            .cert_key_pair = cert_key_pair,
            .private_key_pem = key_pem,
            .private_key_kind = kind,
            .allocator = allocator,
        };
    }

    /// Build a `tls.config.CertKeyPair` from in-memory cert + key PEM,
    /// mapping the library's parse errors onto `LoadError`. The cert slice
    /// may contain extra non-CERTIFICATE blocks (e.g. the private key in a
    /// combined PEM) — they are ignored.
    fn buildCertKeyPair(
        allocator: std.mem.Allocator,
        io: std.Io,
        cert_pem: []const u8,
        key_pem: []const u8,
    ) LoadError!tls.config.CertKeyPair {
        return tls.config.CertKeyPair.fromSlice(allocator, io, cert_pem, key_pem) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return error.TlsKeyParseFailed,
        };
    }

    pub fn deinit(self: *HttpsTlsConfig) void {
        self.cert_bundle.deinit(self.allocator);
        self.cert_key_pair.deinit(self.allocator);
        self.allocator.free(self.private_key_pem);
        self.* = undefined;
    }
};

/// Per-connection server-side TLS state for HTTPS termination (#609).
///
/// Owns the socket reader/writer (with their record-sized buffers) and the
/// post-handshake `tls.Connection`. **Must be pinned** for its whole
/// lifetime: `tls.server` stores `&self.reader.interface` / `&self.writer.interface`
/// in the returned connection, and `std.Io.net.Stream.Reader`/`Writer`
/// recover themselves from those interface pointers via `@fieldParentPtr`.
/// Construct it as an `undefined` stack/heap local and call `handshake`
/// in place; never copy or move it afterwards.
///
/// The underlying socket fd is borrowed from the accept loop, which closes
/// it after the request is served; `TlsServerConn` does not own the fd.
pub const TlsServerConn = struct {
    reader: std.Io.net.Stream.Reader = undefined,
    writer: std.Io.net.Stream.Writer = undefined,
    conn: tls.Connection = undefined,
    input_buf: [tls.input_buffer_len]u8 = undefined,
    output_buf: [tls.output_buffer_len]u8 = undefined,

    /// Run the server-side TLS handshake over `accepted`, using `cfg`'s
    /// pre-parsed certificate + key. On success `self.conn` is a live
    /// `tls.Connection` ready for `read`/`writeAll`. On failure the library
    /// has already written a TLS alert to the socket; the caller should just
    /// close the connection. `self` must already live at its final address.
    pub fn handshake(self: *TlsServerConn, accepted: std.Io.net.Stream, cfg: *HttpsTlsConfig) !void {
        const io = std.Io.Threaded.global_single_threaded.io();
        self.reader = accepted.reader(io, &self.input_buf);
        self.writer = accepted.writer(io, &self.output_buf);
        // `io.random` is CSPRNG-backed (seeded from getrandom/urandom); the
        // rng source only needs to outlive the handshake call — the server
        // `tls.Connection` does not retain it.
        var rng_src: std.Random.IoSource = .{ .io = io };
        self.conn = try tls.server(&self.reader.interface, &self.writer.interface, .{
            .rng = rng_src.interface(),
            .auth = &cfg.cert_key_pair,
            .now = std.Io.Clock.real.now(io),
        });
    }
};

/// Sniff a PEM private-key BEGIN marker and classify the key type.
/// Returns `null` if no recognised marker is present in the first
/// 4 KiB of the file (the BEGIN line lives at offset 0 in
/// well-formed PEM; the 4 KiB window tolerates leading comments).
fn sniffPrivateKeyKind(pem: []const u8) ?HttpsTlsConfig.PrivateKeyKind {
    const window = pem[0..@min(pem.len, 4 * 1024)];
    if (std.mem.indexOf(u8, window, "-----BEGIN PRIVATE KEY-----") != null) {
        // RFC 5958 PKCS#8 — the most common modern format and what
        // `openssl genpkey` emits by default. The inner key OID
        // disambiguates RSA vs EC vs Ed25519.
        return .pkcs8;
    }
    if (std.mem.indexOf(u8, window, "-----BEGIN RSA PRIVATE KEY-----") != null) {
        // PKCS#1 — legacy `openssl genrsa` format.
        return .rsa;
    }
    if (std.mem.indexOf(u8, window, "-----BEGIN EC PRIVATE KEY-----") != null) {
        // SEC1 — legacy `openssl ecparam -genkey` format.
        return .ec;
    }
    return null;
}

/// Extract the `-----BEGIN … PRIVATE KEY-----` … `-----END … PRIVATE KEY-----`
/// block (including the markers) from a combined PEM bundle. Returned
/// slice is allocated through `allocator` and owned by the caller.
fn extractPrivateKeyBlock(
    allocator: std.mem.Allocator,
    full_pem: []const u8,
) error{ OutOfMemory, TlsKeyEmpty, TlsKeyParseFailed }![]u8 {
    const candidates = [_]struct { begin: []const u8, end: []const u8 }{
        .{ .begin = "-----BEGIN PRIVATE KEY-----", .end = "-----END PRIVATE KEY-----" },
        .{ .begin = "-----BEGIN RSA PRIVATE KEY-----", .end = "-----END RSA PRIVATE KEY-----" },
        .{ .begin = "-----BEGIN EC PRIVATE KEY-----", .end = "-----END EC PRIVATE KEY-----" },
    };
    for (candidates) |c| {
        const begin = std.mem.indexOf(u8, full_pem, c.begin) orelse continue;
        const end_off = std.mem.indexOfPos(u8, full_pem, begin + c.begin.len, c.end) orelse return error.TlsKeyParseFailed;
        const block_end = end_off + c.end.len;
        const block = full_pem[begin..block_end];
        const dup = try allocator.alloc(u8, block.len);
        @memcpy(dup, block);
        return dup;
    }
    return error.TlsKeyEmpty;
}

pub fn serveHttpComponentBytes(
    data: []const u8,
    allocator: Allocator,
    adapter: *WasiCliAdapter,
    options: ServeHttpOptions,
    opts: core_backend.Options,
) anyerror!void {
    // #918: block SIGINT/SIGTERM *before* the component decode below (and
    // the JIT compile that follows in `serveLoadedHttpComponent`), so a
    // signal that races startup is held pending rather than lost. The real
    // handler is installed and the signals unblocked later, right before
    // the accept loop (`armHttpShutdown`). Only for the long-lived
    // serve-forever path; the finite-`max_requests` unit-test path never
    // signals.
    if (options.max_requests == null) blockHttpShutdownSignals();
    const component_storage = allocator.create(ctypes_root.Component) catch return error.OutOfMemory;
    defer allocator.destroy(component_storage);
    component_storage.* = component_loader.load(data, allocator) catch return error.LoadFailed;
    return serveLoadedHttpComponent(component_storage, allocator, adapter, options, opts);
}

pub fn serveLoadedHttpComponent(
    component: *const ctypes_root.Component,
    allocator: Allocator,
    adapter: *WasiCliAdapter,
    options: ServeHttpOptions,
    opts: core_backend.Options,
) anyerror!void {
    // #918: portable graceful-shutdown wiring. SIGINT/SIGTERM are blocked
    // early (in `serveHttpComponentBytes`, before the component decode +
    // JIT compile) so a signal that races startup is held pending. Block
    // again here (idempotent) so direct callers of this entry point are
    // covered too. The real async-signal-safe handler is installed and the
    // signals unblocked *late* — right before the accept loop, once all of
    // startup's own signal manipulation is done — by `armHttpShutdown`;
    // `disarmHttpShutdown` tears the waker down on the normal control-flow
    // path once the loop unwinds. The handler only sets an atomic flag and
    // writes one byte to the waker pipe; every teardown step (listener
    // close, `inst.deinit`, arena / allocator cleanup) runs here, never
    // inside the handler. Skipped for the finite-`max_requests` unit-test
    // mode (no signals) and on Windows (no POSIX signal APIs).
    const serve_forever = options.max_requests == null;
    if (serve_forever) blockHttpShutdownSignals();
    defer if (serve_forever) disarmHttpShutdown();

    const inst = instance_mod.instantiateWithOptions(
        component,
        allocator,
        opts,
    ) catch |err| switch (err) {
        error.AotImportUnresolvable => return error.AotImportUnresolvable,
        else => return error.InstantiateFailed,
    };
    defer inst.deinit();

    var providers: std.StringHashMapUnmanaged(ImportBinding) = .empty;
    defer providers.deinit(adapter.allocator);

    populateWasiProviders(adapter, component, &providers) catch return error.OutOfMemory;
    inst.linkImports(providers) catch |err| switch (err) {
        error.StartFunctionFailed => return error.StartTrapped,
        else => return error.LinkFailed,
    };

    // Mirror the P3 cli/run path so `incoming-handler.handle` can use
    // `wasi:clocks` timers / cancel propagation while servicing a
    // request — the http-service fixture's handler does not exercise
    // either today, but the wiring is essentially free and keeps the
    // two dispatchers behaviourally aligned. (#570 / #551.)
    inst.async_event_driver = &WasiCliAdapter.driveAsyncEvents;
    inst.async_event_driver_ctx = adapter;
    inst.async_cancel_driver = &WasiCliAdapter.cancelAllPendingTimers;
    inst.async_future_drop_driver = &WasiCliAdapter.cancelPendingHttpFetchForFuture;

    // Prefer the P3 (`@0.3.x`) export when present; fall back to the
    // legacy 0.2 dispatch otherwise. The P3 path goes through
    // `serveOneHttpConnectionP3` → `dispatchHttpHandlerP3` (async-lifted
    // `result<response, error-code>`); the 0.2 path uses the
    // `response-outparam`-based ABI. (#570)
    const handler_name_p3 = (try findHttpIncomingHandlerExportNameP3(component, inst, allocator));
    const handler_name = handler_name_p3 orelse
        ((try findHttpIncomingHandlerExportName(component, inst, allocator)) orelse
            return error.NoIncomingHandlerExport);
    defer allocator.free(handler_name);
    const dispatch_p3 = handler_name_p3 != null;

    const io = std.Io.Threaded.global_single_threaded.io();
    // Exclusive bind: leave `reuse_address` at its `false` default so a
    // second wamr started on the same port fails with `AddressInUse`
    // rather than silently joining a SO_REUSEPORT pool (stdlib's
    // `reuse_address` flag sets both SO_REUSEADDR *and* SO_REUSEPORT on
    // POSIX). The kernel briefly holds the port in TIME_WAIT for a few
    // seconds after a clean shutdown; that's the intended trade-off.
    var server = std.Io.net.IpAddress.listen(&options.listen_address, io, .{
        .kernel_backlog = 128,
    }) catch |err| switch (err) {
        error.AddressInUse => return error.AddressInUse,
        else => return error.ListenFailed,
    };
    defer server.deinit(io);

    // HTTPS termination (#583 follow-up / #609). When the caller supplied a
    // parsed `HttpsTlsConfig`, each accepted connection is wrapped in a
    // server-side TLS handshake (via the `cataggar/tls.zig` dependency)
    // before HTTP/1.1 is served over the encrypted stream — see
    // `serveOneHttpConnectionP3`. When null, the listener serves plaintext
    // HTTP/1.1 (the PR #580 + #595 path).
    const url_scheme: []const u8 = if (options.tls_config != null) "https" else "http";

    if (options.announce_listening) {
        // `server.socket.address` carries the kernel-resolved port
        // (matches what `getsockname(2)` would report). Emit two
        // distinct lines:
        //   - stdout: `Listening on <ip:port>` (legacy CLI feedback,
        //     used by non-suite drivers / humans).
        //   - stderr: `<scheme>://<host>:<port>` (wasi-testsuite
        //     `TestCaseRunner.get_http_server` scans stderr's first
        //     line for the `http://` prefix; without this the
        //     `http-service` fixture fails on `do_request`). (#570)
        var buf: [192]u8 = undefined;
        const stdout_line = std.fmt.bufPrint(&buf, "Listening on {f}\n", .{server.socket.address}) catch buf[0..0];
        var stdout_file = std.Io.File.stdout();
        stdout_file.writeStreamingAll(io, stdout_line) catch {};

        var stderr_buf: [192]u8 = undefined;
        const stderr_line = std.fmt.bufPrint(&stderr_buf, "{s}://{f}\n", .{ url_scheme, server.socket.address }) catch stderr_buf[0..0];
        var stderr_file = std.Io.File.stderr();
        stderr_file.writeStreamingAll(io, stderr_line) catch {};
    }

    // Install the SIGINT/SIGTERM handler and unblock the signals now, once
    // the listener is up and all of startup's signal manipulation is done
    // — the wasi-testsuite `http-service` fixture issues
    // `{ "type": "kill", "signal": "SIGINT" }` followed by
    // `{ "type": "wait" }` (default exit_code 0). Without a portable
    // handler the default disposition is process-terminate with a
    // non-zero signal status (observed as `Popen` `-2` on macOS, #918),
    // which the runner reports as a failure. `armHttpShutdown` also
    // unblocks the signals blocked at startup, so a SIGINT that raced the
    // JIT compile is delivered to the handler right here; the accept loop
    // below then observes the flag / self-pipe and shuts down cleanly.
    if (serve_forever) armHttpShutdown();

    var served: usize = 0;
    while (options.max_requests == null or served < options.max_requests.?) {
        // Portable graceful shutdown: block on the listener *and* the
        // shutdown self-pipe so a SIGINT/SIGTERM wakes `accept` promptly
        // instead of waiting for the next connection. `std.posix.poll`
        // retries `EINTR` internally, so a signal delivered to this
        // thread simply re-enters `poll` and then observes the readable
        // pipe / atomic flag. Guarded to non-Windows because
        // `std.posix.poll` is a compile error on Windows (and the waker
        // is always null there). (#918)
        if (comptime builtin.os.tag != .windows) {
            if (http_shutdown_waker) |w| {
                if (http_shutdown_requested.load(.acquire)) break;
                var pfds = [_]std.posix.pollfd{
                    .{ .fd = server.socket.handle, .events = std.posix.POLL.IN, .revents = 0 },
                    .{ .fd = w.read_fd, .events = std.posix.POLL.IN, .revents = 0 },
                };
                _ = std.posix.poll(&pfds, -1) catch break;
                if (http_shutdown_requested.load(.acquire)) break;
                if (pfds[1].revents != 0) break;
                if (pfds[0].revents & (std.posix.POLL.ERR | std.posix.POLL.NVAL) != 0) {
                    return error.AcceptFailed;
                }
                if (pfds[0].revents & std.posix.POLL.IN == 0) continue;
            }
        }
        const accepted = server.accept(io) catch return error.AcceptFailed;
        {
            defer accepted.close(io);
            if (dispatch_p3) {
                serveOneHttpConnectionP3(adapter, inst, handler_name, accepted, options.tls_config);
            } else {
                serveOneHttpConnection(adapter, inst, handler_name, accepted);
            }
        }
        served += 1;
    }
}

/// SIGINT/SIGTERM handler: request an orderly shutdown of the
/// `wasi:http/service` accept loop. Async-signal-safe — it only stores
/// an atomic flag and writes one byte to the shutdown self-pipe so a
/// `poll()` parked on the accept path wakes immediately. All teardown
/// (listener close, component `deinit`, allocator cleanup) then runs on
/// the normal control-flow path once the loop unwinds; nothing unsafe
/// (allocation, `deinit`, buffered I/O) happens inside the handler.
/// (#918)
fn httpShutdownRequest() void {
    http_shutdown_requested.store(true, .release);
    const fd = http_shutdown_wake_fd.load(.acquire);
    if (fd >= 0) {
        const byte = [_]u8{1};
        // Best-effort, async-signal-safe wake. Errors (EINTR / EAGAIN /
        // EPIPE) are ignored — the atomic flag is the source of truth;
        // the byte only unblocks a `poll()` on the read end.
        _ = std.posix.system.write(fd, &byte, 1);
    }
}

/// Per-platform `callconv(.c)` trampolines into `httpShutdownRequest`.
/// The signal-handler function-pointer type is `fn (SIG)` where `SIG`
/// is the platform's signal enum, which differs between the raw Linux
/// (`std.os.linux.SIG`) and the libc/BSD (`std.posix.SIG`) ABIs — hence
/// two thin wrappers. Only the one referenced by the active target is
/// analyzed (lazy analysis), so neither is compiled on Windows. (#918)
fn httpShutdownSignalHandlerLinux(_: std.os.linux.SIG) callconv(.c) void {
    httpShutdownRequest();
}

fn httpShutdownSignalHandlerPosix(_: std.posix.SIG) callconv(.c) void {
    httpShutdownRequest();
}

fn installHttpShutdownHandler() void {
    switch (builtin.os.tag) {
        .windows => return,
        .linux => {
            // Use the raw linux sigaction syscall: when libc is linked
            // (musl) the std.posix wrapper expects `c.common_linux_Sigaction`
            // which has a different layout than `std.os.linux.Sigaction`
            // and rejects this struct. The raw syscall takes
            // `linux.Sigaction` directly on every linux target.
            const linux = std.os.linux;
            var act: linux.Sigaction = .{
                .handler = .{ .handler = httpShutdownSignalHandlerLinux },
                .mask = linux.sigemptyset(),
                // SA_RESETHAND: a *second* SIGINT (impatient Ctrl-C)
                // falls through to the default disposition and terminates
                // the process, so shutdown can never wedge.
                .flags = linux.SA.RESETHAND,
            };
            _ = linux.sigaction(linux.SIG.INT, &act, null);
            _ = linux.sigaction(linux.SIG.TERM, &act, null);
        },
        else => {
            // macOS / BSD: the libc `sigaction` wrapper matches
            // `std.posix.Sigaction`'s layout, so use it directly. This is
            // what fixes the macOS `Popen(-2)` shutdown failure (#918):
            // previously no handler was installed off-Linux.
            var act: std.posix.Sigaction = .{
                .handler = .{ .handler = httpShutdownSignalHandlerPosix },
                .mask = std.posix.sigemptyset(),
                .flags = std.posix.SA.RESETHAND,
            };
            std.posix.sigaction(std.posix.SIG.INT, &act, null);
            std.posix.sigaction(std.posix.SIG.TERM, &act, null);
        },
    }
}

fn statusForRequestReadError(err: anyerror) u16 {
    return switch (err) {
        error.HttpRequestBodyTooLarge => 413,
        error.HttpRequestUriTooLong => 414,
        error.HttpRequestHeaderTooLarge => 431,
        error.HttpUnsupportedTransferCoding => 501,
        else => 400,
    };
}

fn serveOneHttpConnection(
    adapter: *WasiCliAdapter,
    inst: *ComponentInstance,
    handler_name: []const u8,
    accepted: std.Io.net.Stream,
) void {
    defer adapter.cleanupHttpResources();

    var input = streams.InputStream.fromTcpStream(accepted.socket.handle);
    var output = streams.OutputStream.toTcpStream(accepted.socket.handle);
    const io = std.Io.Threaded.global_single_threaded.io();
    var interrupt_ctx = HttpAcceptedInterruptContext{
        .stream = accepted,
        .io = io,
    };
    const interrupt = HttpConnectionInterrupt{
        .context = &interrupt_ctx,
        .callback = &interruptAcceptedHttpConnection,
    };

    const request_handle = adapter.readIncomingRequestFromStream(&input) catch |err| {
        adapter.writeHttpSimpleResponse(&output, statusForRequestReadError(err), "bad request\n") catch {};
        return;
    };

    const outparam = adapter.allocator.create(ResponseOutparam) catch {
        adapter.writeHttpSimpleResponse(&output, 500, "out of memory\n") catch {};
        return;
    };
    outparam.* = .{};
    const outparam_handle = adapter.pushResponseOutparam(outparam) catch {
        adapter.allocator.destroy(outparam);
        adapter.writeHttpSimpleResponse(&output, 500, "out of memory\n") catch {};
        return;
    };

    const args = [_]abi_root.InterfaceValue{
        .{ .handle = request_handle },
        .{ .handle = outparam_handle },
    };
    var results: [0]abi_root.InterfaceValue = .{};
    const live_response: ?*InboundHttpResponseSession = live: {
        const session = InboundHttpResponseSession.create(
            adapter.allocator,
            adapter,
            inst,
            &output,
            false,
            interrupt,
            null,
        ) catch break :live null;
        session.p2_mode = true;
        session.start() catch {
            session.destroy();
            break :live null;
        };
        break :live session;
    };

    executor_root.callComponentFuncWithHostTaskContext(
        inst,
        handler_name,
        &args,
        &results,
        if (live_response) |session| @ptrCast(session) else null,
        adapter.allocator,
    ) catch {
        var output_started = false;
        var terminal: HttpLiveTerminal = .handler_error;
        if (live_response) |session| {
            session.handlerFailed();
            session.waitAndJoin();
            session.propagateTerminalToGuest();
            output_started = session.hasOutputStarted();
            terminal = session.currentTerminal();
            session.destroy();
        }
        if (!output_started and terminal != .client_disconnected and
            terminal != .shutdown)
        {
            adapter.writeHttpSimpleResponse(
                &output,
                500,
                "handler trapped\n",
            ) catch {};
        }
        WasiCliAdapter.cancelAllPendingAsyncOps(
            adapter,
            inst,
            null,
            adapter.allocator,
        );
        return;
    };

    var live_terminal: HttpLiveTerminal = .fallback;
    var live_output_started = false;
    if (live_response) |session| {
        _ = session.handlerReturnedP2(outparam_handle);
        session.waitAndJoin();
        session.propagateTerminalToGuest();
        live_terminal = session.currentTerminal();
        live_output_started = session.hasOutputStarted();
        session.destroy();
    }
    if (live_terminal == .succeeded) return;
    if (live_terminal != .fallback) {
        if (live_terminal == .response_error and !live_output_started) {
            adapter.writeHttpSimpleResponse(
                &output,
                500,
                "invalid response\n",
            ) catch {};
        }
        WasiCliAdapter.cancelAllPendingAsyncOps(
            adapter,
            inst,
            null,
            adapter.allocator,
        );
        return;
    }

    // P2 serves one request per connection, so a disconnect has no
    // keep-alive to suppress — but the guest may still own host
    // operations whose results can no longer be observed (#616 A8).
    adapter.writeHttpResponseFromOutparam(&output, outparam_handle) catch |err| {
        if (err == error.HttpClientDisconnected) {
            WasiCliAdapter.cancelAllPendingAsyncOps(adapter, inst, null, adapter.allocator);
        }
    };
}

const HttpAcceptedInterruptContext = struct {
    stream: std.Io.net.Stream,
    io: std.Io,
};

fn interruptAcceptedHttpConnection(ctx_opaque: ?*anyopaque) void {
    const ctx: *HttpAcceptedInterruptContext =
        @ptrCast(@alignCast(ctx_opaque.?));
    ctx.stream.shutdown(ctx.io, .both) catch {};
}

/// P3 (`@0.3.x`) variant of `serveOneHttpConnection`. Dispatches
/// `wasi:http/incoming-handler@0.3.0.handle` through the async-lifted
/// canonical ABI and writes the resulting `result<response,
/// error-code>` back to the socket. Connection is closed by the
/// caller (`defer accepted.close(io)` in `serveLoadedHttpComponent`)
/// once this function returns. Honors HTTP/1.1 keep-alive — the
/// inner `serveOneHttpConnectionP3Stream` loops over multiple
/// requests until a `Connection: close` is negotiated, the client
/// closes cleanly, or `SO_RCVTIMEO` fires. (#570 / #583 A5)
///
/// When `tls_config` is non-null, the connection is first upgraded to a
/// server-side TLS session (HTTPS termination, #609); the HTTP/1.1 parser
/// then runs unchanged over the decrypted stream. A failed handshake closes
/// the connection (the TLS library has already emitted an alert).
fn serveOneHttpConnectionP3(
    adapter: *WasiCliAdapter,
    inst: *ComponentInstance,
    handler_name: []const u8,
    accepted: std.Io.net.Stream,
    tls_config: ?*HttpsTlsConfig,
) void {
    setKeepAliveIdleTimeout(accepted.socket.handle, http_p3_keep_alive_idle_seconds);
    const io = std.Io.Threaded.global_single_threaded.io();
    var interrupt_ctx = HttpAcceptedInterruptContext{
        .stream = accepted,
        .io = io,
    };
    const interrupt = HttpConnectionInterrupt{
        .context = &interrupt_ctx,
        .callback = &interruptAcceptedHttpConnection,
    };

    if (tls_config) |cfg| {
        // `TlsServerConn` must be pinned (the TLS connection holds pointers
        // into its reader/writer), so build it in place on this frame and
        // never move it. ~50 KiB of record buffers live here for the
        // duration of the connection.
        var tconn: TlsServerConn = .{};
        tconn.handshake(accepted, cfg) catch return;
        // Best-effort `close_notify` on the way out.
        defer tconn.conn.close() catch {};
        var input = streams.InputStream.fromTlsConn(&tconn.conn);
        var output = streams.OutputStream.toTlsConn(&tconn.conn);
        adapter.serveOneHttpConnectionP3StreamInterruptible(
            inst,
            handler_name,
            &input,
            &output,
            interrupt,
        );
        return;
    }

    var input = streams.InputStream.fromTcpStream(accepted.socket.handle);
    var output = streams.OutputStream.toTcpStream(accepted.socket.handle);
    adapter.serveOneHttpConnectionP3StreamInterruptible(
        inst,
        handler_name,
        &input,
        &output,
        interrupt,
    );
}

/// Set a per-socket `SO_RCVTIMEO` so the keep-alive read between
/// requests doesn't park forever (#583 A5). Linux/POSIX-only — on
/// Windows the listener path is gated behind the same builtin
/// check, and the conformance suite isn't run there.
fn setKeepAliveIdleTimeout(fd: std.posix.fd_t, seconds: i64) void {
    if (builtin.target.os.tag == .windows) return;
    const tv = std.posix.timeval{ .sec = seconds, .usec = 0 };
    const bytes = std.mem.asBytes(&tv);
    std.posix.setsockopt(fd, std.posix.SOL.SOCKET, std.posix.SO.RCVTIMEO, bytes) catch {};
}

// ── Tests ───────────────────────────────────────────────────────────────────

test "WasiCliAdapter: init/deinit captures empty buffer" {
    var adapter = WasiCliAdapter.init(std.testing.allocator);
    defer adapter.deinit();
    try std.testing.expectEqualStrings("", adapter.getStdoutBytes());
}

test "WasiCliAdapter: end-to-end via instance import + alias + canon.lower" {
    const testing = std.testing;

    // Hand-authored core module:
    //   (type 0 (func (param i32 i32)))
    //   (type 1 (func))
    //   (import "host" "write" (func (type 0)))
    //   (memory 1)
    //   (func (type 1)
    //     i32.const 8 i32.const 6 call 0)            ;; write(ptr=8, len=6)
    //   (export "run" (func 1))
    //   (data (i32.const 8) "hello\n")
    const core_wasm = [_]u8{
        0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
        // type section: 2 types (5+3 bytes content + count = 9)
        0x01, 0x09, 0x02,
        0x60, 0x02, 0x7f, 0x7f, 0x00, // (i32, i32) -> ()
        0x60, 0x00, 0x00, // () -> ()
        // import section: host.write : type 0 (14 bytes content)
        0x02, 0x0e, 0x01,
        0x04, 'h',  'o',
        's',  't',  0x05,
        'w',  'r',  'i',
        't',  'e',  0x00,
        0x00,
        // function section: 1 local fn of type 1
        0x03, 0x02,
        0x01, 0x01,
        // memory section: 1 mem, min=1
        0x05,
        0x03, 0x01, 0x00,
        0x01,
        // export section: "run" -> func 1
        0x07, 0x07,
        0x01, 0x03, 'r',
        'u',  'n',  0x00,
        0x01,
        // code section: 1 body, 8 bytes
        0x0a, 0x0a,
        0x01, 0x08, 0x00,
        0x41, 0x08, // i32.const 8
        0x41, 0x06, // i32.const 6
        0x10, 0x00, // call 0 (host.write)
        0x0b, // end
        // data section: 1 segment, mem 0, offset i32.const 8, "hello\n"
        0x0b,
        0x0c,
        0x01,
        0x00, // active mem 0
        0x41, 0x08, 0x0b, // offset = i32.const 8
        0x06, 'h',  'e',
        'l',  'l',  'o',
        '\n',
    };

    const core_modules = [_]ctypes.CoreModule{.{ .data = &core_wasm }};

    // Component types:
    //   type 0 = func (list<u8>) -> ()  for the canon-lowered host call
    //   type 1 = list<u8>  (list-element u8)
    //   type 2 = instance { export "write" (func (type 0)) }
    const list_u8 = ctypes.TypeDef{ .list = .{ .element = .u8 } };
    const params = [_]ctypes.NamedValType{
        .{ .name = "data", .type = .{ .list = 1 } },
    };
    const inst_decls = [_]ctypes.Decl{
        .{ .@"export" = .{ .name = "write", .desc = .{ .func = 0 } } },
    };
    const type_defs = [_]ctypes.TypeDef{
        .{ .func = .{ .params = &params, .results = .none } },
        list_u8,
        .{ .instance = .{ .decls = &inst_decls } },
    };

    // imports: (instance (type 2)) — name "wasi:hello/world"
    const imports_decl = [_]ctypes.ImportDecl{
        .{ .name = "wasi:hello/world", .desc = .{ .instance = 2 } },
    };

    // alias instance_export sort=func instance=0 name="write" → component func 0
    const aliases_decl = [_]ctypes.Alias{
        .{ .instance_export = .{
            .sort = .func,
            .instance_idx = 0,
            .name = "write",
        } },
    };

    // canon.lower of component func 0 → core func 0 (the host import slot)
    const canons = [_]ctypes.Canon{
        .{ .lower = .{ .func_idx = 0, .opts = &.{} } },
    };

    // Wire core instance: inline exports {write: func 0 (the lowered slot)},
    // then instantiate the core module passing inline as "host".
    const inline_exports = [_]ctypes.CoreInlineExport{
        .{ .name = "write", .sort_idx = .{ .sort = .func, .idx = 0 } },
    };
    const inst_args = [_]ctypes.CoreInstantiateArg{
        .{ .name = "host", .instance_idx = 0 },
    };
    const core_insts = [_]ctypes.CoreInstanceExpr{
        .{ .exports = &inline_exports },
        .{ .instantiate = .{ .module_idx = 0, .args = &inst_args } },
    };

    const component = ctypes.Component{
        .core_modules = &core_modules,
        .core_instances = &core_insts,
        .core_types = &.{},
        .components = &.{},
        .instances = &.{},
        .aliases = &aliases_decl,
        .types = &type_defs,
        .canons = &canons,
        .imports = &imports_decl,
        .exports = &.{},
    };

    const inst = try instance_mod.instantiate(&component, testing.allocator);
    defer inst.deinit();

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    var providers: std.StringHashMapUnmanaged(ImportBinding) = .empty;
    defer providers.deinit(testing.allocator);
    try adapter.populateProviders(&providers, "wasi:hello/world", "write");

    try inst.linkImports(providers);

    // Trampoline must have been re-bound to the adapter's host fn.
    try testing.expect(inst.trampoline_ctxs.items.len == 1);
    try testing.expect(inst.trampoline_ctxs.items[0].host_func.call != null);

    // Invoke "run", which calls write(8, 6) and pulls "hello\n" out of memory.
    const mi = inst.firstModuleInst() orelse return error.TestFailed;
    const run_idx = mi.getExportFunc("run") orelse return error.TestFailed;
    const env = try @import("../runtime/common/exec_env.zig").ExecEnv.create(mi, 512, testing.allocator);
    defer env.destroy();
    try @import("../runtime/interpreter/interp.zig").executeFunction(env, run_idx);

    try testing.expectEqualStrings("hello\n", adapter.getStdoutBytes());
}

test "WasiCliAdapter: hello-world fixture (cli/stdout + io/streams + run)" {
    const executor = @import("executor.zig");
    const abi_mod = @import("canonical_abi.zig");
    const testing = std.testing;

    // Hand-authored core module:
    //   (type 0 (func (result i32)))                    ;; () -> i32
    //   (type 1 (func (param i32 i32 i32) (result i32))) ;; write_flush
    //   (type 2 (func (param i32)))                      ;; drop_stream
    //   (import "host" "get_stdout"  (func (type 0)))   ;; func 0
    //   (import "host" "write_flush" (func (type 1)))   ;; func 1
    //   (import "host" "drop_stream" (func (type 2)))   ;; func 2
    //   (memory 1)
    //   (func (type 0)                                   ;; func 3 = "run"
    //     (local i32)
    //     call $get_stdout         ;; handle on stack
    //     local.tee 0              ;; save handle, leave on stack
    //     i32.const 16 i32.const 14
    //     call $write_flush        ;; result discriminant on stack
    //     drop                     ;; ignore (test: should be 0)
    //     local.get 0
    //     call $drop_stream
    //     i32.const 0)             ;; return ok
    //   (export "run" (func 3))
    //   (data (i32.const 16) "hello, world!\n")
    const core_wasm = [_]u8{
        0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
        // type section: 3 types, content = 1 + 4 + 7 + 4 = 16 bytes
        0x01, 0x10, 0x03,
        0x60, 0x00, 0x01, 0x7f, // type 0
        0x60, 0x03, 0x7f, 0x7f, 0x7f, 0x01, 0x7f, // type 1
        0x60, 0x01, 0x7f, 0x00, // type 2
        // import section: 3 imports, content = 1 + 18 + 19 + 19 = 57 bytes
        0x02, 0x39, 0x03, 0x04,
        'h',  'o',  's',  't',
        0x0a, 'g',  'e',  't',
        '_',  's',  't',  'd',
        'o',  'u',  't',  0x00,
        0x00, 0x04, 'h',  'o',
        's',  't',  0x0b, 'w',
        'r',  'i',  't',  'e',
        '_',  'f',  'l',  'u',
        's',  'h',  0x00, 0x01,
        0x04, 'h',  'o',  's',
        't',  0x0b, 'd',  'r',
        'o',  'p',  '_',  's',
        't',  'r',  'e',  'a',
        'm',  0x00, 0x02,
        // function section: 1 local fn of type 0
        0x03,
        0x02, 0x01, 0x00,
        // memory section: 1 mem, min=1
        0x05,
        0x03, 0x01, 0x00, 0x01,
        // export section: "run" -> func 3
        0x07, 0x07, 0x01, 0x03,
        'r',  'u',  'n',  0x00,
        0x03,
        // code section: 1 body, body_size=21, count=1 + 22 body = 23
        0x0a, 0x17, 0x01,
        0x15, // body size
        0x01, 0x01, 0x7f, // 1 local of i32
        0x10, 0x00, // call 0 (get_stdout)
        0x22, 0x00, // local.tee 0
        0x41, 0x10, // i32.const 16
        0x41, 0x0e, // i32.const 14
        0x10, 0x01, // call 1 (write_flush)
        0x1a, // drop
        0x20, 0x00, // local.get 0
        0x10, 0x02, // call 2 (drop_stream)
        0x41, 0x00, // i32.const 0
        0x0b, // end
        // data section: 1 segment, mem 0, offset i32.const 16, "hello, world!\n"
        0x0b,
        0x14,
        0x01,
        0x00,
        0x41,
        0x10,
        0x0b,
        0x0e,
        'h',
        'e',
        'l',
        'l',
        'o',
        ',',
        ' ',
        'w',
        'o',
        'r',
        'l',
        'd',
        '!',
        '\n',
    };

    const core_modules = [_]ctypes.CoreModule{.{ .data = &core_wasm }};

    // Component types:
    //   type 0 = list element u8 (used as element of list<u8>)  -- not a TypeDef; lists carry their element inline
    //   type 0 = func () -> own<output-stream(=resource type idx 99 sentinel)>
    // For simplicity use `.handle = ...` via own/borrow with a stable resource
    // type idx — we're not exercising guest-side resource tables, just the
    // i32 round-trip.
    const RES_TYPE_IDX: u32 = 100; // sentinel; never actually looked up.

    // type 0: get-stdout : () -> own<output-stream>
    const t0_results: ctypes.FuncType.ResultList = .{ .unnamed = .{ .own = RES_TYPE_IDX } };
    // type 1: write-and-flush : (own<output-stream>, list<u8>) -> result<_,_>
    const t1_params = [_]ctypes.NamedValType{
        .{ .name = "this", .type = .{ .own = RES_TYPE_IDX } },
        .{ .name = "data", .type = .{ .list = 4 } }, // list type at type idx 4
    };
    // type 2: drop : (own<output-stream>) -> ()
    const t2_params = [_]ctypes.NamedValType{
        .{ .name = "this", .type = .{ .own = RES_TYPE_IDX } },
    };
    // type 3: run : () -> result<_,_>  (idx of result type below)
    const t3_results: ctypes.FuncType.ResultList = .{ .unnamed = .{ .result = 5 } };

    const inst_stdout_decls = [_]ctypes.Decl{
        .{ .@"export" = .{ .name = "get-stdout", .desc = .{ .func = 0 } } },
    };
    const inst_streams_decls = [_]ctypes.Decl{
        .{ .@"export" = .{ .name = "[method]output-stream.blocking-write-and-flush", .desc = .{ .func = 1 } } },
        .{ .@"export" = .{ .name = "[resource-drop]output-stream", .desc = .{ .func = 2 } } },
    };

    const type_defs = [_]ctypes.TypeDef{
        .{ .func = .{ .params = &.{}, .results = t0_results } }, // 0
        .{ .func = .{ .params = &t1_params, .results = .{ .unnamed = .{ .result = 5 } } } }, // 1
        .{ .func = .{ .params = &t2_params, .results = .none } }, // 2
        .{ .func = .{ .params = &.{}, .results = t3_results } }, // 3
        .{ .list = .{ .element = .u8 } }, // 4
        .{ .result = .{ .ok = null, .err = null } }, // 5
        .{ .instance = .{ .decls = &inst_stdout_decls } }, // 6
        .{ .instance = .{ .decls = &inst_streams_decls } }, // 7
    };

    const imports_decl = [_]ctypes.ImportDecl{
        .{ .name = "wasi:cli/stdout", .desc = .{ .instance = 6 } },
        .{ .name = "wasi:io/streams", .desc = .{ .instance = 7 } },
    };

    // Aliases: 3 component-func + 1 core-func (for the lifted run export).
    const aliases_decl = [_]ctypes.Alias{
        .{ .instance_export = .{ .sort = .func, .instance_idx = 0, .name = "get-stdout" } }, // → comp func 0
        .{ .instance_export = .{ .sort = .func, .instance_idx = 1, .name = "[method]output-stream.blocking-write-and-flush" } }, // → comp func 1
        .{ .instance_export = .{ .sort = .func, .instance_idx = 1, .name = "[resource-drop]output-stream" } }, // → comp func 2
        .{ .instance_export = .{ .sort = .{ .core = .func }, .instance_idx = 1, .name = "run" } }, // core-func alias
    };

    // Canons: 3 lowers (core funcs 0..2), then 1 lift (comp func 3).
    // The lift's core_func_idx points into the component-level core-func
    // index space: 0..2 = lowers, 3 = the "run" core alias above.
    const canons = [_]ctypes.Canon{
        .{ .lower = .{ .func_idx = 0, .opts = &.{} } },
        .{ .lower = .{ .func_idx = 1, .opts = &.{} } },
        .{ .lower = .{ .func_idx = 2, .opts = &.{} } },
        .{ .lift = .{ .core_func_idx = 3, .type_idx = 3, .opts = &.{} } },
    };

    // Inline core instance exposes the 3 lowered funcs as host.{...} imports
    // for the actual core module instantiation.
    const inline_exports = [_]ctypes.CoreInlineExport{
        .{ .name = "get_stdout", .sort_idx = .{ .sort = .func, .idx = 0 } },
        .{ .name = "write_flush", .sort_idx = .{ .sort = .func, .idx = 1 } },
        .{ .name = "drop_stream", .sort_idx = .{ .sort = .func, .idx = 2 } },
    };
    const inst_args = [_]ctypes.CoreInstantiateArg{
        .{ .name = "host", .instance_idx = 0 },
    };
    const core_insts = [_]ctypes.CoreInstanceExpr{
        .{ .exports = &inline_exports },
        .{ .instantiate = .{ .module_idx = 0, .args = &inst_args } },
    };

    const exports_decl = [_]ctypes.ExportDecl{
        .{ .name = "run", .desc = .{ .func = 3 }, .sort_idx = .{ .sort = .func, .idx = 3 } },
    };

    const component = ctypes.Component{
        .core_modules = &core_modules,
        .core_instances = &core_insts,
        .core_types = &.{},
        .components = &.{},
        .instances = &.{},
        .aliases = &aliases_decl,
        .types = &type_defs,
        .canons = &canons,
        .imports = &imports_decl,
        .exports = &exports_decl,
    };

    const inst = try instance_mod.instantiate(&component, testing.allocator);
    defer inst.deinit();

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    var providers: std.StringHashMapUnmanaged(ImportBinding) = .empty;
    defer providers.deinit(testing.allocator);
    try adapter.populateWasiCliRun(&providers, "wasi:cli/stdout", "wasi:io/streams");

    try inst.linkImports(providers);

    // All three trampolines should now have their host_func bound.
    try testing.expect(inst.trampoline_ctxs.items.len == 3);
    for (inst.trampoline_ctxs.items) |ctx| {
        try testing.expect(ctx.host_func.call != null);
    }

    // Invoke the lifted "run" component export. It returns
    // result<_,_> which lifts to a `.result_val { is_ok = true }`.
    var results: [1]abi_mod.InterfaceValue = undefined;
    try executor.callComponentFunc(inst, "run", &.{}, &results, testing.allocator);
    try testing.expect(results[0] == .result_val);
    try testing.expect(results[0].result_val.is_ok);

    try testing.expectEqualStrings("hello, world!\n", adapter.getStdoutBytes());

    // Stream handle should now be dropped (slot is null).
    try testing.expectEqual(@as(usize, 0), adapter.stream_table.publishedCount());
}

test "matchesWasiPrefix: exact and version-suffixed names" {
    const testing = std.testing;
    try testing.expect(matchesWasiPrefix("wasi:cli/stdout", "wasi:cli/stdout"));
    try testing.expect(matchesWasiPrefix("wasi:cli/stdout@0.2.6", "wasi:cli/stdout"));
    try testing.expect(matchesWasiPrefix("wasi:io/streams@0.2", "wasi:io/streams"));
    try testing.expect(!matchesWasiPrefix("wasi:cli/stdout-extra", "wasi:cli/stdout"));
    try testing.expect(!matchesWasiPrefix("other:cli/stdout", "wasi:cli/stdout"));
    try testing.expect(!matchesWasiPrefix("wasi:cli/std", "wasi:cli/stdout"));
}

test "runLoadedComponent: matches versioned WASI import names" {
    // Same hand-authored fixture as the "hello-world fixture" test, but
    // with versioned import names (`@0.2.6`) and dispatched through the
    // CLI's `runLoadedComponent` helper. This exercises the full
    // populateWasiProviders → linkImports → callComponentFunc path.
    const testing = std.testing;

    const core_wasm = [_]u8{
        0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
        0x01, 0x10, 0x03, 0x60, 0x00, 0x01, 0x7f, 0x60,
        0x03, 0x7f, 0x7f, 0x7f, 0x01, 0x7f, 0x60, 0x01,
        0x7f, 0x00, 0x02, 0x39, 0x03, 0x04, 'h',  'o',
        's',  't',  0x0a, 'g',  'e',  't',  '_',  's',
        't',  'd',  'o',  'u',  't',  0x00, 0x00, 0x04,
        'h',  'o',  's',  't',  0x0b, 'w',  'r',  'i',
        't',  'e',  '_',  'f',  'l',  'u',  's',  'h',
        0x00, 0x01, 0x04, 'h',  'o',  's',  't',  0x0b,
        'd',  'r',  'o',  'p',  '_',  's',  't',  'r',
        'e',  'a',  'm',  0x00, 0x02, 0x03, 0x02, 0x01,
        0x00, 0x05, 0x03, 0x01, 0x00, 0x01, 0x07, 0x07,
        0x01, 0x03, 'r',  'u',  'n',  0x00, 0x03, 0x0a,
        0x17, 0x01, 0x15, 0x01, 0x01, 0x7f, 0x10, 0x00,
        0x22, 0x00, 0x41, 0x10, 0x41, 0x0e, 0x10, 0x01,
        0x1a, 0x20, 0x00, 0x10, 0x02, 0x41, 0x00, 0x0b,
        0x0b, 0x14, 0x01, 0x00, 0x41, 0x10, 0x0b, 0x0e,
        'h',  'e',  'l',  'l',  'o',  ',',  ' ',  'w',
        'o',  'r',  'l',  'd',  '!',  '\n',
    };
    const core_modules = [_]ctypes.CoreModule{.{ .data = &core_wasm }};

    const RES_TYPE_IDX: u32 = 100;
    const t1_params = [_]ctypes.NamedValType{
        .{ .name = "this", .type = .{ .own = RES_TYPE_IDX } },
        .{ .name = "data", .type = .{ .list = 4 } },
    };
    const t2_params = [_]ctypes.NamedValType{
        .{ .name = "this", .type = .{ .own = RES_TYPE_IDX } },
    };

    const inst_stdout_decls = [_]ctypes.Decl{
        .{ .@"export" = .{ .name = "get-stdout", .desc = .{ .func = 0 } } },
    };
    const inst_streams_decls = [_]ctypes.Decl{
        .{ .@"export" = .{ .name = "[method]output-stream.blocking-write-and-flush", .desc = .{ .func = 1 } } },
        .{ .@"export" = .{ .name = "[resource-drop]output-stream", .desc = .{ .func = 2 } } },
    };

    const type_defs = [_]ctypes.TypeDef{
        .{ .func = .{ .params = &.{}, .results = .{ .unnamed = .{ .own = RES_TYPE_IDX } } } },
        .{ .func = .{ .params = &t1_params, .results = .{ .unnamed = .{ .result = 5 } } } },
        .{ .func = .{ .params = &t2_params, .results = .none } },
        .{ .func = .{ .params = &.{}, .results = .{ .unnamed = .{ .result = 5 } } } },
        .{ .list = .{ .element = .u8 } },
        .{ .result = .{ .ok = null, .err = null } },
        .{ .instance = .{ .decls = &inst_stdout_decls } },
        .{ .instance = .{ .decls = &inst_streams_decls } },
    };

    // Versioned import names — the CLI must still match these.
    const imports_decl = [_]ctypes.ImportDecl{
        .{ .name = "wasi:cli/stdout@0.2.6", .desc = .{ .instance = 6 } },
        .{ .name = "wasi:io/streams@0.2.6", .desc = .{ .instance = 7 } },
    };

    const aliases_decl = [_]ctypes.Alias{
        .{ .instance_export = .{ .sort = .func, .instance_idx = 0, .name = "get-stdout" } },
        .{ .instance_export = .{ .sort = .func, .instance_idx = 1, .name = "[method]output-stream.blocking-write-and-flush" } },
        .{ .instance_export = .{ .sort = .func, .instance_idx = 1, .name = "[resource-drop]output-stream" } },
        .{ .instance_export = .{ .sort = .{ .core = .func }, .instance_idx = 1, .name = "run" } },
    };

    const canons = [_]ctypes.Canon{
        .{ .lower = .{ .func_idx = 0, .opts = &.{} } },
        .{ .lower = .{ .func_idx = 1, .opts = &.{} } },
        .{ .lower = .{ .func_idx = 2, .opts = &.{} } },
        .{ .lift = .{ .core_func_idx = 3, .type_idx = 3, .opts = &.{} } },
    };

    const inline_exports = [_]ctypes.CoreInlineExport{
        .{ .name = "get_stdout", .sort_idx = .{ .sort = .func, .idx = 0 } },
        .{ .name = "write_flush", .sort_idx = .{ .sort = .func, .idx = 1 } },
        .{ .name = "drop_stream", .sort_idx = .{ .sort = .func, .idx = 2 } },
    };
    const inst_args = [_]ctypes.CoreInstantiateArg{
        .{ .name = "host", .instance_idx = 0 },
    };
    const core_insts = [_]ctypes.CoreInstanceExpr{
        .{ .exports = &inline_exports },
        .{ .instantiate = .{ .module_idx = 0, .args = &inst_args } },
    };

    const exports_decl = [_]ctypes.ExportDecl{
        .{ .name = "run", .desc = .{ .func = 3 }, .sort_idx = .{ .sort = .func, .idx = 3 } },
    };

    const component = ctypes.Component{
        .core_modules = &core_modules,
        .core_instances = &core_insts,
        .core_types = &.{},
        .components = &.{},
        .instances = &.{},
        .aliases = &aliases_decl,
        .types = &type_defs,
        .canons = &canons,
        .imports = &imports_decl,
        .exports = &exports_decl,
    };

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    const outcome = try runLoadedComponent(&component, testing.allocator, &adapter, .{});
    try testing.expect(outcome.is_ok);
    try testing.expectEqualStrings("hello, world!\n", adapter.getStdoutBytes());
}

test "populateWasiProviders: binds wasi:io/poll and wasi:io/error (#154)" {
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    // Hand-build a component with versioned poll + error instance imports.
    const imports = [_]ctypes_root.ImportDecl{
        .{ .name = "wasi:io/poll@0.2.6", .desc = .{ .instance = 0 } },
        .{ .name = "wasi:io/error@0.2.6", .desc = .{ .instance = 0 } },
    };
    const component = ctypes_root.Component{
        .core_modules = &.{},
        .core_instances = &.{},
        .core_types = &.{},
        .components = &.{},
        .instances = &.{},
        .aliases = &.{},
        .types = &.{},
        .canons = &.{},
        .imports = &imports,
        .exports = &.{},
    };

    var providers: std.StringHashMapUnmanaged(ImportBinding) = .empty;
    defer providers.deinit(testing.allocator);

    try populateWasiProviders(&adapter, &component, &providers);

    try testing.expect(providers.contains("wasi:io/poll@0.2.6"));
    try testing.expect(providers.contains("wasi:io/error@0.2.6"));
    // Bare names (no version suffix) must NOT be registered when the
    // component imports the versioned form.
    try testing.expect(!providers.contains("wasi:io/poll"));
    try testing.expect(!providers.contains("wasi:io/error"));

    // Poll methods and resource drops are wired.
    try testing.expect(adapter.io_poll_iface.members.contains("poll"));
    try testing.expect(adapter.io_poll_iface.members.contains("[method]pollable.ready"));
    try testing.expect(adapter.io_poll_iface.members.contains("[method]pollable.block"));
    try testing.expect(adapter.io_poll_iface.members.contains("[resource-drop]pollable"));
    try testing.expect(adapter.io_error_iface.members.contains("[resource-drop]error"));
}

test "wasiVersion: detects @0.2 / @0.3 / unspecified" {
