    var dt_fields = [_]InterfaceValue{
        .{ .u64 = 1_700_000_000 },
        .{ .u32 = 0 },
    };
    const dt_iv = InterfaceValue{ .record_val = &dt_fields };
    const ts_arg = InterfaceValue{ .variant_val = .{ .discriminant = 2, .payload = &dt_iv } };

    var set_args = [_]InterfaceValue{
        .{ .handle = handle },
        ts_arg,
        ts_arg,
    };
