    const preopen_handle = try adapter.pushFsDescriptor(.{ .preopen = .{
        .dir = tmp.dir,
        .flags = .{ .read = true, .mutate_directory = true },
    } });
    defer _ = adapter.fs_descriptor_table.withdraw(preopen_handle);

    var ci: ComponentInstance = undefined;
