test "wasi:http #521: https outgoing-handler proceeds past the TLS gate" {
    // Regression for #521: the `HTTP_protocol_error` short-circuit
    // added by #477/#501 has been removed. `https://` requests now
    // flow into `std.http.Client.fetch`, which delegates TLS to
    // `std.crypto.tls`. The destination (`127.0.0.1:1`) is almost
    // certainly closed, so `fetch` returns `error.ConnectionRefused`
    // before the TLS handshake even begins; with the #583 A3 error
    // refinement, this surfaces as `connection_refused` (was
    // `internal_error` pre-refinement). The point of this test
    // remains: `HTTP_protocol_error` must never again be produced by a
    // well-formed `https://` request.
    //
    // (#583 A2) The outbound fetch now runs on a worker thread and
    // the future is `.pending` on return; we drive it via
    // `drainPendingHttpFetches` until the worker publishes its
    // outcome through `mapHttpFetchError`.
    //
    // Skipped on Windows: `std.http.Client.fetch` over WinSock surfaces
    // `WSAECONNREFUSED` as `error.Unexpected` (or occasionally
    // `ConnectionResetByPeer`) rather than the POSIX
    // `error.ConnectionRefused`, so this end-to-end transport check is
    // platform-dependent. The pure-helper `mapHttpFetchError`
    // tests further down exercise the WIT mapping deterministically
    // across all targets.
    if (builtin.os.tag == .windows) return error.SkipZigTest;
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    // Non-empty allow-list so the empty-list deny path doesn't fire.
    const allow = try testing.allocator.alloc(IpCidr, 1);
    allow[0] = try IpCidr.parse("127.0.0.0/8");
    adapter.sockets_allow_list_template = allow;

    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);

    const req = try testing.allocator.create(OutgoingRequest);
    req.* = .{
        .method_disc = 0, // GET
        .scheme_disc = 1, // https
        .authority = try testing.allocator.dupe(u8, "127.0.0.1:1"),
        .path_with_query = try testing.allocator.dupe(u8, "/"),
        .headers_handle = fh,
    };
    const rh = try adapter.pushOutgoingRequest(req);

    const args = [_]InterfaceValue{
        .{ .handle = rh },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpOutgoingHandlerHandle(&adapter, &ci, &args, &results, testing.allocator);
    defer results[0].deinit(testing.allocator);

    try testing.expect(results[0] == .result_val);
    try testing.expect(results[0].result_val.is_ok);
    const fut_handle = results[0].result_val.payload.?.handle;
    const fut = adapter.http_future_responses.unsafeGetPtrForTest(fut_handle).?.*;

    // Drive the worker thread to completion. The fetch fails fast
    // because the destination has no listener.
    var drive_attempts: usize = 0;
    while (drive_attempts < 50_000 and fut.state == .pending) : (drive_attempts += 1) {
        adapter.drainPendingHttpFetches();
        if (fut.state != .pending) break;
        const io = std.Io.Threaded.global_single_threaded.io();
        const dur: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
            .clock = .awake,
        };
        dur.sleep(io) catch {};
    }
    try testing.expect(fut.state == .ready_err);
    // The gate is gone — `HTTP_protocol_error` must never be the
    // result of a scheme check on `https://`.
    try testing.expect(fut.state.ready_err != @as(u32, @intFromEnum(HttpErrorCode.HTTP_protocol_error)));
    // Port 1 has no listener — TCP refuses before TLS can run, so
    // the refined mapping yields `connection_refused` (#583 A3).
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.connection_refused)),
        fut.state.ready_err,
    );
}

/// Block-poll an `outgoing-handler` future until its worker thread
/// publishes a settled state (`.ready_ok` / `.ready_err`) or the
/// iteration budget is exhausted. Mirrors how `pollable.block` /
/// `poll.poll` would drive the future in real component execution.
/// (#583 A2)
fn p3DrainPendingHttpUntilSettled(
    adapter: *WasiCliAdapter,
    fut: *FutureIncomingResponse,
    iters: usize,
) void {
    var i: usize = 0;
    while (i < iters and fut.state == .pending) : (i += 1) {
        adapter.drainPendingHttpFetches();
        if (fut.state != .pending) return;
        const io = std.Io.Threaded.global_single_threaded.io();
        const dur: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
            .clock = .awake,
        };
        dur.sleep(io) catch {};
    }
}

/// Spin up a one-shot HTTP/1.1 server bound to 127.0.0.1 on an
/// arbitrary port, serve a single `GET /` request with the provided
/// body, then close. The server runs on a dedicated thread so the
/// test thread can issue a fetch concurrently. Used by the #583 A2
/// happy-path round-trip test below.
const TestHttpServer = struct {
    thread: std.Thread,
    port: u16,

    fn serveLoopback(allocator: Allocator, body: []const u8) !TestHttpServer {
        const io = std.Io.Threaded.global_single_threaded.io();
        var any: std.Io.net.IpAddress = .{ .ip4 = .{ .bytes = .{ 127, 0, 0, 1 }, .port = 0 } };
        const server = try std.Io.net.IpAddress.listen(&any, io, .{
            .kernel_backlog = 1,
        });
        const bound = switch (server.socket.address) {
            .ip4 => |v4| v4.port,
            else => {
                var srv_mut = server;
                srv_mut.deinit(io);
                return error.SkipZigTest;
            },
        };
        const body_copy = try allocator.dupe(u8, body);
        const ctx = try allocator.create(TestHttpServerCtx);
        ctx.* = .{
            .allocator = allocator,
            .server = server,
            .body = body_copy,
        };
        const t = try std.Thread.spawn(.{}, TestHttpServerCtx.run, .{ctx});
        return .{ .thread = t, .port = bound };
    }
};

const TestHttpServerCtx = struct {
    allocator: Allocator,
    server: std.Io.net.Server,
    body: []u8,

    fn run(self: *TestHttpServerCtx) void {
        defer {
            self.allocator.free(self.body);
            const io = std.Io.Threaded.global_single_threaded.io();
            var srv = self.server;
            srv.deinit(io);
            self.allocator.destroy(self);
        }
        const io = std.Io.Threaded.global_single_threaded.io();
        const stream = self.server.accept(io) catch return;
        defer stream.close(io);

        // Drain request bytes until end-of-headers. The client is
        // `std.http.Client.fetch` with no body, so we don't parse
        // `Content-Length`.
        var req_buf: [4096]u8 = undefined;
        var total: usize = 0;
        while (total < req_buf.len) {
            var dests = [_][]u8{req_buf[total..]};
            const n = io.vtable.netRead(io.userdata, stream.socket.handle, &dests) catch return;
            if (n == 0) break;
            total += n;
            if (std.mem.indexOf(u8, req_buf[0..total], "\r\n\r\n") != null) break;
        }

        var resp_buf: [256]u8 = undefined;
        const resp_head = std.fmt.bufPrint(&resp_buf, "HTTP/1.1 200 OK\r\n" ++
            "Content-Length: {d}\r\n" ++
            "Connection: close\r\n" ++
            "\r\n", .{self.body.len}) catch return;
        const head_slices = [_][]const u8{resp_head};
        _ = io.vtable.netWrite(io.userdata, stream.socket.handle, &.{}, &head_slices, 1) catch return;
        const body_slices = [_][]const u8{self.body};
        _ = io.vtable.netWrite(io.userdata, stream.socket.handle, &.{}, &body_slices, 1) catch return;
    }
};

test "wasi:http #583 A2: outgoing-handler defers fetch and resolves via worker thread" {
    // Happy-path round-trip exercising the #583 A2 deferred-completion
    // path end to end:
    //   * mint an outgoing-request bound to a loopback test server,
    //   * call `outgoing-handler.handle` — observe a `.pending` future,
    //   * drive `drainPendingHttpFetches` until the worker publishes,
    //   * assert the future settles `.ready_ok(incoming-response)` with
    //     the expected 200 status and body bytes.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    var server = TestHttpServer.serveLoopback(testing.allocator, "hello-583-A2") catch
        return error.SkipZigTest;

    // 127.0.0.0/8 allow-list — required to leave the empty-list deny path.
    const allow = try testing.allocator.alloc(IpCidr, 1);
    allow[0] = try IpCidr.parse("127.0.0.0/8");
    adapter.sockets_allow_list_template = allow;

    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);

    const req = try testing.allocator.create(OutgoingRequest);
    req.* = .{
        .method_disc = 0, // GET
        .scheme_disc = 0, // http
        .authority = try std.fmt.allocPrint(testing.allocator, "127.0.0.1:{d}", .{server.port}),
        .path_with_query = try testing.allocator.dupe(u8, "/"),
        .headers_handle = fh,
    };
    const rh = try adapter.pushOutgoingRequest(req);

    const args = [_]InterfaceValue{
        .{ .handle = rh },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpOutgoingHandlerHandle(&adapter, &ci, &args, &results, testing.allocator);
    defer results[0].deinit(testing.allocator);

    try testing.expect(results[0] == .result_val);
    try testing.expect(results[0].result_val.is_ok);
    const fut_handle = results[0].result_val.payload.?.handle;
    const fut = adapter.http_future_responses.unsafeGetPtrForTest(fut_handle).?.*;
    // First observation: future is `.pending` and a worker entry is
    // registered. The empty-allow-list / invalid-URL deny paths
    // would have settled synchronously, so seeing `.pending` here
    // is exactly what the spec calls for.
    try testing.expect(fut.state == .pending);
    try testing.expectEqual(@as(usize, 1), adapter.pending_http_fetches.publishedCount());

    p3DrainPendingHttpUntilSettled(&adapter, fut, 10_000);
    // Make sure the server thread has fully exited before we tear
    // down the test allocator (the body copy lives on the server
    // context).
    server.thread.join();

    try testing.expect(fut.state == .ready_ok);
    const ir = adapter.http_incoming_responses.unsafeGetPtrForTest(fut.state.ready_ok).?.*;
    try testing.expectEqual(@as(u16, 200), ir.status);
    try testing.expect(ir.body_data != null);
    try testing.expectEqualStrings("hello-583-A2", ir.body_data.?);
    // Pending list drained — entry was consumed by the settle.
    try testing.expectEqual(@as(usize, 0), adapter.pending_http_fetches.publishedCount());
}

/// Spin up a one-shot HTTP/1.1 server bound to 127.0.0.1 on an arbitrary
/// port whose response head is fully caller-supplied. Used by the
/// #583 A4 response-header tests below — the existing
/// `TestHttpServer.serveLoopback` is locked to a minimal
/// `Content-Length`/`Connection: close` response shape, so a second
/// helper sits alongside that lets the test specify the exact set of
/// (name, value) response headers (and accompanying body) the lifted
/// `incoming-response` should reflect back through
/// `incoming-response.headers`. The server runs on a dedicated thread
/// so the test thread can issue a fetch concurrently.
const TestHttpHeaderServer = struct {
    thread: std.Thread,
    port: u16,

    /// `response_head` is the full response head including the status
    /// line and trailing `\r\n\r\n` (caller-supplied). `body` is the
    /// response body bytes that follow the head; both slices are
    /// duped into context-owned memory and freed after the server
    /// finishes.
    fn serveLoopback(
        allocator: Allocator,
        response_head: []const u8,
        body: []const u8,
    ) !TestHttpHeaderServer {
        const io = std.Io.Threaded.global_single_threaded.io();
        var any: std.Io.net.IpAddress = .{ .ip4 = .{ .bytes = .{ 127, 0, 0, 1 }, .port = 0 } };
        const server = try std.Io.net.IpAddress.listen(&any, io, .{
            .kernel_backlog = 1,
        });
        const bound = switch (server.socket.address) {
            .ip4 => |v4| v4.port,
            else => {
                var srv_mut = server;
                srv_mut.deinit(io);
                return error.SkipZigTest;
            },
        };
        const head_copy = try allocator.dupe(u8, response_head);
        errdefer allocator.free(head_copy);
        const body_copy = try allocator.dupe(u8, body);
        errdefer allocator.free(body_copy);
        const ctx = try allocator.create(TestHttpHeaderServerCtx);
        ctx.* = .{
            .allocator = allocator,
            .server = server,
            .head = head_copy,
            .body = body_copy,
        };
        const t = try std.Thread.spawn(.{}, TestHttpHeaderServerCtx.run, .{ctx});
        return .{ .thread = t, .port = bound };
    }
};

const TestHttpHeaderServerCtx = struct {
    allocator: Allocator,
    server: std.Io.net.Server,
    head: []u8,
    body: []u8,

    fn run(self: *TestHttpHeaderServerCtx) void {
        defer {
            self.allocator.free(self.head);
            self.allocator.free(self.body);
            const io = std.Io.Threaded.global_single_threaded.io();
            var srv = self.server;
            srv.deinit(io);
            self.allocator.destroy(self);
        }
        const io = std.Io.Threaded.global_single_threaded.io();
        const stream = self.server.accept(io) catch return;
        defer stream.close(io);

        // Drain request bytes until end-of-headers. The client side
        // sends a bodyless GET so we don't need to parse
        // `Content-Length`.
        var req_buf: [4096]u8 = undefined;
        var total: usize = 0;
        while (total < req_buf.len) {
            var dests = [_][]u8{req_buf[total..]};
            const n = io.vtable.netRead(io.userdata, stream.socket.handle, &dests) catch return;
            if (n == 0) break;
            total += n;
            if (std.mem.indexOf(u8, req_buf[0..total], "\r\n\r\n") != null) break;
        }

        const head_slices = [_][]const u8{self.head};
        _ = io.vtable.netWrite(io.userdata, stream.socket.handle, &.{}, &head_slices, 1) catch return;
        if (self.body.len > 0) {
            const body_slices = [_][]const u8{self.body};
            _ = io.vtable.netWrite(io.userdata, stream.socket.handle, &.{}, &body_slices, 1) catch return;
        }
    }
};

/// Drive an outbound P2 outgoing-handler call against a caller-supplied
/// `TestHttpHeaderServer` and return the lifted `IncomingResponse` so
/// the test can inspect its lifted `headers_handle`. Shared scaffolding
/// for the #583 A4 response-header tests. Caller owns the returned
/// `IncomingResponse` (still owned by the adapter — freed on
/// `adapter.deinit()`).
fn p3HttpFetchAndAwaitResponse(
    adapter: *WasiCliAdapter,
    ci: *ComponentInstance,
    allocator: Allocator,
    port: u16,
) !*IncomingResponse {
    const fields = try allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);

    const req = try allocator.create(OutgoingRequest);
    req.* = .{
        .method_disc = 0, // GET
        .scheme_disc = 0, // http
        .authority = try std.fmt.allocPrint(allocator, "127.0.0.1:{d}", .{port}),
        .path_with_query = try allocator.dupe(u8, "/"),
        .headers_handle = fh,
    };
    const rh = try adapter.pushOutgoingRequest(req);

    const args = [_]InterfaceValue{
        .{ .handle = rh },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpOutgoingHandlerHandle(adapter, ci, &args, &results, allocator);
    defer results[0].deinit(allocator);

    if (results[0] != .result_val or !results[0].result_val.is_ok)
        return error.UnexpectedHandlerResult;
    const fut_handle = results[0].result_val.payload.?.handle;
    const fut = adapter.http_future_responses.unsafeGetPtrForTest(fut_handle).?.*;
    p3DrainPendingHttpUntilSettled(adapter, fut, 10_000);
    if (fut.state != .ready_ok) return error.HttpFetchFailed;
    return adapter.http_incoming_responses.unsafeGetPtrForTest(fut.state.ready_ok).?.*;
}

test "wasi:http #583 A4: outgoing-handler surfaces single response header" {
    // Round-trip: GET against a local listener that echoes a single
    // custom `X-Wamr-Test` header. The lifted `incoming-response`
    // must report that header through `incoming-response.headers`.
    if (!build_options.network_tests) return error.SkipZigTest;
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    var server = TestHttpHeaderServer.serveLoopback(
        testing.allocator,
        "HTTP/1.1 200 OK\r\n" ++
            "X-Wamr-Test: hello-headers\r\n" ++
            "Content-Length: 5\r\n" ++
            "Connection: close\r\n" ++
            "\r\n",
        "body!",
    ) catch return error.SkipZigTest;

    const allow = try testing.allocator.alloc(IpCidr, 1);
    allow[0] = try IpCidr.parse("127.0.0.0/8");
    adapter.sockets_allow_list_template = allow;

    const ir = try p3HttpFetchAndAwaitResponse(&adapter, &ci, testing.allocator, server.port);
    server.thread.join();

    try testing.expectEqual(@as(u16, 200), ir.status);
    try testing.expectEqualStrings("body!", ir.body_data.?);

    // Inspect lifted headers via the public `incoming-response.headers`
    // accessor (#583 A4) — exactly the path a guest would observe.
    const hdr_args = [_]InterfaceValue{.{ .handle = 0 }};
    _ = hdr_args; // shape filled in below
    var hdr_results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    var ir_handle: u32 = 0;
    const response_handles = try adapter.http_incoming_responses.snapshotHandles(testing.allocator);
    defer testing.allocator.free(response_handles);
    for (response_handles) |handle| {
        if (adapter.http_incoming_responses.unsafeGetPtrForTest(handle).?.* == ir) {
            ir_handle = handle;
            break;
        }
    }
    try testing.expect(ir_handle != 0);
    const get_args = [_]InterfaceValue{.{ .handle = ir_handle }};
    try WasiCliAdapter.httpIncomingResponseHeaders(&adapter, &ci, &get_args, &hdr_results, testing.allocator);
    const hf_handle = hdr_results[0].handle;
    const hf = adapter.http_fields_table.unsafeGetPtrForTest(hf_handle).?.*;
    // Exactly one application-level header survives the
    // transport-managed strip (`X-Wamr-Test`).
    try testing.expectEqual(@as(usize, 1), hf.entries.items.len);
    try testing.expectEqualStrings("X-Wamr-Test", hf.entries.items[0].name);
    try testing.expectEqualStrings("hello-headers", hf.entries.items[0].value);
}

test "wasi:http #583 A4: outgoing-handler surfaces multiple response headers in order" {
    // Multi-header: a listener returning three distinct headers must
    // round-trip all three through `incoming-response.headers` in the
    // server's emit order.
    if (!build_options.network_tests) return error.SkipZigTest;
