    server.thread.join();

    try testing.expectEqual(@as(u16, 201), ir.status);

    const hf = adapter.http_fields_table.unsafeGetPtrForTest(ir.headers_handle).?.*;
    // Three application-level headers survive the strip; the two
    // transport-managed entries (`Content-Length`, `Connection`) are
    // gone. Wire order is preserved.
    try testing.expectEqual(@as(usize, 3), hf.entries.items.len);
    try testing.expectEqualStrings("X-First", hf.entries.items[0].name);
    try testing.expectEqualStrings("alpha", hf.entries.items[0].value);
    try testing.expectEqualStrings("Content-Type", hf.entries.items[1].name);
    try testing.expectEqualStrings("text/plain", hf.entries.items[1].value);
    try testing.expectEqualStrings("X-Second", hf.entries.items[2].name);
    try testing.expectEqualStrings("beta", hf.entries.items[2].value);
}

test "wasi:http #583 A4: outgoing-handler strips transport-managed response headers" {
    // The WIT spec requires the host to strip transport-managed
    // headers (Content-Length, Transfer-Encoding, Connection,
    // Keep-Alive, Trailer, TE, Upgrade, Host) from the lifted
    // `incoming-response.headers`. Build a response that mixes one
    // application header with a full set of transport-managed
    // headers — only the application header must survive.
    if (!build_options.network_tests) return error.SkipZigTest;
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    var server = TestHttpHeaderServer.serveLoopback(
        testing.allocator,
        "HTTP/1.1 200 OK\r\n" ++
            "Content-Length: 3\r\n" ++
            "Connection: close\r\n" ++
            "Keep-Alive: timeout=5\r\n" ++
            "X-App: kept\r\n" ++
            "Trailer: X-Foo\r\n" ++
            "\r\n",
        "ok!",
    ) catch return error.SkipZigTest;

    const allow = try testing.allocator.alloc(IpCidr, 1);
    allow[0] = try IpCidr.parse("127.0.0.0/8");
    adapter.sockets_allow_list_template = allow;

    const ir = try p3HttpFetchAndAwaitResponse(&adapter, &ci, testing.allocator, server.port);
    server.thread.join();

    try testing.expectEqual(@as(u16, 200), ir.status);
    try testing.expectEqualStrings("ok!", ir.body_data.?);

    const hf = adapter.http_fields_table.unsafeGetPtrForTest(ir.headers_handle).?.*;
    // Only `X-App` survives — all four transport-managed entries are
    // stripped by `isTransportManagedHeader`.
    try testing.expectEqual(@as(usize, 1), hf.entries.items.len);
    try testing.expectEqualStrings("X-App", hf.entries.items[0].name);
    try testing.expectEqualStrings("kept", hf.entries.items[0].value);
    // Sanity-check the strip predicate is case-insensitive — the
    // server emitted mixed-case headers; case must not affect the
    // match.
    for (hf.entries.items) |e| {
        try testing.expect(!std.ascii.eqlIgnoreCase(e.name, "content-length"));
        try testing.expect(!std.ascii.eqlIgnoreCase(e.name, "connection"));
        try testing.expect(!std.ascii.eqlIgnoreCase(e.name, "keep-alive"));
        try testing.expect(!std.ascii.eqlIgnoreCase(e.name, "trailer"));
    }
}

// Pure-helper test for `isTransportManagedHeader` — no network
// required. Exercises the case-insensitive match and the full set of
// transport-managed names the WIT spec mandates the host strip.
// (#583 A4)
test "wasi:http #583 A4: isTransportManagedHeader matches the spec set case-insensitively" {
    const testing = std.testing;
    inline for ([_][]const u8{
        "content-length",    "Content-Length",    "CONTENT-LENGTH",
        "transfer-encoding", "Transfer-Encoding", "connection",
        "Connection",        "keep-alive",        "Keep-Alive",
        "trailer",           "Trailer",           "te",
        "TE",                "upgrade",           "Upgrade",
        "host",              "Host",
    }) |name| {
        try testing.expect(isTransportManagedHeader(name));
    }
    inline for ([_][]const u8{
        "content-type",
        "x-app",
        "X-Wamr-Test",
        "authorization",
        "accept",
        "",
    }) |name| {
        try testing.expect(!isTransportManagedHeader(name));
    }
}

test "wasi:http #583 A2: outgoing-handler settles connect-refused as connection_refused" {
    // Negative-path coverage: a fetch against a closed loopback port
    // must surface through the deferred-completion worker and resolve
    // the future to `.ready_err(.connection_refused)` — the historic
    // synchronous handler always returned `internal_error`. The
    // #583 A3 `mapHttpFetchError` table now drives both the worker
    // and the synchronous P3 path to the same classified result. The
    // test also pins the *absence* of `HTTP_protocol_error` (the
    // #477 / #501 scheme gate was retired in #521 — this is the
    // regression keeper for the 0.2 outbound path).
    //
    // Skipped on Windows for the same reason as the sibling #521
    // tests: WinSock's `WSAECONNREFUSED` does not round-trip through
    // `std.http.Client.FetchError` as POSIX `error.ConnectionRefused`,
    // so the asserted variant is platform-dependent. The pure-helper
    // `mapHttpFetchError` tests (#583 A3) cover the deterministic
    // WIT mapping on every target.
    if (builtin.os.tag == .windows) return error.SkipZigTest;
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    const allow = try testing.allocator.alloc(IpCidr, 1);
    allow[0] = try IpCidr.parse("127.0.0.0/8");
    adapter.sockets_allow_list_template = allow;

    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);

    // 127.0.0.1:1 is the canonical "no listener" target on UNIX.
    const req = try testing.allocator.create(OutgoingRequest);
    req.* = .{
        .method_disc = 0,
        .scheme_disc = 0, // http
        .authority = try testing.allocator.dupe(u8, "127.0.0.1:1"),
        .path_with_query = try testing.allocator.dupe(u8, "/"),
        .headers_handle = fh,
    };
    const rh = try adapter.pushOutgoingRequest(req);

    const args = [_]InterfaceValue{
        .{ .handle = rh },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpOutgoingHandlerHandle(&adapter, &ci, &args, &results, testing.allocator);
    defer results[0].deinit(testing.allocator);

    const fut_handle = results[0].result_val.payload.?.handle;
    const fut = adapter.http_future_responses.unsafeGetPtrForTest(fut_handle).?.*;
    try testing.expect(fut.state == .pending);
    p3DrainPendingHttpUntilSettled(&adapter, fut, 10_000);
    try testing.expect(fut.state == .ready_err);
    try testing.expect(fut.state.ready_err != @as(u32, @intFromEnum(HttpErrorCode.HTTP_protocol_error)));
    // POSIX `error.ConnectionRefused` → `connection_refused` via the
    // #583 A3 mapping; deterministic on Linux / macOS.
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.connection_refused)),
        fut.state.ready_err,
    );
}

test "wasi:http #583 A2: adapter teardown joins in-flight workers cleanly (no UAF)" {
    // Cancellation / cleanup correctness: even if the host adapter
    // is torn down while a worker thread is still running its
    // `std.http.Client.fetch`, the shared heap struct must remain
    // valid until the worker is joined — otherwise the worker
    // UAFs on the publish-to-`shared.outcome` step. This test
    // exercises the path by issuing a fetch and immediately
    // dropping the adapter without draining; `deinit` is the cancel
    // edge that joins outstanding threads.
    //
    // It also covers the cancel sentinel path: `deinit` marks
    // `shared.cancelled = true` before joining, so even if the
    // worker raced ahead with a success, the post-join free path
    // discards the response body cleanly.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    var ci: ComponentInstance = undefined;

    const allow = try testing.allocator.alloc(IpCidr, 1);
    allow[0] = try IpCidr.parse("127.0.0.0/8");
    adapter.sockets_allow_list_template = allow;

    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);

    // Target an unbound loopback port so the worker returns quickly
    // with ECONNREFUSED — the join in `deinit` then completes
    // promptly. (We can't unblock a mid-fetch
    // `std.http.Client.fetch` on Zig 0.16, so the cancel test
    // relies on a fast-failing destination; the UAF-safety check
    // is the invariant.)
    const req = try testing.allocator.create(OutgoingRequest);
    req.* = .{
        .method_disc = 0,
        .scheme_disc = 0, // http
        .authority = try testing.allocator.dupe(u8, "127.0.0.1:1"),
        .path_with_query = try testing.allocator.dupe(u8, "/"),
        .headers_handle = fh,
    };
    const rh = try adapter.pushOutgoingRequest(req);

    const args = [_]InterfaceValue{
        .{ .handle = rh },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpOutgoingHandlerHandle(&adapter, &ci, &args, &results, testing.allocator);
    defer results[0].deinit(testing.allocator);

    const fut_handle = results[0].result_val.payload.?.handle;
    const fut = adapter.http_future_responses.unsafeGetPtrForTest(fut_handle).?.*;
    try testing.expect(fut.state == .pending);
    try testing.expectEqual(@as(usize, 1), adapter.pending_http_fetches.publishedCount());

    // Tear down without ever draining. `deinit` must:
    //   * set `cancelled` on every pending entry,
    //   * join the worker thread (this is the UAF-safety check),
    //   * free the success.body if the worker won the race, then
    //   * free the shared heap struct.
    adapter.deinit();
}

test "wasi:http #583 A2: future-response.drop while worker in flight defers slot reuse" {
    // Slot-reuse race regression: if the guest drops the
    // future-incoming-response *while* the worker thread is still
    // mid-fetch, the slot must stay reserved (with the parked
    // FutureIncomingResponse intact) until the drainer can join the
    // worker — otherwise `pushFutureResponse` could reuse the slot
    // for a different future and the worker's completion would
    // settle the wrong resource. (#583 A2)
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    const allow = try testing.allocator.alloc(IpCidr, 1);
    allow[0] = try IpCidr.parse("127.0.0.0/8");
    adapter.sockets_allow_list_template = allow;

    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);

    const req = try testing.allocator.create(OutgoingRequest);
    req.* = .{
        .method_disc = 0,
        .scheme_disc = 0,
        .authority = try testing.allocator.dupe(u8, "127.0.0.1:1"),
        .path_with_query = try testing.allocator.dupe(u8, "/"),
        .headers_handle = fh,
    };
    const rh = try adapter.pushOutgoingRequest(req);

    const args = [_]InterfaceValue{
        .{ .handle = rh },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpOutgoingHandlerHandle(&adapter, &ci, &args, &results, testing.allocator);
    defer results[0].deinit(testing.allocator);
    const fut_handle = results[0].result_val.payload.?.handle;
    try testing.expectEqual(@as(usize, 1), adapter.pending_http_fetches.publishedCount());

    // Guest drops the future before the drainer settles. The public
    // handle disappears immediately, while the operation's retained
    // lease prevents its retired node from being reused.
    const drop_args = [_]InterfaceValue{.{ .handle = fut_handle }};
    var drop_results: [0]InterfaceValue = .{};
    try WasiCliAdapter.httpFutureDrop(&adapter, &ci, &drop_args, &drop_results, testing.allocator);

    try testing.expect(!adapter.http_future_responses.contains(fut_handle));
    try testing.expect(adapter.pending_http_fetches.unsafeGetPtrForTest(0).?.shared.?.cancelled.load(.acquire));

    // Drive the drainer. Once the worker publishes (the fast
    // ECONNREFUSED path), `drainPendingHttpFetches` must both
    // discard the outcome AND null the slot — at which point
    // `pushFutureResponse` is free to reuse it.
    var attempts: usize = 0;
    while (attempts < 10_000 and adapter.pending_http_fetches.publishedCount() > 0) : (attempts += 1) {
        adapter.drainPendingHttpFetches();
        if (adapter.pending_http_fetches.publishedCount() == 0) break;
        const io = std.Io.Threaded.global_single_threaded.io();
        const dur: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
            .clock = .awake,
        };
        dur.sleep(io) catch {};
    }
    try testing.expect(!adapter.http_future_responses.contains(fut_handle));
    try testing.expectEqual(@as(usize, 0), adapter.pending_http_fetches.publishedCount());
}

test "wasi:http #521: opt-in real HTTPS outgoing-handler against example.com" {
    // Real-network smoke test, gated by `-Dnetwork_tests=true`. CI
    // and the default `zig build test` skip this path so the suite
    // does not depend on external connectivity. Enable locally with:
    //   zig build test -Dnetwork_tests=true
    if (!build_options.network_tests) return error.SkipZigTest;

    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    const allow = try testing.allocator.alloc(IpCidr, 1);
    allow[0] = try IpCidr.parse("0.0.0.0/0");
    adapter.sockets_allow_list_template = allow;

    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);

    const req = try testing.allocator.create(OutgoingRequest);
    req.* = .{
        .method_disc = 0, // GET
        .scheme_disc = 1, // https
        .authority = try testing.allocator.dupe(u8, "example.com"),
        .path_with_query = try testing.allocator.dupe(u8, "/"),
        .headers_handle = fh,
    };
    const rh = try adapter.pushOutgoingRequest(req);

    const args = [_]InterfaceValue{
        .{ .handle = rh },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpOutgoingHandlerHandle(&adapter, &ci, &args, &results, testing.allocator);
    defer results[0].deinit(testing.allocator);

    try testing.expect(results[0] == .result_val);
    try testing.expect(results[0].result_val.is_ok);
    const fut_handle = results[0].result_val.payload.?.handle;
    const fut = adapter.http_future_responses.unsafeGetPtrForTest(fut_handle).?.*;
    // (#583 A2) Drive the deferred-completion worker — real network
    // round-trips routinely take 100s of ms.
    p3DrainPendingHttpUntilSettled(&adapter, fut, 30_000);
    try testing.expect(fut.state == .ready_ok);
    const ir = adapter.http_incoming_responses.unsafeGetPtrForTest(fut.state.ready_ok).?.*;
    // example.com canonically returns 200 (or 30x to https itself).
    try testing.expect(ir.status >= 200 and ir.status < 400);
}

test "http #477: http outgoing-handler without allow-list returns HTTP_request_denied (regression)" {
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    // Allow-list intentionally left empty. Build a real `http://`
    // request so we exercise both branches: the empty-allow-list
    // check must trigger before the (passing) scheme check.
    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);

    const req = try testing.allocator.create(OutgoingRequest);
    req.* = .{
        .method_disc = 0,
        .scheme_disc = 0, // http
        .authority = try testing.allocator.dupe(u8, "example.com"),
        .path_with_query = try testing.allocator.dupe(u8, "/"),
        .headers_handle = fh,
    };
    const rh = try adapter.pushOutgoingRequest(req);

    const args = [_]InterfaceValue{
        .{ .handle = rh },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpOutgoingHandlerHandle(&adapter, &ci, &args, &results, testing.allocator);
    defer results[0].deinit(testing.allocator);

    try testing.expect(results[0] == .result_val);
    try testing.expect(results[0].result_val.is_ok);
    const fut_handle = results[0].result_val.payload.?.handle;
    const fut = adapter.http_future_responses.unsafeGetPtrForTest(fut_handle).?.*;
    try testing.expect(fut.state == .ready_err);
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.HTTP_request_denied)),
        fut.state.ready_err,
    );
}

test "http #176: incoming-response.consume transfers body data" {
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    // Manually create an IncomingResponse with body data
    const body_bytes = try testing.allocator.dupe(u8, "response body");
    const resp_fields = try testing.allocator.create(HttpFields);
    resp_fields.* = .{};
    const fh = try adapter.pushHttpFields(resp_fields);

    const ir = try testing.allocator.create(IncomingResponse);
    ir.* = .{ .status = 200, .headers_handle = fh, .body_data = body_bytes };
    const ir_handle = try adapter.pushIncomingResponse(ir);

    // Call consume
    const cons_args = [_]InterfaceValue{.{ .handle = ir_handle }};
    var cons_r: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpIncomingResponseConsume(&adapter, &ci, &cons_args, &cons_r, testing.allocator);
    defer cons_r[0].deinit(testing.allocator);
    try testing.expect(cons_r[0].result_val.is_ok);
    const body_handle = cons_r[0].result_val.payload.?.handle;

    // Get body stream
    const stream_args = [_]InterfaceValue{.{ .handle = body_handle }};
    var stream_r: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpIncomingBodyStream(&adapter, &ci, &stream_args, &stream_r, testing.allocator);
    defer stream_r[0].deinit(testing.allocator);
    try testing.expect(stream_r[0].result_val.is_ok);
    const sh = stream_r[0].result_val.payload.?.handle;

    // Read from the stream
    const is = adapter.input_stream_table.unsafeGetPtrForTest(sh).?;
    var buf: [64]u8 = undefined;
    const read_result = is.stream.read(&buf);
    switch (read_result) {
        .ok => |n| try testing.expectEqualStrings("response body", buf[0..n]),
        else => return error.UnexpectedResult,
    }

    // Second consume should fail
    var cons_r2: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpIncomingResponseConsume(&adapter, &ci, &cons_args, &cons_r2, testing.allocator);
    try testing.expect(!cons_r2[0].result_val.is_ok);
}

