    c_results[0].deinit(std.testing.allocator);
    var n_results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.instanceNetwork(adapter, &ci, &.{}, &n_results, std.testing.allocator);
