test "WasiCliAdapter.cancelAllPendingTimers: aborts in-flight waits with cancel disposition (#551)" {
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = makeBareCiForClocksTest();
    defer freeBareCiForClocksTest(&ci);

    adapter.monotonic_clock_override = 0;

    // Two pending `wait-for` timers — the classic `multi-clock-wait`
    // shape where a task.cancel must reap every outstanding waitable.
    const args1 = [_]InterfaceValue{.{ .u64 = 1_000 }};
    var res1: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.monotonicWaitFor(&adapter, &ci, &args1, &res1, testing.allocator);
    const fh1 = res1[0].handle;
    const args2 = [_]InterfaceValue{.{ .u64 = 2_000 }};
    var res2: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.monotonicWaitFor(&adapter, &ci, &args2, &res2, testing.allocator);
    const fh2 = res2[0].handle;
    try testing.expectEqual(@as(usize, 2), adapter.timer_futures.publishedCount());

    WasiCliAdapter.cancelAllPendingTimers(&adapter, &ci, null, testing.allocator);

    // Both futures are now in the cancel-disposition state, which the
    // executor's `popReadyEvent` translates into
    // `STATUS_STARTED_CANCELLED` for the EVENT_SUBTASK payload.
    try testing.expectEqual(
        @import("async.zig").Future.State.closed,
        ci.futures.getPtr(fh1).?.state,
    );
    try testing.expectEqual(true, ci.futures.getPtr(fh1).?.write_closed);
    try testing.expectEqual(
        @import("async.zig").Future.State.closed,
        ci.futures.getPtr(fh2).?.state,
    );
    try testing.expectEqual(true, ci.futures.getPtr(fh2).?.write_closed);

    // Pending list is drained; subsequent timer-wheel drives are no-ops.
    try testing.expectEqual(@as(usize, 0), adapter.timer_futures.publishedCount());
    try testing.expect(!adapter.completeDueTimerFutures(&ci, testing.allocator));
}

test "WasiCliAdapter.cancelAllPendingAsyncOps: UDP receive cancel mid-pending settles future with cancel sentinel (#583 B1)" {
    // Mirrors the timer-future cancel test but for the
    // `udp-socket.receive` deferred-completion path (#576). A guest
    // that issues `task.cancel` while parked on a `recvfrom` must
    // observe the future settling with the cancel disposition
    // (`STATUS_STARTED_CANCELLED` published to the waitable) instead
    // of waiting forever for a datagram that never arrives.
    if (builtin.os.tag == .windows) return error.SkipZigTest;
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    var ci: ComponentInstance = undefined;
    try ci.enableTestMem(testing.allocator, 4096);
    defer ci.disableTestMem();
    p3TestInitAsyncTables(&ci);
    defer p3TestDeinitAsyncTables(&ci, testing.allocator);

    _ = try p3UdpReceiveTestSetup(&adapter, &ci);

    // Call receive on the receiver — no datagram waiting yet so the
    // future parks on `pending_udp_receives`.
    const args = [_]InterfaceValue{.{ .handle = 1 }};
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.udpReceiveP3(&adapter, &ci, &args, &results, testing.allocator);
    const fh = results[0].handle;
    const fut = ci.futures.getPtr(fh).?;
    try testing.expectEqual(async_mod.Future.State.pending, fut.state);
    try testing.expectEqual(@as(usize, 1), adapter.pending_udp_receives.publishedCount());

    // Wire up a waitable so we can verify the cancel sentinel reaches it.
    const ws_handle = ci.allocAsyncHandle();
    try ci.waitable_sets.put(testing.allocator, ws_handle, .{});
    const ws = ci.waitable_sets.getPtr(ws_handle).?;
    const idx = try ws.register(.{
        .kind = .future_read,
        .handle = fh,
    }, testing.allocator);
    fut.read_waitable = .{ .set_handle = ws_handle, .item_index = idx };

    // Guest issues `canon task.cancel`. The adapter's cancel driver
    // must reap the pending receive.
    WasiCliAdapter.cancelAllPendingAsyncOps(&adapter, &ci, null, testing.allocator);

    // Future is now settled in the cancel disposition.
    try testing.expectEqual(async_mod.Future.State.closed, fut.state);
    try testing.expectEqual(true, fut.write_closed);
    // Waitable carries the wit-bindgen `STATUS_STARTED_CANCELLED`
    // discriminant for the EVENT_SUBTASK pop.
    try testing.expectEqual(@as(usize, 1), ws.items.items.len);
    try testing.expect(ws.items.items[0].ready);
    try testing.expectEqual(executor_root.STATUS_STARTED_CANCELLED, ws.items.items[0].code);
    // Pending entry was reaped — `driveAsyncEvents` will not re-poll
    // the fd looking for a datagram the guest no longer wants.
    try testing.expectEqual(@as(usize, 0), adapter.pending_udp_receives.publishedCount());
}

test "WasiCliAdapter.cancelAllPendingAsyncOps: FS write-via-stream drain loop short-circuits with .err (#583 B1)" {
    // The host-driver `on_write` callback for a
    // `descriptor.write-via-stream` slot must observe the cancel
    // flag flipped by the cancel driver and return `.err` so the
    // executor closes the read end and the guest's next
    // `stream.write` returns DROPPED — no further pwrite(2) syscalls
    // happen after cancel.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    const io = std.Io.Threaded.global_single_threaded.io();
    try tmp.dir.writeFile(io, .{ .sub_path = "p3-cancel-w.txt", .data = "" });
    const file = try tmp.dir.openFile(io, "p3-cancel-w.txt", .{ .mode = .read_write });
    const desc_handle = try adapter.pushFsDescriptor(.{ .file = .{ .file = file, .flags = .{ .read = true, .write = true } } });

    var ci: ComponentInstance = undefined;
    try ci.enableTestMem(testing.allocator, 4096);
    defer ci.disableTestMem();
    p3TestInitAsyncTables(&ci);
    defer p3TestDeinitAsyncTables(&ci, testing.allocator);

    // Seed an empty stream then call write-via-stream so the adapter
    // installs the host_driver.
    const stream_handle = ci.allocAsyncHandle();
    try ci.streams.put(testing.allocator, stream_handle, .{});

    var args = [_]InterfaceValue{
        .{ .handle = desc_handle },
        .{ .handle = stream_handle },
        .{ .u64 = 0 },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.fsDescriptorWriteViaStreamP3(&adapter, &ci, &args, &results, testing.allocator);

    // One ctx was registered — keep a pointer to it for direct
    // invocation of the on_write callback.
    try testing.expectEqual(@as(usize, 1), adapter.fs_write_stream_ctxs.publishedCount());
    const slot = ci.streams.getPtr(stream_handle).?;
    try testing.expect(slot.host_driver != null);

    // First chunk pre-cancel: `on_write` must `pwrite(2)` and return
    // `.progressed`, advancing the running offset.
    var stream_for_cb: async_mod.AsyncStream = .{};
    defer stream_for_cb.deinit(testing.allocator);
    const before = adapter.fs_write_stream_ctxs.unsafeGetPtrForTest(0).?.*.bytes_written;
    const action_ok = slot.host_driver.?.on_write.?(
        slot.host_driver.?.context,
        &stream_for_cb,
        "abc",
        ci.allocator,
    );
    try testing.expectEqual(async_mod.HostStreamAction.progressed, action_ok);
    try testing.expectEqual(before + 3, adapter.fs_write_stream_ctxs.unsafeGetPtrForTest(0).?.*.bytes_written);

    // Cancel — flips the per-ctx flag on every registered FS stream.
    WasiCliAdapter.cancelAllPendingAsyncOps(&adapter, &ci, null, testing.allocator);
    try testing.expect(adapter.fs_write_stream_ctxs.unsafeGetPtrForTest(0).?.*.cancelled.load(.acquire));

    // Post-cancel chunk: drain loop short-circuits with `.err`. The
    // running offset must NOT advance — no further pwrite happened.
    const cancelled_offset = adapter.fs_write_stream_ctxs.unsafeGetPtrForTest(0).?.*.bytes_written;
    const action_cancel = slot.host_driver.?.on_write.?(
        slot.host_driver.?.context,
        &stream_for_cb,
        "xyz",
        ci.allocator,
    );
    try testing.expectEqual(async_mod.HostStreamAction.err, action_cancel);
    try testing.expectEqual(cancelled_offset, adapter.fs_write_stream_ctxs.unsafeGetPtrForTest(0).?.*.bytes_written);

    // File still only contains the pre-cancel chunk.
    var buf: [16]u8 = undefined;
    const n = try file.readPositional(io, &.{&buf}, 0);
    try testing.expectEqualStrings("abc", buf[0..n]);
}

test "WasiCliAdapter.cancelAllPendingAsyncOps: FS read-via-stream on_read short-circuits with .eof after cancel (#583 B1)" {
    // `read-via-stream` pre-buffers the file synchronously and sets
    // `write_closed = true`, so the executor never invokes the
    // host-driver callback in steady state. The cancel hook still
    // matters for the lazy-drain refactor and is verified by direct
    // invocation here: after cancel, `fsReadViaStreamOnRead` must
    // return `.eof` so the executor closes the writable end and the
    // guest's next `stream.read` sees DROPPED with zero bytes
    // transferred.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    const io = std.Io.Threaded.global_single_threaded.io();
    try tmp.dir.writeFile(io, .{ .sub_path = "p3-cancel-r.txt", .data = "cancel-bytes" });
    const file = try tmp.dir.openFile(io, "p3-cancel-r.txt", .{ .mode = .read_only });
    const desc_handle = try adapter.pushFsDescriptor(.{ .file = .{ .file = file, .flags = .{ .read = true } } });

    var ci: ComponentInstance = undefined;
    try ci.enableTestMem(testing.allocator, 4096);
    defer ci.disableTestMem();
    p3TestInitAsyncTables(&ci);
    defer p3TestDeinitAsyncTables(&ci, testing.allocator);

    var args = [_]InterfaceValue{ .{ .handle = desc_handle }, .{ .u64 = 0 } };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.fsDescriptorReadViaStreamP3(&adapter, &ci, &args, &results, testing.allocator);
    defer results[0].deinit(testing.allocator);

    const stream_handle = results[0].tuple_val[0].handle;
    const slot = ci.streams.getPtr(stream_handle).?;

    // Pre-buffer is intact and the cancel-aware host_driver is wired up.
    try testing.expectEqualStrings("cancel-bytes", slot.buffer.items);
    try testing.expect(slot.host_driver != null);
    try testing.expectEqual(@as(usize, 1), adapter.fs_read_stream_ctxs.publishedCount());
    const ctx = adapter.fs_read_stream_ctxs.unsafeGetPtrForTest(0).?.*;
    try testing.expect(!ctx.cancelled.load(.acquire));

    // Snapshot the buffer length so we can prove cancel doesn't
    // mutate it.
    const buffered_before = slot.buffer.items.len;

    // Cancel — flips the per-ctx flag on every registered FS read stream.
    WasiCliAdapter.cancelAllPendingAsyncOps(&adapter, &ci, null, testing.allocator);
    try testing.expect(ctx.cancelled.load(.acquire));

    // Direct invocation of on_read post-cancel: `.eof`, no bytes
    // appended. The pre-buffered FIFO content is untouched.
    var stream_for_cb: async_mod.AsyncStream = .{};
    defer stream_for_cb.deinit(testing.allocator);
    const action = slot.host_driver.?.on_read.?(
        slot.host_driver.?.context,
        &stream_for_cb,
        ci.allocator,
    );
    try testing.expectEqual(async_mod.HostStreamAction.eof, action);
    try testing.expectEqual(@as(usize, 0), stream_for_cb.buffer.items.len);
    try testing.expectEqual(buffered_before, slot.buffer.items.len);
}

test "WasiCliAdapter FS write-via-stream: per-chunk cancel polling within multi-MiB write returns .err with partial bytes persisted (#583, #602 follow-up)" {
    // PR #602 introduced per-64-KiB cancel polling inside the HTTP
    // outbound body-read loop; this test verifies the symmetric
    // pattern on the FS write-via-stream driver. A watcher thread
    // flips `ctx.cancelled` once it observes the running
    // `bytes_written` cross the first chunk boundary; the driver's
    // per-chunk poll then short-circuits with `.err` mid-buffer,
    // leaving the bytes from the chunks that completed before
    // cancel was seen intact on disk (no partial-chunk tear —
    // each chunk's `pwrite(2)` is atomic).
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    const io = std.Io.Threaded.global_single_threaded.io();
    try tmp.dir.writeFile(io, .{ .sub_path = "fs-cancel-midchunk-w.bin", .data = "" });
    const file = try tmp.dir.openFile(io, "fs-cancel-midchunk-w.bin", .{ .mode = .read_write });
    const desc_handle = try adapter.pushFsDescriptor(.{
        .file = .{ .file = file, .flags = .{ .read = true, .write = true } },
    });

    var ci: ComponentInstance = undefined;
    try ci.enableTestMem(testing.allocator, 4096);
    defer ci.disableTestMem();
    p3TestInitAsyncTables(&ci);
    defer p3TestDeinitAsyncTables(&ci, testing.allocator);

    const stream_handle = ci.allocAsyncHandle();
    try ci.streams.put(testing.allocator, stream_handle, .{});

    var args = [_]InterfaceValue{
        .{ .handle = desc_handle },
        .{ .handle = stream_handle },
        .{ .u64 = 0 },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.fsDescriptorWriteViaStreamP3(&adapter, &ci, &args, &results, testing.allocator);

    try testing.expectEqual(@as(usize, 1), adapter.fs_write_stream_ctxs.publishedCount());
    const ctx = adapter.fs_write_stream_ctxs.unsafeGetPtrForTest(0).?.*;
    const slot = ci.streams.getPtr(stream_handle).?;

    // Declared ahead of `WriteWatcher` so the watcher can tell a
    // genuine mid-write observation apart from waking up only after
    // the whole buffer already drained (see `run` below, #866).
    const buf_size: usize = 16 * 1024 * 1024;

    const WriteWatcher = struct {
        ctx_ref: *FsWriteStreamCtx,
        buf_size: usize,
        observed_at: std.atomic.Value(u64) = .{ .raw = 0 },
        fn run(self: *@This()) void {
            var spins: usize = 0;
            // Spin-poll `bytes_written`; flip cancel as soon as we
            // see the running counter cross the first chunk
            // boundary. The spin bound keeps a flaky CI machine
            // (where the write finishes before the watcher
            // schedules) from deadlocking the test — we surface
            // the miss via `observed_at == 0` so the assertions
            // below can `error.SkipZigTest` instead of failing.
            //
            // #866: a slow/loaded CI runner can also descend the
            // *other* way — this thread doesn't get scheduled at
            // all until the writer has already finished the entire
            // buffer, at which point `bytes_written == buf_size`
            // satisfies the naive `seen >= FS_CANCEL_POLL_CHUNK_BYTES`
            // check even though there was never a real mid-write
            // window to interrupt. Treat that the same as "never
            // observed" (leave `observed_at` at 0) rather than
            // flipping `cancelled` after the fact and asserting the
            // driver should have returned `.err` for a write that,
            // from the writer's perspective, already legitimately
            // completed.
            while (spins < 100_000_000) : (spins += 1) {
                const seen = @atomicLoad(u64, &self.ctx_ref.bytes_written, .acquire);
                if (seen >= self.buf_size) return;
                if (seen >= WasiCliAdapter.FS_CANCEL_POLL_CHUNK_BYTES) {
                    self.observed_at.store(seen, .release);
                    self.ctx_ref.cancelled.store(true, .release);
                    return;
                }
                std.atomic.spinLoopHint();
            }
        }
    };
    var watcher_ctx = WriteWatcher{ .ctx_ref = ctx, .buf_size = buf_size };
    const watcher = try std.Thread.spawn(.{}, WriteWatcher.run, .{&watcher_ctx});

    const big_buf = try testing.allocator.alloc(u8, buf_size);
    defer testing.allocator.free(big_buf);
    @memset(big_buf, 'W');

    var stream_for_cb: async_mod.AsyncStream = .{};
    defer stream_for_cb.deinit(testing.allocator);
    const action = slot.host_driver.?.on_write.?(
        slot.host_driver.?.context,
        &stream_for_cb,
        big_buf,
        ci.allocator,
    );
    watcher.join();
    // If the watcher never observed a genuine mid-write boundary
    // crossing — either because the host's pwrite throughput
    // outran a spin-poll thread's wake-up entirely, or (#866)
    // because the watcher only got scheduled after the whole
    // buffer had already drained — skip rather than flake.
    if (watcher_ctx.observed_at.load(.acquire) == 0) return error.SkipZigTest;

    try testing.expectEqual(async_mod.HostStreamAction.err, action);
    const wrote = ctx.bytes_written;
    // At least one chunk fired before cancel was observed.
    try testing.expect(wrote >= WasiCliAdapter.FS_CANCEL_POLL_CHUNK_BYTES);
    // And the driver bailed before the full buffer drained.
    try testing.expect(wrote < buf_size);
    // No partial-chunk tear: the file contains exactly `wrote` bytes.
    const stat = try file.stat(io);
    try testing.expectEqual(wrote, stat.size);
}

test "WasiCliAdapter FS read-via-stream: per-chunk cancel polling within eager pre-buffer caps bytes_read (#583, #602 follow-up)" {
    // Symmetric to the write-side per-chunk cancel test. A watcher
    // thread flips `ctx.cancelled` once `bytes_read` crosses the
    // first chunk boundary; the eager-prebuffer helper observes the
    // flip between `readPositional(2)` chunks and bails. The slot's
    // FIFO ends up shorter than the source file, proving cancel was
    // honoured mid-fill. Drives `fsEagerPreBufferChunked` directly
    // because the ctx pointer is only stable after the trampoline
    // appends it to `fs_read_stream_ctxs` — invoking the helper
    // gives the watcher a stable ctx reference up front.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    // 16 MiB of 'R' so the chunked drain has plenty of iterations
    // for the watcher to catch a boundary.
    const file_size: usize = 16 * 1024 * 1024;
    const seed_buf = try testing.allocator.alloc(u8, file_size);
    defer testing.allocator.free(seed_buf);
    @memset(seed_buf, 'R');

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    const io = std.Io.Threaded.global_single_threaded.io();
    try tmp.dir.writeFile(io, .{ .sub_path = "fs-cancel-midchunk-r.bin", .data = seed_buf });
    const file = try tmp.dir.openFile(io, "fs-cancel-midchunk-r.bin", .{ .mode = .read_only });
    const fs_file: FsDescriptor.FsFile = .{ .file = file, .flags = .{ .read = true } };
    const desc_handle = try adapter.pushFsDescriptor(.{ .file = fs_file });
    _ = desc_handle;

    const ctx = try adapter.allocFsReadStreamCtx(0, 0);
    defer WasiCliAdapter.fsReadStreamCtxOnDestroy(ctx);

    var slot: async_mod.AsyncStream = .{
        .elem_type_idx = 0,
        .elem_size_hint = 1,
        .state = .open,
        .read_closed = false,
        .write_closed = true,
    };
    defer slot.deinit(testing.allocator);

    const scratch = try testing.allocator.alloc(u8, WasiCliAdapter.FS_CANCEL_POLL_CHUNK_BYTES);
    defer testing.allocator.free(scratch);

    const ReadWatcher = struct {
        ctx_ref: *FsReadStreamCtx,
        file_size: usize,
        observed_at: std.atomic.Value(u64) = .{ .raw = 0 },
        fn run(self: *@This()) void {
            var spins: usize = 0;
            // #866: same "watcher wakes up only after the whole
            // read already drained" race as the write-side sibling
            // test above — treat that as unobserved (leave
            // `observed_at` at 0) rather than flipping `cancelled`
            // after the fact and asserting the loop should have
            // bailed early for a read that, from the reader's
            // perspective, already legitimately reached EOF.
            while (spins < 100_000_000) : (spins += 1) {
                const seen = @atomicLoad(u64, &self.ctx_ref.bytes_read, .acquire);
                if (seen >= self.file_size) return;
                if (seen >= WasiCliAdapter.FS_CANCEL_POLL_CHUNK_BYTES) {
                    self.observed_at.store(seen, .release);
                    self.ctx_ref.cancelled.store(true, .release);
                    return;
                }
                std.atomic.spinLoopHint();
            }
        }
    };
    var watcher_ctx = ReadWatcher{ .ctx_ref = ctx, .file_size = file_size };
    const watcher = try std.Thread.spawn(.{}, ReadWatcher.run, .{&watcher_ctx});

    WasiCliAdapter.fsEagerPreBufferChunked(fs_file, ctx, &slot, 0, scratch, testing.allocator);
    watcher.join();

    if (watcher_ctx.observed_at.load(.acquire) == 0) return error.SkipZigTest;

    // Cancel observed: the FIFO holds fewer bytes than the source
    // file. At least one chunk fired (the boundary the watcher saw)
    // and the loop bailed before reaching EOF.
    try testing.expect(slot.buffer.items.len >= WasiCliAdapter.FS_CANCEL_POLL_CHUNK_BYTES);
    try testing.expect(slot.buffer.items.len < file_size);
    // The bytes that did drain are intact: every byte is the seed
    // 'R' — no partial-chunk tear.
    for (slot.buffer.items) |b| try testing.expectEqual(@as(u8, 'R'), b);
}

test "WasiCliAdapter FS write-via-stream: cancel-before-first-chunk skips pwrite(2) entirely (#583, #602 follow-up)" {
    // The per-chunk drain loop's pre-entry check must fire before
    // any pwrite issues: if `task.cancel` was already observed when
    // the driver gets called with a multi-MiB guest buffer, zero
    // bytes hit the disk. Matches PR #593's original cancel
    // semantics while documenting that the chunked refactor
    // preserves the "no syscall on already-cancelled" guarantee.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    const io = std.Io.Threaded.global_single_threaded.io();
    try tmp.dir.writeFile(io, .{ .sub_path = "fs-cancel-prefirst-w.bin", .data = "" });
    const file = try tmp.dir.openFile(io, "fs-cancel-prefirst-w.bin", .{ .mode = .read_write });
    const desc_handle = try adapter.pushFsDescriptor(.{
        .file = .{ .file = file, .flags = .{ .read = true, .write = true } },
    });

    var ci: ComponentInstance = undefined;
    try ci.enableTestMem(testing.allocator, 4096);
    defer ci.disableTestMem();
    p3TestInitAsyncTables(&ci);
    defer p3TestDeinitAsyncTables(&ci, testing.allocator);

    const stream_handle = ci.allocAsyncHandle();
    try ci.streams.put(testing.allocator, stream_handle, .{});

    var args = [_]InterfaceValue{
        .{ .handle = desc_handle },
        .{ .handle = stream_handle },
        .{ .u64 = 0 },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.fsDescriptorWriteViaStreamP3(&adapter, &ci, &args, &results, testing.allocator);

    try testing.expectEqual(@as(usize, 1), adapter.fs_write_stream_ctxs.publishedCount());
    const ctx = adapter.fs_write_stream_ctxs.unsafeGetPtrForTest(0).?.*;
    const slot = ci.streams.getPtr(stream_handle).?;

    // Pre-flip cancel before invoking the driver. The driver must
    // observe the flag on entry and return `.err` without any
    // pwrite(2) — `bytes_written` stays at 0 and the file remains
    // empty on disk.
    ctx.cancelled.store(true, .release);

    const buf_size: usize = 1 * 1024 * 1024;
    const big_buf = try testing.allocator.alloc(u8, buf_size);
    defer testing.allocator.free(big_buf);
    @memset(big_buf, 'X');

    var stream_for_cb: async_mod.AsyncStream = .{};
    defer stream_for_cb.deinit(testing.allocator);
    const action = slot.host_driver.?.on_write.?(
        slot.host_driver.?.context,
        &stream_for_cb,
        big_buf,
        ci.allocator,
    );
    try testing.expectEqual(async_mod.HostStreamAction.err, action);
    try testing.expectEqual(@as(u64, 0), ctx.bytes_written);
    const stat = try file.stat(io);
    try testing.expectEqual(@as(u64, 0), stat.size);
}

test "WasiCliAdapter.cancelAllPendingAsyncOps: outbound HTTP fetch flips shared.cancelled and drainer settles HTTP_request_denied (#583 B1)" {
    // The blocking `std.http.Client.fetch` cannot be interrupted
    // from another thread, but the per-fetch `shared.cancelled`
    // atomic flag IS observed by the drainer
    // (`settlePendingHttpFetch`) once the worker publishes its
    // outcome. The cancel driver flips that flag for every entry on
    // `pending_http_fetches`, so a guest-issued `task.cancel`
    // surfaces as `HTTP_request_denied` regardless of the wire
    // outcome — best-effort, observed at the worker's next
    // synchronisation point.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    // Mint a `.pending` FutureIncomingResponse + a heap-allocated
    // shared block, and register a fake `PendingHttpFetch` entry as
    // if a worker thread were in flight. We use a synthetic worker
    // (a no-op thread that immediately publishes `done`) so the
    // drainer's `thread.join()` returns instantly without invoking
    // the real `std.http.Client.fetch`. Mirrors the unit-test pattern
    // used elsewhere in this module to avoid network dependency.
    const fut = try testing.allocator.create(FutureIncomingResponse);
    fut.* = .{ .state = .pending };
    const fh = try adapter.pushFutureResponse(fut);

    const shared = try adapter.allocator.create(PendingHttpFetchShared);
    shared.* = .{};

    const Worker = struct {
        fn run(s: *PendingHttpFetchShared) void {
            // Simulate worker that's already finished its fetch
            // with a success outcome, so the cancel-vs-success race
            // is observable: cancel must override the success.
            s.outcome = .{ .success = .{ .status = 200, .headers = &.{}, .body = &.{} } };
            s.done.store(true, .release);
        }
    };
    const t = try std.Thread.spawn(.{}, Worker.run, .{shared});
    const future_lease = adapter.http_future_responses.acquire(fh).?;
    _ = try adapter.pending_http_fetches.publish(.{
        .armed = .{ .raw = true },
        .future_handle = fh,
        .thread = t,
        .shared = shared,
        .future_lease = future_lease,
    });

    // Cancel — flips `shared.cancelled` for every pending fetch.
    WasiCliAdapter.cancelAllPendingAsyncOps(&adapter, &ci, null, testing.allocator);
    try testing.expect(adapter.pending_http_fetches.unsafeGetPtrForTest(0).?.shared.?.cancelled.load(.acquire));

    // Drain. The drainer sees `cancelled = true` and overrides the
    // success outcome with `HTTP_request_denied` per the documented
    // cancel arm of `settlePendingHttpFetch`.
    var attempts: usize = 0;
    while (attempts < 10_000 and adapter.pending_http_fetches.publishedCount() > 0) : (attempts += 1) {
        adapter.drainPendingHttpFetches();
        if (adapter.pending_http_fetches.publishedCount() == 0) break;
        const drv_io = std.Io.Threaded.global_single_threaded.io();
        const dur: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
            .clock = .awake,
        };
        dur.sleep(drv_io) catch {};
    }
    try testing.expectEqual(@as(usize, 0), adapter.pending_http_fetches.publishedCount());

    // Future settled to the cancel sentinel (HTTP_request_denied).
    const settled = adapter.http_future_responses.unsafeGetPtrForTest(fh).?.*;
    switch (settled.state) {
        .ready_err => |code| try testing.expectEqual(
            @as(u32, @intFromEnum(HttpErrorCode.HTTP_request_denied)),
            code,
        ),
        else => return error.UnexpectedHttpFutureState,
    }
}

test "wasi:http #616 A1: P3 HTTP cancellation is scoped to ComponentInstance" {
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci_a = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci_a);
    var ci_b = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci_b);

    const Fixture = struct {
        future_handle: u32,
        shared: *PendingHttpFetchShared,

        fn init(
            target_adapter: *WasiCliAdapter,
            target_ci: *ComponentInstance,
            allocator: Allocator,
        ) !@This() {
            const future_handle = target_ci.allocAsyncHandle();
            try target_ci.futures.put(allocator, future_handle, .{
                .elem_type_idx = 0,
                .state = .pending,
            });
            const shared = try target_adapter.allocator.create(PendingHttpFetchShared);
            errdefer target_adapter.allocator.destroy(shared);
            shared.* = .{};
            const Worker = struct {
                fn run(state: *PendingHttpFetchShared) void {
                    state.outcome = .{ .failure = .internal_error };
                    state.done.store(true, .release);
                }
            };
            const thread = try std.Thread.spawn(.{}, Worker.run, .{shared});
            errdefer thread.join();
            _ = try target_adapter.pending_http_fetches_p3.publish(.{
                .armed = .{ .raw = true },
                .future_handle = future_handle,
                .ci = target_ci,
                .thread = thread,
                .shared = shared,
            });
            return .{ .future_handle = future_handle, .shared = shared };
        }
    };

    const fetch_a = try Fixture.init(&adapter, &ci_a, testing.allocator);
    const fetch_b = try Fixture.init(&adapter, &ci_b, testing.allocator);

    WasiCliAdapter.cancelAllPendingAsyncOps(
        &adapter,
        &ci_a,
        null,
        testing.allocator,
    );
    try testing.expect(fetch_a.shared.cancelled.load(.acquire));
    try testing.expect(!fetch_b.shared.cancelled.load(.acquire));

    var attempts: usize = 0;
    while (attempts < 10_000 and adapter.pending_http_fetches_p3.publishedCount() > 0) : (attempts += 1) {
        adapter.drainPendingHttpFetchesP3(&ci_a, testing.allocator);
        adapter.drainPendingHttpFetchesP3(&ci_b, testing.allocator);
        if (adapter.pending_http_fetches_p3.publishedCount() == 0) break;
        const io = std.Io.Threaded.global_single_threaded.io();
        const duration: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = std.time.ns_per_ms },
            .clock = .awake,
        };
        duration.sleep(io) catch {};
    }
    try testing.expectEqual(@as(usize, 0), adapter.pending_http_fetches_p3.publishedCount());

    const decoded_a = decodeP3ClientSendBytes(
        ci_a.futures.getPtr(fetch_a.future_handle).?.payload.?,
    );
    try testing.expect(!decoded_a.is_ok);
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.HTTP_request_denied)),
        decoded_a.payload,
    );
    const decoded_b = decodeP3ClientSendBytes(
        ci_b.futures.getPtr(fetch_b.future_handle).?.payload.?,
    );
    try testing.expect(!decoded_b.is_ok);
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.internal_error)),
        decoded_b.payload,
    );
}

test "wasi:http #616 A7: dropping the readable end cancels the matching P3 fetch" {
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci_a = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci_a);
    var ci_b = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci_b);

    const Fixture = struct {
        future_handle: u32,
        shared: *PendingHttpFetchShared,

        fn init(
            target_adapter: *WasiCliAdapter,
            target_ci: *ComponentInstance,
            allocator: Allocator,
        ) !@This() {
            const future_handle = target_ci.allocAsyncHandle();
            try target_ci.futures.put(allocator, future_handle, .{
                .elem_type_idx = 0,
                .state = .pending,
            });
            const shared = try target_adapter.allocator.create(PendingHttpFetchShared);
            errdefer target_adapter.allocator.destroy(shared);
            shared.* = .{};
            const Worker = struct {
                fn run(state: *PendingHttpFetchShared) void {
                    state.outcome = .{ .failure = .internal_error };
                    state.done.store(true, .release);
                }
            };
            const thread = try std.Thread.spawn(.{}, Worker.run, .{shared});
            errdefer thread.join();
            _ = try target_adapter.pending_http_fetches_p3.publish(.{
                .armed = .{ .raw = true },
                .future_handle = future_handle,
                .ci = target_ci,
                .thread = thread,
                .shared = shared,
            });
            return .{ .future_handle = future_handle, .shared = shared };
        }
    };

    const dropped = try Fixture.init(&adapter, &ci_a, testing.allocator);
    const kept = try Fixture.init(&adapter, &ci_a, testing.allocator);
    const other_ci = try Fixture.init(&adapter, &ci_b, testing.allocator);

    // A P3 guest abandoning a response never issues `task.cancel`; it
    // just drops the readable end. The driver must treat that as a
    // cancel for exactly that fetch — and only that fetch. Getting the
    // scoping wrong here would abort unrelated concurrent requests,
    // including ones owned by a different component instance.
    WasiCliAdapter.cancelPendingHttpFetchForFuture(
        &adapter,
        &ci_a,
        dropped.future_handle,
    );
    try testing.expect(dropped.shared.cancelled.load(.acquire));
    try testing.expect(!kept.shared.cancelled.load(.acquire));
    try testing.expect(!other_ci.shared.cancelled.load(.acquire));

    // A handle that matches numerically but belongs to another
    // instance must not be cancelled either.
    WasiCliAdapter.cancelPendingHttpFetchForFuture(
        &adapter,
        &ci_b,
        kept.future_handle,
    );
    try testing.expect(!kept.shared.cancelled.load(.acquire));

    var attempts: usize = 0;
    while (attempts < 10_000 and adapter.pending_http_fetches_p3.publishedCount() > 0) : (attempts += 1) {
        adapter.drainPendingHttpFetchesP3(&ci_a, testing.allocator);
        adapter.drainPendingHttpFetchesP3(&ci_b, testing.allocator);
        if (adapter.pending_http_fetches_p3.publishedCount() == 0) break;
        const io = std.Io.Threaded.global_single_threaded.io();
        const duration: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = std.time.ns_per_ms },
            .clock = .awake,
        };
        duration.sleep(io) catch {};
    }
    try testing.expectEqual(@as(usize, 0), adapter.pending_http_fetches_p3.publishedCount());

    // The cancelled fetch settles as denied; its neighbour keeps the
    // outcome the worker actually produced.
    const decoded_dropped = decodeP3ClientSendBytes(
        ci_a.futures.getPtr(dropped.future_handle).?.payload.?,
    );
    try testing.expect(!decoded_dropped.is_ok);
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.HTTP_request_denied)),
        decoded_dropped.payload,
    );
    const decoded_kept = decodeP3ClientSendBytes(
        ci_a.futures.getPtr(kept.future_handle).?.payload.?,
    );
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.internal_error)),
        decoded_kept.payload,
    );
}

test "wasi:http #833: in-flight HTTP future exposes a wakeable backend fd (no busy-spin)" {
    // Before #833 the `.http_future_response` pollable had no backend
    // fd, so `waitForBackendEvents` saw zero fds and returned at once →
    // the guest tight-looped `block → get(pending) → block`. With a
    // self-pipe waker, `pollableBackend` now hands `poll()` a real fd
    // that the worker signals on completion, so the host parks instead
    // of spinning.
    if (builtin.os.tag == .windows) return error.SkipZigTest;
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    const fut = try testing.allocator.create(FutureIncomingResponse);
    fut.* = .{ .state = .pending };
    const fh = try adapter.pushFutureResponse(fut);

    const shared = try adapter.allocator.create(PendingHttpFetchShared);
    shared.* = .{};
    shared.waker = try Waker.init();

    // Worker that publishes `done` + signals the waker after a short
    // delay — the exact `httpFetchWorker` completion sequence.
    const Worker = struct {
        fn run(s: *PendingHttpFetchShared) void {
            const w_io = std.Io.Threaded.global_single_threaded.io();
            const d: std.Io.Clock.Duration = .{
                .raw = .{ .nanoseconds = 20 * std.time.ns_per_ms },
                .clock = .awake,
            };
            d.sleep(w_io) catch {};
            s.outcome = .{ .failure = .internal_error };
            s.done.store(true, .release);
            if (s.waker) |w| w.signal();
        }
    };
    const t = try std.Thread.spawn(.{}, Worker.run, .{shared});
    const future_lease = adapter.http_future_responses.acquire(fh).?;
    _ = try adapter.pending_http_fetches.publish(.{
        .armed = .{ .raw = true },
        .future_handle = fh,
        .thread = t,
        .shared = shared,
        .future_lease = future_lease,
    });

    // The future's pollable now reports a backend fd.
    var backend = adapter.pollableBackend(.{ .http_future_response = fh });
    defer if (backend) |*active| active.deinit();
    try testing.expect(backend != null);

    // `poll()` on that fd must block until the worker signals — verify
    // it parks for a meaningful interval rather than returning instantly.
    const ph = try adapter.pushPollable(.{ .http_future_response = fh });
    const handles = [_]u32{ph};
    const start = adapter.monotonicNs();
    const used = try adapter.waitForBackendEvents(&handles, 5_000);
    const elapsed_ns = adapter.monotonicNs() - start;
    try testing.expect(used);
    try testing.expect(elapsed_ns >= 5 * std.time.ns_per_ms);

    // Drain settles the future and closes the waker fds (no leak).
    adapter.drainPendingHttpFetches();
    try testing.expectEqual(@as(usize, 0), adapter.pending_http_fetches.publishedCount());
    const settled = adapter.http_future_responses.unsafeGetPtrForTest(fh).?.*;
    try testing.expect(settled.state != .pending);
}

test "wasi:http #583 B1 follow-up: httpClientLowLevelFetch observes pre-connect cancel without syscall" {
    // Phase-by-phase cancel polling, pre-connect arm. With
    // `cancelled` pre-set, the helper's first synchronisation
    // point (top-of-function `checkHttpCancel`) fires BEFORE
    // `std.http.Client.request` issues any connect/TLS syscall —
    // verified indirectly by passing a non-listening 127.0.0.1
    // address: if the helper had attempted the connect we'd
    // observe `error.ConnectionRefused`. Getting
    // `error.HttpFetchCancelled` instead is the proof of "no
    // syscall issued".
    const testing = std.testing;
    var cancelled: std.atomic.Value(bool) = .{ .raw = true };
    const io = std.Io.Threaded.global_single_threaded.io();

    const result = httpClientLowLevelFetch(
        testing.allocator,
        io,
        "http://127.0.0.1:1/",
        .GET,
        &.{},
        null,
        .{},
        &cancelled,
    );
    try testing.expectError(error.HttpFetchCancelled, result);
}

test "wasi:http #583 B1 follow-up: httpFetchWorker translates Cancelled to HTTP_request_denied (end-to-end)" {
    // Spawn the real worker against an unrouted address with the
    // shared cancel flag pre-flipped. The worker's top-of-function
    // pre-fetch guard catches the cancel; the drainer settles the
    // future with `HTTP_request_denied`. End-to-end coverage of
    // worker → drainer → future-settle pipeline. No network
    // dependency because the helper bails before connect.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    // 127.0.0.0/8 allow-list — irrelevant since we never reach
    // connect, but `spawnHttpFetchPending` doesn't consult it
    // anyway (the deny path is in the `outgoing-handler.handle`
    // surface).
    const fh = try adapter.spawnHttpFetchPending(
        "http://127.0.0.1:1/",
        .GET,
        &.{},
        null,
        .{},
    );
    try testing.expectEqual(@as(usize, 1), adapter.pending_http_fetches.publishedCount());
    // Pre-flip cancel BEFORE the worker has a chance to fail-
    // connect. The worker's pre-fetch guard observes this on its
    // first synchronisation point and publishes
    // `HTTP_request_denied` without invoking the network stack.
    adapter.pending_http_fetches.unsafeGetPtrForTest(0).?.shared.?.cancelled.store(true, .release);

    // Drive the drainer until the worker publishes. The settle
    // path either picks up `cancelled = true` directly (drainer
    // override arm) or the worker has already published
    // `HTTP_request_denied` via the helper's pre-connect bail —
    // both arms emit the same `error-code` to the guest.
    var attempts: usize = 0;
    while (attempts < 10_000 and adapter.pending_http_fetches.publishedCount() > 0) : (attempts += 1) {
        adapter.drainPendingHttpFetches();
        if (adapter.pending_http_fetches.publishedCount() == 0) break;
        const drv_io = std.Io.Threaded.global_single_threaded.io();
        const dur: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
            .clock = .awake,
        };
        dur.sleep(drv_io) catch {};
    }
    try testing.expectEqual(@as(usize, 0), adapter.pending_http_fetches.publishedCount());

    const settled = adapter.http_future_responses.unsafeGetPtrForTest(fh).?.*;
    switch (settled.state) {
        .ready_err => |code| try testing.expectEqual(
            @as(u32, @intFromEnum(HttpErrorCode.HTTP_request_denied)),
            code,
        ),
        else => return error.UnexpectedHttpFutureState,
    }
}

/// Loopback HTTP server with explicit phase signalling used by the
/// #583 B1 follow-up phase-boundary cancel tests. Exposes:
///   * `request_received`: flipped after reading the request head.
///   * `unblock_response`: caller flips this to let the server
///     proceed to writing the response.
///   * `chunk_sent`: flipped after writing the first body chunk
///     (mid-body cancel test only — set to `null` to skip).
///   * `unblock_body`: caller flips this to let the server write
///     the rest of the body (mid-body cancel test only).
const TestHttpPhaseServer = struct {
    thread: std.Thread,
    port: u16,
    ctx: *TestHttpPhaseServerCtx,

    fn serveLoopback(
        allocator: Allocator,
        head: []const u8,
        body_part1: []const u8,
        body_part2: []const u8,
        request_received: *std.atomic.Value(bool),
        unblock_response: *std.atomic.Value(bool),
        chunk_sent: ?*std.atomic.Value(bool),
        unblock_body: ?*std.atomic.Value(bool),
    ) !TestHttpPhaseServer {
        const io = std.Io.Threaded.global_single_threaded.io();
        var any: std.Io.net.IpAddress = .{ .ip4 = .{ .bytes = .{ 127, 0, 0, 1 }, .port = 0 } };
        const server = try std.Io.net.IpAddress.listen(&any, io, .{
            .kernel_backlog = 1,
        });
        const bound = switch (server.socket.address) {
            .ip4 => |v4| v4.port,
            else => {
                var srv_mut = server;
                srv_mut.deinit(io);
                return error.SkipZigTest;
            },
        };
        const head_copy = try allocator.dupe(u8, head);
        errdefer allocator.free(head_copy);
        const body1_copy = try allocator.dupe(u8, body_part1);
        errdefer allocator.free(body1_copy);
        const body2_copy = try allocator.dupe(u8, body_part2);
        errdefer allocator.free(body2_copy);
        const ctx = try allocator.create(TestHttpPhaseServerCtx);
        ctx.* = .{
            .allocator = allocator,
            .server = server,
            .head = head_copy,
            .body_part1 = body1_copy,
            .body_part2 = body2_copy,
            .request_received = request_received,
            .unblock_response = unblock_response,
            .chunk_sent = chunk_sent,
            .unblock_body = unblock_body,
        };
        const t = try std.Thread.spawn(.{}, TestHttpPhaseServerCtx.run, .{ctx});
        return .{ .thread = t, .port = bound, .ctx = ctx };
    }
};

const TestHttpPhaseServerCtx = struct {
    allocator: Allocator,
    server: std.Io.net.Server,
    head: []u8,
    body_part1: []u8,
    body_part2: []u8,
    request_received: *std.atomic.Value(bool),
    unblock_response: *std.atomic.Value(bool),
    chunk_sent: ?*std.atomic.Value(bool),
    unblock_body: ?*std.atomic.Value(bool),

    fn run(self: *TestHttpPhaseServerCtx) void {
        defer {
            self.allocator.free(self.head);
            self.allocator.free(self.body_part1);
            self.allocator.free(self.body_part2);
            const io = std.Io.Threaded.global_single_threaded.io();
            var srv = self.server;
            srv.deinit(io);
            self.allocator.destroy(self);
        }
        const io = std.Io.Threaded.global_single_threaded.io();
        const stream = self.server.accept(io) catch return;
        defer stream.close(io);

        // Drain request head.
        var req_buf: [4096]u8 = undefined;
        var total: usize = 0;
        while (total < req_buf.len) {
            var dests = [_][]u8{req_buf[total..]};
            const n = io.vtable.netRead(io.userdata, stream.socket.handle, &dests) catch return;
            if (n == 0) break;
            total += n;
            if (std.mem.indexOf(u8, req_buf[0..total], "\r\n\r\n") != null) break;
        }
        // Signal: request fully received.
        self.request_received.store(true, .release);

        // Block until the test thread says "go". Polled at 1ms
        // intervals — the test thread flips cancel before
        // signalling so the helper's next phase-check observes
        // it whenever the helper is unblocked.
        while (!self.unblock_response.load(.acquire)) {
            const dur: std.Io.Clock.Duration = .{
                .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
                .clock = .awake,
            };
            dur.sleep(io) catch {};
        }

        const head_slices = [_][]const u8{self.head};
        _ = io.vtable.netWrite(io.userdata, stream.socket.handle, &.{}, &head_slices, 1) catch return;
        if (self.body_part1.len > 0) {
            const body_slices = [_][]const u8{self.body_part1};
            _ = io.vtable.netWrite(io.userdata, stream.socket.handle, &.{}, &body_slices, 1) catch return;
        }

        // Mid-body cancel test only: signal that the first chunk
        // has been sent, then block until the test thread says
        // "send the rest". The mid-body test never sets
        // `unblock_body`, so the server effectively hangs —
        // intentional, because the helper bails out at the next
        // cancel-check before reading more bytes.
        if (self.chunk_sent) |ev| ev.store(true, .release);
        if (self.unblock_body) |ev| {
            while (!ev.load(.acquire)) {
                const dur: std.Io.Clock.Duration = .{
                    .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
                    .clock = .awake,
                };
                dur.sleep(io) catch {};
            }
            if (self.body_part2.len > 0) {
                const body_slices = [_][]const u8{self.body_part2};
                _ = io.vtable.netWrite(io.userdata, stream.socket.handle, &.{}, &body_slices, 1) catch return;
            }
        }
    }
};

/// Worker-thread harness invoked by the #583 B1 follow-up tests:
/// drives `httpClientLowLevelFetch` to completion against a caller-
/// supplied URL, writes the resulting status / `error.HttpFetchCancelled`
/// flag into the supplied out-params. Keeps the test thread free to
/// flip `cancelled` mid-fetch and observe the helper's response.
const TestHttpFetchWorkerCtx = struct {
    allocator: Allocator,
    url: []const u8,
    cancelled: *std.atomic.Value(bool),
    out_was_cancelled: *std.atomic.Value(bool),
    out_done: *std.atomic.Value(bool),

    fn run(self: *TestHttpFetchWorkerCtx) void {
        const io = std.Io.Threaded.global_single_threaded.io();
        const result = httpClientLowLevelFetch(
            self.allocator,
            io,
            self.url,
            .GET,
            &.{},
            null,
            .{},
            self.cancelled,
        );
        if (result) |r| {
            self.allocator.free(r.body);
            freeOwnedHttpHeaders(self.allocator, r.headers);
        } else |err| {
            if (err == error.HttpFetchCancelled) {
                self.out_was_cancelled.store(true, .release);
            }
        }
        self.out_done.store(true, .release);
    }
};

test "wasi:http #583 B1 follow-up: httpClientLowLevelFetch observes cancel between send-head and receive-head (#583)" {
    // Phase-boundary cancel test. Server accepts + reads the
    // request head, then blocks until the test thread says
    // "respond". The test thread flips cancel BEFORE unblocking
    // the server, so by the time the helper has connected and
    // sent the request head, the cancel flag is already set
    // when its pre-receive-head (and any subsequent) sync point
    // is reached. The helper bails with
    // `error.HttpFetchCancelled` and `errdefer` chains in the
    // helper release any partial-state allocations — verified
    // by `testing.allocator`'s leak detector.
    if (!build_options.network_tests) return error.SkipZigTest;
    const testing = std.testing;

    var request_received: std.atomic.Value(bool) = .{ .raw = false };
    var unblock_response: std.atomic.Value(bool) = .{ .raw = false };
    var server = TestHttpPhaseServer.serveLoopback(
        testing.allocator,
        "HTTP/1.1 200 OK\r\nContent-Length: 5\r\nConnection: close\r\n\r\n",
        "hello",
        "",
        &request_received,
        &unblock_response,
        null,
        null,
    ) catch return error.SkipZigTest;

    const url = try std.fmt.allocPrint(testing.allocator, "http://127.0.0.1:{d}/", .{server.port});
    defer testing.allocator.free(url);

    var cancelled: std.atomic.Value(bool) = .{ .raw = false };
    var was_cancelled: std.atomic.Value(bool) = .{ .raw = false };
    var done: std.atomic.Value(bool) = .{ .raw = false };
    const worker_ctx = try testing.allocator.create(TestHttpFetchWorkerCtx);
    defer testing.allocator.destroy(worker_ctx);
    worker_ctx.* = .{
        .allocator = testing.allocator,
        .url = url,
        .cancelled = &cancelled,
        .out_was_cancelled = &was_cancelled,
        .out_done = &done,
    };
    const worker_thread = try std.Thread.spawn(.{}, TestHttpFetchWorkerCtx.run, .{worker_ctx});

    // Wait for the server to acknowledge that the request head
    // has been received — at this point the helper is past
    // `client.request(...)` + `sendBodiless()` and headed for
    // (or already inside) `receiveHead(...)`.
    const drv_io = std.Io.Threaded.global_single_threaded.io();
    var spin: usize = 0;
    while (spin < 10_000 and !request_received.load(.acquire)) : (spin += 1) {
        const dur: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
            .clock = .awake,
        };
        dur.sleep(drv_io) catch {};
    }
    try testing.expect(request_received.load(.acquire));

    // Flip cancel BEFORE letting the server respond.
    cancelled.store(true, .release);
    // Unblock the server so the helper's `receiveHead` returns —
    // its pre-body-read cancel check then observes the flag.
    unblock_response.store(true, .release);

    worker_thread.join();
    server.thread.join();

    try testing.expect(done.load(.acquire));
    try testing.expect(was_cancelled.load(.acquire));
}

test "wasi:http #583 B1 follow-up: httpClientLowLevelFetch observes cancel mid-body-read at chunk boundary (#583)" {
    // Mid-body cancel test. Server sends the response head plus a
    // first 32 KiB body chunk (well under the helper's 64 KiB
    // `http_cancel_body_chunk_bytes`), signals `chunk_sent`, and
    // then blocks waiting for `unblock_body`. The test thread
    // flips cancel AND releases `unblock_body` so the server
    // proceeds to send the remainder of `Content-Length` worth of
    // bytes: any helper that was blocked in
    // `body_reader.stream(...)` waiting for more data unblocks,
    // reads, and hits its next per-chunk cancel check —
    // observing `cancelled = true` and bailing with
    // `error.HttpFetchCancelled`. Partial body bytes accumulated
    // in `aw` are released by the helper's errdefer chain;
    // `testing.allocator`'s leak detector catches any regression.
    if (!build_options.network_tests) return error.SkipZigTest;
    const testing = std.testing;

    // Body framed by Content-Length. First chunk is 32 KiB so
    // helper iter 1 reads a single sub-chunk-limit pump. The
    // remaining 96 KiB forces helper to keep iterating past
    // chunk 1 — and lets the per-chunk cancel check at iter 2
    // (or iter 3 if helper raced past iter 2) fire deterministically.
    const part1_len: usize = 32 * 1024;
    const part2_len: usize = 96 * 1024;
    const total_len: usize = part1_len + part2_len;
    const part1 = try testing.allocator.alloc(u8, part1_len);
    defer testing.allocator.free(part1);
    @memset(part1, 'A');
    const part2 = try testing.allocator.alloc(u8, part2_len);
    defer testing.allocator.free(part2);
    @memset(part2, 'B');

    var head_buf: [128]u8 = undefined;
    const head = try std.fmt.bufPrint(
        &head_buf,
        "HTTP/1.1 200 OK\r\nContent-Length: {d}\r\nConnection: close\r\n\r\n",
        .{total_len},
    );

    var request_received: std.atomic.Value(bool) = .{ .raw = false };
    var unblock_response: std.atomic.Value(bool) = .{ .raw = false };
    var chunk_sent: std.atomic.Value(bool) = .{ .raw = false };
    var unblock_body: std.atomic.Value(bool) = .{ .raw = false };

    var server = TestHttpPhaseServer.serveLoopback(
        testing.allocator,
        head,
        part1,
        part2,
        &request_received,
        &unblock_response,
        &chunk_sent,
        &unblock_body,
    ) catch return error.SkipZigTest;

    const url = try std.fmt.allocPrint(testing.allocator, "http://127.0.0.1:{d}/", .{server.port});
    defer testing.allocator.free(url);

    var cancelled: std.atomic.Value(bool) = .{ .raw = false };
    var was_cancelled: std.atomic.Value(bool) = .{ .raw = false };
    var done: std.atomic.Value(bool) = .{ .raw = false };
    const worker_ctx = try testing.allocator.create(TestHttpFetchWorkerCtx);
    defer testing.allocator.destroy(worker_ctx);
    worker_ctx.* = .{
        .allocator = testing.allocator,
        .url = url,
        .cancelled = &cancelled,
        .out_was_cancelled = &was_cancelled,
        .out_done = &done,
    };
    const worker_thread = try std.Thread.spawn(.{}, TestHttpFetchWorkerCtx.run, .{worker_ctx});

    // Wait for the server to acknowledge request received, then
    // release the response head + first body chunk.
    const drv_io = std.Io.Threaded.global_single_threaded.io();
    var spin: usize = 0;
    while (spin < 10_000 and !request_received.load(.acquire)) : (spin += 1) {
        const dur: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
            .clock = .awake,
        };
        dur.sleep(drv_io) catch {};
    }
    try testing.expect(request_received.load(.acquire));
    unblock_response.store(true, .release);

    // Wait until the server has sent the first body chunk —
    // the helper is now either mid-iteration on chunk 1 or
    // about to enter its iteration 2 cancel check.
    spin = 0;
    while (spin < 10_000 and !chunk_sent.load(.acquire)) : (spin += 1) {
        const dur: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
            .clock = .awake,
        };
        dur.sleep(drv_io) catch {};
    }
    try testing.expect(chunk_sent.load(.acquire));

    // Flip cancel AND signal the server to send the rest of
    // the body. Doing both atomically avoids a deadlock: if the
    // helper has already iterated past the first chunk and is
    // blocked in `body_reader.stream(...)` waiting for more
    // bytes, releasing `unblock_body` lets it unblock and reach
    // its next per-chunk cancel check (which observes the flag
    // and bails). If the helper hasn't iterated yet, the iter-2
    // check fires immediately on its first loop-back.
    cancelled.store(true, .release);
    unblock_body.store(true, .release);

    worker_thread.join();
    server.thread.join();
    try testing.expect(done.load(.acquire));
    try testing.expect(was_cancelled.load(.acquire));
}

/// Synthetic response-phase operation used by the #616 A1 deadline
/// tests: sleeps for `ns` and then reports the sentinel. Racing this
/// against a shorter budget exercises exactly the machinery
/// `receiveHead` and the body-chunk reads go through, without needing
/// a socket.
fn testHttpSlowOp(io: std.Io, ns: u64, sentinel: usize) error{Canceled}!usize {
    const dur: std.Io.Clock.Duration = .{
        .raw = .{ .nanoseconds = @as(i96, ns) },
        .clock = .awake,
    };
    try dur.sleep(io);
    return sentinel;
}

test "wasi:http #616 A7: an in-flight operation is interrupted by the cancel flag" {
    const testing = std.testing;
    var threaded: std.Io.Threaded = .init(testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();

    // The heart of A7. Before this change `cancelled` was only read at
    // phase boundaries, so an operation that had already blocked ran to
    // completion regardless. Here the operation would take a minute; the
    // flag is already set, so the cancel lane must win essentially
    // immediately and the syscall must be torn down rather than waited
    // out.
    // The generous 10 s budget is a failure detector, not part of the
    // behaviour under test: if the cancel lane did not fire, this call
    // would fail with `HttpResponseTimeout` after ten seconds instead
    // of hanging on the operation's own minute-long sleep.
    var cancelled: std.atomic.Value(bool) = .init(true);
    const result = httpRunWithOptionalDeadline(
        testHttpSlowOp,
        io,
        .{ .duration = .{ .raw = .{ .nanoseconds = 10 * std.time.ns_per_s }, .clock = .awake } },
        &cancelled,
        .{ io, 60 * std.time.ns_per_s, 0xD4 },
    );

    try testing.expectError(error.HttpFetchCancelled, result);
    // The guest-visible mapping is unchanged: a cancelled fetch is
    // still reported as a denied request.
    try testing.expectEqual(
        HttpErrorCode.HTTP_request_denied,
        mapHttpFetchError(error.HttpFetchCancelled),
    );
}

test "wasi:http #616 A7: a cancel raised while the operation is blocked still wins" {
    const testing = std.testing;
    var threaded: std.Io.Threaded = .init(testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();

    // Same as above but the flag is raised *after* the operation has
    // already parked, which is the real-world ordering: the worker
    // blocks first, the guest cancels later. This is precisely the case
    // the old advisory polling could not handle.
    var cancelled: std.atomic.Value(bool) = .init(false);
    const Raiser = struct {
        fn run(flag: *std.atomic.Value(bool)) void {
            const raiser_io = std.Io.Threaded.global_single_threaded.io();
            const delay: std.Io.Clock.Duration = .{
                .raw = .{ .nanoseconds = 20 * std.time.ns_per_ms },
                .clock = .awake,
            };
            delay.sleep(raiser_io) catch {};
            flag.store(true, .release);
        }
    };
    var raiser = try std.Thread.spawn(.{}, Raiser.run, .{&cancelled});
    defer raiser.join();

    // As above, the 10 s budget bounds the failure mode: a cancel lane
    // that never wakes shows up as `HttpResponseTimeout`.
    const result = httpRunWithOptionalDeadline(
        testHttpSlowOp,
        io,
        .{ .duration = .{ .raw = .{ .nanoseconds = 10 * std.time.ns_per_s }, .clock = .awake } },
        &cancelled,
        .{ io, 60 * std.time.ns_per_s, 0xD5 },
    );

    try testing.expectError(error.HttpFetchCancelled, result);
}

test "wasi:http #616 A7: an unset cancel flag leaves the operation's result intact" {
    const testing = std.testing;
    var threaded: std.Io.Threaded = .init(testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();

    // The cancel lane must be transparent when it does not fire: it is
    // armed on every guarded call in the request path, so a leaky lane
    // would corrupt every ordinary request.
    var cancelled: std.atomic.Value(bool) = .init(false);
    const got = try httpRunWithOptionalDeadline(
        testHttpSlowOp,
        io,
        .none,
        &cancelled,
        .{ io, 1 * std.time.ns_per_ms, 0xD6 },
    );
    try testing.expectEqual(@as(usize, 0xD6), got);
}

test "wasi:http #616 A7: the deadline still wins when it expires before any cancel" {
    const testing = std.testing;
    var threaded: std.Io.Threaded = .init(testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();

    // Three-lane race: with both a budget and a cancel flag armed, the
    // budget must keep its #616 A1 semantics and report a timeout, not
    // be masked by the newly-added lane.
    var cancelled: std.atomic.Value(bool) = .init(false);
    const result = httpRunWithOptionalDeadline(
        testHttpSlowOp,
        io,
        .{ .duration = .{ .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms }, .clock = .awake } },
        &cancelled,
        .{ io, 60 * std.time.ns_per_s, 0xD7 },
    );
    try testing.expectError(error.HttpResponseTimeout, result);
}

test "wasi:http #616 A1: request-options snapshot carries all three transport timeouts" {
    const testing = std.testing;

    // An absent `request-options` leaves every budget unset so the
    // zero-configuration path keeps running operations inline.
    const unset = HttpFetchOptions.fromRequestOptions(null);
    try testing.expectEqual(@as(?u64, null), unset.connect_timeout_ns);
    try testing.expectEqual(@as(?u64, null), unset.first_byte_timeout_ns);
    try testing.expectEqual(@as(?u64, null), unset.between_bytes_timeout_ns);
    try testing.expect(unset.connectTimeout() == .none);
    try testing.expect(unset.firstByteTimeout() == .none);
    try testing.expect(unset.betweenBytesTimeout() == .none);

    // Before #616 A1 the snapshot dropped `first-byte` and
    // `between-bytes` on the floor, so the response phase ran
    // unbounded no matter what the guest configured.
    const opts: RequestOptions = .{
        .connect_timeout_ns = 1,
        .first_byte_timeout_ns = 2,
        .between_bytes_timeout_ns = 3,
    };
    const snapshot = HttpFetchOptions.fromRequestOptions(&opts);
    try testing.expectEqual(@as(?u64, 1), snapshot.connect_timeout_ns);
    try testing.expectEqual(@as(?u64, 2), snapshot.first_byte_timeout_ns);
    try testing.expectEqual(@as(?u64, 3), snapshot.between_bytes_timeout_ns);

    // `Io.Duration.nanoseconds` is i96, so the whole u64 WIT domain
    // round-trips without narrowing.
    const max_ns: u64 = std.math.maxInt(u64);
    const saturated = HttpFetchOptions{
        .first_byte_timeout_ns = max_ns,
        .between_bytes_timeout_ns = max_ns,
    };
    switch (saturated.firstByteTimeout()) {
        .duration => |d| try testing.expectEqual(@as(i96, max_ns), d.raw.nanoseconds),
        else => return error.TestUnexpectedResult,
    }
    switch (saturated.betweenBytesTimeout()) {
        .duration => |d| try testing.expectEqual(@as(i96, max_ns), d.raw.nanoseconds),
        else => return error.TestUnexpectedResult,
    }
}

test "wasi:http #616 A1: response-phase expiry maps to HTTP-response-timeout, not connection-timeout" {
    const testing = std.testing;

    // `error.Timeout` still means "the connect budget expired", so it
    // must keep its `connection-timeout` mapping.
    try testing.expectEqual(HttpErrorCode.connection_timeout, mapHttpFetchError(error.Timeout));

    // A `first-byte` / `between-bytes` expiry happens on a connection
    // that was established successfully, so reporting it as a
    // connection timeout would misattribute the failure.
    try testing.expectEqual(
        HttpErrorCode.HTTP_response_timeout,
        mapHttpFetchError(error.HttpResponseTimeout),
    );
}

test "wasi:http #616 A1: unset budget runs the operation inline and returns its value" {
    const testing = std.testing;
    var threaded: std.Io.Threaded = .init(testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();

    // `.none` must not spawn a racing timer: an unconfigured guest
    // keeps the exact cost it had before #616 A1.
    const got = try httpRunWithOptionalDeadline(
        testHttpSlowOp,
        io,
        .none,
        null,
        .{ io, 0, 0xA1 },
    );
    try testing.expectEqual(@as(usize, 0xA1), got);
}

test "wasi:http #616 A1: an operation finishing inside its budget keeps its result" {
    const testing = std.testing;
    var threaded: std.Io.Threaded = .init(testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();

    // Generous budget versus an immediate operation: the raced path
    // must be transparent when the deadline is not hit, otherwise
    // every bounded read would corrupt its own result.
    const got = try httpRunWithOptionalDeadline(
        testHttpSlowOp,
        io,
        .{ .duration = .{ .raw = .{ .nanoseconds = 30 * std.time.ns_per_s }, .clock = .awake } },
        null,
        .{ io, 0, 0xB2 },
    );
    try testing.expectEqual(@as(usize, 0xB2), got);
}

test "wasi:http #616 A1: an operation exceeding its budget fails with HttpResponseTimeout" {
    const testing = std.testing;
    var threaded: std.Io.Threaded = .init(testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();

    // This is the shape of a server that accepts the connection and
    // then never sends a response head (or stalls mid-body). Before
    // #616 A1 the adapter waited forever; now the budget wins and the
    // guest gets `HTTP_response_timeout`.
    const result = httpRunWithOptionalDeadline(
        testHttpSlowOp,
        io,
        .{ .duration = .{ .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms }, .clock = .awake } },
        null,
        .{ io, 60 * std.time.ns_per_s, 0xC3 },
    );
    try testing.expectError(error.HttpResponseTimeout, result);
    if (result) |_| {
        return error.TestUnexpectedResult;
    } else |err| {
        try testing.expectEqual(HttpErrorCode.HTTP_response_timeout, mapHttpFetchError(err));
    }
}

test "wasi:http #616 A1: each raced call re-arms its budget so progress resets the window" {
    const testing = std.testing;
    var threaded: std.Io.Threaded = .init(testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();

    // `between-bytes-timeout` is "time without progress", not a
    // whole-body allowance. The body loop therefore arms a fresh timer
    // per chunk; several chunks in a row must all succeed even though
    // their combined duration exceeds one chunk's budget.
    const budget: std.Io.Timeout = .{
        .duration = .{ .raw = .{ .nanoseconds = 5 * std.time.ns_per_s }, .clock = .awake },
    };
    var chunk: usize = 0;
    while (chunk < 4) : (chunk += 1) {
        const got = try httpRunWithOptionalDeadline(
            testHttpSlowOp,
            io,
            budget,
            null,
            .{ io, 1 * std.time.ns_per_ms, chunk },
        );
        try testing.expectEqual(chunk, got);
    }
}

test "wasi:http #616 A1: redirect method rewrite matches RFC 9110" {
    const testing = std.testing;

    // 303 always downgrades to GET.
    try testing.expectEqual(std.http.Method.GET, httpRedirectMethod(.see_other, .POST));
    try testing.expectEqual(std.http.Method.GET, httpRedirectMethod(.see_other, .PUT));

    // 301 / 302 downgrade only POST; every other method is preserved.
    try testing.expectEqual(std.http.Method.GET, httpRedirectMethod(.moved_permanently, .POST));
    try testing.expectEqual(std.http.Method.GET, httpRedirectMethod(.found, .POST));
    try testing.expectEqual(std.http.Method.PUT, httpRedirectMethod(.found, .PUT));
    try testing.expectEqual(std.http.Method.HEAD, httpRedirectMethod(.moved_permanently, .HEAD));

    // 307 / 308 exist precisely to preserve the method.
    try testing.expectEqual(
        std.http.Method.POST,
        httpRedirectMethod(.temporary_redirect, .POST),
    );
    try testing.expectEqual(
        std.http.Method.POST,
        httpRedirectMethod(.permanent_redirect, .POST),
    );

    // The adapter's hop budget must stay equal to the
    // `RedirectBehavior.init(3)` budget it replaced, so guest-visible
    // redirect behavior did not change when the loop moved in-tree.
    try testing.expectEqual(@as(u16, 3), http_max_redirect_hops);
}

/// Loopback server for the #616 A1 redirect tests. Serves
/// `connections` sequential requests: the first `redirects` of them
/// answer with a 3xx carrying a `Location` (and a body, so the test
/// also covers the adapter refusing to drain a redirect body), and any
/// remaining request answers 200. Each hop's request line is recorded
/// so the test can assert the loop actually walked the chain.
const TestHttpRedirectServerCtx = struct {
    const max_hops = 8;
    const line_capacity = 128;

    allocator: Allocator,
    server: std.Io.net.Server,
    redirects: u32,
    redirect_status: []const u8,
    connections: u32,
    request_lines: [max_hops][line_capacity]u8 = undefined,
    request_line_lens: [max_hops]usize = @splat(0),
    served: u32 = 0,

    fn run(self: *TestHttpRedirectServerCtx) void {
        const io = std.Io.Threaded.global_single_threaded.io();
        defer {
            var srv = self.server;
            srv.deinit(io);
        }

        var hop: u32 = 0;
        while (hop < self.connections) : (hop += 1) {
            const stream = self.server.accept(io) catch return;
            defer stream.close(io);

            var req_buf: [4096]u8 = undefined;
            var total: usize = 0;
            while (total < req_buf.len) {
                var dests = [_][]u8{req_buf[total..]};
                const n = io.vtable.netRead(io.userdata, stream.socket.handle, &dests) catch break;
                if (n == 0) break;
                total += n;
                if (std.mem.indexOf(u8, req_buf[0..total], "\r\n\r\n") != null) break;
            }

            if (hop < max_hops) {
                const eol = std.mem.indexOf(u8, req_buf[0..total], "\r\n") orelse total;
                const len = @min(eol, line_capacity);
                @memcpy(self.request_lines[hop][0..len], req_buf[0..len]);
                self.request_line_lens[hop] = len;
            }
            self.served = hop + 1;

            var head_buf: [256]u8 = undefined;
            const response = if (hop < self.redirects)
                std.fmt.bufPrint(
                    &head_buf,
                    "HTTP/1.1 {s}\r\nLocation: /hop{d}\r\nContent-Length: 4\r\n" ++
                        "Connection: close\r\n\r\nskip",
                    .{ self.redirect_status, hop + 1 },
                ) catch return
            else
                std.fmt.bufPrint(
                    &head_buf,
                    "HTTP/1.1 200 OK\r\nContent-Length: 5\r\nConnection: close\r\n\r\nfinal",
                    .{},
                ) catch return;

            const slices = [_][]const u8{response};
            _ = io.vtable.netWrite(io.userdata, stream.socket.handle, &.{}, &slices, 1) catch return;
        }
    }
};

const TestHttpRedirectServer = struct {
    thread: std.Thread,
    port: u16,
    ctx: *TestHttpRedirectServerCtx,

    fn serveLoopback(
        allocator: Allocator,
        redirects: u32,
        redirect_status: []const u8,
        connections: u32,
    ) !TestHttpRedirectServer {
        const io = std.Io.Threaded.global_single_threaded.io();
        var any: std.Io.net.IpAddress = .{ .ip4 = .{ .bytes = .{ 127, 0, 0, 1 }, .port = 0 } };
        const server = try std.Io.net.IpAddress.listen(&any, io, .{ .kernel_backlog = 4 });
        const bound = switch (server.socket.address) {
            .ip4 => |v4| v4.port,
            else => {
                var srv_mut = server;
                srv_mut.deinit(io);
                return error.SkipZigTest;
            },
        };
        const ctx = try allocator.create(TestHttpRedirectServerCtx);
        errdefer allocator.destroy(ctx);
        ctx.* = .{
            .allocator = allocator,
            .server = server,
            .redirects = redirects,
            .redirect_status = redirect_status,
            .connections = connections,
        };
        const t = try std.Thread.spawn(.{}, TestHttpRedirectServerCtx.run, .{ctx});
        return .{ .thread = t, .port = bound, .ctx = ctx };
    }

    fn requestLine(self: *const TestHttpRedirectServer, hop: usize) []const u8 {
        return self.ctx.request_lines[hop][0..self.ctx.request_line_lens[hop]];
    }
};

test "wasi:http #616 A1: adapter-owned redirect loop walks each hop under its own connect budget" {
    // The adapter now follows redirects itself so every hop is
    // acquired through `httpClientConnectWithTimeout`. Previously
    // `Request.receiveHead` reconnected via the untimed
    // `Client.connect`, leaving hops 2..n outside `connect-timeout`
    // entirely. A non-zero connect budget is set here so the test
    // fails if any hop ever bypasses the timed connector.
    if (!build_options.network_tests) return error.SkipZigTest;
    const testing = std.testing;

    var server = TestHttpRedirectServer.serveLoopback(
        testing.allocator,
        2,
        "302 Found",
        3,
    ) catch return error.SkipZigTest;
    defer testing.allocator.destroy(server.ctx);
    defer server.thread.join();

    const url = try std.fmt.allocPrint(testing.allocator, "http://127.0.0.1:{d}/start", .{server.port});
    defer testing.allocator.free(url);

    // Deadline enforcement needs a backend that can race and cancel
    // syscalls, which is why the adapter keeps its own
    // `http_worker_io` instead of the single-threaded global.
    var worker_io: std.Io.Threaded = .init(testing.allocator, .{});
    defer worker_io.deinit();
    const io = worker_io.io();

    const result = try httpClientLowLevelFetch(
        testing.allocator,
        io,
        url,
        .GET,
        &.{},
        null,
        .{ .connect_timeout_ns = 30 * std.time.ns_per_s },
        null,
    );
    defer testing.allocator.free(result.body);
    defer freeOwnedHttpHeaders(testing.allocator, result.headers);

    try testing.expectEqual(@as(u16, 200), result.status);
    try testing.expectEqualStrings("final", result.body);

    // Three connections: the original request plus one per followed
    // hop, each targeting the resolved relative `Location`.
    try testing.expectEqual(@as(u32, 3), server.ctx.served);
    try testing.expectEqualStrings("GET /start HTTP/1.1", server.requestLine(0));
    try testing.expectEqualStrings("GET /hop1 HTTP/1.1", server.requestLine(1));
    try testing.expectEqualStrings("GET /hop2 HTTP/1.1", server.requestLine(2));
}

test "wasi:http #616 A1: redirect hop budget still matches the replaced stdlib behavior" {
    // `RedirectBehavior.init(3)` followed three hops and failed the
    // fourth with `error.TooManyHttpRedirects`. Moving the loop in-tree
    // must not have changed that guest-visible contract.
    if (!build_options.network_tests) return error.SkipZigTest;
    const testing = std.testing;

    // Always redirect; the client is expected to give up after four
    // connections (initial request + three follows).
    var server = TestHttpRedirectServer.serveLoopback(
        testing.allocator,
        100,
        "302 Found",
        4,
    ) catch return error.SkipZigTest;
    defer testing.allocator.destroy(server.ctx);
    defer server.thread.join();

    const url = try std.fmt.allocPrint(testing.allocator, "http://127.0.0.1:{d}/start", .{server.port});
    defer testing.allocator.free(url);

    var worker_io: std.Io.Threaded = .init(testing.allocator, .{});
    defer worker_io.deinit();

    const result = httpClientLowLevelFetch(
        testing.allocator,
        worker_io.io(),
        url,
        .GET,
        &.{},
        null,
        .{},
        null,
    );
    try testing.expectError(error.TooManyHttpRedirects, result);
}

test "wasi:http #616 A1: a stalled response head expires against first-byte-timeout" {
    // Server accepts the connection and reads the request, then never
    // sends a response head. Before #616 A1 the adapter blocked here
    // forever regardless of `request-options`; now the per-hop
    // `first-byte-timeout` fires and maps to `HTTP_response_timeout`.
    if (!build_options.network_tests) return error.SkipZigTest;
    const testing = std.testing;

    var request_received: std.atomic.Value(bool) = .{ .raw = false };
    var unblock_response: std.atomic.Value(bool) = .{ .raw = false };
    var server = TestHttpPhaseServer.serveLoopback(
        testing.allocator,
        "HTTP/1.1 200 OK\r\nContent-Length: 5\r\nConnection: close\r\n\r\n",
        "hello",
        "",
        &request_received,
        &unblock_response,
        null,
        null,
    ) catch return error.SkipZigTest;

    const url = try std.fmt.allocPrint(testing.allocator, "http://127.0.0.1:{d}/", .{server.port});
    defer testing.allocator.free(url);

    var worker_io: std.Io.Threaded = .init(testing.allocator, .{});
    defer worker_io.deinit();

    const result = httpClientLowLevelFetch(
        testing.allocator,
        worker_io.io(),
        url,
        .GET,
        &.{},
        null,
        .{ .first_byte_timeout_ns = 50 * std.time.ns_per_ms },
        null,
    );
    // Release the server thread now that the client has given up.
    unblock_response.store(true, .release);
    server.thread.join();

    try testing.expectError(error.HttpResponseTimeout, result);
}

test "wasi:clocks/monotonic-clock@0.3 polyfill: subscribe-duration pollable fires via P3 timer (#483)" {
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = makeBareCiForClocksTest();
    defer freeBareCiForClocksTest(&ci);

    adapter.monotonic_clock_override = 0;

    const args = [_]InterfaceValue{.{ .u64 = 200 }};
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.subscribeDurationP3Polyfill(&adapter, &ci, &args, &results, testing.allocator);
    const ph = results[0].handle;

    const pollable = adapter.lookupPollable(ph) orelse return error.MissingPollable;
    try testing.expect(pollable == .future_timer);
    try testing.expect(!adapter.pollableIsReady(pollable));

    // Drive the underlying P3 timer past its deadline.
    adapter.monotonic_clock_override = 300;
    _ = adapter.completeDueTimerFutures(&ci, testing.allocator);

    try testing.expect(adapter.pollableIsReady(pollable));
}

