test "hasWasiCliRunP3Export: routes P3 components to async-lifted path (#520)" {
    // The CLI dispatches `wamr run` against component bytes by checking
    // for a 0.3.x `wasi:cli/run@…` instance export at the top level —
    // present iff the component should drive the async-lifted dispatch
    // path. wit-component-emitted P3 binaries carry BOTH a 0.2 and a
    // 0.3 export side-by-side; we must pick the 0.3 path even when
    // a 0.2 export is also present.
    const testing = std.testing;
    const exports_p3 = [_]ctypes_root.ExportDecl{
        .{
            .name = "wasi:cli/run@0.2.0",
            .desc = .{ .instance = 0 },
            .sort_idx = .{ .sort = .instance, .idx = 0 },
        },
        .{
            .name = "wasi:cli/run@0.3.0-rc-2026-03-15",
            .desc = .{ .instance = 0 },
            .sort_idx = .{ .sort = .instance, .idx = 2 },
        },
    };
    const exports_p2_only = [_]ctypes_root.ExportDecl{
        .{
            .name = "wasi:cli/run@0.2.0",
            .desc = .{ .instance = 0 },
            .sort_idx = .{ .sort = .instance, .idx = 0 },
        },
    };
    const empty_exports: [0]ctypes_root.ExportDecl = .{};

    const comp_p3 = ctypes_root.Component{
        .core_modules = &.{},
        .core_instances = &.{},
        .core_types = &.{},
        .components = &.{},
        .instances = &.{},
        .aliases = &.{},
        .types = &.{},
        .canons = &.{},
        .imports = &.{},
        .exports = &exports_p3,
    };
    const comp_p2 = ctypes_root.Component{
        .core_modules = &.{},
        .core_instances = &.{},
        .core_types = &.{},
        .components = &.{},
        .instances = &.{},
        .aliases = &.{},
        .types = &.{},
        .canons = &.{},
        .imports = &.{},
        .exports = &exports_p2_only,
    };
    const comp_empty = ctypes_root.Component{
        .core_modules = &.{},
        .core_instances = &.{},
        .core_types = &.{},
        .components = &.{},
        .instances = &.{},
        .aliases = &.{},
        .types = &.{},
        .canons = &.{},
        .imports = &.{},
        .exports = &empty_exports,
    };
    try testing.expectEqual(true, hasWasiCliRunP3Export(&comp_p3));
    try testing.expectEqual(false, hasWasiCliRunP3Export(&comp_p2));
    try testing.expectEqual(false, hasWasiCliRunP3Export(&comp_empty));
}

test "insecureSeed memoises pair across calls (#520)" {
    // Per WASI spec, `wasi:random/insecure-seed.{get-,}insecure-seed` is
    // meant to be called only once; subsequent calls must return the
    // same `tuple<u64, u64>`. The wasi-p3-testsuite `random` fixture
    // asserts this invariant. Confirm two successive calls produce
    // identical tuples.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    var ci: ComponentInstance = undefined;
    var r1: [1]InterfaceValue = .{.{ .u32 = 0 }};
    var r2: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.insecureSeed(&adapter, &ci, &.{}, &r1, testing.allocator);
    defer r1[0].deinit(testing.allocator);
    try WasiCliAdapter.insecureSeed(&adapter, &ci, &.{}, &r2, testing.allocator);
    defer r2[0].deinit(testing.allocator);

    try testing.expect(r1[0] == .tuple_val);
    try testing.expect(r2[0] == .tuple_val);
    try testing.expectEqual(r1[0].tuple_val[0].u64, r2[0].tuple_val[0].u64);
    try testing.expectEqual(r1[0].tuple_val[1].u64, r2[0].tuple_val[1].u64);
}

// ───────────────────────────────────────────────────────────────────
// wasi:http@0.3.0 unit tests (#487)
// ───────────────────────────────────────────────────────────────────

/// Minimal `ComponentInstance` shim for testing P3 http callbacks
/// without standing up a full module. We only need the four fields
/// the http callbacks touch (`allocator`, `streams`, `futures`,
/// `next_async_handle`); everything else stays `undefined`.
fn p3HttpTestCi(allocator: std.mem.Allocator) ComponentInstance {
    var ci: ComponentInstance = undefined;
    ci.allocator = allocator;
    ci.initAsyncTablesForTest(allocator) catch
        @panic("failed to initialize HTTP test tables");
    return ci;
}

fn p3HttpTestCiDeinit(ci: *ComponentInstance) void {
    ci.deinitAsyncTablesForTest();
}

/// Decode a `result<own<response>, error-code>` canonical-ABI lowered
/// byte buffer (40 bytes — produced by `httpP3LowerAsyncPayload`) into
/// a `(is_ok, payload)` pair. On `is_ok` the payload is the
/// response-resource slot index (post-`decodeResourceWireAbi`); on
/// !is_ok the payload is the `error-code` variant discriminant. Used
/// by the post-#589 unit tests to inspect the bytes wit-bindgen
/// would lower into the guest's `retptr` destination.
fn decodeP3ClientSendBytes(bytes: []const u8) struct { is_ok: bool, payload: u32 } {
    // result disc at offset 0, payload at offset 8 (payload_align = 8
    // because option<u64> on the error-code arm forces 8-byte
    // alignment).
    const is_ok = bytes[0] == 0;
    if (is_ok) {
        const wire = std.mem.readInt(u32, bytes[8..12], .little);
        return .{ .is_ok = true, .payload = abi.decodeResourceWireAbi(wire) };
    } else {
        // Variant discriminant is 1 byte (39 ≤ 256 cases) at offset 8.
        return .{ .is_ok = false, .payload = bytes[8] };
    }
}

/// Spin the adapter's P3 HTTP drainer until the named future on `ci`
/// transitions out of `.pending`, capped at `iters` 1 ms polls.
/// Test-side counterpart of `p3DrainPendingHttpUntilSettled` for the
/// post-#589 deferred-completion path that settles
/// `ComponentInstance.futures` slots rather than the adapter-owned
/// `FutureIncomingResponse`.
fn p3DrainPendingHttpP3UntilSettled(
    adapter: *WasiCliAdapter,
    ci: *ComponentInstance,
    future_handle: u32,
    iters: usize,
) void {
    var i: usize = 0;
    while (i < iters) : (i += 1) {
        const fut = ci.futures.getPtr(future_handle) orelse return;
        if (fut.state != .pending) return;
        adapter.drainPendingHttpFetchesP3(ci, ci.allocator);
        if (fut.state != .pending) return;
        const io = std.Io.Threaded.global_single_threaded.io();
        const dur: std.Io.Clock.Duration = .{
            .raw = .{ .nanoseconds = 1 * std.time.ns_per_ms },
            .clock = .awake,
        };
        dur.sleep(io) catch {};
    }
}

test "wasi:http@0.3 (#487): request.new + consume-body returns body stream + trailers future" {
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    // Pre-build a body stream<u8> handle in ci.streams holding "hello".
    const body_handle = ci.allocAsyncHandle();
    var body: async_mod.AsyncStream = .{ .elem_type_idx = 0 };
    try body.buffer.appendSlice(testing.allocator, "hello");
    body.write_closed = true;
    try ci.streams.put(testing.allocator, body_handle, body);

    // Pre-build a ready trailers future.
    const trailers_handle = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, trailers_handle, .{
        .elem_type_idx = 0,
        .state = .ready,
        .write_closed = true,
    });

    // Build option<stream<u8>> = some(body_handle).
    var body_inner: InterfaceValue = .{ .handle = body_handle };
    const body_opt: InterfaceValue = .{ .option_val = .{ .is_some = true, .payload = &body_inner } };
    const trailers_arg: InterfaceValue = .{ .handle = trailers_handle };
    const options_opt: InterfaceValue = .{ .option_val = .{ .is_some = false, .payload = null } };

    // request.new(headers=0, contents=some(body), trailers, options=none)
    const new_args = [_]InterfaceValue{
        .{ .handle = 0 }, // headers
        body_opt,
        trailers_arg,
        options_opt,
    };
    var new_results: [1]InterfaceValue = undefined;
    try WasiCliAdapter.httpRequestNewP3(&adapter, &ci, &new_args, &new_results, testing.allocator);
    defer new_results[0].deinit(testing.allocator);

    try testing.expect(new_results[0] == .tuple_val);
    try testing.expectEqual(@as(usize, 2), new_results[0].tuple_val.len);
    const req_handle = new_results[0].tuple_val[0].handle;
    try testing.expect(adapter.http_requests_p3.contains(req_handle));

    // consume-body should return tuple<body-stream-handle, trailers-handle>.
    const cb_args = [_]InterfaceValue{.{ .handle = req_handle }};
    var cb_results: [1]InterfaceValue = undefined;
    try WasiCliAdapter.httpRequestConsumeBodyP3(&adapter, &ci, &cb_args, &cb_results, testing.allocator);
    defer cb_results[0].deinit(testing.allocator);

    try testing.expect(cb_results[0] == .tuple_val);
    try testing.expectEqual(@as(usize, 2), cb_results[0].tuple_val.len);
    try testing.expectEqual(body_handle, cb_results[0].tuple_val[0].handle);
    try testing.expectEqual(trailers_handle, cb_results[0].tuple_val[1].handle);

    // Body stream should still hold "hello".
    const s = ci.streams.getPtr(body_handle).?;
    try testing.expectEqualStrings("hello", s.buffer.items);
}

test "wasi:http@0.3 (#487): client.send denies when allow-list empty" {
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    // Build a request via the constructor so all bookkeeping is real.
    var trailers_inner_arg: InterfaceValue = .{
        .option_val = .{ .is_some = false, .payload = null },
    };
    _ = &trailers_inner_arg;

    const trailers_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, trailers_h, .{
        .elem_type_idx = 0,
        .state = .ready,
        .write_closed = true,
    });

    const new_args = [_]InterfaceValue{
        .{ .handle = 0 },
        .{ .option_val = .{ .is_some = false, .payload = null } },
        .{ .handle = trailers_h },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var new_results: [1]InterfaceValue = undefined;
    try WasiCliAdapter.httpRequestNewP3(&adapter, &ci, &new_args, &new_results, testing.allocator);
    defer new_results[0].deinit(testing.allocator);
    const req_handle = new_results[0].tuple_val[0].handle;

    // Empty allow-list (default) → HTTP_request_denied. Post-#589 the
    // host fn returns a `.handle` future whose payload is the
    // canonical-ABI err-arm envelope (the trampoline-shape requirement
    // for `canon.lower (async)`); the future is already `.ready` for
    // synchronous deny paths so no drain is needed.
    const send_args = [_]InterfaceValue{.{ .handle = req_handle }};
    var send_results: [1]InterfaceValue = undefined;
    try WasiCliAdapter.httpClientSendP3(&adapter, &ci, &send_args, &send_results, testing.allocator);
    defer send_results[0].deinit(testing.allocator);

    try testing.expect(send_results[0] == .handle);
    const fh = send_results[0].handle;
    const fut = ci.futures.getPtr(fh).?;
    try testing.expect(fut.state == .ready);
    const decoded = decodeP3ClientSendBytes(fut.payload.?);
    try testing.expect(!decoded.is_ok);
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.HTTP_request_denied)),
        decoded.payload,
    );
}

test "wasi:http@0.3 #589: P3 client.send ok-arm lowered bytes match canonical-ABI envelope" {
    // Confirms that `httpP3LowerAsyncPayload(.client_send_ok, ...)`
    // produces exactly the bytes wit-bindgen would lower for a
    // `result<own<response>, error-code>` ok-arm carrying a
    // representative resource handle.
    //
    // Expected envelope shape (computed from the registry):
    //   * result disc-size = 1, payload align = 8 (option<u64> on the
    //     err arm forces 8-byte align), result payload offset = 8,
    //     max payload size = 32 (variant) → total = 40 bytes.
    //   * bytes[0]      = 0           (result disc — ok)
    //   * bytes[1..8]   = padding     (alignUp(1, 8) = 8)
    //   * bytes[8..12]  = LE wire     (own<response> = rep + 1 per
    //                                  `encodeResourceWireAbi`)
    //   * bytes[12..40] = zeroed      (variant tail unused on ok arm)
    const testing = std.testing;
    const response_handle: u32 = 5;
    const val = try httpP3BuildClientSendOkIv(testing.allocator, response_handle);
    defer val.deinit(testing.allocator);
    const bytes = try httpP3LowerAsyncPayload(testing.allocator, .client_send_ok, val);
    defer testing.allocator.free(bytes);

    try testing.expectEqual(@as(usize, 40), bytes.len);
    try testing.expectEqual(@as(u8, 0), bytes[0]); // ok disc
    // Result padding (bytes 1..8) is zeroed.
    for (bytes[1..8]) |b| try testing.expectEqual(@as(u8, 0), b);
    // Own-handle wire = rep + 1.
    const wire = std.mem.readInt(u32, bytes[8..12], .little);
    try testing.expectEqual(@as(u32, response_handle + 1), wire);
    // Variant-arm padding (bytes 12..40) is zeroed because we wrote
    // the ok arm.
    for (bytes[12..40]) |b| try testing.expectEqual(@as(u8, 0), b);
}

test "wasi:http@0.3 #589: P3 client.send err-arm lowered bytes match wit-bindgen for connection-refused" {
    // Confirms that `httpP3LowerAsyncPayload(.client_send_err, ...)`
    // for `Err(connection-refused)` produces the same canonical-ABI
    // bytes wit-bindgen would emit:
    //   * bytes[0]      = 1     (result disc — err)
    //   * bytes[1..8]   = pad   (result payload align = 8)
    //   * bytes[8]      = 6     (error-code variant disc —
    //                            connection-refused at index 6)
    //   * bytes[9..40]  = pad   (variant payload align = 8; the
    //                            arm has no payload, and the buffer
    //                            is @memset(0)-initialised before
    //                            the lowering)
    const testing = std.testing;
    const val = try httpP3BuildClientSendErrIv(testing.allocator, .connection_refused);
    defer val.deinit(testing.allocator);
    const bytes = try httpP3LowerAsyncPayload(testing.allocator, .client_send_err, val);
    defer testing.allocator.free(bytes);

    try testing.expectEqual(@as(usize, 40), bytes.len);
    try testing.expectEqual(@as(u8, 1), bytes[0]); // err disc
    for (bytes[1..8]) |b| try testing.expectEqual(@as(u8, 0), b);
    try testing.expectEqual(@as(u8, 6), bytes[8]); // connection-refused
    for (bytes[9..40]) |b| try testing.expectEqual(@as(u8, 0), b);
}

test "wasi:http@0.3 #589: P3 client.send err-arm uses 0.3 error-code variant discriminants" {
    // The 0.3 `error-code` is a 39-case variant (not the flat 0.2
    // enum) with payloads on certain arms — declared in
    // `http_p3_error_code_cases`. The discriminant numbering must
    // match the WIT-declaration order so a guest decoding the bytes
    // via wit-bindgen observes the correct arm.
    //
    // Spot-check both ends of the table plus a payload-bearing arm to
    // pin the ordering. The lowered envelope is always 40 bytes (the
    // 0.3 variant envelope; a flat 0.2 enum would be 4 bytes), which
    // is also asserted as a guard against a regression to the wrong
    // type — the size check by itself is the strongest signal that
    // we're using the variant lowering and not an enum lowering.
    const testing = std.testing;

    const cases = [_]struct { code: HttpErrorCode, disc: u8 }{
        .{ .code = .DNS_timeout, .disc = 0 },
        .{ .code = .DNS_error, .disc = 1 }, // payload-bearing
        .{ .code = .connection_refused, .disc = 6 },
        .{ .code = .TLS_alert_received, .disc = 14 }, // payload-bearing
        .{ .code = .HTTP_request_denied, .disc = 15 },
        .{ .code = .HTTP_response_body_size, .disc = 28 }, // payload-bearing
        .{ .code = .internal_error, .disc = 38 }, // payload-bearing, last arm
    };

    for (cases) |c| {
        const val = try httpP3BuildClientSendErrIv(testing.allocator, c.code);
        defer val.deinit(testing.allocator);
        const bytes = try httpP3LowerAsyncPayload(testing.allocator, .client_send_err, val);
        defer testing.allocator.free(bytes);

        // Envelope size is 40 bytes; if we mistakenly treated
        // error-code as the 0.2 flat enum (4-byte sizeof), the
        // buffer would shrink to 8 bytes here.
        try testing.expectEqual(@as(usize, 40), bytes.len);
        try testing.expectEqual(@as(u8, 1), bytes[0]); // err disc
        try testing.expectEqual(c.disc, bytes[8]);
        // The enum value and the WIT discriminant must agree —
        // protects against a future reorder of `HttpErrorCode`
        // away from the 0.3 WIT order.
        try testing.expectEqual(@as(u32, c.disc), @intFromEnum(c.code));
    }
}

test "wasi:http@0.3 #589: P3 client.send drains deferred outcome and lowers ok-arm bytes (loopback)" {
    // End-to-end round-trip exercise:
    //   * spawn a loopback HTTP/1.1 server,
    //   * call `client.send` against it,
    //   * observe a `.pending` future minted by `spawnHttpFetchPendingP3`,
    //   * drive `drainPendingHttpFetchesP3` until the worker publishes,
    //   * assert the lowered payload bytes are the canonical-ABI
    //     `Ok(response)` envelope referencing the host's response
    //     resource slot, and the response stream holds the served
    //     body bytes.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    var server = TestHttpServer.serveLoopback(testing.allocator, "hello-589") catch
        return error.SkipZigTest;

    try adapter.setSocketsAllowList(&.{"127.0.0.0/8"});

    const trailers_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, trailers_h, .{
        .elem_type_idx = 0,
        .state = .ready,
        .write_closed = true,
    });

    const new_args = [_]InterfaceValue{
        .{ .handle = 0 },
        .{ .option_val = .{ .is_some = false, .payload = null } },
        .{ .handle = trailers_h },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var new_results: [1]InterfaceValue = undefined;
    try WasiCliAdapter.httpRequestNewP3(&adapter, &ci, &new_args, &new_results, testing.allocator);
    defer new_results[0].deinit(testing.allocator);
    const req_handle = new_results[0].tuple_val[0].handle;
    const r = adapter.http_requests_p3.unsafeGetPtrForTest(req_handle).?.*;
    r.scheme_disc = 0; // http
    r.authority = try std.fmt.allocPrint(testing.allocator, "127.0.0.1:{d}", .{server.port});

    const send_args = [_]InterfaceValue{.{ .handle = req_handle }};
    var send_results: [1]InterfaceValue = undefined;
    try WasiCliAdapter.httpClientSendP3(&adapter, &ci, &send_args, &send_results, testing.allocator);
    defer send_results[0].deinit(testing.allocator);

    try testing.expect(send_results[0] == .handle);
    const fh = send_results[0].handle;
    const fut0 = ci.futures.getPtr(fh).?;
    try testing.expect(fut0.state == .pending);
    try testing.expectEqual(@as(usize, 1), adapter.pending_http_fetches_p3.publishedCount());

    p3DrainPendingHttpP3UntilSettled(&adapter, &ci, fh, 10_000);
    server.thread.join();

    const fut = ci.futures.getPtr(fh).?;
    try testing.expect(fut.state == .ready);
    const decoded = decodeP3ClientSendBytes(fut.payload.?);
    try testing.expect(decoded.is_ok);
    // Worker drained — entry consumed.
    try testing.expectEqual(@as(usize, 0), adapter.pending_http_fetches_p3.publishedCount());

    // The decoded payload is the host's response resource slot — the
    // body stream should hold the served bytes.
    const resp = adapter.http_responses_p3.unsafeGetPtrForTest(decoded.payload).?.*;
    try testing.expectEqual(@as(u16, 200), resp.status);
    const body_stream = ci.streams.getPtr(resp.body_stream_handle.?).?;
    try testing.expectEqualStrings("hello-589", body_stream.buffer.items);
}

test "wasi:http@0.3 #521: client.send proceeds past the TLS gate for https" {
    // Counterpart to the P2 test: the #477/#501 `HTTP_protocol_error`
    // short-circuit is gone for `wasi:http/client.send@0.3.0` as
    // well. `https://127.0.0.1:1/` has no listener so TCP connect
    // refuses before TLS can start; with the #583 A3 error refinement
    // the host surfaces `connection_refused`, never
    // `HTTP_protocol_error` and never the catch-all `internal_error`.
    //
    // Skipped on Windows for the same reason as the P2 sibling:
    // WinSock's `WSAECONNREFUSED` does not round-trip through
    // `std.http.Client.FetchError` as `error.ConnectionRefused`, so
    // the asserted variant is platform-dependent. The pure-helper
    // `mapHttpFetchError` tests cover the deterministic mapping on
    // every target.
    if (builtin.os.tag == .windows) return error.SkipZigTest;
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    try adapter.setSocketsAllowList(&.{"127.0.0.0/8"});

    const trailers_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, trailers_h, .{
        .elem_type_idx = 0,
        .state = .ready,
        .write_closed = true,
    });

    const new_args = [_]InterfaceValue{
        .{ .handle = 0 },
        .{ .option_val = .{ .is_some = false, .payload = null } },
        .{ .handle = trailers_h },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var new_results: [1]InterfaceValue = undefined;
    try WasiCliAdapter.httpRequestNewP3(&adapter, &ci, &new_args, &new_results, testing.allocator);
    defer new_results[0].deinit(testing.allocator);
    const req_handle = new_results[0].tuple_val[0].handle;

    // Set scheme=https (discriminant 1) and authority.
    const r = adapter.http_requests_p3.unsafeGetPtrForTest(req_handle).?.*;
    r.scheme_disc = 1;
    r.authority = try testing.allocator.dupe(u8, "127.0.0.1:1");

    const send_args = [_]InterfaceValue{.{ .handle = req_handle }};
    var send_results: [1]InterfaceValue = undefined;
    try WasiCliAdapter.httpClientSendP3(&adapter, &ci, &send_args, &send_results, testing.allocator);
    defer send_results[0].deinit(testing.allocator);

    // Post-#589: `client.send` returns a `.handle` future; drain it
    // until the worker thread publishes the connect-refused outcome.
    try testing.expect(send_results[0] == .handle);
    const fh = send_results[0].handle;
    p3DrainPendingHttpP3UntilSettled(&adapter, &ci, fh, 10_000);
    const fut = ci.futures.getPtr(fh).?;
    try testing.expect(fut.state == .ready);
    const decoded = decodeP3ClientSendBytes(fut.payload.?);
    try testing.expect(!decoded.is_ok);
    // The scheme gate is gone — `HTTP_protocol_error` must not be the
    // outcome of a well-formed `https://` request.
    try testing.expect(decoded.payload != @as(u32, @intFromEnum(HttpErrorCode.HTTP_protocol_error)));
    // Port 1 has no listener; TCP connect refuses before TLS runs,
    // which the #583 A3 mapping surfaces as `connection_refused`.
    try testing.expectEqual(@as(u32, @intFromEnum(HttpErrorCode.connection_refused)), decoded.payload);
}

test "wasi:http #583 A3: mapHttpFetchError classifies connection-refused" {
    // Direct mapping unit-test — does not require network. Verifies
    // that `error.ConnectionRefused` from `std.http.Client.fetch`
    // (e.g. attempting to dial a closed local port) surfaces as the
    // dedicated `connection_refused` variant rather than the old
    // catch-all `internal_error`.
    const testing = std.testing;
    try testing.expectEqual(HttpErrorCode.connection_refused, mapHttpFetchError(error.ConnectionRefused));
    // Companion arms in the same connection-level cluster.
    try testing.expectEqual(HttpErrorCode.connection_terminated, mapHttpFetchError(error.ConnectionResetByPeer));
    try testing.expectEqual(HttpErrorCode.connection_terminated, mapHttpFetchError(error.ReadFailed));
    try testing.expectEqual(HttpErrorCode.connection_terminated, mapHttpFetchError(error.WriteFailed));
    try testing.expectEqual(HttpErrorCode.connection_timeout, mapHttpFetchError(error.Timeout));
    try testing.expectEqual(HttpErrorCode.destination_unavailable, mapHttpFetchError(error.HostUnreachable));
    try testing.expectEqual(HttpErrorCode.destination_unavailable, mapHttpFetchError(error.NetworkUnreachable));
}

test "wasi:http #583 A3: mapHttpFetchError classifies TLS handshake failures" {
    // `std.http.Client.connectTcpOptions` remaps every non-OOM /
    // non-cancel / non-unexpected error from `std.crypto.tls.Client.init`
    // to `error.TlsInitializationFailed` — which is the only TLS
    // error variant that ever escapes `client.fetch`. With the #583 A3
    // refinement, that one variant now lands on `TLS_protocol_error`
    // instead of the catch-all `internal_error`. Cert-bundle load
    // failures get their own `TLS_certificate_error` arm.
    const testing = std.testing;
    try testing.expectEqual(HttpErrorCode.TLS_protocol_error, mapHttpFetchError(error.TlsInitializationFailed));
    try testing.expectEqual(HttpErrorCode.TLS_certificate_error, mapHttpFetchError(error.CertificateBundleLoadFailure));
}

test "wasi:http #583 A3: mapHttpFetchError classifies DNS NXDOMAIN" {
    // `std.Io.net.HostName.LookupError.UnknownHostName` is the
    // canonical "no such host" failure mode (the resolver answered
    // NXDOMAIN). With #583 A3 this maps to `DNS_error` instead of the
    // generic `internal_error`. Other LookupError variants (resolver
    // failure, parse failure, etc.) also flow into `DNS_error`.
    const testing = std.testing;
    try testing.expectEqual(HttpErrorCode.DNS_error, mapHttpFetchError(error.UnknownHostName));
    try testing.expectEqual(HttpErrorCode.DNS_error, mapHttpFetchError(error.NameServerFailure));
    try testing.expectEqual(HttpErrorCode.DNS_error, mapHttpFetchError(error.InvalidDnsARecord));
    try testing.expectEqual(HttpErrorCode.DNS_error, mapHttpFetchError(error.InvalidDnsAAAARecord));
    try testing.expectEqual(HttpErrorCode.DNS_error, mapHttpFetchError(error.ResolvConfParseFailed));
    try testing.expectEqual(HttpErrorCode.DNS_error, mapHttpFetchError(error.DetectingNetworkConfigurationFailed));
    try testing.expectEqual(HttpErrorCode.destination_not_found, mapHttpFetchError(error.NoAddressReturned));
}

test "wasi:http #583 A3: mapHttpFetchError classifies HTTP / URI / fallthrough" {
    // Coverage for the remaining clusters: response-framing,
    // URI parse failures, and the intentional `internal_error`
    // fallthrough for truly-unknown errors.
    const testing = std.testing;
    // Response framing (Request.ReceiveHeadError) ────────────────────
    try testing.expectEqual(HttpErrorCode.HTTP_protocol_error, mapHttpFetchError(error.HttpHeadersInvalid));
    try testing.expectEqual(HttpErrorCode.HTTP_protocol_error, mapHttpFetchError(error.HttpChunkInvalid));
    try testing.expectEqual(HttpErrorCode.HTTP_response_header_section_size, mapHttpFetchError(error.HttpHeadersOversize));
    try testing.expectEqual(HttpErrorCode.HTTP_response_body_size, mapHttpFetchError(error.StreamTooLong));
    try testing.expectEqual(HttpErrorCode.HTTP_response_content_coding, mapHttpFetchError(error.UnsupportedCompressionMethod));
    try testing.expectEqual(HttpErrorCode.loop_detected, mapHttpFetchError(error.TooManyHttpRedirects));
    try testing.expectEqual(HttpErrorCode.connection_terminated, mapHttpFetchError(error.HttpRequestTruncated));
    try testing.expectEqual(HttpErrorCode.connection_terminated, mapHttpFetchError(error.HttpConnectionClosing));
    // URI / request shape (Uri.ParseError + RequestError) ──────────
    try testing.expectEqual(HttpErrorCode.HTTP_request_URI_invalid, mapHttpFetchError(error.UnsupportedUriScheme));
    try testing.expectEqual(HttpErrorCode.HTTP_request_URI_invalid, mapHttpFetchError(error.UriMissingHost));
    try testing.expectEqual(HttpErrorCode.HTTP_request_URI_invalid, mapHttpFetchError(error.InvalidFormat));
    try testing.expectEqual(HttpErrorCode.HTTP_request_URI_invalid, mapHttpFetchError(error.UnexpectedCharacter));
    try testing.expectEqual(HttpErrorCode.HTTP_request_URI_invalid, mapHttpFetchError(error.InvalidPort));
    // Intentional fallthrough — unknown / resource-exhaustion paths.
    try testing.expectEqual(HttpErrorCode.internal_error, mapHttpFetchError(error.OutOfMemory));
    try testing.expectEqual(HttpErrorCode.internal_error, mapHttpFetchError(error.Unexpected));
    try testing.expectEqual(HttpErrorCode.internal_error, mapHttpFetchError(error.Canceled));
    try testing.expectEqual(HttpErrorCode.internal_error, mapHttpFetchError(error.SystemResources));
}

test "wasi:http #583 A3: connect-refused end-to-end (P2 outgoing-handler, http)" {
    // End-to-end transport-error mapping for the Preview 2 outgoing
    // handler over plaintext HTTP. Port 1 on the loopback has no
    // listener, so `std.http.Client.fetch` returns
    // `error.ConnectionRefused`; with the #583 A3 refinement the
    // future surfaces `connection_refused` instead of `internal_error`.
    //
    // (#583 A2) The P2 outbound handler now runs the blocking fetch
    // on a worker thread and returns a `.pending` future; this test
    // drives `drainPendingHttpFetches` until the worker publishes
    // its outcome through `mapHttpFetchError`.
    //
    // Skipped on Windows: WinSock's `WSAECONNREFUSED` does not surface
    // as `error.ConnectionRefused` through `std.http.Client.fetch`
    // (it appears as `error.Unexpected` / `ConnectionResetByPeer` /
    // `BrokenPipe` depending on Zig stdlib revision), so this
    // platform-dependent integration check is gated to POSIX. The
    // pure-helper `mapHttpFetchError` tests cover the WIT mapping
    // deterministically on every target.
    if (builtin.os.tag == .windows) return error.SkipZigTest;
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci: ComponentInstance = undefined;

    const allow = try testing.allocator.alloc(IpCidr, 1);
    allow[0] = try IpCidr.parse("127.0.0.0/8");
    adapter.sockets_allow_list_template = allow;

    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);

    const req = try testing.allocator.create(OutgoingRequest);
    req.* = .{
        .method_disc = 0, // GET
        .scheme_disc = 0, // http
        .authority = try testing.allocator.dupe(u8, "127.0.0.1:1"),
        .path_with_query = try testing.allocator.dupe(u8, "/"),
        .headers_handle = fh,
    };
    const rh = try adapter.pushOutgoingRequest(req);

    const args = [_]InterfaceValue{
        .{ .handle = rh },
        .{ .option_val = .{ .is_some = false, .payload = null } },
    };
    var results: [1]InterfaceValue = .{.{ .u32 = 0 }};
    try WasiCliAdapter.httpOutgoingHandlerHandle(&adapter, &ci, &args, &results, testing.allocator);
    defer results[0].deinit(testing.allocator);

    try testing.expect(results[0] == .result_val);
    try testing.expect(results[0].result_val.is_ok);
    const fut = adapter.http_future_responses.unsafeGetPtrForTest(results[0].result_val.payload.?.handle).?.*;
    // (#583 A2) Drive the deferred worker. `error.ConnectionRefused`
    // happens fast on a closed loopback port; the worker publishes
    // and the drainer settles `.ready_err(.connection_refused)`.
    p3DrainPendingHttpUntilSettled(&adapter, fut, 10_000);
    try testing.expect(fut.state == .ready_err);
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.connection_refused)),
        fut.state.ready_err,
    );
}

