    // Empty authority rejected.
    try testing.expect(!try Caller.callSetSome(&adapter, &ci, req_handle, ""));
}

test "sockets (#520 wave 2): socketCodeToP3Disc maps internal enum to WIT 0.3 variant discs" {
    const testing = std.testing;
    // WIT 0.3 `wasi:sockets/types.error-code` variant ordering:
    // 0=access-denied, 1=not-supported, 2=invalid-argument, 3=out-of-memory,
    // 4=timeout, 5=invalid-state, 6=address-not-bindable, 7=address-in-use,
    // 8=remote-unreachable, 9=connection-refused, 10=connection-broken,
    // 11=connection-reset, 12=connection-aborted, 13=datagram-too-large,
    // 14=other(option<string>). Our internal `SocketErrorCode` enum
    // matches the 0.2 ENUM ordering (`unknown=0`, access_denied=1, …)
    // which is off-by-one from 0.3 — that mismatch is what
    // `socketCodeToP3Disc` translates at the host boundary.
    try testing.expectEqual(@as(u32, 0), WasiCliAdapter.socketCodeToP3Disc(.access_denied));
    try testing.expectEqual(@as(u32, 1), WasiCliAdapter.socketCodeToP3Disc(.not_supported));
    try testing.expectEqual(@as(u32, 2), WasiCliAdapter.socketCodeToP3Disc(.invalid_argument));
    try testing.expectEqual(@as(u32, 3), WasiCliAdapter.socketCodeToP3Disc(.out_of_memory));
    try testing.expectEqual(@as(u32, 5), WasiCliAdapter.socketCodeToP3Disc(.invalid_state));
    try testing.expectEqual(@as(u32, 6), WasiCliAdapter.socketCodeToP3Disc(.address_not_bindable));
    try testing.expectEqual(@as(u32, 7), WasiCliAdapter.socketCodeToP3Disc(.address_in_use));
    // 0.2-only cases (no 0.3 equivalent) fall back to `other(none)` = 14.
    try testing.expectEqual(@as(u32, 14), WasiCliAdapter.socketCodeToP3Disc(.unknown));
    try testing.expectEqual(@as(u32, 14), WasiCliAdapter.socketCodeToP3Disc(.concurrency_conflict));
    try testing.expectEqual(@as(u32, 14), WasiCliAdapter.socketCodeToP3Disc(.not_in_progress));
    try testing.expectEqual(@as(u32, 14), WasiCliAdapter.socketCodeToP3Disc(.would_block));
    try testing.expectEqual(@as(u32, 14), WasiCliAdapter.socketCodeToP3Disc(.new_socket_limit));
}

test "sockets #575/#583 A6: bindAndGetsockname SO_REUSEADDR lets immediate rebind to TIME_WAIT port succeed" {
    const testing = std.testing;
    const io = std.Io.Threaded.global_single_threaded.io();

    // First bind: wildcard:0 — kernel assigns an ephemeral port.
    const wildcard: std.Io.net.IpAddress = .{ .ip4 = .{
        .bytes = [4]u8{ 127, 0, 0, 1 },
        .port = 0,
    } };
    const first = try bindAndGetsockname(wildcard, .stream, .tcp);
    const assigned_port = switch (first.address) {
        .ip4 => |v4| v4.port,
        .ip6 => |v6| v6.port,
    };
    try testing.expect(assigned_port != 0);

    // Close the first socket — the kernel may leave the 4-tuple in
    // TIME_WAIT. Without SO_REUSEADDR on the new socket below the
    // rebind would fail with `error.AddressInUse` for that window.
    // With the setsockopt added in #575 (POSIX) / #583 A6 (Windows)
    // it succeeds on every supported platform.
    first.close(io);

    // Second bind: same port, fresh socket. With SO_REUSEADDR set by
    // `bindAndGetsockname` this must succeed even if the first tuple
    // is still in TIME_WAIT — the symptom that broke
    // `sockets-tcp-bind::test_reuseaddr` before #575 on POSIX (and
    // would break it on MinGW CI once Windows runs the p3 suite,
    // absent #583 A6).
    const rebind_addr: std.Io.net.IpAddress = .{ .ip4 = .{
        .bytes = [4]u8{ 127, 0, 0, 1 },
        .port = assigned_port,
    } };
    const second = try bindAndGetsockname(rebind_addr, .stream, .tcp);
    defer second.close(io);

    const got_port = switch (second.address) {
        .ip4 => |v4| v4.port,
        .ip6 => |v6| v6.port,
    };
    try testing.expectEqual(assigned_port, got_port);
}

test "sockets #583 A6: bindAndGetsockname wildcard:0 round-trip is portable across POSIX/Windows" {
    // Smoke-test the same `bindAndGetsockname` entry point on every
    // platform — on POSIX it exercises the raw-syscall path, on
    // Windows it exercises the ws2_32 path added by #583 A6. Both
    // arms must:
    //   1. Open a socket and bind to 127.0.0.1:0 successfully.
    //   2. Receive a non-zero kernel-assigned ephemeral port via
    //      getsockname.
    //   3. Allow an immediate rebind on the resolved port using a
    //      fresh socket (SO_REUSEADDR coverage — same expectation as
    //      `sockets-tcp-bind::test_reuseaddr`).
    //   4. Repeat the round trip for UDP/.dgram so the non-stream
    //      branch of the `mode` switch is hit too.
    const testing = std.testing;
    const io = std.Io.Threaded.global_single_threaded.io();

    inline for (.{
        .{ std.Io.net.Socket.Mode.stream, std.Io.net.Protocol.tcp },
        .{ std.Io.net.Socket.Mode.dgram, std.Io.net.Protocol.udp },
    }) |pair| {
        const mode = pair[0];
        const proto = pair[1];

        const wildcard: std.Io.net.IpAddress = .{ .ip4 = .{
            .bytes = [4]u8{ 127, 0, 0, 1 },
            .port = 0,
        } };
        const first = try bindAndGetsockname(wildcard, mode, proto);
        const assigned_port = switch (first.address) {
            .ip4 => |v4| v4.port,
            .ip6 => |v6| v6.port,
        };
        try testing.expect(assigned_port != 0);
        first.close(io);

        const rebind_addr: std.Io.net.IpAddress = .{ .ip4 = .{
            .bytes = [4]u8{ 127, 0, 0, 1 },
            .port = assigned_port,
        } };
        const second = try bindAndGetsockname(rebind_addr, mode, proto);
        defer second.close(io);
        const got_port = switch (second.address) {
            .ip4 => |v4| v4.port,
            .ip6 => |v6| v6.port,
        };
        try testing.expectEqual(assigned_port, got_port);
    }
}

test "main (#520 wave 2): runComponent applies --map-dir flags via addPreopen" {
    const testing = std.testing;

    // Spin up an adapter the same way `runComponent` does and verify
    // that `addPreopen` ends up in `fs_preopens`. The CLI plumbing
    // path itself (parse `--map-dir`, call `cwd_dir.openDir`, hand
    // off to `addPreopen`) is exercised end-to-end by the
    // wasi-p3-testsuite filesystem fixtures once the async-future
    // lower fix lands; this unit test pins the contract.
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();

    const handle = try adapter.addPreopen("fs-tests.dir", tmp.dir);
    // Replace the slot with null so adapter.deinit doesn't double-close
    // (tmp.cleanup() owns the dir handle).
    _ = adapter.fs_descriptor_table.withdraw(handle);

    try testing.expectEqual(@as(usize, 1), adapter.fs_preopens.items.len);
    try testing.expectEqualStrings("fs-tests.dir", adapter.fs_preopens.items[0].name);
    // `dir_handle` is the 0-based slot index; the wire encoding
    // (`slot + 1`) is applied by `fsGetDirectories` via
    // `abi.encodeResourceWireAbi` when lowering to guest memory.
    try testing.expectEqual(handle, adapter.fs_preopens.items[0].dir_handle);
}

// ── #562: wasi:http@0.3 host-handle wire offset for `outgoing-response`
// and friends. Verifies that every http host-instance table reserves
// slot 0 as a null sentinel, so the canon-ABI `decodeResourceWire(wire)`
// mapping of wire `0` → host slot `0` lands on a null entry (rather
// than silently returning the first allocated resource). PR #560
// applied the same pattern to sockets + filesystem; this PR extends
// the convention to http (`http_outgoing_responses`,
// `http_outgoing_requests`, `http_outgoing_bodies`,
// `http_incoming_responses`, `http_incoming_requests`,
// `http_incoming_bodies`, `http_fields`, `http_future_trailers`).

test "http (#562): outgoing-response push reserves slot 0 + wire round-trips through encodeResourceWire" {
    const testing = std.testing;
    const executor = @import("executor.zig");

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    // Push a fresh `OutgoingResponse`. The headers_handle field is
    // populated from a real `pushHttpFields` slot to keep the
    // adapter's deinit clean.
    const fields = try adapter.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);
    try testing.expect(fh >= 1); // slot 0 reserved

    const resp = try adapter.allocator.create(OutgoingResponse);
    resp.* = .{ .status = 200, .headers_handle = fh };
    const slot = try adapter.pushOutgoingResponse(resp);

    // Slot must be 1+ (slot 0 is the null sentinel).
    try testing.expect(slot >= 1);
    try testing.expect(!adapter.http_outgoing_responses.contains(0));
    try testing.expectEqual(resp, adapter.http_outgoing_responses.unsafeGetPtrForTest(slot).?.*);

    // wire = slot + 1 (`encodeResourceWire`). Non-zero, so wit-bindgen
    // Rust's `Resource<OutgoingResponse>::from_handle(wire)` will not
    // trip the `handle != 0` debug assertion.
    const wire = executor.encodeResourceWire(slot);
    try testing.expect(wire >= 2);
    try testing.expectEqual(slot + 1, wire);

    // Round-trip back to slot via `decodeResourceWire`.
    const decoded = executor.decodeResourceWire(wire);
    try testing.expectEqual(slot, decoded);
    try testing.expectEqual(resp, adapter.http_outgoing_responses.unsafeGetPtrForTest(decoded).?.*);
}

test "http (#562): http_fields_table push reserves slot 0 + wire round-trips through encodeResourceWire" {
    const testing = std.testing;
    const executor = @import("executor.zig");

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    const fields = try adapter.allocator.create(HttpFields);
    fields.* = .{};
    const slot = try adapter.pushHttpFields(fields);

    // Slot 0 stays null; first allocation lands at slot 1.
    try testing.expect(slot >= 1);
    try testing.expect(!adapter.http_fields_table.contains(0));
    try testing.expectEqual(fields, adapter.http_fields_table.unsafeGetPtrForTest(slot).?.*);

    // Encode → decode → lookup must round-trip to the same resource.
    const wire = executor.encodeResourceWire(slot);
    try testing.expect(wire >= 2);
    const decoded = executor.decodeResourceWire(wire);
    try testing.expectEqual(slot, decoded);
    try testing.expectEqual(fields, adapter.http_fields_table.unsafeGetPtrForTest(decoded).?.*);
}

test "http (#562): every http host table reserves slot 0 — wire=0 lookup returns null, not the first allocation" {
    const testing = std.testing;
    const executor = @import("executor.zig");

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    // Allocate one resource into every http host table so that slot 1
    // is real. `decodeResourceWire(0) == 0` (the canon-ABI lifts a
    // wire-zero handle to host slot 0); slot 0 of every http table
    // must be null so the corresponding `lookup*` returns null
    // instead of silently surfacing the first allocation.
    const fields = try adapter.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);
    try testing.expect(fh >= 1);

    const out_req = try adapter.allocator.create(OutgoingRequest);
    out_req.* = .{ .headers_handle = fh };
    const out_req_slot = try adapter.pushOutgoingRequest(out_req);
    try testing.expect(out_req_slot >= 1);

    const in_req = try adapter.allocator.create(IncomingRequest);
    in_req.* = .{};
    const in_req_slot = try adapter.pushIncomingRequest(in_req);
    try testing.expect(in_req_slot >= 1);

    const out_resp = try adapter.allocator.create(OutgoingResponse);
    out_resp.* = .{ .status = 200, .headers_handle = fh };
    const out_resp_slot = try adapter.pushOutgoingResponse(out_resp);
    try testing.expect(out_resp_slot >= 1);

    const in_resp = try adapter.allocator.create(IncomingResponse);
    in_resp.* = .{};
    const in_resp_slot = try adapter.pushIncomingResponse(in_resp);
    try testing.expect(in_resp_slot >= 1);

    const out_body = try adapter.allocator.create(OutgoingBody);
    out_body.* = .{};
    const out_body_slot = try adapter.pushOutgoingBody(out_body);
    try testing.expect(out_body_slot >= 1);

    const in_body = try adapter.allocator.create(IncomingBody);
    in_body.* = .{};
    const in_body_slot = try adapter.pushIncomingBody(in_body);
    try testing.expect(in_body_slot >= 1);

    const ft = try adapter.allocator.create(FutureTrailers);
    ft.* = .{};
    const ft_slot = try adapter.pushFutureTrailers(ft);
    try testing.expect(ft_slot >= 1);

    // For each of the 8 tables listed in #562, `decodeResourceWire(0)`
    // returns host slot `0`, and `lookup*(0)` must return null so the
    // host doesn't silently target the first real allocation.
    const wire_zero_slot = executor.decodeResourceWire(0);
    try testing.expectEqual(@as(u32, 0), wire_zero_slot);
    try testing.expect(!adapter.http_fields_table.contains(wire_zero_slot));
    try testing.expect(!adapter.http_outgoing_requests.contains(wire_zero_slot));
    try testing.expect(!adapter.http_incoming_requests.contains(wire_zero_slot));
    try testing.expect(!adapter.http_outgoing_responses.contains(wire_zero_slot));
    try testing.expect(!adapter.http_incoming_responses.contains(wire_zero_slot));
    try testing.expect(!adapter.http_outgoing_bodies.contains(wire_zero_slot));
    try testing.expect(!adapter.http_incoming_bodies.contains(wire_zero_slot));
    // `lookupFutureTrailers` doesn't exist as a helper (`http_future_trailers`
    // is accessed inline via `items[handle]`), but the table itself must
    // still reserve slot 0:
    try testing.expect(!adapter.http_future_trailers.contains(0));
}

test "http (#562): slot-reuse stays within the 1-based range after a drop" {
    const testing = std.testing;

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    // Three pushes land at slots 1, 2, 3 (slot 0 reserved).
    const o1 = try adapter.allocator.create(OutgoingResponse);
    o1.* = .{ .status = 200, .headers_handle = 0 };
    const s1 = try adapter.pushOutgoingResponse(o1);
    const o2 = try adapter.allocator.create(OutgoingResponse);
    o2.* = .{ .status = 200, .headers_handle = 0 };
    const s2 = try adapter.pushOutgoingResponse(o2);
    const o3 = try adapter.allocator.create(OutgoingResponse);
    o3.* = .{ .status = 200, .headers_handle = 0 };
    const s3 = try adapter.pushOutgoingResponse(o3);
    try testing.expectEqual(@as(u32, 1), s1);
    try testing.expectEqual(@as(u32, 2), s2);
    try testing.expectEqual(@as(u32, 3), s3);

    // Free slot 2; disabled builds preserve the numeric handle while enabled
    // builds reuse the same slot with a larger encoded generation.
    adapter.allocator.destroy(o2);
    _ = adapter.http_outgoing_responses.withdraw(s2);

    const o4 = try adapter.allocator.create(OutgoingResponse);
    o4.* = .{ .status = 201, .headers_handle = 0 };
    const s4 = try adapter.pushOutgoingResponse(o4);
    if (build_options.lib_wasi_threads) {
        try testing.expectEqual(@as(u32, 2), stable_resource.handleIndex(s4));
        try testing.expect(
            stable_resource.handleGeneration(s4) >
                stable_resource.handleGeneration(s2),
        );
    } else {
        try testing.expectEqual(@as(u32, 2), s4);
    }
    try testing.expect(!adapter.http_outgoing_responses.contains(0));
}

// ───────────────────────────────────────────────────────────────────
// wasi:http@0.3.0 http-service end-to-end (#570) unit tests
// ───────────────────────────────────────────────────────────────────

test "wasi:http@0.3 (#570): createIncomingRequestP3FromHttpBytes parses GET line + headers + empty body" {
    // Synthetic HTTP/1.1 request → `HttpRequestP3` round-trip. Mirrors
    // the wasi-testsuite `http-service` driver path: an accepted TCP
    // socket's bytes get parsed into a P3 request resource without
    // needing the dispatcher to actually invoke a guest export.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    const request_bytes =
        "GET /hello?x=1 HTTP/1.1\r\n" ++
        "Host: example.com\r\n" ++
        "User-Agent: wamr-test\r\n" ++
        "Content-Length: 0\r\n" ++
        "\r\n";
    const req_handle = try adapter.createIncomingRequestP3FromHttpBytes(&ci, request_bytes);
    try testing.expect(req_handle > 0); // slot 0 is reserved (#562)

    const r = adapter.http_requests_p3.unsafeGetPtrForTest(req_handle).?.*;
    // GET → method discriminant 0.
    try testing.expectEqual(@as(u32, 0), r.method_disc);
    try testing.expectEqualStrings("/hello?x=1", r.path_with_query.?);
    try testing.expectEqualStrings("example.com", r.authority.?);
    // Default scheme is http (#570 — `splitHttpTarget` returns 0
    // when no `http(s)://` prefix is present in the origin-form target).
    try testing.expectEqual(@as(?u32, 0), r.scheme_disc);

    // Headers are interned as an immutable HttpFields. The two
    // user-supplied headers + the `host` echo land here.
    const fields = adapter.http_fields_table.unsafeGetPtrForTest(r.headers_handle).?.*;
    try testing.expect(fields.immutable);
    try testing.expect(fields.entries.items.len >= 3);

    // Body stream<u8> is pre-EOF for a zero-length request — the guest
    // can read once and immediately observe write-closed semantics.
    const body_handle = r.body_stream_handle orelse return error.TestFailed;
    const body_stream = ci.streams.getPtr(body_handle) orelse return error.TestFailed;
    try testing.expectEqual(@as(usize, 0), body_stream.buffer.items.len);
    try testing.expect(body_stream.write_closed);

    // Trailers + transmission futures must be ready-settled so the
    // guest's `.await` resolves synchronously on the first poll.
    const trailers_fut = ci.futures.getPtr(r.trailers_future_handle) orelse return error.TestFailed;
    try testing.expectEqual(async_mod.Future.State.ready, trailers_fut.state);
    const tx_fut = ci.futures.getPtr(r.transmission_future_handle) orelse return error.TestFailed;
    try testing.expectEqual(async_mod.Future.State.ready, tx_fut.state);
}

test "wasi:http@0.3 (#570): createIncomingRequestP3FromHttpBytes preserves POST body in stream" {
    // POST with `Content-Length: <n>` and an `<n>`-byte body. The body
    // bytes must land in the per-instance `stream<u8>` so the guest's
    // `request.consume-body` rendezvous can hand them back unmodified.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    const body_payload = "hello body";
    const request_bytes =
        "POST /submit HTTP/1.1\r\n" ++
        "Host: api.example\r\n" ++
        "Content-Length: 10\r\n" ++
        "\r\n" ++
        body_payload;
    const req_handle = try adapter.createIncomingRequestP3FromHttpBytes(&ci, request_bytes);

    const r = adapter.http_requests_p3.unsafeGetPtrForTest(req_handle).?.*;
    // POST → method discriminant 2 (per `httpMethodDiscriminant`).
    try testing.expectEqual(@as(u32, 2), r.method_disc);
    try testing.expectEqualStrings("/submit", r.path_with_query.?);
    const body_stream = ci.streams.getPtr(r.body_stream_handle.?) orelse return error.TestFailed;
    try testing.expectEqualStrings(body_payload, body_stream.buffer.items);
    try testing.expect(body_stream.write_closed);
}

test "wasi:http@0.3 (#570): writeHttpResponseP3FromHandle emits status line + headers + body" {
    // Synthetic `HttpResponseP3` lifted via the same constructor the
    // dispatch path uses. The streaming writer renders it as
    // HTTP/1.1 over a backing in-memory sink so the wasi-testsuite
    // `requests.request(...)` driver receives the expected status +
    // body. Matches the JSON expectations of `http-service.json`:
    // `200 + content-type: text/plain + "hey\n"`.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    // Set up a response with `content-type: text/plain` header and a
    // pre-filled body stream containing "hey\n".
    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const name = try testing.allocator.dupe(u8, "content-type");
    const value = try testing.allocator.dupe(u8, "text/plain");
    try fields.entries.append(testing.allocator, .{ .name = name, .value = value });
    const fields_handle = try adapter.pushHttpFields(fields);

    const body_handle = ci.allocAsyncHandle();
    var body: async_mod.AsyncStream = .{ .elem_type_idx = 0 };
    try body.buffer.appendSlice(testing.allocator, "hey\n");
    body.write_closed = true;
    try ci.streams.put(testing.allocator, body_handle, body);

    // Allocate ready-settled trailers + transmission futures so the
    // writer can reason about their state without driving any
    // additional canon ops.
    const trailers_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, trailers_h, .{
        .elem_type_idx = 0,
        .state = .ready,
        .write_closed = true,
    });
    const tx_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, tx_h, .{
        .elem_type_idx = 0,
        .state = .ready,
        .write_closed = true,
    });

    const resp = try testing.allocator.create(HttpResponseP3);
    resp.* = .{
        .status = 200,
        .headers_handle = fields_handle,
        .body_stream_handle = body_handle,
        .trailers_future_handle = trailers_h,
        .transmission_future_handle = tx_h,
    };
    const resp_handle = try adapter.pushHttpResponseP3(resp);

    // Drive `writeHttpResponseP3FromHandle` into a buffer-backed sink
    // so the test can assert the exact wire format.
    var out = streams.OutputStream.toBuffer();
    defer out.deinit(testing.allocator);

    try adapter.writeHttpResponseP3FromHandle(&out, &ci, resp_handle, false);

    const written = out.getBufferContents();
    // Status-line + standard headers + chunked-framed body. The
    // guest did not set Content-Length, so the writer falls back
    // to Transfer-Encoding: chunked (#583 A5).
    try testing.expect(std.mem.startsWith(u8, written, "HTTP/1.1 200 OK\r\n"));
    try testing.expect(std.mem.indexOf(u8, written, "content-type: text/plain\r\n") != null);
    try testing.expect(std.mem.indexOf(u8, written, "Transfer-Encoding: chunked\r\n") != null);
    try testing.expect(std.mem.indexOf(u8, written, "Connection: close\r\n") != null);
    // One non-zero chunk + the terminating 0-chunk with no trailers.
    try testing.expect(std.mem.indexOf(u8, written, "\r\n4\r\nhey\n\r\n") != null);
    try testing.expect(std.mem.endsWith(u8, written, "0\r\n\r\n"));
}

const LiveHttpTestSink = struct {
    const Failure = enum { none, closed, io_error };

    mutex: platform.Mutex = .init,
    bytes: [128 * 1024]u8 = undefined,
    len: usize = 0,
    discard: bool = false,
    block_body: bool = false,
    failure: Failure = .none,
    head_seen: std.atomic.Value(bool) = .init(false),
    blocked: std.atomic.Value(bool) = .init(false),
    release: std.atomic.Value(bool) = .init(false),
    first_seen: std.atomic.Value(bool) = .init(false),
    first_before_handler_return: std.atomic.Value(bool) = .init(false),
    handler_returned: ?*std.atomic.Value(bool) = null,

    fn write(ctx_opaque: ?*anyopaque, data: []const u8) streams.StreamResult {
        const self: *LiveHttpTestSink = @ptrCast(@alignCast(ctx_opaque.?));
        const is_head = std.mem.startsWith(u8, data, "HTTP/1.1 ");
        if (is_head) self.head_seen.store(true, .release);
        const is_body = self.head_seen.load(.acquire) and !is_head;

        if (is_body) {
            switch (self.failure) {
                .none => {},
                .closed => return .{ .closed = {} },
                .io_error => return .{ .err = .io_error },
            }
            if (self.block_body) {
                self.blocked.store(true, .release);
                while (!self.release.load(.acquire)) platform.usleep(100);
            }
            if (std.mem.indexOf(u8, data, "first") != null) {
                self.first_seen.store(true, .release);
                const returned = if (self.handler_returned) |flag|
                    flag.load(.acquire)
                else
                    false;
                if (!returned) {
                    self.first_before_handler_return.store(true, .release);
                }
            }
        }

        if (!self.discard) {
            self.mutex.lock();
            defer self.mutex.unlock();
            if (data.len > self.bytes.len - self.len) {
                return .{ .err = .io_error };
            }
            @memcpy(self.bytes[self.len .. self.len + data.len], data);
            self.len += data.len;
        }
        return .{ .ok = data.len };
    }

    fn interrupt(ctx_opaque: ?*anyopaque) void {
        const self: *LiveHttpTestSink = @ptrCast(@alignCast(ctx_opaque.?));
        self.release.store(true, .release);
    }

    fn contents(self: *LiveHttpTestSink) []const u8 {
        return self.bytes[0..self.len];
    }
};

const LiveHttpProducer = struct {
    session: *InboundHttpResponseSession,
    chunks: []const []const u8,
    pause_after_first: ?*std.atomic.Value(bool) = null,
    accepted: std.atomic.Value(bool) = .init(true),
    done: std.atomic.Value(bool) = .init(false),

    fn run(self: *LiveHttpProducer) void {
        for (self.chunks, 0..) |chunk, i| {
            if (!InboundHttpResponseSession.onBodyWrite(self.session, chunk)) {
                self.accepted.store(false, .release);
                self.done.store(true, .release);
                return;
            }
            if (i == 0) {
                if (self.pause_after_first) |release| {
                    while (!release.load(.acquire)) platform.usleep(100);
                }
            }
        }
        InboundHttpResponseSession.onBodyClosed(self.session);
        self.done.store(true, .release);
    }
};

const LiveHttpResponseFixture = struct {
    response_handle: u32,
    body_handle: ?u32,
    trailers_handle: u32,
    transmission_handle: u32,
};

fn makeLiveHttpResponseFixture(
    adapter: *WasiCliAdapter,
    ci: *ComponentInstance,
    content_length: ?usize,
    with_body: bool,
    trailer: ?struct { name: []const u8, value: []const u8 },
) !LiveHttpResponseFixture {
    const fields = try adapter.allocator.create(HttpFields);
    fields.* = .{};
    const fields_handle = try adapter.pushHttpFields(fields);
    if (content_length) |length| {
        const name = try adapter.allocator.dupe(u8, "content-length");
        errdefer adapter.allocator.free(name);
        const value = try std.fmt.allocPrint(adapter.allocator, "{d}", .{length});
        errdefer adapter.allocator.free(value);
        try fields.entries.append(adapter.allocator, .{
            .name = name,
            .value = value,
        });
    }

    const body_handle: ?u32 = if (with_body) blk: {
        const handle = ci.allocAsyncHandle();
        try ci.streams.put(ci.allocator, handle, .{ .elem_type_idx = 0 });
        break :blk handle;
    } else null;

    var trailers_payload: ?[]u8 = null;
    if (trailer) |entry| {
        const trailer_fields = try adapter.allocator.create(HttpFields);
        trailer_fields.* = .{};
        const name = try adapter.allocator.dupe(u8, entry.name);
        errdefer adapter.allocator.free(name);
        const value = try adapter.allocator.dupe(u8, entry.value);
        errdefer adapter.allocator.free(value);
        try trailer_fields.entries.append(adapter.allocator, .{
            .name = name,
            .value = value,
        });
        const trailer_fields_handle = try adapter.pushHttpFields(trailer_fields);
        const payload = try ci.allocator.alloc(u8, 8);
        @memset(payload, 0);
        payload[0] = 1;
        std.mem.writeInt(
            u32,
            payload[4..8],
            trailer_fields_handle,
            .little,
        );
        trailers_payload = payload;
    }

    const trailers_handle = ci.allocAsyncHandle();
    try ci.futures.put(ci.allocator, trailers_handle, .{
        .elem_type_idx = 0,
        .state = .ready,
        .write_closed = true,
        .payload = trailers_payload,
    });
    const transmission_handle = ci.allocAsyncHandle();
    try ci.futures.put(ci.allocator, transmission_handle, .{
        .elem_type_idx = 0,
        .state = .pending,
    });

    const response = try adapter.allocator.create(HttpResponseP3);
    response.* = .{
        .headers_handle = fields_handle,
        .body_stream_handle = body_handle,
        .trailers_future_handle = trailers_handle,
        .transmission_future_handle = transmission_handle,
    };
    const response_handle = try adapter.pushHttpResponseP3(response);
    return .{
        .response_handle = response_handle,
        .body_handle = body_handle,
        .trailers_handle = trailers_handle,
        .transmission_handle = transmission_handle,
    };
}

fn startLiveHttpTestSession(
    adapter: *WasiCliAdapter,
    ci: *ComponentInstance,
    output: *streams.OutputStream,
    sink: *LiveHttpTestSink,
    fixture: LiveHttpResponseFixture,
) !*InboundHttpResponseSession {
    const session = try InboundHttpResponseSession.create(
        adapter.allocator,
        adapter,
        ci,
        output,
        false,
        .{
            .context = sink,
            .callback = &LiveHttpTestSink.interrupt,
        },
        .{
            .context = sink,
            .write = &LiveHttpTestSink.write,
        },
    );
    errdefer session.destroy();
    try session.start();
    try std.testing.expect(session.attachP3Response(
        fixture.response_handle,
        fixture.body_handle,
        fixture.trailers_handle,
        fixture.transmission_handle,
    ));
    return session;
}

fn waitForLiveHttpFlag(flag: *const std.atomic.Value(bool)) !void {
    var attempts: usize = 0;
    while (!flag.load(.acquire) and attempts < 50_000) : (attempts += 1) {
        platform.usleep(100);
    }
    try std.testing.expect(flag.load(.acquire));
}

fn waitForLiveHttpTerminal(
    session: *InboundHttpResponseSession,
    terminal: HttpLiveTerminal,
) !void {
    var attempts: usize = 0;
    while (session.currentTerminal() != terminal and
        attempts < 50_000) : (attempts += 1)
    {
        platform.usleep(100);
    }
    try std.testing.expectEqual(terminal, session.currentTerminal());
}

test "wasi:http #616 A8 live: first body chunk reaches the client before handler return" {
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);
    var output: streams.OutputStream = .{ .sink = .closed };

    const fixture = try makeLiveHttpResponseFixture(
        &adapter,
        &ci,
        11,
        true,
        null,
    );
    var handler_returned = std.atomic.Value(bool).init(false);
    var sink = LiveHttpTestSink{ .handler_returned = &handler_returned };
    const session = try startLiveHttpTestSession(
        &adapter,
        &ci,
        &output,
        &sink,
        fixture,
    );
    defer session.destroy();

    var release = std.atomic.Value(bool).init(false);
    const chunks = [_][]const u8{ "first", "second" };
    var producer = LiveHttpProducer{
        .session = session,
        .chunks = &chunks,
        .pause_after_first = &release,
    };
    const thread = try std.Thread.spawn(.{}, LiveHttpProducer.run, .{&producer});
    var joined = false;
    defer {
        release.store(true, .release);
        if (!joined) thread.join();
    }

    try waitForLiveHttpFlag(&sink.first_seen);
    try testing.expect(sink.first_before_handler_return.load(.acquire));
    try testing.expect(!handler_returned.load(.acquire));

    release.store(true, .release);
    thread.join();
    joined = true;
    try waitForLiveHttpTerminal(session, .succeeded);
    try testing.expect(session.driveGuestEvents());
    const transmission = ci.futures.getPtr(fixture.transmission_handle).?;
    try testing.expectEqual(async_mod.Future.State.ready, transmission.state);
    try testing.expect(!handler_returned.load(.acquire));
    handler_returned.store(true, .release);
    session.handlerReturned(fixture.response_handle);
    session.waitAndJoin();
    session.propagateTerminalToGuest();

    try testing.expectEqual(HttpLiveTerminal.succeeded, session.currentTerminal());
    try testing.expect(std.mem.endsWith(u8, sink.contents(), "firstsecond"));
}

test "wasi:http #616 A8 live: response streams are bounded before response.new associates them" {
    const testing = std.testing;
    const core_types_mod = @import("../runtime/common/types.zig");
    const inst_mod_core = @import("../runtime/interpreter/instance.zig");
    const ExecEnv = @import("../runtime/common/exec_env.zig").ExecEnv;

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);
    var output: streams.OutputStream = .{ .sink = .closed };
    var sink = LiveHttpTestSink{};
    const session = try InboundHttpResponseSession.create(
        testing.allocator,
        &adapter,
        &ci,
        &output,
        false,
        .{
            .context = &sink,
            .callback = &LiveHttpTestSink.interrupt,
        },
        .{
            .context = &sink,
            .write = &LiveHttpTestSink.write,
        },
