    defer adapter.deinit();
    try testing.expect(!adapter.trace_calls);
    adapter.setTraceCalls(true);
    try testing.expect(adapter.trace_calls);
    adapter.setTraceCalls(false);
    try testing.expect(!adapter.trace_calls);
}

